local run = function(func, timeout)
	local started = tick()
	local lastError
	repeat
		local success, result = xpcall(func, debug and debug.traceback or tostring)
		if success then
			return result
		end

		lastError = result
		if not timeout or timeout <= 0 then
			break
		end
		task.wait(0.2)
	until tick() - started >= timeout

	warn('[ElevateV4] Skipped a BedWars module during startup: '..tostring(lastError))
end
