local function getSword()
	local bestSword, bestSwordSlot, bestSwordDamage = nil, nil, 0
	local inventory = store.inventory and store.inventory.inventory
	for slot, item in pairs(inventory and inventory.items or {}) do
		local itemMeta = item and bedwars.ItemMeta[item.itemType]
		local swordMeta = itemMeta and itemMeta.sword
		if swordMeta then
			local swordDamage = swordMeta.damage or 0
			if swordDamage > bestSwordDamage then
				bestSword, bestSwordSlot, bestSwordDamage = item, slot, swordDamage
			end
		end
	end
	return bestSword, bestSwordSlot
end

local function getTool(breakType)
	local bestTool, bestToolSlot, bestToolDamage = nil, nil, 0
	local inventory = store.inventory and store.inventory.inventory
	for slot, item in pairs(inventory and inventory.items or {}) do
		local itemMeta = item and bedwars.ItemMeta[item.itemType]
		local toolMeta = itemMeta and itemMeta.breakBlock
		if toolMeta then
			local toolDamage = toolMeta[breakType] or 0
			if toolDamage > bestToolDamage then
				bestTool, bestToolSlot, bestToolDamage = item, slot, toolDamage
			end
		end
	end
	return bestTool, bestToolSlot
end

local function getBreakTool(breakType)
	if not breakType then return end
	local cached = store.tools[breakType]
	if cached ~= nil then
		return cached or nil
	end
	local tool = getTool(breakType)
	store.tools[breakType] = tool or false
	return tool
end

local function getWool()
	local inventory = store.inventory and store.inventory.inventory
	for _, wool in pairs(inventory and inventory.items or {}) do
		if wool.itemType and wool.itemType:find('wool', 1, true) then
			return wool and wool.itemType, wool and wool.amount
		end
	end
end

local function getStrength(plr)
	if not plr.Player then
		return 0
	end

	local strength = 0
	for _, v in (store.inventories[plr.Player] or {items = {}}).items do
		local itemmeta = bedwars.ItemMeta[v.itemType]
		if itemmeta and itemmeta.sword and itemmeta.sword.damage > strength then
			strength = itemmeta.sword.damage
		end
	end

	return strength
end

local function getPlacedBlock(pos)
	if not pos then
		return
	end
	local roundedPosition = bedwars.BlockController:getBlockPosition(pos)
	return bedwars.BlockController:getStore():getBlockAt(roundedPosition), roundedPosition
end
getgenv().getPlacedBlock = getPlacedBlock
local function installWindStackHook()
	local controller = bedwars.WindWalkerController
	if not controller or type(controller.updateJump) ~= 'function' then return end
	if getgenv().__AetherWindHookedV2 == controller then return end
	local original = controller.updateJump
	controller.updateJump = function(self, count, ...)
		getgenv().__AetherWindStacks = tonumber(count) or 0
		return original(self, count, ...)
	end
	getgenv().__AetherWindHookedV2 = controller
end
installWindStackHook()
local function getWindStacks()
	installWindStackHook()
	return tonumber(getgenv().__AetherWindStacks) or 0
end
getgenv().getWindStacks = getWindStacks
getgenv().WIND_WALKER_MAX_STACKS = 5

local function getBlocksInPoints(s, e)
	local blocks, list = bedwars.BlockController:getStore(), {}
	for x = s.X, e.X do
		for y = s.Y, e.Y do
			for z = s.Z, e.Z do
				local vec = Vector3.new(x, y, z)
				if blocks:getBlockAt(vec) then
					table.insert(list, vec * 3)
				end
			end
		end
	end
	return list
end

local function getNearGround(range)
	range = Vector3.new(3, 3, 3) * (range or 10)
	local localPosition, mag, closest = entitylib.character.RootPart.Position, 60
	local blocks = getBlocksInPoints(bedwars.BlockController:getBlockPosition(localPosition - range), bedwars.BlockController:getBlockPosition(localPosition + range))

	for _, v in blocks do
		if not getPlacedBlock(v + Vector3.new(0, 3, 0)) then
			local newmag = (localPosition - v).Magnitude
			if newmag < mag then
				mag, closest = newmag, v + Vector3.new(0, 3, 0)
			end
		end
	end

	table.clear(blocks)
	return closest
end

local function getShieldAttribute(char)
	local returned = 0
	for name, val in char:GetAttributes() do
		if name:find('Shield') and type(val) == 'number' and val > 0 then
			returned += val
		end
	end
	return returned
end

local knockbackSpeed, knockbackBoost = 0, tick()
local function getSpeed()
	local multi, increase, modifiers = 0, true, bedwars.SprintController:getMovementStatusModifier():getModifiers()

	for v in modifiers do
		local val = v.constantSpeedMultiplier and v.constantSpeedMultiplier or 0
		if val and val > math.max(multi, 1) then
			increase = false
			multi = val - (0.06 * math.round(val))
		end
	end

	for v in modifiers do
		multi += math.max((v.moveSpeedMultiplier or 0) - 1, 0)
	end

	if multi > 0 and increase then
		multi += 0.16 + (0.02 * math.round(multi))
	end

	return (20 + (knockbackBoost > tick() and knockbackSpeed or 0)) * (multi + 1)
end
getgenv().getSpeed = getSpeed

store.engineSpeed = function(module)
	local speed = 0
	module:Clean(runService.PostSimulation:Connect(function()
		if not entitylib.isAlive then
			speed = 0
			return
		end
		local velocity = entitylib.character.RootPart.AssemblyLinearVelocity
		local sample = Vector3.new(velocity.X, 0, velocity.Z).Magnitude
		speed = sample >= speed and sample or speed + (sample - speed) * 0.25
	end))
	return function()
		return math.max(speed, getSpeed())
	end
end

