local function isFrozen(char, threshold)
	local character = char or (entitylib.character and entitylib.character.Character)
	if not character or not bedwars.StatusEffectUtil then return false end
	local ok, active = pcall(function()
		return bedwars.StatusEffectUtil:isActive(character, 'frozen')
	end)
	if not ok or not active then return false end
	if not threshold then return true end
	local stacks
	for name, value in character:GetAttributes() do
		if name:find('frozen', 1, true) and name:find('stack', 1, true) and type(value) == 'number' then
			stacks = value
			break
		end
	end
	if type(stacks) == 'number' then return stacks >= threshold end
	return true
end

local function resolveAnimation(names)
	local types = bedwars.AnimationType
	if type(types) ~= 'table' then return nil end
	for _, name in names do
		if types[name] ~= nil then
			return types[name]
		end
	end
	return nil
end

local animationMatches = {}
local function matchAnimation(key, groups, reject)
	local cached = animationMatches[key]
	if cached ~= nil then
		return cached or nil
	end
	local types = bedwars.AnimationType
	if type(types) ~= 'table' then return nil end

	local found
	for _, words in groups do
		for name, value in types do
			
			if type(name) ~= 'string' then continue end
			local lowered = name:lower()
			local hit = true
			for _, word in words do
				if not lowered:find(word, 1, true) then
					hit = false
					break
				end
			end
			if hit and reject then
				for _, word in reject do
					if lowered:find(word, 1, true) then
						hit = false
						break
					end
				end
			end
			if hit then
				found = value
				break
			end
		end
		if found ~= nil then break end
	end

	if found == nil then
		animationMatches[key] = false
	else
		animationMatches[key] = found
	end
	return found
end

local function removeTags(str)
	str = str:gsub('<br%s*/>', '\n')
	return (str:gsub('<[^<>]->', ''))
end

local function formatNumber(value)
	local text = tostring(math.floor(tonumber(value) or 0))
	local sign = ''
	if text:sub(1, 1) == '-' then
		sign, text = '-', text:sub(2)
	end
	local out = text:reverse():gsub('(%d%d%d)', '%1,'):reverse()
	return sign..(out:gsub('^,', ''))
end

