local frictionTable, oldfrict = {}, {}
local frictionConnection
local frictionState

local function modifyVelocity(v)
	if v:IsA('BasePart') and v.Name ~= 'HumanoidRootPart' and not oldfrict[v] then
		oldfrict[v] = v.CustomPhysicalProperties or 'none'
		v.CustomPhysicalProperties = PhysicalProperties.new(0.0001, 0.2, 0.5, 1, 1)
	end
end

local function updateVelocity(force)
	local newState = getTableSize(frictionTable) > 0
	if frictionState ~= newState or force then
		if frictionConnection then
			frictionConnection:Disconnect()
		end
		if newState then
			if entitylib.isAlive then
				for _, v in entitylib.character.Character:GetDescendants() do
					modifyVelocity(v)
				end
				frictionConnection = entitylib.character.Character.DescendantAdded:Connect(modifyVelocity)
			end
		else
			for i, v in oldfrict do
				i.CustomPhysicalProperties = v ~= 'none' and v or nil
			end
			table.clear(oldfrict)
		end
	end
	frictionState = newState
end

local kitorder = {
	hannah = 5,
	spirit_assassin = 4,
	dasher = 3,
	jade = 2,
	regent = 1
}

local getBlockHits
local sortmethods, breakmethods = {
	Damage = function(a, b)
		return a.Entity.Character:GetAttribute('LastDamageTakenTime') < b.Entity.Character:GetAttribute('LastDamageTakenTime')
	end,
	Threat = function(a, b)
		return getStrength(a.Entity) > getStrength(b.Entity)
	end,
	Kit = function(a, b)
		return (a.Entity.Player and kitorder[a.Entity.Player:GetAttribute('PlayingAsKit')] or 0) > (b.Entity.Player and kitorder[b.Entity.Player:GetAttribute('PlayingAsKit')] or 0)
	end,
	Health = function(a, b)
		return a.Entity.Health < b.Entity.Health
	end,
	Angle = function(a, b)
		local selfrootpos = entitylib.character.RootPart.Position
		local localfacing = entitylib.character.RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)
		local angle = math.acos(localfacing:Dot(((a.Entity.RootPart.Position - selfrootpos) * Vector3.new(1, 0, 1)).Unit))
		local angle2 = math.acos(localfacing:Dot(((b.Entity.RootPart.Position - selfrootpos) * Vector3.new(1, 0, 1)).Unit))
		return angle < angle2
	end,
	Mouse = function(a, b)
		local mouse = lplr:GetMouse()
		local origin = Vector2.new(mouse.X, mouse.Y)

		local posa, visa = gameCamera:WorldToScreenPoint(a.Entity.RootPart.Position)
		local posb, visb = gameCamera:WorldToScreenPoint(b.Entity.RootPart.Position)
		local dista = visa and (Vector2.new(posa.X, posa.Y) - origin).Magnitude or math.huge
        local distb = visb and (Vector2.new(posb.X, posb.Y) - origin).Magnitude or math.huge
        return (dista == dista and dista or math.huge) < (distb == distb and distb or math.huge)
	end
}, {
	Health = function(...)
		return getBlockHits(...)
	end,
	Distance = function(a)
		local pos = (entitylib.isAlive and (entitylib.character.RootPart.Position - Vector3.new(0, 1, 0)) or Vector3.zero)
		return (pos - Vector3.new(a.Position.X, pos.Y, a.Position.Z)).Magnitude
	end
}

local function screenPriorityDistance(entry, origin)
	local ent = entry and entry.Entity
	local root = ent and ent.RootPart
	if not root then return math.huge end
	local point, visible = gameCamera:WorldToViewportPoint(root.Position)
	if not visible then return math.huge end
	return (Vector2.new(point.X, point.Y) - origin).Magnitude
end
sortmethods.None = function() return false end
sortmethods.Closest = function(a, b) return (a.Magnitude or math.huge) < (b.Magnitude or math.huge) end
sortmethods.Farthest = function(a, b) return (a.Magnitude or 0) > (b.Magnitude or 0) end
sortmethods['Lowest health'] = function(a, b) return (a.Entity.Health or math.huge) < (b.Entity.Health or math.huge) end
sortmethods['Highest health'] = function(a, b) return (a.Entity.Health or 0) > (b.Entity.Health or 0) end
sortmethods.Mouse = function(a, b)
	local origin = inputService:GetMouseLocation()
	return screenPriorityDistance(a, origin) < screenPriorityDistance(b, origin)
end
sortmethods.Crosshair = function(a, b)
	local origin = gameCamera.ViewportSize / 2
	return screenPriorityDistance(a, origin) < screenPriorityDistance(b, origin)
end
sortmethods.Distance = function(a, b)
	local selfpos = entitylib.isAlive and entitylib.character.RootPart.Position
	if not selfpos then return false end
	return (selfpos - a.Entity.RootPart.Position).Magnitude < (selfpos - b.Entity.RootPart.Position).Magnitude
end
sortmethods.Health = function(a, b)
	return (a.Entity.Health or math.huge) < (b.Entity.Health or math.huge)
end
sortmethods.Damage = function(a, b)
	local held = store.hand and store.hand.tool
	local meta = held and bedwars.ItemMeta and bedwars.ItemMeta[held.Name]
	local damage = (meta and meta.sword and tonumber(meta.sword.damage)) or 20
	if damage <= 0 then damage = 20 end
	return ((a.Entity.Health or math.huge) / damage) < ((b.Entity.Health or math.huge) / damage)
end
sortmethods.Angle = function(a, b)
	if not entitylib.isAlive or not entitylib.character or not entitylib.character.RootPart then return false end
	local look = gameCamera.CFrame.LookVector
	local selfpos = entitylib.character.RootPart.Position
	local function facing(entity)
		local root = entity.Entity.RootPart
		if not root then return -2 end
		local delta = root.Position - selfpos
		if delta.Magnitude <= 0.01 then return 1 end
		return look:Dot(delta.Unit)
	end
	return facing(a) > facing(b)
end
local threatCache, threatAt = {}, 0
local function threatScore(plr)
	if not plr then return -1 end
	local analyser = getgenv().EntityAnalyser
	if not analyser or analyser.Enabled ~= true then return -1 end
	local now = tick()
	if now - threatAt > 0.5 then
		threatAt = now
		table.clear(threatCache)
	end
	local cached = threatCache[plr]
	if cached then return cached end
	local ok, analysis = pcall(analyser.Analyse, analyser, plr)
	local score = ok and analysis and tonumber(analysis.OverallSkill)
	if not score then score = -1 end
	threatCache[plr] = score
	return score
end
sortmethods.Threat = function(a, b)
	return threatScore(a.Entity.Player) > threatScore(b.Entity.Player)
end
local TARGET_MODE_TOOLTIP = 'Who to prefer when several targets are in range\nCursor - nearest your cursor\nDistance - closest to you\nDamage - fewest hits to kill\nAngle - smallest turn to face\nLowest Health / Highest Health\nThreat - rated best by EntityAnalyser\nHit chance - easiest to hit'

shared.AetherScreenSorts = {[sortmethods.Mouse] = 'Mouse', [sortmethods.Crosshair] = 'Crosshair'}
sortmethods.Cursor = sortmethods.Mouse
sortmethods['Lowest Health'] = sortmethods['Lowest health']
sortmethods['Highest Health'] = sortmethods['Highest health']
do
	local flat = Vector3.new(1, 0, 1)
	local function missBudget(entry)
		local ent = entry and entry.Entity
		local root = ent and ent.RootPart
		if not root then return math.huge end
		local origin = entitylib.isAlive and entitylib.character.RootPart.Position or root.Position
		local flight = (root.Position - origin).Magnitude / 120
		local velocity = root.AssemblyLinearVelocity
		local budget = (velocity * flat).Magnitude * flight * 0.28 + flight * 4
		if ent.Humanoid and ent.Humanoid.FloorMaterial == Enum.Material.Air then
			budget += math.abs(velocity.Y) * flight * 0.12 + 2
		end
		return budget
	end
	sortmethods['Hit chance'] = function(a, b)
		return missBudget(a) < missBudget(b)
	end
end
local TARGET_MODES = {'Cursor', 'Distance', 'Damage', 'Angle', 'Lowest Health', 'Highest Health', 'Threat', 'Hit chance'}
local sortlist = {}
for _, name in ipairs(TARGET_MODES) do
	if sortmethods[name] then table.insert(sortlist, name) end
end
getgenv().sortlist = sortlist
local function getSortList()
	return table.clone(sortlist)
end

run(function()
	local oldstart = entitylib.start
	local function customEntity(ent)
		if ent:HasTag('inventory-entity') and not ent:HasTag('Monster') and not ent:HasTag('trainingRoomDummy') then
			return
		end

		entitylib.addEntity(ent, nil, ent:HasTag('Drone') and function(self)
			local droneplr = playersService:GetPlayerByUserId(self.Character:GetAttribute('PlayerUserId'))
			return not droneplr or lplr:GetAttribute('Team') ~= droneplr:GetAttribute('Team')
		end or function(self)
			return lplr:GetAttribute('Team') ~= self.Character:GetAttribute('Team')
		end)
	end

	entitylib.start = function()
		oldstart()
		if entitylib.Running then
			for _, ent in collectionService:GetTagged('entity') do
				customEntity(ent)
			end
			table.insert(entitylib.Connections, collectionService:GetInstanceAddedSignal('entity'):Connect(customEntity))
			table.insert(entitylib.Connections, collectionService:GetInstanceRemovedSignal('entity'):Connect(function(ent)
				entitylib.removeEntity(ent)
			end))
		end
	end

	entitylib.addPlayer = function(plr)
		if plr.Character then
			entitylib.refreshEntity(plr.Character, plr)
		end
		entitylib.PlayerConnections[plr] = {
			plr.CharacterAdded:Connect(function(char)
				entitylib.refreshEntity(char, plr)
			end),
			plr.CharacterRemoving:Connect(function(char)
				entitylib.removeEntity(char, plr == lplr)
			end),
			plr:GetAttributeChangedSignal('Team'):Connect(function()
				for _, v in entitylib.List do
					if v.Targetable ~= entitylib.targetCheck(v) then
						entitylib.refreshEntity(v.Character, v.Player)
					end
				end

				if plr == lplr then
					entitylib.start()
				else
					entitylib.refreshEntity(plr.Character, plr)
				end
			end)
		}
	end

	entitylib.addEntity = function(char, plr, teamfunc)
		if not char then return end
		entitylib.EntityThreads[char] = task.spawn(function()
			local hum, humrootpart, head
			if plr then
				hum = waitForChildOfType(char, 'Humanoid', 10)
				humrootpart = hum and waitForChildOfType(hum, 'RootPart', workspace.StreamingEnabled and 9e9 or 10, true)
				head = char:WaitForChild('Head', 10) or humrootpart
			else
				hum = {HipHeight = 0.5}
				humrootpart = waitForChildOfType(char, 'PrimaryPart', 10, true)
				head = humrootpart
			end
			local updateobjects = plr and plr ~= lplr and {
				char:WaitForChild('ArmorInvItem_0', 5),
				char:WaitForChild('ArmorInvItem_1', 5),
				char:WaitForChild('ArmorInvItem_2', 5),
				char:WaitForChild('HandInvItem', 5)
			} or {}

			if hum and humrootpart then
				local entity = {
					Connections = {},
					Character = char,
					Health = (char:GetAttribute('Health') or 100) + getShieldAttribute(char),
					Head = head,
					Humanoid = hum,
					HumanoidRootPart = humrootpart,
					HipHeight = hum.HipHeight + (humrootpart.Size.Y / 2) + (hum.RigType == Enum.HumanoidRigType.R6 and 2 or 0),
					Jumps = 0,
					JumpTick = tick(),
					Jumping = false,
					LandTick = tick(),
					MaxHealth = char:GetAttribute('MaxHealth') or 100,
					NPC = plr == nil,
					Player = plr,
					RootPart = humrootpart,
					TeamCheck = teamfunc
				}

				if plr == lplr then
					entity.AirTime = tick()
					entitylib.character = entity
					entitylib.isAlive = true
					entitylib.Events.LocalAdded:Fire(entity)
					table.insert(entitylib.Connections, char.AttributeChanged:Connect(function(attr)
						vapeEvents.AttributeChanged:Fire(attr)
					end))
				else
					entity.Targetable = entitylib.targetCheck(entity)
					if plr ~= nil then
						local function deviceAttributeChanged()
							entitylib.Events.EntityUpdated:Fire(entity)
						end
						table.insert(entity.Connections, plr:GetAttributeChangedSignal('UserInputType'):Connect(deviceAttributeChanged))
						table.insert(entity.Connections, char:GetAttributeChangedSignal('UserInputType'):Connect(deviceAttributeChanged))
					end
					if plr ~= nil then
						table.insert(entity.Connections, hum.AnimationPlayed:Connect(function(track)
							entitylib.Events.AnimationPlayed:Fire(plr, track)
						end))
					end

					for _, v in entitylib.getUpdateConnections(entity) do
						table.insert(entity.Connections, v:Connect(function()
							entity.Health = (char:GetAttribute('Health') or 100) + getShieldAttribute(char)
							entity.MaxHealth = char:GetAttribute('MaxHealth') or 100
							entitylib.Events.EntityUpdated:Fire(entity)
						end))
					end

					for _, v in updateobjects do
						table.insert(entity.Connections, v:GetPropertyChangedSignal('Value'):Connect(function()
							task.delay(0.1, function()
								if bedwars.getInventory then
									store.inventories[plr] = bedwars.getInventory(plr)
									entitylib.Events.EntityUpdated:Fire(entity)
								end
							end)
						end))
					end

					if plr then
						local anim = char:FindFirstChild('Animate')
						if anim then
							pcall(function()
								anim = anim.jump:FindFirstChildWhichIsA('Animation').AnimationId
								table.insert(entity.Connections, hum.Animator.AnimationPlayed:Connect(function(playedanim)
									if playedanim.Animation.AnimationId == anim then
										entity.JumpTick = tick()
										entity.Jumps += 1
										entity.LandTick = tick() + 1
										entity.Jumping = entity.Jumps > 1
									end
								end))
							end)
						end

						task.delay(0.1, function()
							if bedwars.getInventory and plr.Parent then
								store.inventories[plr] = bedwars.getInventory(plr)
								entitylib.Events.EntityUpdated:Fire(entity)
							end
						end)
					end
					table.insert(entitylib.List, entity)
					entitylib.Events.EntityAdded:Fire(entity)
				end

				table.insert(entity.Connections, char.ChildRemoved:Connect(function(part)
					if part == humrootpart or part == hum or part == head then
						if part == humrootpart and hum.RootPart then
							humrootpart = hum.RootPart
							entity.RootPart = hum.RootPart
							entity.HumanoidRootPart = hum.RootPart
							return
						end
						entitylib.removeEntity(char, plr == lplr)
					end
				end))
			end
			entitylib.EntityThreads[char] = nil
		end)
	end

	entitylib.getUpdateConnections = function(ent)
		local char = ent.Character
		local tab = {
			char:GetAttributeChangedSignal('Health'),
			char:GetAttributeChangedSignal('MaxHealth'),
			{
				Connect = function()
					ent.Friend = ent.Player and isFriend(ent.Player) or nil
					ent.Target = ent.Player and isTarget(ent.Player) or nil
					return {Disconnect = function() end}
				end
			}
		}

		if ent.Player then
			table.insert(tab, ent.Player:GetAttributeChangedSignal('PlayingAsKit'))
		end

		for name, val in char:GetAttributes() do
			if name:find('Shield') and type(val) == 'number' then
				table.insert(tab, char:GetAttributeChangedSignal(name))
			end
		end

		return tab
	end

	entitylib.targetCheck = function(ent)
		if ent.TeamCheck then
			return ent:TeamCheck()
		end
		if ent.NPC then return true end
		if isFriend(ent.Player) then return false end
		if not select(2, whitelist:get(ent.Player)) then return false end
		return lplr:GetAttribute('Team') ~= ent.Player:GetAttribute('Team')
	end
	vape:Clean(entitylib.Events.LocalAdded:Connect(updateVelocity))
end)
entitylib.start()

local require, debug = require, debug
local function upvalueAvailable(func, index)
	if type(func) ~= 'function' or type(debug) ~= 'table' or type(debug.getupvalue) ~= 'function' then
		return false
	end
	return pcall(debug.getupvalue, func, index)
end
local function safeUpvalue(func, index, key)
	if type(func) ~= 'function' or type(debug) ~= 'table' or type(debug.getupvalue) ~= 'function' then
		return nil
	end
	local function read(at)
		local res = table.pack(pcall(debug.getupvalue, func, at))
		if not res[1] then return nil end
		if res.n >= 3 then return res[3] end
		return res[2]
	end
	local value = read(index)
	if key == nil then return value end
	if type(value) == 'table' and rawget(value, key) ~= nil then return value end
	for at = 1, 24 do
		value = read(at)
		if type(value) == 'table' and rawget(value, key) ~= nil then return value end
	end
	return nil
end
