	canDebug = not table.find({'Solara', 'Xeno'}, (identifyexecutor and ({identifyexecutor()})[1]) or '') and true or false
	if not canDebug then
		local cheatenginelib = loadstring(downloadFile('ElevateV4/libraries/cheatenginelib.lua'), 'cheatenginelib')(vape, vapeEvents, entitylib)
		require = function(v)
			return cheatenginelib[({v:GetFullName():gsub(lplr.Name, 'PlayerTemplate')})[1]]:await()
		end
		debug = setmetatable({getproto = function() return function() end end}, {
			__index = function(self, index)
				self[index] = function() end
				return self[index]
			end
		})
	end
end)

local CheatersFlagged = {}
run(function()
	
	local KnitInit, Knit
	local knitDeadline = tick() + 45
	repeat
		KnitInit, Knit = pcall(function()
			return require(replicatedStorage.rbxts_include.node_modules["@easy-games"].knit.src).KnitClient
		end)
		if KnitInit and Knit then break end
		task.wait()
	until tick() > knitDeadline
	if not (KnitInit and Knit) then
		error('BedWars Knit never became available - the game has not finished loading')
	end

	if canDebug and not upvalueAvailable(Knit.Start, 1) then
		local upvalueDeadline = tick() + 15
		repeat task.wait() until upvalueAvailable(Knit.Start, 1) or tick() > upvalueDeadline
		if not upvalueAvailable(Knit.Start, 1) then
			
			warn('[ElevateV4] debug.getupvalue is unavailable here - modules that need it are disabled')
			canDebug = false
		end
	end

	local Flamework = require(replicatedStorage['rbxts_include']['node_modules']['@flamework'].core.out).Flamework
	local igniteDeadline = tick() + 45
	repeat
		local ok, ignited = pcall(debug.getupvalue, Flamework.ignite, 1)
		if not ok or type(ignited) ~= 'boolean' or ignited then break end
		task.wait(0.1)
	until tick() > igniteDeadline
	local controllers = {Built = {}, Ids = {
		'@easy-games/game-core:client/controllers/ability/ability-controller@AbilityController',
		'client/controllers/game/kill-feed/kill-feed-controller@KillFeedController',
		'@easy-games/game-core:client/controllers/notification-controller@NotificationController',
		'@easy-games/lobby:client/controllers/party-controller@PartyController'
	}}
	local function findController(id, again)
		if again or not controllers.Scanned then
			controllers.Scanned = true
			local delta = false
			if identifyexecutor then
				local named, executor = pcall(identifyexecutor)
				delta = named and tostring(executor):lower():find('delta', 1, true) ~= nil
			end
			local ok, core = pcall(function()
				return require(replicatedStorage['rbxts_include']['node_modules']['@flamework'].core.out)
			end)
			local known = ok and type(core) == 'table' and type(core.Reflect) == 'table' and core.Reflect.idToObj or nil
			local singletons
			if delta and ok and type(core) == 'table' and type(core.Modding) == 'table' and type(core.Modding.getSingletons) == 'function' then
				local got, map = pcall(core.Modding.getSingletons)
				singletons = got and type(map) == 'table' and map or nil
			end
			local classes, left = {}, 0
			if type(known) == 'table' and (delta or getgc) then
				for _, wanted in again or controllers.Ids do
					local class = known[wanted]
					if type(class) == 'table' and not classes[class] then
						local built = singletons and rawget(singletons, class)
						if type(built) == 'table' and getmetatable(built) == class then
							controllers.Built[wanted] = built
						else
							classes[class] = wanted
							left += 1
						end
					end
				end
			end
			if left > 0 and not delta and getgc then
				for _, v in getgc(true) do
					if type(v) == 'table' then
						local meta = getmetatable(v)
						local wanted = meta ~= nil and classes[meta]
						if wanted then
							controllers.Built[wanted] = v
							classes[meta] = nil
							left -= 1
							if left == 0 then break end
						end
					end
				end
			end
		end
		return id and controllers.Built[id] or nil
	end
	local missingControllers = {}
	local function resolveController(id)
		local found = findController(id)
		if found then return found end
		local ok, result = pcall(Flamework.resolveDependency, id)
		if ok and result ~= nil then return result end
		local name = id:match('@(%w+)$') or id
		warn('[ElevateV4] '..name..' is not built yet, looking for it again when it is used: '..tostring(result))
		local info = {Id = id, Tries = 0, Next = 0}
		local function real()
			if info.Real then return info.Real end
			if tick() >= info.Next and (info.Walks or 0) < 12 then
				info.Walks = (info.Walks or 0) + 1
				info.Next = tick() + 5
				controllers.Built[id] = nil
				info.Real = findController(nil, {id}) or findController(id)
			end
			return info.Real
		end
		local fallback = {}
		if name == 'AbilityController' then
			local net
			pcall(function()
				local class = require(replicatedStorage['rbxts_include']['node_modules']['@flamework'].core.out).Reflect.idToObj[id]
				for i = 1, 8 do
					local ok2, v = pcall(debug.getupvalue, class.useAbility, i)
					if ok2 and type(v) == 'table' and type(v.client) == 'table' and v.client.useAbility then
						net = v.client
						break
					end
				end
			end)
			local used = {}
			fallback.canUseAbility = function(_, ability)
				return net ~= nil and tick() - (used[ability] or 0) >= 1
			end
			fallback.useAbility = function(_, ability, ...)
				if not net or tick() - (used[ability] or 0) < 1 then return false end
				used[ability] = tick()
				return (pcall(function(...) net.useAbility:fire(ability, ...) end, ...))
			end
		end
		local stub = setmetatable({}, {
			__index = function(_, key)
				local found = real()
				if found then
					local value = found[key]
					if type(value) == 'function' then
						return function(_, ...) return value(found, ...) end
					end
					return value
				end
				return fallback[key] or function() end
			end
		})
		info.Stub = stub
		info.Lookup = real
		missingControllers[name] = info
		return stub
	end
