local kitModules = {}
local kitsWithBehaviour = {}

local function kitHasBehaviour(id)
    return kitsWithBehaviour[id] == true
end

local function kitHooksOf(module)
    local hooks = module.KitHooks
    if not hooks then
        hooks = {}
        module.KitHooks = hooks
    end
    return hooks
end

local createModule = kits.CreateModule
function kits:CreateModule(settings)
    if type(settings) == 'table' and type(settings.Name) == 'string' and KIT_BEHAVIOURS[settings.Name] then
        kitsWithBehaviour[KIT_BEHAVIOURS[settings.Name]] = true
    end
    return createModule(self, settings)
end
vape.Libraries.mergedModule = function(category, settings)
	local parts, main, restarting = {}, nil, false
	local own = settings.Function
	settings.Function = function(callback)
		if own then own(callback) end
		for _, part in parts do
			if callback and part.Switch.Enabled then
				part.Running = true
				local thread = task.spawn(part.Run, true)
				if coroutine.status(thread) ~= 'dead' then main:Clean(thread) end
			elseif part.Running then
				part.Running = false
				task.spawn(part.Run, false)
			end
		end
	end
	main = category:CreateModule(settings)
	function main:Part(partsettings)
		local part = {Run = partsettings.Function or function() end}
		part.Switch = main:CreateToggle({
			Name = partsettings.Label,
			Default = partsettings.Default ~= false,
			Tooltip = partsettings.Tooltip,
			Function = function()
				if main.Enabled and not restarting then
					restarting = true
					task.defer(function()
						restarting = false
						if main.Enabled then
							main:Toggle()
							main:Toggle()
						end
					end)
				end
			end
		})
		setmetatable(part, {__index = function(_, key)
			if key == 'Enabled' then
				return main.Enabled and part.Switch.Enabled
			elseif key == 'Toggle' then
				return function()
					part.Switch:Toggle()
				end
			end
			local value = main[key]
			if type(value) == 'function' then
				return function(_, ...) return value(main, ...) end
			end
			return value
		end})
		table.insert(parts, part)
		return part
	end
	return main
end
local function getKitModule(id, create)
    local module = kitModules[id]
    if module or not create then return module end

    local meta = bedwars.BedwarsKitMeta and bedwars.BedwarsKitMeta[id]
    local display = tostring((meta and (meta.name or meta.displayName)) or id)
    local name = 'Auto' .. display:gsub('[^%w]', '')
    if vape.Kits and vape.Kits.Modules and vape.Kits.Modules[name] or vape.Modules[name] then
        name = name .. 'Ability'
    end
    local hooks = {}
    module = createModule(kits, {
        Name = name,
        Category = 'Auto',
        Tooltip = 'Uses the ' .. display .. ' kit ability for you',
        Function = function(enabled)
            for _, hook in hooks do
                pcall(hook, enabled)
            end
        end
    })
    module.KitHooks = hooks
    module.KitId = id
    kitModules[id] = module
    return module
end

