			vape.Categories.Minigames = vape.Categories.World or vape.Categories.Utility
		end
	end
end)

-- ===== Blatant/AntiVoid.lua =====
run(function()
	local AntiFall
	local Mode
	local Material
	local Color
	local FlyRelease
	local PopAboveLand
	local rayCheck = RaycastParams.new()
	rayCheck.RespectCanCollide = true

	local CELL = 3

	local function balloonCount()
		return (lplr.Character and lplr.Character:GetAttribute('InflatedBalloons')) or 0
	end

	local function inflate()
		if balloonCount() < 3 and getItem('balloon') then
			for _ = 1, 3 - balloonCount() do
				pcall(function() bedwars.BalloonController:inflateBalloon() end)
			end
		end
	end

	local function getLowGround()
		local mag = math.huge
		for _, pos in bedwars.BlockController:getStore():getAllBlockPositions() do
			pos = pos * 3
			if pos.Y < mag and not getPlacedBlock(pos + Vector3.new(0, 3, 0)) then
				mag = pos.Y
			end
		end
		return mag
	end

	local lowestValue, lowestAt = math.huge, 0
	local function lowestGround()
		if tick() - lowestAt > 5 then
			lowestValue = getLowGround()
			lowestAt = tick()
		end
		return lowestValue
	end

	local columnKey, columnValue, columnAt = nil, nil, 0

	local function beingCarried()
		local flyModule = Fly or vape.Modules.Fly
		local longJumpModule = LongJump or vape.Modules.LongJump
		if flyModule and flyModule.Enabled then return true end
		if longJumpModule and longJumpModule.Enabled then return true end
		return false
	end

	local function landBelow(root, lookahead)
		local pos = root.Position
		local horiz = root.AssemblyLinearVelocity * Vector3.new(1, 0, 1)
		local drift = horiz * math.clamp(lookahead or 0, 0, 2)
		local from = Vector3.new(pos.X + drift.X, pos.Y, pos.Z + drift.Z)

		rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiFallPart}
		rayCheck.CollisionGroup = root.CollisionGroup
		local ray = workspace:Raycast(from, Vector3.new(0, -600, 0), rayCheck)
		if ray then return ray.Position.Y end

		local lowest = lowestGround()
		if lowest == math.huge then return nil end
		local cell = bedwars.BlockController:getBlockPosition(from)
		local key = cell.X .. ',' .. cell.Z
		if columnKey == key and (tick() - columnAt) < 0.15 then
			return columnValue
		end
		local floor = math.max(math.floor(lowest / CELL), cell.Y - 400)
		local found = nil
		for y = cell.Y, floor, -1 do
			if getPlacedBlock(Vector3.new(cell.X, y, cell.Z) * CELL) then
				found = y * CELL
				break
			end
		end
		columnKey, columnValue, columnAt = key, found, tick()
		return found
	end

	local flyOwned, landSince = false, 0

	local function flyModule()
		return Fly or vape.Modules.Fly
	end

	local function stopFly(force)
		local module = flyModule()
		if not module then
			flyOwned = false
			return
		end
		if flyOwned and (force or module.Enabled) then
			flyOwned = false
			if module.Enabled then
				task.spawn(function()
					module:Toggle()
				end)
			end
		end
	end

	local function updateFlyMode()
		if Mode.Value ~= 'Fly' then
			stopFly(true)
			return
		end
		if not entitylib.isAlive then
			stopFly(true)
			return
		end
		local root = entitylib.character.RootPart
		local module = flyModule()
		if not root or not module then return end

		local grounded = entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air
		local land = grounded and root.Position.Y or landBelow(root, 0.25)

		if not land then
			landSince = 0
			if not module.Enabled then
				flyOwned = true
				root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, 0, root.AssemblyLinearVelocity.Z)
				task.spawn(function()
					module:Toggle()
				end)
			elseif not flyOwned then
				return
			end
			return
		end

		if flyOwned then
			if landSince == 0 then
				landSince = tick()
			end
			local safeDrop = (FlyRelease and FlyRelease.Value or 12)
			if (tick() - landSince) >= 0.2 and (root.Position.Y - land) <= safeDrop then
				stopFly(false)
			end
		else
			landSince = 0
		end
	end

	AntiFall = vape.Categories.Blatant:CreateModule({
		Name = 'AntiVoid',
		ExtraText = function() return Mode.Value end,
		Function = function(callback)
			if callback then
				repeat task.wait() until store.matchState ~= 0 or (not AntiFall.Enabled)
				if not AntiFall.Enabled then return end

				flyOwned, landSince = false, 0
				AntiFall:Clean(function()
					stopFly(true)
				end)

				AntiFall:Clean(runService.Heartbeat:Connect(updateFlyMode))

				AntiFall:Clean(task.spawn(function()
					repeat
						if Mode.Value == 'Balloon' and PopAboveLand.Enabled and entitylib.isAlive and balloonCount() > 0 then
							local root = entitylib.character.RootPart
							if workspace:Raycast(root.Position, Vector3.new(0, -3000, 0), store.airRay) then
								for _ = 1, 3 do
									if balloonCount() <= 0 then break end
									pcall(function() bedwars.BalloonController:deflateBalloon() end)
									task.wait(0.05)
								end
							end
						end
						task.wait(0.1)
					until not AntiFall.Enabled
				end))

				local pos, debounce = getLowGround(), tick()
				if pos ~= math.huge then
					AntiFallPart = Instance.new('Part')
					AntiFallPart.Size = Vector3.new(10000, 1, 10000)
					AntiFallPart.Transparency = 1 - Color.Opacity
					AntiFallPart.Material = Enum.Material[Material.Value]
					AntiFallPart.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
					AntiFallPart.Position = Vector3.new(0, pos - 2, 0)
					AntiFallPart.CanCollide = Mode.Value == 'Collide'
					AntiFallPart.Anchored = true
					AntiFallPart.CanQuery = false
					AntiFallPart.Parent = workspace
					AntiFall:Clean(AntiFallPart)
					AntiFall:Clean(AntiFallPart.Touched:Connect(function(touched)
						if touched.Parent == lplr.Character and entitylib.isAlive and debounce < tick() then
							debounce = tick() + 0.1
							if Mode.Value == 'Normal' then
								local top = getNearGround()
								if top then
									local lastTeleport = lplr:GetAttribute('LastTeleported')
									local connection
									connection = runService.PreSimulation:Connect(function()
										if beingCarried() then
											connection:Disconnect()
											AntiFallDirection = nil
											return
										end

										if entitylib.isAlive and lplr:GetAttribute('LastTeleported') == lastTeleport then
											local delta = ((top - entitylib.character.RootPart.Position) * Vector3.new(1, 0, 1))
											local root = entitylib.character.RootPart
											AntiFallDirection = delta.Unit == delta.Unit and delta.Unit or Vector3.zero
											root.Velocity *= Vector3.new(1, 0, 1)
											rayCheck.FilterDescendantsInstances = {gameCamera, lplr.Character}
											rayCheck.CollisionGroup = root.CollisionGroup

											local ray = workspace:Raycast(root.Position, AntiFallDirection, rayCheck)
											if ray then
												for _ = 1, 10 do
													local dpos = roundPos(ray.Position + ray.Normal * 1.5) + Vector3.new(0, 3, 0)
													if not getPlacedBlock(dpos) then
														top = dpos
														break
													end
												end
											end

											root.CFrame += Vector3.new(0, top.Y - root.Position.Y, 0)
											if not frictionTable.Speed then
												root.AssemblyLinearVelocity = (AntiFallDirection * getSpeed()) + Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
											end

											if delta.Magnitude < 1 then
												connection:Disconnect()
												AntiFallDirection = nil
											end
										else
											connection:Disconnect()
											AntiFallDirection = nil
										end
									end)
									AntiFall:Clean(connection)
								end
							elseif Mode.Value == 'Balloon' then
								inflate()
							elseif Mode.Value == 'Velocity' then
								entitylib.character.RootPart.Velocity = Vector3.new(entitylib.character.RootPart.Velocity.X, 100, entitylib.character.RootPart.Velocity.Z)
							end
						end
					end))
				end
			else
				AntiFallDirection = nil
				stopFly(true)
			end
		end,
		Tooltip = 'Prevents you from falling into the void'
	})
	Mode = AntiFall:CreateDropdown({
		Name = 'Move Mode',
		List = {'Normal', 'Collide', 'Velocity', 'Fly', 'Balloon'},
		Function = function(val)
			if AntiFallPart then
				AntiFallPart.CanCollide = val == 'Collide'
			end
			if val ~= 'Fly' then
				stopFly(true)
			end
			pcall(function()
				FlyRelease.Object.Visible = val == 'Fly'
				PopAboveLand.Object.Visible = val == 'Balloon'
			end)
		end,
		Tooltip = 'How it saves you'
	})
	FlyRelease = AntiFall:CreateSlider({
		Name = 'Release height',
		Min = 3,
		Max = 60,
		Default = 12,
		Suffix = ' studs',
		Darker = true,
		Visible = false,
		Tooltip = 'How close to land Fly mode stops'
	})
	PopAboveLand = AntiFall:CreateToggle({
		Name = 'Pop when above land',
		Darker = true,
		Visible = false,
		Tooltip = 'Pops the balloons as soon as there is ground underneath you again'
	})
	local materials = {'ForceField'}
	for _, v in Enum.Material:GetEnumItems() do
		if v.Name ~= 'ForceField' then
			table.insert(materials, v.Name)
		end
	end
	Material = AntiFall:CreateDropdown({
		Name = 'Material',
		List = materials,
		Function = function(val)
			if AntiFallPart then
				AntiFallPart.Material = Enum.Material[val]
			end
		end
	})
	Color = AntiFall:CreateColorSlider({
		Name = 'Colour',
		DefaultOpacity = 0.5,
		Function = function(h, s, v, o)
			if AntiFallPart then
				AntiFallPart.Color = Color3.fromHSV(h, s, v)
				AntiFallPart.Transparency = 1 - o
			end
		end
	})
end)

-- ===== Blatant/AntiVoidFlag.lua =====
run(function()
	local v2 = httpService
	local v3 = playersService
	local v4 = replicatedStorage
	local v5 = runService
	local v6 = inputService
	local v7 = tweenService
	local v8 = collectionService
	local v9 = guiService
	local v10 = game:GetService('TeleportService')
	local obj = debug
	local currentCamera = gameCamera
	local localPlayer = lplr
	local entity = entitylib
	local getfontbounds = getfontsize
	local getvapeasset = getcustomasset
	local v11 = replicatesignal and (clonefunction and clonefunction(replicatesignal) or replicatesignal) or nil

		local v12 = nil

		local function fn5(arg)
			local tbl3 = {}

			for _, v13 in { Vector3.new(1, 0, 0), Vector3.new(0, 0, 1), Vector3.new(-1, 0, 0), Vector3.new(0, 0, -1) }, nil, nil do
				for i = 1, 18 do
					local hit = workspace:Raycast(arg + Vector3.new(0, 500, 0) + v13 * i, Vector3.new(0, -1000, 0), store.airRay)

					if hit then
						table.insert(tbl3, hit.Position)
					end
				end
			end

			table.sort(tbl3, function(arg2, arg3)
				return (Vector3.new(arg.X, arg2.Y, arg.Z) - arg2).Magnitude < (Vector3.new(arg.X, arg3.Y, arg.Z) - arg3).Magnitude
			end)

			return tbl3[1]
		end

		v12 = vape.Categories.Blatant:CreateModule({
			Name = "AntiVoidFlag",
			Tooltip = 'Keeps you safe when you are pulled back over the void',
			Function = function(arg)
				if arg and v11 then
					local seat
					pcall(function()
						seat = v4.Assets.Effects.snowball_rider.Handle.Seat
					end)
					if not seat then return end
					local flag = false

					local function fn6()
						while true do
							if entity.isAlive then
								local humanoidRootPart = localPlayer.Character:FindFirstChild("HumanoidRootPart")
								local humanoid = localPlayer.Character:FindFirstChildOfClass("Humanoid")

								if humanoidRootPart and humanoid and not isnetworkowner(humanoidRootPart) and not workspace:Raycast(humanoidRootPart.Position, Vector3.new(0, -1000, 0), store.airRay) then
									humanoidRootPart.AssemblyLinearVelocity = Vector3.zero
									flag = true
									humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
									v11(seat.RemoteCreateSeatWeld, humanoid)
								elseif humanoidRootPart and isnetworkowner(humanoidRootPart) and flag or not humanoidRootPart and flag then
									if humanoidRootPart then
										local v13 = fn5(humanoidRootPart.Position)

										if v13 then
											notif("AntiVoidFlag", "Teleported.", 8, "info")
											humanoidRootPart.AssemblyLinearVelocity = Vector3.new(0, 2.5, 0)
											humanoidRootPart.CFrame = CFrame.lookAlong(v13 + Vector3.new(0, 2.5, 0), humanoidRootPart.CFrame.LookVector)
										end
									end

									v11(seat.RemoteDestroySeatWeld)
									flag = false
								end
							elseif flag then
								v11(seat.RemoteDestroySeatWeld)
								flag = false
							end

							task.wait()
							if v12.Enabled then
								continue
							end
							break
						end

						if flag then
							v11(seat.RemoteDestroySeatWeld)
						end
					end

					fn6()
				end
			end,
		})
	end)

-- ===== Blatant/AutoBuildUp.lua =====
run(function()
    local AutoBuildUp
    local LimitItems
    local pending = {}
    local nextPlacement = 0
    local directions = {
        Vector3.new(3, 0, 0), Vector3.new(-3, 0, 0), Vector3.new(0, 3, 0),
        Vector3.new(0, -3, 0), Vector3.new(0, 0, 3), Vector3.new(0, 0, -3)
    }

    local function getBuildBlock()
        local hand = store.hand
        if hand and hand.toolType == 'block' and hand.tool and (hand.amount or 0) > 0 then return hand.tool.Name end
        if LimitItems.Enabled then return nil end
        local wool, woolamount = getWool()
        if wool and (woolamount or 0) > 0 then return wool end
        for _, item in store.inventory.inventory.items do
            local meta = bedwars.ItemMeta[item.itemType]
            if meta and meta.block and (item.amount or 0) > 0 then return item.itemType end
        end
    end

    local function adjacent(pos)
        for _, offset in directions do
            if getPlacedBlock(pos + offset) then return true end
        end
        return false
    end

    local function buildTarget(root, character)
        local feet = root.Position.Y - (character.HipHeight or 3)
        local base = bedwars.BlockController:getBlockPosition(Vector3.new(root.Position.X, feet, root.Position.Z))
        for step = 0, 2 do
            local world = (base + Vector3.new(0, step, 0)) * 3
            if not getPlacedBlock(world) then return world end
        end
    end

    local function queuePlacement(pos, block)
        local key = tostring(pos)
        local request = pending[key]
        if request and tick() < request.retryAt then return end
        if not adjacent(pos) then return end
        pending[key] = {retryAt = tick() + math.clamp(0.22 + lplr:GetNetworkPing(), 0.25, 0.55), attempts = request and request.attempts + 1 or 1}
        nextPlacement = tick() + math.max(0.125, lplr:GetNetworkPing() * 0.6)
        task.spawn(function()
            local resolved = getBuildBlock()
            if not resolved or getPlacedBlock(pos) then
                pending[key] = nil
                return
            end
            bedwars.placeBlock(pos, resolved)
            task.delay(math.clamp(0.18 + lplr:GetNetworkPing(), 0.22, 0.5), function()
                if not AutoBuildUp.Enabled then return end
                if getPlacedBlock(pos) then
                    pending[key] = nil
                elseif pending[key] and pending[key].attempts >= 3 then
                    pending[key] = nil
                end
            end)
        end)
    end

    AutoBuildUp = vape.Categories.Blatant:CreateModule({
        Name = 'AutoBuildUp',
        Function = function(callback)
            table.clear(pending)
            nextPlacement = 0
            if not callback then return end
            AutoBuildUp:Clean(runService.Heartbeat:Connect(function()
                if not entitylib.isAlive or inputService:GetFocusedTextBox() then return end
                local character = entitylib.character
                local root, humanoid = character.RootPart, character.Humanoid
                if not root or not humanoid then return end
                local holding = humanoid.Jump or inputService:IsKeyDown(Enum.KeyCode.Space) or inputService:IsKeyDown(Enum.KeyCode.ButtonA)
                if not holding then return end
                if tick() < nextPlacement then return end
                local block = getBuildBlock()
                if not block then return end
                local infinite = vape.Modules.InfiniteJump and vape.Modules.InfiniteJump.Enabled
                if infinite and root.AssemblyLinearVelocity.Y < 22 then
                    root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, 28, root.AssemblyLinearVelocity.Z)
                end
                local target = buildTarget(root, character)
                if not target then return end
                queuePlacement(target, block)
            end))
        end,
        Tooltip = 'Towers upward while space is held'
    })
    LimitItems = AutoBuildUp:CreateToggle({Name = 'Limit to items', Tooltip = 'Only works while holding the item it uses'})
end)

-- ===== Blatant/AutoChargeProj.lua =====
run(function()
	local AutoChargeProj
	local Percentage
	local Items
	local removeHook

	local function allowed(projectile)
		local list = Items.ListEnabled
		if #list == 0 then return true end
		local tool = store.hand.tool
		return table.find(list, projectile) ~= nil or (tool ~= nil and table.find(list, tool.Name) ~= nil)
	end

	local function clearHook()
		if removeHook then
			removeHook()
			removeHook = nil
		end
	end

	AutoChargeProj = vape.Categories.Blatant:CreateModule({
		Name = 'AutoChargeProj',
		Function = function(enabled)
			clearHook()
			if not enabled then return end
			if not (bedwars.ProjectileLaunchHook and bedwars.ProjectileController) then
				notif('AutoChargeProj', 'Projectile controller is unavailable.', 5, 'warning')
				task.defer(function() if AutoChargeProj.Enabled then AutoChargeProj:Toggle() end end)
				return
			end
			removeHook = bedwars.ProjectileLaunchHook:Add('AutoChargeProj', 80, function(nextHook, self, launchData, ...)
				local metadata = launchData and bedwars.ProjectileMeta[launchData.projectile]
				if metadata and metadata.predictionLifetimeSec and launchData.drawDurationSeconds and allowed(launchData.projectile) then
					local charge = Percentage.Value / 100
					launchData.drawDurationSeconds = math.max(launchData.drawDurationSeconds, metadata.predictionLifetimeSec * charge)
					launchData.velocityMultiplier = math.max(launchData.velocityMultiplier or 0, charge)
				end
				return nextHook(self, launchData, ...)
			end)
			AutoChargeProj:Clean(clearHook)
		end,
		Tooltip = 'Instantly charges projectile items to the set charge'
	})
	Percentage = AutoChargeProj:CreateSlider({
		Name = 'Percentage',
		Min = 0,
		Max = 100,
		Default = 50,
		Suffix = '%'
	})
	Items = AutoChargeProj:CreateTextList({
		Name = 'Items',
		Placeholder = 'item or projectile id',
		Tooltip = 'Items to charge, empty charges everything'
	})
end)

-- ===== Blatant/BalloonDisabler.lua =====
run(function()
    local Runtime = assert(AetherMatchRuntime, 'Aether BedWars runtime is unavailable')
    local ctx = AetherRuntimeContext
    local Ports = AetherPortContext
    local safe = aetherPortSafe
    local notify = aetherPortNotify
    local rootOfLocal = aetherPortRoot
    local matchRunning = aetherPortMatchRunning
    local equippedKit = aetherPortEquippedKit
    local horizontalUnit = aetherPortHorizontalUnit
    local moduleByName = aetherPortModule
    local register = aetherPortRegister
    local abilityController = aetherPortAbilityController
    local canUseAbility = aetherPortCanUseAbility
    local useAbility = aetherPortUseAbility
    local nearestTarget = aetherPortNearestTarget
    local waitCancelable = aetherPortWait
    local addMovementOwner = aetherPortAddMovementOwner
    local createDecoy = aetherPortCreateDecoy
    local workspaceService = workspace
local BalloonDisabler, BalloonAutoDisable
local balloonControllerState
local balloonAutoConnection

local function stopBalloonAutoDisable()
    if balloonAutoConnection then
        pcall(balloonAutoConnection.Disconnect, balloonAutoConnection)
        balloonAutoConnection = nil
    end
end

local function restoreBalloonController()
    local state = balloonControllerState
    balloonControllerState = nil
    if not state or not state.Controller then return end
    pcall(function()
        if state.Controller.hookBalloon == state.Hook then
            state.Controller.hookBalloon = state.HookOriginal
        end
        if state.Controller.enableBalloonPhysics == state.Physics then
            state.Controller.enableBalloonPhysics = state.PhysicsOriginal
        end
        if state.Controller.deflateBalloon == state.Deflate then
            state.Controller.deflateBalloon = state.DeflateOriginal
        end
    end)
end

BalloonDisabler = (function()
	local module, created
	module, created = register('Blatant', 'BalloonDisabler', {
        Tooltip = 'Stops the balloon check while a balloon is equipped',
        Function = function(callback)
            restoreBalloonController()
            if not callback then return end

            local controller = bedwars.BalloonController
            local item = safe('balloon.inventory', getItem, 'balloon')
            if not item then
                notify('BalloonDisabler: no balloon is available.', 5, 'alert')
                return
            end
            if not controller or type(controller.hookBalloon) ~= 'function' then
                notify('BalloonDisabler: balloon controller is unavailable.', 5, 'warning')
                return
            end

            local state = {
                Controller = controller,
                HookOriginal = controller.hookBalloon,
                PhysicsOriginal = controller.enableBalloonPhysics,
                DeflateOriginal = controller.deflateBalloon
            }
            balloonControllerState = state

            state.Hook = function(self, player, attachment, balloon)
                if tostring(player) ~= lplr.Name then
                    if state.HookOriginal then
                        return state.HookOriginal(self, player, attachment, balloon)
                    end
                    return
                end

                safe('balloon.hide', function()
                    if not balloon then return end
                    local visual = balloon:FindFirstChild('Balloon') or balloon:WaitForChild('Balloon', 1)
                    if visual then
                        visual.CFrame = CFrame.new(0, -1995, 0)
                        visual:ClearAllChildren()
                    end
                end)
                restoreBalloonController()
                task.delay(0.5, function()
                    if module.Enabled then
                        notify('BalloonDisabler: local balloon controller disabled.', 5)
                    end
                end)
            end
            state.Physics = function() end
            state.Deflate = function() end

            local installed, errorMessage = pcall(function()
                if type(controller.inflateBalloon) == 'function' then
                    controller:inflateBalloon()
                end
                controller.enableBalloonPhysics = state.Physics
                controller.deflateBalloon = state.Deflate
                controller.hookBalloon = state.Hook
            end)
            if not installed then
                restoreBalloonController()
                notify('BalloonDisabler: controller setup failed.', 5, 'warning')
                Ports.Diagnostics.BalloonDisabler = {At = tick(), Error = tostring(errorMessage)}
            end
        end
    })
    if created then
        BalloonAutoDisable = module:CreateToggle({
            Name = 'AutoDisable',
            Default = false,
            Function = function(enabled)
                stopBalloonAutoDisable()
                if not enabled then return end
                local inventories = ctx.replicatedStorage and ctx.replicatedStorage:FindFirstChild('Inventories')
                if not inventories then
                    notify('BalloonDisabler: inventory controller is unavailable.', 5, 'warning')
                    return
                end
                local connected, connection = pcall(inventories.DescendantAdded.Connect, inventories.DescendantAdded, function(object)
                    if object.Parent and object.Parent.Name == lplr.Name and object.Name == 'balloon' then
                        task.spawn(function()
                            repeat task.wait() until getItem('balloon') or not BalloonAutoDisable.Enabled
                            if BalloonAutoDisable.Enabled and not module.Enabled then
                                module:Toggle()
                            end
                        end)
                    end
                end)
                if connected then
                    balloonAutoConnection = connection
                    BalloonAutoDisable:Clean(connection)
                end
            end
        })
        module:Clean(function()
            stopBalloonAutoDisable()
            restoreBalloonController()
        end)
    end
    return module
end)()
end)

-- ===== Blatant/DamageBoost.lua =====
run(function()
    local DamageBoost
    local stack

    DamageBoost = vape.Categories.Blatant:CreateModule({
	Name = 'DamageBoost',
	Function = function(callback)
		if callback then
			DamageBoost:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
				if entitylib.isAlive and tick() > (stack or 0) and damageTable.entityInstance == lplr.Character and not LongJump.Enabled then
					local horizontal = (damageTable.knockbackMultiplier and damageTable.knockbackMultiplier.horizontal or 0)
					knockbackSpeed = bedwars.KnockbackUtil.calculateKnockbackVelocity(Vector3.one, 1, {
						vertical = 0,
						horizontal = horizontal,
					}).Magnitude * (0.9 + lplr:GetNetworkPing())
                        stack = tick() + (knockbackSpeed / 45)
                        knockbackBoost = tick() + (horizontal / 3.5)
				end
			end))
		end
	end,
        Tooltip = 'Makes you go slightly faster when damaged'
    })
end)

-- ===== Blatant/Fly.lua =====
run(function()
    local Value
    local VerticalValue
    local WallCheck
    local PopBalloons
    local TP
    local ShowUI
    local AirOnly
    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    local up, down, old = 0, 0
    local deflateHook
    local bar, fill

    local function removeBar()
        if bar then
            bar:Destroy()
            bar, fill = nil, nil
        end
    end

    local function createBar()
        removeBar()
        bar = Instance.new('Frame')
        bar.AnchorPoint = Vector2.new(0.5, 0)
        bar.BackgroundColor3 = Color3.new()
        bar.BackgroundTransparency = 0.5
        bar.BorderSizePixel = 0
        bar.Position = UDim2.new(0.5, 0, 0.5, 150)
        bar.Size = UDim2.fromOffset(160, 6)
        bar.Visible = false
        bar.Parent = vape.gui
        local corner = Instance.new('UICorner')
        corner.CornerRadius = UDim.new(1, 0)
        corner.Parent = bar
        fill = Instance.new('Frame')
        fill.BorderSizePixel = 0
        fill.Size = UDim2.fromScale(0, 1)
        fill.Parent = bar
        corner:Clone().Parent = fill
    end

    local function updateBar(airTime, airborne, counting)
        if not bar or not fill then return end
        bar.Visible = Fly.Enabled and counting and entitylib.isAlive and (airborne or not AirOnly.Enabled) or false
        fill.BackgroundColor3 = Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value)
        fill.Size = UDim2.fromScale(math.clamp(airTime / 2, 0, 1), 1)
    end

    Fly = vape.Categories.Blatant:CreateModule({
        Name = 'Fly',
        Function = function(callback)
            frictionTable.Fly = callback or nil
            updateVelocity()
            if callback then
                up, down = 0, 0
                if not deflateHook then
                    old = bedwars.BalloonController.deflateBalloon
                    deflateHook = function(...)
                        if Fly.Enabled then return end
                        return old(...)
                    end
                    bedwars.BalloonController.deflateBalloon = deflateHook
                end
                local tpTick, tpToggle, oldy = tick(), true
                local engineSpeed = store.engineSpeed(Fly)

                if lplr.Character and (lplr.Character:GetAttribute('InflatedBalloons') or 0) == 0 and getItem('balloon') then
                    bedwars.BalloonController:inflateBalloon()
                end
                Fly:Clean(vapeEvents.AttributeChanged.Event:Connect(function(changed)
                    if changed == 'InflatedBalloons' and (lplr.Character:GetAttribute('InflatedBalloons') or 0) == 0 and getItem('balloon') then
                        bedwars.BalloonController:inflateBalloon()
                    end
                end))
                Fly:Clean(runService.PreSimulation:Connect(function(dt)
                    if entitylib.isAlive and isnetworkowner(entitylib.character.RootPart) then
                        local flyAllowed = (lplr.Character:GetAttribute('InflatedBalloons') and lplr.Character:GetAttribute('InflatedBalloons') > 0) or store.matchState == 2
                        local mass = (-0.02 + (flyAllowed and 6 or 0) * (tick() % 0.4 < 0.2 and -1 or 1)) + ((up + down) * VerticalValue.Value)
                        local root, moveDirection = entitylib.character.RootPart, entitylib.character.Humanoid.MoveDirection
                        local currentSpeed = getSpeed()
                        local destination = moveDirection * math.max(Value.Value - engineSpeed(), 0) * dt
                        rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiFallPart}
                        rayCheck.CollisionGroup = root.CollisionGroup

                        if WallCheck.Enabled then
                            local ray = workspace:Raycast(root.Position, destination, rayCheck)
                            if ray then
                                destination = ((ray.Position + ray.Normal) - root.Position)
                            end
                        end

                        local counting = not flyAllowed and TP.Enabled and not vape.FloatExempt
                        local airborne = entitylib.character.Humanoid.FloorMaterial == Enum.Material.Air
                        local airTime = counting and tpToggle and airborne and (tick() - (entitylib.character.AirTime or tick())) or 0
                        Fly.PullIn = counting and (2 - airTime) or nil
                        updateBar(airTime, airborne, counting)

                        if not flyAllowed then
                            if tpToggle then
                                local airleft = (tick() - entitylib.character.AirTime)
                                if airleft > 2 then
                                    if not oldy then
                                        local ray = workspace:Raycast(root.Position, Vector3.new(0, -1000, 0), rayCheck)
                                        if ray and TP.Enabled and not vape.FloatExempt then
                                            tpToggle = false
                                            oldy = root.Position.Y
                                            tpTick = tick() + 0.11
                                            root.CFrame = CFrame.lookAlong(Vector3.new(root.Position.X, ray.Position.Y + entitylib.character.HipHeight, root.Position.Z), root.CFrame.LookVector)
                                        end
                                    end
                                end
                            else
                                if oldy then
                                    if tpTick < tick() then
                                        local newpos = Vector3.new(root.Position.X, oldy, root.Position.Z)
                                        root.CFrame = CFrame.lookAlong(newpos, root.CFrame.LookVector)
                                        tpToggle = true
                                        oldy = nil
                                    else
                                        mass = 0
                                    end
                                end
                            end
                        end

                        root.CFrame += destination
                        root.AssemblyLinearVelocity = (moveDirection * currentSpeed) + Vector3.new(0, mass, 0)
                    end
                end))
                Fly:Clean(inputService.InputBegan:Connect(function(input)
                    if not inputService:GetFocusedTextBox() then
                        if input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.ButtonA then
                            up = 1
                        elseif input.KeyCode == Enum.KeyCode.LeftShift or input.KeyCode == Enum.KeyCode.ButtonL2 then
                            down = -1
                        end
                    end
                end))
                Fly:Clean(inputService.InputEnded:Connect(function(input)
                    if input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.ButtonA then
                        up = 0
                    elseif input.KeyCode == Enum.KeyCode.LeftShift or input.KeyCode == Enum.KeyCode.ButtonL2 then
                        down = 0
                    end
                end))
                if inputService.TouchEnabled then
                    pcall(function()
                        local jumpButton = lplr.PlayerGui.TouchGui.TouchControlFrame.JumpButton
                        Fly:Clean(jumpButton:GetPropertyChangedSignal('ImageRectOffset'):Connect(function()
                            up = jumpButton.ImageRectOffset.X == 146 and 1 or 0
                        end))
                    end)
                end
            else
                Fly.PullIn = nil
                updateBar(0, false, false)
                if deflateHook and bedwars.BalloonController.deflateBalloon == deflateHook then
                    bedwars.BalloonController.deflateBalloon = old
                    deflateHook = nil
                end
                if PopBalloons.Enabled and entitylib.isAlive and (lplr.Character:GetAttribute('InflatedBalloons') or 0) > 0 then
                    for _ = 1, 3 do
                        bedwars.BalloonController:deflateBalloon()
                    end
                end
            end
        end,
        ExtraText = function()
            return 'Heatseeker'
        end,
        Tooltip = 'Lets you fly'
    })
    Value = Fly:CreateSlider({
        Name = 'Speed',
        Min = 1,
        Max = 23,
        Default = 23,
        Suffix = function(val)
            return val == 1 and 'stud/s' or 'studs/s'
        end,
        Tooltip = 'How fast you fly'
    })
    VerticalValue = Fly:CreateSlider({
        Name = 'Vertical Speed',
        Min = 1,
        Max = 150,
        Default = 50,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
    WallCheck = Fly:CreateToggle({
        Name = 'Wall Check',
        Default = true
    })
    PopBalloons = Fly:CreateToggle({
        Name = 'Pop Balloons',
        Default = true
    })
    TP = Fly:CreateToggle({
        Name = 'TP Down',
        Default = true
    })
    ShowUI = Fly:CreateGroup({
        Name = 'Show UI',
        Function = function(callback)
            if callback then
                local other = vape.Modules.TPDown
                other = other and other.Options['Show UI']
                if other and other.Enabled then other:Toggle() end
                createBar()
            else
                removeBar()
            end
        end,
        Tooltip = 'Shows a bar that fills up until you are pulled down'
    })
    AirOnly = ShowUI:CreateToggle({
        Name = 'Air Only',
        Tooltip = 'Only shows the bar while you are in the air'
    })
    vape:Clean(removeBar)
    Fly:CreateButton({
        Name = 'Reset to default speeds',
        Tooltip = 'Sets speed back to the game\'s default',
        Function = function()
            Value:SetValue(20)
        end,
    })
end)

-- ===== Blatant/FlyingBackpackDisabler.lua =====
run(function()
	local FlyingBackpackDisabler
	local AirDelay
	local Leeway
	local BlockJump
	local FLAP_COST = 10
	local WINDOW = 3.65
	local RESEND = 0.3
	local HANDBACK = 0.8
	local jumpHook
	local refusedAt = 0
	local lastFlap = 0
	local lastSent = 0
	local retryAt = 0
	local backoffUntil = 0
	local warned = false

	local function backpack()
		local inventory = store.inventory and store.inventory.inventory
		local pack = inventory and inventory.backpack
		if type(pack) == 'table' and pack.itemType == 'flying_backpack' then
			return pack.tool or true
		end
		local slot = lplr.Character and lplr.Character:FindFirstChild('BedWarsBackpackSlot')
		local tool = slot and slot.Value
		return tool and tool.Name == 'flying_backpack' and tool or nil
	end

	local function ready(tool)
		if tick() - lastSent < RESEND or tick() < retryAt then return false end
		local energy = typeof(tool) == 'Instance' and tool:GetAttribute('Energy')
		if type(energy) == 'number' and energy < FLAP_COST then return false end
		return workspace:GetServerTimeNow() >= (tonumber(lplr:GetAttribute('NextFlapReadyTime')) or 0)
	end

	local function flap()
		local sent = tick()
		lastSent = sent
		task.spawn(function()
			local ok, accepted = pcall(function()
				return bedwars.Client:Get('FlyingBackpackFlap'):CallServer()
			end)
			if ok and accepted then
				lastFlap = math.max(lastFlap, sent)
			else
				retryAt = tick() + 0.3
			end
		end)
	end

	local function setJumpBlock(enabled)
		local controller = bedwars.FlyingBackpackController
		if type(controller) ~= 'table' then return end
		if enabled then
			if not jumpHook then
				jumpHook = function() return nil end
				controller.flapWings = jumpHook
			end
		elseif jumpHook then
			if rawget(controller, 'flapWings') == jumpHook then
				controller.flapWings = nil
			end
			jumpHook = nil
		end
	end

	FlyingBackpackDisabler = vape.Categories.Blatant:CreateModule({
		Name = 'FlyingBackpackDisabler',
		Function = function(callback)
			vape.FloatExempt = nil
			setJumpBlock(callback and BlockJump.Enabled)
			if not callback then return end

			warned = false
			lastFlap, lastSent, retryAt, backoffUntil, refusedAt = 0, 0, 0, 0, 0
			FlyingBackpackDisabler:Clean(lplr:GetAttributeChangedSignal('LastTeleported'):Connect(function()
				if not vape.FloatExempt then return end
				backoffUntil = tick() + 10
				vape.FloatExempt = nil
				notif('FlyingBackpackDisabler', 'The server still pulled you back, so TP Down is back on for 10 seconds.', 6, 'warning')
			end))
			FlyingBackpackDisabler:Clean(function()
				vape.FloatExempt = nil
				setJumpBlock(false)
			end)

			local airSince
			repeat
				local tool = entitylib.isAlive and backpack() or nil
				local covered = false
				if not tool then
					airSince = nil
					if entitylib.isAlive and not warned then
						warned = true
						notif('FlyingBackpackDisabler', 'Equip a Flying Backpack. This starts working as soon as one is on your back.', 6, 'warning')
					end
				elseif entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air then
					airSince = nil
				else
					airSince = airSince or tick()
					local age = tick() - lastFlap
					if tick() - airSince >= AirDelay.Value and age >= WINDOW - math.max(Leeway.Value, HANDBACK + 0.2) and ready(tool) then
						flap()
					end
					covered = age < WINDOW - HANDBACK and tick() >= backoffUntil
					if not covered and vape.FloatExempt and tick() - refusedAt > 15 then
						refusedAt = tick()
						notif('FlyingBackpackDisabler', 'The server stopped accepting flaps here (too high up or out of energy), so TP Down has taken over.', 6, 'warning')
					end
				end
				vape.FloatExempt = covered or nil
				task.wait(0.05)
			until not FlyingBackpackDisabler.Enabled
		end,
