	local TargetParticlesGroup = Killaura:CreateGroup({
		Name = "Target particles",
		Function = function(Callback: boolean)
			if vape.ThreadFix then
				setthreadidentity(8)
			end
			if Callback then
				for i: number = 1, 10 do
					if vape.ThreadFix then
						setthreadidentity(8)
					end
					local Part: Part = Instance.new("Part")
					if vape.ThreadFix then
						setthreadidentity(8)
					end
					Part.Size = Vector3.new(2, 4, 2)
					Part.Anchored = true
					Part.CanCollide = false
					Part.Transparency = 1
					Part.CanQuery = false
					if vape.ThreadFix then
						setthreadidentity(8)
					end
					Part.Parent = Killaura.Enabled and Camera or nil
					if vape.ThreadFix then
						setthreadidentity(8)
					end
					local Emitter: ParticleEmitter = Instance.new("ParticleEmitter")
					if vape.ThreadFix then
						setthreadidentity(8)
					end
					Emitter.Brightness = 1.5
					Emitter.Size = NumberSequence.new(ParticleSize.Value)
					Emitter.Shape = Enum.ParticleEmitterShape.Sphere
					Emitter.Texture = ParticleTexture.Value
					Emitter.Transparency = NumberSequence.new(0)
					Emitter.Lifetime = NumberRange.new(0.4)
					Emitter.Speed = NumberRange.new(16)
					Emitter.Rate = 128
					Emitter.Drag = 16
					Emitter.ShapePartial = 1
					Emitter.Color = ColorSequence.new({
						ColorSequenceKeypoint.new(0, Color3.fromHSV(ParticleColor1.Hue, ParticleColor1.Sat, ParticleColor1.Value)),
						ColorSequenceKeypoint.new(1, Color3.fromHSV(ParticleColor2.Hue, ParticleColor2.Sat, ParticleColor2.Value))
					})
					if vape.ThreadFix then
						setthreadidentity(8)
					end
					Emitter.Parent = Part
					Particles[i] = Part
				end
			else
				for _, v: Part in Particles do
					if vape.ThreadFix then
						setthreadidentity(8)
					end
					v:Destroy()
				end
				table.clear(Particles)
			end
		end
	})
	ParticleTexture = TargetParticlesGroup:CreateTextBox({
		Name = "Texture",
		Function = function()
			for _, v: Part in Particles do
				if vape.ThreadFix then
					setthreadidentity(8)
				end
				v.ParticleEmitter.Texture = ParticleTexture.Value
			end
		end,
		Default = "rbxassetid://14736249347",
		Darker = true
	})
	ParticleColor1 = TargetParticlesGroup:CreateColorSlider({
		Name = "Color Begin",
		Function = function(Hue: number, Sat: number, Val: number)
			for _, v: Part in Particles do
				if vape.ThreadFix then
					setthreadidentity(8)
				end
				v.ParticleEmitter.Color = ColorSequence.new({
					ColorSequenceKeypoint.new(0, Color3.fromHSV(Hue, Sat, Val)),
					ColorSequenceKeypoint.new(1, Color3.fromHSV(ParticleColor2.Hue, ParticleColor2.Sat, ParticleColor2.Value))
				})
			end
		end,
		Darker = true
	})
	ParticleColor2 = TargetParticlesGroup:CreateColorSlider({
		Name = "Color End",
		Function = function(Hue: number, Sat: number, Val: number)
			for _, v: Part in Particles do
				if vape.ThreadFix then
					setthreadidentity(8)
				end
				v.ParticleEmitter.Color = ColorSequence.new({
					ColorSequenceKeypoint.new(0, Color3.fromHSV(ParticleColor1.Hue, ParticleColor1.Sat, ParticleColor1.Value)),
					ColorSequenceKeypoint.new(1, Color3.fromHSV(Hue, Sat, Val))
				})
			end
		end,
		Darker = true
	})
	ParticleSize = TargetParticlesGroup:CreateSlider({
		Name = "Size",
		Min = 0,
		Max = 1,
		Decimal = 100,
		Function = function(Val: number)
			for _, v: Part in Particles do
				if vape.ThreadFix then
					setthreadidentity(8)
				end
				v.ParticleEmitter.Size = NumberSequence.new(Val)
			end
		end,
		Default = 0.2,
		Darker = true
	})
	Face = Killaura:CreateToggle({Name = "Face target"})
	Animation = Killaura:CreateGroup({
		Name = "Custom Animation",
		Function = function(Callback: boolean)
			if vape.ThreadFix then
				setthreadidentity(8)
			end
			if Killaura.Enabled then
				Killaura:Toggle()
				Killaura:Toggle()
			end
		end
	})
	local AnimationNames: {string} = {}
	for Name: string in Animations do
		if Name ~= "Normal" then
			table.insert(AnimationNames, Name)
		end
	end
	table.sort(AnimationNames)
	table.insert(AnimationNames, 1, "Normal")
	AnimationMode = Animation:CreateDropdown({
		Name = "Animation Mode",
		List = AnimationNames,
		Darker = true
	})
	AnimationSpeed = Animation:CreateSlider({
		Name = "Animation Speed",
		Min = 0,
		Max = 2,
		Default = 1,
		Decimal = 10,
		Darker = true
	})
	AnimationTween = Animation:CreateToggle({
		Name = "No Tween",
		Darker = true
	})
	Limit = Killaura:CreateToggle({
		Name = "Limit to items",
		Function = function(Callback: boolean)
			if UserInputService.TouchEnabled and Killaura.Enabled then
				pcall(function()
					LocalPlayer.PlayerGui.MobileUI["2"].Visible = Callback
				end)
			end
		end,
		Tooltip = 'Only works while holding the item it uses'
	})
	LegitAura = Killaura:CreateToggle({
		Name = "Swing only",
		Tooltip = "Only attacks while swinging manually"
	})
end)

-- ===== Blatant/LongJump.lua =====
run(function()
    local Value
    local CameraDir
    local LimitItems
    local ChangeDir
    local AutoDisable
    local DisableAfter
    local start
    local JumpTick, JumpSpeed, Direction = tick(), 0
    local jumpWasActive = false
    local arcStart, arcEnd
	local function horizontalDirection(direction)
		local flat = direction and Vector3.new(direction.X, 0, direction.Z) or Vector3.zero
		if flat.Magnitude > 0.001 then return flat.Unit end
		local look = entitylib.isAlive and entitylib.character.RootPart.CFrame.LookVector or Vector3.zAxis
		flat = Vector3.new(look.X, 0, look.Z)
		return flat.Magnitude > 0.001 and flat.Unit or Vector3.zAxis
	end
    local projectileRemote = {InvokeServer = function() end}
    task.spawn(function()
        projectileRemote = bedwars.Client:Get(remotes.FireProjectile).instance
    end)

    local function launchProjectile(item, pos, proj, speed, dir)
        if not pos then return end

        pos = pos - dir * 0.1
        local shootPosition = (CFrame.lookAlong(pos, Vector3.new(0, -speed, 0)) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ)))
        switchItem(item.tool, 0)
        task.wait(0.1)
        bedwars.ProjectileController:createLocalProjectile(bedwars.ProjectileMeta[proj], proj, proj, shootPosition.Position, '', shootPosition.LookVector * speed, {drawDurationSeconds = 1})
        if projectileRemote:InvokeServer(item.tool, proj, proj, shootPosition.Position, pos, shootPosition.LookVector * speed, httpService:GenerateGUID(true), {drawDurationSeconds = 1}, workspace:GetServerTimeNow() - 0.045) then
			local itemMeta = bedwars.ItemMeta[item.itemType]
			local source = itemMeta and itemMeta.projectileSource
			local shoot = source and type(source.launchSound) == 'table' and #source.launchSound > 0 and source.launchSound or nil
			shoot = shoot and shoot[math.random(1, #shoot)] or nil
            if shoot then
                bedwars.SoundManager:playSound(shoot)
            end
        end
    end

    local LongJumpMethods = {
        cannon = function(_, pos, dir)
            pos = pos - Vector3.new(0, (entitylib.character.HipHeight + (entitylib.character.RootPart.Size.Y / 2)) - 3, 0)
            local rounded = Vector3.new(math.round(pos.X / 3) * 3, math.round(pos.Y / 3) * 3, math.round(pos.Z / 3) * 3)
            bedwars.placeBlock(rounded, 'cannon', false)

            task.delay(0, function()
                local block, blockpos = getPlacedBlock(rounded)
                if block and block.Name == 'cannon' and (entitylib.character.RootPart.Position - block.Position).Magnitude < 20 then
                    local breaktype = bedwars.ItemMeta[block.Name].block.breakType
                    local tool = getBreakTool(breaktype)
                    if tool then
                        switchItem(tool.tool)
                    end

                    bedwars.Client:Get(remotes.CannonAim):SendToServer({
                        cannonBlockPos = blockpos,
                        lookVector = dir
                    })

                    local broken = 0.1
                    if bedwars.BlockController:calculateBlockDamage(lplr, {blockPosition = blockpos}) < block:GetAttribute('Health') then
                        broken = 0.4
                        bedwars.breakBlock(block, true, true)
                    end

                    task.delay(broken, function()
                        for _ = 1, 3 do
                            local call = bedwars.Client:Get(remotes.CannonLaunch):CallServer({cannonBlockPos = blockpos})
                            if call then
                                bedwars.breakBlock(block, true, true)
                                JumpSpeed = 5.25 * Value.Value
                                JumpTick = tick() + 2.3
								Direction = horizontalDirection(dir)
                                break
                            end
                            task.wait(0.1)
                        end
                    end)
                end
            end)
        end,
        cat = function(_, _, dir)
            LongJump:Clean(vapeEvents.CatPounce.Event:Connect(function()
                JumpSpeed = 4 * Value.Value
                JumpTick = tick() + 2.5
				Direction = horizontalDirection(dir)
                entitylib.character.RootPart.Velocity = Vector3.zero
            end))

            
            
            
            
            if bedwars.CatController and typeof(bedwars.CatController.leap) == 'function' then
                local controller = bedwars.CatController
                local original = controller.leap
                local hook
                hook = function(...)
                    vapeEvents.CatPounce:Fire()
                    return original(...)
                end
                controller.leap = hook
                LongJump:Clean(function()
                    if controller.leap == hook then
                        controller.leap = original
                    end
                end)
            end

            if not bedwars.AbilityController:canUseAbility('CAT_POUNCE') then
                repeat task.wait() until bedwars.AbilityController:canUseAbility('CAT_POUNCE') or not LongJump.Enabled
            end

            if bedwars.AbilityController:canUseAbility('CAT_POUNCE') and LongJump.Enabled then
                bedwars.AbilityController:useAbility('CAT_POUNCE')
            end
        end,
        fireball = function(item, pos, dir)
            launchProjectile(item, pos, 'fireball', 60, dir)
        end,
        grappling_hook = function(item, pos, dir)
            launchProjectile(item, pos, 'grappling_hook_projectile', 140, dir)
        end,
        jadeHammer = function(item, _, dir)
            local jade = AetherMatchRuntime and AetherMatchRuntime.Jade
            if jade then
                local result = jade:ActivateForTraversal('LongJump', dir, function()
                    return not LongJump.Enabled
                end)
                if not result.confirmed or not LongJump.Enabled then return end
                JumpSpeed = 1.4 * Value.Value
                JumpTick = tick() + 2.5
				Direction = horizontalDirection(dir)
                return
            end

            local ability = getJadeAbility(item)
            if not bedwars.AbilityController:canUseAbility(ability) then
                repeat
                    task.wait()
                    ability = getJadeAbility(item)
                until bedwars.AbilityController:canUseAbility(ability) or not LongJump.Enabled
            end
            if bedwars.AbilityController:canUseAbility(ability) and LongJump.Enabled then
                if not activateJadeTool(item) then bedwars.AbilityController:useAbility(ability) end
                local deadline = tick() + 0.75
                repeat
                    task.wait()
                until not bedwars.AbilityController:canUseAbility(ability) or tick() >= deadline or not LongJump.Enabled
                if not LongJump.Enabled or bedwars.AbilityController:canUseAbility(ability) then return end
                JumpSpeed = 1.4 * Value.Value
                JumpTick = tick() + 2.5
				Direction = horizontalDirection(dir)
            end
        end,
        tnt = function(item, pos, dir)
            pos = pos - Vector3.new(0, (entitylib.character.HipHeight + (entitylib.character.RootPart.Size.Y / 2)) - 3, 0)
            local rounded = Vector3.new(math.round(pos.X / 3) * 3, math.round(pos.Y / 3) * 3, math.round(pos.Z / 3) * 3)
            start = Vector3.new(rounded.X, start.Y, rounded.Z) + (dir * (item.itemType == 'pirate_gunpowder_barrel' and 2.6 or 0.2))
            bedwars.placeBlock(rounded, item.itemType, false)
        end,
        wood_dao = function(item, pos, dir)
            if (lplr.Character:GetAttribute('CanDashNext') or 0) > workspace:GetServerTimeNow() or not bedwars.AbilityController:canUseAbility('dash') then
                repeat task.wait() until (lplr.Character:GetAttribute('CanDashNext') or 0) < workspace:GetServerTimeNow() and bedwars.AbilityController:canUseAbility('dash') or not LongJump.Enabled
            end

            if LongJump.Enabled then
                bedwars.SwordController.lastAttack = workspace:GetServerTimeNow()
                switchItem(item.tool, 0.1)
                replicatedStorage['events-@easy-games/game-core:shared/game-core-networking@getEvents.Events'].useAbility:FireServer('dash', {
                    direction = dir,
                    origin = pos,
                    weapon = item.itemType
                })
                JumpSpeed = 4.5 * Value.Value
                JumpTick = tick() + 2.4
				Direction = horizontalDirection(dir)
            end
        end
    }
    for _, v in {'stone_dao', 'iron_dao', 'diamond_dao', 'emerald_dao'} do
        LongJumpMethods[v] = LongJumpMethods.wood_dao
    end
    for _, hammer in jadeHammerNames do
        LongJumpMethods[hammer] = LongJumpMethods.jadeHammer
    end
    LongJumpMethods.void_axe = LongJumpMethods.jadeHammer
    LongJumpMethods.siege_tnt = LongJumpMethods.tnt
    LongJumpMethods.pirate_gunpowder_barrel = LongJumpMethods.tnt

	local function heldLongJumpMethod()
		local hand = store.hand
		local handValue = lplr.Character and lplr.Character:FindFirstChild('HandInvItem')
		local tool = handValue and handValue.Value or nil
		local itemType
		if tool then
			itemType = tool.Name
		else
			tool = hand and hand.tool
			itemType = hand and hand.itemType
		end
		if not tool then return nil end
		local raw = itemType or tool.Name
		local normalized = tostring(raw):lower():gsub('[%s%-]+', '_')
		local method = LongJumpMethods[raw] or LongJumpMethods[normalized]
		local jadeName = isJadeHammerName(normalized)
		if jadeName then method = LongJumpMethods.jadeHammer end
		if not method then return nil end
		local item = getItem(raw) or getItem(normalized)
		if jadeName and AetherMatchRuntime and AetherMatchRuntime.Jade then
			item = AetherMatchRuntime.Jade:GetBestHammer() or item
		end
		item = item or {itemType = normalized, tool = tool, amount = hand and hand.amount or 1}
		return method, item, normalized
	end

    LongJump = vape.Categories.Blatant:CreateModule({
        Name = 'LongJump',
        Function = function(callback)
            frictionTable.LongJump = callback or nil
            updateVelocity()
            if callback then
                if AutoDisable.Enabled then
                    task.spawn(function()
                        task.wait(DisableAfter.Value)
                        if not LongJump.Enabled then return end
                        notif('LongJump', 'Hit Auto Disable time, <font color="#f75454">Disabling</font>!', 2, 'info')
                        LongJump:Toggle()
                    end)
                end
				if LimitItems and LimitItems.Enabled and not heldLongJumpMethod() then
                    frictionTable.LongJump = nil
                    updateVelocity()
                    notif('LongJump', 'Hold a long-jump item to use it (Limit to items is on).', 4)
                    return task.spawn(function() if LongJump.Enabled then LongJump:Toggle() end end)
                end
                LongJump:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
                    
                    if LimitItems and LimitItems.Enabled then return end
                    if damageTable.entityInstance == lplr.Character and damageTable.fromEntity == lplr.Character and (not damageTable.knockbackMultiplier or not damageTable.knockbackMultiplier.disabled) then
                        local knockbackBoost = bedwars.KnockbackUtil.calculateKnockbackVelocity(Vector3.one, 1, {
                            vertical = 0,
                            horizontal = (damageTable.knockbackMultiplier and damageTable.knockbackMultiplier.horizontal or 1)
                        }).Magnitude * 1.1

                        if knockbackBoost >= JumpSpeed then
                            local pos = damageTable.fromPosition and Vector3.new(damageTable.fromPosition.X, damageTable.fromPosition.Y, damageTable.fromPosition.Z) or damageTable.fromEntity and damageTable.fromEntity.PrimaryPart.Position
                            if not pos then return end
                            local vec = (entitylib.character.RootPart.Position - pos)
                            JumpSpeed = knockbackBoost
                            JumpTick = tick() + 2.5
                            Direction = Vector3.new(vec.X, 0, vec.Z).Unit
                        end
                    end
                end))
                LongJump:Clean(vapeEvents.GrapplingHookFunctions.Event:Connect(function(dataTable)
                    if dataTable.hookFunction == 'PLAYER_IN_TRANSIT' then
                        local vec = entitylib.character.RootPart.CFrame.LookVector
                        JumpSpeed = 2.5 * Value.Value
                        JumpTick = tick() + 2.5
                        Direction = Vector3.new(vec.X, 0, vec.Z).Unit
                    end
                end))

                start = entitylib.isAlive and entitylib.character.RootPart.Position or nil
                LongJump:Clean(runService.PreSimulation:Connect(function(dt)
                    local root = entitylib.isAlive and entitylib.character.RootPart or nil

                    if root and isnetworkowner(root) then
                        if JumpTick > tick() then
                            if not jumpWasActive then
                                jumpWasActive = true
                                longJumpActivation:Fire(root.AssemblyLinearVelocity)
                            end
                            
                            
                            
                            
                            if ChangeDir and ChangeDir.Enabled and Direction then
                                local steer = entitylib.character.Humanoid.MoveDirection
                                steer = Vector3.new(steer.X, 0, steer.Z)
                                if steer.Magnitude < 0.1 and CameraDir and CameraDir.Enabled then
                                    local look = gameCamera.CFrame.LookVector
                                    steer = Vector3.new(look.X, 0, look.Z)
                                end
                                if steer.Magnitude > 0.1 then
                                    Direction = steer.Unit
                                end
                            end
                            root.AssemblyLinearVelocity = Direction * (getSpeed() + ((JumpTick - tick()) > 1.1 and JumpSpeed or 0)) + Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
                            if entitylib.character.Humanoid.FloorMaterial == Enum.Material.Air and not start then
                                if arcEnd ~= JumpTick then
                                    arcStart, arcEnd = tick(), JumpTick
                                end
                                local total = math.max(arcEnd - arcStart, 0.1)
                                local rise = (16 / total) * (1 - 2 * math.clamp((tick() - arcStart) / total, 0, 1))
                                root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, rise + dt * workspace.Gravity, root.AssemblyLinearVelocity.Z)
                            else
                                root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, 15, root.AssemblyLinearVelocity.Z)
                            end
                            start = nil
                        else
                            jumpWasActive = false
                            if start then
                                root.CFrame = CFrame.lookAlong(start, root.CFrame.LookVector)
                            end
                            root.AssemblyLinearVelocity = Vector3.zero
                            JumpSpeed = 0
                        end
                    else
                        start = nil
                    end
                end))

				local heldMethod, heldItem = heldLongJumpMethod()
				if heldMethod then
					task.spawn(heldMethod, heldItem, start, (CameraDir.Enabled and gameCamera or entitylib.character.RootPart).CFrame.LookVector)
                    return
                end

                
                
                if LimitItems and LimitItems.Enabled then return end

                for i, v in LongJumpMethods do
                    local item = getItem(i)
                    if item or store.equippedKit == i then
                        task.spawn(v, item, start, (CameraDir.Enabled and gameCamera or entitylib.character.RootPart).CFrame.LookVector)
                        break
                    end
                end
            else
                JumpTick = tick()
                jumpWasActive = false
                Direction = nil
                JumpSpeed = 0
            end
        end,
        ExtraText = function()
            return 'Heatseeker'
        end,
        Tooltip = 'Lets you jump farther'
    })
    Value = LongJump:CreateSlider({
        Name = 'Speed',
        Min = 1,
        Max = 37,
        Default = 37,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
    CameraDir = LongJump:CreateToggle({
        Name = 'Camera Direction'
    })
    LimitItems = LongJump:CreateToggle({
        Name = 'Limit to items',
        Tooltip = 'Only works while holding the item it uses'
    })
    ChangeDir = LongJump:CreateToggle({
        Name = 'Change direction mid-air',
        Tooltip = 'Lets you steer the boost with your movement keys'
    })
    AutoDisable = LongJump:CreateToggle({
        Name = 'Auto Disable',
        Default = false,
        Tooltip = 'Turns itself off after a set time'
    })
    DisableAfter = LongJump:CreateSlider({
        Name = 'Disable After:',
        Min = 0.1,
        Max = 5,
        Default = 1.5,
        Decimal = 100,
        Darker = true,
        Suffix = function(val)
            return 'seconds'
        end
    })

    local api = {
        Module = LongJump,
        Methods = LongJumpMethods,
        GetHeldMethod = heldLongJumpMethod,
        GetJumpTick = function() return JumpTick end
    }
    shared.AetherLongJumpRuntime = api
    vape:Clean(function() if shared.AetherLongJumpRuntime == api then shared.AetherLongJumpRuntime = nil end end)
end)

-- ===== Blatant/NoFallDamage.lua =====
run(function()
    local NoFall
    local Mode
    local Clutch
    local HealthCheck
    local CvDamage
    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    rayCheck.FilterType = Enum.RaycastFilterType.Exclude
    
    local plainCheck = RaycastParams.new()
    plainCheck.RespectCanCollide = true
    plainCheck.FilterType = Enum.RaycastFilterType.Exclude
    local usedPearl = false
    local lastLegitUse = 0
    local clutchBusyUntil = 0
    local lastBlockPlace = 0
    local lastZephyrJump = 0
    local fallAnchorY
    local projectileRemote = {InvokeServer = function() end}
    task.spawn(function()
        projectileRemote = bedwars.Client:Get(remotes.FireProjectile).instance
    end)

    local daoItems = {'wood_dao', 'stone_dao', 'iron_dao', 'diamond_dao', 'emerald_dao'}

    local function validCharacter()
        if not entitylib.isAlive then return end
        local character = entitylib.character
        local root = character.RootPart or character.HumanoidRootPart
        local humanoid = character.Humanoid
        if root and humanoid and humanoid.Health > 0 then
            return character, root, humanoid
        end
    end

    local function updateRay(root)
        rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiFallPart}
        rayCheck.CollisionGroup = root.CollisionGroup
    end

    local function getGround(root, character, distance)
        updateRay(root)
        local hipHeight = character.HipHeight or (character.Humanoid and character.Humanoid.HipHeight) or 2
        local castDistance = -(distance + hipHeight + (root.Size.Y * 0.5))
        return workspace:Blockcast(root.CFrame, Vector3.new(3, 3, 3), Vector3.new(0, castDistance, 0), rayCheck)
    end

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    local function groundBelow(root, character)
        local ground = getGround(root, character, 1500)
        if ground then return ground.Position.Y end

        plainCheck.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiFallPart}
        local ray = workspace:Raycast(root.Position, Vector3.new(0, -3000, 0), plainCheck)
        if ray then return ray.Position.Y end

        local success, blockY = pcall(function()
            local origin = root.Position
            for step = 1, 200 do
                local below = Vector3.new(origin.X, origin.Y - (step * 3), origin.Z)
                if getPlacedBlock(below) then
                    
                    return (bedwars.BlockController:getBlockPosition(below).Y * 3) + 1.5
                end
            end
            return nil
        end)
        return success and blockY or nil
    end

    
    
    
    local function standClearance(root, character)
        local humanoid = character.Humanoid
        return character.HipHeight or ((humanoid and humanoid.HipHeight or 2) + (root.Size.Y * 0.5))
    end

    
    
    
    
    local trackedFall = 0

    local function updateTrackedFall(root, humanoid)
        if humanoid and humanoid.FloorMaterial ~= Enum.Material.Air then
            trackedFall = 0
        else
            trackedFall = math.min(trackedFall, root.AssemblyLinearVelocity.Y)
        end
        return trackedFall
    end

    
    
    
    
    
    
    
    
    
	local clearRegisteredFall
	local function tpNoFall(root, character)
        local groundY = groundBelow(root, character)
        if not groundY then return false end

        local floorY = groundY + standClearance(root, character)
        local drop = root.Position.Y - floorY
        
        if drop <= 1 then return false end

        local velocity = root.AssemblyLinearVelocity
		local landed = root.CFrame - Vector3.new(0, drop, 0)
		
		
		character:PivotTo(landed)
        
        
        
        
        root.AssemblyLinearVelocity = Vector3.new(velocity.X, 0, velocity.Z)
        
        
        
		trackedFall = 0
		clearRegisteredFall(-1)
		return true
    end

    local function restoreTool(oldTool)
        if oldTool and oldTool.tool then
            task.delay(0.18, function()
                switchItem(oldTool.tool)
                local oldHotbar = getHotbar(oldTool.tool)
                if oldHotbar then hotbarSwitch(oldHotbar) end
            end)
        end
    end

    local function firePearl(root, spot, pearl)
        if usedPearl or not pearl or not projectileRemote or not projectileRemote.InvokeServer then return end
        local meta = bedwars.ProjectileMeta.telepearl
        if not meta then return end

        local calc = prediction.SolveTrajectory(root.Position, meta.launchVelocity, meta.gravitationalAcceleration, spot, Vector3.zero, workspace.Gravity, 0, 0, nil, false, spot, nil, nil, true)
        if not calc then return end

        local oldTool = store.hand
        local hotbar = getHotbar(pearl.tool)
        switchItem(pearl.tool, 0.1)
        if hotbar then hotbarSwitch(hotbar) end
        task.wait(0.03)

        local direction = CFrame.lookAt(root.Position, calc).LookVector * meta.launchVelocity
        local success = pcall(function()
            bedwars.ProjectileController:createLocalProjectile(meta, 'telepearl', 'telepearl', root.Position, nil, direction, {drawDurationSeconds = 1})
            projectileRemote:InvokeServer(pearl.tool, 'telepearl', 'telepearl', root.Position, root.Position, direction, httpService:GenerateGUID(true), {
                drawDurationSeconds = 1,
                shotId = httpService:GenerateGUID(false)
            }, workspace:GetServerTimeNow() - 0.045)
        end)
        restoreTool(oldTool)
        if success then
            usedPearl = true
            return true
        end
    end

    local function blockClutch(root)
        if tick() - lastBlockPlace < 0.08 then return end
        local wool, amount = getWool()
        if not wool or (amount or 0) < 1 then return end

        lastBlockPlace = tick()
        local placePosition = bedwars.BlockController:getBlockPosition(root.Position - Vector3.new(0, 4, 0)) * 3
        fallAnchorY = root.Position.Y
        if not getPlacedBlock(placePosition) and bedwars.placeBlock(placePosition, wool) then
            return true
        end
    end

    local function isFallFatal(root, humanoid, ground)
        if not HealthCheck or not HealthCheck.Enabled then return true end
        if not ground then return true end

        local health = (lplr.Character and lplr.Character:GetAttribute('Health')) or humanoid.Health
        local fallBlocks = math.max(0, ((fallAnchorY or root.Position.Y) - ground.Position.Y) / 3)
        local estimatedDamage = math.max(0, fallBlocks - 6) * 5
        return estimatedDamage >= health + 10
    end

    local function abilityClutch(item, ability, callback)
        if not item then return end
        local oldTool = store.hand
        local hotbar = getHotbar(item.tool)
        switchItem(item.tool, 0.1)
        if hotbar then hotbarSwitch(hotbar) end
        task.wait(0.05)
        callback(item, ability)
        restoreTool(oldTool)
        return true
    end

    local function useToolAbility(ability, data)
        local success, result = pcall(function()
            return bedwars.AbilityController:useAbility(ability, newproxy(true), data)
        end)
        if success and result ~= false then return true end

        success, result = pcall(function()
            return bedwars.AbilityController:useAbility(ability, data)
        end)
        if success and result ~= false then return true end

        pcall(function()
            bedwars.Client:Get(remotes.UseAbility).instance:FireServer(ability, data)
        end)
        return true
    end

    local function jadeClutch(root)
        local item
        for _, hammer in jadeHammerNames do
            item = getItem(hammer)
            if item then break end
        end
        if not item then return end
        local ability = 'jade_hammer_jump'
        if bedwars.AbilityController:canUseAbility(ability) then
            return abilityClutch(item, ability, function(_, abilityId)
                useToolAbility(abilityId, {direction = Vector3.yAxis, origin = root.Position})
                root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, math.max(root.AssemblyLinearVelocity.Y, -3), root.AssemblyLinearVelocity.Z)
            end)
        end
    end

    local function voidClutch(root)
        local item = getItem('void_axe')
        if not item then return end
        local ability = item.itemType..'_jump'
        if bedwars.AbilityController:canUseAbility(ability) then
            return abilityClutch(item, ability, function(_, abilityId)
                useToolAbility(abilityId, {direction = Vector3.yAxis, origin = root.Position})
                root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, math.max(root.AssemblyLinearVelocity.Y, -3), root.AssemblyLinearVelocity.Z)
            end)
        end
    end

    local function daoClutch(root)
        for _, itemName in daoItems do
            local item = getItem(itemName)
            if item and (lplr.Character:GetAttribute('CanDashNext') or 0) < workspace:GetServerTimeNow() and bedwars.AbilityController:canUseAbility('dash') then
                return abilityClutch(item, 'dash', function(dao)
                    bedwars.SwordController.lastAttack = workspace:GetServerTimeNow()
                    replicatedStorage['events-@easy-games/game-core:shared/game-core-networking@getEvents.Events'].useAbility:FireServer('dash', {
                        direction = Vector3.new(root.CFrame.LookVector.X, -0.05, root.CFrame.LookVector.Z).Unit,
                        origin = root.Position,
                        weapon = dao.itemType
                    })
                    root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, math.max(root.AssemblyLinearVelocity.Y, -3), root.AssemblyLinearVelocity.Z)
                end)
            end
        end
    end

    local function toolClutch(root)
        if Clutch and Clutch:Has('Dao') and daoClutch(root) then return true end
        if Clutch and Clutch:Has('Jade Hammer') and jadeClutch(root) then return true end
        if Clutch and Clutch:Has('Void Axe') and voidClutch(root) then return true end
    end

    local function shouldToolClutch(root, humanoid, groundDistance)
        if not groundDistance or groundDistance == math.huge then return false end
        local verticalSpeed = math.abs(root.AssemblyLinearVelocity.Y)
        if verticalSpeed <= 0 then return false end

        local bodyClearance = (humanoid.HipHeight or 2) + (root.Size.Y * 0.5)
        local remainingDistance = math.max(0, groundDistance - bodyClearance)
        return remainingDistance <= 4.5 or (remainingDistance / verticalSpeed) <= 0.16
    end

    local function telepearlClutch(root, ground, groundDistance)
        if usedPearl or not (Clutch and Clutch:Has('Telepearl')) then return end
        local pearl = getItem('telepearl')
        return pearl and ground and firePearl(root, ground.Position + Vector3.new(0, 3, 0), pearl)
    end

    local clutchMethod

    local function hasWool()
        local wool, amount = getWool()
        return wool ~= nil and (amount or 0) >= 1
    end

    local function legitClutch(root, humanoid, ground)
        local now = tick()
        if now < clutchBusyUntil or now - lastLegitUse < 0.06 then return end
        if humanoid.FloorMaterial ~= Enum.Material.Air or root.AssemblyLinearVelocity.Y >= 0 then
            fallAnchorY = root.Position.Y
            clutchMethod = nil
            return
        end

        local groundDistance = ground and (root.Position.Y - ground.Position.Y) or math.huge
        fallAnchorY = fallAnchorY or root.Position.Y
        lastLegitUse = now

        if not isFallFatal(root, humanoid, ground) then return end

        local blocksUsable = (Clutch and Clutch:Has('Blocks')) and groundDistance > 21
            and (fallAnchorY - root.Position.Y) >= 15 and hasWool()
        local pearlUsable = Clutch and Clutch:Has('Telepearl') and not usedPearl and getItem('telepearl') ~= nil
        local toolUsable = ground and shouldToolClutch(root, humanoid, groundDistance) and true or false

        if clutchMethod == 'blocks' and not blocksUsable then clutchMethod = nil end
        if clutchMethod == 'pearl' and not pearlUsable then clutchMethod = nil end
        if clutchMethod == 'tool' and not toolUsable then clutchMethod = nil end
        if not clutchMethod then
            clutchMethod = blocksUsable and 'blocks' or pearlUsable and 'pearl' or toolUsable and 'tool' or nil
        end

        if root.AssemblyLinearVelocity.Y > -60 then return end

        if clutchMethod == 'blocks' then
            if blockClutch(root) then
                clutchBusyUntil = tick() + 0.08
                return true
            end
        elseif clutchMethod == 'pearl' then
            if telepearlClutch(root, ground, groundDistance) then
                clutchBusyUntil = tick() + 0.65
                return true
            end
        elseif clutchMethod == 'tool' then
            if toolClutch(root) then
                clutchBusyUntil = tick() + 0.65
                return true
            end
        end
    end

    
    
    
    local function hasZephyrKit()
        local success, result = pcall(function()
            local kit = store.equippedKit
            if kit == nil or kit == '' then
                kit = lplr:GetAttribute('PlayingAsKit')
            end
            if kit == nil then return nil end
            
            
            
            local name = string.lower(tostring(kit))
            return name:find('zephyr') ~= nil or name:find('wind') ~= nil
        end)
        if not success then return nil end
        return result
    end

    local zephyrFired = false
    local function zephyrClutch(root, humanoid, ground)
        local now = tick()
        if humanoid.FloorMaterial ~= Enum.Material.Air or root.AssemblyLinearVelocity.Y >= 0 then
            fallAnchorY = root.Position.Y
            zephyrFired = false
            return
        end

        fallAnchorY = fallAnchorY or root.Position.Y
        
        
        if zephyrFired or now - lastZephyrJump < 0.3 then return end
        if not ground or not isFallFatal(root, humanoid, ground) then return end

        
        
        if hasZephyrKit() == false then return end

        local stacks = type(getWindStacks) == 'function' and getWindStacks() or 0
        if stacks < 5 then return end

        local groundDistance = root.Position.Y - ground.Position.Y
        local bodyClearance = (humanoid.HipHeight or 2) + (root.Size.Y * 0.5)
        local remainingDistance = math.max(0, groundDistance - bodyClearance)
        local verticalSpeed = math.abs(root.AssemblyLinearVelocity.Y)

        
        
        
        local totalFall = math.max(fallAnchorY - root.Position.Y, 0) + remainingDistance
        if totalFall < 20 then return end

        
        if remainingDistance <= 3.5 or (verticalSpeed > 0 and (remainingDistance / verticalSpeed) <= 0.09) then
            lastZephyrJump = now
            zephyrFired = true
            pcall(function()
                humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
                humanoid.Jump = true
            end)
            
            
            task.delay(0.2, function()
                pcall(function()
                    if humanoid.Parent then
                        humanoid.Jump = false
                    end
                end)
            end)
            return true
        end
    end

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    local groundHit
    local groundHitBlock

    local function resolveGroundHit()
        if groundHit and groundHitBlock then return groundHit end
        local success, remote, block = pcall(function()
            local managed = replicatedStorage.rbxts_include.node_modules['@rbxts'].net.out._NetManaged
            return managed.GroundHit, workspace.Map.Worlds.tr_Range.Blocks:GetChildren()[222]
        end)
        groundHit = success and remote or nil
        groundHitBlock = success and block or nil
        return groundHit
    end
    task.spawn(resolveGroundHit)

	clearRegisteredFall = function()
        local remote = resolveGroundHit()
        if not remote or not groundHitBlock then return false end
		local success = pcall(function()
			remote:FireServer(
                groundHitBlock,
                Vector3.new(-10.598394393921, -35.038021087646, -16.960966110229),
                1785564031.154
            )
        end)
        return success
    end

    local cvStateConnections = {}
    local modeGeneration = 0

    local function restoreCvStateConnections()
        for _, connection in cvStateConnections do
            pcall(function()
                if connection.Enable then connection:Enable() end
            end)
        end
        table.clear(cvStateConnections)
    end

    local function disableCvStateConnections(humanoid)
        restoreCvStateConnections()
        if not humanoid or type(getconnections) ~= 'function' then return end
        local ok, connections = pcall(getconnections, humanoid.StateChanged)
        if not ok or type(connections) ~= 'table' then return end
        for _, connection in connections do
            if connection and connection.Disable then
                local disabled = pcall(connection.Disable, connection)
                if disabled then table.insert(cvStateConnections, connection) end
            end
        end
    end

    local function startCvBlatant(generation)
        if entitylib.isAlive then
            disableCvStateConnections(entitylib.character.Humanoid)
        end

        local trackedVelocity = 0
        local settle = 0
        local groundHit
        pcall(function()
            groundHit = bedwars.Handler:Get('GroundHit')
        end)

        NoFall:Clean(runService.PostSimulation:Connect(function()
            if generation ~= modeGeneration or not NoFall.Enabled or Mode.Value ~= 'Blatant' then return end
            if not entitylib.isAlive or store.matchState ~= 1 or store.infinitefly then
                if store.infinitefly then
                    trackedVelocity = 0
                    settle = tick() + 0.5
                end
                return
            end

            local root = entitylib.character.RootPart
            local humanoid = entitylib.character.Humanoid
            local velocity = root.Velocity
            if trackedVelocity < -(45 + ((CvDamage and CvDamage.Value or 0) * 0.75)) and tick() >= settle then
                
                
                root.Velocity = Vector3.new(0, 2.5, 0)
                humanoid:ChangeState(Enum.HumanoidStateType.Landed)
                runService.PreRender:Wait()
                if generation == modeGeneration and NoFall.Enabled and Mode.Value == 'Blatant' and root.Parent then
                    root.Velocity = velocity
                    if groundHit then
                        pcall(groundHit.Fire, groundHit, 'SendToServer', nil, Vector3.new(0, trackedVelocity, 0), workspace:GetServerTimeNow())
                    end
                end
            end
            trackedVelocity = velocity.Y
        end))

        NoFall:Clean(entitylib.Events.LocalAdded:Connect(function(ent)
            if generation ~= modeGeneration or not NoFall.Enabled or Mode.Value ~= 'Blatant' then return end
            task.defer(function()
                if generation == modeGeneration and NoFall.Enabled and Mode.Value == 'Blatant' then
                    disableCvStateConnections(ent.Humanoid)
                end
            end)
        end))
    end

    local function setSettingsVisible()
        local legit = Mode and Mode.Value == 'Legit'
        if CvDamage and CvDamage.Object then CvDamage.Object.Visible = not legit end
        if HealthCheck and HealthCheck.Object then HealthCheck.Object.Visible = legit end
        if Clutch and Clutch.Object then Clutch.Object.Visible = legit end
    end

    NoFall = vape.Categories.Blatant:CreateModule({
        Name = 'NoFallDamage',
        Function = function(callback)
            modeGeneration += 1
            local generation = modeGeneration

            if callback then
                restoreCvStateConnections()
                if Mode.Value == 'Blatant' then
                    startCvBlatant(generation)
                end

                repeat
                    local waitDelay = 0.1
                    local character, root, humanoid = validCharacter()
                    if character then
                        updateTrackedFall(root, humanoid)
                        if humanoid.FloorMaterial ~= Enum.Material.Air then
                            usedPearl = false
                        elseif Mode.Value == 'Legit' then
                            local ground = getGround(root, character, HealthCheck and HealthCheck.Enabled and 300 or 30)
                            local zephyred = false
                            if Clutch and Clutch:Has('Zephyr') then
                                zephyred = zephyrClutch(root, humanoid, ground)
                                if zephyred then waitDelay = 0.05 end
                            end
                            if not zephyred then legitClutch(root, humanoid, ground) end
                        end
                    end
                    task.wait(waitDelay)
                until not NoFall.Enabled or generation ~= modeGeneration
            else
                restoreCvStateConnections()
                usedPearl = false
                lastLegitUse = 0
                clutchBusyUntil = 0
                lastBlockPlace = 0
                lastZephyrJump = 0
                zephyrFired = false
                fallAnchorY = nil
                clutchMethod = nil
                trackedFall = 0
            end
        end,
        Tooltip = 'Prevents fall damage'
    })
	Mode = NoFall:CreateDropdown({
		Name = 'Mode',
		List = {'Blatant', 'Legit'},
        Function = function()
            setSettingsVisible()
            if NoFall.Enabled then
                NoFall:Toggle()
                NoFall:Toggle()
            end
        end,
		Tooltip = 'Blatant - cancels fall damage\nLegit - saves you by clutching'
    })
    CvDamage = NoFall:CreateSlider({
        Name = 'Damage',
        Min = 0,
        Max = 100,
        Default = 0,
        Suffix = '%',
        Tooltip = 'How much fall damage to take'
    })
    Clutch = NoFall:CreateMultiDropdown({
        Name = 'Clutch with',
        List = {'Blocks', 'Zephyr', 'Telepearl', 'Dao', 'Jade Hammer', 'Void Axe'},
        Default = {'Blocks', 'Telepearl', 'Dao', 'Jade Hammer', 'Void Axe'},
        Tooltip = 'What it uses to save you from a fall'
    })
    HealthCheck = NoFall:CreateToggle({
        Name = 'Health check',
        Tooltip = 'Only clutches when the fall would kill you'
    })

    setSettingsVisible()
end)

-- ===== Blatant/NoSlowdown.lua =====
run(function()
    local NoSlowdown
    local old, hook, hooked

    NoSlowdown = vape.Categories.Blatant:CreateModule({
        Name = 'NoSlowdown',
        Function = function(callback)
            local modifier = bedwars.SprintController:getMovementStatusModifier()
            if callback then
                if not (hook and hooked == modifier) then
                    old = modifier.addModifier
                    hooked = modifier
                    hook = function(self, tab)
                        if NoSlowdown.Enabled and type(tab) == 'table' and tab.moveSpeedMultiplier then
                            tab.moveSpeedMultiplier = math.max(tab.moveSpeedMultiplier, 1)
                        end
                        return old(self, tab)
                    end
                    modifier.addModifier = hook
                end

                local slowing = {}
                for i in modifier.modifiers do
                    if (i.moveSpeedMultiplier or 1) < 1 then
                        table.insert(slowing, i)
                    end
                end
                for _, i in slowing do
                    modifier:removeModifier(i)
                end
            elseif hook then
                if hooked.addModifier == hook then
                    hooked.addModifier = old
                    old, hook, hooked = nil, nil, nil
                end
            end
        end,
        Tooltip = 'Stops items and weapons slowing you down'
    })
end)

-- ===== Blatant/PlayerAttach.lua =====
run(function()

    local util = vape.Libraries.bedwarsutil
    local PlayerAttach
    local Range
    local Targets

    local rayCheck = RaycastParams.new()
    rayCheck.FilterType = Enum.RaycastFilterType.Exclude

    PlayerAttach = vape.Categories.Blatant:CreateModule({
        Name = 'PlayerAttach',
        Tooltip = 'Sticks you to the nearest target',
        Function = function(call)
            if call then
                local plr, nextScan = nil, 0
                local function sortHealth(a, b)
                    return a.Entity.Health < b.Entity.Health
                end
                repeat
                    if entitylib.isAlive then
                        if tick() >= nextScan then
                            nextScan = tick() + 0.1
                            plr = entitylib.AllPosition({
                                Range = Range.Value,
                                Wallcheck = Targets.Walls.Enabled or nil,
                                Part = 'RootPart',
                                Players = Targets.Players.Enabled,
                                Priority = Targets.Priority and Targets.Priority.Value,
                                NPCs = Targets.NPCs.Enabled,
                                Limit = 1,
                                Sort = sortHealth
                            })[1]
                        end
                        local root = entitylib.character.RootPart
                        if plr and plr.RootPart and plr.RootPart.Parent and root and isnetworkowner(root) then
                            rayCheck.FilterDescendantsInstances = {plr.RootPart.Parent, lplr.Character}

                            root.AssemblyLinearVelocity = Vector3.new(0, root.Size.Y / 2 + entitylib.character.Humanoid.HipHeight + 0.25 * 3, 0)
                            root.CFrame = plr.RootPart.CFrame + (not workspace:Raycast(plr.RootPart.Position, plr.RootPart.CFrame.LookVector, rayCheck) and (plr.RootPart.CFrame.LookVector * 1.4) or Vector3.zero)
                        end
                    else
                        plr = nil
                    end
                    task.wait()
                until not PlayerAttach.Enabled
            end
        end
    })

    Targets = PlayerAttach:CreateTargets({
        Players = true,
        NPCs = true
    })

    Range = PlayerAttach:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 35,
        Default = 23,
        Suffix = util.Studs
    })
end)

-- ===== Blatant/ProjectileAimbot.lua =====
run(function()
	local ProjectileAimbot
	local Blacklist
	local TargetPart
	local Targets
	local Sort
	local FOV
	local Range
	local AutoCharge
	local Aim = {}
	local OtherProjectiles
	local rayCheck = RaycastParams.new()
	rayCheck.FilterType = Enum.RaycastFilterType.Include
	rayCheck.FilterDescendantsInstances = {workspace:FindFirstChild('Map')}
	local fovCircle
	local fovColour
	local fovThickness
	local ShowFOV
	local circleLibrary = vape.Libraries and vape.Libraries.fovcircle
	local launchHook
	local sticky = {}
	local held
	local SWITCH, IDLE, HOLD = 0.4, 0.75, 0.3

	local function stickTo(candidates)
		local now = tick()
		if now - (sticky.Clock or 0) > IDLE then
			sticky.Entity, sticky.Rival = nil, nil
		end
		sticky.Clock = now
		local top = candidates[1]
		local current = sticky.Entity
		if current and not table.find(candidates, current) then
			current = nil
		end
		if not current then
			sticky.Entity, sticky.Rival = top, nil
			return top
		end
		if top ~= current then
			if sticky.Rival ~= top then
				sticky.Rival, sticky.Since = top, now
			end
			if now - sticky.Since >= SWITCH then
				sticky.Entity, sticky.Rival = top, nil
				return top
			end
		else
			sticky.Rival = nil
		end
		return current
	end

	local function projectileChargeTime()
		local held = store.hand and store.hand.tool
		local itemMeta = held and bedwars.ItemMeta and bedwars.ItemMeta[held.Name]
		local source = itemMeta and (itemMeta.projectileSource or itemMeta.multiProjectileSource)
		if not source then return nil end
		return tonumber(source.maxStrengthChargeSec)
	end

	local function resolveProjectileAimbotPart(ent, requested, projectileType)
		local character = ent and ent.Character
		local root = ent and (ent.RootPart or ent.HumanoidRootPart) or character and character.PrimaryPart
		if not character then return root end
		local function first(...)
			for index = 1, select('#', ...) do
				local partName = select(index, ...)
				local part = partName and character:FindFirstChild(partName)
				if part and part:IsA('BasePart') then return part end
			end
			return root
		end
		if requested == 'Dynamic' then
			requested = isHeadshotDynamic(projectileType) and 'Head' or 'RootPart'
		end
		if requested == 'Head' then return first('Head') end
		if requested == 'Torso' then return first('UpperTorso', 'Torso', 'LowerTorso') end
		if requested == 'Left arm' then return first('LeftHand', 'LeftLowerArm', 'LeftUpperArm', 'Left Arm') end
		if requested == 'Right arm' then return first('RightHand', 'RightLowerArm', 'RightUpperArm', 'Right Arm') end
		if requested == 'Left leg' then return first('LeftFoot', 'LeftLowerLeg', 'LeftUpperLeg', 'Left Leg') end
		if requested == 'Right leg' then return first('RightFoot', 'RightLowerLeg', 'RightUpperLeg', 'Right Leg') end
		if requested == 'Random' then
			local available = {first('Head'), first('UpperTorso', 'Torso'), first('LeftHand', 'Left Arm'), first('RightHand', 'Right Arm'), first('LeftFoot', 'Left Leg'), first('RightFoot', 'Right Leg')}
			local filtered = {}
			for _, part in available do if part and part ~= root then table.insert(filtered, part) end end
			return #filtered > 0 and filtered[math.random(1, #filtered)] or root
		end
		return root
	end

	local function targetGravityOf(ent)
		local gravity = workspace.Gravity
		local character = ent.Character
		local balloons = character and character:GetAttribute('InflatedBalloons')
		if type(balloons) == 'number' and balloons > 0 then
			gravity = workspace.Gravity * (1 - (balloons >= 4 and 1.2 or balloons >= 3 and 1 or 0.975))
		end
		if ent.RootPart and ent.RootPart:FindFirstChild('rbxassetid://8200754399') then gravity = 6 end
		if ent.Player and ent.Player:GetAttribute('IsOwlTarget') then
			for _, owl in collectionService:GetTagged('Owl') do
				if owl:GetAttribute('Target') == ent.Player.UserId and owl:GetAttribute('Status') == 2 then
					gravity = 0
					break
				end
			end
		end
		return gravity
	end

	local function solveAimbotLaunch(origin, projmeta, projectileType, launch)
		local drawSpeed = type(launch) == 'table' and typeof(launch.initialVelocity) == 'Vector3' and launch.initialVelocity.Magnitude or nil
		local metaOk, meta = pcall(projmeta.getProjectileMeta, projmeta)
		meta = metaOk and meta or bedwars.ProjectileMeta[projectileType]
		if type(meta) ~= 'table' then return end
		local gravityMultiplier = tonumber(projmeta.gravityMultiplier) or 1
		if gravityMultiplier == 0 then gravityMultiplier = 1 end
		local gravity = (tonumber(meta.gravitationalAcceleration) or 196.2) * gravityMultiplier
		local fullSpeed = tonumber(meta.launchVelocity) or drawSpeed
		if not fullSpeed or fullSpeed <= 0 then return end
		local shootSpeed = drawSpeed and drawSpeed > 0 and drawSpeed or fullSpeed
		local solveSpeed = Aim.Enabled == false and fullSpeed or shootSpeed

		local function valuesFor(ent)
			local aimPart = resolveProjectileAimbotPart(ent, TargetPart.Value, projectileType)
			if not aimPart or not aimPart.Parent then return end
			local partAim = TargetPart.Value ~= 'Dynamic' or isHeadshotDynamic(projectileType)
			local targetPosition = aimPart.Position
			local targetVelocity = Vector3.zero
			local playerGravity = targetGravityOf(ent)
			local root = ent.RootPart
			if not root then return end
			local airborne = (ent.Humanoid and ent.Humanoid.FloorMaterial == Enum.Material.Air)
				or math.abs(root.AssemblyLinearVelocity.Y) > 0.01

			local function solve(position)
				local ok, aimPoint, _, travelTime = pcall(
					prediction.SolveTrajectory,
					origin, solveSpeed, gravity, position, targetVelocity, playerGravity,
					ent.HipHeight, ent.Jumping and 42.6 or nil, store.airRay, airborne,
					root.Position, root, nil, true, partAim
				)
				if ok and aimPoint and travelTime then return aimPoint, travelTime end
			end

			local aimPoint, travelTime = solve(targetPosition)
			if not aimPoint then return end

			local direction = CFrame.new(origin, aimPoint).LookVector
			return {Velocity = direction * shootSpeed, Time = travelTime, Player = ent}
		end

		local inCircle = circleLibrary and circleLibrary.ContainsEntity
		if not inCircle then return nil end
		local center = circleLibrary.Center()
		local candidates = {}
		for _, ent in entitylib.AllPosition({
			Part = 'RootPart',
			Range = Range.Value,
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Priority = Targets.Priority and Targets.Priority.Value,
			Wallcheck = Targets.Walls.Enabled,
			Origin = origin,
			Sort = sortmethods[Sort.Value]
		}) do
			if inCircle(ent, FOV.Value, center) then
				table.insert(candidates, ent)
				if #candidates >= 10 then break end
			end
		end

		local now = tick()
		local keep = stickTo(candidates)
		if keep then
			local ok, values = pcall(valuesFor, keep)
			if ok and values then
				held = {Values = values, Clock = now}
				return values
			end
			if held and held.Values.Player == keep and now - held.Clock < HOLD then
				return held.Values
			end
		end
		for _, ent in candidates do
			if ent ~= keep then
				local ok, values = pcall(valuesFor, ent)
				if ok and values then
					sticky.Entity, sticky.Rival = ent, nil
					held = {Values = values, Clock = now}
					return values
				end
			end
		end
		local last = held and held.Values.Player
		if last and now - held.Clock < HOLD and last.RootPart and last.RootPart.Parent then
			return held.Values
		end
		return nil
	end

	ProjectileAimbot = vape.Categories.Blatant:CreateModule({
		Name = 'ProjectileAimbot',
		ExtraText = function() return Sort.Value end,
		Function = function(callback)
			if callback then
				if not (bedwars.ProjectileLaunchHook and bedwars.ProjectileController) then
					notif('ProjectileAimbot', 'The projectile controller is unavailable.', 5, 'warning')
					task.defer(function()
						if ProjectileAimbot.Enabled then ProjectileAimbot:Toggle() end
					end)
					return
				end
				if vape.Modules.SilentAim and vape.Modules.SilentAim.Enabled then vape.Modules.SilentAim:Toggle() end
				launchHook = bedwars.ProjectileLaunchHook:Add('ProjectileAimbot', 12, function(nextLaunch, self, launchData, ...)
					local projmeta = launchData
					if AutoCharge.Enabled and type(projmeta) == 'table' and bedwars.ProjectileMeta[projmeta.projectile] then
						local fullCharge = projectileChargeTime()
						if fullCharge then
							projmeta.drawDurationSeconds = math.max(tonumber(projmeta.drawDurationSeconds) or 0, fullCharge)
							projmeta.velocityMultiplier = math.max(tonumber(projmeta.velocityMultiplier) or 0, 1)
						end
					end

					local worldmeta, launchOrigin, shootPosition = ...
					local launch = nextLaunch(self, launchData, ...)
					if not projmeta then return launch end
					local gamePosition = type(launch) == 'table' and typeof(launch.positionFrom) == 'Vector3' and launch.positionFrom or nil
					local base = gamePosition
						or (typeof(shootPosition) == 'Vector3' and shootPosition)
						or (typeof(launchOrigin) == 'Vector3' and launchOrigin)
						or (entitylib.isAlive and entitylib.character.RootPart.Position)
					if not base then return launch end
					local projectileType = tostring(projmeta.projectile or '')
					if projectileType == '' or ((not OtherProjectiles.Enabled) and not projectileType:find('arrow')) then return launch end
					local blacklistName = (projectileType == 'glue_trap' or projectileType == 'glue_projectile') and 'gloop' or projectileType
					if table.find(Blacklist.ListEnabled or {}, blacklistName) then return launch end

					local ok, solved = pcall(solveAimbotLaunch, base, projmeta, projectileType, launch)
					if not ok then
						if shared.VapeDeveloper then
							warn('[catvape] projectile aimbot solve failed: ' .. tostring(solved))
						end
						return launch
					end
					if type(solved) ~= 'table' then return launch end

					local projMeta = bedwars.ProjectileMeta[projectileType] or {}
					local answer = {}
					if type(launch) == 'table' then
						for key, value in pairs(launch) do
							answer[key] = value
						end
					end
					answer.initialVelocity = solved.Velocity
					if not gamePosition then
						answer.positionFrom = base
					end
					answer.deltaT = answer.deltaT or tonumber(projmeta.lifetimeSec) or tonumber(projMeta.lifetimeSec) or 7
					answer.gravitationalAcceleration = answer.gravitationalAcceleration or tonumber(projMeta.gravitationalAcceleration) or 196.2
					answer.drawDurationSeconds = answer.drawDurationSeconds or tonumber(projmeta.drawDurationSeconds) or 1
					store.hitchance.ProjectileAimbot = {
						Value = getHitChance(solved.Player, solved.Time),
						Clock = tick()
					}
					targetinfo.Targets[solved.Player] = tick() + 1
					return answer
				end)
				if ShowFOV.Enabled and circleLibrary and circleLibrary.New then
					fovCircle = circleLibrary.New({
						Name = 'PAFOVCircle',
						Parent = vape.gui,
						Visible = function()
							return ProjectileAimbot and ProjectileAimbot.Enabled and ShowFOV.Enabled
						end,
						Radius = function()
							return FOV.Value
						end,
						Colour = function()
							return Color3.fromHSV(fovColour.Hue, fovColour.Sat, fovColour.Value)
						end,
						Thickness = function()
							return fovThickness.Value
						end
					})
				end
				ProjectileAimbot:Clean(function()
					table.clear(sticky)
					held = nil
					if launchHook then launchHook(); launchHook = nil end
					if fovCircle then fovCircle:Destroy(); fovCircle = nil end
				end)
			elseif launchHook then
				launchHook()
				launchHook = nil
				if fovCircle then fovCircle:Destroy(); fovCircle = nil end
			end
		end,
		Tooltip = 'Silently aims your shots at enemies'
	})
	Targets = ProjectileAimbot:CreateTargets({
		Players = true,
		Walls = true
	})
	local methods = {'Distance', 'Damage'}
	for _, i in sortlist do
		if not table.find(methods, i) then
			table.insert(methods, i)
		end
	end
	Sort = ProjectileAimbot:CreateDropdown({
		Name = 'Target mode',
		List = methods,
		Default = 'Distance',
		Tooltip = TARGET_MODE_TOOLTIP
	})
	TargetPart = ProjectileAimbot:CreateDropdown({
		Name = 'Part',
		List = {'RootPart', 'Head', 'Torso', 'Left arm', 'Right arm', 'Left leg', 'Right leg', 'Random', 'Dynamic'},
		Tooltip = 'Where on the body shots aim'
	})
	FOV = ProjectileAimbot:CreateSlider({
		Name = 'FOV',
		Min = 1,
		Max = 1000,
		Default = 1000,
		Suffix = ' px',
		Tooltip = 'How far from your cursor a target can be'
	})
	Range = ProjectileAimbot:CreateSlider({
		Name = 'Range',
		Min = 30,
		Max = 1000,
		Default = 1000,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end,
		Tooltip = 'How far away a target can be'
	})
	ShowFOV = ProjectileAimbot:CreateGroup({
		Name = 'FOV Circle',
		Tooltip = 'Shows the range around your cursor',
		Function = function(callback)
			if not ProjectileAimbot.Enabled then return end
			if fovCircle then fovCircle:Destroy(); fovCircle = nil end
			if callback and circleLibrary and circleLibrary.New then
				fovCircle = circleLibrary.New({
					Name = 'PAFOVCircle',
					Parent = vape.gui,
					Visible = function()
						return ProjectileAimbot and ProjectileAimbot.Enabled and ShowFOV.Enabled
					end,
					Radius = function()
						return FOV.Value
					end,
					Colour = function()
						return Color3.fromHSV(fovColour.Hue, fovColour.Sat, fovColour.Value)
					end,
					Thickness = function()
						return fovThickness.Value
					end
				})
			end
		end
	})
	fovColour = ShowFOV:CreateColorSlider({
		Name = 'Circle colour',
		Darker = true
	})
	fovThickness = ShowFOV:CreateSlider({
		Name = 'Circle thickness',
		Min = 1,
		Max = 8,
		Default = 1,
		Darker = true,
		Tooltip = 'Width of the ring in pixels'
	})
	AutoCharge = ProjectileAimbot:CreateGroup({
		Name = 'Auto Charge',
		Function = function(callback)
			if Aim and Aim.Object then
			end
		end,
		Default = true,
		Tooltip = 'Fires bows at full charge however long you draw'
	})
	Aim = AutoCharge:CreateToggle({
		Name = 'Aim change',
		Default = true,
		Darker = true,
		Tooltip = 'Matches your shot\'s path to its charge'
	})
	OtherProjectiles = ProjectileAimbot:CreateToggle({
		Name = 'Other Projectiles',
		Default = true
	})
	Blacklist = ProjectileAimbot:CreateTextList({
		Name = 'Blacklist',
		Default = {'telepearl'}
	})
end)

-- ===== Blatant/RecoveryTP.lua =====
run(function()
    local RecoveryTP
    local HealthThreshold
    local TeleportHeight
    local GroundTime
    local PlayerCheck
    local groundedSince = 0
	local trackedCharacter
	local recovered = false

	local function validCharacter()
		local character = entitylib.character
		if not entitylib.isAlive or not character or not character.Character or not character.Character.Parent then return end
		local humanoid, root = character.Humanoid, character.RootPart
		if not humanoid or humanoid.Health <= 0 or not root or not root.Parent then return end
		return character, humanoid, root
	end

	local function playerNearby(origin)
		local list = type(entitylib.List) == 'table' and entitylib.List or {}
		for _, ent in list do
			local root = ent and ent.RootPart
			local player = ent and ent.Player
			if player and player ~= lplr and player.Parent == playersService and root and root.Parent
				and (not ent.Health or ent.Health > 0) and (root.Position - origin).Magnitude <= 50 then
				return true
			end
		end
		return false
	end

    RecoveryTP = vape.Categories.Blatant:CreateModule({
        Name = 'RecoveryTP',
        Function = function(callback)
			groundedSince, trackedCharacter, recovered = 0, nil, false
			if not callback then return end
			RecoveryTP:Clean(lplr.CharacterAdded:Connect(function(character)
				trackedCharacter, groundedSince, recovered = character, 0, false
			end))
            RecoveryTP:Clean(runService.PostSimulation:Connect(function()
				if not RecoveryTP.Enabled then return end
				local character, humanoid, root = validCharacter()
				if not character then groundedSince, recovered = 0, false return end
				if trackedCharacter ~= character.Character then
					trackedCharacter, groundedSince, recovered = character.Character, 0, false
				end
				if humanoid.Health >= HealthThreshold.Value then groundedSince, recovered = 0, false return end
				if recovered then return end
				local ownsRoot = false
				pcall(function() ownsRoot = isnetworkowner(root) end)
				if not ownsRoot then groundedSince = 0 return end
				if PlayerCheck.Enabled and not playerNearby(root.Position) then groundedSince = 0 return end
				if humanoid.FloorMaterial == Enum.Material.Air then groundedSince = 0 return end
                local now = tick()
                if groundedSince == 0 then groundedSince = now return end
				if now - groundedSince < GroundTime.Value then return end
				groundedSince, recovered = 0, true
				root.CFrame = CFrame.new(root.Position.X, TeleportHeight.Value, root.Position.Z) * root.CFrame.Rotation
                root.AssemblyLinearVelocity = Vector3.zero
                humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
            end))
        end,
        Tooltip = 'Teleports you to a safe height when your health is critical'
    })
    HealthThreshold = RecoveryTP:CreateSlider({Name = 'Health threshold', Min = 1, Max = 99, Default = 35, Suffix = ' HP'})
    TeleportHeight = RecoveryTP:CreateSlider({Name = 'Safe height', Min = 80, Max = 300, Default = 180, Suffix = ' studs'})
    GroundTime = RecoveryTP:CreateSlider({Name = 'Ground time', Min = 0.1, Max = 3, Default = 0.5, Decimal = 100, Suffix = ' seconds'})
    PlayerCheck = RecoveryTP:CreateToggle({
        Name = 'Player check',
        Tooltip = 'Only teleports with a player nearby'
    })
end)

-- ===== Blatant/Speed.lua =====
run(function()
	local Speed
	local Mode
	local Value
	local WallCheck
	local AutoJump
	local AlwaysJump
	local SpeedEffect
	local Modifier = {}
	local RayCheck: RaycastParams = RaycastParams.new()
	RayCheck.RespectCanCollide = true
	local FilterFor
	local SavedImpulse

	local function hasSpeedEffect(): boolean
	    local Character = lplr.Character
	    local Expiry = Character and Character:GetAttribute("StatusEffect_speed")
	    return type(Expiry) == "number" and Expiry > workspace:GetServerTimeNow()
	end
	
	Speed = vape.Categories.Blatant:CreateModule({
	    Name = "Speed",
	    Function = function(Callback: boolean)
	        local Blatant: boolean = Callback and Mode.Value == "Blatant"
	        local Zephyr = vape.Kits and vape.Kits.Modules.ZephyrDisabler or vape.Modules.ZephyrDisabler
	        local ZephyrActive: boolean = Zephyr ~= nil and Zephyr.Enabled == true
	        frictionTable.Speed = Blatant or nil
	        updateVelocity()
	        pcall(function()
	            debug.setconstant(bedwars.WindWalkerController.updateSpeed, 7, (Blatant or ZephyrActive) and "constantSpeedMultiplier" or "moveSpeedMultiplier")
	        end)
	        pcall(function()
	            local Controller = bedwars.StatefulEntityKnockbackController
	            if Blatant or ZephyrActive then
	                if SavedImpulse == nil and Controller.lastImpulseTime ~= math.huge then
	                    SavedImpulse = Controller.lastImpulseTime
	                end
	                Controller.lastImpulseTime = math.huge
	            elseif Controller.lastImpulseTime == math.huge then
	                Controller.lastImpulseTime = SavedImpulse or 0
	                SavedImpulse = nil
	            end
	        end)
	        if not Callback and entitylib.isAlive then
	            local Root = entitylib.character.RootPart
	            Root.AssemblyLinearVelocity = Vector3.new(0, Root.AssemblyLinearVelocity.Y, 0)
	        end

	        if Callback then
	            local EngineSpeed = store.engineSpeed(Speed)
	            if not Blatant then
	                Modifier.moveSpeedMultiplier = Value.Value / 20
	                local Handle = bedwars.SprintController:getMovementStatusModifier():addModifier(Modifier)
	                Speed:Clean(function()
	                    Handle:Destroy()
	                end)
	            end

	            Speed:Clean(runService.PreSimulation:Connect(function(Delta: number)
	                if Blatant then
	                    bedwars.StatefulEntityKnockbackController.lastImpulseTime = math.huge
	                end
	                if entitylib.isAlive and not (Fly and Fly.Enabled) and not (LongJump and LongJump.Enabled) and isnetworkowner(entitylib.character.RootPart) then
	                    local State: Enum.HumanoidStateType = entitylib.character.Humanoid:GetState()
	                    if State == Enum.HumanoidStateType.Climbing then
	                        return
	                    end

	                    local MoveDirection: Vector3 = AntiFallDirection or entitylib.character.Humanoid.MoveDirection
	                    if Blatant then
	                        local Root, CurrentSpeed = entitylib.character.RootPart, getSpeed()
	                        local Target: number = (SpeedEffect.Enabled and hasSpeedEffect()) and 34.5 or Value.Value
	                        local Destination: Vector3 = MoveDirection * math.max(Target - EngineSpeed(), 0) * Delta
	                        if WallCheck.Enabled and Destination.Magnitude > 0.001 then
	                            if FilterFor ~= lplr.Character then
	                                FilterFor = lplr.Character
	                                RayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera}
	                            end
	                            if RayCheck.CollisionGroup ~= Root.CollisionGroup then
	                                RayCheck.CollisionGroup = Root.CollisionGroup
	                            end
	                            local WallRay: RaycastResult? = workspace:Raycast(Root.Position, Destination, RayCheck)
	                            if WallRay then
	                                Destination = (WallRay.Position + WallRay.Normal) - Root.Position
	                            end
	                        end

	                        Root.CFrame += Destination
	                        Root.AssemblyLinearVelocity = (MoveDirection * CurrentSpeed) + Vector3.new(0, Root.AssemblyLinearVelocity.Y, 0)
	                    end
	                    if AutoJump.Enabled and (State == Enum.HumanoidStateType.Running or State == Enum.HumanoidStateType.Landed) and MoveDirection ~= Vector3.zero and (store.attacking or AlwaysJump.Enabled) then
	                        entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
	                    end
	                end
	            end))
	        end
	    end,
	    ExtraText = function()
	        return Mode.Value
	    end,
	    Tooltip = "Increases your movement speed"
	})
	
	Mode = Speed:CreateDropdown({
	    Name = "Mode",
	    List = {"Blatant", "Legit"},
	    Function = function(Val: string)
	        if WallCheck then
	            WallCheck.Object.Visible = Val == "Blatant"
	        end
	        if SpeedEffect then
	            SpeedEffect.Object.Visible = Val == "Blatant"
	        end
	        if Speed.Enabled then
	            Speed:Toggle()
	            Speed:Toggle()
	        end
	    end,
	    Default = "Blatant",
	    Tooltip = 'Blatant - moves you forward\nLegit - raises your sprint speed'
	})
	Value = Speed:CreateSlider({
	    Name = "Speed",
	    Function = function(Val: number)
	        if Speed.Enabled and Mode.Value == "Legit" then
	            Modifier.moveSpeedMultiplier = Val / 20
	            bedwars.SprintController:getMovementStatusModifier():updateModifiers()
	        end
	    end,
	    Min = 1,
	    Max = 23,
	    Default = 23,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end
	})
	SpeedEffect = Speed:CreateToggle({
	    Name = "Speed Effect",
	    Tooltip = 'Moves faster while a speed effect is active'
	})
	WallCheck = Speed:CreateToggle({
	    Name = "Wall Check",
	    Default = true
	})
	AutoJump = Speed:CreateGroup({
	    Name = "AutoJump"
	})
	AlwaysJump = AutoJump:CreateToggle({
	    Name = "Always Jump"
	})
end)

-- ===== Blatant/Spider.lua =====
run(function()
	local Spider
	local SpiderShift = false
    local Mode
    local Animation
    local Value
    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    local Active, Truss, Loaded
    local dirty, lastCharacter, lastTruss = true

    local climbAnimation = Instance.new('Animation')
    climbAnimation.AnimationId = 'rbxassetid://11344417710'

    Spider = vape.Categories.Blatant:CreateModule({
	Name = 'Spider',
	ExtraText = function() return Mode.Value end,
	Function = function(callback)
		if callback then
			if Truss then
				Truss.Parent = gameCamera
			end

			dirty = true
			Spider:Clean(entitylib.Events.EntityAdded:Connect(function() dirty = true end))
			Spider:Clean(entitylib.Events.EntityRemoved:Connect(function() dirty = true end))
			Spider:Clean(runService.PreSimulation:Connect(function(dt)
				if entitylib.isAlive then
					local root = entitylib.character.RootPart
					if dirty or lastCharacter ~= lplr.Character or lastTruss ~= Truss then
						dirty, lastCharacter, lastTruss = false, lplr.Character, Truss
						local chars = { gameCamera, lplr.Character, Truss }
						for _, v in entitylib.List do
							table.insert(chars, v.Character)
						end
						rayCheck.FilterDescendantsInstances = chars
					end
					SpiderShift = inputService:IsKeyDown(Enum.KeyCode.LeftShift)
					rayCheck.CollisionGroup = root.CollisionGroup

                        local dir, stop = entitylib.character.Humanoid.MoveDirection, false
                        if dir.Magnitude <= 0 then
                            dir, stop = root.CFrame.LookVector, true
                        end
                        local vec = dir * 2.5
                        local ray = workspace:Raycast(
                            root.Position - Vector3.new(0, entitylib.character.HipHeight - 0.5, 0),
                            vec,
                            rayCheck
                        )
                        if Active then
                            if not Loaded and Animation.Enabled then
                                Loaded = entitylib.character.Humanoid:LoadAnimation(climbAnimation)
                                Loaded:Play()
                            end
                            if Loaded then
                                Loaded:AdjustSpeed((not stop) and 2 or 0)
                            end
                            
                            
                            
                            
                            
                            if not ray and not stop then
                                root.Velocity = Vector3.new(root.Velocity.X, 0, root.Velocity.Z)
                            end
                        end

                        Active = ray
                        if Active and ray.Normal.Y == 0 and not stop then
                            if not (vape.Modules.NoClip and vape.Modules.NoClip.Enabled) or not SpiderShift then
                                if Animation.Enabled then
                                    entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Climbing)
                                end

                                root.Velocity *= Vector3.new(1, 0, 1)
                                if Mode.Value == 'CFrame' then
                                    root.CFrame += Vector3.new(0, Value.Value * dt, 0)
                                elseif Mode.Value == 'Impulse' then
                                    root:ApplyImpulse(Vector3.new(0, Value.Value, 0) * root.AssemblyMass)
                                else
                                    root.Velocity += Vector3.new(0, Value.Value, 0)
                                end
                            end
                        elseif not Active then
                            if Loaded then
                                Loaded:Stop()
                            end
                            Loaded = nil
                        end
                    else
                        if Loaded then
                            Loaded:Stop()
                        end
                        Loaded = nil
				end
			end))
		else
			if Truss then
				Truss.Parent = nil
			end
                if Loaded then
                    Loaded:Stop()
                end
                Loaded = nil
			SpiderShift = false
		end
	end,
	Tooltip = 'Lets you climb walls. Hold Shift to pass through with NoClip',
    })
    Mode = Spider:CreateDropdown({
	Name = 'Mode',
	List = {'Velocity', 'Impulse', 'CFrame'},
	Function = function(val)
		Value.Object.Visible = val ~= 'Part'
            if Truss then
			Truss:Destroy()
			Truss = nil
		end
		if val == 'Part' then
			Truss = Instance.new('TrussPart')
			Truss.Size = Vector3.new(2, 2, 2)
			Truss.Transparency = 1
			Truss.Anchored = true
			Truss.Parent = Spider.Enabled and gameCamera or nil
		end
	end,
	Tooltip = 'How you are moved up',
    })
    Value = Spider:CreateSlider({
	Name = 'Speed',
	Min = 0,
	Max = 100,
	Default = 30,
	Darker = true,
	Suffix = function(val)
		return val == 1 and 'stud' or 'studs'
	end,
    })
    Animation = Spider:CreateToggle({
        Name = 'Use bedwars climbing',
        Tooltip = 'Plays the kit climbing animation'
    })
end)

-- ===== Blatant/TPDown.lua =====
run(function()
	local TPDown
	local Delay
	local Touchdown
	local Return
	local ShowUI
	local AirOnly
	
	local RayParams: RaycastParams = RaycastParams.new()
	RayParams.RespectCanCollide = true
	
	local Bar: Frame? = nil
	local Fill: Frame? = nil
	
	local function RemoveBar()
	    if Bar then
	        Bar:Destroy()
	        Bar, Fill = nil, nil
	    end
	end
	
	local function CreateBar()
	    RemoveBar()
	
	    Bar = Instance.new("Frame")
	    Bar.AnchorPoint = Vector2.new(0.5, 0)
	    Bar.BackgroundColor3 = Color3.new()
	    Bar.BackgroundTransparency = 0.5
	    Bar.BorderSizePixel = 0
	    Bar.Position = UDim2.new(0.5, 0, 0.5, 150)
	    Bar.Size = UDim2.fromOffset(160, 6)
	    Bar.Visible = false
	    Bar.Parent = vape.gui
	    local Corner: UICorner = Instance.new("UICorner")
	    Corner.CornerRadius = UDim.new(1, 0)
	    Corner.Parent = Bar
	
	    Fill = Instance.new("Frame")
	    Fill.BorderSizePixel = 0
	    Fill.Size = UDim2.fromScale(0, 1)
	    Fill.Parent = Bar
	    Corner:Clone().Parent = Fill
	end
	
	local function HandledElsewhere(): (boolean, any)
	    for _, Name: string in {"Fly", "InfiniteJump"} do
	        local Module = vape.Modules[Name]
	        local Option = Module and Module.Options["TP Down"]
	        if Module and Module.Enabled and Option and Option.Enabled then
	            return true, Module
	        end
	    end
	    return false, nil
	end
	
	local function UpdateBar(AirTime: number, Airborne: boolean, Span: number?)
	    if not Bar or not Fill then
	        return
	    end
	
	    Bar.Visible = TPDown.Enabled and entitylib.isAlive and (Airborne or not AirOnly.Enabled)
	    Fill.BackgroundColor3 = Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value)
	    Fill.Size = UDim2.fromScale(math.clamp(AirTime / (Span or Delay.Value), 0, 1), 1)
	end
	
	TPDown = vape.Categories.Blatant:CreateModule({
	    Name = "TPDown",
	    Function = function(Callback: boolean)
	        TPDown.PullIn = nil
	        if Callback then
	            local OldY: number? = nil
	            local ReturnTick: number = 0
	            local NextPull: number = 0
	
	            TPDown:Clean(runService.PreSimulation:Connect(function()
	                local Handled: boolean, Handler = HandledElsewhere()
	                if not entitylib.isAlive or vape.MovementOwner or Handled then
	                    OldY = nil
	                    TPDown.PullIn = nil
	                    if Handled and entitylib.isAlive and not vape.MovementOwner then
	                        local InAir: boolean = entitylib.character.Humanoid.FloorMaterial == Enum.Material.Air
	                        local Left: number? = Handler.PullIn
	                        if Handler.Name ~= "Fly" then
	                            Left = InAir and (2 - (tick() - (entitylib.character.AirTime or tick()))) or 2
	                        end
	                        UpdateBar(Left and (2 - Left) or 0, InAir, 2)
	                    else
	                        UpdateBar(0, false)
	                    end
	                    return
	                end
	
	                local Root: BasePart = entitylib.character.RootPart
	                local Airborne: boolean = entitylib.character.Humanoid.FloorMaterial == Enum.Material.Air
	                local AirTime: number = Airborne and (tick() - (entitylib.character.AirTime or tick())) or 0
	
	                if ReturnTick > tick() then
	                    Root.AssemblyLinearVelocity = Vector3.new(Root.AssemblyLinearVelocity.X, 0, Root.AssemblyLinearVelocity.Z)
	                    UpdateBar(0, Airborne)
	                    return
	                end
	
	                if OldY then
	                    Root.CFrame = CFrame.lookAlong(Vector3.new(Root.Position.X, OldY, Root.Position.Z), Root.CFrame.LookVector)
	                    entitylib.character.AirTime = tick()
	                    OldY = nil
	                    UpdateBar(0, true)
	                    return
	                end
	
	                if vape.FloatExempt then
	                    TPDown.PullIn = nil
	                    UpdateBar(0, Airborne)
	                    return
	                end

	                TPDown.PullIn = Airborne and (Delay.Value - AirTime) or nil
	                UpdateBar(AirTime, Airborne)
	
	                if Airborne and AirTime > Delay.Value and NextPull < tick() and isnetworkowner(Root) then
	                    RayParams.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiFallPart}
	                    RayParams.CollisionGroup = Root.CollisionGroup
	                    local Ground: RaycastResult? = workspace:Raycast(Root.Position, Vector3.new(0, -1000, 0), RayParams)
	                    if Ground then
	                        OldY = Return.Enabled and Root.Position.Y or nil
	                        ReturnTick = tick() + Touchdown.Value
	                        NextPull = ReturnTick + 0.2
	                        Root.CFrame = CFrame.lookAlong(Vector3.new(Root.Position.X, Ground.Position.Y + entitylib.character.HipHeight, Root.Position.Z), Root.CFrame.LookVector)
	                        Root.AssemblyLinearVelocity = Vector3.new(Root.AssemblyLinearVelocity.X, 0, Root.AssemblyLinearVelocity.Z)
	                    end
	                end
	            end))
	        else
	            UpdateBar(0, false)
	        end
	    end,
	    Tooltip = 'Touches the ground when you have been in the air too long'
	})
	
	Delay = TPDown:CreateSlider({
	    Name = "Air Time",
	    Min = 0.5,
	    Max = 3,
	    Default = 1.7,
	    Decimal = 10,
	    Suffix = function(Val: number)
	        return Val == 1 and "second" or "seconds"
	    end,
	    Tooltip = "How long you can stay in the air before it pulls you down"
	})
	Touchdown = TPDown:CreateSlider({
	    Name = "Touchdown",
	    Min = 0.05,
	    Max = 0.5,
	    Default = 0.11,
	    Decimal = 100,
	    Suffix = function(Val: number)
	        return Val == 1 and "second" or "seconds"
	    end,
	    Tooltip = "How long you stay on the ground before going back up"
	})
	Return = TPDown:CreateToggle({
	    Name = "Return",
	    Default = true,
	    Tooltip = 'Teleports you back up after being pulled down'
	})
	ShowUI = TPDown:CreateGroup({
	    Name = "Show UI",
	    Function = function(Callback: boolean)
	
	        if Callback then
	            local Other = vape.Modules.Fly
	            Other = Other and Other.Options["Show UI"]
	            if Other and Other.Enabled then
	                Other:Toggle()
	            end
	            CreateBar()
	        else
	            RemoveBar()
	        end
	    end,
	    Tooltip = 'Shows a bar that fills up until you are pulled down'
	})
	AirOnly = ShowUI:CreateToggle({
	    Name = "Air Only",
	    Darker = true,
	    Tooltip = "Only shows the bar while you are in the air"
	})
	vape:Clean(RemoveBar)
end)

-- ===== Combat/AimAssist.lua =====
run(function()
	local AimAssist
	local AimMode
	local Mode
	local Targets
	local Sort
	local AimPart
	local AimSpeed
	local Smoothness
	local Shake
	local Distance
	local AngleSlider
	local StrafeIncrease
	local BlockBreak
	local KillauraTarget
	local ClickAim
	local Mouse
	local Limit
	
	local rng = Random.new()
	local cache = setmetatable({}, {__mode = 'k'})
	
	local function getAim(ent)
		if AimPart.Value == 'Closest' then
			if not cache[ent.Character] then
				cache[ent.Character] = ent.Character:GetChildren()
			end
			local localPosition, magnitude, part = inputService.TouchEnabled and gameCamera.ViewportSize / 2 or inputService:GetMouseLocation(), 9e9, nil
			for _, v in cache[ent.Character] do
				if v and v.Parent and v:IsA('BasePart') then
					local position, vis = gameCamera:WorldToViewportPoint(v.Position)
					if vis then
						local mag = (localPosition - Vector2.new(position.X, position.Y)).Magnitude
						if mag < magnitude then
							magnitude = mag
							part = v
						end
					end
				end
			end
			if part then
				return part.Position
			end
		end
		return ent.RootPart.Position
	end
	
	local started, lasttarget, nextsearch = 0, nil, 0
	local aimfuncs = {
		Simple = function(localcframe, ent, fps)
			local speed = (AimSpeed.Value + (StrafeIncrease.Enabled and (inputService:IsKeyDown(Enum.KeyCode.A) or inputService:IsKeyDown(Enum.KeyCode.D)) and 10 or 0)) / Smoothness.Value
			return localcframe:Lerp(CFrame.lookAt(localcframe.p, getAim(ent) + Vector3.new((rng:NextNumber() - 0.5) * Shake.Value * fps, (rng:NextNumber() - 0.5) * Shake.Value * fps, (rng:NextNumber() - 0.5) * Shake.Value * fps)), speed * fps), speed
		end,
		Adaptive = function(localcframe, ent, fps)
			local t = math.min(tick() - started, 1)
			local prog = t < 0.5 and 4 * t * t * t or 1 - math.pow(-2 * t + 2, 3) / 2
			local speed = ((AimSpeed.Value * 0.1 * prog) + (1 - prog) + (StrafeIncrease.Enabled and (inputService:IsKeyDown(Enum.KeyCode.A) or inputService:IsKeyDown(Enum.KeyCode.D)) and 10 or 5)) / Smoothness.Value
			return localcframe:Lerp(CFrame.lookAt(localcframe.p, getAim(ent) + Vector3.new((rng:NextNumber() - 0.5) * Shake.Value * fps, (rng:NextNumber() - 0.5) * Shake.Value * fps, (rng:NextNumber() - 0.5) * Shake.Value * fps)), speed * fps), speed
		end
	}
	
	AimAssist = vape.Categories.Combat:CreateModule({
		Name = 'AimAssist',
		ExtraText = function() return Mode.Value end,
		Function = function(callback)
			if callback then
				local rotate = 0
				AimAssist:Clean(runService.PostSimulation:Connect(function(dt)
					if entitylib.isAlive then
						entitylib.character.Humanoid.AutoRotate = tick() > rotate
	
						local blocked = Mouse.Enabled and not inputService:IsMouseButtonPressed(0) and (tick() - bedwars.SwordController.lastSwing) > 0.15
						blocked = blocked or (ClickAim.Enabled and (tick() - bedwars.SwordController.lastSwing) > 0.3)
						blocked = blocked or (BlockBreak.Enabled and (tick() - store.lastHit) < 0.3)
						blocked = blocked or (Limit.Enabled and store.hand.toolType ~= 'sword')
	
						local ent
						if not blocked then
							if entitylib.isAlive and lasttarget and lasttarget.Character and lasttarget.Character.Parent and lasttarget.RootPart and lasttarget.RootPart.Parent and lasttarget.Targetable and entitylib.isVulnerable(lasttarget) and (entitylib.character.RootPart.Position - lasttarget.RootPart.Position).Magnitude <= Distance.Value and not (Targets.Walls.Enabled and entitylib.Wallcheck(entitylib.character.RootPart.Position, lasttarget.RootPart.Position, Targets.Walls.Enabled, lasttarget)) and tick() < nextsearch then
								ent = lasttarget
							else
								local target = store.KillauraTarget
								ent = KillauraTarget.Enabled and entitylib.isAlive and target and target.Character and target.Character.Parent and target.RootPart and target.RootPart.Parent and target.Targetable and entitylib.isVulnerable(target) and (entitylib.character.RootPart.Position - target.RootPart.Position).Magnitude <= Distance.Value and not (Targets.Walls.Enabled and entitylib.Wallcheck(entitylib.character.RootPart.Position, target.RootPart.Position, Targets.Walls.Enabled, target)) and target or entitylib.EntityPosition({
									Range = Distance.Value,
									Part = 'RootPart',
									Wallcheck = Targets.Walls.Enabled,
									Players = Targets.Players.Enabled,
									NPCs = Targets.NPCs.Enabled,
									Priority = Targets.Priority.Value,
									Sort = sortmethods[Sort.Value]
								})
								if ent ~= lasttarget then
									started = tick()
								end
								lasttarget = ent
								nextsearch = tick() + 1
							end
						end
	
						if ent then
							local root = entitylib.character.RootPart
							local delta = (ent.RootPart.Position - root.Position)
							local localfacing = root.CFrame.LookVector * Vector3.new(1, 0, 1)
							local horizontal = delta * Vector3.new(1, 0, 1)
							local angle = localfacing.Magnitude > 0 and horizontal.Magnitude > 0 and math.acos(math.clamp(localfacing.Unit:Dot(horizontal.Unit), -1, 1)) or 0
							if angle >= (math.rad(AngleSlider.Value) / 2) then
								return
							end
							targetinfo.Targets[ent] = tick() + 1
	
							local firstPerson = entitylib.character.Head.LocalTransparencyModifier == 1
							local perspective = AimMode.Value
							if perspective == 'Mouse' then
								local cframe, speed = aimfuncs[Mode.Value](gameCamera.CFrame, ent, dt)
								local viewport = gameCamera:WorldToViewportPoint(cframe.Position)
								local pos = (Vector2.new(viewport.X, viewport.Y) - inputService:GetMouseLocation()) * (speed / 15)
								mousemoverel(pos.X, pos.Y)
							elseif perspective == 'First person' or (perspective == 'Dynamic' and firstPerson) then
								if not firstPerson then return end
								local cframe = aimfuncs[Mode.Value](gameCamera.CFrame, ent, dt)
								gameCamera.CFrame = cframe
							elseif perspective == 'Third person' or (perspective == 'Dynamic' and not firstPerson) then
								if firstPerson then return end
								local cframe = aimfuncs[Mode.Value](root.CFrame, ent, dt)
								local direction = cframe.LookVector * Vector3.new(1, 0, 1)
								if direction.Magnitude > 0 then
									entitylib.character.Humanoid.AutoRotate = false
									root.CFrame = CFrame.lookAlong(root.Position, direction)
									rotate = tick() + 0.1
								end
							end
						end
					else
						lasttarget = nil
					end
				end))
			else
				lasttarget = nil
				if entitylib.isAlive then
					entitylib.character.Humanoid.AutoRotate = true
				end
			end
		end,
		Tooltip = 'Smoothly aims at the closest target while holding a sword'
	})
	Targets = AimAssist:CreateTargets({
		Players = true,
		Walls = true
	})
	
	AimMode = AimAssist:CreateDropdown({
		Name = 'Aim perspective',
		Tooltip = 'How your aim is moved: camera, character, mouse or picked by your view',
		List = {'First person', 'Third person', 'Dynamic'},
		Default = 'First person'
	})
	Mode = AimAssist:CreateDropdown({
		Name = 'Mode',
		List = {'Simple', 'Adaptive'},
		Tooltip = 'Simple - smooth aiming\nAdaptive - tracks targets more closely',
		Default = 'Simple'
	})
	local methods = {'Angle', 'Damage', 'Distance'}
	for _, v in sortlist do
		if not table.find(methods, v) then
			table.insert(methods, v)
		end
	end
	ClickAim = AimAssist:CreateToggle({
		Name = 'Click aim',
		Default = true
	})
	Mouse = AimAssist:CreateToggle({Name = 'Require mouse down'})
	StrafeIncrease = AimAssist:CreateToggle({Name = 'Strafe increase'})
	BlockBreak = AimAssist:CreateToggle({Name = 'Check block break'})
	KillauraTarget = AimAssist:CreateToggle({Name = 'Use killaura target'})
	AimSpeed = AimAssist:CreateSlider({
		Name = 'Aim speed',
		Min = 1,
		Max = 20,
		Default = 6
	})
	Smoothness = AimAssist:CreateSlider({
		Name = 'Smoothness',
		Min = 1,
		Max = 20,
		Default = 1,
		Decimal = 10,
		Tooltip = 'Softens the aim, 1 leaves it unchanged'
	})
	Distance = AimAssist:CreateSlider({
		Name = 'Distance',
		Min = 1,
		Max = 30,
		Default = 30,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end
	})
	Shake = AimAssist:CreateSlider({
		Name = 'Shake',
		Min = 0,
		Max = 100,
		Default = 0,
		Tooltip = 'Adds random jitter to look more human'
	})
	AngleSlider = AimAssist:CreateSlider({
		Name = 'Max angle',
		Min = 1,
		Max = 360,
		Default = 70
	})
	Limit = AimAssist:CreateToggle({
		Name = 'Limit to items',
		Tooltip = 'Only works while holding the item it uses'
	})
	Sort = AimAssist:CreateDropdown({
		Name = 'Target mode',
		List = methods,
		Default = 'Angle',
		Tooltip = TARGET_MODE_TOOLTIP
	})
	AimPart = AimAssist:CreateDropdown({
		Name = 'Target area',
		List = {'Center', 'Closest'},
		Default = 'Center'
	})
end)

-- ===== Combat/AutoClicker.lua =====
run(function()
	local AutoClicker
	local Attack
	local CPS
	local Place
	local Wool
	local Debug
	local BlockCPS = {}
	local held = false
	local nextPlace, nextClick = 0, 0
	local placeGap
	local LOG = 'ElevateV4/profiles/autoclickerlog.txt'
	local logBuffer, logStart, logLines, lastFlush = nil, 0, 0, 0
	local lastSeenPlace, lastOwnPlace, lastHitSeen = nil, 0, nil
	local hitOld, hitHook
	local logLine, vec

	local function isCasting()
		local casting = lplr:GetAttribute('IsCasting')
		return casting and casting ~= 0 and casting ~= ''
	end

	local function canSwing()
		if type(bedwars.SwordController.getSwordSwingDisabled) ~= 'function' or bedwars.SwordController:getSwordSwingDisabled() or isCasting() then
			return false
		end

		local itemmeta = store.hand and store.hand.tool and bedwars.ItemMeta[store.hand.tool.Name]
		return itemmeta ~= nil and itemmeta.sword ~= nil and itemmeta.sword.chargedAttack == nil
	end

	local function canPlace()
		local controller = bedwars.BlockPlacementController
		return controller ~= nil and not controller.disabled and not isCasting()
	end

	local function getWoolBaseCps()
		if Wool.Enabled and store.hand and store.hand.tool then
			return store.hand.tool.Name:find('wool_') ~= nil
		end
		return not Wool.Enabled
	end

	local function placeInterval()
		local cps = BlockCPS:GetRandomValue()
		return math.max(1 / math.max(cps, 0.001), 1 / (bedwars.SharedConstants.BLOCK_PLACE_CPS or 12))
	end

	local function clickInterval()
		return 1 / math.max(CPS:GetRandomValue(), 0.001)
	end

	local function canClickBlock()
		if store.hand.toolType ~= 'block' or not Place.Enabled then return false end
		if not getWoolBaseCps() then return false end
		local blockPlacer = bedwars.BlockPlacementController.blockPlacer
		if not blockPlacer or not canPlace() then return false end
		return (workspace:GetServerTimeNow() - (bedwars.BlockCpsController.lastPlaceTimestamp or 0)) >= ((1 / (bedwars.SharedConstants.BLOCK_PLACE_CPS or 12)) * 0.5)
	end

	local function callAutoBridge(blockPlacer)
		task.spawn(function()
			pcall(function()
				local controller = bedwars.KnockbackController
				local sinceKnockback = controller and workspace:GetServerTimeNow() - controller:getLastKnockbackTime() or 0
				blockPlacer:autoBridge(sinceKnockback >= 0.2)
			end)
		end)
	end

	local function placeThroughCrosshair(blockPlacer)
		local selector = blockPlacer.clientManager and blockPlacer.clientManager:getBlockSelector()
		local mouseinfo = selector and selector:getMouseInfo(0)
		if mouseinfo and mouseinfo.placementPosition == mouseinfo.placementPosition then
			lastOwnPlace = tick()
			if logBuffer then
				local cell = mouseinfo.placementPosition
				task.spawn(function()
					local ok, res = pcall(blockPlacer.placeBlock, blockPlacer, cell, mouseinfo)
					logLine(string.format('placeBlock %s -> %s %s', vec(cell), tostring(ok), tostring(res)))
				end)
			else
				task.spawn(blockPlacer.placeBlock, blockPlacer, mouseinfo.placementPosition, mouseinfo)
			end
			return true
		end
		return false
	end

	local function placeSafelyDownwards(blockPlacer)
		if type(blockPlacer.autoBridge) ~= 'function' then return end
		local humanoid = entitylib.isAlive and entitylib.character and entitylib.character.Humanoid
		if not humanoid or humanoid.MoveDirection.Magnitude <= 0.1 then return end
		callAutoBridge(blockPlacer)
	end

	local function placeBlock()
		local blockPlacer = bedwars.BlockPlacementController.blockPlacer
		if not blockPlacer then return false end

		if inputService.TouchEnabled and type(blockPlacer.autoBridge) == 'function' then
			callAutoBridge(blockPlacer)
			return true
		end

		if placeThroughCrosshair(blockPlacer) then return true end
		local humanoid = entitylib.isAlive and entitylib.character and entitylib.character.Humanoid
		if type(blockPlacer.autoBridge) == 'function' and humanoid and humanoid.MoveDirection.Magnitude > 0.1 then
			placeSafelyDownwards(blockPlacer)
			return true
		end
		return false
	end

	logLine = function(text)
		if not logBuffer or logLines > 4000 then return end
		logLines += 1
		table.insert(logBuffer, string.format('%.3f %s', tick() - logStart, text))
	end

	local function flushLog(force)
		if not logBuffer or #logBuffer == 0 or (not force and tick() - lastFlush < 0.5) then return end
		lastFlush = tick()
		local text = table.concat(logBuffer, '\n')..'\n'
		table.clear(logBuffer)
		pcall(appendfile, LOG, text)
	end

	vec = function(v)
		return v and string.format('%.1f,%.1f,%.1f', v.X, v.Y, v.Z) or 'nil'
	end

	local function startLog()
		logBuffer, logStart, logLines, lastFlush = {}, tick(), 0, tick()
		local on = {}
		for _, name in {'FastPlace', 'AutoTool', 'MineThrough', 'Reach', 'Scaffold', 'AntiHit', 'AutoDodge', 'Breaker', 'BlockIn', 'AutoBuildUp', 'Speed', 'Fly', 'NoFallDamage', 'Velocity', 'Killaura'} do
			local module = vape.Modules[name]
			if module and module.Enabled then table.insert(on, name) end
		end
		local hand = store.hand or {}
		local header = string.format('--- hold %s | tool %s (%s) | BLOCK_PLACE_CPS %s | Block CPS %s-%s | CPS %s-%s | ping %.3f | on: %s',
			os.date('%H:%M:%S'), tostring(hand.itemType), tostring(hand.toolType), tostring(bedwars.SharedConstants.BLOCK_PLACE_CPS),
			tostring(BlockCPS.ValueMin), tostring(BlockCPS.ValueMax), tostring(CPS.ValueMin), tostring(CPS.ValueMax),
			lplr:GetNetworkPing(), table.concat(on, ','))
		pcall(function()
			if not isfile(LOG) or #readfile(LOG) > 400000 then
				writefile(LOG, '')
			end
		end)
		logLine(header)
		lastSeenPlace = bedwars.BlockCpsController.lastPlaceTimestamp
		local breaker = bedwars.BlockBreaker
		lastHitSeen = breaker and breaker.lastHitTime
	end

	local function logFrame(dt)
		if not logBuffer or tick() - logStart > 60 then return end
		local hand = store.hand or {}
		local root = entitylib.isAlive and entitylib.character.RootPart
		local hum = entitylib.isAlive and entitylib.character.Humanoid
		local parts = {string.format('dt %.3f%s', dt, dt > 0.05 and ' HITCH' or '')}
		if root then
			table.insert(parts, string.format('y %.2f vy %.1f %s', root.Position.Y, root.AssemblyLinearVelocity.Y, tostring(hum.FloorMaterial):gsub('Enum.Material.', '')))
		end
		local ok, err = pcall(function()
			if hand.toolType == 'block' then
				local placer = bedwars.BlockPlacementController.blockPlacer
				local selector = placer and placer.clientManager and placer.clientManager:getBlockSelector()
				local info = selector and selector:getMouseInfo(0)
				local pos = info and info.placementPosition
				table.insert(parts, 'cell '..(pos == nil and 'none' or pos ~= pos and 'nan' or vec(pos)))
				table.insert(parts, 'disabled '..tostring(bedwars.BlockPlacementController.disabled))
			else
				local breaker = bedwars.BlockBreaker
				local selector = breaker and breaker.clientManager and breaker.clientManager:getBlockSelector()
				local info = selector and selector:getMouseInfo(1, {range = breaker.range})
				local target = info and info.target
				table.insert(parts, 'target '..(target and (target.blockInstance.Name..' '..vec(target.blockRef.blockPosition)) or 'none'))
				table.insert(parts, string.format('health %s', tostring(breaker and breaker.blockHealth)))
			end
		end)
		if not ok then table.insert(parts, 'probe error '..tostring(err)) end
		local placed = bedwars.BlockCpsController.lastPlaceTimestamp
		if placed ~= lastSeenPlace then
			table.insert(parts, string.format('PLACED %s', tick() - lastOwnPlace < 0.1 and 'by us' or 'by the game'))
			lastSeenPlace = placed
		end
		local breaker = bedwars.BlockBreaker
		if breaker and breaker.lastHitTime ~= lastHitSeen then
			table.insert(parts, 'HIT')
			lastHitSeen = breaker.lastHitTime
		end
		logLine(table.concat(parts, ' | '))
		flushLog()
	end

	local function hookHitLog()
		local breaker = bedwars.BlockBreaker
		if hitHook or type(breaker) ~= 'table' or type(breaker.hitBlock) ~= 'function' then return end
		hitOld = breaker.hitBlock
		hitHook = function(self, maid, ray, ...)
			if not (logBuffer and AutoClicker.Enabled and Debug.Enabled) then
				return hitOld(self, maid, ray, ...)
			end
			local before = self.lastHitTime
			local source = 'unknown'
			pcall(function()
				source = debug.info(2, 's'):match('[^%.]+$') or 'unknown'
			end)
			local results = table.pack(pcall(hitOld, self, maid, ray, ...))
			logLine(string.format('hitBlock from %s ray %s -> %s%s', source, ray and 'given' or 'nil',
				self.lastHitTime ~= before and 'hit' or 'no hit', results[1] and '' or ' ERROR '..tostring(results[2])))
			if not results[1] then error(results[2], 0) end
			return table.unpack(results, 2, results.n)
		end
		breaker.hitBlock = hitHook
	end

	local function unhookHitLog()
		if hitHook and bedwars.BlockBreaker and bedwars.BlockBreaker.hitBlock == hitHook then
			bedwars.BlockBreaker.hitBlock = hitOld
			hitHook, hitOld = nil, nil
		end
	end

	local function clickOnce()
		local toolType = store.hand and store.hand.toolType
		if not ((toolType == 'block' and Place.Enabled) or (toolType == 'sword' and Attack.Enabled)) then return end
		local now = tick()
		if toolType == 'sword' and now < nextClick then return end
		if bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN) then return end
		if store.hand.toolType == 'block' then
			placeGap = placeGap or placeInterval()
			if now >= nextPlace and canClickBlock()
				and workspace:GetServerTimeNow() - (bedwars.BlockCpsController.lastPlaceTimestamp or 0) >= placeGap
				and placeBlock() then
				nextPlace = now + placeGap
				placeGap = placeInterval()
			end
		elseif Attack.Enabled and store.hand.toolType == 'sword' then
			if now < nextClick then return end
			nextClick = now + clickInterval()
			if inputService.TouchEnabled then
				local controller = bedwars.SwordController
				if controller.mobileSwingPressed then
					controller:mobileSwingPressed()
				end
			elseif canSwing() and not bedwars.SwordController.disableSwingState then
				bedwars.gatedSwing(bedwars.SwordController.swingSwordAtMouse, bedwars.SwordController, 0.39)
			end
		end
	end

	local warned = false
	local function stopClicking()
		if held and logBuffer then
			logLine('--- released')
			flushLog(true)
			logBuffer = nil
		end
		held = false
	end

	local function AutoClick()
		held = true
		warned = false
		local now = tick()
		nextClick = now + clickInterval()
		nextPlace = now + (store.hand and store.hand.toolType == 'block' and placeInterval() or 0)
		placeGap = nil
		if Debug.Enabled then
			startLog()
		end
	end

	local function isAttack(input)
		local keybinds = bedwars.KeybindLoadController and bedwars.KeybindLoadController:getKeybinds()
		local keyboard = keybinds and keybinds.keyboard and keybinds.keyboard.controlActions.Attack or Enum.UserInputType.MouseButton1
		local gamepad = keybinds and keybinds.gamepad and keybinds.gamepad.controlActions.Attack or Enum.KeyCode.ButtonR2
		return input.UserInputType == keyboard or input.KeyCode == keyboard or input.KeyCode == gamepad
	end

	AutoClicker = vape.Categories.Combat:CreateModule({
		Name = 'AutoClicker',
		ExtraText = function() return CPS.ValueMin..'-'..CPS.ValueMax end,
		Function = function(callback)
			if callback then
				if Debug.Enabled then hookHitLog() end
				AutoClicker:Clean(runService.Heartbeat:Connect(function(dt)
					if not held then return end
					if logBuffer then logFrame(dt) end
					local ok, err = pcall(clickOnce)
					if not ok and not warned then
						warned = true
						warn('[ElevateV4] AutoClicker: '..tostring(err))
					end
				end))
				AutoClicker:Clean(inputService.InputBegan:Connect(function(input)
					if logBuffer and input.KeyCode == Enum.KeyCode.J then
						logLine('*** MARK')
					end
					if isAttack(input) then
						AutoClick()
					end
				end))

				AutoClicker:Clean(inputService.InputEnded:Connect(function(input)
					if isAttack(input) then
						stopClicking()
					end
				end))

				if inputService.TouchEnabled then
					local hooked = {}
					local function hookButton(button)
						if hooked[button] or not button:IsA('GuiButton') or not tonumber(button.Name) then return end
						hooked[button] = true
						AutoClicker:Clean(button.MouseButton1Down:Connect(AutoClick))
						AutoClicker:Clean(button.MouseButton1Up:Connect(stopClicking))
					end

					task.spawn(function()
						local mobileUI = lplr.PlayerGui:WaitForChild('MobileUI', 20)
						if not mobileUI or not AutoClicker.Enabled then return end

						for _, v in mobileUI:GetChildren() do
							hookButton(v)
						end
						AutoClicker:Clean(mobileUI.ChildAdded:Connect(hookButton))
					end)
				end
			else
				stopClicking()
				unhookHitLog()
			end
		end,
		Tooltip = 'Clicks for you while you hold the attack button'
	})

	Attack = AutoClicker:CreateGroup({
		Name = 'Attack',
		Default = true,
		Tooltip = 'Swings your sword while you hold attack'
	})
	CPS = Attack:CreateTwoSlider({
		Name = 'CPS',
		Min = 1,
		Max = 9,
		DefaultMin = 7,
		DefaultMax = 7
	})
	Place = AutoClicker:CreateGroup({
		Name = 'Place Blocks',
		Function = function(callback)
			if BlockCPS and BlockCPS.Object then
			end

		end,
		Default = true
	})
	Wool = Place:CreateToggle({Name = 'Wool only', Tooltip = 'Only clicks when you are holding wool', Darker = true})
	Debug = AutoClicker:CreateToggle({
		Name = 'Debug log',
		Tooltip = 'Logs what it does to a file. Press J to mark a moment',
		Function = function(callback)
			if callback and AutoClicker.Enabled then
				hookHitLog()
			elseif not callback then
				unhookHitLog()
			end
		end
	})
	BlockCPS = Place:CreateTwoSlider({
		Name = 'Block CPS',
		Min = 1,
		Max = 20,
		DefaultMin = 20,
		DefaultMax = 20,
		Darker = true
	})
end)

-- ===== Combat/BowAssist.lua =====
run(function()
	local BowAssist
	local Targets
	local Sort
	local AimPart
	local FOV
	local AimSpeed
	local Smoothness
	local Distance
	local Shake
	local Clear
	local Blacklist
	local Debug
	
	local drawStart, oldStart, oldStop = 0
	local rng = Random.new()
	local nextDiag = 0
	local diagReason

	local function isDrawing()
		if drawStart > 0 and tick() - drawStart < 30 then return true end
		local ok, held = pcall(function()
			return inputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
		end)
		if ok and held then return true end
		ok, held = pcall(function()
			return inputService:IsGamepadButtonDown(Enum.KeyCode.ButtonR2)
		end)
		return ok and held == true
	end

	local function report(sent, detail)
		if not (Debug and Debug.Enabled) or tick() <= nextDiag then return end
		nextDiag = tick() + 2
		if sent then
			task.defer(notif, 'BowAssist', 'eased the aim onto '..tostring(detail), 4)
		else
			task.defer(notif, 'BowAssist', 'left the draw alone: '..tostring(detail), 4, 'warning')
		end
	end
	
	local arcCheck = RaycastParams.new()
	arcCheck.FilterType = Enum.RaycastFilterType.Exclude
	
	BowAssist = vape.Categories.Combat:CreateModule({
		Name = 'BowAssist',
		Function = function(callback)
			if callback then
				local controller = bedwars.DefaultProjectileSourceController
				if not controller then
					notif('BowAssist', 'The projectile source controller is unavailable.', 5, 'warning')
					return
				end
				oldStart = controller.onStartCharging
				if type(oldStart) == 'function' then
					controller.onStartCharging = function(self, ...)
						drawStart = tick()
						return oldStart(self, ...)
					end
				end
	
				oldStop = controller.onStopCharging
				if type(oldStop) == 'function' then
					controller.onStopCharging = function(self, ...)
						drawStart = 0
						return oldStop(self, ...)
					end
				end				BowAssist:Clean(runService.PostSimulation:Connect(function(dt)
					if not entitylib.isAlive or not isDrawing() then return end

					local meta = store.hand.tool and bedwars.ItemMeta[store.hand.tool.Name]
					local source = meta and meta.projectileSource
					if not source or not source.projectileType then return end
	
					local ammo = store.hand.tool.Name
					if source.ammoItemTypes and #source.ammoItemTypes > 0 then
						ammo = nil
						for _, v in store.inventory.inventory.items do
							if table.find(source.ammoItemTypes, v.itemType) then
								ammo = v.itemType
								break
							end
						end
					end
					if not ammo then return end					local projType = source.projectileType(ammo)
					if table.find(Blacklist.ListEnabled or {}, ((projType == 'glue_trap' or projType == 'glue_projectile') and 'gloop' or projType)) then
						report(false, projType..' is blacklisted')
						return
					end

					local projmeta = bedwars.ProjectileMeta[projType]
					if not projmeta or type(projmeta.launchVelocity) ~= 'number' then
						report(false, 'no projectile meta for '..tostring(projType))
						return
					end

					local scalar = tonumber(source.minStrengthScalar) or 1
					local chargeWindow = tonumber(source.maxStrengthChargeSec) or tonumber(source.multiShotChargeTime)
					local ratio = chargeWindow and drawStart > 0 and math.clamp((tick() - drawStart) / chargeWindow, 0, 1) or 1
					local projSpeed = projmeta.launchVelocity * (scalar + (1 - scalar) * ratio)

	
					local localPosition = entitylib.character.RootPart.Position
					local ent = entitylib.EntityMouse({
						Range = FOV.Value,
						Part = 'RootPart',
						Wallcheck = Targets.Walls.Enabled,
						Players = Targets.Players.Enabled,
						NPCs = Targets.NPCs.Enabled,
						Priority = Targets.Priority.Value,
						Origin = localPosition,
						Sort = sortmethods[Sort.Value]
					})					if not ent or (localPosition - ent.RootPart.Position).Magnitude > Distance.Value then
						report(false, 'no target inside the FOV within '..tostring(Distance.Value)..' studs')
						return
					end

					local targetPosition = ent[AimPart.Value].Position
					local shootPosition
					pcall(function()
						local value = bedwars.ProjectileController:getLaunchPosition(gameCamera.CFrame)
						if typeof(value) == 'Vector3' then
							shootPosition = value
						elseif typeof(value) == 'CFrame' then
							shootPosition = value.Position
						end
					end)
					if not shootPosition then
						local bow = bedwars.BowConstantsTable
						shootPosition = bow and (CFrame.new(localPosition, targetPosition) * CFrame.new(Vector3.new(-bow.RelX, -bow.RelY, -bow.RelZ))).Position
							or (localPosition + (targetPosition - localPosition).Unit * 1.5)
					end
					local gravity = projmeta.gravitationalAcceleration or 196.2
					local calc, _, travelTime = prediction.SolveTrajectory(shootPosition, projSpeed, gravity, targetPosition, ent.RootPart.AssemblyLinearVelocity, workspace.Gravity, ent.HipHeight, ent.Jumping and 42.6 or nil, nil, ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(ent.RootPart.AssemblyLinearVelocity.Y) > 0.01, ent.RootPart.Position, ent.RootPart, nil, true)
					if not calc then
						report(false, 'no ballistic solution to '..tostring(ent.Player and ent.Player.Name or 'the target'))
						return
					end

	
					if Clear.Enabled and travelTime then
						local ignorelist = {gameCamera, lplr.Character}
						for _, v in entitylib.List do
							if v.Character then
								table.insert(ignorelist, v.Character)
							end
						end
						arcCheck.FilterDescendantsInstances = ignorelist
						if not prediction.IsTrajectoryClear(shootPosition, calc - shootPosition, gravity, travelTime, arcCheck) then
							report(false, 'a block is in the way of the arc')
							return
						end
					end
	
					report(true, (ent.Player and ent.Player.Name) or 'the target')
					targetinfo.Targets[ent] = tick() + 1
					local jitter = Vector3.new((rng:NextNumber() - 0.5) * Shake.Value * dt, (rng:NextNumber() - 0.5) * Shake.Value * dt, (rng:NextNumber() - 0.5) * Shake.Value * dt)
					local speed = math.clamp((AimSpeed.Value / Smoothness.Value) * dt, 0, 1)
					if entitylib.character.Head.LocalTransparencyModifier ~= 1 and mousemoverel then
						local viewport = gameCamera:WorldToViewportPoint(calc + jitter)
						if viewport.Z > 0 then
							local pos = (Vector2.new(viewport.X, viewport.Y) - inputService:GetMouseLocation()) * speed
							mousemoverel(pos.X, pos.Y)
						end
					else
						gameCamera.CFrame = gameCamera.CFrame:Lerp(CFrame.lookAt(gameCamera.CFrame.Position, calc + jitter), speed)
					end
				end))
			else
				drawStart = 0
				local controller = bedwars.DefaultProjectileSourceController
				if controller then
					if oldStart then controller.onStartCharging = oldStart end
					if oldStop then controller.onStopCharging = oldStop end
				end
			end
		end,
		Tooltip = 'Eases your aim onto where the arrow will drop while drawing a bow'
	})
	
	Targets = BowAssist:CreateTargets({
		Players = true,
		Walls = true
	})
	local methods = {'Distance', 'Damage'}
	for _, v in sortlist do
		if not table.find(methods, v) then
			table.insert(methods, v)
		end
	end
	Sort = BowAssist:CreateDropdown({
		Name = 'Target mode',
		List = methods,
		Default = 'Distance',
		Tooltip = TARGET_MODE_TOOLTIP
	})
	AimPart = BowAssist:CreateDropdown({
		Name = 'Part',
		List = {'RootPart', 'Head'}
	})
	FOV = BowAssist:CreateSlider({
		Name = 'FOV',
		Min = 1,
		Max = 1000,
		Default = 220,
		Tooltip = 'How far from your cursor a target can be'
	})
	Distance = BowAssist:CreateSlider({
		Name = 'Distance',
		Min = 1,
		Max = 300,
		Default = 200,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end
	})
	AimSpeed = BowAssist:CreateSlider({
		Name = 'Aim speed',
		Min = 1,
		Max = 20,
		Default = 5
	})
	Smoothness = BowAssist:CreateSlider({
		Name = 'Smoothness',
		Min = 1,
		Max = 20,
		Default = 2,
		Decimal = 10,
		Tooltip = 'Softens the aim, 1 leaves it unchanged'
	})
	Shake = BowAssist:CreateSlider({
		Name = 'Shake',
		Min = 0,
		Max = 100,
		Default = 0,
		Tooltip = 'Adds random jitter to look more human'
	})
	Clear = BowAssist:CreateToggle({
		Name = 'Clear shot only',
		Default = true,
		Tooltip = 'Stops assisting when a block is in the way'
	})
	Blacklist = BowAssist:CreateTextList({
		Name = 'Blacklist',
		Default = {'gloop', 'telepearl'},
		Darker = true,
		Placeholder = 'projectile',
		Tooltip = 'Projectile types the assist leaves alone'
	})
	Debug = BowAssist:CreateToggle({
		Name = 'Debug',
		Tooltip = 'Logs what it does'
	})
end)

-- ===== Combat/HitregAdjuster.lua =====
run(function()
	local HitregAdjuster, Hitreg
	local firstConnection, restoreConnection

	HitregAdjuster = vape.Categories.Combat:CreateModule({
		Name = 'HitregAdjuster',
		Function = function(enabled)
			if not enabled then return end
			local sync = bedwars.SyncEvents and bedwars.SyncEvents.SwordSwing
			if not sync then
				notif('HitregAdjuster', 'Sword swing events are unavailable.', 5, 'warning')
				HitregAdjuster:Toggle()
				return
			end
			local original
			firstConnection = sync:setPriority(150):connect(function(event)
				original = event.attackSpeed
				event.attackSpeed = 10 / math.max(Hitreg:GetRandomValue() - 1, 1)
			end)
			restoreConnection = sync:setPriority(300):connect(function(event)
				if original ~= nil then event.attackSpeed = original end
			end)
			HitregAdjuster:Clean(function()
				if firstConnection then firstConnection:Destroy(); firstConnection = nil end
				if restoreConnection then restoreConnection:Destroy(); restoreConnection = nil end
			end)
		end,
		Tooltip = 'Adjusts the spacing of your own sword swings'
	})
	Hitreg = HitregAdjuster:CreateTwoSlider({Name = 'Hitreg', Min = 1, Max = 35, DefaultMin = 35, DefaultMax = 35, Suffix = ' hits / 10s'})
end)

