-- ===== Combat/Reach.lua =====
run(function()

	local util = vape.Libraries.bedwarsutil
	local BlockReach
		local BlockRange
		local BreakReach
		local BreakRange
		local SwordReach
		local SwordRange

		local old
		local hook

		Reach = vape.Categories.Combat:CreateModule({
			Name = 'Reach',
			ExtraText = function() return tostring(SwordRange.Value) end,
			Tooltip = 'Lets you hit, place and mine from further away',
			Function = function(callback)
				bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = callback and SwordReach.Enabled and SwordRange.Value + 2 or 14.4
				if callback then
					if hook then return end
					old = bedwars.BlockSelector.getMouseInfo
					hook = function(...)
						local Self, Select, Args = ...
						if not Reach.Enabled then
							return old(...)
						end
						local range
						if Select == 0 and BlockReach.Enabled then
							range = BlockRange.Value
						elseif Select == 1 and BreakReach.Enabled then
							range = BreakRange.Value
						end
						if range ~= nil then
							Args = Args or {}
							Args.range = range
						end
						return old(Self, Select, Args)
					end
					bedwars.BlockSelector.getMouseInfo = hook
				else
					if bedwars.BlockSelector.getMouseInfo == hook then
						bedwars.BlockSelector.getMouseInfo = old
						hook = nil
						old = nil
					end
				end
			end,
		})
		SwordReach = Reach:CreateGroup({
			Name = 'Sword Reach',
			Default = true,
			Function = function(callback)
				if SwordRange then bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = Reach.Enabled and callback and SwordRange.Value + 2 or 14.4 end
			end,
		})
		SwordRange = SwordReach:CreateSlider({
			Name = 'Sword Range',
			Min = 1,
			Max = 18,
			Default = 18,
			Decimal = 5,
			Darker = true,
			Suffix = util.Studs,
			Function = function(val)
				bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = Reach.Enabled and SwordReach.Enabled and val + 2 or 14.4
			end,
		})
		BlockReach = Reach:CreateGroup({
			Name = 'Placement Reach',
		})
		BlockRange = BlockReach:CreateSlider({
			Name = 'Placement Range',
			Min = 1,
			Max = 60,
			Default = 18,
			Darker = true,
			Suffix = util.Studs,
		})
		BreakReach = Reach:CreateGroup({
			Name = 'Break Reach',
		})
		BreakRange = BreakReach:CreateSlider({
			Name = 'Break Range',
			Min = 1,
			Max = 30,
			Default = 30,
			Decimal = 5,
			Darker = true,
			Suffix = util.Studs,
		})
		Reach:CreateButton({
			Name = 'Reset to default reach',
			Tooltip = 'Sets every range back to the game\'s default',
			Function = function()
				BreakRange:SetValue(18)
				BlockRange:SetValue(24)
				SwordRange:SetValue(12.4)
			end,
		})
	end)

-- ===== Combat/Sprint.lua =====
run(function()
    local Sprint
    local old
    local hook

    local SPRINT_WALK_SPEED = 20

    local function isSprinting(controller)
        return type(controller.isSprinting) == 'function' and controller:isSprinting()
    end

    local function assertSprint()
        local controller = bedwars.SprintController
        if not controller or type(controller.startSprinting) ~= 'function' then return end
        local character = entitylib.isAlive and entitylib.character
        local humanoid = character and character.Humanoid
        if not humanoid or humanoid.Health <= 0 then return end
        if isSprinting(controller) and humanoid.WalkSpeed >= SPRINT_WALK_SPEED then return end
        controller:stopSprinting()
        controller:startSprinting()
    end

    Sprint = vape.Categories.Combat:CreateModule({
        Name = 'Sprint',
        Function = function(callback)
            if callback then
                if inputService.TouchEnabled then
                    pcall(function()
                        lplr.PlayerGui.MobileUI['4'].Visible = false
                    end)
                end
                old = bedwars.SprintController.stopSprinting
                hook = function(...)
                    local call = old(...)
                    bedwars.SprintController:startSprinting()
                    return call
                end
                bedwars.SprintController.stopSprinting = hook
                Sprint:Clean(entitylib.Events.LocalAdded:Connect(function()
                    for _, pause in {0.1, 0.25, 0.5, 0.75, 1, 1.5, 2} do
                        task.delay(pause, function()
                            if Sprint.Enabled then
                                assertSprint()
                            end
                        end)
                    end
                end))
                bedwars.SprintController:stopSprinting()
                assertSprint()
            else
                if inputService.TouchEnabled then
                    pcall(function()
                        lplr.PlayerGui.MobileUI['4'].Visible = true
                    end)
                end
                if bedwars.SprintController.stopSprinting == hook then
                    bedwars.SprintController.stopSprinting = old
                end
                hook, old = nil, nil
                bedwars.SprintController:stopSprinting()
            end
        end,
        Tooltip = 'Keeps you sprinting while you move'
    })
end)

-- ===== Combat/TriggerBot.lua =====
run(function()
	local TriggerBot
	local Targets
	local Range
	local Angle
	local CPS
	local Limit
	local Region
	local Continue
	local Duration
	local Mouse
	local AFKCheck
	local GUI
	local BoxColor
	local BoxTween
	local BoxSpeed
	
	local box
	local lastTarget, lastSwing, killUntil = nil, 0, 0
	local rayParams = RaycastParams.new()
	
	local function getTarget(localPosition, attackRange, angle)
		if angle > 0 then
			local origin, facing = gameCamera.CFrame.Position, gameCamera.CFrame.LookVector
			local limit = math.cos(math.rad(math.min(angle, 360)) / 2)
			for _, v in entitylib.AllPosition({
				Part = 'RootPart',
				Range = attackRange,
				Origin = localPosition,
				Players = Targets.Players.Enabled,
				NPCs = Targets.NPCs.Enabled,
				Priority = Targets.Priority.Value,
				Wallcheck = Targets.Walls.Enabled or nil,
				Sort = sortmethods.Distance
			}) do
				local delta = v.RootPart.Position - origin
				if delta.Magnitude < 0.001 or facing:Dot(delta.Unit) >= limit then
					return v
				end
			end
	
			return nil
		end
	
		local unit = lplr:GetMouse().UnitRay
		rayParams.FilterDescendantsInstances = {lplr.Character}
		local ray = bedwars.QueryUtil:raycast(unit.Origin, unit.Direction * 200, rayParams)
		if not ray then return nil end
	
		for _, v in entitylib.List do
			if v.Targetable and ray.Instance:IsDescendantOf(v.Character) and (localPosition - v.RootPart.Position).Magnitude <= attackRange then
				if Targets.Players.Enabled and v.Player or Targets.NPCs.Enabled and not v.Player then
					if not Targets.Walls.Enabled or not entitylib.Wallcheck(localPosition, v.RootPart.Position, true, v) then
						return v
					end
				end
			end
		end
	
		return nil
	end
	
	TriggerBot = vape.Categories.Combat:CreateModule({
		Name = 'TriggerBot',
		ExtraText = function() return CPS.ValueMin..'-'..CPS.ValueMax end,
		Function = function(callback)
			if callback then
				lastTarget, lastSwing, killUntil = nil, 0, 0
	
				repeat
					local ent, doAttack
					if entitylib.isAlive and (not GUI.Enabled or not bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN)) and (not Mouse.Enabled or inputService:IsMouseButtonPressed(0)) and (not AFKCheck.Enabled or not isAfk()) then
						if (not Limit.Enabled or store.hand.toolType == 'sword') and bedwars.DaoController.chargingMaid == nil then
							local attackRange = math.clamp(Range.Value, 0, getReach(store.hand.tool) * 2)
							ent = getTarget(entitylib.character.RootPart.Position, attackRange, Angle.Value)
							doAttack = ent ~= nil
	
							if lastTarget and lastTarget.Health <= 0 then
								if tick() - lastSwing <= 1 then
									killUntil = tick() + Duration.Value
								end
								lastTarget = nil
							end
	
							if not doAttack and Region.Enabled then
								doAttack = (bedwars.SwordController.getTargetInRegion and bedwars.SwordController:getTargetInRegion(attackRange, 0) ~= nil) or false
							end
	
							if not doAttack and Continue.Enabled and tick() < killUntil then
								doAttack = true
							end
	
							if ent then
								lastTarget = ent
								targetinfo.Targets[ent] = tick() + 1
							end
	
							if doAttack and canSwing() then
								if ent then
									lastSwing = tick()
								end
								bedwars.SwordController:swingSwordAtMouse()
							end
						end
					end
	
					if box then
						box.Adornee = ent and ent.RootPart or nil
						tweenService:Create(box, TweenInfo.new(BoxSpeed.Value, Enum.EasingStyle[BoxTween.Value]), {
							Size = ent and Vector3.new(4, 6, 4) or Vector3.zero
						}):Play()
						if ent then
							box.Color3 = Color3.fromHSV(BoxColor.Hue, BoxColor.Sat, BoxColor.Value)
							box.Transparency = 1 - BoxColor.Opacity
						end
					end
	
					task.wait(doAttack and 1 / CPS:GetRandomValue() or 0.016)
				until not TriggerBot.Enabled
			end
		end,
		Tooltip = 'Attacks or fires when your cursor is on an enemy'
	})
	
	Targets = TriggerBot:CreateTargets({
		Players = true,
		NPCs = true,
		Walls = true
	})
	Range = TriggerBot:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 18,
		Default = 18,
		Decimal = 10,
		Suffix = function(val)
			return val <= 1 and 'stud' or 'studs'
		end,
		Tooltip = 'How far away a target can be'
	})
	Angle = TriggerBot:CreateSlider({
		Name = 'Angle',
		Min = 0,
		Max = 360,
		Default = 0,
		Suffix = 'degrees',
		Tooltip = 'How wide an area around your view it attacks'
	})
	TriggerBot:CreateButton({
		Name = 'Reset to default reach',
		Tooltip = 'Sets the range back to the game\'s default',
		Function = function()
			Range:SetValue(14.4)
			Angle:SetValue(0)
		end,
	})
	CPS = TriggerBot:CreateTwoSlider({
		Name = 'CPS',
		Min = 1,
		Max = 9,
		DefaultMin = 7,
		DefaultMax = 7
	})
	Limit = TriggerBot:CreateToggle({
		Name = 'Limit to items',
		Default = true,
		Tooltip = 'Only works while holding the item it uses'
	})
	Region = TriggerBot:CreateToggle({
		Name = 'Region check',
		Default = true,
		Tooltip = 'Also swings when anything is inside your sword region'
	})
	Continue = TriggerBot:CreateGroup({
		Name = 'Continue after kill',
		Tooltip = 'Keeps swinging briefly after a kill'
	})
	Duration = Continue:CreateSlider({
		Name = 'Continue time',
		Min = 0.05,
		Max = 2,
		Default = 0.4,
		Decimal = 100,
		Darker = true,
		Suffix = 'seconds'
	})
	Mouse = TriggerBot:CreateToggle({Name = 'Require mouse down'})
	AFKCheck = TriggerBot:CreateToggle({
		Name = 'AFK check',
		Tooltip = 'Stops attacking while you are away from your keyboard and mouse'
	})
	GUI = TriggerBot:CreateToggle({Name = 'GUI check'})
	local ShowTargetGroup = TriggerBot:CreateGroup({
		Name = 'Show target',
		Function = function(callback)
			if callback then
				box = Instance.new('BoxHandleAdornment')
				box.Adornee = nil
				box.AlwaysOnTop = true
				box.Size = Vector3.zero
				box.CFrame = CFrame.new(0, -0.5, 0)
				box.ZIndex = 0
				box.Parent = vape.gui
			elseif box then
				box:Destroy()
				box = nil
			end
		end
	})
	local animlist = {'Bounce'}
	for _, v in Enum.EasingStyle:GetEnumItems() do
		if not table.find(animlist, v.Name) then
			table.insert(animlist, v.Name)
		end
	end
	BoxTween = ShowTargetGroup:CreateDropdown({
		Name = 'Box Animation',
		List = animlist,
		Darker = true
	})
	BoxSpeed = ShowTargetGroup:CreateSlider({
		Name = 'Animation Speed',
		Min = 0,
		Max = 10,
		Default = 0.9,
		Decimal = 30,
		Darker = true
	})
	BoxColor = ShowTargetGroup:CreateColorSlider({
		Name = 'Target Color',
		Darker = true,
		DefaultHue = 0.6,
		DefaultOpacity = 0.5
	})
end)

-- ===== Combat/Velocity.lua =====
run(function()
    local Velocity
    local Horizontal
    local Vertical
    local Chance
    local TargetCheck
    local Direction
    local rand, old = Random.new()
    local hook

    local function rotateY(vector, degrees)
        local radians = math.rad(degrees)
        return Vector3.new(
            vector.X * math.cos(radians) - vector.Z * math.sin(radians),
            0,
            vector.X * math.sin(radians) + vector.Z * math.cos(radians)
        )
    end

    local function getDirectionalSource(root, sourcePosition)
        local direction = Direction.Value
        if direction == 'Default' then
            return sourcePosition
        elseif direction == 'Up' then
            root:ApplyImpulse(Vector3.new(0, root.AssemblyMass * 120, 0))
            return nil, true
        elseif direction == 'Void' then
            root:ApplyImpulse(Vector3.new(0, -root.AssemblyMass * 60, 0))
            return nil, true
        end

        local rootPosition = root.Position
        if direction == 'Left' then
            return rootPosition + root.CFrame.RightVector * 10
        elseif direction == 'Right' then
            return rootPosition - root.CFrame.RightVector * 10
        elseif direction == 'Reverse' and sourcePosition then
            return Vector3.new(2 * rootPosition.X - sourcePosition.X, sourcePosition.Y, 2 * rootPosition.Z - sourcePosition.Z)
        end

        local flatSource = sourcePosition and Vector3.new(sourcePosition.X, 0, sourcePosition.Z)
        local velocity = flatSource and ((rootPosition * Vector3.new(1, 0, 1)) - flatSource)
        if not velocity or velocity.Magnitude < 0.001 then
            return sourcePosition
        end

        velocity = velocity.Unit
        direction = direction == 'Random' and ({'Left', 'Right', 'Pull'})[rand:NextInteger(1, 3)] or direction
        local redirected = direction == 'Pull' and -velocity or table.find({'Left', 'Right'}, direction) and rotateY(velocity, direction == 'Left' and 90 or -90) or velocity
        return Vector3.new(rootPosition.X - redirected.X * 100, sourcePosition.Y, rootPosition.Z - redirected.Z * 100)
    end

    Velocity = vape.Categories.Combat:CreateModule({
        Name = 'Velocity',
        ExtraText = function() return Horizontal.Value..'% '..Vertical.Value..'%' end,
        Function = function(callback)
            if callback then
                if hook then return end
                old = bedwars.KnockbackUtil.applyKnockback
                hook = function(root, mass, dir, knockback, ...)
                    if not Velocity.Enabled or rand:NextNumber(0, 100) > Chance.Value then
                        return old(root, mass, dir, knockback, ...)
                    end
                    local check = (not TargetCheck.Enabled) or entitylib.EntityPosition({
                        Range = 50,
                        Part = 'RootPart',
                        Players = true
                    })

                    if check then
                        knockback = knockback or {}
                        if Horizontal.Value == 0 and Vertical.Value == 0 and Direction.Value == 'Default' then return end
                        if Horizontal.Value ~= 0 or Vertical.Value ~= 0 then
                            knockback.horizontal = (knockback.horizontal or 1) * (Horizontal.Value / 100)
                            knockback.vertical = (knockback.vertical or 1) * (Vertical.Value / 100)
                        end
                        local redirectedSource, skipOriginal = getDirectionalSource(root, dir)
                        if skipOriginal then return end
                        dir = redirectedSource or dir
                    end

                    return old(root, mass, dir, knockback, ...)
                end
                bedwars.KnockbackUtil.applyKnockback = hook
            elseif hook and bedwars.KnockbackUtil.applyKnockback == hook then
                bedwars.KnockbackUtil.applyKnockback = old
                hook, old = nil, nil
            end
        end,
        Tooltip = 'Reduces knockback taken'
    })
    Horizontal = Velocity:CreateSlider({
        Name = 'Horizontal',
        Min = 0,
        Max = 100,
        Default = 0,
        Suffix = '%'
    })
    Vertical = Velocity:CreateSlider({
        Name = 'Vertical',
        Min = 0,
        Max = 100,
        Default = 0,
        Suffix = '%'
    })
    Chance = Velocity:CreateSlider({
        Name = 'Chance',
        Min = 0,
        Max = 100,
        Default = 100,
        Suffix = '%'
    })
    Velocity:CreateButton({
        Name = 'Reset to default knockback',
        Tooltip = 'Sets knockback back to the game\'s default',
        Function = function()
            Horizontal:SetValue(100)
            Vertical:SetValue(100)
            Chance:SetValue(100)
        end,
    })
    TargetCheck = Velocity:CreateToggle({Name = 'Only when targeting'})
    Direction = Velocity:CreateDropdown({
        Name = 'Direction',
        List = {'Default', 'Backwards', 'Up', 'Void', 'Left', 'Right', 'Reverse', 'Pull', 'Random'},
        Default = 'Default',
        Tooltip = 'Changes the direction of knockback'
    })
end)

-- ===== Inventory/ArmorSwitch.lua =====
run(function()
    local ArmorSwitch
    local Mode
    local Targets
    local Range

    local function waitForInventory()
        local answered = false
        local connection = vapeEvents.InventoryChanged.Event:Once(function()
            answered = true
        end)
        local deadline = tick() + 0.5
        repeat
            task.wait()
        until answered or tick() > deadline
        connection:Disconnect()
    end

    ArmorSwitch = vape.Categories.Inventory:CreateModule({
        Name = 'ArmorSwitch',
        Function = function(callback)
            if callback then
                if Mode.Value == 'Toggle' then
                    repeat
                        local state = entitylib.EntityPosition({
                            Part = 'RootPart',
                            Range = Range.Value,
                            Players = Targets.Players.Enabled,
                            Priority = Targets.Priority and Targets.Priority.Value,
                            NPCs = Targets.NPCs.Enabled,
                            Wallcheck = Targets.Walls.Enabled
                        }) and true or false

                        for i = 0, 2 do
                            local armor = store.inventory.inventory.armor[i + 1]
                            if (armor ~= 'empty') ~= state and ArmorSwitch.Enabled then
                                local item = armor == 'empty' and state and getBestArmor(i) or nil
                                if armor ~= 'empty' or item then
                                    bedwars.Store:dispatch({
                                        type = 'InventorySetArmorItem',
                                        item = item,
                                        armorSlot = i
                                    })
                                    waitForInventory()
                                end
                            end
                        end
                        task.wait(0.1)
                    until not ArmorSwitch.Enabled
                else
                    ArmorSwitch:Toggle()
                    for i = 0, 2 do
                        local armor = store.inventory.inventory.armor[i + 1]
                        local item = armor == 'empty' and getBestArmor(i) or nil
                        if armor ~= 'empty' or item then
                            bedwars.Store:dispatch({
                                type = 'InventorySetArmorItem',
                                item = item,
                                armorSlot = i
                            })
                            waitForInventory()
                        end
                    end
                end
            end
        end,
        Tooltip = 'Takes your armour on and off to bait enemies'
    })
    Targets = ArmorSwitch:CreateTargets({
        Players = true,
        NPCs = true
    })
    Mode = ArmorSwitch:CreateDropdown({
        Name = 'Mode',
        List = {'Toggle', 'On Key'},
        Tooltip = 'Toggle - wears armour only with someone near\nOn Key - swaps once and switches off'
    })
    Range = ArmorSwitch:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 30,
        Default = 30,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
end)

-- ===== Inventory/AutoBank.lua =====
run(function()
    local AutoBank
    local Whitelist
    local ChestRange
    local Withdraw
    local OnlyWhenLow
    local LowHealth

    local util = vape.Libraries.bedwarsutil
    local cooldowns = {}
    local banked = 0

    local function matches(name)
        if not name then return false end
        local lower = tostring(name):lower()
        for _, entry in Whitelist.ListEnabled do
            local wanted = tostring(entry):lower()
            if wanted == lower or (wanted == 'wool' and lower:find('wool', 1, true)) then
                return true
            end
        end
        return false
    end

    local function bankable(item)
        local name = item and (item.itemType or (item.tool and item.tool.Name))
        if not name or not item.tool then return nil end
        local meta = bedwars.ItemMeta and bedwars.ItemMeta[name]
        if meta and (meta.armor or meta.sword or meta.breakBlock) then return nil end
        return matches(name) and name or nil
    end

    local function atChest()
        return util.Shop.ChestScreenOpen() or util.Chest.InRange(ChestRange.Value)
    end

    local function lowEnough()
        if not OnlyWhenLow.Enabled then return true end
        local health = util.Health.Current()
        return not health or health <= LowHealth.Value
    end

    local function deposit(folder)
        local wanted = {}
        local now = os.clock()
        for _, item in store.inventory.inventory.items do
            local name = bankable(item)
            if name and (cooldowns[name] or 0) < now then
                table.insert(wanted, {Name = name, Tool = item.tool})
            end
        end
        if #wanted == 0 then return end
        util.Chest.Observe(folder, function()
            for _, entry in wanted do
                if not AutoBank.Enabled then break end
                if not util.Chest.Give(folder, entry.Tool) then
                    cooldowns[entry.Name] = os.clock() + 5
                end
            end
        end)
    end

    local function withdraw(folder)
        local wanted = {}
        for _, entry in util.Chest.Entries(folder) do
            if matches(entry.Name) then
                table.insert(wanted, entry)
            end
        end
        if #wanted == 0 then return false end
        util.Chest.Observe(folder, function()
            for index, entry in wanted do
                if not AutoBank.Enabled or index > 8 then break end
                if entry.Parent then util.Chest.Take(folder, entry) end
            end
        end)
        return true
    end

    local function count(folder)
        local total = 0
        for _, entry in util.Chest.Entries(folder) do
            if matches(entry.Name) then
                total += entry:GetAttribute('Amount') or 1
            end
        end
        return total
    end

    AutoBank = vape.Categories.Inventory:CreateModule({
        Name = 'AutoBank',
        Function = function(callback)
            if not callback then
                banked = 0
                return
            end
            if not util.Queue.Await(AutoBank) then return end
            local redeposit = false
            repeat
                local folder = util.Chest.OwnFolder()
                if folder then
                    banked = count(folder)
                    if entitylib.isAlive and store.matchState ~= 2 and atChest() then
                        if util.Shop.BuyScreenOpen() then
                            if Withdraw.Enabled and withdraw(folder) then
                                redeposit = true
                            end
                        elseif redeposit or lowEnough() then
                            deposit(folder)
                            redeposit = false
                        end
                    end
                end
                task.wait(0.1)
            until not AutoBank.Enabled
        end,
        ExtraText = function()
            return banked > 0 and tostring(banked) or 'Chest'
        end,
        Tooltip = 'Keeps resources in your personal chest and takes them out at shops'
    })
    Whitelist = AutoBank:CreateTextList({
        Name = 'Whitelist',
        Default = {'emerald', 'diamond', 'iron'},
        Tooltip = 'Items to bank'
    })
    ChestRange = AutoBank:CreateSlider({
        Name = 'Chest range',
        Min = 1,
        Max = 30,
        Default = util.Chest.Range,
        Suffix = util.Studs,
        Tooltip = 'How close to your personal chest you need to be'
    })
    Withdraw = AutoBank:CreateToggle({
        Name = 'Withdraw at shop',
        Default = true,
        Tooltip = 'Takes items out of the chest while a shop is open'
    })
    OnlyWhenLow = AutoBank:CreateGroup({
        Name = 'Only when low',
        Tooltip = 'Only banks once your health drops to Low HP'
    })
    LowHealth = OnlyWhenLow:CreateSlider({
        Name = 'Low HP',
        Min = 1,
        Max = 100,
        Default = 30,
        Darker = true
    })
end)

-- ===== Inventory/AutoBuy.lua =====
run(function()
	local util = vape.Libraries.bedwarsutil

	local AutoBuy
	local Buy
	local BedwarsCheck
	local GUI
	local SmartCheck
	local OpenShop
	local ArrowAmount
	local Custom = {}
	local CustomPost = {}
	local Functions, id = {}
	local Callbacks = {Custom, Functions, CustomPost}
	local npctick = tick()

	local swords = {
		'wood_sword',
		'stone_sword',
		'iron_sword',
		'diamond_sword',
		'emerald_sword'
	}

	local armors = {
		'none',
		'leather_chestplate',
		'iron_chestplate',
		'diamond_chestplate',
		'emerald_chestplate'
	}

	local axes = {
		'none',
		'wood_axe',
		'stone_axe',
		'iron_axe',
		'diamond_axe'
	}

	local pickaxes = {
		'none',
		'wood_pickaxe',
		'stone_pickaxe',
		'iron_pickaxe',
		'diamond_pickaxe'
	}

	local function getShopNPC()
		local itemShop = util.Shop.Nearby('item')
		local upgradeShop = util.Shop.Nearby('upgrade')
		local shop = (itemShop or upgradeShop) and true or nil
		return shop, itemShop ~= nil, upgradeShop ~= nil, itemShop and itemShop.Id or nil
	end

	local function canBuy(item, currencytable, amount)
		return util.Shop.CanBuy(item, currencytable, amount)
	end

	local function buyItem(item, currencytable)
		if not id then return end
		util.Shop.Purchase(item, id, currencytable, {Label = 'AutoBuy'})
	end

	local function buyTool(tool, tools, currencytable)
		local bought, buyable = false
		tool = tool and table.find(tools, tool.itemType) and table.find(tools, tool.itemType) + 1 or math.huge

		for i = tool, #tools do
			local v = util.Shop.Item(tools[i])
			if not v then continue end
			if canBuy(v, currencytable) then
				if SmartCheck.Enabled and bedwars.ItemMeta[tools[i]].breakBlock and i > 2 then
					if Buy:Has('Armour') then
						local currentarmor = store.inventory.inventory.armor[2]
						currentarmor = currentarmor and currentarmor ~= 'empty' and currentarmor.itemType or 'none'
						if (table.find(armors, currentarmor) or 3) < 3 then break end
					end
					if Buy:Has('Sword') then
						if store.tools.sword and (table.find(swords, store.tools.sword.itemType) or 2) < 2 then break end
					end
				end
				bought = true
				buyable = v
			end
			if v.nextTier then break end
		end

		if buyable and not util.Shop.Pending(buyable.itemType) then
			buyItem(buyable, currencytable)
		end

		return bought
	end

	local function familyList(pattern, exclude)
		local meta = bedwars and bedwars.ItemMeta or {}
		local found = {}
		for name in meta do
			if type(name) == 'string' and name:find(pattern, 1, true) and not (exclude and name:find(exclude, 1, true)) then
				table.insert(found, name)
			end
		end
		return found
	end

	local bows = familyList('bow', 'crossbow')
	local crossbows = familyList('crossbow')
	local shopFiltered = false

	local function filterFamilies()
		if shopFiltered or type(bedwars.ShopItems) ~= 'table' then return end
		local sold = {}
		for _, entry in bedwars.ShopItems do
			if type(entry) == 'table' and entry.itemType then
				sold[entry.itemType] = true
			end
		end
		if next(sold) == nil then return end
		shopFiltered = true
		for _, list in {bows, crossbows} do
			local kept = {}
			for _, name in list do
				if sold[name] then table.insert(kept, name) end
			end
			if #kept > 0 then
				table.clear(list)
				table.move(kept, 1, #kept, 1, list)
			end
		end
	end

	local function ownedOf(pattern, exclude)
		local best
		for _, item in util.Inventory.Items() do
			local itemType = item and tostring(item.itemType) or ''
			if itemType:find(pattern, 1, true) and not (exclude and itemType:find(exclude, 1, true)) then
				best = itemType
			end
		end
		return best
	end

	local function aboveOwned(families, owned)
		if not owned then return families end
		local index = table.find(families, owned)
		if not index then return families end
		local rest = {}
		for i = index + 1, #families do
			table.insert(rest, families[i])
		end
		return rest
	end

	local function buyFamily(families, owned, currencytable)
		filterFamilies()
		for _, name in aboveOwned(families, owned) do
			local item = util.Shop.Item(name)
			if item and canBuy(item, currencytable) then
				if not util.Shop.Pending(item.itemType) then
					buyItem(item, currencytable)
				end
				return true
			end
		end
		return false
	end

	local function topUpArrows(currencytable)
		if not id or not ArrowAmount then return false end
		return util.Refill.TopUp('arrow', ArrowAmount.Value, id, currencytable, 'AutoBuy')
	end

	local function refreshBowPurchase()
		if not Buy then return end
		local bow, crossbow, arrows = Buy:Has('Bow'), Buy:Has('Crossbow'), Buy:Has('Arrows')
		Functions[3] = (bow or crossbow or arrows) and function(currencytable, shop)
			if not shop then return end
			local bought = false
			if bow and buyFamily(bows, ownedOf('bow', 'crossbow'), currencytable) then bought = true end
			if crossbow and buyFamily(crossbows, ownedOf('crossbow'), currencytable) then bought = true end
			if arrows then
				local armed = bought or ownedOf('bow') ~= nil
				if armed and topUpArrows(currencytable) then bought = true end
			end
			return bought
		end or nil
	end

	AutoBuy = vape.Categories.Inventory:CreateModule({
		Name = 'AutoBuy',
		Function = function(callback)
			if callback then					util.Queue.Await()
				if BedwarsCheck.Enabled and not store.queueType:find('bedwars') then return end

				local lastupgrades
				AutoBuy:Clean(vapeEvents.InventoryAmountChanged.Event:Connect(function()
					
					
					
					npctick = math.min(npctick, tick())
				end))

				repeat
					local npc, shop, upgrades, newid = getShopNPC()
					id = newid
					if GUI.Enabled and not util.Shop.BuyScreenOpen() then
						npc = nil
					end

					if npc and lastupgrades ~= upgrades then
						npctick = tick()
						lastupgrades = upgrades
					end

					if npc and npctick <= tick() and store.matchState ~= 2 and store.shopLoaded then
						local currencytable = {}
						local waitcheck
						for _, tab in Callbacks do
							for _, callback in tab do
								local ok, res = pcall(callback, currencytable, shop, upgrades)
								if ok and res then
									waitcheck = true
								end
							end
						end
						
						
						
						
						npctick = tick() + (waitcheck and 0.4 or 0.5)
					end

					task.wait(0.1)
				until not AutoBuy.Enabled
			else
				npctick = tick()
			end
		end,
		Tooltip = 'Buys items for you near the shop'
	})

	local function buySword(currencytable, shop)
		if not shop then return end

		if store.equippedKit == 'dasher' then
			swords = {
				[1] = 'wood_dao',
				[2] = 'stone_dao',
				[3] = 'iron_dao',
				[4] = 'diamond_dao',
				[5] = 'emerald_dao'
			}
		elseif store.equippedKit == 'ice_queen' then
			swords[5] = 'ice_sword'
		elseif store.equippedKit == 'ember' then
			swords[5] = 'infernal_saber'
		elseif store.equippedKit == 'lumen' then
			swords[5] = 'light_sword'
		end

		return buyTool(store.tools.sword, swords, currencytable)
	end

	local function buyArmor(currencytable, shop)
		if not shop then return end
		local currentarmor = store.inventory.inventory.armor[2] ~= 'empty' and store.inventory.inventory.armor[2] or getBestArmor(1)
		currentarmor = currentarmor and currentarmor.itemType or 'none'
		return buyTool({itemType = currentarmor}, armors, currencytable)
	end

	local function buyAxe(currencytable, shop)
		if not shop then return end
		return buyTool(store.tools.wood or {itemType = 'none'}, axes, currencytable)
	end

	local function buyPickaxe(currencytable, shop)
		if not shop then return end
		return buyTool(store.tools.stone, pickaxes, currencytable)
	end

	local function applyBuy()
		Functions[1] = Buy:Has('Sword') and buySword or nil
		Functions[2] = Buy:Has('Armour') and buyArmor or nil
		Functions[4] = Buy:Has('Axe') and buyAxe or nil
		Functions[5] = Buy:Has('Pickaxe') and buyPickaxe or nil
		refreshBowPurchase()
	end

	Buy = AutoBuy:CreateMultiDropdown({
		Name = 'Buy',
		List = {'Sword', 'Armour', 'Bow', 'Crossbow', 'Arrows', 'Axe', 'Pickaxe'},
		Default = {'Armour'},
		Function = function()
			npctick = tick()
			applyBuy()
		end,
		Tooltip = 'What it buys'
	})
	ArrowAmount = AutoBuy:CreateSlider({
		Name = 'Arrow amount',
		Min = 8,
		Max = 256,
		Default = 32,
		Darker = true,
		Visible = function() return Buy:Has('Arrows') end,
		Tooltip = 'How many arrows to keep'
	})
	applyBuy()
	BedwarsCheck = AutoBuy:CreateToggle({
		Name = 'Only Bedwars',
		Function = function()
			if AutoBuy.Enabled then
				AutoBuy:Toggle()
				AutoBuy:Toggle()
			end
		end,
		Default = true
	})
	GUI = AutoBuy:CreateToggle({Name = 'GUI check'})
	SmartCheck = AutoBuy:CreateToggle({
		Name = 'Smart check',
		Default = true,
		Tooltip = 'Buys iron armour before iron axe'
	})
	AutoBuy:CreateTextList({
		Name = 'Item',
		Placeholder = 'priority/item/amount/after',
		Function = function(list)
			table.clear(Custom)
			table.clear(CustomPost)
			for _, entry in list do
				local tab = entry:split('/')
				local ind = tonumber(tab[1])
				if ind then
					(tab[4] and CustomPost or Custom)[ind] = function(currencytable, shop)
						if not shop then return end

						local v = util.Shop.Item(tab[2])
						if v then
							local item = getItem(tab[2] == 'wool_white' and bedwars.Shop.getTeamWool(lplr:GetAttribute('Team')) or tab[2])
							item = (item and tonumber(tab[3]) - item.amount or tonumber(tab[3])) // v.amount
							if item > 0 and not util.Shop.Pending(v.itemType) and canBuy(v, currencytable, item) then
								for _ = 1, item do
									buyItem(v, currencytable)
								end
								return true
							end
						end
					end
				end
			end
		end
	})
end)

-- ===== Inventory/AutoChestSplit.lua =====
run(function()
	local v2 = httpService
	local v3 = playersService
	local v4 = replicatedStorage
	local v5 = runService
	local v6 = inputService
	local v7 = tweenService
	local v8 = collectionService
	local v9 = guiService
	local v10 = game:GetService('TeleportService')
	local obj = debug
	local currentCamera = gameCamera
	local localPlayer = lplr
	local entity = entitylib
	local getfontbounds = getfontsize
	local getvapeasset = getcustomasset

		local v12 = nil
		local v13 = nil
		local v14 = nil
		local v15 = nil
		local v16 = nil
		local n = 0

		local function fn5(arg)
			for _, v17 in v8:GetTagged("personal-chest") do
				local primaryPart = not v17:IsA("Model") and v17 or v17.PrimaryPart or v17:FindFirstChildWhichIsA("BasePart", true)
				if primaryPart and (primaryPart.Position - arg).Magnitude <= v14.Value then
					return primaryPart
				end
			end

			return nil
		end

		local function fn6(arg)
			local attribute = localPlayer:GetAttribute("Team")
			local huge = math.huge
			local v17 = nil

			for _, v18 in v8:GetTagged("team-crate") do
				local primaryPart = not v18:IsA("Model") and v18 or v18.PrimaryPart or v18:FindFirstChildWhichIsA("BasePart", true)
				local magnitude = primaryPart and (primaryPart.Position - arg).Magnitude or math.huge

				if magnitude < huge then
					huge = magnitude
					v17 = v18
				end
			end

			return v17 ~= nil and v17:GetAttribute("Team") ~= attribute
		end

		local function fn7()
			local inventories = v4:FindFirstChild("Inventories")
			local v17

			if inventories then
				local findFirstChild = inventories.FindFirstChild
				local str = ("%*_personal"):format(localPlayer.Name)
				v17 = findFirstChild(inventories, str)
			else
				v17 = inventories
			end

			local v18 = v17 or nil
			if not v18 then
				return
			end

			for _, v19 in v13.ListEnabled, nil, nil do
				local v20 = getItem(v19)
				local flag

				if v20 then
					flag = (v20.amount or 1) >= v15.Value
				else
					flag = v20
				end

				if flag then
					task.spawn(function()
						bedwars.Client:GetNamespace("Inventory"):Get("ChestGiveItem"):CallServer(v18, v20.tool)
					end)
				end
			end
		end

		local v17

		v12 = vape.Categories.Inventory:CreateModule({
			Name = "AutoChestSplit",
			Function = function(arg)
				if arg then
					n = 0

					while true do
						task.wait()
						if not (store.matchState ~= 0 or not v12.Enabled) then
							continue
						end
						break
					end

					if not v12.Enabled then
						return
					end

					while true do
						if entity.isAlive and tick() >= n and #v13.ListEnabled > 0 then
							local position = entity.character.RootPart.Position

							if fn5(position) and (not v16.Enabled or fn6(position)) then
								local value = v17.Value
								n = tick() + value
								fn7()
							end
						end

						task.wait(0.1)
						if v12.Enabled then
							continue
						end
						break
					end
				end
			end,
			Tooltip = 'Banks the split in your personal chest when you reach one',
		})

		v13 = v12:CreateMultiDropdown({ Name = "Items", List = { "iron", "diamond", "emerald" }, Default = { "diamond", "emerald" }, Tooltip = "What counts as the split" })

		v14 = v12:CreateSlider({
			Name = "Range",
			Min = 1,
			Max = 18,
			Default = 18,
			Suffix = function(arg)
				return arg <= 1 and "stud" or "studs"
			end,
			Tooltip = 'How close to the chest you need to be',
		})

		v15 = v12:CreateSlider({
			Name = "Minimum",
			Min = 1,
			Max = 64,
			Default = 1,
			Tooltip = 'Only acts when you hold at least this many',
		})

		v16 = v12:CreateToggle({
			Name = "Enemy base only",
			Default = true,
			Tooltip = "Only banks at a chest that is closer to their generator than yours",
		})

		v17 = v12:CreateSlider({ Name = "Delay", Min = 0, Max = 5, Decimal = 10, Default = 0.5, Suffix = "seconds" })
	end)

-- ===== Inventory/AutoConsume.lua =====
run(function()
	local AutoConsume
	local Health
	local Consume
	local MushroomKinds
	local MushroomRange
	local MushroomAnimation
	local Items
	local Combat
	local Delay

	local HEALTH_PRIORITY = {'golden_apple', 'big_apple', 'orange', 'apple'}
	local consumeCooldown = {}
	local CONSUME_COOLDOWN = 0.4

	local function itemMeta(id)
		return bedwars.ItemMeta and bedwars.ItemMeta[id] or nil
	end

	local function isConsumable(id)
		local meta = itemMeta(id)
		return meta and type(meta.consumable) == 'table' or false
	end

	local function classOf(id)
		if not isConsumable(id) then return nil end
		local lower = id:lower()
		local consumable = itemMeta(id).consumable or {}
		local effect = consumable.statusEffect and tostring(consumable.statusEffect.statusEffectType or ''):lower() or ''
		if lower:find('shield', 1, true) or effect:find('shield') then return 'shield' end
		if lower:find('mushroom', 1, true) then return 'mushroom' end
		if lower:find('speed', 1, true) or effect:find('speed') then return 'speed' end
		if lower:find('apple', 1, true) or lower:find('orange', 1, true) or lower:find('heal', 1, true) or consumable.requiresMissingHealth or effect:find('health') then return 'health' end
		return 'other'
	end

	local function inventoryItems()
		local inventory = store.inventory and store.inventory.inventory
		return inventory and inventory.items or {}
	end

	local function pick(predicate)
		local chosen
		for _, item in inventoryItems() do
			if item and item.itemType and predicate(item.itemType) then
				chosen = chosen or item
			end
		end
		return chosen
	end

	local function best(class)
		if class == 'health' then
			for _, name in HEALTH_PRIORITY do
				local found = pick(function(id) return id == name end)
				if found then return found end
			end
			return pick(function(id) return classOf(id) == 'health' end)
		end
		return pick(function(id) return classOf(id) == class end)
	end

	local function use(item, key)
		if not item or not item.tool then return false end
		local now = os.clock()
		key = key or item.itemType
		if (consumeCooldown[key] or 0) > now then return false end
		consumeCooldown[key] = now + CONSUME_COOLDOWN
		return pcall(function()
			bedwars.Client:Get(remotes.ConsumeItem):CallServer({item = item.tool})
		end)
	end

	local function consumeClass(class)
		return use(best(class), class)
	end

	local function healthPercent(character)
		local health = tonumber(character:GetAttribute('Health')) or 0
		local maxHealth = tonumber(character:GetAttribute('MaxHealth')) or 100
		return maxHealth > 0 and (health / maxHealth) * 100 or 100
	end

	local function check(attribute)
		if not entitylib.isAlive or not lplr.Character then return end
		local character = lplr.Character

		if not attribute or attribute:find('Health') then
			if healthPercent(character) <= Health.Value then
				local used = Consume:Has('Health items') and consumeClass('health')
				if not used and Consume:Has('Mushrooms') then
					consumeClass('mushroom')
				end
			end
		end

		if Consume:Has('Shield potions') and (not attribute or attribute:find('Shield')) then
			if (tonumber(character:GetAttribute('Shield_POTION')) or 0) == 0 then
				consumeClass('shield')
			end
		end

		if Consume:Has('Speed potions') and (not attribute or attribute == 'StatusEffect_speed') then
			if not character:GetAttribute('StatusEffect_speed') then
				consumeClass('speed')
			end
		end

		if Consume:Has('Other consumables') then
			for _, item in inventoryItems() do
				local id = item and item.itemType
				local meta = id and itemMeta(id)
				local effect = meta and meta.consumable and meta.consumable.statusEffect
				local effectType = effect and effect.statusEffectType
				if effectType and classOf(id) == 'other' and not character:GetAttribute('StatusEffect_'..tostring(effectType)) then
					use(item, id)
				end
			end
		end
	end

	local MUSHROOM_KINDS = {[0] = 'heal', [1] = 'shield', [2] = 'speed', [3] = 'dizzy'}
	local eaten = setmetatable({}, {__mode = 'k'})

	local function wantsMushroom(kind, character)
		local name = MUSHROOM_KINDS[kind]
		if not name then return false end
		local listed = false
		for _, v in MushroomKinds.ListEnabled do
			local entry = v:lower()
			if entry == name or (name == 'heal' and entry == 'health') then
				listed = true
				break
			end
		end
		if not listed then return false end
		if name == 'heal' then
			return healthPercent(character) <= Health.Value
		end
		return true
	end

	local function forestLoop()
		repeat
			local character = lplr.Character
			if Consume:Has('Forest mushrooms') and entitylib.isAlive and character then
				local origin = entitylib.character.RootPart.Position
				local now = tick()
				for _, v in collectionService:GetTagged('forest_environment_plant') do
					local part = v:IsA('Model') and v.PrimaryPart or v
					local id = v:GetAttribute('Id')
					if id and part and now > (eaten[v] or 0) and (origin - part.Position).Magnitude <= MushroomRange.Value and wantsMushroom(v:GetAttribute('MushroomType'), character) then
						eaten[v] = now + 1
						if MushroomAnimation.Enabled then
							pcall(function()
								bedwars.GameAnimationUtil:playAnimation(character, bedwars.AnimationType.PUNCH)
								bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.FP_USE_ITEM)
							end)
						end
						bedwars.Handler:Get('CollectCollectableEntity'):Fire('SendToServer', {
							id = id,
							collectableName = v.Name
						})
					end
				end
				task.wait(0.1)
			else
				task.wait(0.5)
			end
		until not AutoConsume.Enabled
	end

	local function buffLoop()
		repeat
			local character = lplr.Character
			if Consume:Has('Buff list') and entitylib.isAlive and character and store.matchState == 1 and not isCasting() and (not Combat.Enabled or (workspace:GetServerTimeNow() - (character:GetAttribute('LastDamageTakenTime') or 0)) < 6) then
				for _, v in Items.ListEnabled do
					local item = getItem(v)
					local consumable = item and itemMeta(v) and itemMeta(v).consumable
					if consumable then
						local effect = consumable.statusEffect and consumable.statusEffect.statusEffectType or ({v:gsub('_potion', '')})[1]
						if not character:GetAttribute(`StatusEffect_{effect}`) then
							bedwars.Handler:Get('ConsumeItem'):Fire('CallServerAsync', {item = item.tool})
							task.wait(consumable.consumeTime or 1)
							break
						end
					end
				end
			end
			task.wait(Delay.Value)
		until not AutoConsume.Enabled
	end

	AutoConsume = vape.Categories.Inventory:CreateModule({
		Name = 'AutoConsume',
		Function = function(callback)
			if callback then
				AutoConsume:Clean(vapeEvents.InventoryAmountChanged.Event:Connect(check))
				AutoConsume:Clean(vapeEvents.AttributeChanged.Event:Connect(function(attribute)
					if attribute:find('Shield') or attribute:find('Health') or attribute == 'StatusEffect_speed' then
						check(attribute)
					end
				end))
				check()
				AutoConsume:Clean(task.spawn(buffLoop))
				AutoConsume:Clean(task.spawn(forestLoop))
			else
				table.clear(eaten)
			end
		end,
		Tooltip = 'Uses healing, shield, speed and utility items for you'
	})
	Health = AutoConsume:CreateSlider({
		Name = 'Health Percent',
		Min = 1,
		Max = 99,
		Default = 70,
		Suffix = '%'
	})
	Consume = AutoConsume:CreateMultiDropdown({
		Name = 'Consume',
		List = {'Health items', 'Mushrooms', 'Shield potions', 'Speed potions', 'Other consumables', 'Forest mushrooms', 'Buff list'},
		Default = {'Health items', 'Shield potions', 'Speed potions'},
		Tooltip = 'What it uses'
	})
	MushroomKinds = AutoConsume:CreateMultiDropdown({
		Name = 'Mushroom kinds',
		List = {'Speed', 'Heal', 'Shield', 'Dizzy'},
		Default = {'Speed', 'Heal', 'Shield'},
		Darker = true,
		Visible = function() return Consume:Has('Forest mushrooms') end,
		Tooltip = 'Which forest mushrooms to eat'
	})
	MushroomRange = AutoConsume:CreateSlider({
		Name = 'Mushroom range',
		Min = 1,
		Max = 12,
		Default = 10,
		Darker = true,
		Visible = function() return Consume:Has('Forest mushrooms') end,
		Suffix = function(val)
			return val <= 1 and 'stud' or 'studs'
		end,
		Tooltip = 'How close something must be to collect it'
	})
	MushroomAnimation = AutoConsume:CreateToggle({
		Name = 'Pickup animation',
		Default = true,
		Darker = true,
		Visible = function() return Consume:Has('Forest mushrooms') end,
		Tooltip = 'Plays the pickup animation'
	})
	Items = AutoConsume:CreateItemPicker({
		Name = 'Items',
		Multi = true,
		Items = bedwars.itemPickerList(function(_, meta)
			return type(meta.consumable) == 'table'
		end),
		Default = {'fury_potion', 'crit_star', 'vitality_star', 'pie'},
		Darker = true,
		Visible = function() return Consume:Has('Buff list') end,
		Tooltip = 'Items to use, such as fury_potion or pie'
	})
	Combat = AutoConsume:CreateToggle({
		Name = 'In combat only',
		Darker = true,
		Visible = function() return Consume:Has('Buff list') end,
		Tooltip = 'Only uses the listed items when recently hit'
	})
	Delay = AutoConsume:CreateSlider({
		Name = 'Delay',
		Min = 0.1,
		Max = 5,
		Default = 0.5,
		Decimal = 10,
		Darker = true,
		Visible = function() return Consume:Has('Buff list') end,
		Suffix = 'seconds'
	})
end)

-- ===== Inventory/AutoFish.lua =====
run(function()
	local AutoFish
	local Show
	local Blacklist
	local Minigame
	local MinigameMode = {}
	local CompleteDelay = {}
	local Reaction = {}
	local Clicks = {}
	local Cast
	local CastDelay = {}
	local rejects = {}
	
	local old
	
	local function getCastSpot()
		local localPosition = entitylib.character.RootPart.Position
		local open
	
		for dist = 5, 17, 3 do
			for angle = 0, 330, 30 do
				local spot = localPosition + (CFrame.Angles(0, math.rad(angle), 0).LookVector * dist)
				local ray = workspace:Raycast(spot + Vector3.new(0, 8, 0), Vector3.new(0, -26, 0), store.airRay)
				local check = ray and ray.Position or spot
				local rejected = false
				for _, v in rejects do
					if (v - check).Magnitude < 4 then
						rejected = true
						break
					end
				end
	
				if not ray then
					if not open and not rejected then
						open = spot
					end
				elseif ray.Material == Enum.Material.Water and not rejected then
					return ray.Position
				end
			end
		end
		return open
	end
	
	local function playMinigame()
		local util = bedwars.FishermanUtil
		if not util or util.startingMarkerIncrementSpeed == nil then return end
		local marker, zone
		local deadline = tick() + 3
		repeat
			for _, v in lplr.PlayerGui:GetDescendants() do
				if v.Name == 'Marker' and v.Parent and v.Parent.Name == 'Minigame' then
					local found = v.Parent:FindFirstChild('FishZone')
					if found then
						marker, zone = v, found
						break
					end
				end
			end
			if not marker then task.wait(0.1) end
		until marker or tick() > deadline
		if not marker then return end
	
		local speed, aim = util.startingMarkerIncrementSpeed, 0
		repeat
			if not marker.Parent or not zone.Parent then return end
	
			local width = marker.AbsoluteSize.X
			local center = marker.AbsolutePosition.X + (width / 2)
			local delta = ((zone.AbsolutePosition.X + (zone.AbsoluteSize.X / 2) + aim) - center) / math.max(width, 1)
			if delta > 0.2 then
				tweenService:Create(marker, TweenInfo.new(math.max(speed, util.holdMinimumMarkerIncrementSpeed), Enum.EasingStyle.Linear), {
					Position = UDim2.new(math.min(marker.Position.X.Scale + util.markerIncrementAmount, 1 - marker.Size.X.Scale), 0, 0.5, 0)
				}):Play()
				speed -= 0.01
				task.wait(0.05)
			elseif delta < -0.2 then
				tweenService:Create(marker, TweenInfo.new(util.totalDecaySpeedSec * (marker.Position.X.Scale + marker.Size.X.Scale), Enum.EasingStyle.Linear), {
					Position = UDim2.new(0, 2, 0.5, 0)
				}):Play()
				speed = util.startingMarkerIncrementSpeed
				aim = (math.random() - 0.5) * width * 0.1
				task.wait(Reaction:GetRandomValue())
			else
				local period = 1 / Clicks:GetRandomValue()
				tweenService:Create(marker, TweenInfo.new(math.max(util.startingMarkerIncrementSpeed, util.holdMinimumMarkerIncrementSpeed), Enum.EasingStyle.Linear), {
					Position = UDim2.new(math.min(marker.Position.X.Scale + util.markerIncrementAmount, 1 - marker.Size.X.Scale), 0, 0.5, 0)
				}):Play()
				task.wait(period * (0.35 + (math.random() * 0.25)))
				tweenService:Create(marker, TweenInfo.new(util.totalDecaySpeedSec * (marker.Position.X.Scale + marker.Size.X.Scale), Enum.EasingStyle.Linear), {
					Position = UDim2.new(0, 2, 0.5, 0)
				}):Play()
				speed = util.startingMarkerIncrementSpeed
				aim = (math.random() - 0.5) * width * 0.1
				task.wait(period * (0.35 + (math.random() * 0.25)))
			end
		until not AutoFish.Enabled or not Minigame.Enabled
	end
	
	AutoFish = vape.Categories.Inventory:CreateModule({
		Name = 'AutoFish',
		Function = function(callback)
			if callback then
				old = bedwars.FishingMinigameController.startMinigame
				bedwars.FishingMinigameController.startMinigame = function(...)
					if Minigame.Enabled and MinigameMode.Value == 'Instant' then
						task.wait(CompleteDelay:GetRandomValue())
						return select(3, ...)({win = true})
					end
	
					local call = (old or bedwars.FishingMinigameController.startMinigame)(...)
					if Minigame.Enabled then
						task.spawn(playMinigame)
					end
					return call
				end
	
				AutoFish:Clean(bedwars.Handler:Get('FishFound').Remote:Connect(function(data)
					local reroll = #Blacklist.ListEnabled > 0
					for _, v in data.dropData.drops do
						local amount = tonumber(v.amount) or 0
						if Show.Enabled then
							local itemDisplay = bedwars.ItemMeta[v.itemType] and bedwars.ItemMeta[v.itemType].displayName or v.itemType
							notif('AutoFish', `You can get {amount} {itemDisplay:lower()}{amount >= 2 and 's' or ''} on ur next fish`, 20, 'info')
						end
						if not table.find(Blacklist.ListEnabled, v.itemType) then
							reroll = false
						end
					end
	
					if reroll and entitylib.isAlive then
						lplr.Character.Humanoid.Jump = true
					end
				end))
				repeat
					local bait
					for _, v in workspace:GetChildren() do
						if v.Name == 'fisherman_bobber' and v:GetAttribute('ProjectileShooter') == lplr.UserId then
							bait = v
							break
						end
					end
	
					if entitylib.isAlive and Cast.Enabled and (store.hand.tool and store.hand.tool.Name == 'fishing_rod') and not bait then
						local spot = getCastSpot()
						if not spot and #rejects > 0 then
							table.clear(rejects)
							spot = getCastSpot()
						end
	
						if spot then
							task.wait(CastDelay:GetRandomValue())
							if AutoFish.Enabled then
								local item = bedwars.FishingRodController:getHandItem()
								if item and not bedwars.FishingRodController.projectileHandler and bedwars.FishingRodController:canLaunch() then
									bedwars.FishingRodController:beginHolding(item, nil, bedwars.FishingRodController.aimingMaid, false)
									task.wait()
									local handler = bedwars.FishingRodController.projectileHandler
									if handler then
										local meta = bedwars.ProjectileMeta.fisherman_bobber
										local origin = (bedwars.ProjectileController:getLaunchPosition(item.tool) or entitylib.character.RootPart.Position) + handler.fromPositionOffset
										handler.targetPoint = prediction.SolveTrajectory(origin, meta.launchVelocity, meta.gravitationalAcceleration, spot, Vector3.zero, workspace.Gravity, 0, 0, nil, false, spot, nil, nil, true) or spot
									end
									bedwars.FishingRodController:releaseChargeInput(bedwars.FishingRodController.aimingMaid, function()
										return true
									end, nil)
								end
	
								task.wait(2.5)
								local cast
								for _, v in workspace:GetChildren() do
									if v.Name == 'fisherman_bobber' and v:GetAttribute('ProjectileShooter') == lplr.UserId then
										cast = v
										break
									end
								end
								if not cast or not cast:GetAttribute('WaitingForFish') then
									table.insert(rejects, spot)
								end
							end
						end
					end
					task.wait(0.1)
				until not AutoFish.Enabled
			else
				table.clear(rejects)
				if old then
					bedwars.FishingMinigameController.startMinigame = old
					old = nil
				end
			end
		end,
		Tooltip = 'Fishes for you with the fishing rod'
	})
	
	Blacklist = AutoFish:CreateTextList({
		Name = 'Blacklisted loot',
		Default = {'iron'},
		Tooltip = 'Cancels the catch when every drop is blacklisted'
	})
	Show = AutoFish:CreateToggle({
		Name = 'Show loot drops',
		Tooltip = 'Tells you what your next catches will be'
	})
	Minigame = AutoFish:CreateGroup({
		Name = 'Auto Minigame',
		Function = function(callback)
			if MinigameMode and MinigameMode.Object then
				if CompleteDelay and MinigameMode then CompleteDelay.Object.Visible = callback and MinigameMode.Value == 'Instant' end
				if MinigameMode and Reaction then Reaction.Object.Visible = callback and MinigameMode.Value == 'Legit' end
				if Clicks and MinigameMode then Clicks.Object.Visible = callback and MinigameMode.Value == 'Legit' end
			end
		end,
		Default = true,
		Tooltip = 'Automatically completes the minigame'
	})
	MinigameMode = Minigame:CreateDropdown({
		Name = 'Minigame mode',
		List = {'Instant', 'Legit'},
		Darker = true,
		Function = function(value)
			if CompleteDelay.Object then
				CompleteDelay.Object.Visible = Minigame.Enabled and value == 'Instant'
				Reaction.Object.Visible = Minigame.Enabled and value == 'Legit'
				Clicks.Object.Visible = Minigame.Enabled and value == 'Legit'
			end
		end,
		Tooltip = 'Instant wins at once, Legit plays it out'
	})
	CompleteDelay = AutoFish:CreateTwoSlider({
		Name = 'Complete delay',
		Min = 0,
		Max = 25,
		Decimal = 5,
		DefaultMin = 0.1,
		DefaultMax = 0.9,
		Darker = true
	})
	Reaction = AutoFish:CreateTwoSlider({
		Name = 'Reaction',
		Min = 0,
		Max = 1,
		Decimal = 100,
		DefaultMin = 0.06,
		DefaultMax = 0.19,
		Darker = true,
		Visible = false,
		Tooltip = 'How long it takes to react to the fish moving'
	})
	Clicks = AutoFish:CreateTwoSlider({
		Name = 'Clicks',
		Min = 3,
		Max = 20,
		DefaultMin = 8,
		DefaultMax = 13,
		Darker = true,
		Visible = false,
		Suffix = 'cps',
		Tooltip = 'How fast it taps to keep the bar on the fish'
	})
	Cast = AutoFish:CreateGroup({
		Name = 'Auto Cast',
		Function = function(callback)
			if CastDelay.Object then
			end
		end,
		Tooltip = 'Finds a spot to fish and casts there, wherever your camera looks'
	})
	CastDelay = Cast:CreateTwoSlider({
		Name = 'Cast delay',
		Min = 0,
		Max = 5,
		Decimal = 5,
		DefaultMin = 0.3,
		DefaultMax = 1.2,
		Darker = true
	})
end)

