				slot.BorderSizePixel = 0
				slot.Parent = hotbar
			end
			hotbar.MouseButton1Click:Connect(function()
				local ind = table.find(optionapi.Hotbars, hotbardata)
				if ind == optionapi.Selected then
					vape.gui.ScaledGui.ClickGui.Visible = false
					optionapi.Window.Visible = true
					for i = 1, 9 do
						optionapi.Window['Slot'..i].ImageLabel.Image = hotbardata.Hotbar[tostring(i)] and bedwars.getIcon({itemType = hotbardata.Hotbar[tostring(i)]}, true) or ''
					end
				else
					if optionapi.Hotbars[optionapi.Selected] then
						optionapi.Hotbars[optionapi.Selected].Object.BackgroundColor3 = uipallet.Main
					end
					hotbar.BackgroundColor3 = color.Light(uipallet.Main, 0.034)
					optionapi.Selected = ind
				end
			end)
			local close = Instance.new('ImageButton')
			close.Name = 'Close'
			close.Size = UDim2.fromOffset(16, 16)
			close.Position = UDim2.new(1, -23, 0, 6)
			close.BackgroundColor3 = Color3.new(1, 1, 1)
			close.BackgroundTransparency = 1
			close.Image = getcustomasset('ElevateV4/assets/new/closemini.png')
			close.ImageColor3 = color.Light(uipallet.Text, 0.2)
			close.ImageTransparency = 0.5
			close.AutoButtonColor = false
			close.Parent = hotbar
			local closecorner = Instance.new('UICorner')
			closecorner.CornerRadius = UDim.new(1, 0)
			closecorner.Parent = close
			close.MouseEnter:Connect(function()
				close.ImageTransparency = 0.3
				tween:Tween(close, TweenInfo.new(0.2), {
					BackgroundTransparency = 0.6
				})
			end)
			close.MouseLeave:Connect(function()
				close.ImageTransparency = 0.5
				tween:Tween(close, TweenInfo.new(0.2), {
					BackgroundTransparency = 1
				})
			end)
			close.MouseButton1Click:Connect(function()
				local ind = table.find(self.Hotbars, hotbardata)
				local obj = self.Hotbars[self.Selected]
				local obj2 = self.Hotbars[ind]
				if obj and obj2 then
					obj2.Object:ClearAllChildren()
					obj2.Object:Destroy()
					table.remove(self.Hotbars, ind)
					self.Selected = table.find(self.Hotbars, obj) or 1
				end
			end)
		end
	
		api.Options.HotbarList = optionapi
	
		return optionapi
	end
	
	local function sortCallback()
		if Active then return end
		Active = true
		local wanted = {}
		for i, v in List.Hotbars[List.Selected] and List.Hotbars[List.Selected].Hotbar or {} do
			wanted[i] = v
			if v == 'diamond_sword' then
				local sword = store.tools.sword
				wanted[i] = sword and sword.itemType or 'wood_sword'
			elseif v == 'diamond_pickaxe' then
				local pickaxe = store.tools.stone
				wanted[i] = pickaxe and pickaxe.itemType or 'wood_pickaxe'
			elseif v == 'diamond_axe' then
				local axe = store.tools.wood
				wanted[i] = axe and axe.itemType or 'wood_axe'
			elseif v == 'wood_bow' then
				local bow = getBow()
				wanted[i] = bow and bow.itemType or 'wood_bow'
			elseif v == 'wool_white' then
				local clone = table.clone(store.inventory.inventory.items)
				table.sort(clone, function(a, b)
					return a.amount < b.amount
				end)
				for _, v2 in clone do
					local block = bedwars.ItemMeta[v2.itemType].block
					if block and not block.seeThrough then
						wanted[i] = v2.itemType
						break
					end
				end
			end
		end
	
		for _, v in store.inventory.inventory.items do
			local slot
			for i2, v2 in wanted do
				if v.itemType == v2 then
					slot = tonumber(i2)
					break
				end
			end
	
			if slot then
				local olditem = store.inventory.hotbar[slot]
				if olditem.item and olditem.item.itemType == v.itemType then continue end
				if olditem.item then
					bedwars.Store:dispatch({
						type = 'InventoryRemoveFromHotbar',
						slot = slot - 1
					})
					vapeEvents.InventoryChanged.Event:Wait()
				end
	
				local newslot
				for i, v2 in store.inventory.hotbar do
					if v2.item and v2.item.itemType == v.itemType then
						newslot = i - 1
						break
					end
				end
	
				if newslot then
					bedwars.Store:dispatch({
						type = 'InventoryRemoveFromHotbar',
						slot = newslot
					})
					vapeEvents.InventoryChanged.Event:Wait()
					if olditem.item then
						local swap
						for _, v2 in store.inventory.inventory.items do
							if v2.itemType == olditem.item.itemType then
								swap = v2
								break
							end
						end
						bedwars.Store:dispatch({
							type = 'InventoryAddToHotbar',
							item = swap,
							slot = newslot
						})
						vapeEvents.InventoryChanged.Event:Wait()
					end
				end
	
				local held
				for _, v2 in store.inventory.inventory.items do
					if v2.itemType == v.itemType then
						held = v2
						break
					end
				end
				bedwars.Store:dispatch({
					type = 'InventoryAddToHotbar',
					item = held,
					slot = slot - 1
				})
				vapeEvents.InventoryChanged.Event:Wait()
			elseif Clear.Enabled then
				local newslot
				for i, v2 in store.inventory.hotbar do
					if v2.item and v2.item.itemType == v.itemType then
						newslot = i - 1
						break
					end
				end
	
				if newslot then
					bedwars.Store:dispatch({
						type = 'InventoryRemoveFromHotbar',
						slot = newslot
					})
					vapeEvents.InventoryChanged.Event:Wait()
				end
			end
		end
	
		Active = false
	end
	
	AutoHotbar = vape.Categories.Inventory:CreateModule({
		Name = 'AutoHotbar',
		Function = function(callback)
			if callback then
				task.spawn(sortCallback)
				if Mode.Value == 'On Key' then
					AutoHotbar:Toggle()
					return
				end
	
				AutoHotbar:Clean(vapeEvents.InventoryAmountChanged.Event:Connect(sortCallback))
			end
		end,
		Tooltip = 'Arranges your hotbar the way you set it'
	})
	
	Mode = AutoHotbar:CreateDropdown({
		Name = 'Activation',
		List = {'Toggle', 'On Key'},
		Function = function()
			if AutoHotbar.Enabled then
				AutoHotbar:Toggle()
				AutoHotbar:Toggle()
			end
		end
	})
	Clear = AutoHotbar:CreateToggle({Name = 'Clear Hotbar'})
	List = AutoHotbar:CreateHotbarList({})
end)

-- ===== Inventory/AutoRefill.lua =====
run(function()
	local util = vape.Libraries.bedwarsutil

	local AutoRefill
	local Whitelist
	local Fighting

	local SLIDER_MAX = 256

	local sliders = {}
	local order = {}
	local active = {}

	local defaults = {
		arrow = {Min = 16, Target = 32},
		wool = {Min = 16, Target = 64},
	}
	local fallback = {Min = 16, Target = 32}

	local function refillPass(shopId)
		local currencytable = {}
		local bought = false
		for _, family in order do
			local slider = sliders[family]
			if active[family] and slider then
				local minimum = tonumber(slider.ValueMin) or 0
				local target = tonumber(slider.ValueMax) or 0
				if minimum > 0 and util.Refill.Held(family) < minimum then
					if util.Refill.TopUp(family, target, shopId, currencytable, 'AutoRefill') then
						bought = true
					end
				end
			end
		end
		return bought
	end

	local function syncItems()
		local list = Whitelist and Whitelist.List or {}
		local enabled = Whitelist and Whitelist.ListEnabled or {}
		table.clear(active)

		for _, raw in list do
			local family = util.Families.Name(raw)
			if family then
				if not table.find(order, family) then
					table.insert(order, family)
				end
				if not sliders[family] then
					local preset = defaults[family] or fallback
					sliders[family] = AutoRefill:CreateTwoSlider({
						Name = util.Families.Label(family),
						Min = 0,
						Max = SLIDER_MAX,
						Decimal = 1,
						DefaultMin = preset.Min,
						DefaultMax = preset.Target,
						Darker = true,
						Tooltip = 'Buys up to the upper amount when you drop below the lower one'
					})
				end
				if table.find(enabled, raw) then
					active[family] = true
				end
			end
		end

		for family, slider in sliders do
			if slider.Object then
				slider.Object.Visible = active[family] and true or false
			end
		end
	end

	AutoRefill = vape.Categories.Inventory:CreateModule({
		Name = 'AutoRefill',
		Function = function(callback)
			if not callback then return end

			if not util.Queue.Await(AutoRefill) then return end
			util.Refill.ResolveConflict('AutoRefill')

			local nextPass = 0
			repeat
				local fighting = Fighting.Enabled and util.Utils.InCombat()
				local store = getgenv().store
				local blocked = util.Refill.BlockedBy('AutoRefill')
				if not blocked and util.Utils.Alive() and store and store.shopLoaded and store.matchState ~= 2 and not fighting and nextPass <= tick() then
					local shopId = util.Shop.Id('item')
					if shopId then
						local bought = refillPass(shopId)
						if bought then
							util.Refill.Claim('AutoRefill')
						end
						nextPass = tick() + 0.75
					end
				end
				task.wait(util.PollInterval)
			until not AutoRefill.Enabled
		end,
		Tooltip = 'Buys items you are running low on near a shop'
	})

	Whitelist = AutoRefill:CreateTextList({
		Name = 'Whitelist',
		Placeholder = 'Item name...',
		Default = {'arrow', 'wool'},
		Function = function()
			syncItems()
		end,
		Tooltip = 'Items to keep topped up'
	})

	syncItems()

	Fighting = AutoRefill:CreateToggle({
		Name = 'Ignore while fighting',
		Default = true,
		Tooltip = 'Stops refilling during fights'
	})
end)

-- ===== Inventory/AutoSteal.lua =====
run(function()
    
    
    
    
    local util = vape.Libraries.bedwarsutil

    local AutoSteal
    local Range, Delay, GUI, Skywars, Chests, Bank
    local Start = 0

    local inv = util.Chest.Remotes
    local getFolder = util.Chest.FolderOf

    
    
    
    local ownPersonalFolder = util.Chest.OwnFolder

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    local function isPersonalFolder(folder)
        if not folder then return false end
        local name = tostring(folder.Name):lower()
        return name:sub(-9) == '_personal' or name == 'personal'
    end

    local function isPersonal(chest)
        return util.Chest.IsPersonal(chest)
    end

    local function lootFolder(folder, items)
        if not folder or isPersonalFolder(folder) then return end
        local own = ownPersonalFolder()
        if own and folder == own then return end
        util.Chest.Observe(folder, function()
            for _, entry in util.Chest.Entries(folder) do
                if util.Chest.Take(folder, entry) and items then
                    table.insert(items, entry.Name)
                end
            end
        end)
    end

    AutoSteal = vape.Categories.Inventory:CreateModule({
        Name = 'AutoSteal',
        Function = function(call)
            if not call then return end
            repeat task.wait() until store.matchState ~= 0 or not AutoSteal.Enabled
            if not AutoSteal.Enabled then return end

            local crates = collection('team-crate', AutoSteal, function(tab, obj)
                task.delay(0, function()
                    if obj:GetAttribute('Team') ~= lplr:GetAttribute('Team') then
                        table.insert(tab, obj)
                    end
                end)
            end)
            local chests = collection('chest', AutoSteal)
            local items = {}

            repeat
                if entitylib.isAlive and store.matchState ~= 2 then
                    local localPosition = entitylib.character.RootPart.Position
                    local chestScreenOpen = bedwars.AppController and bedwars.AppController:isAppOpen('ChestApp') or false
                    local canLoot = GUI.Enabled and chestScreenOpen or not GUI.Enabled and not chestScreenOpen
                    if (tick() - Start) >= Delay.Value and canLoot then
                        for _, v in crates do
                            if not isPersonal(v) and (localPosition - v.Position).Magnitude <= Range.Value then
                                lootFolder(getFolder(v), items)
                            end
                        end

                        if Chests.Enabled and ((not Skywars.Enabled) or (store.queueType and store.queueType:find('skywars'))) then
                            for _, v in chests do
                                if not isPersonal(v) and (localPosition - v.Position).Magnitude <= Range.Value then
                                    lootFolder(getFolder(v), items)
                                end
                            end
                        end

                        local own = Bank.Enabled and #items > 0 and ownPersonalFolder() or nil
                        if own and util.Chest.InRange(Range.Value, localPosition) then
                            util.Chest.Observe(own, function()
                                for _, name in table.clone(items) do
                                    local item = getItem(name)
                                    if item and util.Chest.Give(own, item.tool) then
                                        local index = table.find(items, name)
                                        if index then
                                            table.remove(items, index)
                                        end
                                    end
                                end
                            end)
                        end
                    Start = tick()
                    end
                end
                task.wait(0.1)
            until not AutoSteal.Enabled
        end,
        Tooltip = 'Steals from enemy crates and nearby chests'
    })

    Range = AutoSteal:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 18,
        Default = 18,
        Suffix = util.Studs,
    })
    Delay = AutoSteal:CreateSlider({
        Name = 'Delay',
        Min = 0,
        Max = 1,
        Decimal = 100,
        Suffix = 'seconds',
        Default = 0,
    })
    Chests = AutoSteal:CreateToggle({Name = 'Nearby chests', Default = true, Tooltip = 'Also loots nearby chests'})
    Skywars = AutoSteal:CreateToggle({Name = 'Only Skywars', Tooltip = 'Only loot nearby chests while in Skywars'})
    Bank = AutoSteal:CreateToggle({Name = 'Bank loot', Default = true, Tooltip = 'Deposit stolen loot into your personal chest'})
    GUI = AutoSteal:CreateToggle({
        Name = 'GUI Check',
        Tooltip = 'Only loots while a chest screen is open'
    })
end)

-- ===== Inventory/AutoUpgrade.lua =====
run(function()
	local util = vape.Libraries.bedwarsutil

	local AutoUpgrade

	local SETTLE_TIME = 2

	local catalog = {}
	local toggles = {}
	local pending = {}
	local lastMatchState, lastTeam

	local function liveMeta()
		local module = bedwars.TeamUpgradeUtil
		if type(module) == 'table' and type(module.getTeamUpgradeMetaForQueue) == 'function' then
			local ok, meta = pcall(module.getTeamUpgradeMetaForQueue, store.queueType)
			if ok and type(meta) == 'table' and next(meta) ~= nil then return meta end
		end
		local meta = bedwars.TeamUpgradeMeta
		return type(meta) == 'table' and meta or {}
	end

	local function labelOf(upgrade)
		return upgrade.Name == 'Armor' and 'Protection' or upgrade.Name
	end

	local function liveOffers()
		if not util.Shop.UpgradeScreenOpen() then return nil end
		local app = lplr.PlayerGui:FindFirstChild(util.Shop.UpgradeApp, true)
		if not app then return nil end

		local known, offers, count = {}, {}, 0
		for _, upgrade in catalog do
			known[upgrade.Id] = true
		end
		for _, object in app:GetDescendants() do
			local id = tostring(object.Name):match('^(.+)_ShopItemCard$')
			if id and known[id] and not offers[id] then
				offers[id] = true
				count += 1
			end
		end
		return count > 0 and offers or nil
	end

	local function createToggle(upgrade)
		if toggles[upgrade.Id] then return toggles[upgrade.Id] end
		toggles[upgrade.Id] = AutoUpgrade:CreateToggle({
			Name = 'Buy '..labelOf(upgrade),
			Default = upgrade.Id == 'ARMOR' or upgrade.Id == 'DAMAGE',
			Darker = true,
			Tooltip = 'Buys this upgrade first when you can afford it'
		})
		return toggles[upgrade.Id]
	end

	local function refreshCatalog()
		local list = {}
		for id, upgrade in liveMeta() do
			if type(upgrade) == 'table' and type(upgrade.tiers) == 'table' and #upgrade.tiers > 0 then
				local entry = {
					Id = id,
					Name = tostring(upgrade.name or id),
					Order = tonumber(upgrade.order) or 0,
					Tiers = upgrade.tiers,
					DisabledInQueue = upgrade.disabledInQueue
				}
				table.insert(list, entry)
				createToggle(entry)
			end
		end
		table.sort(list, function(a, b)
			if a.Order ~= b.Order then return a.Order < b.Order end
			return a.Id < b.Id
		end)
		catalog = list
		return list
	end

	local function resetForMatch()
		local team = lplr:GetAttribute('Team')
		if store.matchState ~= lastMatchState or team ~= lastTeam then
			lastMatchState, lastTeam = store.matchState, team
			table.clear(pending)
		end
	end

	local function buyTier(upgrade, tierIndex, diamonds)
		local tier = upgrade.Tiers[tierIndex]
		if type(tier) ~= 'table' then return false end
		if tier.availableOnlyInQueue and not table.find(tier.availableOnlyInQueue, store.queueType) then return false end

		local cost = tonumber(tier.cost) or 0
		if diamonds < cost then return false end

		bedwars.Handler:Get('RequestPurchaseTeamUpgrade'):Fire('CallServerAsync', upgrade.Id):andThen(function(suc)
			if suc then
				util.Utils.Notify('AutoUpgrade', 'Bought '..labelOf(upgrade)..' '..tierIndex, 3)
			end
		end)
		return true, cost
	end

	local function upgradePass()
		local offers = liveOffers()
		local diamondCount = util.Inventory.Amount('diamond')
		local now = tick()
		local currentTiers = util.Shop.TeamUpgrades()

		for _, upgrade in catalog do
			local toggle = toggles[upgrade.Id]
			if toggle and toggle.Enabled then
				local blocked = upgrade.DisabledInQueue and table.find(upgrade.DisabledInQueue, store.queueType or '')
				if not blocked and (not offers or offers[upgrade.Id]) then
					local tier = (currentTiers[upgrade.Id] or 0) + 1
					if tier <= #upgrade.Tiers then
						local waiting = pending[upgrade.Id]
						local settled = not waiting or waiting.Tier ~= tier or (now - waiting.At) >= SETTLE_TIME
						if settled then
							pending[upgrade.Id] = nil
							local bought, cost = buyTier(upgrade, tier, diamondCount)
							if bought then
								diamondCount -= cost
								pending[upgrade.Id] = {Tier = tier, At = tick()}
							end
						end
					end
				end
			end
		end
	end

	AutoUpgrade = vape.Categories.Inventory:CreateModule({
		Name = 'AutoUpgrade',
		Function = function(callback)
			if not callback then return end

			if not util.Queue.Await(AutoUpgrade) then return end

			local nextPass = 0
			repeat
				if util.Utils.Alive() and store.shopLoaded and store.matchState ~= 2 and nextPass <= tick() then
					resetForMatch()
					refreshCatalog()
					if util.Shop.Nearby('upgrade') then
						upgradePass()
						nextPass = tick() + 0.4
					end
				end
				task.wait(util.PollInterval)
			until not AutoUpgrade.Enabled
		end,
		Tooltip = 'Buys the chosen team upgrades at the upgrade shop'
	})

	refreshCatalog()
end)

-- ===== Inventory/FastConsume.lua =====
run(function()
    local Value
    local oldclickhold, oldshowprogress

    local FastConsume = vape.Categories.Inventory:CreateModule({
        Name = 'FastConsume',
        Function = function(callback)
            if callback then
                oldclickhold = bedwars.ClickHold.startClick
                oldshowprogress = bedwars.ClickHold.showProgress
                bedwars.ClickHold.startClick = function(self)
                    self.startedClickTime = tick()
                    local handle = self:showProgress()
                    local clicktime = self.startedClickTime
                    bedwars.RuntimeLib.Promise.defer(function()
                        task.wait(self.durationSeconds * (Value.Value / 40))
                        if handle == self.handle and clicktime == self.startedClickTime and self.closeOnComplete then
                            self:hideProgress()
                            if self.onComplete then self.onComplete() end
                            if self.onPartialComplete then self.onPartialComplete(1) end
                            self.startedClickTime = -1
                        end
                    end)
                end

                bedwars.ClickHold.showProgress = function(self)
                    local roact = debug.getupvalue(oldshowprogress, 1)
                    local countdown = roact.mount(roact.createElement('ScreenGui', {}, { roact.createElement('Frame', {
                        [roact.Ref] = self.wrapperRef,
                        Size = UDim2.new(),
                        Position = UDim2.fromScale(0.5, 0.55),
                        AnchorPoint = Vector2.new(0.5, 0),
                        BackgroundColor3 = Color3.fromRGB(0, 0, 0),
                        BackgroundTransparency = 0.8
                    }, { roact.createElement('Frame', {
                        [roact.Ref] = self.progressRef,
                        Size = UDim2.fromScale(0, 1),
                        BackgroundColor3 = Color3.new(1, 1, 1),
                        BackgroundTransparency = 0.5
                    }) }) }), lplr:FindFirstChild('PlayerGui'))

                    self.handle = countdown
                    local sizetween = tweenService:Create(self.wrapperRef:getValue(), TweenInfo.new(0.1), {
                        Size = UDim2.fromScale(0.11, 0.005)
                    })
                    local countdowntween = tweenService:Create(self.progressRef:getValue(), TweenInfo.new(self.durationSeconds * (Value.Value / 100), Enum.EasingStyle.Linear), {
                        Size = UDim2.fromScale(1, 1)
                    })

                    sizetween:Play()
                    countdowntween:Play()
                    table.insert(self.tweens, countdowntween)
                    table.insert(self.tweens, sizetween)

                    return countdown
                end
            else
                bedwars.ClickHold.startClick = oldclickhold
                bedwars.ClickHold.showProgress = oldshowprogress
                oldclickhold = nil
                oldshowprogress = nil
            end
        end,
        Tooltip = 'Uses items faster'
    })
    Value = FastConsume:CreateSlider({
        Name = 'Multiplier',
        Min = 0,
        Max = 100
    })
end)

-- ===== Inventory/FastDrop.lua =====
run(function()
    local FastDrop
    local EveryItem

    local function dropItem(item)
        local tool = item and item.tool
        if not tool or not item.itemType then return false end
        local ok, drop = pcall(function()
            return bedwars.Handler:Get('DropItem'):Fire('CallServer', {item = tool, amount = item.amount})
        end)
        return ok and drop ~= nil
    end

    FastDrop = vape.Categories.Inventory:CreateModule({
        Name = 'FastDrop',
        Function = function(callback)
            if callback then
                repeat
                    local held = inputService:GetFocusedTextBox() == nil
                        and (inputService:IsKeyDown(Enum.KeyCode.Q) or inputService:IsKeyDown(Enum.KeyCode.H) or inputService:IsKeyDown(Enum.KeyCode.Backspace))
                    if entitylib.isAlive and (not store.inventory.opened) and held then
                        if EveryItem.Enabled then
                            local inventory = store.inventory and store.inventory.inventory
                            for _, item in type(inventory) == 'table' and inventory.items or {} do
                                if not FastDrop.Enabled or not entitylib.isAlive then break end
                                dropItem(item)
                                task.wait(0.03)
                            end
                            task.wait(0.05)
                        else
                            task.spawn(bedwars.ItemDropController.dropItemInHand, bedwars.ItemDropController)
                            task.wait()
                        end
                    else
                        task.wait(0.1)
                    end
                until not FastDrop.Enabled
            end
        end,
        Tooltip = 'Drops your held item quickly while you hold Q, H or Backspace'
    })
    EveryItem = FastDrop:CreateToggle({
        Name = 'Every item',
        Tooltip = 'Drops everything you carry, not just the held item'
    })
end)

-- ===== Legit/BedAlarm.lua =====
run(function()
	local v2 = httpService
	local v3 = playersService
	local v4 = replicatedStorage
	local v5 = runService
	local v6 = inputService
	local v7 = tweenService
	local v8 = collectionService
	local v9 = guiService
	local v10 = game:GetService('TeleportService')
	local obj = debug
	local currentCamera = gameCamera
	local localPlayer = lplr
	local entity = entitylib
	local getfontbounds = getfontsize
	local getvapeasset = getcustomasset

		local v12 = nil
		local v13 = nil
		local v14 = nil
		local v15 = nil
		local v16 = nil
		local tbl3 = { "telepearl", "boba_pearl", "teleport_hat" }
		local raycastParams = RaycastParams.new()
		raycastParams.RespectCanCollide = true

		v12 = vape.Categories.Legit:CreateModule({
			Name = "BedAlarm",
			Category = "Game",
			Function = function(arg)
				if arg then
					local obj2 = setmetatable({}, { __mode = "k" })
					local n = 0

					local v17 = bedwars.SyncEvents.ProjectileLaunched:connect(function(arg2)
						if not v14.Enabled or not table.find(tbl3, arg2.projectileType) or typeof(arg2.origin) ~= "Vector3" or typeof(arg2.launchVelocity) ~= "Vector3" then
							return
						end
						local v17 = entity.getEntity(arg2.shooter)
						local isAlive = v17 and v17.Targetable and entity.isAlive
						local v18 = nil

						if isAlive then
							v18 = nil

							for _, v19 in v8:GetTagged("bed") do
								if tonumber(v19:GetAttribute("TeamId")) == tonumber(localPlayer:GetAttribute("Team")) then
									v18 = v19
									break
								else
									v18 = nil
								end
							end
						end

						if not v18 or os.clock() < n then
							return
						end
						local v19 = bedwars.ProjectileMeta[arg2.projectileType]
						local vector = Vector3.new(0, -(v19 and v19.gravitationalAcceleration or 196.2), 0)
						local filterDescendantsInstances = { arg2.shooter }

						for _, v20 in entity.List, nil, nil do
							table.insert(filterDescendantsInstances, v20.Character)
						end

						raycastParams.FilterDescendantsInstances = filterDescendantsInstances
						local origin = arg2.origin

						for i = 1, 100 do
							local n2 = i * 0.05
							local n3 = arg2.origin + arg2.launchVelocity * n2 + vector * 0.5 * n2 * n2
							local v20 = workspace:Raycast(origin, n3 - origin, raycastParams)

							if v20 then
								origin = v20.Position
								break
							else
								origin = n3
							end
						end

						if v15.Value < (origin - v18.Position).Magnitude then
							return
						end
						n = os.clock() + 3.05

						if v13.Enabled and v17.Player and not obj2[v17.Character] then
							obj2[v17.Character] = true
							bedwars.BedAlarmController:addIntruderPlayerHighlight(v17.Player)
						end

						bedwars.NotificationController:sendInfoNotification({ message = "[Bed Alarm]: An intruder pearled to your bed!" })
						local flag = (entity.character.RootPart.Position - v18.Position).Magnitude < 30
						bedwars.AudioManager:playAudio(flag and bedwars.SoundList.BED_ALARM or bedwars.SoundList.BED_ALARM_TRIGGERED_FAR, { volumeMultiplier = v16.Value, position = flag and v18.Position or nil, rollOffMaxDistance = 100 })
					end)

					v12:Clean(function()
						v17:Destroy()
					end)
					;(function(...) end)()
				end
			end,
			Tooltip = "Notifies when an enemy is near your bed",
		})

		v13 = v12:CreateToggle({
			Name = "Highlight intruders",
			Default = true,
			Tooltip = 'Outlines intruders through walls',
		})

		v14 = v12:CreateToggle({
			Name = "Pearl detection",
			Default = true,
			Tooltip = 'Also warns you of pearls landing at your bed',
		})

		v15 = v12:CreateSlider({
			Name = "Range",
			Min = 1,
			Max = 100,
			Default = 70,
			Suffix = function(arg)
				return arg == 1 and "stud" or "studs"
			end,
		})

		v16 = v12:CreateSlider({ Name = "Volume multiplier", Min = 0.1, Max = 2, Default = 1.4, Decimal = 100 })
	end)

-- ===== Legit/BedBreakEffect.lua =====
run(function()
    local BedBreakEffect
    local Mode
    local List
    local NameToId = {}

    BedBreakEffect = vape.Categories.Legit:CreateModule({
        Name = 'BedBreakEffect',
        Function = function(callback)
            if callback then
                BedBreakEffect:Clean(vapeEvents.BedwarsBedBreak.Event:Connect(function(data)
                    firesignal(bedwars.Client:Get('BedBreakEffectTriggered').instance.OnClientEvent, {
                        player = data.player,
                        position = data.bedBlockPosition * 3,
                        effectType = NameToId[List.Value],
                        teamId = data.brokenBedTeam.id,
                        centerBedPosition = data.bedBlockPosition * 3
                    })
                end))
            end
        end,
