run(function()
	local Main = vape.Libraries.mergedModule(vape.Categories.Legit, {
		Name = 'HitColour',
		Tooltip = 'Changes or removes the flash when players are hit'
	})

run(function()
    local HitColor
    local Color
    local done = setmetatable({}, {__mode = 'k'})

    HitColor = Main:Part({
		Label = 'Custom colour',
        Name = 'HitColour',
        Function = function(callback)
            if callback then
                repeat
                    local fill = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
                    for _, v in entitylib.List do
                        local highlight = v.Character and v.Character:FindFirstChild('_DamageHighlight_')
                        if highlight then
                            done[highlight] = true
                            highlight.FillColor = fill
                            highlight.FillTransparency = Color.Opacity
                        end
                    end
                    task.wait(0.1)
                until not HitColor.Enabled
            else
                for highlight in done do
                    pcall(function()
                        highlight.FillColor = Color3.new(1, 0, 0)
                        highlight.FillTransparency = 0.4
                    end)
                end
                table.clear(done)
            end
        end,
        Tooltip = 'Customize the hit highlight options'
    })
    Color = HitColor:CreateColorSlider({
        Name = 'Colour',
        DefaultOpacity = 0.4
    })
end)

run(function()
	local WhiteHits
	local descendantConnection
	local function removeDamageHighlight(obj)
		if obj and obj.Name == '_DamageHighlight_' then
			pcall(function()
				if obj:IsA('Highlight') then obj.Enabled = false end
				obj:Destroy()
			end)
		end
	end
	local function scanCharacters()
		for _, ent in entitylib.List do
			local character = ent and ent.Character
			if character then
				removeDamageHighlight(character)
				for _, obj in character:GetDescendants() do
					removeDamageHighlight(obj)
				end
			end
		end
	end
	WhiteHits = Main:Part({
		Label = 'No red flash',
		Default = false,
		Name = "WhiteHits",
		Function = function(callback)
			if callback then
				if descendantConnection then descendantConnection:Disconnect() end
				descendantConnection = workspace.DescendantAdded:Connect(removeDamageHighlight)
				repeat
					scanCharacters()
					task.wait(0.1)
				until not WhiteHits.Enabled
				if descendantConnection then
					descendantConnection:Disconnect()
					descendantConnection = nil
				end
			else
				if descendantConnection then
					descendantConnection:Disconnect()
					descendantConnection = nil
				end
			end
		end,
		Tooltip = 'Removes the red damage highlight on players'
	})
end)

end)

-- ===== Legit/HitFix.lua =====
run(function()
    local HitFix

    local function findConstant(func)
        local ok, constants = pcall(debug.getconstants, func)
        if ok and type(constants) == 'table' then
            for index, value in constants do
                if value == 'Raycast' or value == 'raycast' then
                    return index
                end
            end
            return nil
        end
        local read, value = pcall(debug.getconstant, func, 23)
        return read and (value == 'Raycast' or value == 'raycast') and 23 or nil
    end

    local function findUpvalue(func)
        local function holds(index)
            local read, value = pcall(debug.getupvalue, func, index)
            if not read then return nil end
            return value == workspace or (bedwars.QueryUtil ~= nil and value == bedwars.QueryUtil)
        end
        if holds(4) then return 4 end
        for index = 1, 24 do
            local found = holds(index)
            if found == nil then break end
            if found then return index end
        end
        return nil
    end

    HitFix = vape.Categories.Legit:CreateModule({
        Name = 'HitFix',
        Function = function(callback)
            local swing = bedwars.SwordController and bedwars.SwordController.swingSwordAtMouse
            local constant = type(swing) == 'function' and findConstant(swing)
            local upvalue = constant and findUpvalue(swing)
            if not constant or not upvalue or (callback and not bedwars.QueryUtil) then
                if callback then
                    notif('HitFix', 'The game\'s sword code has changed and HitFix could not find what it patches.', 6, 'warning')
                    HitFix:Toggle()
                end
                return
            end
            debug.setconstant(swing, constant, callback and 'raycast' or 'Raycast')
            debug.setupvalue(swing, upvalue, callback and bedwars.QueryUtil or workspace)
        end,
        Tooltip = 'Fixes sword hit detection'
    })
end)

-- ===== Legit/Interface.lua =====
run(function()
	local Main = vape.Libraries.mergedModule(vape.Categories.Legit, {
		Name = 'Interface',
		Tooltip = 'Restyles the hotbar and health bar and cleans up the UI'
	})

run(function()
	local Interface
	local HotbarOpenInventory = ({pcall(function()
		return require(lplr.PlayerScripts.TS.controllers.global.hotbar.ui['hotbar-open-inventory']).HotbarOpenInventory
	end)})[2]
	local HotbarHealthbar = ({pcall(function()
		return require(lplr.PlayerScripts.TS.controllers.global.hotbar.ui.healthbar['hotbar-healthbar']).HotbarHealthbar
	end)})[2]
	local HotbarApp = ({pcall(function()
		return getRoactRender(require(lplr.PlayerScripts.TS.controllers.global.hotbar.ui['hotbar-app']).HotbarApp.render)
	end)})[2]
	local old, new = {}, {}
	local madeHotbar, madeHealth = {}, {}
	local hotbarTextConnection, healthTextConnection
	local HotbarGuiSync, HotbarSlotColor, HotbarGradient, HotbarRounding, HotbarHighlight, HotbarHideNums
	local HotbarColorA, HotbarColorB, HotbarOutlineColor, HotbarRoundSize
	local HealthGuiSync, HealthMainOn, HealthGradOn, HealthBgOn, HealthRoundOn, HealthStrokeOn, HealthTextOn, HealthFontOn
	local HealthMainCol, HealthGradCol, HealthBgCol, HealthStrokeCol, HealthTextCol, HealthRoundSize, HealthFontDrop, HealthTextList

	vape:Clean(function()
		for _, v in new do
			table.clear(v)
		end
		for _, v in old do
			table.clear(v)
		end
		table.clear(new)
		table.clear(old)
	end)

	local function modifyconstant(func, ind, val)
		if not func then return end
		if not old[func] then old[func] = {} end
		if not new[func] then new[func] = {} end
		if not old[func][ind] then
			old[func][ind] = debug.getconstant(func, ind)
		end
		if typeof(old[func][ind]) ~= typeof(val) then return end
		new[func][ind] = val

		if Interface.Enabled then
			if val then
				debug.setconstant(func, ind, val)
			else
				debug.setconstant(func, ind, old[func][ind])
				old[func][ind] = nil
			end
		end
	end

	local function guiColor()
		local ok, hue = pcall(function()
			return vape.GUIColor and vape.GUIColor.Hue or 0.6
		end)
		if not ok then hue = 0.6 end
		return Color3.fromHSV(hue, 1, 1)
	end

	local function isAlive()
		local character = lplr.Character
		local humanoid = character and character:FindFirstChildOfClass('Humanoid')
		return humanoid ~= nil and humanoid.Health > 0
	end

	local function hotbarIcons()
		local icons = ({pcall(function()
			return lplr.PlayerGui.hotbar['1'].ItemsHotbar
		end)})[2]
		return typeof(icons) == 'Instance' and icons or nil
	end

	local function paintHotbar()
		local icons = hotbarIcons()
		if not icons then return end
		local sync = HotbarGuiSync and HotbarGuiSync.Enabled
		local synced = sync and guiColor() or nil
		for _, slot in ipairs(icons:GetChildren()) do
			local button = slot:FindFirstChildWhichIsA('ImageButton')
			local label = button and button:FindFirstChildWhichIsA('TextLabel')
			if not label then continue end
			if sync then
				button.BackgroundColor3 = synced
			elseif HotbarSlotColor and HotbarSlotColor.Enabled and not (HotbarGradient and HotbarGradient.Enabled) then
				local c = HotbarColorA
				button.BackgroundColor3 = c and Color3.fromHSV(c.Hue or 0, c.Sat or 0, c.Value or 1) or synced
			end
			if HotbarGradient and HotbarGradient.Enabled and not sync then
				button.BackgroundColor3 = Color3.new(1, 1, 1)
				if not button:FindFirstChildWhichIsA('UIGradient') then
					local g = Instance.new('UIGradient')
					local a = HotbarColorA and Color3.fromHSV(HotbarColorA.Hue or 0, HotbarColorA.Sat or 0, HotbarColorA.Value or 1) or Color3.fromRGB(80, 160, 255)
					local b = HotbarColorB and Color3.fromHSV(HotbarColorB.Hue or 0.7, HotbarColorB.Sat or 0.8, HotbarColorB.Value or 1) or Color3.fromRGB(180, 80, 255)
					g.Color = ColorSequence.new({ColorSequenceKeypoint.new(0, a), ColorSequenceKeypoint.new(1, b)})
					g.Parent = button
					table.insert(madeHotbar, g)
				end
			end
			if HotbarRounding and HotbarRounding.Enabled and not button:FindFirstChildWhichIsA('UICorner') then
				local c = Instance.new('UICorner')
				c.CornerRadius = UDim.new(0, HotbarRoundSize and HotbarRoundSize.Value or 8)
				c.Parent = button
				table.insert(madeHotbar, c)
			end
			if HotbarHighlight and HotbarHighlight.Enabled and not button:FindFirstChildWhichIsA('UIStroke') then
				local s = Instance.new('UIStroke')
				s.Thickness = 1.3
				s.Color = synced
					or (HotbarOutlineColor and Color3.fromHSV(HotbarOutlineColor.Hue or 0, HotbarOutlineColor.Sat or 0, HotbarOutlineColor.Value or 1))
					or Color3.new(1, 1, 1)
				s.Parent = button
				table.insert(madeHotbar, s)
			end
			if HotbarHideNums and HotbarHideNums.Enabled then
				label.Visible = false
			end
		end
	end

	local paintQueued, healthQueued = false, false
	local applyHealthbar
	local function queuePaint()
		if paintQueued then return end
		paintQueued = true
		task.delay(0.1, function()
			paintQueued = false
			if Interface and Interface.Enabled then paintHotbar() end
		end)
	end
	local function queueHealth()
		if healthQueued then return end
		healthQueued = true
		task.delay(0.15, function()
			healthQueued = false
			if Interface and Interface.Enabled then applyHealthbar() end
		end)
	end

	local function clearHotbar()
		for _, o in ipairs(madeHotbar) do
			pcall(function() o:Destroy() end)
		end
		table.clear(madeHotbar)
		pcall(function()
			local icons = hotbarIcons()
			for _, slot in ipairs(icons and icons:GetChildren() or {}) do
				local btn = slot:FindFirstChildWhichIsA('ImageButton')
				if btn then
					btn.BackgroundColor3 = Color3.fromRGB(29, 36, 46)
					local lab = btn:FindFirstChildWhichIsA('TextLabel')
					if lab then lab.Visible = true end
				end
			end
		end)
	end

	function applyHealthbar()
		if not Interface or not Interface.Enabled then return end
		local bar = ({pcall(function()
			return lplr.PlayerGui.hotbar['1'].HotbarHealthbarContainer.HealthbarProgressWrapper['1']
		end)})[2]
		if typeof(bar) ~= 'Instance' then return end

		if HealthGuiSync and HealthGuiSync.Enabled then
			bar.BackgroundColor3 = guiColor()
		elseif HealthMainOn and HealthMainOn.Enabled then
			bar.BackgroundColor3 = HealthMainCol and Color3.fromHSV(HealthMainCol.Hue or 0, HealthMainCol.Sat or 0.8, HealthMainCol.Value or 1) or Color3.fromRGB(203, 54, 36)
			if HealthGradOn and HealthGradOn.Enabled then
				bar.BackgroundColor3 = Color3.new(1, 1, 1)
				local g = bar:FindFirstChildWhichIsA('UIGradient') or Instance.new('UIGradient', bar)
				local a = HealthMainCol and Color3.fromHSV(HealthMainCol.Hue or 0, HealthMainCol.Sat or 0.8, HealthMainCol.Value or 1) or Color3.fromRGB(203, 54, 36)
				local b = HealthGradCol and Color3.fromHSV(HealthGradCol.Hue or 0.05, HealthGradCol.Sat or 0.8, HealthGradCol.Value or 1) or Color3.fromRGB(255, 160, 40)
				g.Color = ColorSequence.new({ColorSequenceKeypoint.new(0, a), ColorSequenceKeypoint.new(1, b)})
				table.insert(madeHealth, g)
			end
		end

		local bg = bar.Parent and bar.Parent.Parent
		if typeof(bg) == 'Instance' then
			if HealthBgOn and HealthBgOn.Enabled then
				bg.BackgroundColor3 = HealthBgCol and Color3.fromHSV(HealthBgCol.Hue or 0.6, HealthBgCol.Sat or 0.2, HealthBgCol.Value or 0.2) or Color3.fromRGB(41, 51, 65)
			end
			if HealthStrokeOn and HealthStrokeOn.Enabled and not bg:FindFirstChildWhichIsA('UIStroke') then
				local s = Instance.new('UIStroke')
				s.Thickness = 1.6
				s.Color = HealthStrokeCol and Color3.fromHSV(HealthStrokeCol.Hue or 0, HealthStrokeCol.Sat or 0, HealthStrokeCol.Value or 1) or Color3.new(1, 1, 1)
				s.Parent = bg
				table.insert(madeHealth, s)
			end
			if HealthRoundOn and HealthRoundOn.Enabled then
				for _, f in ipairs(bar.Parent:GetChildren()) do
					if f:IsA('Frame') and not f:FindFirstChildWhichIsA('UICorner') then
						local c = Instance.new('UICorner')
						c.CornerRadius = UDim.new(0, HealthRoundSize and HealthRoundSize.Value or 4)
						c.Parent = f
						table.insert(madeHealth, c)
					end
				end
				if not bg:FindFirstChildWhichIsA('UICorner') then
					local c = Instance.new('UICorner')
					c.CornerRadius = UDim.new(0, HealthRoundSize and HealthRoundSize.Value or 4)
					c.Parent = bg
					table.insert(madeHealth, c)
				end
			end

			local label = bg:FindFirstChild('1')
			if typeof(label) == 'Instance' and label:IsA('TextLabel') then
				if HealthTextCol and HealthTextOn and HealthTextOn.Enabled then
					label.TextColor3 = Color3.fromHSV(HealthTextCol.Hue or 0, HealthTextCol.Sat or 0, HealthTextCol.Value or 1)
				end
				if HealthFontOn and HealthFontOn.Enabled and HealthFontDrop then
					pcall(function() label.Font = Enum.Font[HealthFontDrop.Value] end)
				end
				local function rewrite()
					local custom = ''
					if HealthTextList and HealthTextList.ObjectList and #HealthTextList.ObjectList > 0 then
						custom = HealthTextList.ObjectList[math.random(1, #HealthTextList.ObjectList)]
					end
					local hp = isAlive() and tostring(math.floor(lplr.Character:GetAttribute('Health') or 0)) or '0'
					if HealthTextOn and HealthTextOn.Enabled and custom ~= '' then
						label.Text = custom:gsub('<health>', hp)
					else
						label.Text = hp
					end
				end
				rewrite()
				if healthTextConnection then healthTextConnection:Disconnect() end
				healthTextConnection = label:GetPropertyChangedSignal('Text'):Connect(rewrite)
			end
		end
	end

	local function clearHealthbar()
		if healthTextConnection then healthTextConnection:Disconnect() end
		healthTextConnection = nil
		for _, o in ipairs(madeHealth) do
			pcall(function() o:Destroy() end)
		end
		table.clear(madeHealth)
		pcall(function()
			local bar = lplr.PlayerGui.hotbar['1'].HotbarHealthbarContainer.HealthbarProgressWrapper['1']
			bar.BackgroundColor3 = Color3.fromRGB(203, 54, 36)
			bar.Parent.Parent.BackgroundColor3 = Color3.fromRGB(41, 51, 65)
		end)
	end

	Interface = Main:Part({
		Label = 'Restyle UI',
		Name = 'Interface',
		Function = function(callback)
			for i, v in (callback and new or old) do
				for i2, v2 in v do
					debug.setconstant(i, i2, v2)
				end
			end
			if callback then
				Interface:Clean(lplr.PlayerGui.DescendantAdded:Connect(function(v)
					if v.Name == 'hotbar' then
						queuePaint()
					elseif v.Name == 'HotbarHealthbarContainer' then
						queueHealth()
					end
				end))
				paintHotbar()
				applyHealthbar()
			else
				clearHotbar()
				clearHealthbar()
			end
		end,
		Tooltip = 'Restyles the hotbar and health bar and cleans up the UI',
		Category = 'Hud'
	})

	if canDebug then
		local fontitems = {'LuckiestGuy'}
		for _, v in Enum.Font:GetEnumItems() do
			if v.Name ~= 'LuckiestGuy' then
				table.insert(fontitems, v.Name)
			end
		end
		Interface:CreateDropdown({
			Name = 'Health Font',
			List = fontitems,
			Function = function(val)
				modifyconstant(HotbarHealthbar and HotbarHealthbar.render, 77, val)
			end
		})
		Interface:CreateColorSlider({
			Name = 'Health Colour',
			Function = function(hue, sat, val)
				modifyconstant(HotbarHealthbar and HotbarHealthbar.render, 16, tonumber(Color3.fromHSV(hue, sat, val):ToHex(), 16))
				if Interface.Enabled then
					local hotbar = lplr.PlayerGui:FindFirstChild('hotbar')
					hotbar = hotbar and hotbar:FindFirstChild('HealthbarProgressWrapper', true)
					if hotbar then
						hotbar['1'].BackgroundColor3 = Color3.fromHSV(hue, sat, val)
					end
				end
			end
		})
		Interface:CreateColorSlider({
			Name = 'Hotbar Colour',
			DefaultOpacity = 0.8,
			Function = function(hue, sat, val, opacity)
				local func = oldinvrender or (HotbarOpenInventory and HotbarOpenInventory.render)
				local render = HotbarApp and debug.getupvalue(HotbarApp, 23)
				render = render and render.render
				modifyconstant(render, 51, tonumber(Color3.fromHSV(hue, sat, val):ToHex(), 16))
				modifyconstant(render, 58, tonumber(Color3.fromHSV(hue, sat, math.clamp(val > 0.5 and val - 0.2 or val + 0.2, 0, 1)):ToHex(), 16))
				modifyconstant(render, 54, 1 - opacity)
				modifyconstant(render, 55, math.clamp(1.2 - opacity, 0, 1))
				modifyconstant(func, 31, tonumber(Color3.fromHSV(hue, sat, val):ToHex(), 16))
				modifyconstant(func, 32, math.clamp(1.2 - opacity, 0, 1))
				modifyconstant(func, 34, tonumber(Color3.fromHSV(hue, sat, math.clamp(val > 0.5 and val - 0.2 or val + 0.2, 0, 1)):ToHex(), 16))
			end
		})
	end

	HotbarGuiSync = Interface:CreateToggle({Name = 'Hotbar GUI sync', Function = function() if Interface.Enabled then clearHotbar(); paintHotbar() end end})
	HotbarSlotColor = Interface:CreateToggle({Name = 'Hotbar slot colour', Function = function() if Interface.Enabled then clearHotbar(); paintHotbar() end end})
	HotbarGradient = Interface:CreateToggle({Name = 'Hotbar gradient', Function = function() if Interface.Enabled then clearHotbar(); paintHotbar() end end})
	HotbarRounding = Interface:CreateToggle({Name = 'Hotbar rounding', Function = function() if Interface.Enabled then clearHotbar(); paintHotbar() end end})
	HotbarHighlight = Interface:CreateToggle({Name = 'Hotbar outline', Function = function() if Interface.Enabled then clearHotbar(); paintHotbar() end end})
	HotbarHideNums = Interface:CreateToggle({Name = 'Hotbar no numbers', Function = function() if Interface.Enabled then clearHotbar(); paintHotbar() end end})
	HotbarRoundSize = Interface:CreateSlider({Name = 'Hotbar round radius', Min = 1, Max = 16, Default = 8})
	HotbarColorA = Interface:CreateColorSlider({Name = 'Hotbar colour 1'})
	HotbarColorB = Interface:CreateColorSlider({Name = 'Hotbar gradient 2'})
	HotbarOutlineColor = Interface:CreateColorSlider({Name = 'Hotbar outline colour'})

	HealthGuiSync = Interface:CreateToggle({Name = 'Healthbar GUI sync', Function = function() if Interface.Enabled then clearHealthbar(); applyHealthbar() end end})
	HealthMainOn = Interface:CreateToggle({Name = 'Healthbar main colour', Default = true, Function = function() if Interface.Enabled then applyHealthbar() end end})
	HealthGradOn = Interface:CreateToggle({Name = 'Healthbar gradient', Function = function() if Interface.Enabled then applyHealthbar() end end})
	HealthBgOn = Interface:CreateToggle({Name = 'Healthbar background', Function = function() if Interface.Enabled then applyHealthbar() end end})
	HealthRoundOn = Interface:CreateToggle({Name = 'Healthbar rounding', Function = function() if Interface.Enabled then clearHealthbar(); applyHealthbar() end end})
	HealthStrokeOn = Interface:CreateToggle({Name = 'Healthbar outline', Function = function() if Interface.Enabled then clearHealthbar(); applyHealthbar() end end})
	HealthTextOn = Interface:CreateToggle({Name = 'Healthbar custom text', Function = function() if Interface.Enabled then applyHealthbar() end end})
	HealthFontOn = Interface:CreateToggle({Name = 'Healthbar custom font'})
	HealthRoundSize = Interface:CreateSlider({Name = 'Healthbar round size', Min = 1, Max = 16, Default = 4})
	local fonts = {'LuckiestGuy', 'GothamBold', 'SourceSansBold', 'Arcade', 'Fantasy'}
	HealthFontDrop = Interface:CreateDropdown({Name = 'Healthbar font', List = fonts, Default = 'LuckiestGuy'})
	HealthTextList = Interface:CreateTextList({Name = 'Healthbar text', TempText = 'use <health>'})
	HealthMainCol = Interface:CreateColorSlider({Name = 'Healthbar colour'})
	HealthGradCol = Interface:CreateColorSlider({Name = 'Healthbar secondary'})
	HealthBgCol = Interface:CreateColorSlider({Name = 'Healthbar background colour'})
	HealthStrokeCol = Interface:CreateColorSlider({Name = 'Healthbar outline colour'})
	HealthTextCol = Interface:CreateColorSlider({Name = 'Healthbar text colour'})
end)

run(function()
	local GetRoactRender = getRoactRender
	local function CreateGuiOverrides()
		local Objects = {}
		local function Restore()
			for Object, Saved in Objects do
				Saved.Destroying:Disconnect()
				for Property, Value in Saved.Properties do
					Value.Connection:Disconnect()
					if Object.Parent and Object[Property] == Value.Applied then
						Object[Property] = Value.Original
					end
				end
			end
			table.clear(Objects)
		end
		local function Apply(Object, Properties)
			local Saved = Objects[Object]
			if not Saved then
				Saved = {Properties = {}}
				Objects[Object] = Saved
				Saved.Destroying = Object.Destroying:Connect(function()
					Objects[Object] = nil
				end)
			end
			for Property, Applied in Properties do
				local Value = Saved.Properties[Property]
				if not Value then
					Value = {Original = Object[Property], Applied = Applied}
					Saved.Properties[Property] = Value
					Value.Connection = Object:GetPropertyChangedSignal(Property):Connect(function()
						if Objects[Object] == Saved and Object[Property] ~= Value.Applied then
							Value.Original = Object[Property]
							Object[Property] = Value.Applied
						end
					end)
				end
				Value.Applied = Applied
				Object[Property] = Applied
			end
		end
		return {Apply = Apply, Restore = Restore}
	end
	local GetVapeAsset = getcustomasset
	local LocalPlayer = lplr
	local StarterGui = starterGui
	local UICleanup
	local OpenInventory
	local KillFeed
	local OldTabList
	local ResizeHealth
	local NoNumbers
	local OriginalPlayerList: boolean?
	local HotbarApp = canDebug and GetRoactRender(require(LocalPlayer.PlayerScripts.TS.controllers.global.hotbar.ui["hotbar-app"]).HotbarApp.render)
	local HotbarOpenInventory = canDebug and require(LocalPlayer.PlayerScripts.TS.controllers.global.hotbar.ui["hotbar-open-inventory"]).HotbarOpenInventory
	local OldConstants, NewConstants = {}, {}
	local Indices: {[any]: {[string]: number}} = {}
	local OldKillFeed
	local GuiOverrides = CreateGuiOverrides()

	local function Added(Object: Instance)
		if not UICleanup.Enabled then
			return
		end
		if Object:IsA("ScreenGui") and Object.Name == "KillFeedGui" and KillFeed.Enabled then
			GuiOverrides.Apply(Object, {Enabled = false})
		elseif Object:IsA("GuiObject") and Object:FindFirstAncestor("hotbar") then
			if Object.Name == "HotbarHealthbarContainer" and ResizeHealth.Enabled then
				GuiOverrides.Apply(Object, {Size = UDim2.new(1, 0, Object.Size.Y.Scale, Object.Size.Y.Offset)})
			elseif Object.Parent.Name == "ItemsHotbar" and Object.Name == "10" and OpenInventory.Enabled then
				GuiOverrides.Apply(Object, {Visible = false})
			elseif Object:IsA("TextLabel") and Object.Parent:IsA("ImageButton") and Object:FindFirstAncestor("ItemsHotbar") and NoNumbers.Enabled then
				GuiOverrides.Apply(Object, {Visible = false})
			end
		end
	end

	local function Refresh()
		GuiOverrides.Restore()
		if UICleanup.Enabled then
			for _, v: Instance in LocalPlayer.PlayerGui:GetDescendants() do
				Added(v)
			end
		end
	end

	vape:Clean(function()
		for _, v: {[number]: any} in NewConstants do
			table.clear(v)
		end
		for _, v: {[number]: any} in OldConstants do
			table.clear(v)
		end
		table.clear(NewConstants)
		table.clear(OldConstants)
		table.clear(Indices)
	end)

	local function FindComponent(Name: string)
		if not HotbarApp then
			return nil
		end
		for Index: number = 1, 64 do
			local Success, Value = pcall(debug.getupvalue, HotbarApp, Index)
			if not Success then
				break
			end
			if type(Value) == "table" and rawget(Value, "__componentName") == Name then
				return Value
			end
		end
		return nil
	end

	local function Resolve(Function, Key: string, Value: any, After: any?): number?
		if typeof(Function) ~= "function" then
			return nil
		end
		local Known: {[string]: number}? = Indices[Function]
		if Known and Known[Key] then
			return Known[Key]
		end
		local Index: number?
		local Valid, Constants = pcall(debug.getconstants, Function)
		if Valid and type(Constants) == "table" then
			local Seen = After == nil
			for I = 1, table.maxn(Constants) do
				local Constant = Constants[I]
				if not Seen then
					Seen = Constant == After
				elseif Constant == Value then
					Index = I
					break
				end
			end
		end
		if Index then
			Indices[Function] = Known or {}
			Indices[Function][Key] = Index
		end
		return Index
	end

	local function ModifyConstant(Function, Index: number?, Value)
		if not Function or not Index then
			return
		end
		local Saved: {[number]: any}? = OldConstants[Function]
		local Original: any = Saved and Saved[Index]
		if Original == nil then
			if Value == nil then
				return
			end
			local Valid: boolean
			Valid, Original = pcall(debug.getconstant, Function, Index)
			if not Valid or typeof(Original) ~= typeof(Value) then
				return
			end
		end

		OldConstants[Function] = Saved or {}
		NewConstants[Function] = NewConstants[Function] or {}
		OldConstants[Function][Index] = Original
		NewConstants[Function][Index] = Value
		if UICleanup.Enabled then
			if Value then
				debug.setconstant(Function, Index, Value)
			else
				debug.setconstant(Function, Index, Original)
				OldConstants[Function][Index] = nil
			end
		end
	end

	UICleanup = Main:Part({
		Label = 'Clean up UI',
		Default = false,
		Name = "UICleanup",
		Category = "Game",
		Function = function(Callback: boolean)
			if not canDebug then
				if Callback then
					OriginalPlayerList = StarterGui:GetCoreGuiEnabled(Enum.CoreGuiType.PlayerList)
					UICleanup:Clean(GuiOverrides.Restore)
					UICleanup:Clean(LocalPlayer.PlayerGui.DescendantAdded:Connect(Added))
					StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, OldTabList.Enabled)
				elseif OriginalPlayerList ~= nil then
					StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, OriginalPlayerList)
					OriginalPlayerList = nil
				end
				Refresh()
				return
			end

			for Function: (...any) -> ...any, Constants: {[number]: any} in (Callback and NewConstants or OldConstants) do
				for i: number, Value: any in Constants do
					debug.setconstant(Function, i, Value)
				end
			end
			if Callback then
				if OpenInventory.Enabled then
					oldinvrender = HotbarOpenInventory.render
					HotbarOpenInventory.render = function()
						return bedwars.Roact.createElement("TextButton", {Visible = false}, {})
					end
				end

				if KillFeed.Enabled then
					OldKillFeed = bedwars.KillFeedController.addToKillFeed
					bedwars.KillFeedController.addToKillFeed = function() end
				end

				if OldTabList.Enabled then
					StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, true)
				end
			else
				if oldinvrender then
					HotbarOpenInventory.render = oldinvrender
					oldinvrender = nil
				end

				if KillFeed.Enabled then
					bedwars.KillFeedController.addToKillFeed = OldKillFeed
					OldKillFeed = nil
				end

				if OldTabList.Enabled then
					StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, false)
				end
			end
		end,
		Tooltip = 'Keeps popups and extra buttons off your screen'
	})

	ResizeHealth = UICleanup:CreateToggle({
		Name = "Resize Health",
		Function = function(Callback: boolean)
			if not canDebug then
				Refresh()
				return
			end
			local Healthbar = FindComponent("HotbarHealthbar")
			local Tile = FindComponent("HotbarTile")
			ModifyConstant(HotbarApp, Resolve(HotbarApp, "Width", 0.6), Callback and 1 or nil)
			ModifyConstant(Healthbar and Healthbar.render, Healthbar and Resolve(Healthbar.render, "Width", 0.85), Callback and 1 or nil)
			ModifyConstant(Tile and Tile.tweenPosition, Tile and Resolve(Tile.tweenPosition, "Lift", -0.075), Callback and 0 or nil)
		end,
		Default = true
	})
	NoNumbers = UICleanup:CreateToggle({
		Name = "No Hotbar Numbers",
		Function = function(Callback: boolean)
			if not canDebug then
				Refresh()
				return
			end
			local Tile = FindComponent("HotbarTile")
			local InventoryRender = oldinvrender or HotbarOpenInventory.render
			ModifyConstant(Tile and Tile.render, Tile and Resolve(Tile.render, "Number", 0.23, "Keybind"), Callback and 0 or nil)
			ModifyConstant(InventoryRender, Resolve(InventoryRender, "Number", 0.23), Callback and 0 or nil)
		end,
		Default = true
	})
	OpenInventory = UICleanup:CreateToggle({
		Name = "No Inventory Button",
		Function = function(Callback: boolean)
			if not canDebug then
				Refresh()
				return
			end
			if UICleanup.Enabled then
				if Callback then
					oldinvrender = HotbarOpenInventory.render
					HotbarOpenInventory.render = function()
						return bedwars.Roact.createElement("TextButton", {Visible = false}, {})
					end
				else
					HotbarOpenInventory.render = oldinvrender
					oldinvrender = nil
				end
			end
		end,
		Default = true
	})
	KillFeed = UICleanup:CreateToggle({
		Name = "No Kill Feed",
		Function = function(Callback: boolean)
			if not canDebug then
				Refresh()
				return
			end
			if UICleanup.Enabled then
				if Callback then
					OldKillFeed = bedwars.KillFeedController.addToKillFeed
					bedwars.KillFeedController.addToKillFeed = function() end
				else
					bedwars.KillFeedController.addToKillFeed = OldKillFeed
					OldKillFeed = nil
				end
			end
		end,
		Default = true
	})
	OldTabList = UICleanup:CreateToggle({
		Name = "Old Player List",
		Function = function(Callback: boolean)
			if UICleanup.Enabled then
				StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, Callback)
			end
		end,
		Default = true
	})
	UICleanup:CreateToggle({
		Name = "Fix Queue Card",
		Function = function(Callback: boolean)
			if not canDebug then
				return
			end
			ModifyConstant(bedwars.QueueCard.render, Resolve(bedwars.QueueCard.render, "Card", 0.01), Callback and 0.1 or nil)
		end,
		Visible = canDebug,
		Default = true
	})
end)

end)

-- ===== Legit/KillEffect.lua =====
run(function()
    local KillEffect
    local Mode
    local List
    local NameToId = {}

    local killeffects = {
        Gravity = function(_, _, char, _)
            char:BreakJoints()
            local highlight = char:FindFirstChildWhichIsA('Highlight')
            local nametag = char:FindFirstChild('Nametag', true)
            if highlight then
                highlight:Destroy()
            end
            if nametag then
                nametag:Destroy()
            end

            task.spawn(function()
                local partvelo = {}
                for _, v in char:GetDescendants() do
                    if v:IsA('BasePart') then
                        partvelo[v.Name] = v.Velocity
                    end
                end
                char.Archivable = true
                local clone = char:Clone()
                clone.Humanoid.Health = 100
                clone.Parent = workspace
                game:GetService('Debris'):AddItem(clone, 30)
                char:Destroy()
                task.wait(0.01)
                clone.Humanoid:ChangeState(Enum.HumanoidStateType.Dead)
                clone:BreakJoints()
                task.wait(0.01)
                for _, v in clone:GetDescendants() do
                    if v:IsA('BasePart') then
                        local bodyforce = Instance.new('BodyForce')
                        bodyforce.Force = Vector3.new(0, (workspace.Gravity - 10) * v:GetMass(), 0)
                        bodyforce.Parent = v
                        v.CanCollide = true
                        v.Velocity = partvelo[v.Name] or Vector3.zero
                    end
                end
            end)
        end,
        Lightning = function(_, _, char, _)
            char:BreakJoints()
            local highlight = char:FindFirstChildWhichIsA('Highlight')
            if highlight then
                highlight:Destroy()
            end
            local startpos = 1125
            local startcf = char.PrimaryPart.CFrame.p - Vector3.new(0, 8, 0)
            local newpos = Vector3.new((math.random(1, 10) - 5) * 2, startpos, (math.random(1, 10) - 5) * 2)

            for i = startpos - 75, 0, -75 do
                local newpos2 = Vector3.new((math.random(1, 10) - 5) * 2, i, (math.random(1, 10) - 5) * 2)
                if i == 0 then
                    newpos2 = Vector3.zero
                end
                local part = Instance.new('Part')
                part.Size = Vector3.new(1.5, 1.5, 77)
                part.Material = Enum.Material.SmoothPlastic
                part.Anchored = true
                part.Material = Enum.Material.Neon
                part.CanCollide = false
                part.CFrame = CFrame.new(startcf + newpos + ((newpos2 - newpos) * 0.5), startcf + newpos2)
                part.Parent = workspace
                local part2 = part:Clone()
                part2.Size = Vector3.new(3, 3, 78)
                part2.Color = Color3.new(0.7, 0.7, 0.7)
                part2.Transparency = 0.7
                part2.Material = Enum.Material.SmoothPlastic
                part2.Parent = workspace
                game:GetService('Debris'):AddItem(part, 0.5)
                game:GetService('Debris'):AddItem(part2, 0.5)
                bedwars.QueryUtil:setQueryIgnored(part, true)
                bedwars.QueryUtil:setQueryIgnored(part2, true)
                if i == 0 then
                    local soundpart = Instance.new('Part')
                    soundpart.Transparency = 1
                    soundpart.Anchored = true
                    soundpart.Size = Vector3.zero
                    soundpart.Position = startcf
                    soundpart.Parent = workspace
                    bedwars.QueryUtil:setQueryIgnored(soundpart, true)
                    local sound = Instance.new('Sound')
                    sound.SoundId = 'rbxassetid://6993372814'
                    sound.Volume = 2
                    sound.Pitch = 0.5 + (math.random(1, 3) / 10)
                    sound.Parent = soundpart
                    sound:Play()
                    sound.Ended:Connect(function()
                        soundpart:Destroy()
                    end)
                end
                newpos = newpos2
            end
        end,
        Delete = function(_, _, char, _)
            char:Destroy()
        end
    }

    KillEffect = vape.Categories.Legit:CreateModule({
        Name = 'KillEffect',
        Function = function(callback)
            if callback then
                for i, v in killeffects do
                    bedwars.KillEffectController.killEffects['Custom'..i] = {
                        new = function()
                            return {
                                onKill = v,
                                isPlayDefaultKillEffect = function()
                                    return false
                                end
                            }
                        end
                    }
                end
                KillEffect:Clean(lplr:GetAttributeChangedSignal('KillEffectType'):Connect(function()
                    lplr:SetAttribute('KillEffectType', Mode.Value == 'Bedwars' and NameToId[List.Value] or 'Custom'..Mode.Value)
                end))
                lplr:SetAttribute('KillEffectType', Mode.Value == 'Bedwars' and NameToId[List.Value] or 'Custom'..Mode.Value)
            else
                for i in killeffects do
                    bedwars.KillEffectController.killEffects['Custom'..i] = nil
                end
                lplr:SetAttribute('KillEffectType', 'default')
            end
        end,
        Tooltip = 'Custom final kill effects'
    })
    local modes = {'Bedwars'}
    for i in killeffects do
        table.insert(modes, i)
    end
    Mode = KillEffect:CreateDropdown({
        Name = 'Mode',
        List = modes,
        Function = function(val)
            List.Object.Visible = val == 'Bedwars'
            if KillEffect.Enabled then
                lplr:SetAttribute('KillEffectType', val == 'Bedwars' and NameToId[List.Value] or 'Custom'..val)
            end
        end
    })
    local KillEffectName = {}
    for i, v in bedwars.KillEffectMeta do
        table.insert(KillEffectName, v.name)
        NameToId[v.name] = i
    end
    table.sort(KillEffectName)
    List = KillEffect:CreateDropdown({
        Name = 'Bedwars',
        List = KillEffectName,
        Function = function(val)
            if KillEffect.Enabled then
                lplr:SetAttribute('KillEffectType', NameToId[val])
            end
        end,
        Darker = true
    })
end)

-- ===== Legit/PotionStatus.lua =====
run(function()
	local GetFontBounds = getfontsize
	local Entity = entitylib
	local GetVapeAsset = getcustomasset
	local LocalPlayer = lplr
	local UIPallet = uipallet
	local PotionStatus
	local ShowPositive
	local ShowNegative
	local Background
	local BackgroundColor
	local Effects: {[string]: number} = {}
	local Seen: {[string]: boolean} = {}
	local Replacements: {[string]: string} = {
		speed = "rbxassetid://71873445837330"
	}
	local Negative: {[string]: boolean} = {
		bleed = true,
		burn = true,
		cold = true,
		curse_of_the_altar = true,
		decay = true,
		dizzy = true,
		feeble = true,
		frost_bite = true,
		frosted = true,
		frozen = true,
		grave_trap = true,
		greased = true,
		grounded = true,
		grounded_enchant = true,
		hungry = true,
		infected_poison = true,
		isabel_shield_broken = true,
		lunar_venom = true,
		mage_burn = true,
		oil_spilled = true,
		oiled = true,
		on_ice = true,
		owl_target = true,
		poison = true,
		powdered = true,
		shield_down = true,
		shrink = true,
		silas_halloween_hex = true,
		silence = true,
		skeleton_poison = true,
		snae_poison_arrow = true,
		snake_poison_sword = true,
		soaked = true,
		SPIDER_WEB_SLOW = true,
		stacking_decay = true,
		Vengeful_venom = true,
		void_hunter_marked = true,
		weak_armor = true,
		werewolf_fear = true,
		zapped_1 = true,
		zapped_2 = true,
		zapped_3 = true
	}
	local AccentColor: Color3 = Color3.fromRGB(5, 134, 105)
	local WarnColor: Color3 = Color3.fromRGB(236, 129, 44)
	local DangerColor: Color3 = Color3.fromRGB(250, 50, 56)
	local HalfCut: NumberSequence = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 0),
		NumberSequenceKeypoint.new(0.5, 0),
		NumberSequenceKeypoint.new(0.501, 1),
		NumberSequenceKeypoint.new(1, 1)
	})
	local Holder: Frame

	local function Added(Active)
		if vape.ThreadFix then
			setthreadidentity(8)
		end

		Effects[Active.statusEffect] = Active.expireTime
		local Duration: number = Active.expireTime - workspace:GetServerTimeNow()
		if Duration <= 0 then
			Effects[Active.statusEffect] = nil
			return
		end

		local ItemMeta = bedwars.ItemMeta[Active.statusEffect] or bedwars.ItemMeta[`{Active.statusEffect}_potion`]
		local Effect: Frame = Instance.new("Frame")
		Effect.BackgroundTransparency = 1
		Effect.Parent = Holder
		local Ring: Frame = Instance.new("Frame")
		Ring.BackgroundTransparency = 1
		Ring.Position = UDim2.fromOffset(0, 4)
		Ring.Size = UDim2.fromOffset(50, 50)
		Ring.Parent = Effect
		local Backing: Frame = Instance.new("Frame")
		Backing.BackgroundTransparency = 1
		Backing.Position = UDim2.fromOffset(4.5, 4.5)
		Backing.Size = UDim2.fromOffset(41, 41)
		Backing.Parent = Ring
		local BackingCorner: UICorner = Instance.new("UICorner")
		BackingCorner.CornerRadius = UDim.new(1, 0)
		BackingCorner.Parent = Backing
		local BackingStroke: UIStroke = Instance.new("UIStroke")
		BackingStroke.Color = Color3.new()
		BackingStroke.Thickness = 3.6
		BackingStroke.Transparency = 0.216
		BackingStroke.Parent = Backing
		local Gradients, Strokes = {}, {}

		for _, Side: string in {"Left", "Right"} do
			local Clip: Frame = Instance.new("Frame")
			Clip.BackgroundTransparency = 1
			Clip.ClipsDescendants = true
			Clip.Position = UDim2.fromOffset(Side == "Right" and 25 or 0, 0)
			Clip.Size = UDim2.fromOffset(25, 50)
			Clip.Parent = Ring
			local Arc: Frame = Instance.new("Frame")
			Arc.BackgroundTransparency = 1
			Arc.Position = UDim2.fromOffset(Side == "Right" and -21 or 4, 4)
			Arc.Size = UDim2.fromOffset(42, 42)
			Arc.Parent = Clip
			local ArcCorner: UICorner = Instance.new("UICorner")
			ArcCorner.CornerRadius = UDim.new(1, 0)
			ArcCorner.Parent = Arc
			local ArcStroke: UIStroke = Instance.new("UIStroke")
			ArcStroke.Color = AccentColor
			ArcStroke.Thickness = 4
			ArcStroke.Parent = Arc
			local ArcGradient: UIGradient = Instance.new("UIGradient")
			ArcGradient.Transparency = HalfCut
			ArcGradient.Parent = ArcStroke
			Gradients[Side] = ArcGradient
			Strokes[Side] = ArcStroke
		end

		local Sidebar: Frame = Instance.new("Frame")
		Sidebar.AnchorPoint = Vector2.new(0, 0.5)
		Sidebar.BackgroundColor3 = Color3.fromRGB(170, 170, 170)
		Sidebar.BackgroundTransparency = 0.5
		Sidebar.BorderSizePixel = 0
		Sidebar.Position = UDim2.new(0, 53, 0.5, 1)
		Sidebar.Size = UDim2.fromOffset(2, 27)
		Sidebar.Parent = Effect
		local EffectImage: ImageLabel = Instance.new("ImageLabel")
		EffectImage.AnchorPoint = Vector2.new(0, 0.5)
		EffectImage.BackgroundTransparency = 1
		EffectImage.Image = Replacements[Active.statusEffect] or (ItemMeta and ItemMeta.image) or bedwars.ImageList.POTION_ART
		EffectImage.Position = UDim2.new(0, 10, 0.5, 0)
		EffectImage.Size = UDim2.fromOffset(30, 30)
		EffectImage.Parent = Effect
		local EffectName: TextLabel = Instance.new("TextLabel")
		EffectName.BackgroundTransparency = 1
		EffectName.FontFace = UIPallet.FontSemiBold
		EffectName.Position = UDim2.fromOffset(67, 10)
		EffectName.Size = UDim2.fromOffset(108, 20)
		EffectName.Text = (`{Active.statusEffect:sub(0, 1):upper()}{Active.statusEffect:sub(2, #Active.statusEffect)}`):gsub("_", " ")
		EffectName.TextColor3 = Color3.new(1, 1, 1)
		EffectName.TextSize = 15
		EffectName.TextXAlignment = Enum.TextXAlignment.Left
		EffectName.Parent = Effect
		local NameShadow: TextLabel = EffectName:Clone()
		NameShadow.Position += UDim2.fromOffset(1, 1)
		NameShadow.TextColor3 = Color3.new()
		NameShadow.TextTransparency = 0.5
		NameShadow.ZIndex = 0
		NameShadow.Parent = Effect
		Effect.Size = UDim2.fromOffset(GetFontBounds(EffectName.Text, 15, UIPallet.FontSemiBold).X + 80, 57)
		local EffectDuration: TextLabel = EffectName:Clone()
		EffectDuration.Position = UDim2.fromOffset(67, 29)
		EffectDuration.Text = "00:00"
		EffectDuration.TextSize = 14
		EffectDuration.Parent = Effect
		local DurationShadow: TextLabel = EffectDuration:Clone()
		DurationShadow.Position += UDim2.fromOffset(1, 1)
		DurationShadow.TextColor3 = Color3.new()
		DurationShadow.TextTransparency = 0.5
		DurationShadow.ZIndex = 0
		DurationShadow.Parent = Effect
		local Seconds: number = 0
		local ShownSeconds: number?
		local ShownColor: Color3?

		repeat
			local Remaining: number = math.max(Active.expireTime - workspace:GetServerTimeNow(), 0)
			local Percent: number = Remaining / Duration
			local RingColor: Color3 = Percent > 0.5 and AccentColor or (Percent > 0.25 and WarnColor or DangerColor)
			local Theta: number = math.min(Percent, 1) * 360
			Seconds = math.floor(Remaining)
			Gradients.Left.Rotation = math.clamp(Theta, 180, 360)
			Gradients.Right.Rotation = math.clamp(Theta, 0, 180)
			if RingColor ~= ShownColor then
				ShownColor = RingColor
				Strokes.Left.Color = RingColor
				Strokes.Right.Color = RingColor
				EffectDuration.TextColor3 = RingColor
			end
			if Seconds ~= ShownSeconds then
				ShownSeconds = Seconds
				local Text: string = ("%02d:%02d"):format(Seconds // 60, Seconds % 60)
				EffectDuration.Text = Text
				DurationShadow.Text = Text
			end
			task.wait(0.1)
		until Seconds <= 0 or Effects[Active.statusEffect] ~= Active.expireTime or not PotionStatus.Enabled

		Effect:Destroy()

		if Effects[Active.statusEffect] == Active.expireTime then
			Effects[Active.statusEffect] = nil
		end
	end

	PotionStatus = vape.Categories.Legit:CreateModule({
		Name = "PotionStatus",
		Category = "Hud",
		Function = function(Callback: boolean)
			if Callback then
				repeat
					table.clear(Seen)

					if Entity.isAlive then
						for _, v: any in bedwars.StatusEffectUtil:getAllActive(LocalPlayer.Character) do
							if (v.expireTime or 0) - workspace:GetServerTimeNow() > 0 and (Negative[v.statusEffect] and ShowNegative.Enabled or not Negative[v.statusEffect] and ShowPositive.Enabled) then
								Seen[v.statusEffect] = true

								if Effects[v.statusEffect] ~= v.expireTime then
									task.spawn(Added, v)
								end
							end
						end
					end

					for StatusEffect: string in Effects do
						if not Seen[StatusEffect] then
							Effects[StatusEffect] = nil
						end
					end

					task.wait(0.1)
				until not PotionStatus.Enabled

				table.clear(Effects)
			end
		end,
		Size = UDim2.fromOffset(240, 64),
		Tooltip = "Shows your currently active effects"
	})

	Holder = PotionStatus.Children
	Holder.BackgroundColor3 = Color3.new()
	Holder.BackgroundTransparency = 0.5
	local HolderCorner: UICorner = Instance.new("UICorner")
	HolderCorner.CornerRadius = UDim.new(0, 4)
	HolderCorner.Parent = Holder
	local Layout: UIListLayout = Instance.new("UIListLayout")
	Layout.HorizontalAlignment = Enum.HorizontalAlignment.Left
	Layout.SortOrder = Enum.SortOrder.LayoutOrder
	Layout.Parent = Holder
	vape:Clean(Layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
		if vape.ThreadFix then
			setthreadidentity(8)
		end

		Holder.Size = UDim2.fromOffset(Layout.AbsoluteContentSize.X, Layout.AbsoluteContentSize.Y)
	end))
	ShowPositive = PotionStatus:CreateToggle({
		Name = "Show Positive Effects",
		Default = true
	})
	ShowNegative = PotionStatus:CreateToggle({
		Name = "Show Negative Effects",
		Default = true
	})
	Background = PotionStatus:CreateGroup({
		Name = "Render background",
		Function = function(Callback: boolean)
			if BackgroundColor then
				Holder.BackgroundTransparency = Callback and 1 - BackgroundColor.Opacity or 1
			end
		end,
		Default = true
	})
	BackgroundColor = Background:CreateColorSlider({
		Name = "Background Color",
		DefaultValue = 0,
		DefaultOpacity = 0.5,
		Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
			Holder.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)
			Holder.BackgroundTransparency = Background.Enabled and 1 - Opacity or 1
		end,
		Darker = true
	})
end)

-- ===== Legit/ReachDisplay.lua =====
run(function()
    local ReachDisplay
    local label

    ReachDisplay = vape.Categories.Legit:CreateModule({
        Name = 'ReachDisplay',
        Function = function(callback)
            if callback then
                local lastText
                repeat
                    local text = (store.attackReachUpdate > tick() and store.attackReach or '0.00')..' studs'
                    if text ~= lastText then
                        lastText = text
                        label.Text = text
                    end
                    task.wait(0.4)
                until not ReachDisplay.Enabled
            end
        end,
        Size = UDim2.fromOffset(100, 41),
        Category = 'Hud',
        Tooltip = 'Shows how far away your last hit landed'
    })
    ReachDisplay:CreateFont({
        Name = 'Font',
        Blacklist = 'Gotham',
        Function = function(val)
            if label and val then label.FontFace = val end
        end
    })
    ReachDisplay:CreateColorSlider({
        Name = 'Colour',
        DefaultValue = 0,
        DefaultOpacity = 0.5,
        Function = function(hue, sat, val, opacity)
            label.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
            label.BackgroundTransparency = 1 - opacity
        end
    })
    label = Instance.new('TextLabel')
    label.Size = UDim2.fromScale(1, 1)
    label.BackgroundTransparency = 0.5
    label.TextSize = 15
    label.Font = Enum.Font.Gotham
    label.Text = '0.00 studs'
    label.TextColor3 = Color3.new(1, 1, 1)
    label.BackgroundColor3 = Color3.new()
    label.Parent = ReachDisplay.Children
    local corner = Instance.new('UICorner')
    corner.CornerRadius = UDim.new(0, 4)
    corner.Parent = label
end)

-- ===== Legit/SoundChanger.lua =====
run(function()
    local SoundChanger
    local List
    local soundlist = {}
    local old

    SoundChanger = vape.Categories.Legit:CreateModule({
        Name = 'SoundChanger',
        Function = function(callback)
            if callback then
                old = bedwars.SoundManager.playSound
                bedwars.SoundManager.playSound = function(self, id, ...)
                    if soundlist[id] then
                        id = soundlist[id]
                    end

                    return old(self, id, ...)
                end
            else
                bedwars.SoundManager.playSound = old
                old = nil
            end
        end,
        Tooltip = 'Changes in-game sounds to custom ones'
    })
    List = SoundChanger:CreateTextList({
        Name = 'Sounds',
        Placeholder = '(DAMAGE_1/ben.mp3)',
        Function = function()
            table.clear(soundlist)
            for _, entry in List.ListEnabled do
                local split = entry:split('/')
                local id = bedwars.SoundList[split[1]]
                if id and #split > 1 then
                    soundlist[id] = split[2]:find('rbxasset') and split[2] or isfile(split[2]) and assetfunction(split[2]) or ''
                end
            end
        end
    })
end)

-- ===== Legit/StreamDisabler.lua =====
run(function()
	local DisableStreamer
	local old = {}
	local oldLevels = {}
	local oldUsernames = {}
	local levelMap = {}
	local updaterThread = nil

	local function strip(plrs)
		if plrs == lplr then return end

		local disguiseName = plrs:GetAttribute("DisguiseDisplayName")
		if disguiseName and disguiseName ~= "" then
			old[plrs] = disguiseName
			plrs:SetAttribute("DisguiseDisplayName", "")
		end

		local disguiseUsername = plrs:GetAttribute("DisguiseUsername")
		if disguiseUsername and disguiseUsername ~= "" then
			oldUsernames[plrs] = disguiseUsername
			plrs:SetAttribute("DisguiseUsername", "")
		end

		local playerLevel = plrs:GetAttribute("PlayerLevel")
		if playerLevel then
			oldLevels[plrs] = playerLevel
			levelMap[plrs.Name] = playerLevel
		end
	end

	DisableStreamer = vape.Categories.Legit:CreateModule({
		Name = 'StreamDisabler',
		Function = function(callback)
			if callback then
				for _, plrs in playersService:GetPlayers() do
					strip(plrs)
				end

				pcall(function()
					bedwars.StreamerModeController:updateNametags(true)
				end)

				DisableStreamer:Clean(playersService.PlayerAdded:Connect(function(plrs)
					task.wait(1)
					if not DisableStreamer.Enabled or not plrs.Parent then return end
					strip(plrs)
					pcall(function()
						bedwars.StreamerModeController:updateNametags(true)
					end)
				end))
				DisableStreamer:Clean(playersService.PlayerRemoving:Connect(function(plrs)
					old[plrs], oldUsernames[plrs], oldLevels[plrs] = nil, nil, nil
					levelMap[plrs.Name] = nil
				end))

				updaterThread = task.spawn(function()
					while DisableStreamer.Enabled do
						local tabList = lplr.PlayerGui:FindFirstChild("TabListScreenGui")
						if tabList then
							for _, desc in tabList:GetDescendants() do
								if desc:IsA("TextLabel") and desc.Name == "PlayerLevel" then
									local text = desc.Text
									if text:find("%[%?%]") then
										local siblingName = desc.Parent:FindFirstChild("PlayerName")
										if siblingName then
											local currentNameText = siblingName.Text
											local cleanName = currentNameText:gsub("^@", ""):match("^%s*(.-)%s*$")

											local matchedPlayer = nil
											for _, plr in playersService:GetPlayers() do
												if plr == lplr then continue end
												if cleanName == plr.Name or cleanName == plr.DisplayName then
													matchedPlayer = plr
													break
												end
											end

											if matchedPlayer then
												local realLevel = levelMap[matchedPlayer.Name]
												if realLevel then
													desc.Text = '<font color="rgb(255,255,255)">[' .. tostring(realLevel) .. ']</font>'
												end
											end
										end
									end
								end
							end
						end
						task.wait(0.3)
					end
				end)
				DisableStreamer:Clean(updaterThread)
			else
				updaterThread = nil

				for _, plrs in playersService:GetPlayers() do
					if plrs == lplr then continue end

					if old[plrs] then
						plrs:SetAttribute("DisguiseDisplayName", old[plrs])
					end

					if oldUsernames[plrs] then
						plrs:SetAttribute("DisguiseUsername", oldUsernames[plrs])
					end

					if oldLevels[plrs] then
						plrs:SetAttribute("PlayerLevel", oldLevels[plrs])
					end
				end
				table.clear(old)
				table.clear(oldUsernames)
				table.clear(oldLevels)
				table.clear(levelMap)

				pcall(function()
					bedwars.StreamerModeController:updateNametags(true)
				end)

				task.spawn(function()
					local tabList = lplr.PlayerGui:FindFirstChild("TabListScreenGui")
					if tabList then
						tabList.Enabled = false
						task.wait()
						tabList.Enabled = true
					end
				end)
			end
		end,
		Tooltip = "Disables people's Streamer Modes"
	})
end)

