-- ===== Legit/WinEffect.lua =====
run(function()
    local WinEffect
    local List
    local NameToId = {}

    local function selectedId()
        return List and NameToId[List.Value] or nil
    end

    local function applyAttribute()
        local id = selectedId()
        if id ~= nil then
            lplr:SetAttribute('WinEffectType', id)
        end
    end

    local function playEffect()
        local id = selectedId()
        if id == nil then return end
        applyAttribute()

        local remote
        pcall(function()
            remote = bedwars.Client:Get('WinEffectTriggered')
        end)
        local instance = remote and remote.instance
        if instance and instance.OnClientEvent then
            local payload = {
                winEffectType = id,
                winningPlayer = lplr
            }
            local fired = false
            pcall(function()
                for _, conn in getconnections(instance.OnClientEvent) do
                    local fn = conn.Function or conn.FunctionValue
                    if type(fn) == 'function' then
                        fired = true
                        pcall(fn, payload)
                    end
                end
            end)
            if not fired then
                pcall(function()
                    firesignal(instance.OnClientEvent, payload)
                end)
            end
        end
    end

    WinEffect = vape.Categories.Legit:CreateModule({
        Name = 'WinEffect',
        Function = function(callback)
            if callback then
                applyAttribute()
                WinEffect:Clean(lplr:GetAttributeChangedSignal('WinEffectType'):Connect(applyAttribute))
                WinEffect:Clean(vapeEvents.MatchEndEvent.Event:Connect(playEffect))
            end
        end,
        Tooltip = 'Lets you pick any win effect, only on your screen'
    })
    local WinEffectName = {}
    for i, v in bedwars.WinEffectMeta do
        table.insert(WinEffectName, v.name)
        NameToId[v.name] = i
    end
    table.sort(WinEffectName)
    List = WinEffect:CreateDropdown({
        Name = 'Effects',
        List = WinEffectName,
        Function = function()
            if WinEffect.Enabled then
                applyAttribute()
            end
        end
    })
end)

-- ===== Render/ArmorTrims.lua =====
run(function()
	local ArmourTrims
	local Trim
	local Colour
	local Effect
	local Tier
	local added = {}
	local trims, colours, effects = {}, {}, {}
	local trimvalues, colourvalues, effectvalues = {}, {}, {}

	local function label(value)
		return (tostring(value):gsub('_', ' '):gsub('%a+', function(word)
			return word:sub(1, 1):upper()..word:sub(2):lower()
		end))
	end

	for _, v in bedwars.ArmorTrimType or {} do
		local meta = bedwars.ArmorTrimMeta and bedwars.ArmorTrimMeta[v]
		local name = meta and meta.name or label(v)
		if trimvalues[name] == nil then
			trimvalues[name] = v
			table.insert(trims, name)
		end
	end
	table.sort(trims)

	for i, v in bedwars.ArmorTrimColor or {} do
		local name = label(i)
		if colourvalues[name] == nil then
			colourvalues[name] = v
			table.insert(colours, name)
		end
	end
	table.sort(colours)

	for _, v in bedwars.ArmorTrimEffectType or {} do
		local meta = bedwars.ArmorTrimEffectMeta and bedwars.ArmorTrimEffectMeta[v]
		local name = meta and meta.name or label(v)
		if effectvalues[name] == nil then
			effectvalues[name] = v
			table.insert(effects, name)
		end
	end
	table.sort(effects)

	local slotnames = {[0] = 'helmet', [1] = 'chestplate', [2] = 'boots'}

	local function wornSlots()
		local worn = {}
		for _, v in store.inventory.inventory.armor or {} do
			local itemmeta = typeof(v) == 'table' and bedwars.ItemMeta[v.itemType]
			if itemmeta and itemmeta.armor and slotnames[itemmeta.armor.slot] then
				worn[slotnames[itemmeta.armor.slot]] = true
			end
		end
		return worn
	end

	local function clearTrim()
		for _, v in added do
			if v.Parent then
				v:Destroy()
			end
		end
		table.clear(added)
	end

	local function applyTrim()
		clearTrim()
		if not ArmourTrims.Enabled or not lplr.Character then return end
		if not bedwars.ArmorTrimController or not bedwars.ArmorTrimUtil or not bedwars.AccessoryUtil then return end

		local trim = trimvalues[Trim.Value]
		local colour = colourvalues[Colour.Value]
		local effect = effectvalues[Effect.Value]
		if not trim or not colour or not effect then return end

		local before = {}
		for _, v in lplr.Character:GetDescendants() do
			before[v] = true
		end

		bedwars.ArmorTrimController:attachArmorTrimEffects(lplr.Character, trim, colour, Tier.Value - 1, effect)

		local colourmeta = bedwars.ArmorTrimColorMeta and bedwars.ArmorTrimColorMeta[colour]
		local worn = wornSlots()
		for _, v in bedwars.ArmorTrimUtil.createArmorTrims(trim, colourmeta and colourmeta.color or Color3.new(1, 1, 1), Tier.Value - 1) do
			local slot
			for piece in worn do
				if table.find(v.Name:split('_'), piece) then
					slot = piece
					break
				end
			end

			if slot then
				bedwars.AccessoryUtil:addAccessory(lplr.Character, v)
			else
				v:Destroy()
			end
		end
		bedwars.WeldTable:weldCharacterAccessories(lplr.Character)

		for _, v in lplr.Character:GetDescendants() do
			if not before[v] then
				table.insert(added, v)
			end
		end
	end

	ArmourTrims = vape.Categories.Render:CreateModule({
		Name = 'ArmourTrims',
		Function = function(callback)
			if callback then
				ArmourTrims:Clean(lplr.CharacterAdded:Connect(function()
					task.wait(1)
					applyTrim()
				end))
				ArmourTrims:Clean(clearTrim)
			end
			applyTrim()
		end,
		Tooltip = 'Shows an armour trim on yourself, only you can see it'
	})

	Trim = ArmourTrims:CreateDropdown({
		Name = 'Trim',
		List = trims,
		Function = function()
			if ArmourTrims.Enabled then
				applyTrim()
			end
		end
	})
	Colour = ArmourTrims:CreateDropdown({
		Name = 'Colour',
		List = colours,
		Function = function()
			if ArmourTrims.Enabled then
				applyTrim()
			end
		end
	})
	Effect = ArmourTrims:CreateDropdown({
		Name = 'Effect',
		List = effects,
		Function = function()
			if ArmourTrims.Enabled then
				applyTrim()
			end
		end
	})
	Tier = ArmourTrims:CreateSlider({
		Name = 'Tier',
		Min = 1,
		Max = 7,
		Default = 7,
		Function = function()
			if ArmourTrims.Enabled then
				applyTrim()
			end
		end,
		Suffix = function(val)
			local meta = bedwars.ArmorTrimEffectRankMeta and bedwars.ArmorTrimEffectRankMeta[val - 1]
			return meta and meta.tier and label(meta.tier) or ''
		end,
		Tooltip = 'Higher tiers use a fancier effect'
	})
end)

-- ===== Render/BedDefense.lua =====
run(function()
	local Sides = sides
	local AddBlur = addBlur
	local Camera = gameCamera
	local CollectionService = collectionService
	local Color = color
	local Entity = entitylib
	local GetPlacedBlock = getPlacedBlock
	local GetVapeAsset = getcustomasset
	local LocalPlayer = lplr
	local RoundPosition = roundPos
	local RunService = runService
	local Store = store
	local UIPallet = uipallet
	local UserInputService = inputService
	local VapeEvents = vapeEvents
	local BedDefense
	local Target
	local MaxLayers
	local View
	local ShowBed
	local AutoRotate
	local RotateSpeed
	local Transparency
	local Holder, Viewport, ViewportCamera, Empty, ButtonRow, BedLabel
	local Layers, Buttons, Tracked = {}, {}, {}
	local TrackedCount, Detected = 0, 0
	local Current, Manual, BedClone
	local Accent
	local Yaw, Pitch, Radius, Center, Zoom = 0, math.rad(28), 12, Vector3.zero, 1
	local Dragging, LastDrag, Pending = nil, Vector3.zero, false
	local Touches, PinchDistance = {}, nil

	local function CloneModel(Object: Instance)
		local Clone: Instance? = Object:Clone()
		if not Clone then return end
		for _, Tag: string in Clone:GetTags() do
			Clone:RemoveTag(Tag)
		end
		for _, v: Instance in Clone:GetDescendants() do
			for _, Tag: string in v:GetTags() do
				v:RemoveTag(Tag)
			end
		end
		return Clone
	end

	local function GetBeds()
		local Beds: {Instance} = {}
		local Team: string = tostring(LocalPlayer:GetAttribute("Team"))
		for _, Bed: Instance in CollectionService:GetTagged("bed") do
			if Bed:IsDescendantOf(workspace) and tostring(Bed:GetAttribute("TeamId")) ~= Team and not table.find(Beds, Bed) then
				table.insert(Beds, Bed)
			end
		end
		table.sort(Beds, function(A: Instance, B: Instance)
			return (tonumber(A:GetAttribute("TeamId")) or 0) < (tonumber(B:GetAttribute("TeamId")) or 0)
		end)
		return Beds
	end

	local function GetBedName(Bed: Instance)
		local TeamId: number? = tonumber(Bed:GetAttribute("TeamId"))
		local Queue = bedwars.QueueMeta[Store.queueType]
		local Team = Queue and TeamId and Queue.teams[TeamId]
		return `{Team and Team.displayName or `Team {TeamId or "?"}`} Bed`
	end

	local function GetTargetBed()
		local Beds: {Instance} = GetBeds()
		if Target.Value == "Manual" then
			return Manual and Manual.Parent and Manual or Beds[1]
		end

		local Origin: Vector3 = Entity.isAlive and Entity.character.RootPart.Position or Camera.CFrame.Position
		local Best, BestScore
		for _, Bed: BasePart in Beds do
			local Score: number = Target.Value == "Crosshair" and -Camera.CFrame.LookVector:Dot((Bed.Position - Camera.CFrame.Position).Unit) or (Bed.Position - Origin).Magnitude
			if not BestScore or Score < BestScore then
				Best, BestScore = Bed, Score
			end
		end
		return Best
	end

	local function ScanLayers(Bed: BasePart)
		local Depth, Queue, BlockLayers = {}, {}, {}
		for _, v: Vector3 in {RoundPosition(Bed.Position), RoundPosition(Bed.CFrame * Vector3.new(0, 0, 3))} do
			Depth[v] = 0
			table.insert(Queue, v)
		end

		local Head: number = 0
		while Head < #Queue do
			Head += 1
			local Position: Vector3 = Queue[Head]
			local Level: number = Depth[Position]
			if Level >= MaxLayers.Value then continue end

			for _, Side: Vector3 in Sides do
				local NextPosition: Vector3 = Position + Side
				if Depth[NextPosition] ~= nil then continue end
				local Block: Instance? = GetPlacedBlock(NextPosition)
				if Block and Block ~= Bed and Block.Name ~= "bed" and not Block:GetAttribute("NoBreak") then
					Depth[NextPosition] = Level + 1
					BlockLayers[Level + 1] = BlockLayers[Level + 1] or {}
					table.insert(BlockLayers[Level + 1], Block)
					table.insert(Queue, NextPosition)
				else
					Depth[NextPosition] = false
				end
			end
		end

		return BlockLayers
	end

	local function GetSelected()
		local Index: number? = tonumber(View.Value:match("%d+"))
		return Index and Index <= Detected and Index or nil
	end

	local function UpdateCamera()
		local Distance: number = Radius / math.tan(math.rad(ViewportCamera.FieldOfView / 2)) * 1.15 * Zoom
		ViewportCamera.CFrame = CFrame.new(Center) * CFrame.Angles(0, Yaw, 0) * CFrame.Angles(-Pitch, 0, 0) * CFrame.new(0, 0, Distance)
	end

	local function SetZoom(Value: number)
		Zoom = math.clamp(Value, 0.35, 3)
		UpdateCamera()
	end

	local function GetPinchDistance()
		return (Touches[1].Position - Touches[2].Position).Magnitude
	end

	local function GetAccent()
		return Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value)
	end

	local function UpdateButtons()
		local Selected: number? = GetSelected()
		Accent = GetAccent()
		for Name: string, Button: TextButton in Buttons do
			local Active: boolean = Selected and Name == `Layer {Selected}` or not Selected and Name == "All"
			Button.BackgroundColor3 = Active and Accent or Color.Light(UIPallet.Main, 0.034)
			Button.Label.TextColor3 = Active and UIPallet.Text or Color.Dark(UIPallet.Text, 0.16)
		end
	end

	local function AddShadow(Label: TextLabel)
		local Shadow: TextLabel = Label:Clone()
		Shadow.Name = "Shadow"
		Shadow.Position = Label.Position + UDim2.fromOffset(1, 1)
		Shadow.TextColor3 = Color3.new()
		Shadow.TextTransparency = 0.65
		Shadow.ZIndex = Label.ZIndex - 1
		Shadow.Parent = Label.Parent
		Label:GetPropertyChangedSignal("Text"):Connect(function()
			Shadow.Text = Label.Text
		end)
		Label:GetPropertyChangedSignal("Visible"):Connect(function()
			Shadow.Visible = Label.Visible
		end)
	end

	local function BuildButtons()
		if not ButtonRow then return end
		for _, Button: TextButton in Buttons do
			Button:Destroy()
		end
		table.clear(Buttons)

		local Names: {string} = {}
		for i: number = 1, Detected do
			table.insert(Names, `Layer {i}`)
		end
		table.insert(Names, "All")

		for i: number, Name: string in Names do
			local Button: TextButton = Instance.new("TextButton")
			Button.Name = Name
			Button.AutoButtonColor = false
			Button.BorderSizePixel = 0
			Button.LayoutOrder = i
			Button.Size = UDim2.new(1 / #Names, -4, 1, 0)
			Button.Text = ""
			Button.Parent = ButtonRow
			local Corner: UICorner = Instance.new("UICorner")
			Corner.CornerRadius = UDim.new(0, 4)
			Corner.Parent = Button
			local Label: TextLabel = Instance.new("TextLabel")
			Label.Name = "Label"
			Label.BackgroundTransparency = 1
			Label.FontFace = UIPallet.Font
			Label.Size = UDim2.fromScale(1, 1)
			Label.Text = Detected > 3 and Name ~= "All" and Name:match("%d+") or Name
			Label.TextSize = 12
			Label.ZIndex = 2
			Label.Parent = Button
			AddShadow(Label)
			Button.MouseButton1Click:Connect(function()
				View:SetValue(Name)
			end)
			Buttons[Name] = Button
		end

		UpdateButtons()
	end

	local function UpdateView()
		if not Viewport then return end
		local Selected: number? = GetSelected()
		local Min, Max = Vector3.one * math.huge, Vector3.one * -math.huge
		local Shown: number = 0

		for i: number, Folder: Folder in Layers do
			local Visible: boolean = not Selected or i == Selected
			Folder.Parent = Visible and Viewport or nil
			if Visible then
				for _, Part: BasePart in Folder:QueryDescendants("BasePart") do
					Min, Max = Min:Min(Part.Position - Part.Size / 2), Max:Max(Part.Position + Part.Size / 2)
					Shown += 1
				end
			end
		end

		if BedClone then
			BedClone.Parent = ShowBed.Enabled and Viewport or nil
			Min, Max = Min:Min(Current.Position - Vector3.one * 3), Max:Max(Current.Position + Vector3.one * 3)
		end

		if Min.X ~= math.huge then
			Center = (Min + Max) / 2
			Radius = math.max((Max - Min).Magnitude / 2, 6)
		end

		local BedPart: Instance? = Current and Current:FindFirstChild("Bed")
		BedLabel.Text = Current and GetBedName(Current) or "No bed"
		BedLabel.TextColor3 = BedPart and BedPart.Color or Color.Dark(UIPallet.Text, 0.16)
		Empty.Visible = not Current or Shown == 0
		Empty.Text = not Current and "No bed found" or Selected and `Layer {Selected} is empty` or "No defense"
		UpdateButtons()
		UpdateCamera()
	end

	local function IsUnchanged(BlockLayers)
		local Count: number = 0
		for Level: number, List: {Instance} in BlockLayers do
			for _, Block: Instance in List do
				if Tracked[Block] ~= Level then return false end
				Count += 1
			end
		end
		return Count == TrackedCount
	end

	local function Rebuild(Bed: Instance?, BlockLayers)
		if vape.ThreadFix then
			setthreadidentity(8)
		end
		Pending = false

		for _, Folder: Folder in Layers do
			Folder:Destroy()
		end
		table.clear(Layers)
		table.clear(Tracked)
		TrackedCount = 0
		if BedClone then
			BedClone:Destroy()
			BedClone = nil
		end

		Current = Bed or GetTargetBed()
		BlockLayers = Current and (BlockLayers or ScanLayers(Current)) or {}
		if Detected ~= #BlockLayers then
			Detected = #BlockLayers
			BuildButtons()
		end
		if Current then
			for i: number = 1, Detected do
				local Folder: Folder = Instance.new("Folder")
				Folder.Name = `Layer{i}`
				for _, Block: Instance in BlockLayers[i] or {} do
					Tracked[Block] = i
					TrackedCount += 1
					local Clone: Instance? = CloneModel(Block)
					if Clone then
						Clone.Parent = Folder
					end
				end
				Layers[i] = Folder
			end
			BedClone = CloneModel(Current)
		end

		UpdateView()
	end

	local function CycleBed(Step: number)
		local Beds: {Instance} = GetBeds()
		if #Beds == 0 then return end

		local Index: number = table.find(Beds, Current) or 0
		Manual = Beds[((Index - 1 + Step) % #Beds) + 1]

		if Target.Value ~= "Manual" then
			Target:SetValue("Manual")
		elseif BedDefense.Button.Enabled then
			Rebuild()
		end
	end

	local function RefreshNear(Data)
		if not Current then return end

		local Position = Data and Data.blockRef and Data.blockRef.blockPosition
		if Position and ((Position * 3) - Current.Position).Magnitude <= 30 then
			Pending = true
		end
	end

	local function CreateArrow(Position: UDim2, Step: number)
		local Button: TextButton = Instance.new("TextButton")
		Button.AnchorPoint = Vector2.new(0.5, 0.5)
		Button.AutoButtonColor = false
		Button.BackgroundColor3 = Color.Light(UIPallet.Main, 0.034)
		Button.BorderSizePixel = 0
		Button.Name = Step < 0 and "Previous" or "Next"
		Button.Position = Position
		Button.Size = UDim2.fromOffset(22, 22)
		Button.Text = ""
		Button.Parent = Holder
		local Corner: UICorner = Instance.new("UICorner")
		Corner.CornerRadius = UDim.new(0, 4)
		Corner.Parent = Button
		local Arrow: ImageLabel = Instance.new("ImageLabel")
		Arrow.AnchorPoint = Vector2.new(0.5, 0.5)
		Arrow.BackgroundTransparency = 1
		Arrow.Image = GetVapeAsset(`ElevateV4/assets/new/expandright.png`)
		Arrow.ImageColor3 = Color.Dark(UIPallet.Text, 0.16)
		Arrow.Position = UDim2.fromScale(0.5, 0.5)
		Arrow.Rotation = Step < 0 and 180 or 0
		Arrow.Size = UDim2.fromOffset(6, 12)
		Arrow.Parent = Button
		Button.MouseButton1Click:Connect(function()
			CycleBed(Step)
		end)
		Button.MouseEnter:Connect(function()
			Button.BackgroundColor3 = Color.Light(UIPallet.Main, 0.1)
			Arrow.ImageColor3 = UIPallet.Text
		end)
		Button.MouseLeave:Connect(function()
			Button.BackgroundColor3 = Color.Light(UIPallet.Main, 0.034)
			Arrow.ImageColor3 = Color.Dark(UIPallet.Text, 0.16)
		end)
	end

	BedDefense = vape:CreateOverlay({
		Name = "Bed Defense",
		Icon = GetVapeAsset(`ElevateV4/assets/new/legit_bedalarm.png`),
		Size = UDim2.fromOffset(16, 16),
		Position = UDim2.fromOffset(12, 13),
		CategorySize = 240,
		Function = function(Callback: boolean)
			if Callback then
				BedDefense:Clean(VapeEvents.PlaceBlockEvent.Event:Connect(RefreshNear))
				BedDefense:Clean(VapeEvents.BreakBlockEvent.Event:Connect(RefreshNear))
				BedDefense:Clean(UserInputService.InputChanged:Connect(function(Input: InputObject)
					if PinchDistance and table.find(Touches, Input) then
						local Distance: number = GetPinchDistance()
						if Distance > 0 then
							SetZoom(Zoom * PinchDistance / Distance)
							PinchDistance = Distance
						end
						return
					end
					if not Dragging then return end
					if Input == Dragging or Input.UserInputType == Enum.UserInputType.MouseMovement and Dragging.UserInputType == Enum.UserInputType.MouseButton1 then
						local Delta: Vector3 = Input.Position - LastDrag
						LastDrag = Input.Position
						Yaw -= Delta.X * 0.01
						Pitch = math.clamp(Pitch + Delta.Y * 0.01, math.rad(-80), math.rad(80))
						UpdateCamera()
					end
				end))
				BedDefense:Clean(UserInputService.InputEnded:Connect(function(Input: InputObject)
					local Index: number? = table.find(Touches, Input)
					if Index then
						table.remove(Touches, Index)
						PinchDistance = nil
					end
					if Dragging and (Input == Dragging or Input.UserInputType == Enum.UserInputType.MouseButton1) then
						Dragging = nil
					end
				end))
				BedDefense:Clean(RunService.RenderStepped:Connect(function(DeltaTime: number)
					if AutoRotate.Enabled and not Dragging and not PinchDistance and Holder.AbsoluteSize.X > 0 and BedDefense.Children.Parent.Visible then
						Yaw += DeltaTime * math.rad(RotateSpeed.Value)
						UpdateCamera()
					end
				end))

				Rebuild()

				local Checked: number = tick()
				repeat
					if GetAccent() ~= Accent then
						UpdateButtons()
					end
					local Bed: Instance? = GetTargetBed()
					if Pending or Bed ~= Current then
						Rebuild(Bed)
					elseif Bed and (tick() - Checked) > 0.5 then
						Checked = tick()
						local BlockLayers = ScanLayers(Bed)
						if not IsUnchanged(BlockLayers) then
							Rebuild(Bed, BlockLayers)
						end
					end
					task.wait(0.1)
				until not BedDefense.Button.Enabled
			else
				Dragging, Pending, PinchDistance = nil, false, nil
				table.clear(Touches)
				for _, Folder: Folder in Layers do
					Folder:Destroy()
				end
				table.clear(Layers)
				if BedClone then
					BedClone:Destroy()
					BedClone = nil
				end
				Current = nil
			end
		end
	})

	local OldColor = BedDefense.Color
	function BedDefense:Color(Hue: number, Sat: number, Val: number, IsRainbow: boolean)
		OldColor(self, Hue, Sat, Val, IsRainbow)
		if Holder then
			UpdateButtons()
		end
	end

	Target = BedDefense:CreateDropdown({
		Name = "Bed",
		List = {"Nearest", "Crosshair", "Manual"},
		Function = function()
			if BedDefense.Button.Enabled then
				Rebuild()
			end
		end,
		Tooltip = 'Nearest - the closest enemy bed\nCrosshair - the one you look at\nManual - the one you pick with the arrows'
	})
	View = BedDefense:CreateDropdown({
		Name = "View",
		List = {"All", "Layer 1", "Layer 2", "Layer 3", "Layer 4", "Layer 5", "Layer 6", "Layer 7", "Layer 8", "Layer 9", "Layer 10"},
		Function = function()
			UpdateView()
		end,
		Tooltip = 'Which layer of the defense to show'
	})
	MaxLayers = BedDefense:CreateSlider({
		Name = "Max layers",
		Min = 1,
		Max = 10,
		Default = 6,
		Function = function()
			if Holder and BedDefense.Button.Enabled then
				Rebuild()
			end
		end,
		Tooltip = 'How many layers to scan out from the bed'
	})
	ShowBed = BedDefense:CreateToggle({
		Name = "Show bed",
		Function = function()
			UpdateView()
		end,
		Default = true
	})
	AutoRotate = BedDefense:CreateGroup({
		Name = "Auto rotate",
		Default = true
	})
	RotateSpeed = AutoRotate:CreateSlider({
		Name = "Rotate speed",
		Min = 5,
		Max = 90,
		Default = 20,
		Darker = true,
		Suffix = "Â°/s"
	})
	Transparency = BedDefense:CreateSlider({
		Name = "Transparency",
		Min = 0,
		Max = 1,
		Default = 0.5,
		Decimal = 10,
		Function = function(Val: number)
			if Holder then
				Holder.BackgroundTransparency = Val
			end
		end
	})

	Holder = Instance.new("Frame")
	Holder.BackgroundColor3 = Color.Dark(UIPallet.Main, 0.1)
	Holder.BackgroundTransparency = Transparency.Value
	Holder.ClipsDescendants = true
	Holder.Size = UDim2.fromOffset(240, 246)
	Holder.Parent = BedDefense.Children
	AddBlur(Holder)
	local Corner: UICorner = Instance.new("UICorner")
	Corner.CornerRadius = UDim.new(0, 5)
	Corner.Parent = Holder

	BedLabel = Instance.new("TextLabel")
	BedLabel.BackgroundTransparency = 1
	BedLabel.FontFace = UIPallet.Font
	BedLabel.Position = UDim2.fromOffset(32, 0)
	BedLabel.Size = UDim2.new(1, -64, 0, 32)
	BedLabel.Text = "No bed"
	BedLabel.TextColor3 = Color.Dark(UIPallet.Text, 0.16)
	BedLabel.TextSize = 13
	BedLabel.TextTruncate = Enum.TextTruncate.AtEnd
	BedLabel.Parent = Holder
	AddShadow(BedLabel)

	CreateArrow(UDim2.fromOffset(16, 16), -1)
	CreateArrow(UDim2.new(1, -16, 0, 16), 1)

	local TopDivider: Frame = Instance.new("Frame")
	TopDivider.BackgroundColor3 = Color.Light(UIPallet.Main, 0.04)
	TopDivider.BorderSizePixel = 0
	TopDivider.Position = UDim2.fromOffset(0, 32)
	TopDivider.Size = UDim2.new(1, 0, 0, 1)
	TopDivider.Parent = Holder

	Viewport = Instance.new("ViewportFrame")
	Viewport.Ambient = Color3.fromRGB(170, 170, 170)
	Viewport.BackgroundTransparency = 1
	Viewport.LightColor = Color3.new(1, 1, 1)
	Viewport.LightDirection = Vector3.new(-0.4, -1, -0.3)
	Viewport.Position = UDim2.fromOffset(0, 33)
	Viewport.Size = UDim2.new(1, 0, 0, 176)
	Viewport.Parent = Holder
	ViewportCamera = Instance.new("Camera")
	ViewportCamera.FieldOfView = 40
	ViewportCamera.Parent = Viewport
	Viewport.CurrentCamera = ViewportCamera

	local Capture: TextButton = Instance.new("TextButton")
	Capture.BackgroundTransparency = 1
	Capture.Position = Viewport.Position
	Capture.Size = Viewport.Size
	Capture.Text = ""
	Capture.Parent = Holder
	Capture.InputBegan:Connect(function(Input: InputObject)
		if Input.UserInputType == Enum.UserInputType.Touch then
			table.insert(Touches, Input)
			if #Touches == 2 then
				Dragging, PinchDistance = nil, GetPinchDistance()
				return
			end
		end
		if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
			Dragging, LastDrag = Input, Input.Position
		end
	end)
	Capture.InputChanged:Connect(function(Input: InputObject)
		if Input.UserInputType == Enum.UserInputType.MouseWheel then
			SetZoom(Zoom * (1 - Input.Position.Z * 0.12))
		end
	end)

	Empty = Instance.new("TextLabel")
	Empty.BackgroundTransparency = 1
	Empty.FontFace = UIPallet.Font
	Empty.Position = UDim2.fromOffset(0, 186)
	Empty.Size = UDim2.new(1, 0, 0, 20)
	Empty.Text = "No bed found"
	Empty.TextColor3 = Color.Dark(UIPallet.Text, 0.16)
	Empty.TextSize = 12
	Empty.ZIndex = 2
	Empty.Parent = Holder
	AddShadow(Empty)

	local BottomDivider: Frame = TopDivider:Clone()
	BottomDivider.Position = UDim2.fromOffset(0, 209)
	BottomDivider.Parent = Holder

	ButtonRow = Instance.new("Frame")
	ButtonRow.BackgroundTransparency = 1
	ButtonRow.Position = UDim2.fromOffset(4, 214)
	ButtonRow.Size = UDim2.new(1, -8, 0, 26)
	ButtonRow.Parent = Holder
	local Layout: UIListLayout = Instance.new("UIListLayout")
	Layout.FillDirection = Enum.FillDirection.Horizontal
	Layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
	Layout.Padding = UDim.new(0, 4)
	Layout.SortOrder = Enum.SortOrder.LayoutOrder
	Layout.Parent = ButtonRow
	BuildButtons()
end)

-- ===== Render/BedESP.lua =====
run(function()
	local Camera = gameCamera
	local CollectionService = collectionService
	local Entity = entitylib
	local LocalPlayer = lplr
	local RunService = runService
	local Store = store
	local BedESP
	local Method
	local Color
	local TeamColor
	local BoundingBox
	local Filled
	local HealthBar
	local Name
	local Background
	local HideOwn
	local Distance
	local DistanceLimit
	local Reference = {}
	local BedData = {}
	local Shown: {[Instance]: boolean} = {}
	local MethodUsed: string
	local LastCamera, LastViewport

	local CornerSigns: {Vector3} = {
		Vector3.new(1, 1, 1),
		Vector3.new(1, -1, 1),
		Vector3.new(-1, 1, 1),
		Vector3.new(-1, -1, 1),
		Vector3.new(1, 1, -1),
		Vector3.new(1, -1, -1),
		Vector3.new(-1, 1, -1),
		Vector3.new(-1, -1, -1)
	}

	local function ESPWorldToViewport(Position: Vector3): Vector2
		local ViewportPoint: Vector3 = Camera:WorldToViewportPoint(Position)
		return Vector2.new(ViewportPoint.X, ViewportPoint.Y)
	end

	local function GetBedColor(Bed: Instance)
		local Part: Instance? = Bed:FindFirstChild("Bed")
		return TeamColor.Enabled and Part and Part.Color or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	end

	local function GetBedName(Bed: Instance)
		local TeamId: number? = tonumber(Bed:GetAttribute("TeamId"))
		local Queue = bedwars.QueueMeta[Store.queueType]
		local Team = Queue and TeamId and Queue.teams[TeamId]
		return `{Team and Team.displayName or `Team {TeamId or "?"}`} Bed`
	end

	local function GetBedData(Bed: BasePart)
		local Origin: CFrame = Bed.CFrame
		local Min, Max = Vector3.one * math.huge, Vector3.one * -math.huge
		for _, v: Instance in Bed:GetChildren() do
			if v:IsA("BasePart") and v.Name ~= "Blanket" then
				local PartCFrame, HalfSize = Origin:ToObjectSpace(v.CFrame), v.Size / 2
				if v.Name == "Legs" then
					PartCFrame, HalfSize = PartCFrame * CFrame.new(0, -0.4, 0), HalfSize - Vector3.new(0, 0.5, 0)
				end
				for _, Sign: Vector3 in CornerSigns do
					local Position: Vector3 = PartCFrame * (HalfSize * Sign)
					Min, Max = Min:Min(Position), Max:Max(Position)
				end
			end
		end
		if Min.X == math.huge then
			Min, Max = -Bed.Size / 2, Bed.Size / 2
		end

		local Center, Extents = (Min + Max) / 2, (Max - Min) / 2
		local Corners: {Vector3} = {}
		for i: number, Sign: Vector3 in CornerSigns do
			Corners[i] = Origin * (Center + Extents * Sign)
		end

		return {
			Center = Origin * Center,
			Corners = Corners,
			TeamId = tonumber(Bed:GetAttribute("TeamId")),
			BlockPosition = bedwars.BlockController:getBlockPosition(Bed.Position)
		}
	end

	local function GetBedHealth(Bed: BasePart, Data)
		local BlockData = bedwars.BlockController:getStore():getBlockData(Data.BlockPosition)
		local Health: number = BlockData and (BlockData:GetAttribute("1") or BlockData:GetAttribute("Health")) or Bed:GetAttribute("Health") or 1
		return math.clamp(Health / (Bed:GetAttribute("MaxHealth") or 1), 0, 1)
	end

	local function IsHidden(Bed: Instance, Data, LocalPosition: Vector3?, LocalTeam: number?)
		if HideOwn.Enabled and Data.TeamId == LocalTeam then return true end
		if Distance.Enabled then
			local BedDistance: number = LocalPosition and (LocalPosition - Data.Center).Magnitude or math.huge
			return BedDistance < DistanceLimit.ValueMin or BedDistance > DistanceLimit.ValueMax
		end
		return false
	end

	local ESPAdded = {
		Drawing2D = function(Bed: Instance)
			if vape.ThreadFix then
				setthreadidentity(8)
			end
			local BedDrawings = {}
			BedDrawings.Main = Drawing.new("Square")
			BedDrawings.Main.Transparency = BoundingBox.Enabled and 1 or 0
			BedDrawings.Main.ZIndex = 2
			BedDrawings.Main.Filled = false
			BedDrawings.Main.Thickness = 1
			BedDrawings.Main.Color = GetBedColor(Bed)

			if BoundingBox.Enabled then
				BedDrawings.Border = Drawing.new("Square")
				BedDrawings.Border.Transparency = 0.35
				BedDrawings.Border.ZIndex = 1
				BedDrawings.Border.Thickness = 1
				BedDrawings.Border.Filled = false
				BedDrawings.Border.Color = Color3.new()
				BedDrawings.Border2 = Drawing.new("Square")
				BedDrawings.Border2.Transparency = 0.35
				BedDrawings.Border2.ZIndex = 1
				BedDrawings.Border2.Thickness = 1
				BedDrawings.Border2.Filled = Filled.Enabled
				BedDrawings.Border2.Color = Color3.new()
			end

			if HealthBar.Enabled then
				BedDrawings.HealthLine = Drawing.new("Line")
				BedDrawings.HealthLine.Thickness = 1
				BedDrawings.HealthLine.ZIndex = 2
				BedDrawings.HealthBorder = Drawing.new("Line")
				BedDrawings.HealthBorder.Thickness = 3
				BedDrawings.HealthBorder.Transparency = 0.35
				BedDrawings.HealthBorder.ZIndex = 1
				BedDrawings.HealthBorder.Color = Color3.new()
			end

			if Name.Enabled then
				if Background.Enabled then
					BedDrawings.TextBKG = Drawing.new("Square")
					BedDrawings.TextBKG.Transparency = 0.35
					BedDrawings.TextBKG.ZIndex = 0
					BedDrawings.TextBKG.Thickness = 1
					BedDrawings.TextBKG.Filled = true
					BedDrawings.TextBKG.Color = Color3.new()
				end
				BedDrawings.Drop = Drawing.new("Text")
				BedDrawings.Drop.Color = Color3.new()
				BedDrawings.Drop.Text = GetBedName(Bed)
				BedDrawings.Drop.ZIndex = 1
				BedDrawings.Drop.Center = true
				BedDrawings.Drop.Size = 20
				BedDrawings.Text = Drawing.new("Text")
				BedDrawings.Text.Text = BedDrawings.Drop.Text
				BedDrawings.Text.ZIndex = 2
				BedDrawings.Text.Color = BedDrawings.Main.Color
				BedDrawings.Text.Center = true
				BedDrawings.Text.Size = 20
			end
			Reference[Bed] = BedDrawings
		end,
		Drawing3D = function(Bed: Instance)
			if vape.ThreadFix then
				setthreadidentity(8)
			end
			local BedDrawings = {}
			for i: number = 1, 12 do
				BedDrawings[`Line{i}`] = Drawing.new("Line")
			end

			local BedColor: Color3 = GetBedColor(Bed)
			for _, v: any in BedDrawings do
				v.Thickness = 1
				v.Color = BedColor
			end

			Reference[Bed] = BedDrawings
		end
	}

	local function ESPRemoved(Bed: Instance)
		local BedDrawings = Reference[Bed]
		if BedDrawings then
			if vape.ThreadFix then
				setthreadidentity(8)
			end
			Reference[Bed] = nil
			BedData[Bed] = nil
			Shown[Bed] = nil
			for _, v: any in BedDrawings do
				pcall(function()
					v.Visible = false
					v:Remove()
				end)
			end
		end
	end

	local ColorFunc = {
		Drawing2D = function()
			for Bed: Instance, v: any in Reference do
				v.Main.Color = GetBedColor(Bed)
				if v.Text then
					v.Text.Color = v.Main.Color
				end
			end
		end,
		Drawing3D = function()
			for Bed: Instance, v: any in Reference do
				local BedColor: Color3 = GetBedColor(Bed)
				for _, Line: any in v do
					Line.Color = BedColor
				end
			end
		end
	}

	local ESPLoop = {
		Drawing2D = function()
			if vape.ThreadFix then
				setthreadidentity(8)
			end

			local LocalPosition = Entity.isAlive and Entity.character.RootPart.Position
			local LocalTeam: number? = tonumber(LocalPlayer:GetAttribute("Team"))
			local CameraCFrame, Viewport = Camera.CFrame, Camera.ViewportSize
			local Moved = CameraCFrame ~= LastCamera or Viewport ~= LastViewport
			LastCamera, LastViewport = CameraCFrame, Viewport
			local Now = os.clock()

			for Bed: Instance, v: any in Reference do
				local Data = BedData[Bed]
				local RootVisible = Data.OnScreen
				if Moved or RootVisible == nil then
					local _, OnScreen = Camera:WorldToViewportPoint(Data.Center)
					Data.OnScreen, RootVisible = OnScreen, OnScreen
				end
				RootVisible = RootVisible and not IsHidden(Bed, Data, LocalPosition, LocalTeam)
				if Shown[Bed] ~= RootVisible then
					Shown[Bed] = RootVisible
					Data.Box = nil
					for _, Object: any in v do
						Object.Visible = RootVisible
					end
				end
				if not RootVisible then continue end

				local Health = Data.Health
				if v.HealthLine and (not Health or Now - (Data.HealthAt or 0) > 0.25) then
					Data.HealthAt = Now
					Health = GetBedHealth(Bed, Data)
				end
				if not Moved and Data.Box and Health == Data.Health then continue end

				local MinX, MinY, MaxX, MaxY = math.huge, math.huge, -math.huge, -math.huge
				for _, Corner: Vector3 in Data.Corners do
					local Position: Vector3 = Camera:WorldToViewportPoint(Corner)
					MinX, MinY = math.min(MinX, Position.X), math.min(MinY, Position.Y)
					MaxX, MaxY = math.max(MaxX, Position.X), math.max(MaxY, Position.Y)
				end
				local PosX, PosY, SizeX, SizeY = MinX // 1, MinY // 1, (MaxX - MinX) // 1, (MaxY - MinY) // 1
				local Box = Data.Box
				if Box and Box[1] == PosX and Box[2] == PosY and Box[3] == SizeX and Box[4] == SizeY and Health == Data.Health then continue end
				Data.Box = {PosX, PosY, SizeX, SizeY}
				Data.Health = Health
				v.Main.Position = Vector2.new(PosX, PosY) // 1
				v.Main.Size = Vector2.new(SizeX, SizeY) // 1
				if v.Border then
					v.Border.Position = Vector2.new(PosX - 1, PosY - 1) // 1
					v.Border.Size = Vector2.new(SizeX + 2, SizeY + 2) // 1
					v.Border2.Position = Vector2.new(PosX + 1, PosY + 1) // 1
					v.Border2.Size = Vector2.new(SizeX - 2, SizeY - 2) // 1
				end

				if v.HealthLine then
					v.HealthLine.Color = Color3.fromHSV(Health / 2.5, 0.89, 0.75)
					v.HealthLine.From = Vector2.new(PosX - 6, PosY + SizeY) // 1
					v.HealthLine.To = Vector2.new(PosX - 6, PosY + SizeY - (SizeY * Health)) // 1
					v.HealthBorder.From = Vector2.new(PosX - 6, PosY + SizeY + 1) // 1
					v.HealthBorder.To = Vector2.new(PosX - 6, PosY - 1) // 1
				end

				if v.Text then
					local TextPosition: Vector2 = Vector2.new(PosX + (SizeX / 2), PosY - 28) // 1
					v.Text.Position = TextPosition
					v.Drop.Position = TextPosition + Vector2.new(1, 1)
					if v.TextBKG then
						local TextBounds: Vector2 = v.Text.TextBounds
						v.TextBKG.Size = TextBounds + Vector2.new(8, 4)
						v.TextBKG.Position = TextPosition - Vector2.new(4 + (TextBounds.X / 2), 0)
					end
				end
			end
		end,
		Drawing3D = function()
			if vape.ThreadFix then
				setthreadidentity(8)
			end

			local LocalPosition = Entity.isAlive and Entity.character.RootPart.Position
			local LocalTeam: number? = tonumber(LocalPlayer:GetAttribute("Team"))

			local CameraCFrame, Viewport = Camera.CFrame, Camera.ViewportSize
			local Moved = CameraCFrame ~= LastCamera or Viewport ~= LastViewport
			LastCamera, LastViewport = CameraCFrame, Viewport

			for Bed: Instance, v: any in Reference do
				local Data = BedData[Bed]
				local RootVisible = Data.OnScreen
				if Moved or RootVisible == nil then
					local _, OnScreen = Camera:WorldToViewportPoint(Data.Center)
					Data.OnScreen, RootVisible = OnScreen, OnScreen
				end
				RootVisible = RootVisible and not IsHidden(Bed, Data, LocalPosition, LocalTeam)
				local Became = Shown[Bed] ~= RootVisible
				if Became then
					Shown[Bed] = RootVisible
					for _, Object: any in v do
						Object.Visible = RootVisible
					end
				end
				if not RootVisible or not (Moved or Became) then continue end

				local Corners: {Vector3} = Data.Corners
				local Point1: Vector2 = ESPWorldToViewport(Corners[1])
				local Point2: Vector2 = ESPWorldToViewport(Corners[2])
				local Point3: Vector2 = ESPWorldToViewport(Corners[3])
				local Point4: Vector2 = ESPWorldToViewport(Corners[4])
				local Point5: Vector2 = ESPWorldToViewport(Corners[5])
				local Point6: Vector2 = ESPWorldToViewport(Corners[6])
				local Point7: Vector2 = ESPWorldToViewport(Corners[7])
				local Point8: Vector2 = ESPWorldToViewport(Corners[8])
				v.Line1.From = Point1
				v.Line1.To = Point2
				v.Line2.From = Point3
				v.Line2.To = Point4
				v.Line3.From = Point5
				v.Line3.To = Point6
				v.Line4.From = Point7
				v.Line4.To = Point8
				v.Line5.From = Point1
				v.Line5.To = Point3
				v.Line6.From = Point1
				v.Line6.To = Point5
				v.Line7.From = Point5
				v.Line7.To = Point7
				v.Line8.From = Point7
				v.Line8.To = Point3
				v.Line9.From = Point2
				v.Line9.To = Point4
				v.Line10.From = Point2
				v.Line10.To = Point6
				v.Line11.From = Point6
				v.Line11.To = Point8
				v.Line12.From = Point8
				v.Line12.To = Point4
			end
		end
	}

	local function Added(Bed: Instance)
		if not BedESP.Enabled or not Bed.Parent then return end
		if Reference[Bed] then
			ESPRemoved(Bed)
		end
		BedData[Bed] = GetBedData(Bed)
		ESPAdded[MethodUsed](Bed)
	end

	local function Refresh()
		if BedESP.Enabled then
			BedESP:Toggle()
			BedESP:Toggle()
		end
	end

	BedESP = vape.Categories.Render:CreateModule({
		Name = "BedESP",
		Function = function(Callback: boolean)
			if Callback then
				MethodUsed = `Drawing{Method.Value}`
				BedESP:Clean(CollectionService:GetInstanceAddedSignal("bed"):Connect(function(Bed: Instance)
					task.delay(0.2, Added, Bed)
				end))
				BedESP:Clean(CollectionService:GetInstanceRemovedSignal("bed"):Connect(ESPRemoved))
				BedESP:Clean(vape.Categories.Friends.ColorUpdate.Event:Connect(function()
					ColorFunc[MethodUsed]()
				end))
				BedESP:Clean(RunService.RenderStepped:Connect(ESPLoop[MethodUsed]))
				for _, v: Instance in CollectionService:GetTagged("bed") do
					Added(v)
				end
			else
				for Bed: Instance in Reference do
					ESPRemoved(Bed)
				end
			end
		end,
		Tooltip = 'Shows beds through walls'
	})

	Method = BedESP:CreateDropdown({
		Name = "Mode",
		List = {"2D", "3D"},
		Function = function(Val: string)
			Refresh()
			BoundingBox.Object.Visible = (Val == "2D")
			Filled.Object.Visible = (Val == "2D")
			HealthBar.Object.Visible = (Val == "2D")
			Name.Object.Visible = (Val == "2D")
			Background.Object.Visible = Name.Object.Visible and Name.Enabled
		end
	})
	Color = BedESP:CreateColorSlider({
		Name = "Bed Color",
		Function = function()
			if BedESP.Enabled and ColorFunc[MethodUsed] then
				ColorFunc[MethodUsed]()
			end
		end
	})
	TeamColor = BedESP:CreateToggle({
		Name = "Use Team Color",
		Function = function()
			if BedESP.Enabled and ColorFunc[MethodUsed] then
				ColorFunc[MethodUsed]()
			end
		end,
		Default = true,
		Darker = true
	})
	BoundingBox = BedESP:CreateToggle({
		Name = "Bounding Box",
		Function = Refresh,
		Default = true,
		Darker = true
	})
	Filled = BedESP:CreateToggle({
		Name = "Filled",
		Function = Refresh,
		Darker = true
	})
	HealthBar = BedESP:CreateToggle({
		Name = "Health Bar",
		Function = Refresh,
		Darker = true
	})
	Name = BedESP:CreateToggle({
		Name = "Name",
		Function = function(Callback: boolean)
			Refresh()
			Background.Object.Visible = Callback
		end,
		Darker = true
	})
	Background = BedESP:CreateToggle({
		Name = "Show Background",
		Function = Refresh,
		Darker = true
	})
	HideOwn = BedESP:CreateToggle({
		Name = "Hide Own Bed",
		Default = true,
		Tooltip = "Hides your own team's bed"
	})
	Distance = BedESP:CreateGroup({
		Name = "Distance Check",
	})
	DistanceLimit = Distance:CreateTwoSlider({
		Name = "Bed Distance",
		Min = 0,
		Max = 512,
		DefaultMin = 0,
		DefaultMax = 256,
		Darker = true
	})
end)

-- ===== Render/BedPlates.lua =====
run(function()
    local BedPlates
    local Background
    local Color
    local LayerCounter
    local LayerColor
    local Reference = {}
    local Folder = Instance.new('Folder')
    Folder.Parent = vape.gui

    local function getBlockLayerHealth(block)
	local meta = bedwars.ItemMeta[block]
	return meta and meta.block and meta.block.health or 0
    end

    local function getLayerColor()
	return LayerColor and Color3.fromHSV(LayerColor.Hue, LayerColor.Sat, LayerColor.Value) or Color3.new(1, 1, 1)
    end

    local function scanSide(self, start, tab)
	for _, side in sides do
		local layers = {}
		for i = 1, 15 do
			local block = getPlacedBlock(start + (side * i))
			if not block or block == self or block.Name == 'bed' then
				break
			end
			if not block:GetAttribute('NoBreak') then
				layers[block.Name] = (layers[block.Name] or 0) + 1
			end
		end

		for block, amount in layers do
			tab[block] = math.max(tab[block] or 0, amount)
		end
	end
    end

    local function refreshAdornee(v)
	for _, obj in v.Frame:GetChildren() do
		if obj:IsA('ImageLabel') and obj.Name ~= 'Blur' then
			obj:Destroy()
		end
	end

	local start = v.Adornee.Position
	local layers = {}
	local alreadygot = {}
	scanSide(v.Adornee, start, layers)
	scanSide(v.Adornee, start + Vector3.new(0, 0, 3), layers)
	for block, amount in layers do
		table.insert(alreadygot, {block, amount})
	end
	table.sort(alreadygot, function(a, b)
		local healthA, healthB = getBlockLayerHealth(a[1]), getBlockLayerHealth(b[1])
		return healthA == healthB and a[1] < b[1] or healthA > healthB
	end)
	v.Enabled = #alreadygot > 0

	for _, blockData in alreadygot do
		local block, amount = blockData[1], blockData[2]
		local blockimage = Instance.new('ImageLabel')
		blockimage.Size = UDim2.fromOffset(32, 32)
		blockimage.BackgroundTransparency = 1
		blockimage.Image = bedwars.getIcon({ itemType = block }, true)
		blockimage.Parent = v.Frame
		if amount > 1 and (not LayerCounter or LayerCounter.Enabled) then
			local amounttext = Instance.new('TextLabel')
			amounttext.Name = 'Amount'
			amounttext.Size = UDim2.fromScale(1, 1)
			amounttext.BackgroundTransparency = 1
			amounttext.Text = tostring(amount)
			amounttext.TextColor3 = getLayerColor()
			amounttext.TextSize = 16
			amounttext.TextStrokeTransparency = 0.3
			amounttext.Font = Enum.Font.Arial
			amounttext.Parent = blockimage
		end
	end
    end

    local function refreshAll()
	for _, v in Reference do
		refreshAdornee(v)
	end
    end

    local function updateLayerTextColor()
	local textColor = getLayerColor()
	for _, v in Reference do
		for _, obj in v.Frame:GetDescendants() do
			if obj:IsA('TextLabel') and obj.Name == 'Amount' then
				obj.TextColor3 = textColor
			end
		end
	end
    end

    local function Added(v)
	local billboard = Instance.new('BillboardGui')
	billboard.Parent = Folder
	billboard.Name = 'bed'
	billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
	billboard.Size = UDim2.fromOffset(36, 36)
	billboard.AlwaysOnTop = true
	billboard.ClipsDescendants = false
	billboard.Adornee = v
	local blur = addBlur(billboard)
	blur.Visible = Background.Enabled
	local frame = Instance.new('Frame')
	frame.Size = UDim2.fromScale(1, 1)
	frame.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	frame.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
	frame.Parent = billboard
	local layout = Instance.new('UIListLayout')
	layout.FillDirection = Enum.FillDirection.Horizontal
	layout.Padding = UDim.new(0, 4)
	layout.VerticalAlignment = Enum.VerticalAlignment.Center
	layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
	layout:GetPropertyChangedSignal('AbsoluteContentSize'):Connect(function()
		billboard.Size = UDim2.fromOffset(math.max(layout.AbsoluteContentSize.X + 4, 36), 36)
	end)
	layout.Parent = frame
	local corner = Instance.new('UICorner')
	corner.CornerRadius = UDim.new(0, 4)
	corner.Parent = frame
	Reference[v] = billboard
	refreshAdornee(billboard)
    end

    local function refreshNear(data)
	data = data.blockRef.blockPosition * 3
	for i, v in Reference do
		if (data - i.Position).Magnitude <= 30 then
			refreshAdornee(v)
		end
	end
    end

    BedPlates = vape.Categories.Render:CreateModule({
	Name = 'BedPlates',
	Function = function(callback)
		if callback then
			for _, v in collectionService:GetTagged('bed') do
				task.spawn(Added, v)
			end
			BedPlates:Clean(vapeEvents.PlaceBlockEvent.Event:Connect(refreshNear))
			BedPlates:Clean(vapeEvents.BreakBlockEvent.Event:Connect(refreshNear))
			BedPlates:Clean(collectionService:GetInstanceAddedSignal('bed'):Connect(Added))
			BedPlates:Clean(collectionService:GetInstanceRemovedSignal('bed'):Connect(function(v)
				if Reference[v] then
					Reference[v]:Destroy()
					Reference[v]:ClearAllChildren()
					Reference[v] = nil
				end
			end))
		else
			table.clear(Reference)
			Folder:ClearAllChildren()
		end
	end,
	Tooltip = 'Shows which blocks surround each bed',
    })
    Background = BedPlates:CreateGroup({
	Name = 'Background',
	Function = function(callback)
		for _, v in Reference do
			v.Frame.BackgroundTransparency = 1 - (callback and Color.Opacity or 0)
			v.Blur.Visible = callback
		end
	end,
	Default = true,
    })
    Color = Background:CreateColorSlider({
	Name = 'Background Colour',
	DefaultValue = 0,
	DefaultOpacity = 0.5,
	Function = function(hue, sat, val, opacity)
		for _, v in Reference do
			v.Frame.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
			v.Frame.BackgroundTransparency = 1 - opacity
		end
	end,
	Darker = true,
    })
    LayerCounter = BedPlates:CreateGroup({
	Name = 'Layer Counter',
	Function = function(callback)
		refreshAll()
	end,
	Default = true,
    })
    LayerColor = LayerCounter:CreateColorSlider({
	Name = 'Counter Text Colour',
	DefaultSat = 0,
	DefaultValue = 1,
	Function = function()
		updateLayerTextColor()
	end,
	Visible = LayerCounter.Enabled,
    })
end)

-- ===== Render/BeehiveESP.lua =====
run(function()
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui

	local function createSection()
		local section = {
			Enabled = false,
			Connections = {},
			Reference = {},
			Folder = Instance.new('Folder')
		}
		section.Folder.Parent = Folder
		function section:Clean(item)
			if type(item) == 'function' then
				table.insert(self.Connections, {Disconnect = item})
			elseif item then
				table.insert(self.Connections, item)
			end
		end
		function section:Clear()
			for _, connection in self.Connections do
				pcall(function() connection:Disconnect() end)
			end
			table.clear(self.Connections)
			if self.Stop then self.Stop(self) end
			for _, instance in self.Reference do
				pcall(function() instance:Destroy() end)
			end
			table.clear(self.Reference)
			self.Folder:ClearAllChildren()
		end
		function section:Set(callback)
			if callback == self.Enabled then return end
			self.Enabled = callback
			self:Clear()
			if callback and self.Start then self.Start(self) end
		end
		return section
	end
	local Beehives = createSection()
	local BeehiveColor, BeehiveTransparency, BeehiveScale
	local Callbacks = {}
	local BeehiveESP = vape.Categories.Render:CreateModule({
		Name = 'BeehiveESP',
		Function = function(callback)
			Beehives:Set(callback)
			for _, setting in {BeehiveColor,
				BeehiveTransparency,
				BeehiveScale} do
				if setting and setting.Object then
					setting.Object.Visible = callback
				end
			end
		end,
		Tooltip = 'Shows beehives and their info'
	})
	BeehiveColor = BeehiveESP:CreateColorSlider({Visible = false, Function = function(...) if Callbacks.BeehiveColor then return Callbacks.BeehiveColor(...) end end, Name = 'Hive text colour'})
	BeehiveTransparency = BeehiveESP:CreateSlider({Visible = false, Function = function(...) if Callbacks.BeehiveTransparency then return Callbacks.BeehiveTransparency(...) end end, Name = 'Hive transparency', Default = 0.5, Min = 0, Max = 1, Decimal = 100})
	BeehiveScale = BeehiveESP:CreateSlider({Visible = false, Function = function(...) if Callbacks.BeehiveScale then return Callbacks.BeehiveScale(...) end end, Name = 'Hive scale', Default = 1, Min = 0.1, Max = 1.5, Decimal = 10})

	Beehives.Start = function(self)
		local strings, updates = {}, {}
		local function updated(ent)
			local nametag = self.Reference[ent]
			if nametag then
				nametag.TextSize = 14 * BeehiveScale.Value
				nametag.TextColor3 = Color3.fromHSV(BeehiveColor.Hue, BeehiveColor.Sat, BeehiveColor.Value)
				nametag.BackgroundTransparency = BeehiveTransparency.Value
			end
		end
		local function removing(ent)
			if self.Reference[ent] then
				self.Reference[ent]:Destroy()
				self.Reference[ent] = nil
			end
		end
		local function added(ent)
			local name = playersService:GetNameFromUserIdAsync(ent:GetAttribute('PlacedByUserId')) or 'Unknown'
			strings[ent] = `{name}'s beehive | %s Bee%s`
			local nametag = Instance.new('TextLabel')
			nametag.TextSize = 14 * BeehiveScale.Value
			nametag.Font = Enum.Font.Arial
			local format = string.format(strings[ent], tostring(ent:GetAttribute('Level') or 0), (ent:GetAttribute('Level') or 0) >= 2 and 's' or '')
			local size = getfontsize(format, nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
			nametag.Name = name
			nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
			nametag.AnchorPoint = Vector2.new(0.5, 1)
			nametag.BackgroundColor3 = Color3.new()
			nametag.BackgroundTransparency = 0.5
			nametag.BorderSizePixel = 0
			nametag.Visible = false
			nametag.Text = format
			nametag.TextColor3 = Color3.fromHSV(BeehiveColor.Hue, BeehiveColor.Sat, BeehiveColor.Value)
			nametag.RichText = true
			nametag.Parent = self.Folder
			self.Reference[ent] = nametag
			self:Clean(ent:GetAttributeChangedSignal('Level'):Connect(function()
				updates[ent] = true
			end))
			updates[ent] = true
		end
		self.Stop = function(inner)
			table.clear(strings)
			table.clear(updates)
		end
		for _, v in collectionService:GetTagged('beehive') do
			added(v)
		end
		self:Clean(collectionService:GetInstanceAddedSignal('beehive'):Connect(added))
		self:Clean(collectionService:GetInstanceRemovedSignal('beehive'):Connect(removing))
		self:Clean(runService.PreRender:Connect(function()
			for ent, nametag in self.Reference do
				local headPos, headVis = gameCamera:WorldToViewportPoint(ent.Position + Vector3.new(0, 1, 0))
				nametag.Visible = headVis
				if not headVis then continue end
				if updates[ent] then
					nametag.Text = string.format(strings[ent], tostring(ent:GetAttribute('Level') or 0), (ent:GetAttribute('Level') or 0) >= 2 and 's' or '')
					local size = getfontsize(removeTags(nametag.Text), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
					nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
					updates[ent] = nil
				end
				nametag.Position = UDim2.fromOffset(headPos.X, headPos.Y)
			end
		end))
	end
	Callbacks.BeehiveColor = function()
		if Beehives.Enabled then
			for ent in Beehives.Reference do
				local nametag = Beehives.Reference[ent]
				nametag.TextSize = 14 * BeehiveScale.Value
				nametag.TextColor3 = Color3.fromHSV(BeehiveColor.Hue, BeehiveColor.Sat, BeehiveColor.Value)
				nametag.BackgroundTransparency = BeehiveTransparency.Value
			end
		end
	end
	Callbacks.BeehiveTransparency = Callbacks.BeehiveColor
	Callbacks.BeehiveScale = Callbacks.BeehiveColor
end)

-- ===== Render/ChatNameColor.lua =====
run(function()
    local ChatNameColor
    local Color
    local original
    local applying = false

    local function selectedColor()
        return Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
    end

    local function apply()
        if not ChatNameColor.Enabled then return end
        applying = true
        lplr:SetAttribute('ChatNameColor', selectedColor())
        applying = false
    end

    ChatNameColor = vape.Categories.Render:CreateModule({
        Name = 'ChatNameColour',
        Tooltip = 'Changes your chat name colour while enabled',
        Function = function(enabled)
            if enabled then
                original = lplr:GetAttribute('ChatNameColor')
                apply()
                ChatNameColor:Clean(lplr:GetAttributeChangedSignal('ChatNameColor'):Connect(function()
                    if not applying then apply() end
                end))
            else
                applying = true
                lplr:SetAttribute('ChatNameColor', original)
                applying = false
                original = nil
            end
        end
    })
    Color = ChatNameColor:CreateColorSlider({Name = 'Colour', Function = apply})
end)

-- ===== Render/ChatPosition.lua =====
run(function()
    local ChatPosition
    local Vertical
    local Horizontal
    local moved

    local function targetOffset()
        return Vector2.new(Horizontal and Horizontal.Value or 0, Vertical and Vertical.Value or 200)
    end

    local function applyLegacy()
        local off = targetOffset()
        pcall(function()
            starterGui:SetCore('ChatWindowPosition', UDim2.fromOffset(off.X, off.Y))
        end)
    end

    
    
    local function findChatFrame()
        local roots = {coreGui}
        local pg = lplr:FindFirstChild('PlayerGui')
        if pg then table.insert(roots, pg) end
        for _, root in roots do
            for _, gui in root:GetChildren() do
                if gui:IsA('ScreenGui') and gui.Name:lower():find('chat') then
                    for _, child in gui:GetChildren() do
                        if child:IsA('GuiObject') and child:FindFirstChildWhichIsA('ScrollingFrame', true) then
                            return child
                        end
                    end
                end
            end
        end
    end

    local function apply()
        applyLegacy()
        local frame = findChatFrame()
        if frame then
            moved = frame
            pcall(function()
                frame.Position = UDim2.fromOffset(targetOffset().X, targetOffset().Y)
            end)
        end
    end

    local function restore()
        pcall(function()
            starterGui:SetCore('ChatWindowPosition', UDim2.new())
        end)
        if moved and moved.Parent then
            pcall(function() moved.Position = UDim2.new() end)
        end
        moved = nil
    end

    ChatPosition = vape.Categories.Render:CreateModule({
        Name = 'ChatPosition',
        Function = function(callback)
            if callback then
                ChatPosition:Clean(task.spawn(function()
                    while ChatPosition.Enabled do
                        apply()
                        task.wait(1)
                    end
                end))
            else
                restore()
            end
        end,
        Tooltip = 'Moves the chat window'
    })
    Vertical = ChatPosition:CreateSlider({
        Name = 'Vertical',
        Min = 0,
        Max = 700,
        Default = 200,
        Suffix = ' px',
        Tooltip = 'How far from the top the chat window sits',
        Function = function()
            if ChatPosition.Enabled then apply() end
        end
    })
    Horizontal = ChatPosition:CreateSlider({
        Name = 'Horizontal',
        Min = 0,
        Max = 700,
        Default = 0,
        Suffix = ' px',
        Tooltip = 'How far from the left the chat window sits',
        Function = function()
            if ChatPosition.Enabled then apply() end
        end
    })
end)

-- ===== Render/Clouds.lua =====
run(function()
	local Clouds
	local Scale
	local CloudColor
	local Folder, FolderConnection
	local Reference = setmetatable({}, {__mode = "k"})

	local function ApplyAll()
		if not Clouds.Enabled or not Folder then return end
		for _, v: Instance in Folder:GetChildren() do
			if v:IsA("BasePart") then
				if not Reference[v] then
					Reference[v] = {v.Size, v.Color, v.Transparency}
				end
				v.Size = Reference[v][1] * (Scale.Value / 100)
				v.Color = Color3.fromHSV(CloudColor.Hue, CloudColor.Sat, CloudColor.Value)
				v.Transparency = 1 - CloudColor.Opacity
			end
		end
	end

	local function BindFolder(New: Instance?)
		if FolderConnection then
			FolderConnection:Disconnect()
			FolderConnection = nil
		end

		Folder = New
		if not Folder then return end

		FolderConnection = Folder.ChildAdded:Connect(function(Part: Instance)
			task.defer(function()
				if not Clouds.Enabled or not Part:IsA("BasePart") then return end
				if not Reference[Part] then
					Reference[Part] = {Part.Size, Part.Color, Part.Transparency}
				end
				Part.Size = Reference[Part][1] * (Scale.Value / 100)
				Part.Color = Color3.fromHSV(CloudColor.Hue, CloudColor.Sat, CloudColor.Value)
				Part.Transparency = 1 - CloudColor.Opacity
			end)
		end)
		ApplyAll()
	end

	Clouds = vape.Categories.Render:CreateModule({
		Name = "Clouds",
		Function = function(Callback: boolean)
			if Callback then
				Clouds:Clean(workspace.ChildAdded:Connect(function(Child: Instance)
					if Child.Name == "Clouds" then
						BindFolder(Child)
					end
				end))
				BindFolder(workspace:FindFirstChild("Clouds"))
			else
				BindFolder(nil)
				for Part: BasePart, v: {any} in Reference do
					if Part.Parent then
						Part.Size = v[1]
						Part.Color = v[2]
						Part.Transparency = v[3]
					end
				end
				table.clear(Reference)
			end
		end,
		Tooltip = "Restyles the clouds around the map"
	})

	Scale = Clouds:CreateSlider({
		Name = "Size",
		Min = 5,
		Max = 300,
		Function = ApplyAll,
		Default = 100,
		Suffix = function()
			return "%"
		end
	})
	CloudColor = Clouds:CreateColorSlider({
		Name = "Color",
		DefaultSat = 0,
		Darker = true,
		Function = ApplyAll
	})
end)

-- ===== Render/CollectableESP.lua =====
run(function()
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui

	local function createSection()
		local section = {
			Enabled = false,
			Connections = {},
			Reference = {},
			Folder = Instance.new('Folder')
		}
		section.Folder.Parent = Folder
		function section:Clean(item)
			if type(item) == 'function' then
				table.insert(self.Connections, {Disconnect = item})
			elseif item then
				table.insert(self.Connections, item)
			end
		end
		function section:Clear()
			for _, connection in self.Connections do
				pcall(function() connection:Disconnect() end)
			end
			table.clear(self.Connections)
			if self.Stop then self.Stop(self) end
			for _, instance in self.Reference do
				pcall(function() instance:Destroy() end)
			end
			table.clear(self.Reference)
			self.Folder:ClearAllChildren()
		end
		function section:Set(callback)
			if callback == self.Enabled then return end
			self.Enabled = callback
			self:Clear()
			if callback and self.Start then self.Start(self) end
		end
		function section:Restart()
			if self.Enabled then
				self:Set(false)
				self:Set(true)
			end
		end
		return section
	end
	local Collectables = createSection()
	local CollectableDistance, CollectableScale, CollectableTransparency, CollectableColor, CollectableList
	local Callbacks = {}
	local CollectableESP = vape.Categories.Render:CreateModule({
		Name = 'CollectableESP',
		Function = function(callback)
			Collectables:Set(callback)
			for _, setting in {CollectableDistance,
				CollectableScale,
				CollectableTransparency,
				CollectableColor,
				CollectableList} do
				if setting and setting.Object then
					setting.Object.Visible = callback
				end
			end
		end,
		Tooltip = 'Shows kit collectables through walls'
	})
	CollectableDistance = CollectableESP:CreateToggle({Visible = false, Name = 'Collectable distance', Default = true})
	CollectableScale = CollectableESP:CreateSlider({Visible = false, Function = function(...) if Callbacks.CollectableScale then return Callbacks.CollectableScale(...) end end, Name = 'Collectable scale', Min = 0.5, Max = 3, Default = 1, Decimal = 10})
	CollectableTransparency = CollectableESP:CreateSlider({Visible = false, Function = function(...) if Callbacks.CollectableTransparency then return Callbacks.CollectableTransparency(...) end end, Name = 'Collectable transparency', Min = 0, Max = 1, Default = 0.5, Decimal = 100, Darker = true})
	CollectableColor = CollectableESP:CreateColorSlider({Visible = false, Function = function(...) if Callbacks.CollectableColor then return Callbacks.CollectableColor(...) end end, Name = 'Collectable text colour', Darker = true})
	CollectableList = CollectableESP:CreateTextList({
		Visible = false,
		Name = 'Collectables list',
		Default = {'Coin', 'Crystal', 'Crystalheart', 'Energy', 'Ghost', 'Ingredient', 'Metal', 'Plant', 'Seed', 'Shadow Coin', 'Soul', 'Soulvine', 'Star', 'Tearbloom'},
		Darker = true,
		Function = function()
			Collectables:Restart()
		end
	})

	Collectables.Start = function(self)
		local tags = {
			['alchemist_ingedients'] = 'Ingredient',
			['alchemy_crystal'] = 'Crystal',
			['crystalheart_seed'] = 'Crystalheart',
			['forest_environment_plant'] = 'Plant',
			['ghost'] = 'Ghost',
			['hidden-metal'] = 'Metal',
			['jailor_soul'] = 'Soul',
			['murder_coin'] = 'Coin',
			['shadow_coin'] = 'Shadow Coin',
			['soulvine_seed'] = 'Soulvine',
			['spirit_gardener_energy'] = 'Energy',
			['spirit_gardener_seeds'] = 'Seed',
			['stars'] = 'Star',
			['tearbloom_seed'] = 'Tearbloom'
		}
		local function added(obj, tag)
			if self.Reference[obj] or not table.find(CollectableList.ListEnabled, tags[tag]) then return end
			local nametag = Instance.new('TextLabel')
			nametag.Name = tags[tag]
			nametag.Text = tags[tag]
			nametag.TextSize = 14 * CollectableScale.Value
			nametag.FontFace = uipallet.Font
			local size = getfontsize(nametag.Text, nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
			nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
			nametag.AnchorPoint = Vector2.new(0.5, 1)
			nametag.BackgroundColor3 = Color3.new()
			nametag.BackgroundTransparency = CollectableTransparency.Value
			nametag.BorderSizePixel = 0
			nametag.Visible = false
			nametag.TextColor3 = Color3.fromHSV(CollectableColor.Hue, CollectableColor.Sat, CollectableColor.Value)
			nametag.Parent = self.Folder
			self.Reference[obj] = nametag
		end
		for tag in tags do
			for _, obj in collectionService:GetTagged(tag) do
				added(obj, tag)
			end
			self:Clean(collectionService:GetInstanceAddedSignal(tag):Connect(function(obj)
				added(obj, tag)
			end))
			self:Clean(collectionService:GetInstanceRemovedSignal(tag):Connect(function(obj)
				if self.Reference[obj] then
					self.Reference[obj]:Destroy()
					self.Reference[obj] = nil
				end
			end))
		end
		self:Clean(runService.PreRender:Connect(function()
			local localPosition = entitylib.isAlive and entitylib.character.RootPart.Position
			for i, v in self.Reference do
				local part = i:IsA('Model') and i.PrimaryPart or i
				if not i.Parent or not part then
					v:Destroy()
					self.Reference[i] = nil
					continue
				end
				local screenPos, visible = gameCamera:WorldToViewportPoint(part.Position + Vector3.new(0, 2, 0))
				v.Visible = visible
				if not visible then continue end
				local text = CollectableDistance.Enabled and localPosition and `{v.Name} | {((localPosition - part.Position).Magnitude) // 1}m` or v.Name
				if v.Text ~= text then
					v.Text = text
					local size = getfontsize(text, v.TextSize, v.FontFace, Vector2.new(100000, 100000))
					v.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
				end
				v.Position = UDim2.fromOffset(screenPos.X, screenPos.Y)
			end
		end))
	end
	Callbacks.CollectableScale = function(value)
		for _, v in Collectables.Reference do
			v.TextSize = 14 * value
			local size = getfontsize(v.Text, v.TextSize, v.FontFace, Vector2.new(100000, 100000))
			v.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
		end
	end
	Callbacks.CollectableTransparency = function(value)
		for _, v in Collectables.Reference do
			v.BackgroundTransparency = value
		end
	end
	Callbacks.CollectableColor = function(hue, sat, val)
		for _, v in Collectables.Reference do
			v.TextColor3 = Color3.fromHSV(hue, sat, val)
		end
	end
end)

