-- ===== Render/CustomTags.lua =====
run(function()
    local CustomTags
    local Color
    local TAG
    local old, old2
    local tagGuiConn
    local tagConnections = {}

    local function Color3ToHex(r, g, b)
	return string.lower(string.format('#%02X%02X%02X', r, g, b))
    end

    local function CompleteTagEffect()
	if not lplr:FindFirstChild('Tags') then
		return
	end
	local tagObj = lplr.Tags:FindFirstChild('0')
	if not tagObj then
		return
	end

	if not old then
		old = tagObj.Value
		old2 = tagObj:GetAttribute('Text')
	end

	local color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	local R = math.floor(color.R * 255)
	local G = math.floor(color.G * 255)
	local B = math.floor(color.B * 255)

	tagObj.Value = string.format("<font color='rgb(%d,%d,%d)'>[%s]</font>", R, G, B, TAG.Value)
	tagObj:SetAttribute('Text', TAG.Value)
	lplr:SetAttribute('ClanTag', TAG.Value)

	for _, connection in tagConnections do connection:Disconnect() end
	table.clear(tagConnections)
	if tagGuiConn then
		tagGuiConn:Disconnect()
		tagGuiConn = nil
	end

	local nameToFind = (lplr.DisplayName == '' or lplr.DisplayName == lplr.Name) and lplr.Name or lplr.DisplayName
	local replacement = string.format('<font transparency="0.3" color="%s">[%s]</font> %s', Color3ToHex(R, G, B), TAG.Value, nameToFind)
	local watched = setmetatable({}, {__mode = 'k'})
	local function watchLabel(label)
		if watched[label] or not label:IsA('TextLabel') then return end
		watched[label] = true
		local applying = false
		local function apply()
			if applying or not label.Parent then return end
			if label.Text:lower():find(nameToFind:lower(), 1, true) and label.Text ~= replacement then
				applying = true
				label.Text = replacement
				applying = false
			end
		end
		apply()
		table.insert(tagConnections, label:GetPropertyChangedSignal('Text'):Connect(apply))
	end
	local function watchGui(child)
		if child.Name ~= 'TabListScreenGui' or not child:IsA('ScreenGui') then
			return
		end
		for _, label in child:GetDescendants() do watchLabel(label) end
		table.insert(tagConnections, child.DescendantAdded:Connect(watchLabel))
	end
	tagGuiConn = lplr.PlayerGui.ChildAdded:Connect(watchGui)
	local existing = lplr.PlayerGui:FindFirstChild('TabListScreenGui')
	if existing then watchGui(existing) end
    end

    local function RemoveTagEffect()
	for _, connection in tagConnections do connection:Disconnect() end
	table.clear(tagConnections)

	if tagGuiConn then
		tagGuiConn:Disconnect()
		tagGuiConn = nil
	end

	if lplr:FindFirstChild('Tags') then
		local tagObj = lplr.Tags:FindFirstChild('0')
		if tagObj then
			if old then
				tagObj.Value = old
			end
			if old2 then
				tagObj:SetAttribute('Text', old2)
			end
		end
	end

	if lplr:GetAttribute('ClanTag') then
		lplr:SetAttribute('ClanTag', old)
	end

	old = nil
	old2 = nil
    end

    CustomTags = vape.Categories.Render:CreateModule({
	Name = 'CustomTags',
	Function = function(callback)
		if callback then
			CompleteTagEffect()
		else
			RemoveTagEffect()
		end
	end,
	Tooltip = 'Shows a custom clan tag in chat on your screen'
    })

    Color = CustomTags:CreateColorSlider({
	Name = 'Colour',
	Function = function()
		if CustomTags.Enabled then
			CompleteTagEffect()
		end
	end,
    })
    TAG = CustomTags:CreateTextBox({
	Name = 'Tag',
	Default = 'gg',
	Function = function()
		if CustomTags.Enabled then
			CompleteTagEffect()
		end
	end,
    })
end)

-- ===== Render/GeneratorESP.lua =====
run(function()
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui

	local function createSection()
		local section = {
			Enabled = false,
			Connections = {},
			Reference = {},
			Folder = Instance.new('Folder')
		}
		section.Folder.Parent = Folder
		function section:Clean(item)
			if type(item) == 'function' then
				table.insert(self.Connections, {Disconnect = item})
			elseif item then
				table.insert(self.Connections, item)
			end
		end
		function section:Clear()
			for _, connection in self.Connections do
				pcall(function() connection:Disconnect() end)
			end
			table.clear(self.Connections)
			if self.Stop then self.Stop(self) end
			for _, instance in self.Reference do
				pcall(function() instance:Destroy() end)
			end
			table.clear(self.Reference)
			self.Folder:ClearAllChildren()
		end
		function section:Set(callback)
			if callback == self.Enabled then return end
			self.Enabled = callback
			self:Clear()
			if callback and self.Start then self.Start(self) end
		end
		function section:Restart()
			if self.Enabled then
				self:Set(false)
				self:Set(true)
			end
		end
		return section
	end
	local Generators = createSection()
	local GeneratorTransparency, GeneratorScale, GeneratorList
	local Callbacks = {}
	local GeneratorESP = vape.Categories.Render:CreateModule({
		Name = 'GeneratorESP',
		Function = function(callback)
			for _, setting in {GeneratorTransparency, GeneratorScale, GeneratorList} do
				if setting and setting.Object then
					setting.Object.Visible = callback
				end
			end
			Generators:Set(callback)
		end,
		Tooltip = 'Shows generators and their info'
	})
	GeneratorTransparency = GeneratorESP:CreateSlider({Visible = false, Function = function(...) if Callbacks.GeneratorTransparency then return Callbacks.GeneratorTransparency(...) end end, Name = 'Generator transparency', Default = 0.5, Min = 0, Max = 1, Decimal = 100})
	GeneratorScale = GeneratorESP:CreateSlider({Visible = false, Function = function(...) if Callbacks.GeneratorScale then return Callbacks.GeneratorScale(...) end end, Name = 'Generator scale', Default = 1, Min = 0.1, Max = 1.5, Decimal = 10})
	GeneratorList = GeneratorESP:CreateMultiDropdown({List = {'iron', 'diamond', 'emerald'}, Visible = false, Function = function(...) if Callbacks.GeneratorList then return Callbacks.GeneratorList(...) end end, Name = 'Generators', Default = {'iron', 'diamond', 'emerald'}, Tooltip = 'Which generators get a label'})

	Generators.Start = function(self)
		local strings, cooldown, updates = {}, {}, {}
		local function getNumber(text)
			if not text or text == '' then return 0 end
			local seconds = text:match('%[(%d+)%]')
			if seconds then return tonumber(seconds) or 0 end
			local justNumber = text:match('(%d+)')
			if justNumber then return tonumber(justNumber) or 0 end
			return 0
		end
		local function updated(ent)
			local nametag = self.Reference[ent]
			if nametag then
				nametag.TextSize = 14 * GeneratorScale.Value
				nametag.BackgroundTransparency = GeneratorTransparency.Value
			end
		end
		local function removing(ent)
			if self.Reference[ent] then
				self.Reference[ent]:Destroy()
				self.Reference[ent] = nil
			end
		end
		local function added(ent)
			local tree = ent:FindFirstChild('RoactTree')
			local app = tree and tree:FindFirstChild('TeamOreGeneratorApp')
			if not app then return end
			local name = (app:FindFirstChild('GlobalOreGenerator') or app:FindFirstChild('TeamGenMain'))
			local countdown = (name or app):FindFirstChild('Countdown', true)
			if name then
				name = name:FindFirstChild('Title')
			end
			local tierType = ''
			if name then
				name = name.Text
				tierType = 'iron'
			else
				local ore = tostring(ent:GetAttribute('Id') or '')
				ore = ore:sub(0, #ore - 2)
				tierType = (ore:sub(0, 1):upper() .. ore:sub(2, #ore)):lower()
				name = ore:sub(0, 1):upper() .. ore:sub(2, #ore) .. ' Generator'
			end
			if not GeneratorList:Has(tierType) then return end
			strings[ent] = `{name} %s%s`
			local nametag = Instance.new('TextLabel')
			nametag.TextSize = 14 * GeneratorScale.Value
			nametag.Font = Enum.Font.Arial
			local format = string.format(strings[ent], `| T{ent:GetAttribute('GeneratorLevel')}`, '')
			local size = getfontsize(format, nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
			nametag.Name = name
			nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
			nametag.AnchorPoint = Vector2.new(0.5, 1)
			nametag.BackgroundColor3 = Color3.new()
			nametag.BackgroundTransparency = 0.5
			nametag.BorderSizePixel = 0
			nametag.Visible = false
			nametag.Text = format
			nametag.TextColor3 = Color3.new(1, 1, 1)
			nametag.RichText = true
			nametag.Parent = self.Folder
			self.Reference[ent] = nametag
			local update = function()
				updates[ent] = true
			end
			self:Clean(ent:GetAttributeChangedSignal('GeneratorLevel'):Connect(update))
			self:Clean(ent:GetAttributeChangedSignal('Cooldown'):Connect(update))
			if countdown then
				cooldown[ent] = countdown
				self:Clean(countdown:GetPropertyChangedSignal('Text'):Connect(update))
			end
			update()
		end
		self.Stop = function()
			table.clear(strings)
			table.clear(cooldown)
			table.clear(updates)
		end
		for _, v in collectionService:GetTagged('Generator') do
			added(v)
		end
		self:Clean(collectionService:GetInstanceAddedSignal('Generator'):Connect(added))
		self:Clean(collectionService:GetInstanceRemovedSignal('Generator'):Connect(removing))
		self:Clean(runService.PreRender:Connect(function()
			for ent, nametag in self.Reference do
				local headPos, headVis = gameCamera:WorldToViewportPoint(ent.Position + Vector3.new(0, 1, 0))
				nametag.Visible = headVis
				if not headVis then continue end
				if updates[ent] then
					nametag.Text = string.format(strings[ent], `| T{ent:GetAttribute('GeneratorLevel')}`, cooldown[ent] and ` | {getNumber(cooldown[ent].Text)}s` or '')
					local size = getfontsize(removeTags(nametag.Text), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
					nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
					updates[ent] = nil
				end
				nametag.Position = UDim2.fromOffset(headPos.X, headPos.Y)
			end
		end))
	end
	Callbacks.GeneratorTransparency = function()
		if Generators.Enabled then
			for ent in Generators.Reference do
				local nametag = Generators.Reference[ent]
				nametag.TextSize = 14 * GeneratorScale.Value
				nametag.BackgroundTransparency = GeneratorTransparency.Value
			end
		end
	end
	Callbacks.GeneratorScale = Callbacks.GeneratorTransparency
	Callbacks.GeneratorList = function()
		Generators:Restart()
	end
end)

-- ===== Render/Health.lua =====
run(function()
    local Health

    local function read()
	local character = entitylib.isAlive and lplr.Character
	local health = character and tonumber(character:GetAttribute('Health'))
	if not health then
		return '', Color3.new()
	end
	local maxHealth = math.max(tonumber(character:GetAttribute('MaxHealth')) or health, 1)
	return math.round(health) .. ' ❤️', Color3.fromHSV(math.clamp(health / maxHealth, 0, 1) / 2.8, 0.86, 1)
    end

    Health = vape.Categories.Render:CreateModule({
	Name = 'Health',
	Function = function(callback)
		if callback then
			local label = Instance.new('TextLabel')
			label.Size = UDim2.fromOffset(100, 20)
			label.Position = UDim2.new(0.5, 6, 0.5, 30)
			label.BackgroundTransparency = 1
			label.AnchorPoint = Vector2.new(0.5, 0)
			label.Text, label.TextColor3 = read()
			label.TextSize = 18
			label.Font = Enum.Font.Arial
			label.Parent = vape.gui
			Health:Clean(label)
			Health:Clean(vapeEvents.AttributeChanged.Event:Connect(function()
				label.Text, label.TextColor3 = read()
			end))
		end
	end,
	Tooltip = 'Shows your health in the centre of your screen'
    })
end)

-- ===== Render/InventoryESP.lua =====
run(function()
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui

	local function createSection()
		local section = {
			Enabled = false,
			Connections = {},
			Reference = {},
			Folder = Instance.new('Folder')
		}
		section.Folder.Parent = Folder
		function section:Clean(item)
			if type(item) == 'function' then
				table.insert(self.Connections, {Disconnect = item})
			elseif item then
				table.insert(self.Connections, item)
			end
		end
		function section:Clear()
			for _, connection in self.Connections do
				pcall(function() connection:Disconnect() end)
			end
			table.clear(self.Connections)
			if self.Stop then self.Stop(self) end
			for _, instance in self.Reference do
				pcall(function() instance:Destroy() end)
			end
			table.clear(self.Reference)
			self.Folder:ClearAllChildren()
		end
		function section:Set(callback)
			if callback == self.Enabled then return end
			self.Enabled = callback
			self:Clear()
			if callback and self.Start then self.Start(self) end
		end
		function section:Restart()
			if self.Enabled then
				self:Set(false)
				self:Set(true)
			end
		end
		return section
	end
	local Inventory = createSection()
	local InventoryArmor, InventoryEmpty, InventoryColor
	local Callbacks = {}
	local InventoryESP = vape.Categories.Render:CreateModule({
		Name = 'Target Inventory Panel',
		Function = function(callback)
			Inventory:Set(callback)
			for _, setting in {InventoryArmor,
				InventoryEmpty,
				InventoryColor} do
				if setting and setting.Object then
					setting.Object.Visible = callback
				end
			end
		end,
		Tooltip = 'Shows the inventory of whoever you are currently targeting'
	})
	InventoryArmor = InventoryESP:CreateToggle({Visible = false, Function = function(...) if Callbacks.InventoryArmor then return Callbacks.InventoryArmor(...) end end, Name = 'Inventory armour', Default = true})
	InventoryEmpty = InventoryESP:CreateToggle({Visible = false, Function = function(...) if Callbacks.InventoryEmpty then return Callbacks.InventoryEmpty(...) end end, Name = 'Inventory empty', Tooltip = 'Keeps the panel up when their inventory is unknown'})
	local InventoryPanel
	InventoryColor = InventoryESP:CreateColorSlider({
		Visible = false,
		Name = 'Inventory background colour',
		DefaultValue = 0,
		DefaultOpacity = 0.5,
		Function = function(hue, sat, val, opacity)
			if InventoryPanel then
				InventoryPanel.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
				InventoryPanel.BackgroundTransparency = 1 - opacity
			end
		end
	})

	Inventory.Start = function(self)
		local slotCount, slotSize, slotPadding, columns, headerHeight = 24, 32, 4, 6, 46
		local window, headshot, nametag, grid, armorholder, armordivider
		local slots, armorslots = {}, {}
		local function createSlot(parent)
			local slot = Instance.new('Frame')
			slot.Size = UDim2.fromOffset(slotSize, slotSize)
			slot.BackgroundColor3 = color.Dark(uipallet.Main, 0.02)
			slot.BorderSizePixel = 0
			slot.Visible = false
			slot.Parent = parent
			local corner = Instance.new('UICorner')
			corner.CornerRadius = UDim.new(0, 4)
			corner.Parent = slot
			local stroke = Instance.new('UIStroke')
			stroke.Color = color.Light(uipallet.Main, 0.034)
			stroke.Parent = slot
			local icon = Instance.new('ImageLabel')
			icon.Name = 'Icon'
			icon.Size = UDim2.fromOffset(slotSize - 8, slotSize - 8)
			icon.Position = UDim2.fromScale(0.5, 0.5)
			icon.AnchorPoint = Vector2.new(0.5, 0.5)
			icon.BackgroundTransparency = 1
			icon.Parent = slot
			local amount = Instance.new('TextLabel')
			amount.Name = 'Amount'
			amount.Size = UDim2.fromOffset(slotSize - 4, 11)
			amount.Position = UDim2.fromOffset(0, slotSize - 13)
			amount.BackgroundTransparency = 1
			amount.Text = ''
			amount.TextXAlignment = Enum.TextXAlignment.Right
			amount.TextSize = 11
			amount.TextColor3 = uipallet.Text
			amount.TextStrokeColor3 = Color3.new()
			amount.TextStrokeTransparency = 0.4
			amount.FontFace = uipallet.Font
			amount.Parent = slot
			return slot
		end
		local function setSlot(slot, item, highlight)
			if not item or not item.itemType then
				slot.Visible = false
				return
			end
			slot.Visible = true
			slot.Icon.Image = bedwars.getIcon(item, true)
			slot.Amount.Text = (item.amount or 1) > 1 and tostring(item.amount) or ''
			slot.UIStroke.Color = highlight and Color3.fromHSV(InventoryColor.Hue, InventoryColor.Sat, InventoryColor.Value) or color.Light(uipallet.Main, 0.034)
		end
		local function refresh()
			if not window or not window.Parent then return end
			local ent, highest = nil, tick()
			for i, v in targetinfo.Targets do
				if v < tick() then
					targetinfo.Targets[i] = nil
					continue
				end
				if v > highest then
					ent, highest = i, v
				end
			end
			local player = ent and ent.Player or nil
			local inventory = player and store.inventories[player] or nil
			if not ent or (not inventory and not InventoryEmpty.Enabled) then
				window.Visible = false
				return
			end
			window.Visible = true
			nametag.Text = player and player.DisplayName or (ent.Character and ent.Character.Name) or ''
			headshot.Image = 'rbxthumb://type=AvatarHeadShot&id='..(player and player.UserId or 1)..'&w=420&h=420'
			inventory = inventory or {items = {}, armor = {}}
			local hand = inventory.hand
			local shown = 0
			for i, v in slots do
				local item = inventory.items[i]
				setSlot(v, item, item and hand and item.tool == hand.tool)
				if v.Visible then
					shown = i
				end
			end
			local rows = math.max(math.ceil(shown / columns), 1)
			local gridheight = (rows * slotSize) + ((rows - 1) * slotPadding)
			grid.Size = UDim2.new(1, -28, 0, gridheight)
			local height = headerHeight + 10 + gridheight + 10
			if InventoryArmor.Enabled then
				armordivider.Visible = true
				armorholder.Visible = true
				armordivider.Position = UDim2.fromOffset(0, height - 1)
				for i = 1, 3 do
					setSlot(armorslots[i], inventory.armor[i + 3])
				end
				setSlot(armorslots[4], hand, true)
				armorholder.Position = UDim2.fromOffset(14, height + 9)
				height += slotSize + 19
			else
				armordivider.Visible = false
				armorholder.Visible = false
			end
			window.Size = UDim2.fromOffset(240, height)
		end
		window = Instance.new('Frame')
		window.Name = 'ESPInventory'
		window.Size = UDim2.fromOffset(240, headerHeight)
		window.Position = UDim2.fromOffset(12, 260)
		window.BackgroundColor3 = Color3.fromHSV(InventoryColor.Hue, InventoryColor.Sat, InventoryColor.Value)
		window.BackgroundTransparency = 1 - InventoryColor.Opacity
		window.Visible = false
		window.Parent = vape.gui.ScaledGui or vape.gui
		addBlur(window)
		local corner = Instance.new('UICorner')
		corner.CornerRadius = UDim.new(0, 5)
		corner.Parent = window
		headshot = Instance.new('ImageLabel')
		headshot.Name = 'Headshot'
		headshot.Size = UDim2.fromOffset(26, 26)
		headshot.Position = UDim2.fromOffset(14, 11)
		headshot.BackgroundColor3 = color.Dark(uipallet.Main, 0.02)
		headshot.Image = ''
		headshot.Parent = window
		local headcorner = Instance.new('UICorner')
		headcorner.CornerRadius = UDim.new(0, 4)
		headcorner.Parent = headshot
		nametag = Instance.new('TextLabel')
		nametag.Name = 'Name'
		nametag.Size = UDim2.new(1, -60, 0, 26)
		nametag.Position = UDim2.fromOffset(48, 11)
		nametag.BackgroundTransparency = 1
		nametag.Text = ''
		nametag.TextXAlignment = Enum.TextXAlignment.Left
		nametag.TextSize = 13
		nametag.TextColor3 = uipallet.Text
		nametag.TextTruncate = Enum.TextTruncate.AtEnd
		nametag.FontFace = uipallet.Font
		nametag.Parent = window
		local divider = Instance.new('Frame')
		divider.Name = 'Divider'
		divider.Size = UDim2.new(1, 0, 0, 1)
		divider.Position = UDim2.fromOffset(0, headerHeight - 1)
		divider.BackgroundColor3 = color.Light(uipallet.Main, 0.04)
		divider.BorderSizePixel = 0
		divider.Parent = window
		grid = Instance.new('Frame')
		grid.Name = 'Items'
		grid.Size = UDim2.new(1, -28, 0, 0)
		grid.Position = UDim2.fromOffset(14, headerHeight + 10)
		grid.BackgroundTransparency = 1
		grid.Parent = window
		local layout = Instance.new('UIGridLayout')
		layout.CellSize = UDim2.fromOffset(slotSize, slotSize)
		layout.CellPadding = UDim2.fromOffset(slotPadding, slotPadding)
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		layout.Parent = grid
		for i = 1, slotCount do
			local slot = createSlot(grid)
			slot.LayoutOrder = i
			slots[i] = slot
		end
		armordivider = Instance.new('Frame')
		armordivider.Name = 'ArmorDivider'
		armordivider.Size = UDim2.new(1, 0, 0, 1)
		armordivider.BackgroundColor3 = color.Light(uipallet.Main, 0.04)
		armordivider.BorderSizePixel = 0
		armordivider.Parent = window
		armorholder = Instance.new('Frame')
		armorholder.Name = 'Armour'
		armorholder.Size = UDim2.fromOffset(240, slotSize)
		armorholder.BackgroundTransparency = 1
		armorholder.Parent = window
		local armorlayout = Instance.new('UIListLayout')
		armorlayout.FillDirection = Enum.FillDirection.Horizontal
		armorlayout.Padding = UDim.new(0, slotPadding)
		armorlayout.Parent = armorholder
		for i = 1, 4 do
			local slot = createSlot(armorholder)
			slot.LayoutOrder = i
			armorslots[i] = slot
		end
		InventoryPanel = window
		task.spawn(function()
			repeat
				if not self.Enabled then break end
				refresh()
				task.wait(0.1)
			until false
			window.Visible = false
		end)
		self.Stop = function()
			window:Destroy()
			InventoryPanel = nil
		end
	end
	Callbacks.InventoryArmor = function()
		Inventory:Restart()
	end
	Callbacks.InventoryEmpty = function()
		Inventory:Restart()
	end
end)

