		return Color3.fromHSV(option.Hue, option.Sat, option.Value)
	end

	local function recolor()
		if not Items.Enabled then return end
		for ent, box in boxes do
			box.Color3 = itemColor(ent.Name)
			box.Transparency = 1 - ItemColor.Opacity
		end
		for ent, nametag in Items.Reference do
			nametag.TextColor3 = itemColor(ent.Name)
		end
	end

	local function restart()
		Items:Restart()
	end

	local ItemESP = Main:Part({
		Label = 'Item boxes',
		Name = 'ItemESP',
		Function = function(callback)
			Items:Set(callback)
		end,
		Tooltip = 'Shows dropped items and their count through walls'
	})
	ItemBox = ItemESP:CreateToggle({
		Name = 'Box',
		Default = true,
		Function = restart,
		Tooltip = 'Draws a see-through box around each item drop'
	})
	ItemColor = ItemESP:CreateColorSlider({
		Name = 'Colour',
		DefaultOpacity = 0.35,
		Function = recolor,
		Tooltip = 'Colour of the box and text'
	})
	ItemResources = ItemESP:CreateToggle({
		Name = 'Resource colours',
		Default = true,
		Function = function(callback)
			for _, option in resources do
				if option.Object then
					option.Object.Visible = callback
				end
			end
			recolor()
		end,
		Tooltip = 'Gives each resource its own colour'
	})
	for _, resource in {
		{'iron', 'Iron colour', 0, 0, 0.85},
		{'gold', 'Gold colour', 0.13, 0.85, 1},
		{'diamond', 'Diamond colour', 0.53, 0.7, 1},
		{'emerald', 'Emerald colour', 0.38, 0.8, 0.9}
	} do
		resources[resource[1]] = ItemESP:CreateColorSlider({
			Name = resource[2],
			DefaultHue = resource[3],
			DefaultSat = resource[4],
			DefaultValue = resource[5],
			Darker = true,
			Function = recolor
		})
	end
	ItemName = ItemESP:CreateToggle({
		Name = 'Show name',
		Default = true,
		Function = restart,
		Tooltip = 'Shows the item name next to its count'
	})
	ItemDistance = ItemESP:CreateToggle({
		Name = 'Item distance',
		Function = restart,
		Tooltip = 'Shows the distance of the item'
	})
	ItemScale = ItemESP:CreateSlider({
		Name = 'Item scale',
		Default = 1,
		Min = 0.1,
		Max = 1.5,
		Decimal = 10,
		Function = restart
	})
	ItemWhitelistOnly = ItemESP:CreateGroup({
		Name = 'Item whitelist only',
		Function = function(callback)
			restart()
		end,
		Tooltip = 'Only renders whitelisted items'
	})
	ItemAllowed = ItemWhitelistOnly:CreateTextList({
		Name = 'Item allowed items',
		Darker = true,
		Function = restart
	})

	Items.Start = function(self)
		local names, sizes = {}, {}
		local function added(ent)
			if self.Reference[ent] or not ent:IsA('BasePart') then return end
			local name = bedwars.ItemMeta[ent.Name] and bedwars.ItemMeta[ent.Name].displayName or ent.Name
			if ItemWhitelistOnly.Enabled and not table.find(ItemAllowed.ListEnabled, name:lower()) then return end
			names[ent] = name
			local nametag = Instance.new('TextLabel')
			nametag.TextSize = 14 * ItemScale.Value
			nametag.Font = Enum.Font.Arial
			nametag.Name = ent.Name
			nametag.AnchorPoint = Vector2.new(0.5, 1)
			nametag.BackgroundColor3 = Color3.new()
			nametag.BackgroundTransparency = 0.5
			nametag.BorderSizePixel = 0
			nametag.Visible = false
			nametag.Text = ''
			nametag.TextColor3 = itemColor(ent.Name)
			nametag.RichText = true
			nametag.Parent = self.Folder
			self.Reference[ent] = nametag
			if ItemBox.Enabled then
				local box = Instance.new('BoxHandleAdornment')
				box.Adornee = ent
				box.Size = ent.Size + Vector3.new(0.3, 0.3, 0.3)
				box.AlwaysOnTop = true
				box.ZIndex = 1
				box.Color3 = itemColor(ent.Name)
				box.Transparency = 1 - ItemColor.Opacity
				box.Parent = self.Folder
				boxes[ent] = box
			end
		end
		local function removing(ent)
			if self.Reference[ent] then
				self.Reference[ent]:Destroy()
				self.Reference[ent] = nil
			end
			if boxes[ent] then
				boxes[ent]:Destroy()
				boxes[ent] = nil
			end
			names[ent], sizes[ent] = nil, nil
		end
		self:Clean(collectionService:GetInstanceAddedSignal('ItemDrop'):Connect(added))
		self:Clean(collectionService:GetInstanceRemovedSignal('ItemDrop'):Connect(removing))
		self:Clean(runService.PreRender:Connect(function()
			for ent, nametag in self.Reference do
				local headPos, headVis = gameCamera:WorldToViewportPoint(ent.Position + Vector3.new(0, 1, 0))
				nametag.Visible = headVis
				if not headVis then continue end
				local amount = ent:GetAttribute('Amount') or 1
				local mag = ItemDistance.Enabled and entitylib.isAlive
					and math.floor((entitylib.character.RootPart.Position - ent.Position).Magnitude) or nil
				local cache = tostring(mag or '') .. ':' .. tostring(amount)
				if sizes[ent] ~= cache then
					local text = ItemName.Enabled and names[ent] or ''
					if amount >= 2 or text == '' then
						text = text .. (text ~= '' and ' ' or '') .. 'x' .. tostring(amount)
					end
					if ItemDistance.Enabled then
						text = '<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">' .. tostring(mag or 0) .. '</font><font color="rgb(85, 255, 85)">]</font> ' .. text
					end
					nametag.Text = text
					local size = getfontsize(removeTags(text), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
					nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
					sizes[ent] = cache
				end
				nametag.Position = UDim2.fromOffset(headPos.X, headPos.Y)
			end
		end))
		for _, v in collectionService:GetTagged('ItemDrop') do
			added(v)
		end
		self.Stop = function()
			table.clear(names)
			table.clear(sizes)
			table.clear(boxes)
		end
	end
end)

run(function()
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui

	local function createSection()
		local section = {
			Enabled = false,
			Connections = {},
			Reference = {},
			Folder = Instance.new('Folder')
		}
		section.Folder.Parent = Folder
		function section:Clean(item)
			if type(item) == 'function' then
				table.insert(self.Connections, {Disconnect = item})
			elseif item then
				table.insert(self.Connections, item)
			end
		end
		function section:Clear()
			for _, connection in self.Connections do
				pcall(function() connection:Disconnect() end)
			end
			table.clear(self.Connections)
			if self.Stop then self.Stop(self) end
			for _, instance in self.Reference do
				pcall(function() instance:Destroy() end)
			end
			table.clear(self.Reference)
			self.Folder:ClearAllChildren()
		end
		function section:Set(callback)
			if callback == self.Enabled then return end
			self.Enabled = callback
			self:Clear()
			if callback and self.Start then self.Start(self) end
		end
		return section
	end
	local Loot = createSection()
	local LootIron, LootDiamond, LootEmerald
	local Callbacks = {}
	local LootESP = Main:Part({
		Label = 'Loot icons',
		Default = false,
		Name = 'LootESP',
		Function = function(callback)
			Loot:Set(callback)
			for _, setting in {LootIron,
				LootDiamond,
				LootEmerald} do
				if setting and setting.Object then
					setting.Object.Visible = callback
				end
			end
		end,
		Tooltip = 'Shows iron, diamond and emerald drops'
	})
	LootIron = LootESP:CreateToggle({Visible = false, Function = function(...) if Callbacks.LootIron then return Callbacks.LootIron(...) end end, Name = 'Loot iron', Default = true})
	LootDiamond = LootESP:CreateToggle({Visible = false, Function = function(...) if Callbacks.LootDiamond then return Callbacks.LootDiamond(...) end end, Name = 'Loot diamond', Default = true})
	LootEmerald = LootESP:CreateToggle({Visible = false, Function = function(...) if Callbacks.LootEmerald then return Callbacks.LootEmerald(...) end end, Name = 'Loot emerald', Default = true})

	Loot.Start = function(self)
		local lootTypes = {
			iron = {keywords = {'iron'}, color = Color3.fromRGB(200, 200, 200), icon = 'iron', displayName = 'IRON'},
			diamond = {keywords = {'diamond'}, color = Color3.fromRGB(85, 200, 255), icon = 'diamond', displayName = 'DIAMOND'},
			emerald = {keywords = {'emerald'}, color = Color3.fromRGB(0, 255, 100), icon = 'emerald', displayName = 'EMERALD'}
		}
		local function getLootType(itemName)
			local nameLower = itemName:lower()
			for lootType, config in pairs(lootTypes) do
				for _, keyword in ipairs(config.keywords) do
					if nameLower:find(keyword, 1, true) then
						return lootType, config
					end
				end
			end
		end
		local function isLootEnabled(lootType)
			if lootType == 'iron' then return LootIron.Enabled end
			if lootType == 'diamond' then return LootDiamond.Enabled end
			if lootType == 'emerald' then return LootEmerald.Enabled end
			return false
		end
		local function added(lootHandle, lootType, config)
			if not isLootEnabled(lootType) then return end
			if self.Reference[lootHandle] then return end
			local billboard = Instance.new('BillboardGui')
			billboard.Parent = self.Folder
			billboard.Name = lootType
			billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
			billboard.Size = UDim2.fromOffset(40, 40)
			billboard.AlwaysOnTop = true
			billboard.ClipsDescendants = false
			billboard.Adornee = lootHandle
			local blur = addBlur(billboard)
			if blur then blur.Visible = true end
			local iconImage = bedwars.getIcon({itemType = config.icon}, true)
			if iconImage and iconImage ~= '' then
				local image = Instance.new('ImageLabel')
				image.Size = UDim2.fromOffset(40, 40)
				image.Position = UDim2.fromScale(0.5, 0.5)
				image.AnchorPoint = Vector2.new(0.5, 0.5)
				image.BackgroundColor3 = Color3.new(0, 0, 0)
				image.BackgroundTransparency = 0.3
				image.BorderSizePixel = 0
				image.Image = iconImage
				image.Parent = billboard
				local uicorner = Instance.new('UICorner')
				uicorner.CornerRadius = UDim.new(0, 4)
				uicorner.Parent = image
			else
				local frame = Instance.new('Frame')
				frame.Size = UDim2.fromScale(1, 1)
				frame.BackgroundColor3 = Color3.new(0, 0, 0)
				frame.BackgroundTransparency = 0.3
				frame.BorderSizePixel = 0
				frame.Parent = billboard
				local uicorner = Instance.new('UICorner')
				uicorner.CornerRadius = UDim.new(0, 4)
				uicorner.Parent = frame
				local textLabel = Instance.new('TextLabel')
				textLabel.Size = UDim2.fromScale(1, 1)
				textLabel.Position = UDim2.fromScale(0.5, 0.5)
				textLabel.AnchorPoint = Vector2.new(0.5, 0.5)
				textLabel.BackgroundTransparency = 1
				textLabel.Text = config.displayName
				textLabel.TextColor3 = config.color
				textLabel.TextScaled = true
				textLabel.Font = Enum.Font.GothamBold
				textLabel.TextStrokeTransparency = 0.5
				textLabel.TextStrokeColor3 = Color3.new(0, 0, 0)
				textLabel.Parent = frame
			end
			self.Reference[lootHandle] = billboard
		end
		local function removed(lootHandle)
			if self.Reference[lootHandle] then
				self.Reference[lootHandle]:Destroy()
				self.Reference[lootHandle] = nil
			end
		end
		self.FindLoot = function()
			for _, drop in collectionService:GetTagged('ItemDrop') do
				local handle = drop:FindFirstChild('Handle')
				if handle then
					local lootType, config = getLootType(drop.Name)
					if lootType and isLootEnabled(lootType) and not self.Reference[handle] then
						added(handle, lootType, config)
					end
				end
			end
		end
		self.IsLootEnabled = isLootEnabled
		self.Added = added
		self.Removed = removed
		self.FindLoot()
		self:Clean(collectionService:GetInstanceAddedSignal('ItemDrop'):Connect(function(drop)
			if not self.Enabled then return end
			task.defer(function()
				local handle = drop:FindFirstChild('Handle')
				if not handle then return end
				local lootType, config = getLootType(drop.Name)
				if lootType and isLootEnabled(lootType) then
					added(handle, lootType, config)
				end
			end)
		end))
		self:Clean(collectionService:GetInstanceRemovedSignal('ItemDrop'):Connect(function(drop)
			local handle = drop:FindFirstChild('Handle')
			if handle then
				removed(handle)
			end
		end))
	end
	local lootConfigs = {
		iron = {icon = 'iron', displayName = 'IRON', color = Color3.fromRGB(200, 200, 200)},
		diamond = {icon = 'diamond', displayName = 'DIAMOND', color = Color3.fromRGB(85, 200, 255)},
		emerald = {icon = 'emerald', displayName = 'EMERALD', color = Color3.fromRGB(0, 255, 100)}
	}
	local function refreshLoot(section, lootType)
		if not Loot.Enabled then return end
		local enabled = section.IsLootEnabled and section.IsLootEnabled(lootType)
		if not enabled then
			for handle, billboard in Loot.Reference do
				if billboard.Name == lootType then
					billboard:Destroy()
					Loot.Reference[handle] = nil
				end
			end
		else
			for _, drop in collectionService:GetTagged('ItemDrop') do
				local handle = drop:FindFirstChild('Handle')
				if handle and not Loot.Reference[handle] then
					section.Added(handle, lootType, lootConfigs[lootType])
				end
			end
		end
	end
	Callbacks.LootIron = function() refreshLoot(Loot, 'iron') end
	Callbacks.LootDiamond = function() refreshLoot(Loot, 'diamond') end
	Callbacks.LootEmerald = function() refreshLoot(Loot, 'emerald') end
end)

end)

-- ===== Render/ItemPlates.lua =====
run(function()
	local Sides = sides
	local AddBlur = addBlur
	local CollectionService = collectionService
	local GetPlacedBlock = getPlacedBlock
	local VapeEvents = vapeEvents
	local ItemPlates
	local Whitelist
	local Background
	local Color = {}
	local Reference = {}
	local Folder: Folder = Instance.new("Folder")
	if vape.ThreadFix then
		setthreadidentity(8)
	end
	Folder.Parent = vape.gui

	local function ScanSide(self, Start: Vector3, Found: {string})
		for _, v: Vector3 in Sides do
			for i: number = 1, 15 do
				local Block: Instance? = GetPlacedBlock(Start + (v * i))
				if not Block or Block == self then break end
				if not Block:GetAttribute("NoBreak") and not table.find(Found, Block.Name) then
					table.insert(Found, Block.Name)
				end
			end
		end
	end

	local function RefreshAdornee(Billboard: BillboardGui)
		local Adornee: Instance? = Billboard.Adornee
		if not Adornee or not Adornee.Parent then
			Billboard.Enabled = false
			return
		end

		for _, v: Instance in Billboard.Frame:GetChildren() do
			if v:IsA("ImageLabel") then
				v:Destroy()
			end
		end

		local AlreadyGot: {string} = {}
		ScanSide(Adornee, Adornee.Position, AlreadyGot)
		ScanSide(Adornee, Adornee.Position + Vector3.new(0, 0, 3), AlreadyGot)
		table.sort(AlreadyGot, function(A: string, B: string)
			local First = bedwars.ItemMeta[A]
			local Second = bedwars.ItemMeta[B]
			return (First and First.block and First.block.health or 0) > (Second and Second.block and Second.block.health or 0)
		end)
		Billboard.Enabled = #AlreadyGot > 0

		for _, v: string in AlreadyGot do
			local BlockImage: ImageLabel = Instance.new("ImageLabel")
			BlockImage.Size = UDim2.fromOffset(32, 32)
			BlockImage.BackgroundTransparency = 1
			BlockImage.Image = bedwars.getIcon({itemType = v}, true)
			BlockImage.Parent = Billboard.Frame
		end
	end

	local function Added(Part: Instance)
		if not table.find(Whitelist.ListEnabled, Part.Name) or Reference[Part] then return end

		local Billboard: BillboardGui = Instance.new("BillboardGui")
		Billboard.Parent = Folder
		Billboard.Name = "bed"
		Billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
		Billboard.Size = UDim2.fromOffset(36, 36)
		Billboard.AlwaysOnTop = true
		Billboard.ClipsDescendants = false
		Billboard.Adornee = Part
		local Blur: ImageLabel = AddBlur(Billboard)
		Blur.Visible = Background.Enabled
		local Frame: Frame = Instance.new("Frame")
		Frame.Size = UDim2.fromScale(1, 1)
		Frame.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
		Frame.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
		Frame.Parent = Billboard
		local Layout: UIListLayout = Instance.new("UIListLayout")
		Layout.FillDirection = Enum.FillDirection.Horizontal
		Layout.Padding = UDim.new(0, 4)
		Layout.VerticalAlignment = Enum.VerticalAlignment.Center
		Layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
		Layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
			Billboard.Size = UDim2.fromOffset(math.max(Layout.AbsoluteContentSize.X + 4, 36), 36)
		end)
		Layout.Parent = Frame
		local Corner: UICorner = Instance.new("UICorner")
		Corner.CornerRadius = UDim.new(0, 4)
		Corner.Parent = Frame
		Reference[Part] = Billboard
		RefreshAdornee(Billboard)
	end

	ItemPlates = vape.Categories.Render:CreateModule({
		Name = "ItemPlates",
		Function = function(Callback: boolean)
			if Callback then
				for _, v: Instance in CollectionService:GetTagged("block") do
					task.spawn(Added, v)
				end
				ItemPlates:Clean(VapeEvents.PlaceBlockEvent.Event:Connect(function(Data)
					local Position: Vector3 = Data.blockRef.blockPosition * 3
					for Block: BasePart, v: BillboardGui in Reference do
						if (Position - Block.Position).Magnitude <= 30 then
							RefreshAdornee(v)
						end
					end
				end))
				ItemPlates:Clean(VapeEvents.BreakBlockEvent.Event:Connect(function(Data)
					local Position: Vector3 = Data.blockRef.blockPosition * 3
					for Block: BasePart, v: BillboardGui in Reference do
						if (Position - Block.Position).Magnitude <= 30 then
							RefreshAdornee(v)
						end
					end
				end))
				ItemPlates:Clean(CollectionService:GetInstanceAddedSignal("block"):Connect(Added))
				ItemPlates:Clean(CollectionService:GetInstanceRemovedSignal("block"):Connect(function(Part: Instance)
					if Reference[Part] then
						Reference[Part]:Destroy()
						Reference[Part] = nil
					end
				end))
			else
				table.clear(Reference)
				Folder:ClearAllChildren()
			end
		end,
		Tooltip = 'Shows the blocks around each item'
	})

	Whitelist = ItemPlates:CreateTextList({
		Name = "Whitelist",
		Function = function()
			if ItemPlates.Enabled then
				ItemPlates:Toggle()
				ItemPlates:Toggle()
			end
		end,
		Default = {"beehive"}
	})
	Background = ItemPlates:CreateGroup({
		Name = "Background",
		Function = function(Callback: boolean)
			if Color and Color.Object then
			end
			for _, v: BillboardGui in Reference do
				v.Frame.BackgroundTransparency = 1 - (Callback and Color.Opacity or 0)
				v.Blur.Visible = Callback
			end
		end,
		Default = true
	})
	Color = Background:CreateColorSlider({
		Name = "Background Color",
		DefaultValue = 0,
		DefaultOpacity = 0.5,
		Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
			for _, v: BillboardGui in Reference do
				v.Frame.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)
				v.Frame.BackgroundTransparency = 1 - (Background.Enabled and Opacity or 0)
			end
		end,
		Darker = true
	})
end)

-- ===== Render/NameTags.lua =====
run(function()
	local NameTags
	local Targets
	local Color
	local Background
	local DisplayName
	local Health
	local Distance
	local Rank
	local Enchant
	local Equipment
	local Inventory
	local InventoryList
	local DrawingToggle
	local Scale
	local FontOption
	local Teammates
	local DistanceCheck
	local DistanceLimit
	local Strings, Sizes, Reference, Refreshes = {}, {}, {}, {}

	local getfontbounds = function(text, size, font)
		return getfontsize(text, size, font, Vector2.new(100000, 100000))
	end

	local function getDeviceType(ent)
		local player = ent and ent.Player
		local character = ent and ent.Character
		local value = player and player:GetAttribute('UserInputType')
		if value == nil and character then
			value = character:GetAttribute('UserInputType')
		end
		if type(value) ~= 'string' then return nil end
		value = value:upper():gsub('%s+', '')
		if value == 'PC' then return 'PC' end
		if value == 'MOBILE' then return 'MOBILE' end
		if value == 'GAMEPAD' then return 'GAMEPAD' end
		return nil
	end

	local function getDeviceSuffix(ent, richText)
		local device = getDeviceType(ent)
		if not device then return '' end
		local icons = {
			PC = '🖥️',
			MOBILE = '📱',
			GAMEPAD = '🎮'
		}
		local icon = icons[device]
		if not icon then return '' end
		if richText then
			return ' <font color="rgb(165, 195, 255)">' .. icon .. '</font>'
		end
		return ' ' .. icon
	end

	local function itemTypeFromValue(value)
		if typeof(value) == 'Instance' then return value.Name end
		if type(value) == 'string' then return value end
		return ''
	end

	local function updateEquipment(ent, nametag)
		if not ent or not ent.Player or not nametag then return end
		local inventory = store.inventories[ent.Player]
		local armor = {}

		for _, item in (inventory and inventory.armor or {}) do
			local itemmeta = type(item) == 'table' and bedwars.ItemMeta[item.itemType]
			if itemmeta and itemmeta.armor then
				armor[itemmeta.armor.slot] = item
			end
		end

		-- Read replicated character slots as a fallback before the inventory cache fills.
		for slot = 0, 2 do
			if not armor[slot] then
				local object = ent.Character and ent.Character:FindFirstChild('ArmorInvItem_' .. slot)
				local itemType = itemTypeFromValue(object and object.Value)
				if itemType ~= '' then armor[slot] = {itemType = itemType} end
			end
		end

		local hand = inventory and inventory.hand
		if not hand then
			local object = ent.Character and ent.Character:FindFirstChild('HandInvItem')
			local itemType = itemTypeFromValue(object and object.Value)
			if itemType ~= '' then hand = {itemType = itemType} end
		end

		local kit = ent.Player:GetAttribute('PlayingAsKits') or ent.Player:GetAttribute('PlayingAsKit')
		local kitmeta = type(kit) == 'string' and kit:lower() ~= 'none' and bedwars.BedwarsKitMeta and bedwars.BedwarsKitMeta[kit]
		local icons = {
			Hand = hand or {itemType = ''},
			Helmet = armor[0] or {itemType = ''},
			Chestplate = armor[1] or {itemType = ''},
			Boots = armor[2] or {itemType = ''}
		}
		for name, item in icons do
			local icon = nametag:FindFirstChild(name)
			if icon then icon.Image = bedwars.getIcon(item, true) end
		end
		local kitIcon = nametag:FindFirstChild('Kit')
		if kitIcon then kitIcon.Image = kitmeta and kitmeta.renderImage or '' end
	end
	if vape.ThreadFix then
		setthreadidentity(8)
	end
	
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui
	local methodused
	
	local function updateInventory(ent, nametag)
		local holder = ent.Player and nametag:FindFirstChild('Inventory')
		local inventory = holder and store.inventories[ent.Player]
		if not inventory then return end
	
		local shown = 0
		for _, v in inventory.items or {} do
			if #InventoryList.ListEnabled > 0 and not table.find(InventoryList.ListEnabled, v.itemType) then continue end
	
			shown += 1
			local icon = holder:FindFirstChild(tostring(shown))
			if not icon then
				icon = Instance.new('ImageLabel')
				icon.Name = tostring(shown)
				icon.Size = UDim2.fromOffset(24, 24)
				icon.BackgroundTransparency = 1
				icon.Parent = holder
				local amount = Instance.new('TextLabel')
				amount.Name = 'Amount'
				amount.Size = UDim2.fromOffset(23, 11)
				amount.Position = UDim2.fromOffset(0, 13)
				amount.BackgroundTransparency = 1
				amount.FontFace = nametag.FontFace
				amount.TextSize = 11
				amount.TextColor3 = Color3.new(1, 1, 1)
				amount.TextStrokeColor3 = Color3.new()
				amount.TextStrokeTransparency = 0.4
				amount.TextXAlignment = Enum.TextXAlignment.Right
				amount.Parent = icon
			end
	
			icon.LayoutOrder = shown
			icon.Visible = true
			icon.Image = bedwars.getIcon(v, true)
			icon.Amount.Text = (v.amount or 1) > 1 and tostring(v.amount) or ''
		end
	
		for _, v in holder:GetChildren() do
			if v:IsA('ImageLabel') and tonumber(v.Name) > shown then
				v.Visible = false
			end
		end
	end
	
	local Added = {
		Normal = function(ent)
			if not Targets.Players.Enabled and ent.Player then return end
			if not Targets.NPCs.Enabled and ent.NPC then return end
			if Teammates.Enabled and ent.Targetable == false and (not ent.Friend) then return end
	
			local nametag = Instance.new('TextLabel')
			Strings[ent] = (ent.Player and whitelist:tag(ent.Player, true, true)..(DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name) or ent.Character.Name)..getDeviceSuffix(ent, true)
	
			if Health.Enabled then
				local healthColor = Color3.fromHSV(math.clamp(ent.Health / ent.MaxHealth, 0, 1) / 2.5, 0.89, 0.75)
				Strings[ent] = Strings[ent]..' <font color="rgb('..tostring(math.floor(healthColor.R * 255))..','..tostring(math.floor(healthColor.G * 255))..','..tostring(math.floor(healthColor.B * 255))..')">'..math.round(ent.Health)..'</font>'
			end
	
			if Distance.Enabled then
				Strings[ent] = '<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">%s</font><font color="rgb(85, 255, 85)">]</font> '..Strings[ent]
			end
	
			if Equipment.Enabled then
				for i, v in {'Hand', 'Helmet', 'Chestplate', 'Boots', 'Kit'} do
					local Icon = Instance.new('ImageLabel')
					Icon.Name = v
					Icon.Size = UDim2.fromOffset(30, 30)
					Icon.Position = UDim2.fromOffset(-60 + (i * 30), -30)
					Icon.BackgroundTransparency = 1
					Icon.Image = ''
					Icon.Parent = nametag
				end
			end
	
			if Inventory.Enabled and ent.Player then
				local holder = Instance.new('Frame')
				holder.Name = 'Inventory'
				holder.AnchorPoint = Vector2.new(0.5, 0)
				holder.AutomaticSize = Enum.AutomaticSize.X
				holder.BackgroundTransparency = 1
				holder.Position = UDim2.new(0.5, 0, 1, 2)
				holder.Size = UDim2.fromOffset(0, 24)
				holder.Parent = nametag
				local layout = Instance.new('UIListLayout')
				layout.FillDirection = Enum.FillDirection.Horizontal
				layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
				layout.Padding = UDim.new(0, 2)
				layout.SortOrder = Enum.SortOrder.LayoutOrder
				layout.Parent = holder
			end
	
			nametag.TextSize = 14 * Scale.Value
			nametag.FontFace = FontOption.Value
			local size = getfontbounds(removeTags(Strings[ent]), nametag.TextSize, nametag.FontFace)
	
			task.spawn(function()
				if Rank.Enabled and ent.Player then
					local Icon = Instance.new('ImageLabel')
					Icon.Name = 'RankIcon'
					Icon.Size = UDim2.fromOffset(30, 30)
					Icon.Position = UDim2.fromOffset(size.X + 10, -4)
					Icon.BackgroundTransparency = 1
					Icon.Image = store.rank[ent.Player]:async() and bedwars.RankMeta[store.rank[ent.Player]:async()].image or ''
					Icon.Parent = nametag
				end
			end)
	
			task.spawn(function()
				if Enchant.Enabled and ent.Player then
					local Icon = Instance.new('ImageLabel')
					Icon.Name = 'EnchantIcon'
					Icon.Size = UDim2.fromOffset(30, 30)
					Icon.Position = UDim2.fromOffset(-30, -4)
					Icon.BackgroundTransparency = 1
					Icon.Image = store.enchants[ent.Player]:async() or ''
					Icon.Parent = nametag
				end
			end)
	
			nametag.Name = ent.Player and ent.Player.Name or ent.Character.Name
			nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
			nametag.AnchorPoint = Vector2.new(0.5, 1)
			nametag.BackgroundColor3 = Color3.new()
			nametag.BackgroundTransparency = Background.Value
			nametag.BorderSizePixel = 0
			nametag.Visible = false
			nametag.Text = Distance.Enabled and entitylib.isAlive and string.format(Strings[ent], math.floor((entitylib.character.RootPart.Position - ent.RootPart.Position).Magnitude)) or Strings[ent]
			nametag.TextColor3 = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
			nametag.RichText = true
	
			nametag.Parent = Folder
			Reference[ent] = nametag
			if Equipment.Enabled then updateEquipment(ent, nametag) end
		end,
		Drawing = function(ent)
			if not Targets.Players.Enabled and ent.Player then return end
			if not Targets.NPCs.Enabled and ent.NPC then return end
			if Teammates.Enabled and ent.Targetable == false and (not ent.Friend) then return end
	
			local nametag = {}
			nametag.BG = Drawing.new('Square')
			nametag.BG.Filled = true
			nametag.BG.Transparency = 1 - Background.Value
			nametag.BG.Color = Color3.new()
			nametag.BG.ZIndex = 1
			nametag.Text = Drawing.new('Text')
			nametag.Text.Size = 15 * Scale.Value
			nametag.Text.Font = 0
			nametag.Text.ZIndex = 2
			Strings[ent] = (ent.Player and whitelist:tag(ent.Player, true)..(DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name) or ent.Character.Name)..getDeviceSuffix(ent, false)
	
			if Health.Enabled then
				Strings[ent] = Strings[ent]..' '..math.round(ent.Health)
			end
	
			if Distance.Enabled then
				Strings[ent] = '[%s] '..Strings[ent]
			end
	
			nametag.Text.Text = Strings[ent]
			nametag.Text.Color = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
			nametag.BG.Size = Vector2.new(nametag.Text.TextBounds.X + 8, nametag.Text.TextBounds.Y + 7)
			Reference[ent] = nametag
		end
	}
	
	local Removed = {
		Normal = function(ent)
			local v = Reference[ent]
			if v then
				Reference[ent] = nil
				Strings[ent] = nil
				Sizes[ent] = nil
				Refreshes[ent] = nil
				v:Destroy()
			end
		end,
		Drawing = function(ent)
			local v = Reference[ent]
			if v then
				Reference[ent] = nil
				Strings[ent] = nil
				Sizes[ent] = nil
				for _, v2 in v do
					pcall(function()
						v2.Visible = false
						v2:Remove()
					end)
				end
			end
		end
	}
	
	local shownTag = setmetatable({}, {__mode = 'k'})
	local placedTag = setmetatable({}, {__mode = 'k'})
	local bgSize = setmetatable({}, {__mode = 'k'})
	local function showTag(v, visible)
		if shownTag[v] == visible then return end
		shownTag[v] = visible
		placedTag[v] = nil
		if type(v) == 'table' then
			v.Text.Visible = visible
			v.BG.Visible = visible
		else
			v.Visible = visible
		end
	end

	local Updated = {
		Normal = function(ent)
			local nametag = Reference[ent]
			if nametag then
				Sizes[ent] = nil
				Strings[ent] = (ent.Player and whitelist:tag(ent.Player, true, true)..(DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name) or ent.Character.Name)..getDeviceSuffix(ent, true)
	
				if Health.Enabled then
					local healthColor = Color3.fromHSV(math.clamp(ent.Health / ent.MaxHealth, 0, 1) / 2.5, 0.89, 0.75)
					Strings[ent] = Strings[ent]..' <font color="rgb('..tostring(math.floor(healthColor.R * 255))..','..tostring(math.floor(healthColor.G * 255))..','..tostring(math.floor(healthColor.B * 255))..')">'..math.round(ent.Health)..'</font>'
				end
	
				if Distance.Enabled then
					Strings[ent] = '<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">%s</font><font color="rgb(85, 255, 85)">]</font> '..Strings[ent]
				end
	
				if Equipment.Enabled then
					updateEquipment(ent, nametag)
				end
	
				if Inventory.Enabled then
					updateInventory(ent, nametag)
				end
	
				if Enchant.Enabled and nametag:FindFirstChild('EnchantIcon') then
					nametag.EnchantIcon.Image = store.enchants[ent.Player]:async() or ''
				end
	
				local text = Distance.Enabled and entitylib.isAlive and string.format(Strings[ent], math.floor((entitylib.character.RootPart.Position - ent.RootPart.Position).Magnitude)) or Strings[ent]
				local size = getfontbounds(removeTags(text), nametag.TextSize, nametag.FontFace)
				nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
				nametag.Text = text
			end
		end,
		Drawing = function(ent)
			local nametag = Reference[ent]
			if nametag then
				Sizes[ent] = nil
				Strings[ent] = (ent.Player and whitelist:tag(ent.Player, true)..(DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name) or ent.Character.Name)..getDeviceSuffix(ent, false)
	
				if Health.Enabled then
					Strings[ent] = Strings[ent]..' '..math.round(ent.Health)
				end
	
				if Distance.Enabled then
					Strings[ent] = '[%s] '..Strings[ent]
					nametag.Text.Text = entitylib.isAlive and string.format(Strings[ent], math.floor((entitylib.character.RootPart.Position - ent.RootPart.Position).Magnitude)) or Strings[ent]
				else
					nametag.Text.Text = Strings[ent]
				end
	
				nametag.BG.Size = Vector2.new(nametag.Text.TextBounds.X + 8, nametag.Text.TextBounds.Y + 7)
				bgSize[nametag], placedTag[nametag] = nil, nil
				nametag.Text.Color = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
			end
		end
	}
	
	local ColorFunc = {
		Normal = function(hue, sat, val)
			local color = Color3.fromHSV(hue, sat, val)
			for i, v in Reference do
				v.TextColor3 = entitylib.getEntityColor(i) or color
			end
		end,
		Drawing = function(hue, sat, val)
			local color = Color3.fromHSV(hue, sat, val)
			for i, v in Reference do
				v.Text.Color = entitylib.getEntityColor(i) or color
			end
		end
	}
	
	local Loop = {
		Normal = function()
			if vape.ThreadFix then
				setthreadidentity(8)
			end
	
			local localPosition = entitylib.isAlive and entitylib.character.RootPart.Position
	
			for i, v in Reference do
				if not i.RootPart or not i.RootPart.Parent or not i.Character or not i.Character.Parent then
					showTag(v, false)
					continue
				end
				local rootPosition = i.RootPart.Position
	
				if DistanceCheck.Enabled then
					local distance = localPosition and (localPosition - rootPosition).Magnitude or math.huge
					if distance < DistanceLimit.ValueMin or distance > DistanceLimit.ValueMax then
						showTag(v, false)
						continue
					end
				end
	
				local headPos, headVis = gameCamera:WorldToViewportPoint(rootPosition + Vector3.new(0, i.HipHeight + 1, 0))
				showTag(v, headVis)
				if not headVis then
					continue
				end
	
				if Inventory.Enabled and i.Player and (Refreshes[i] or 0) < tick() then
					Refreshes[i] = tick() + 0.5
					store.inventories[i.Player] = bedwars.getInventory(i.Player)
					updateInventory(i, v)
				end
	
				if Distance.Enabled then
					local mag = localPosition and math.floor((localPosition - rootPosition).Magnitude) or 0
					if Sizes[i] ~= mag then
						v.Text = string.format(Strings[i], mag)
						local ize = getfontbounds(removeTags(v.Text), v.TextSize, v.FontFace)
						v.Size = UDim2.fromOffset(ize.X + 8, ize.Y + 7)
						Sizes[i] = mag
					end
				end
				local x, y = headPos.X // 1, headPos.Y // 1
				local placed = placedTag[v]
				if not placed or placed.X ~= x or placed.Y ~= y then
					placedTag[v] = Vector2.new(x, y)
					v.Position = UDim2.fromOffset(x, y)
				end
			end
		end,
		Drawing = function()
			if vape.ThreadFix then
				setthreadidentity(8)
			end
	
			local localPosition = entitylib.isAlive and entitylib.character.RootPart.Position
	
			for i, v in Reference do
				if not i.RootPart or not i.RootPart.Parent or not i.Character or not i.Character.Parent then
					showTag(v, false)
					continue
				end
				local rootPosition = i.RootPart.Position
	
				if DistanceCheck.Enabled then
					local distance = localPosition and (localPosition - rootPosition).Magnitude or math.huge
					if distance < DistanceLimit.ValueMin or distance > DistanceLimit.ValueMax then
						showTag(v, false)
						continue
					end
				end
	
				local headPos, headVis = gameCamera:WorldToViewportPoint(rootPosition + Vector3.new(0, i.HipHeight + 1, 0))
				showTag(v, headVis)
				if not headVis then
					continue
				end
	
				if Distance.Enabled then
					local mag = localPosition and math.floor((localPosition - rootPosition).Magnitude) or 0
					if Sizes[i] ~= mag then
						v.Text.Text = string.format(Strings[i], mag)
						v.BG.Size = Vector2.new(v.Text.TextBounds.X + 8, v.Text.TextBounds.Y + 7)
						Sizes[i] = mag
						placedTag[v] = nil
					end
				end
				local size = bgSize[v]
				if not size or placedTag[v] == nil then
					size = v.BG.Size
					bgSize[v] = size
				end
				local x, y = (headPos.X - size.X / 2) // 1, (headPos.Y - size.Y) // 1
				local placed = placedTag[v]
				if not placed or placed.X ~= x or placed.Y ~= y then
					local position = Vector2.new(x, y)
					placedTag[v] = position
					v.BG.Position = position
					v.Text.Position = position + Vector2.new(4, 3)
				end
			end
		end
	}
	
	NameTags = vape.Categories.Render:CreateModule({
		Name = 'NameTags',
		Function = function(callback)
			if callback then
				methodused = DrawingToggle.Enabled and 'Drawing' or 'Normal'
				if Removed[methodused] then
					NameTags:Clean(entitylib.Events.EntityRemoved:Connect(Removed[methodused]))
				end
				if Added[methodused] then
					for _, v in entitylib.List do
						if Reference[v] then
							Removed[methodused](v)
						end
						Added[methodused](v)
					end
					NameTags:Clean(entitylib.Events.EntityAdded:Connect(function(ent)
						if Reference[ent] then
							Removed[methodused](ent)
						end
						Added[methodused](ent)
					end))
				end
				if Updated[methodused] then
					NameTags:Clean(entitylib.Events.EntityUpdated:Connect(Updated[methodused]))
					for _, v in entitylib.List do
						Updated[methodused](v)
					end
				end
				if ColorFunc[methodused] then
					NameTags:Clean(vape.Categories.Friends.ColorUpdate.Event:Connect(function()
						ColorFunc[methodused](Color.Hue, Color.Sat, Color.Value)
					end))
				end
				if Loop[methodused] then
					NameTags:Clean(runService.RenderStepped:Connect(Loop[methodused]))
				end
			else
				if Removed[methodused] then
					for i in Reference do
						Removed[methodused](i)
					end
				end
			end
		end,
		Tooltip = 'Shows nametags through walls'
	})
	
	Targets = NameTags:CreateTargets({
		Players = true,
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	FontOption = NameTags:CreateFont({
		Name = 'Font',
		Blacklist = 'Arial',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	Color = NameTags:CreateColorSlider({
		Name = 'Player Color',
		Function = function(hue, sat, val)
			if NameTags.Enabled and ColorFunc[methodused] then
				ColorFunc[methodused](hue, sat, val)
			end
		end
	})
	Scale = NameTags:CreateSlider({
		Name = 'Scale',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Default = 1,
		Min = 0.1,
		Max = 1.5,
		Decimal = 10
	})
	Background = NameTags:CreateSlider({
		Name = 'Transparency',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Default = 0.5,
		Min = 0,
		Max = 1,
		Decimal = 10
	})
	Health = NameTags:CreateToggle({
		Name = 'Health',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	Distance = NameTags:CreateToggle({
		Name = 'Distance',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	Equipment = NameTags:CreateToggle({
		Name = 'Equipment',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	Inventory = NameTags:CreateGroup({
		Name = 'Inventory',
		Function = function(callback)
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Tooltip = 'Shows how many of each listed item they are carrying'
	})
	InventoryList = Inventory:CreateItemPicker({
		Name = 'Inventory Items',
		Multi = true,
		Items = bedwars.itemPickerList(),
		Default = {'fireball', 'glue_projectile', 'telepearl', 'tnt'},
		Darker = true,
		Tooltip = 'Items to count, empty shows everything'
	})
	Enchant = NameTags:CreateToggle({
		Name = 'Show Enchant',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	Rank = NameTags:CreateToggle({
		Name = 'Show Rank',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	DisplayName = NameTags:CreateToggle({
		Name = 'Use Displayname',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Default = true
	})
	Teammates = NameTags:CreateToggle({
		Name = 'Priority Only',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Default = false
	})
	DrawingToggle = NameTags:CreateToggle({
		Name = 'Drawing',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
	})
	DistanceCheck = NameTags:CreateGroup({
		Name = 'Distance Check',
	})
	DistanceLimit = DistanceCheck:CreateTwoSlider({
		Name = 'Player Distance',
		Min = 0,
		Max = 256,
		DefaultMin = 0,
		DefaultMax = 64,
		Darker = true
	})
end)

-- ===== Render/OreESP.lua =====
run(function()
	local OreESP
	local Background
	local Color
	local Scale
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui

	local tracked = {}
	local applyScale

	local function icon()
		local ok, image = pcall(function() return bedwars.getIcon({itemType = 'iron'}, true) end)
		return ok and image or ''
	end

	local function maybeOre(name)
		return name:find('re_mesh', 1, true) ~= nil or name:find('RE_MESH', 1, true) ~= nil or name:find('re_Mesh', 1, true) ~= nil
	end

	local function isOre(obj)
		if typeof(obj) ~= 'Instance' or not maybeOre(obj.Name) or not obj:IsA('BasePart') then return false end
		return obj.Name:lower():find('ore_mesh_block', 1, true) ~= nil
	end

	local function create(obj)
		if tracked[obj] or not isOre(obj) then return end

		local billboard = Instance.new('BillboardGui')
		billboard.Name = 'ore'
		billboard.Size = UDim2.fromOffset(40, 40)
		billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
		billboard.AlwaysOnTop = true
		billboard.Adornee = obj
		billboard.Parent = Folder

		local frame = Instance.new('Frame')
		frame.Size = UDim2.new(1, 0, 1, 0)
		frame.BackgroundTransparency = Background.Enabled and 0.4 or 1
		frame.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
		frame.BorderSizePixel = 0
		frame.Parent = billboard

		local corner = Instance.new('UICorner')
		corner.CornerRadius = UDim.new(0, 4)
		corner.Parent = frame

		local image = Instance.new('ImageLabel')
		image.Size = UDim2.new(1, -6, 1, -6)
		image.Position = UDim2.fromScale(0.5, 0.5)
		image.AnchorPoint = Vector2.new(0.5, 0.5)
		image.BackgroundTransparency = 1
		image.Image = icon()
		image.Parent = frame

		local blur = addBlur(frame)
		blur.Visible = Background.Enabled

		tracked[obj] = {Billboard = billboard, Frame = frame, Blur = blur, Image = image}
		applyScale()
	end

	local function remove(obj)
		local entry = tracked[obj]
		if not entry then return end
		entry.Billboard:Destroy()
		tracked[obj] = nil
	end

	function applyScale()
		for _, entry in tracked do
			entry.Billboard.Size = UDim2.fromOffset(40, 40) * Scale.Value
		end
	end

	local function clear()
		for _, entry in tracked do
			entry.Billboard:Destroy()
		end
		table.clear(tracked)
	end

	OreESP = vape.Categories.Render:CreateModule({
		Name = 'OreESP',
		Function = function(callback)
			if not callback then
				clear()
				return
			end

			for _, obj in workspace:GetDescendants() do
				create(obj)
			end

			OreESP:Clean(workspace.DescendantAdded:Connect(function(obj)
				if not maybeOre(obj.Name) then return end
				task.wait(0.1)
				if OreESP.Enabled then create(obj) end
			end))
			OreESP:Clean(workspace.DescendantRemoving:Connect(function(obj)
				remove(obj)
			end))
		end,
		Tooltip = 'Shows ore blocks through walls'
	})

	Background = OreESP:CreateToggle({
		Name = 'Background',
		Default = true,
		Tooltip = 'Draws a box behind the icon',
		Function = function(enabled)
			if Color and Color.Object then Color.Object.Visible = enabled end
			for _, entry in tracked do
				entry.Frame.BackgroundTransparency = enabled and 0.4 or 1
				entry.Blur.Visible = enabled
			end
		end
	})
	Color = OreESP:CreateColorSlider({
		Name = 'Background Color',
		DefaultValue = 0,
		DefaultOpacity = 0.6,
		Darker = true,
		Function = function(hue, sat, val, opacity)
			for _, entry in tracked do
				entry.Frame.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
				entry.Frame.BackgroundTransparency = 1 - opacity
			end
		end
	})
	Scale = OreESP:CreateSlider({
		Name = 'Scale',
		Min = 0.5,
		Max = 3,
		Default = 1,
		Decimal = 10,
		Function = applyScale
	})

	task.defer(function()
		if Color and Color.Object then Color.Object.Visible = Background.Enabled end
	end)
end)

-- ===== Render/OverlayEditor.lua =====
run(function()
	local OverlayEditor
	local FillColor
	local OutlineColor
	local Thickness
	local Animate
	local Speed
	local overlay, overlayBox, overlayTween
	local activePart

	local function bindPart(part)
		if not OverlayEditor.Enabled or not overlay then return end
		if not part:IsA('BasePart') or not part.Anchored or part.Transparency ~= 1 then return end
		local box = part:FindFirstChildOfClass('SelectionBox')
		if not box then return end

		box.Visible = false
		activePart = part
		if overlayTween then
			overlayTween:Cancel()
			overlayTween = nil
		end

		if Animate.Enabled and overlay.Parent == gameCamera then
			overlayTween = tweenService:Create(overlay, TweenInfo.new(Speed.Value, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				CFrame = part.CFrame,
				Size = part.Size
			})
			overlayTween:Play()
		else
			overlay.CFrame = part.CFrame
			overlay.Size = part.Size
			overlay.Parent = gameCamera
		end
	end

	OverlayEditor = vape.Categories.Render:CreateModule({
		Name = 'OverlayEditor',
		Function = function(callback)
			if callback then
				overlay = Instance.new('Part')
				overlay.Size = Vector3.one * 3
				overlay.Anchored = true
				overlay.CanCollide = false
				overlay.CanQuery = false
				overlay.CanTouch = false
				overlay.CastShadow = false
				overlay.Transparency = 1
				overlayBox = Instance.new('SelectionBox')
				overlayBox.Adornee = overlay
				overlayBox.LineThickness = Thickness.Value
				overlayBox.Color3 = Color3.fromHSV(OutlineColor.Hue, OutlineColor.Sat, OutlineColor.Value)
				overlayBox.Transparency = 1 - OutlineColor.Opacity
				overlayBox.SurfaceColor3 = Color3.fromHSV(FillColor.Hue, FillColor.Sat, FillColor.Value)
				overlayBox.SurfaceTransparency = 1 - FillColor.Opacity
				overlayBox.Parent = overlay
				bedwars.QueryUtil:setQueryIgnored(overlay, true)

				for _, v in workspace:GetChildren() do
					bindPart(v)
				end

				OverlayEditor:Clean(workspace.ChildAdded:Connect(function(child)
					task.defer(bindPart, child)
				end))
				OverlayEditor:Clean(workspace.ChildRemoved:Connect(function(child)
					if child ~= activePart then return end

					activePart = nil
					task.delay(0.06, function()
						if activePart or not OverlayEditor.Enabled then return end
						if overlayTween then
							overlayTween:Cancel()
							overlayTween = nil
						end
						if overlay then
							overlay.Parent = nil
						end
					end)
				end))
			else
				if activePart then
					local box = activePart:FindFirstChildOfClass('SelectionBox')
					if box then
						box.Visible = true
					end
					activePart = nil
				end

				if overlayTween then
					overlayTween:Cancel()
					overlayTween = nil
				end
				if overlay then
					overlay:Destroy()
					overlay, overlayBox = nil, nil
				end
			end
		end,
		Tooltip = 'Restyles the outline on the block you are aiming at'
	})

	FillColor = OverlayEditor:CreateColorSlider({
		Name = 'Fill colour',
		DefaultSat = 0,
		DefaultOpacity = 0.25,
		Darker = true,
		Function = function(hue, sat, val, opacity)
			if overlayBox then
				overlayBox.SurfaceColor3 = Color3.fromHSV(hue, sat, val)
				overlayBox.SurfaceTransparency = 1 - opacity
			end
		end
	})
	OutlineColor = OverlayEditor:CreateColorSlider({
		Name = 'Outline colour',
		DefaultSat = 0,
		Darker = true,
		Function = function(hue, sat, val, opacity)
			if overlayBox then
				overlayBox.Color3 = Color3.fromHSV(hue, sat, val)
				overlayBox.Transparency = 1 - opacity
			end
		end
	})
	Thickness = OverlayEditor:CreateSlider({
		Name = 'Thickness',
		Min = 0.01,
		Max = 0.2,
		Decimal = 100,
		Function = function(value)
			if overlayBox then
				overlayBox.LineThickness = value
			end
		end,
		Default = 0.04
	})
	Animate = OverlayEditor:CreateToggle({
		Name = 'Animate',
		Default = true,
		Tooltip = 'Moves the overlay smoothly between blocks'
	})
	Speed = OverlayEditor:CreateSlider({
		Name = 'Animation time',
		Min = 0.01,
		Max = 0.5,
		Default = 0.08,
		Decimal = 100,
		Suffix = 's'
	})
end)

-- ===== Render/PotESP.lua =====
run(function()
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui

	local function createSection()
		local section = {
			Enabled = false,
			Connections = {},
			Reference = {},
			Folder = Instance.new('Folder')
		}
		section.Folder.Parent = Folder
		function section:Clean(item)
			if type(item) == 'function' then
				table.insert(self.Connections, {Disconnect = item})
			elseif item then
				table.insert(self.Connections, item)
			end
		end
		function section:Clear()
			for _, connection in self.Connections do
				pcall(function() connection:Disconnect() end)
			end
			table.clear(self.Connections)
			if self.Stop then self.Stop(self) end
			for _, instance in self.Reference do
				pcall(function() instance:Destroy() end)
			end
			table.clear(self.Reference)
			self.Folder:ClearAllChildren()
		end
		function section:Set(callback)
			if callback == self.Enabled then return end
			self.Enabled = callback
			self:Clear()
			if callback and self.Start then self.Start(self) end
		end
		return section
	end
	local Pots = createSection()
	local PotBackground, PotColor
	local Callbacks = {}
	local PotESP = vape.Categories.Render:CreateModule({
		Name = 'PotESP',
		Function = function(callback)
			Pots:Set(callback)
			for _, setting in {PotBackground,
				PotColor} do
				if setting and setting.Object then
					setting.Object.Visible = callback and (setting ~= PotColor or PotBackground.Enabled)
				end
			end
		end,
		Tooltip = 'Shows desert pots through walls'
	})
	PotBackground = PotESP:CreateToggle({Visible = false, Function = function(...) if Callbacks.PotBackground then return Callbacks.PotBackground(...) end end, Name = 'Pot background', Default = true})
	PotColor = PotESP:CreateColorSlider({
		Visible = false,
		Name = 'Pot background colour',
		DefaultValue = 0,
		DefaultOpacity = 0.5,
		Darker = true,
		Function = function(hue, sat, val, opacity)
			for _, v in Pots.Reference do
				v.ViewportFrame.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
				v.ViewportFrame.BackgroundTransparency = 1 - (PotBackground.Enabled and opacity or 0)
			end
		end
	})

	Pots.Start = function(self)
		local template
		local function added(block)
			if block.Name ~= 'desert_pot' or self.Reference[block] then return end
			local billboard = Instance.new('BillboardGui')
			billboard.Parent = self.Folder
			billboard.Name = block.Name
			billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
			billboard.Size = UDim2.fromOffset(36, 36)
			billboard.AlwaysOnTop = true
			billboard.ClipsDescendants = false
			billboard.Adornee = block
			local blur = addBlur(billboard)
			if blur then blur.Visible = PotBackground.Enabled end
			local viewport = Instance.new('ViewportFrame')
			viewport.Size = UDim2.fromOffset(36, 36)
			viewport.Position = UDim2.fromScale(0.5, 0.5)
			viewport.AnchorPoint = Vector2.new(0.5, 0.5)
			viewport.BackgroundColor3 = Color3.fromHSV(PotColor.Hue, PotColor.Sat, PotColor.Value)
			viewport.BackgroundTransparency = 1 - (PotBackground.Enabled and PotColor.Opacity or 0)
			viewport.BorderSizePixel = 0
			viewport.Ambient = Color3.new(1, 1, 1)
			viewport.LightColor = Color3.new(1, 1, 1)
			viewport.Parent = billboard
			local uicorner = Instance.new('UICorner')
			uicorner.CornerRadius = UDim.new(0, 4)
			uicorner.Parent = viewport
			if template == nil then
				local assets = replicatedStorage:FindFirstChild('Assets')
				local blocks = assets and assets:FindFirstChild('Blocks')
				local model = blocks and blocks:FindFirstChild('desert_pot')
				template = model and model:FindFirstChildWhichIsA('MeshPart', true) or false
			end
			if template then
				local mesh = template:Clone()
				mesh.CFrame = CFrame.Angles(0, math.rad(25), 0)
				mesh.Parent = viewport
				local camera = Instance.new('Camera')
				camera.CFrame = CFrame.lookAt(Vector3.new(0, 0.75, 3.9), Vector3.new(0, 0.05, 0))
				camera.Parent = viewport
				viewport.CurrentCamera = camera
			end
			self.Reference[block] = billboard
		end
		self.Added = added
		for _, v in collectionService:GetTagged('block') do
			added(v)
		end
		self:Clean(collectionService:GetInstanceAddedSignal('block'):Connect(added))
		self:Clean(collectionService:GetInstanceRemovedSignal('block'):Connect(function(block)
			if self.Reference[block] then
				self.Reference[block]:Destroy()
				self.Reference[block] = nil
			end
		end))
	end
	Callbacks.PotBackground = function(callback)
		PotColor.Object.Visible = callback and PotESP.Enabled
		for _, v in Pots.Reference do
			v.ViewportFrame.BackgroundTransparency = 1 - (callback and PotColor.Opacity or 0)
			if v.Blur then v.Blur.Visible = callback end
		end
	end
end)

-- ===== Render/PotatoMode.lua =====
run(function()
	local PotatoMode
	local Lighting = game:GetService('Lighting')
	local Terrain = workspace:FindFirstChildOfClass('Terrain')
	local saved = {}

	PotatoMode = vape.Categories.Render:CreateModule({
		Name = 'PotatoMode',
		Function = function(callback)
			if callback then
				saved.QualityLevel = settings().Rendering.QualityLevel
				saved.MeshPartDetailLevel = settings().Rendering.MeshPartDetailLevel
				saved.EagerBulkExecution = settings().Rendering.EagerBulkExecution
				pcall(function()
					settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
					settings().Rendering.MeshPartDetailLevel = Enum.MeshPartDetailLevel.Level01
					settings().Rendering.EagerBulkExecution = true
				end)
				pcall(function()
					Lighting.GlobalShadows = false
					Lighting.FogEnd = 9e9
					if Terrain then
						Terrain.Decoration = false
					end
				end)
				for _, v in Lighting:GetChildren() do
					if v:IsA('PostEffect') or v:IsA('BloomEffect') or v:IsA('BlurEffect') or v:IsA('SunRaysEffect') or v:IsA('ColorCorrectionEffect') or v:IsA('DepthOfFieldEffect') then
						saved[v] = v.Enabled
						v.Enabled = false
					end
				end
