				end
				table.clear(saved)
			end
		end,
		Tooltip = 'lowest graphics for max fps'
	})
end)

-- ===== Render/ProjectileTracers.lua =====
run(function()
    local BulletTracers
    local Material
    local Lifetime
    local Curve
    local Opacity
    local Thickness
    local Color
    local Fade

    local rayCheck = RaycastParams.new()
    rayCheck.FilterType = Enum.RaycastFilterType.Exclude

    local launchHook
    local lastTraced = 0
	local pendingLaunch
	local function muzzleOrigin(origin, velocity)
		local constants = bedwars and bedwars.BowConstantsTable
		if type(constants) ~= 'table' or typeof(origin) ~= 'Vector3' or typeof(velocity) ~= 'Vector3' or velocity.Magnitude <= 1e-3 then
			return origin
		end
		local offset = Vector3.new(
			-(tonumber(constants.RelX) or 0),
			-(tonumber(constants.RelY) or 0),
			-(tonumber(constants.RelZ) or 0)
		)
		return (CFrame.lookAt(origin, origin + velocity) * CFrame.new(offset)).Position
	end
	local releaseWindow = 0.5

    local function drawTracer(origin, velocity, gravity)
	local velocityMagnitude = velocity.Magnitude
	if velocityMagnitude <= 0 then return end
	local velocityUnit = velocity / velocityMagnitude
	rayCheck.FilterDescendantsInstances = {lplr.Character}
	local ray = workspace:Raycast(origin, velocityUnit * 2000, rayCheck)
	local endpoint = ray and ray.Position or (origin + velocityUnit * 2000)
	lastTraced = tick()
	pendingLaunch = nil
	prediction.SpawnArcTracer(
		origin,
		velocityUnit,
		velocityMagnitude,
		gravity,
		(endpoint - origin).Magnitude / velocityMagnitude,
		Curve.Value,
		{
			Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value),
			Transparency = Opacity.Value,
			Thick = Thickness.Value,
			Material = Enum.Material[Material.Value],
			Lifetime = Lifetime.Value,
			Fade = Fade.Enabled,
		}
	)
    end

    BulletTracers = vape.Categories.Render:CreateModule({
	Name = 'ProjectileTracers',
	Function = function(callback)
		if callback then
			if bedwars.ProjectileLaunchHook then
				launchHook = bedwars.ProjectileLaunchHook:Add('ProjectileTracers', 5, function(nextLaunch, ...)
					local result = nextLaunch(...)
					if type(result) == 'table' and typeof(result.positionFrom) == 'Vector3'
						and typeof(result.initialVelocity) == 'Vector3' then
						local projmeta = select(2, ...)
						local meta = projmeta and bedwars.ProjectileMeta[projmeta.projectile]
						pendingLaunch = {
							Origin = muzzleOrigin(result.positionFrom, result.initialVelocity),
							Velocity = result.initialVelocity,
							Gravity = tonumber(result.gravitationalAcceleration) or (meta and tonumber(meta.gravitationalAcceleration)) or workspace.Gravity,
							At = tick()
						}
					end
					return result
				end)
				BulletTracers:Clean(function()
					if launchHook then launchHook(); launchHook = nil end
					pendingLaunch = nil
				end)
			end

			BulletTracers:Clean(workspace.ChildAdded:Connect(function(projectile)
				task.delay(0, function()
					if projectile:GetAttribute('ProjectileShooter') ~= lplr.UserId then
						return
					end
					if tick() - lastTraced < 0.35 then return end
					local launch = pendingLaunch
					if launch and (tick() - launch.At) <= releaseWindow then
						drawTracer(launch.Origin, launch.Velocity, launch.Gravity)
						return
					end
					pendingLaunch = nil
					local origin = projectile:GetPivot().Position
					local velocity = projectile.PrimaryPart and projectile.PrimaryPart.Velocity or Vector3.zero
					local meta = bedwars.ProjectileMeta[projectile.Name]
					drawTracer(origin, velocity, meta and tonumber(meta.gravitationalAcceleration) or workspace.Gravity)
				end)
			end))
		elseif launchHook then
			launchHook()
			launchHook = nil
			pendingLaunch = nil
		end
	end,
	Tooltip = 'Changes how projectile trails look'
    })

    local materials = {'SmoothPlastic'}
    for _, v in Enum.Material:GetEnumItems() do
	if v.Name ~= 'SmoothPlastic' then
		table.insert(materials, v.Name)
	end
    end
    Material = BulletTracers:CreateDropdown({
	Name = 'Material',
	List = materials
    })
    Color = BulletTracers:CreateColorSlider({
	Name = 'Tracer Colour',
	DefaultOpacity = 0.5
    })
    Thickness = BulletTracers:CreateSlider({
	Name = 'Thickness',
	Min = 0.01,
	Max = 1,
	Default = 0.1,
	Decimal = 100
    })
    Curve = BulletTracers:CreateSlider({
	Name = 'Curveness',
	Min = 1,
	Max = 100,
	Default = 40,
	Tooltip = 'How smooth the curve is'
    })
    Opacity = BulletTracers:CreateSlider({
	Name = 'Opacity',
	Min = 0,
	Max = 1,
	Default = 0,
	Decimal = 100
    })
    Lifetime = BulletTracers:CreateSlider({
	Name = 'Lifetime',
	Min = 0,
	Max = 5,
	Decimal = 100,
	Default = 2,
	Suffix = 'secs'
    })
    Fade = BulletTracers:CreateToggle({
	Name = 'Fade',
	Default = true
    })
end)

-- ===== Render/QueueCardMods.lua =====
local function category(name)
	if vape and vape.Categories and vape.Categories[name] then
		return vape.Categories[name]
	end
	if vape and vape.Categories then
		for _, cat in pairs(vape.Categories) do
			if type(cat) == "table" and cat.CreateModule then
				return cat
			end
		end
	end
	return nil
end

local function createModule(catName, def)
	local cat = category(catName) or category("Utility") or category("Render") or category("Blatant")
	assert(cat and cat.CreateModule, "Aether GUI not ready (no CreateModule)")
	return cat:CreateModule(def)
end

local function isAlive(plr)
	plr = plr or lplr
	local char = plr.Character
	if not char then return false end
	local hum = char:FindFirstChildOfClass("Humanoid")
	local root = char:FindFirstChild("HumanoidRootPart")
	return hum ~= nil and root ~= nil and hum.Health > 0
end

local function guiColor()
	local ok, color = pcall(function()
		if vape.GUIColor then
			return Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value)
		end
	end)
	if ok and color then return color end
	return Color3.fromRGB(120, 200, 255)
end

run(function()
	local cfg = {
		speed = 0.5,
		c1 = {H = 0.6, S = 0.8, V = 1},
		c2 = {H = 0.8, S = 0.8, V = 0.8}
	}
	local conA, conB
	local Color1, Color2, Speed

	local function apply()
		pcall(function()
			if conA then conA:Disconnect() end
			local app = lplr.PlayerGui:FindFirstChild("QueueApp")
			if not app then return end
			local frame = app:FindFirstChild("1")
			if not frame then return end
			frame.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
			local g = frame:FindFirstChildOfClass("UIGradient") or Instance.new("UIGradient")
			g.Rotation = 180
			g.Parent = frame
			conA = runService.RenderStepped:Connect(function()
				local t = (math.sin(tick() * cfg.speed) + 1) / 2
				local h = cfg.c1.H + (cfg.c2.H - cfg.c1.H) * t
				local s = cfg.c1.S + (cfg.c2.S - cfg.c1.S) * t
				local v = cfg.c1.V + (cfg.c2.V - cfg.c1.V) * t
				g.Color = ColorSequence.new(Color3.fromHSV(h, s, v))
			end)
		end)
	end

	local QueueCard = createModule("Render", {
		Name = "QueueCardMods",
		Tooltip = "Animated gradient on the queue card",
		Function = function(on)
			if on then
				apply()
				conB = lplr.PlayerGui.ChildAdded:Connect(function(c)
					if c.Name == "QueueApp" then
						task.wait(0.1)
						apply()
					end
				end)
			else
				if conA then conA:Disconnect() end
				if conB then conB:Disconnect() end
				conA, conB = nil, nil
			end
		end
	})

	Speed = QueueCard:CreateSlider({
		Name = "Animation Speed",
		Min = 1,
		Max = 5,
		Default = 3,
		Function = function(val)
			cfg.speed = math.clamp(val, 0.1, 5)
		end
	})

	if QueueCard.CreateColorSlider then
		QueueCard:CreateColorSlider({
			Name = "Colour 1",
			Function = function(h, s, v)
				cfg.c1 = {H = h, S = s, V = v}
			end
		})
		QueueCard:CreateColorSlider({
			Name = "Colour 2",
			Function = function(h, s, v)
				cfg.c2 = {H = h, S = s, V = v}
			end
		})
	end
end)

-- ===== Render/SkinChanger.lua =====
run(function()
	local SkinChanger
	local Options = {}
	local skins, families, groups, order = {}, {}, {}, {}
	local names, extras = {}, {}
	local sounds = {}
	local added = setmetatable({}, {__mode = 'k'})
	local watching, lasthand, queued
	local tiers = {leather = true, chainmail = true, wood = true, stone = true, gold = true, iron = true, diamond = true, emerald = true}
	
	local function getSkinMeta(skin)
		local getItemSkinMeta = bedwars.getItemSkinMeta
		return type(getItemSkinMeta) == 'function' and getItemSkinMeta(skin) or nil
	end

	for _, v in bedwars.ItemSkinType or {} do
		local meta = getSkinMeta(v)
		local item = meta and meta.itemType and bedwars.ItemMeta[meta.itemType]
		if item and not item.block then
			local label = `_{v}_`
			for i in meta.itemType:gmatch('[^_]+') do
				label = label:gsub(`_{i}_`, '_')
			end
			label = label:gsub('^_+', ''):gsub('_+$', '')
			label = (tostring(label ~= '' and label or v):gsub('_', ' '):gsub('%a+', function(word)
				return `{word:sub(1, 1):upper()}{word:sub(2)}`
			end))
	
			skins[meta.itemType] = skins[meta.itemType] or {}
			skins[meta.itemType][label] = v
		end
	end
	
	for i in skins do
		local family = i:gsub('_%d+$', '')
		local tier, base = family:match('^([^_]+)_(.+)$')
		family = tier and tiers[tier] and base or family
		if not groups[family] then
			groups[family] = {}
			table.insert(order, family)
		end
		families[i] = family
		table.insert(groups[family], i)
	end
	
	for i, v in groups do
		names[i] = (tostring(#v > 1 and i or v[1]):gsub('_', ' '):gsub('%a+', function(word)
			return `{word:sub(1, 1):upper()}{word:sub(2)}`
		end))
	end
	table.sort(order, function(a, b)
		return names[a] < names[b]
	end)
	
	for _, v in {'lobby_kaida_claw', 'bear_claws', 'summoner_claw_1', 'summoner_claw_2', 'summoner_claw_3', 'summoner_claw_4'} do
		if replicatedStorage.Items and replicatedStorage.Items:FindFirstChild(v) then
			local label = (tostring((v:gsub('^lobby_', ''))):gsub('_', ' '):gsub('%a+', function(word)
				return `{word:sub(1, 1):upper()}{word:sub(2)}`
			end))
			extras[label] = v
		end
	end
	
	local function applyModel(accessory)
		local family = SkinChanger.Enabled and families[accessory.Name]
		local option = family and Options[family]
		local label = option and option.Value
		local model = label and (extras[label] or skins[accessory.Name][label]) or nil
		local handle = accessory:FindFirstChild('Handle')
		local template = replicatedStorage.Items and replicatedStorage.Items:FindFirstChild(model or '')
		if not handle or not template then return end
		if added[accessory] then return end
	
		local grip = handle:FindFirstChild('RightGripAttachment')
		local templategrip = template.Handle:FindFirstChild('RightGripAttachment')
		local record = {
			Parts = {},
			Size = handle.Size,
			Grip = grip and grip.CFrame or nil
		}
		added[accessory] = record
	
		for _, v in handle:GetChildren() do
			if v:IsA('BasePart') and v:GetAttribute('SkinHidden') == nil then
				v:SetAttribute('SkinHidden', v.Transparency)
				v.Transparency = 1
			end
		end
	
		if handle:IsA('MeshPart') and template.Handle:IsA('MeshPart') then
			handle:ApplyMesh(template.Handle)
		end
		handle.Size = template.Handle.Size
		if grip and templategrip then
			grip.CFrame = templategrip.CFrame
		end
	
		for _, v in template.Handle:GetChildren() do
			if v:IsA('BasePart') then
				local part = v:Clone()
				part.CanCollide = false
				part.CanTouch = false
				part.CanQuery = false
				part.Massless = true
				part.CFrame = handle.CFrame * (template.Handle.CFrame:Inverse() * v.CFrame)
				part.Parent = handle
	
				local weld = Instance.new('WeldConstraint')
				weld.Part0 = handle
				weld.Part1 = part
				weld.Parent = part
				table.insert(record.Parts, part)
			end
		end
	end
	
	local function applySkins()
		for i in skins do
			local meta = bedwars.ItemMeta[i]
			if meta and meta.sword then
				local family = SkinChanger.Enabled and families[i]
				local option = family and Options[family]
				local label = option and option.Value
				local skin = label and not extras[label] and skins[i][label] or nil
				local skinmeta = skin and getSkinMeta(skin)
				local sword = skinmeta and skinmeta.sword
				if sword and (sword.swingSounds or sword.hitSounds) then
					if not sounds[i] then
						sounds[i] = {swing = meta.sword.swingSounds, hit = meta.sword.hitSounds}
					end
					meta.sword.swingSounds = sword.swingSounds or sounds[i].swing
					meta.sword.hitSounds = sword.hitSounds or sounds[i].hit
				elseif sounds[i] then
					meta.sword.swingSounds = sounds[i].swing
					meta.sword.hitSounds = sounds[i].hit
					sounds[i] = nil
				end
			end
		end
	
		local inventory = store.inventory.inventory
		local changed = false
		for _, v in inventory.items do
			local family = SkinChanger.Enabled and families[v.itemType]
			local option = family and Options[family]
			local label = option and option.Value
			local skin = label and not extras[label] and skins[v.itemType][label] or nil
			if v.itemSkin ~= skin then
				v.itemSkin = skin
				changed = true
			end
		end
		if inventory.hand then
			local family = SkinChanger.Enabled and families[inventory.hand.itemType]
			local option = family and Options[family]
			local label = option and option.Value
			local skin = label and not extras[label] and skins[inventory.hand.itemType][label] or nil
			if inventory.hand.itemSkin ~= skin then
				inventory.hand.itemSkin = skin
				changed = true
			end
		end
	
		local hand = inventory.hand and inventory.hand.itemType
		if not changed and hand == lasthand then return end
	
		lasthand = hand
		bedwars.InventoryViewmodelController:handleStore(bedwars.Store:getState())
		if not lplr.Character then return end
	
		for _, v in lplr.Character:GetChildren() do
			if not v:IsA('Accessory') then continue end
	
			local record = added[v]
			if record then
				local handle = v:FindFirstChild('Handle')
				local template = replicatedStorage.Items and replicatedStorage.Items:FindFirstChild(v.Name)
				for _, v2 in record.Parts do
					v2:Destroy()
				end
	
				for _, v2 in handle and handle:GetChildren() or {} do
					local transparency = v2:GetAttribute('SkinHidden')
					if transparency then
						v2.Transparency = transparency
						v2:SetAttribute('SkinHidden', nil)
					end
				end
				added[v] = nil
	
				if handle then
					if template and handle:IsA('MeshPart') and template.Handle:IsA('MeshPart') then
						handle:ApplyMesh(template.Handle)
					end
					handle.Size = record.Size
	
					local grip = handle:FindFirstChild('RightGripAttachment')
					if grip and record.Grip then
						grip.CFrame = record.Grip
					end
				end
			end
	
			applyModel(v)
		end
	end
	
	local function queueSkins()
		if queued then return end
	
		queued = true
		task.defer(function()
			queued = false
			applySkins()
		end)
	end
	
	SkinChanger = vape.Categories.Render:CreateModule({
		Name = 'SkinChanger',
		Function = function(callback)
			if callback then
				SkinChanger:Clean(vapeEvents.InventoryChanged.Event:Connect(queueSkins))
				SkinChanger:Clean(vapeEvents.InventoryAmountChanged.Event:Connect(queueSkins))
				SkinChanger:Clean(lplr.CharacterAdded:Connect(function(char)
					lasthand = nil
					if watching then
						watching:Disconnect()
					end
					watching = char.ChildAdded:Connect(function(v)
						if v:IsA('Accessory') and v:WaitForChild('Handle', 3) and SkinChanger.Enabled then
							applyModel(v)
						end
					end)
	
					task.spawn(function()
						for _ = 1, 10 do
							task.wait(0.4)
							if not SkinChanger.Enabled then return end
							applySkins()
						end
					end)
				end))
	
				if lplr.Character then
					if watching then
						watching:Disconnect()
					end
					watching = lplr.Character.ChildAdded:Connect(function(v)
						if v:IsA('Accessory') and v:WaitForChild('Handle', 3) and SkinChanger.Enabled then
							applyModel(v)
						end
					end)
				end
			elseif watching then
				watching:Disconnect()
				watching = nil
			end
			applySkins()
		end,
		Tooltip = 'Reskins the items you hold, only on your screen'
	})
	
	for _, v in order do
		local list, seen = {}, {}
		for _, v2 in groups[v] do
			for i2 in skins[v2] do
				if not seen[i2] then
					seen[i2] = true
					table.insert(list, i2)
				end
			end
		end
	
		local melee = false
		for _, v2 in groups[v] do
			local meta = bedwars.ItemMeta[v2]
			if meta and meta.sword then
				melee = true
				break
			end
		end
	
		if melee then
			for i2 in extras do
				table.insert(list, i2)
			end
		end
	
		table.sort(list)
		table.insert(list, 1, 'None')
		Options[v] = SkinChanger:CreateDropdown({
			Name = names[v],
			List = list,
			Function = function()
				if SkinChanger.Enabled then
					applySkins()
				end
			end
		})
	end
end)

-- ===== Render/StorageESP.lua =====
run(function()
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui

	local function createSection()
		local section = {
			Enabled = false,
			Connections = {},
			Reference = {},
			Folder = Instance.new('Folder')
		}
		section.Folder.Parent = Folder
		function section:Clean(item)
			if type(item) == 'function' then
				table.insert(self.Connections, {Disconnect = item})
			elseif item then
				table.insert(self.Connections, item)
			end
		end
		function section:Clear()
			for _, connection in self.Connections do
				pcall(function() connection:Disconnect() end)
			end
			table.clear(self.Connections)
			if self.Stop then self.Stop(self) end
			for _, instance in self.Reference do
				pcall(function() instance:Destroy() end)
			end
			table.clear(self.Reference)
			self.Folder:ClearAllChildren()
		end
		function section:Set(callback)
			if callback == self.Enabled then return end
			self.Enabled = callback
			self:Clear()
			if callback and self.Start then self.Start(self) end
		end
		return section
	end
	local Storage = createSection()
	local StorageItems, StorageBackground, StorageColor
	local Callbacks = {}
	local StorageESP = vape.Categories.Render:CreateModule({
		Name = 'StorageESP',
		Function = function(callback)
			Storage:Set(callback)
			for _, setting in {StorageItems,
				StorageBackground,
				StorageColor} do
				if setting and setting.Object then
					setting.Object.Visible = callback and (setting ~= StorageColor or StorageBackground.Enabled)
				end
			end
		end,
		Tooltip = 'Shows what is in chests'
	})
	StorageItems = StorageESP:CreateTextList({Visible = false, Function = function(...) if Callbacks.StorageItems then return Callbacks.StorageItems(...) end end, Name = 'Storage items'})
	StorageBackground = StorageESP:CreateToggle({Visible = false, Function = function(...) if Callbacks.StorageBackground then return Callbacks.StorageBackground(...) end end, Name = 'Storage background', Default = true})
	StorageColor = StorageESP:CreateColorSlider({
		Visible = false,
		Name = 'Storage background colour',
		DefaultValue = 0,
		DefaultOpacity = 0.5,
		Darker = true,
		Function = function(hue, sat, val, opacity)
			for _, v in Storage.Reference do
				v.Frame.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
				v.Frame.BackgroundTransparency = 1 - opacity
			end
		end
	})

	Storage.Start = function(self)
		local connections = {}
		local function nearStorageItem(item)
			for _, v in StorageItems.ListEnabled do
				if item:find(v) then
					return v
				end
			end
		end
		local function refreshAdornee(v)
			local chest = v.Adornee:FindFirstChild('ChestFolderValue')
			chest = chest and chest.Value or nil
			if not chest then
				v.Enabled = false
				return
			end
			local chestitems = chest and chest:GetChildren() or {}
			for _, obj in v.Frame:GetChildren() do
				if obj:IsA('ImageLabel') and obj.Name ~= 'Blur' then
					obj:Destroy()
				end
			end
			v.Enabled = false
			local alreadygot = {}
			for _, item in chestitems do
				if not alreadygot[item.Name] and (table.find(StorageItems.ListEnabled, item.Name) or nearStorageItem(item.Name)) then
					alreadygot[item.Name] = true
					v.Enabled = true
					local blockimage = Instance.new('ImageLabel')
					blockimage.Size = UDim2.fromOffset(32, 32)
					blockimage.BackgroundTransparency = 1
					blockimage.Image = bedwars.getIcon({itemType = item.Name}, true)
					blockimage.Parent = v.Frame
				end
			end
			table.clear(chestitems)
		end
		local function removing(v)
			local billboard = self.Reference[v]
			if billboard then
				billboard:Destroy()
				self.Reference[v] = nil
			end
			local list = connections[v]
			if list then
				for _, connection in list do
					connection:Disconnect()
				end
				table.clear(list)
				connections[v] = nil
			end
		end
		local function clear()
			local references = table.clone(self.Reference)
			for v in references do
				removing(v)
			end
			table.clear(references)
		end
		local function added(v)
			local chest = v:WaitForChild('ChestFolderValue', 3)
			if not (chest and self.Enabled and v:HasTag('chest')) then return end
			if self.Reference[v] then
				removing(v)
			end
			chest = chest.Value
			if not chest then return end
			local billboard = Instance.new('BillboardGui')
			billboard.Parent = self.Folder
			billboard.Name = 'chest'
			billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
			billboard.Size = UDim2.fromOffset(36, 36)
			billboard.AlwaysOnTop = true
			billboard.ClipsDescendants = false
			billboard.Adornee = v
			local blur = addBlur(billboard)
			if blur then blur.Visible = StorageBackground.Enabled end
			local frame = Instance.new('Frame')
			frame.Size = UDim2.fromScale(1, 1)
			frame.BackgroundColor3 = Color3.fromHSV(StorageColor.Hue, StorageColor.Sat, StorageColor.Value)
			frame.BackgroundTransparency = 1 - (StorageBackground.Enabled and StorageColor.Opacity or 0)
			frame.Parent = billboard
			local layout = Instance.new('UIListLayout')
			layout.FillDirection = Enum.FillDirection.Horizontal
			layout.Padding = UDim.new(0, 4)
			layout.VerticalAlignment = Enum.VerticalAlignment.Center
			layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
			local layoutConnection = layout:GetPropertyChangedSignal('AbsoluteContentSize'):Connect(function()
				billboard.Size = UDim2.fromOffset(math.max(layout.AbsoluteContentSize.X + 4, 36), 36)
			end)
			layout.Parent = frame
			local corner = Instance.new('UICorner')
			corner.CornerRadius = UDim.new(0, 4)
			corner.Parent = frame
			self.Reference[v] = billboard
			connections[v] = {
				layoutConnection,
				chest.ChildAdded:Connect(function(item)
					if table.find(StorageItems.ListEnabled, item.Name) or nearStorageItem(item.Name) then
						refreshAdornee(billboard)
					end
				end),
				chest.ChildRemoved:Connect(function(item)
					if table.find(StorageItems.ListEnabled, item.Name) or nearStorageItem(item.Name) then
						refreshAdornee(billboard)
					end
				end)
			}
			task.spawn(refreshAdornee, billboard)
		end
		self.Refresh = function()
			for _, v in self.Reference do
				task.spawn(refreshAdornee, v)
			end
		end
		self:Clean(collectionService:GetInstanceAddedSignal('chest'):Connect(added))
		self:Clean(collectionService:GetInstanceRemovedSignal('chest'):Connect(removing))
		self:Clean(clear)
		for _, v in collectionService:GetTagged('chest') do
			task.spawn(added, v)
		end
		self.Stop = function()
			table.clear(connections)
		end
	end
	Callbacks.StorageItems = function()
		if Storage.Refresh then Storage.Refresh() end
	end
	Callbacks.StorageBackground = function(callback)
		StorageColor.Object.Visible = callback and StorageESP.Enabled
		for _, v in Storage.Reference do
			v.Frame.BackgroundTransparency = 1 - (callback and StorageColor.Opacity or 0)
			if v.Blur then v.Blur.Visible = callback end
		end
	end
end)

-- ===== Render/TargetInfoInventory.lua =====
run(function()
	local TargetInfo = targetinfo
	local TargetInfoOverlay = vape.Categories["Target Info"]
	if not (TargetInfo and TargetInfo.Object and TargetInfo.TargetChanged and TargetInfoOverlay and TargetInfoOverlay.CreateToggle) then
	    return
	end
	local ShowInventory
	local Card: Frame = TargetInfo.Object
	local Row: Frame?
	local Tiles: {Frame} = {}
	local Lifted: {[Frame]: boolean} = {}
	local TileSize: number = 30
	local TilePadding: number = 5
	local Columns: number = 7
	local Lift: number = 4
	local Looping: boolean = false
	
	local function CreateRow()
	    Row = Instance.new("Frame")
	    Row.Name = "Inventory"
	    Row.BackgroundTransparency = 1
	    Row.Position = UDim2.new(0, 0, 1, TilePadding + Lift)
	    Row.Size = UDim2.fromScale(1, 0)
	    Row.Visible = false
	    Row.Parent = Card
	    local Grid: UIGridLayout = Instance.new("UIGridLayout")
	    Grid.CellPadding = UDim2.fromOffset(TilePadding, TilePadding)
	    Grid.CellSize = UDim2.fromOffset(TileSize, TileSize)
	    Grid.SortOrder = Enum.SortOrder.LayoutOrder
	    Grid.Parent = Row
	end
	
	local function CreateTile(Index: number): Frame
	    local Cell: Frame = Instance.new("Frame")
	    Cell.Name = `Slot{Index}`
	    Cell.BackgroundTransparency = 1
	    Cell.LayoutOrder = Index
	    Cell.Parent = Row
	    local Tile: Frame = Instance.new("Frame")
	    Tile.Name = "Tile"
	    Tile.BackgroundColor3 = Color3.fromRGB(29, 36, 46)
	    Tile.BorderMode = Enum.BorderMode.Inset
	    Tile.BorderSizePixel = 1
	    Tile.Size = UDim2.fromScale(1, 1)
	    Tile.Parent = Cell
	    local Icon: ImageLabel = Instance.new("ImageLabel")
	    Icon.Name = "Icon"
	    Icon.AnchorPoint = Vector2.new(0.5, 0)
	    Icon.BackgroundTransparency = 1
	    Icon.Position = UDim2.fromScale(0.5, 0.15)
	    Icon.Size = UDim2.fromScale(0.8, 0.8)
	    Icon.Parent = Tile
	    local Amount: TextLabel = Instance.new("TextLabel")
	    Amount.Name = "Amount"
	    Amount.AnchorPoint = Vector2.new(1, 1)
	    Amount.BackgroundTransparency = 1
	    Amount.FontFace = Font.fromName("RobotoMono", Enum.FontWeight.Bold)
	    Amount.Position = UDim2.new(1, -2, 1, 0)
	    Amount.Size = UDim2.new(1, -2, 0, 12)
	    Amount.Text = ""
	    Amount.TextColor3 = Color3.new(1, 1, 1)
	    Amount.TextSize = 11
	    Amount.TextStrokeTransparency = 0.5
	    Amount.TextXAlignment = Enum.TextXAlignment.Right
	    Amount.ZIndex = 2
	    Amount.Parent = Tile
	    Tiles[Index] = Cell
	
	    return Cell
	end
	
	local function SetTile(Cell: Frame, Item, Held: boolean)
	    local Tile: Frame = Cell.Tile
	    Cell.Visible = true
	    Tile.Icon.Image = bedwars.getIcon(Item, true)
	    Tile.Amount.Text = (Item.amount or 1) > 1 and tostring(Item.amount) or ""
	    Tile.BackgroundTransparency = Held and 0.2 or 0.4
	    Tile.BorderColor3 = Held and Color3.new(1, 1, 1) or Color3.fromRGB(114, 126, 172)
	
	    if Lifted[Cell] ~= Held then
	        Lifted[Cell] = Held
	        tween:Tween(Tile, TweenInfo.new(0.12), {
	            Position = UDim2.fromOffset(0, Held and -Lift or 0)
	        })
	    end
	end
	
	local function GetItems(Inventory)
	    local Worn: {[Instance]: boolean} = {}
	    local Items = {}
	
	    for _, v: any in Inventory.armor do
	        if type(v) == "table" and v.tool then
	            Worn[v.tool] = true
	        end
	    end
	
	    for _, v: any in Inventory.items do
	        if v.tool and not Worn[v.tool] then
	            table.insert(Items, v)
	        end
	    end
	
	    table.sort(Items, function(First, Second): boolean
	        local FirstTime: number = First.addedToBackpackTime or 0
	        local SecondTime: number = Second.addedToBackpackTime or 0
	        if FirstTime ~= SecondTime then
	            return FirstTime < SecondTime
	        end
	
	        return First.itemType < Second.itemType
	    end)
	
	    return Items
	end
	
	local function Refresh(Target)
	    if not Row or not Card.Visible or not TargetInfoOverlay.Object.Visible then
	        return
	    end
	
	    local Player: Player? = Target and Target.Player or nil
	    local Inventory = Player and bedwars.getInventory and bedwars.getInventory(Player) or nil
	    local Items = Inventory and GetItems(Inventory) or {}
	    local Hand = Inventory and Inventory.hand or nil
	
	    for i: number, v: any in Items do
	        SetTile(Tiles[i] or CreateTile(i), v, Hand ~= nil and v.tool == Hand.tool)
	    end
	
	    for i: number = #Items + 1, #Tiles do
	        Tiles[i].Visible = false
	    end
	
	    local Rows: number = math.ceil(#Items / Columns)
	    Row.Size = UDim2.new(1, 0, 0, math.max(Rows * (TileSize + TilePadding) - TilePadding, 0))
	    Row.Visible = #Items > 0
	end
	
	local function Clear()
	    if Row then
	        Row:Destroy()
	        Row = nil
	    end
	
	    table.clear(Tiles)
	    table.clear(Lifted)
	end
	
	ShowInventory = TargetInfoOverlay:CreateToggle({
	    Name = "Show Inventory",
	    Function = function(Callback: boolean)
	        if not Callback then
	            Clear()
	            return
	        end
	
	        if not Row then
	            CreateRow()
	        end
	
	        if Looping then
	            return
	        end
	        Looping = true
	
	        task.spawn(function()
	            repeat
	                Refresh(TargetInfo.LastTarget)
	                task.wait(0.1)
	            until not ShowInventory.Enabled or vape.Loaded == nil
	
	            Looping = false
	        end)
	    end,
	    Tooltip = 'Shows the target\'s inventory under the card'
	})
	vape:Clean(TargetInfo.TargetChanged:Connect(function(Target)
	    Refresh(Target)
	end))
end)

-- ===== Render/TeamUpgrades.lua =====
run(function()
	local GetFontBounds = getfontsize
	local Camera = gameCamera
	local CollectionService = collectionService
	local LocalPlayer = lplr
	local RunService = runService
	local TeamUpgrades
	local Session = nil
	local OwnTeam
	local BedUpgrades
	local Color
	local Transparency
	local Scale
	local Reference = {}
	local Folder: Folder = Instance.new("Folder")
	if vape.ThreadFix then
		setthreadidentity(8)
	end
	Folder.Parent = vape.gui

	local Numerals: {string} = {"I", "II", "III", "IV", "V"}

	local function GetAnchor(Object: Instance)
		return Object:IsA("Model") and (Object.PrimaryPart or Object:FindFirstChildWhichIsA("BasePart")) or Object
	end

	local function GetText(Team: string)
		local State = bedwars.Store:getState().Bedwars
		local Upgrades = State.teamUpgrades[Team] or {}
		local Bought: {string} = {}

		for UpgradeId: string, v: any in bedwars.TeamUpgradeMeta do
			local Tier: number? = Upgrades[UpgradeId]
			if Tier and Tier > 0 then
				table.insert(Bought, `{v.name} {Numerals[Tier] or Tier}`)
			end
		end

		table.sort(Bought)

		if BedUpgrades.Enabled then
			local Bed = State.bedTeamUpgrades[Team] or {}
			if Bed.bed_shield then
				table.insert(Bought, "Bed Shield")
			end
			if Bed.bed_alarm then
				table.insert(Bought, "Bed Alarm")
			end
		end

		return `Team {Team} | {#Bought > 0 and table.concat(Bought, ", ") or "No upgrades"}`
	end

	local function Added(Object: Instance, Tag: string)
		local Team: string? = Tag:match("^(%d+)_TeamOreGenerator")
		local Anchor: Instance? = Team and GetAnchor(Object)
		if not Anchor then return end
		if not OwnTeam.Enabled and Team == LocalPlayer:GetAttribute("Team") then return end

		local NameTag: TextLabel = Instance.new("TextLabel")
		NameTag.Name = `Team{Team}`
		NameTag.Text = GetText(Team)
		NameTag.TextSize = 14 * Scale.Value
		NameTag.Font = Enum.Font.Arial
		local Size: Vector2 = GetFontBounds(NameTag.Text, NameTag.TextSize, NameTag.FontFace)
		NameTag.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)
		NameTag.AnchorPoint = Vector2.new(0.5, 1)
		NameTag.BackgroundColor3 = Color3.new()
		NameTag.BackgroundTransparency = Transparency.Value
		NameTag.BorderSizePixel = 0
		NameTag.Visible = false
		NameTag.TextColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
		NameTag.Parent = Folder
		Reference[Anchor] = {Label = NameTag, Team = Team}
	end

	local function Refresh()
		for _, v: {Label: TextLabel, Team: string} in Reference do
			v.Label.Text = GetText(v.Team)
			local Size: Vector2 = GetFontBounds(v.Label.Text, v.Label.TextSize, v.Label.FontFace)
			v.Label.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)
		end
	end

	TeamUpgrades = vape.Categories.Render:CreateModule({
		Name = "TeamUpgrades",
		Function = function(Callback: boolean)
			if Callback then
				local Current = {}
				Session = Current
				for _, Tag: string in CollectionService:GetAllTags() do
					if Tag:match("^%d+_TeamOreGenerator$") then
						for _, v: Instance in CollectionService:GetTagged(Tag) do
							Added(v, Tag)
						end
						TeamUpgrades:Clean(CollectionService:GetInstanceAddedSignal(Tag):Connect(function(Object: Instance)
							Added(Object, Tag)
						end))
					end
				end

				TeamUpgrades:Clean(RunService.PreRender:Connect(function()
					for Anchor: BasePart, v: {Label: TextLabel, Team: string} in Reference do
						if not Anchor.Parent then
							v.Label:Destroy()
							Reference[Anchor] = nil
							continue
						end

						local ScreenPos, Visible = Camera:WorldToViewportPoint(Anchor.Position + Vector3.new(0, 4, 0))
						v.Label.Visible = Visible
						if not Visible then continue end
						v.Label.Position = UDim2.fromOffset(ScreenPos.X, ScreenPos.Y)
					end
				end))

				repeat
					Refresh()
					task.wait(0.5)
				until not TeamUpgrades.Enabled or Session ~= Current
			else
				for Anchor: Instance, v: {Label: TextLabel, Team: string} in Reference do
					v.Label:Destroy()
					Reference[Anchor] = nil
				end
			end
		end,
		Tooltip = 'Shows each team\'s upgrades over their generator'
	})

	OwnTeam = TeamUpgrades:CreateToggle({
		Name = "Show own team",
		Function = function()
			if TeamUpgrades.Enabled then
				TeamUpgrades:Toggle()
				TeamUpgrades:Toggle()
			end
		end
	})
	BedUpgrades = TeamUpgrades:CreateToggle({
		Name = "Bed upgrades",
		Default = true,
		Function = function()
			if TeamUpgrades.Enabled then
				Refresh()
			end
		end,
		Tooltip = 'Shows bed shields and alarms'
	})
	Color = TeamUpgrades:CreateColorSlider({
		Name = "Text Color",
		Function = function(Hue: number, Sat: number, Val: number)
			for _, v: {Label: TextLabel, Team: string} in Reference do
				v.Label.TextColor3 = Color3.fromHSV(Hue, Sat, Val)
			end
		end,
		DefaultSat = 0,
		DefaultValue = 1
	})
	Transparency = TeamUpgrades:CreateSlider({
		Name = "Transparency",
		Min = 0,
		Max = 1,
		Decimal = 100,
		Default = 0.5,
		Function = function(Value: number)
			for _, v: {Label: TextLabel, Team: string} in Reference do
				v.Label.BackgroundTransparency = Value
			end
		end
	})
	Scale = TeamUpgrades:CreateSlider({
		Name = "Scale",
		Min = 0.1,
		Max = 1.5,
		Decimal = 10,
		Default = 1,
		Function = function(Value: number)
			for _, v: {Label: TextLabel, Team: string} in Reference do
				v.Label.TextSize = 14 * Value
				local Size: Vector2 = GetFontBounds(v.Label.Text, v.Label.TextSize, v.Label.FontFace)
				v.Label.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)
			end
		end
	})
end)

-- ===== Render/Trajectories.lua =====
run(function()
	local Trajectories
	local LineColor
	local MaxLength
	local Landing
	local HideGame
	local HighlightTarget
	local latest
	local holder, beam, a0, a1, marker, highlight
	local rayParams = RaycastParams.new()
	rayParams.FilterType = Enum.RaycastFilterType.Exclude
	rayParams.RespectCanCollide = true
	local entityParams = RaycastParams.new()
	entityParams.FilterType = Enum.RaycastFilterType.Include
	entityParams.RespectCanCollide = false
	local entityModels = {}
	local entityCount = 0
	local filterAt, filterChar, entityAt = 0, nil, 0
	local SEGMENT = 5
	local MAX_STEPS = 240
	local NEAR = 8
	local REUSE = 0.25
	local roots, trace = {}, {Roots = {}}
	local STALE = 0.25
	local PLAYER_COLOR = Color3.fromRGB(255, 60, 60)
	local UP = Vector3.new(0, 1, 0)

	local function offsets()
		local bow = bedwars.BowConstantsTable
		return Vector3.new(tonumber(bow and bow.RelX) or 0.8, tonumber(bow and bow.RelY) or -0.6, tonumber(bow and bow.RelZ) or 0)
	end

	local function refreshFilter()
		local now = os.clock()
		if now - filterAt < 1 and filterChar == lplr.Character then return end
		filterAt, filterChar = now, lplr.Character
		local list = {gameCamera}
		if lplr.Character then table.insert(list, lplr.Character) end
		local controller = bedwars.ProjectileController
		local folder = controller and rawget(controller, 'projectileTargetingFolder')
		if folder then table.insert(list, folder) end
		for _, v in collectionService:GetTagged('DontBlockProjectileRaycast') do
			table.insert(list, v)
		end
		rayParams.FilterDescendantsInstances = list
	end

	local function refreshEntities()
		local now = os.clock()
		if now - entityAt < 0.25 then return end
		entityAt = now
		table.clear(entityModels)
		local list = {}
		for _, ent in entitylib.List do
			local character = ent.Character
			if character and character ~= lplr.Character and character.Parent then
				entityModels[character] = ent
				table.insert(list, character)
			end
		end
		entityCount = #list
		entityParams.FilterDescendantsInstances = list
	end

	local function entityOf(instance)
		local model = instance and instance:FindFirstAncestorOfClass('Model')
		for _ = 1, 4 do
			if not model then return nil end
			if entityModels[model] then return model end
			model = model:FindFirstAncestorOfClass('Model')
		end
		return nil
	end

	local function lifetimeOf(handler)
		local ok, meta = pcall(function()
			return handler:getProjectileMeta()
		end)
		if not ok or type(meta) ~= 'table' then
			meta = bedwars.ProjectileMeta[handler.projectile] or {}
		end
		local life = tonumber(meta.lifetimeSec)
		if type(meta.getProjectileOverridesFunction) == 'function' then
			local good, over = pcall(meta.getProjectileOverridesFunction, lplr)
			if good and type(over) == 'table' and tonumber(over.lifetimeOverride) then
				life = tonumber(over.lifetimeOverride)
			end
		end
		return life or 10
	end

	local function nearEntity(roots, count, last, point, length)
		local mid = (last + point) * 0.5
		local reach = length * 0.5 + NEAR
		for i = 1, count do
			if (roots[i] - mid).Magnitude <= reach then
				return true
			end
		end
		return false
	end

	local function simulate(origin, velocity, gravity, lifetime, roots, count)
		local last, travelled, t = origin, 0, 0
		local step = math.clamp(SEGMENT / math.max(velocity.Magnitude, 1), 1 / 240, 1 / 15)
		for _ = 1, MAX_STEPS do
			if t >= lifetime then break end
			t = math.min(t + step, lifetime)
			local point = Vector3.new(origin.X + velocity.X * t, origin.Y + velocity.Y * t - 0.5 * gravity * t * t, origin.Z + velocity.Z * t)
			local segment = point - last
			local result = workspace:Raycast(last, segment, rayParams)
			if count > 0 and nearEntity(roots, count, last, point, segment.Magnitude) then
				local hit = workspace:Raycast(last, segment, entityParams)
				if hit and (not result or (hit.Position - last).Magnitude < (result.Position - last).Magnitude) then
					result = hit
				end
			end
			if result then
				local along = (result.Position - last).Magnitude / math.max(segment.Magnitude, 1e-4)
				return t - step * (1 - along), result
			end
			travelled += segment.Magnitude
			if travelled >= MaxLength.Value then
				return t, nil
			end
			last = point
		end
		return t, nil
	end

	local function setEndpoint(attachment, position, direction)
		local axis = direction.Magnitude <= 0.001 and Vector3.new(1, 0, 0) or direction.Unit
		local side = axis:Cross(math.abs(axis.Y) > 0.99 and Vector3.new(0, 0, 1) or UP).Unit
		attachment.WorldCFrame = CFrame.fromMatrix(position, axis, side:Cross(axis), side)
	end

	local function draw(start, middle, finish)
		local control = middle * 2 - (start + finish) * 0.5
		local c0 = control * (2 / 3) + start * (1 / 3)
		local c1 = control * (2 / 3) + finish * (1 / 3)
		setEndpoint(a0, start, c0 - start)
		setEndpoint(a1, finish, finish - c1)
		beam.CurveSize0 = (c0 - start).Magnitude
		beam.CurveSize1 = (c1 - finish).Magnitude
	end

	local function hide()
		if beam and beam.Enabled then beam.Enabled = false end
		if marker and marker.Transparency ~= 1 then marker.Transparency = 1 end
		if highlight and highlight.Enabled then highlight.Enabled = false end
		trace.At, trace.Result = nil, nil
	end

	local function hiding()
		return Trajectories.Enabled and HideGame.Enabled
	end

	local function hideGameLine()
		local ok, mod = pcall(function()
			return require(lplr.PlayerScripts.TS.controllers.global.combat.projectile['projectile-preview-beam'])
		end)
		local class = ok and type(mod) == 'table' and mod.ProjectilePreviewBeam
		if type(class) == 'table' and type(class.update) == 'function' then
			local original = class.update
			local wrapper = function(self, ...)
				local a, b = original(self, ...)
				if hiding() and self.beam then
					self.beam.Enabled = false
				end
				return a, b
			end
			class.update = wrapper
			Trajectories:Clean(function()
				if class.update == wrapper then
					class.update = original
				end
			end)
		end
		local controller = bedwars.ProjectileController
		if controller and type(controller.showHitIndicator) == 'function' then
			local own = rawget(controller, 'showHitIndicator')
			local original = controller.showHitIndicator
			local wrapper = function(self, ...)
				if hiding() then
					local part = rawget(self, 'hitIndicatorPart')
					if part and part.Transparency ~= 1 then part.Transparency = 1 end
					return
				end
				return original(self, ...)
			end
			controller.showHitIndicator = wrapper
			Trajectories:Clean(function()
				if rawget(controller, 'showHitIndicator') == wrapper then
					controller.showHitIndicator = own
				end
			end)
		end
	end

	local function build()
		holder = workspace.Terrain
		a0 = Instance.new('Attachment')
		a0.Name = 'TrajectoryStart'
		a0.Parent = holder
		a1 = Instance.new('Attachment')
		a1.Name = 'TrajectoryEnd'
		a1.Parent = holder
		beam = Instance.new('Beam')
		beam.Name = 'Trajectory'
		beam.Attachment0, beam.Attachment1 = a0, a1
		beam.Segments = 120
		beam.Width0, beam.Width1 = 0.1, 0.1
		beam.FaceCamera = true
		beam.LightEmission = 1
		beam.Enabled = false
		beam.Parent = holder
		marker = Instance.new('Part')
		marker.Name = 'TrajectoryLanding'
		marker.Shape = Enum.PartType.Ball
		marker.Size = Vector3.new(1, 1, 1)
		marker.Anchored, marker.CanCollide, marker.CanQuery, marker.CanTouch, marker.CastShadow = true, false, false, false, false
		marker.Material = Enum.Material.Neon
		marker.Transparency = 1
		marker.Parent = gameCamera
		highlight = Instance.new('Highlight')
		highlight.Name = 'TrajectoryTarget'
		highlight.FillColor = PLAYER_COLOR
		highlight.FillTransparency = 0.55
		highlight.OutlineColor = Color3.new(1, 1, 1)
		highlight.OutlineTransparency = 0
		highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
		highlight.Enabled = false
		highlight.Parent = gameCamera
		filterAt, entityAt = 0, 0
	end

	local function teardown()
		for _, v in {beam, a0, a1, marker, highlight} do
			if v then v:Destroy() end
		end
		beam, a0, a1, marker, highlight, holder = nil, nil, nil, nil, nil, nil
		latest = nil
		trace.At, trace.Result = nil, nil
		table.clear(roots)
		table.clear(trace.Roots)
		table.clear(entityModels)
		entityCount = 0
	end

	local lastColour, lastOpacity
	local function update()
		local controller = bedwars.ProjectileController
		if not (latest and entitylib.isAlive and controller and controller.isTargeting) or os.clock() - latest.At > STALE then
			return hide()
		end
		local origin, velocity, gravity = latest.From, latest.Velocity, latest.Gravity
		if velocity.Magnitude < 0.01 then return hide() end
		refreshFilter()
		refreshEntities()
		local count = 0
		for _, ent in entityModels do
			local root = ent.RootPart
			if root and root.Parent then
				count += 1
				roots[count] = root.Position
			end
		end
		local t1, result
		local now = os.clock()
		local same = trace.At and now - trace.At < REUSE and trace.Count == count and trace.Gravity == gravity
			and trace.Length == MaxLength.Value and trace.Life == latest.Life
			and (trace.Origin - origin).Magnitude < 0.25 and (trace.Velocity - velocity).Magnitude < velocity.Magnitude * 0.002
		if same then
			for i = 1, count do
				if (trace.Roots[i] - roots[i]).Magnitude > 0.05 then
					same = false
					break
				end
			end
		end
		if same then
			t1, result = trace.T, trace.Result
		else
			t1, result = simulate(origin, velocity, gravity, latest.Life, roots, count)
			trace.At, trace.Count, trace.Gravity, trace.Length, trace.Life = now, count, gravity, MaxLength.Value, latest.Life
			trace.Origin, trace.Velocity, trace.T, trace.Result = origin, velocity, t1, result
			for i = 1, count do
				trace.Roots[i] = roots[i]
			end
		end
		if t1 <= 0.01 then return hide() end
		local function at(t)
			return Vector3.new(origin.X + velocity.X * t, origin.Y + velocity.Y * t - 0.5 * gravity * t * t, origin.Z + velocity.Z * t)
		end
		local finish = result and result.Position or at(t1)
		local shift = (CFrame.lookAt(origin, origin + velocity) * CFrame.new(offsets())).Position - origin
		draw(origin + shift, at(t1 / 2) + shift * 0.5, finish)
		local opacity = LineColor.Opacity or 1
		if lastColour ~= LineColor.Hue + LineColor.Sat * 2 + LineColor.Value * 4 or lastOpacity ~= opacity then
			lastColour, lastOpacity = LineColor.Hue + LineColor.Sat * 2 + LineColor.Value * 4, opacity
			beam.Color = ColorSequence.new(Color3.fromHSV(LineColor.Hue, LineColor.Sat, LineColor.Value))
			beam.Transparency = NumberSequence.new(1 - math.clamp(opacity, 0.05, 1))
		end
		if not beam.Enabled then beam.Enabled = true end
		local target = result and entityOf(result.Instance)
		if HighlightTarget.Enabled and target then
			if highlight.Adornee ~= target then highlight.Adornee = target end
			if not highlight.Enabled then highlight.Enabled = true end
		elseif highlight.Enabled then
			highlight.Enabled = false
		end
		if Landing.Enabled and result then
			marker.Color = target and PLAYER_COLOR or Color3.fromHSV(LineColor.Hue, LineColor.Sat, LineColor.Value)
			marker.CFrame = CFrame.new(result.Position)
			if marker.Transparency ~= 0.25 then marker.Transparency = 0.25 end
		elseif marker.Transparency ~= 1 then
			marker.Transparency = 1
		end
	end

	Trajectories = vape.Categories.Render:CreateModule({
		Name = 'Trajectories',
		Function = function(callback)
			if callback then
				build()
				hideGameLine()
				Trajectories:Clean(bedwars.ProjectileLaunchHook:Add('Trajectories', 1, function(nextLaunch, self, handler, preview, ...)
					local result = nextLaunch(self, handler, preview, ...)
					if preview and type(result) == 'table' and typeof(result.positionFrom) == 'Vector3' and typeof(result.initialVelocity) == 'Vector3' then
						latest = latest or {}
						latest.From = result.positionFrom
						latest.Velocity = result.initialVelocity
						latest.Gravity = tonumber(result.gravitationalAcceleration) or 196.2
						if latest.Handler ~= handler then
							latest.Handler = handler
							latest.Life = lifetimeOf(handler)
						end
						latest.At = os.clock()
					end
					return result
				end))
				runService:BindToRenderStep('AetherTrajectories', Enum.RenderPriority.Camera.Value + 2, update)
				Trajectories:Clean(function()
					runService:UnbindFromRenderStep('AetherTrajectories')
				end)
				Trajectories:Clean(teardown)
			end
		end,
		Tooltip = 'Shows the path of your shot and where it lands'
	})
	LineColor = Trajectories:CreateColorSlider({
		Name = 'Colour',
		DefaultValue = 1,
		DefaultSat = 0,
		DefaultOpacity = 0.85
	})
	MaxLength = Trajectories:CreateSlider({
		Name = 'Max length',
		Min = 20,
		Max = 1000,
		Default = 400,
		Suffix = 'studs'
	})
	Landing = Trajectories:CreateToggle({
		Name = 'Landing marker',
		Default = true,
		Tooltip = 'Marks where the shot lands'
	})
	HighlightTarget = Trajectories:CreateToggle({
		Name = 'Highlight target',
		Default = true,
		Tooltip = 'Highlights the player or mob the shot will hit'
	})
	HideGame = Trajectories:CreateToggle({
		Name = 'Hide game line',
		Default = true,
		Tooltip = 'Hides the game\'s aim line and hit marker'
	})
end)

-- ===== Render/TrapESP.lua =====
run(function()
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui

	local function createSection()
		local section = {
			Enabled = false,
			Connections = {},
			Reference = {},
			Folder = Instance.new('Folder')
		}
		section.Folder.Parent = Folder
		function section:Clean(item)
			if type(item) == 'function' then
				table.insert(self.Connections, {Disconnect = item})
			elseif item then
				table.insert(self.Connections, item)
			end
		end
		function section:Clear()
			for _, connection in self.Connections do
				pcall(function() connection:Disconnect() end)
			end
			table.clear(self.Connections)
			if self.Stop then self.Stop(self) end
			for _, instance in self.Reference do
				pcall(function() instance:Destroy() end)
			end
			table.clear(self.Reference)
			self.Folder:ClearAllChildren()
		end
		function section:Set(callback)
			if callback == self.Enabled then return end
			self.Enabled = callback
			self:Clear()
			if callback and self.Start then self.Start(self) end
		end
		return section
	end
	local Traps = createSection()
	local TrapBackground, TrapColor
	local Callbacks = {}
	local TrapESP = vape.Categories.Render:CreateModule({
		Name = 'TrapESP',
		Function = function(callback)
			Traps:Set(callback)
			for _, setting in {TrapBackground,
				TrapColor} do
				if setting and setting.Object then
					setting.Object.Visible = callback and (setting ~= TrapColor or TrapBackground.Enabled)
				end
			end
		end,
		Tooltip = 'Shows enemy traps through walls'
	})
	TrapBackground = TrapESP:CreateToggle({Visible = false, Function = function(...) if Callbacks.TrapBackground then return Callbacks.TrapBackground(...) end end, Name = 'Trap background', Default = true})
	TrapColor = TrapESP:CreateColorSlider({
		Visible = false,
		Name = 'Trap background colour',
		DefaultValue = 0,
		DefaultOpacity = 0.5,
		Darker = true,
		Function = function(hue, sat, val, opacity)
			for _, v in Traps.Reference do
				v.Frame.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
				v.Frame.BackgroundTransparency = 1 - opacity
			end
		end
	})

	Traps.Start = function(self)
		local function added(v)
			local billboard = Instance.new('BillboardGui')
			billboard.Parent = self.Folder
			billboard.Name = 'trap'
			billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
			billboard.Size = UDim2.fromOffset(36, 36)
			billboard.AlwaysOnTop = true
			billboard.ClipsDescendants = false
			billboard.Adornee = v
			local blur = addBlur(billboard)
			if blur then blur.Visible = TrapBackground.Enabled end
			local frame = Instance.new('Frame')
			frame.Size = UDim2.fromScale(1, 1)
			frame.BackgroundColor3 = Color3.fromHSV(TrapColor.Hue, TrapColor.Sat, TrapColor.Value)
			frame.BackgroundTransparency = 1 - (TrapBackground.Enabled and TrapColor.Opacity or 0)
			frame.Parent = billboard
			local image = Instance.new('ImageLabel')
			image.Size = UDim2.fromOffset(32, 32)
			image.BackgroundTransparency = 1
			image.Image = bedwars.getIcon({itemType = 'snap_trap'}, true)
			image.Parent = frame
			local layout = Instance.new('UIListLayout')
			layout.FillDirection = Enum.FillDirection.Horizontal
			layout.Padding = UDim.new(0, 4)
			layout.VerticalAlignment = Enum.VerticalAlignment.Center
			layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
			layout:GetPropertyChangedSignal('AbsoluteContentSize'):Connect(function()
				billboard.Size = UDim2.fromOffset(math.max(layout.AbsoluteContentSize.X + 4, 36), 36)
			end)
			layout.Parent = frame
			local corner = Instance.new('UICorner')
			corner.CornerRadius = UDim.new(0, 4)
			corner.Parent = frame
			self.Reference[v] = billboard
		end
		self:Clean(collectionService:GetInstanceAddedSignal('snap_trap'):Connect(added))
		self:Clean(collectionService:GetInstanceRemovedSignal('snap_trap'):Connect(function(v)
			if self.Reference[v] then
				self.Reference[v]:Destroy()
				self.Reference[v] = nil
			end
		end))
		for _, v in collectionService:GetTagged('snap_trap') do
			added(v)
		end
	end
	Callbacks.TrapBackground = function(callback)
		TrapColor.Object.Visible = callback and TrapESP.Enabled
		for _, v in Traps.Reference do
			v.Frame.BackgroundTransparency = 1 - (callback and TrapColor.Opacity or 0)
			if v.Blur then v.Blur.Visible = callback end
		end
	end
end)

-- ===== Render/WhiteHits.lua =====
run(function()
	local WhiteHits
	local Color
	local Size
	local Lifetime
	local active = {}

	local function spawnHit(pos)
		local p = Instance.new('Part')
		p.Name = 'WhiteHit'
		p.Anchored = true
		p.CanCollide = false
		p.Material = Enum.Material.Neon
		p.Color = Color3.new(1, 1, 1)
		p.Size = Vector3.new(Size.Value, Size.Value, Size.Value)
		p.CFrame = CFrame.new(pos)
		p.Parent = workspace
		table.insert(active, p)
		task.delay(Lifetime.Value, function()
			p:Destroy()
		end)
	end

	WhiteHits = vape.Categories.Render:CreateModule({
		Name = 'WhiteHitMarker',
		Function = function(callback)
			if callback then
				WhiteHits:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(data)
					if type(data) ~= 'table' or not data.entityInstance or data.fromEntity ~= lplr.Character then return end
					local character = data.entityInstance
					local root = character:FindFirstChild('HumanoidRootPart') or character.PrimaryPart or character:FindFirstChildWhichIsA('BasePart')
					if root then spawnHit(root.Position) end
				end))
			else
				for _, p in active do pcall(function() p:Destroy() end) end
				table.clear(active)
			end
		end,
		Tooltip = 'Shows a white marker when your hit registers'
	})
	Size = WhiteHits:CreateSlider({Name = 'Size', Min = 0.2, Max = 3, Default = 0.8, Decimal = 10})
	Lifetime = WhiteHits:CreateSlider({Name = 'Lifetime', Min = 0.05, Max = 1, Default = 0.25, Decimal = 100})
end)

-- ===== Utility/AntiEffect.lua =====
run(function()
	local AntiEffect
	local Dizzy
	local Fear
	local Vignettes
	local oldvignettes
	
	AntiEffect = vape.Categories.Utility:CreateModule({
		Name = 'AntiEffect',
		Function = function(callback)
			if callback then
				if Dizzy.Enabled then
					runService:UnbindFromRenderStep('dizzy-status')
				end
	
				if Fear.Enabled then
					runService:UnbindFromRenderStep('werewolf-fear-status')
				end
	
				if Vignettes.Enabled then
					oldvignettes = bedwars.VignetteController.enableOnScreenEffects
					bedwars.VignetteController.enableOnScreenEffects = false
					bedwars.VignetteController:destroyAllVignettes()
				end
	
				local added = bedwars.SyncEvents.StatusEffectAdded:setPriority(1000):connect(function(event)
					if event.entityInstance ~= lplr.Character then return end
	
					if Dizzy.Enabled and event.statusEffect == bedwars.StatusEffectMeta.DIZZY then
						runService:UnbindFromRenderStep('dizzy-status')
					end
	
					if Fear.Enabled and event.statusEffect == bedwars.StatusEffectMeta.WEREWOLF_FEAR then
						runService:UnbindFromRenderStep('werewolf-fear-status')
					end
				end)
				AntiEffect:Clean(function()
					added:Destroy()
				end)
			else
				if oldvignettes ~= nil then
					bedwars.VignetteController.enableOnScreenEffects = oldvignettes
					oldvignettes = nil
				end
			end
		end,
		Tooltip = 'Removes debuff effects on your screen'
	})
	Dizzy = AntiEffect:CreateToggle({
		Name = 'Dizzy',
		Default = true,
		Tooltip = 'Stops the dizzy effect changing your walk direction'
	})
	Fear = AntiEffect:CreateToggle({
		Name = 'Werewolf fear',
		Default = true,
		Tooltip = 'Stops the werewolf tail walking you away from it'
	})
	Vignettes = AntiEffect:CreateToggle({
		Name = 'Vignettes',
		Function = function(callback)
			if AntiEffect.Enabled and callback then
				oldvignettes = bedwars.VignetteController.enableOnScreenEffects
				bedwars.VignetteController.enableOnScreenEffects = false
				bedwars.VignetteController:destroyAllVignettes()
			elseif AntiEffect.Enabled and oldvignettes ~= nil then
				bedwars.VignetteController.enableOnScreenEffects = oldvignettes
				oldvignettes = nil
			end
		end,
		Default = true,
		Tooltip = 'Removes coloured screen borders from effects'
	})
end)

-- ===== Utility/AntiLasso.lua =====
run(function()
    local AntiLasso
    local Chance
    local Check
    local currentConnections = {}
    local currentCharacter
    local activeLasso
    local ignoredLasso
    local lassoVersion = 0
    local returnFilter = RaycastParams.new()
    local returnOverlap = OverlapParams.new()

    returnFilter.FilterType = Enum.RaycastFilterType.Exclude
    returnFilter.RespectCanCollide = true
    returnFilter.IgnoreWater = true
    returnOverlap.FilterType = Enum.RaycastFilterType.Exclude
    returnOverlap.RespectCanCollide = true

    local function disconnectCharacter()
        for _, connection in currentConnections do
            connection:Disconnect()
        end
        table.clear(currentConnections)
        currentCharacter = nil
    end

    local function isFinite(value)
        return type(value) == 'number' and value == value and value > -math.huge and value < math.huge
    end

    local function isFiniteCFrame(value)
        if typeof(value) ~= 'CFrame' then return false end
        for _, component in {value:GetComponents()} do
            if not isFinite(component) then return false end
        end
        return true
    end

    
    
    
    
    local function isLassoPart(inst)
        if inst:IsA('RopeConstraint') then return true end
        local name = inst.Name:lower()
        return name:find('lasso', 1, true) ~= nil or name:find('rope', 1, true) ~= nil
    end

    local function getLassoObject(character)
        for _, descendant in character:GetDescendants() do
            if isLassoPart(descendant) then
                return descendant
            end
        end
    end

    local function hasClearance(character, root, position)
        returnOverlap.FilterDescendantsInstances = {character, gameCamera}
        for _, part in workspace:GetPartBoundsInBox(CFrame.new(position), root.Size * Vector3.new(0.9, 1, 0.9), returnOverlap) do
            local queryIgnored = bedwars.QueryUtil.isQueryIgnored
            if part.CanCollide and not (type(queryIgnored) == 'function' and queryIgnored(bedwars.QueryUtil, part)) then
                return false
            end
        end
        return true
    end

    local function getSafeReturnCFrame(event)
        local character, root, saved = event.character, event.root, event.cframe
        local humanoid = character:FindFirstChildOfClass('Humanoid')
        if not isFiniteCFrame(saved) or not root.Parent or not humanoid or humanoid.Health <= 0 then return end
        local position = saved.Position
        if position.Y <= workspace.FallenPartsDestroyHeight + 12 then return end

        returnFilter.FilterDescendantsInstances = {character, gameCamera}
        local ground = workspace:Raycast(position + Vector3.yAxis * 3, -Vector3.yAxis * 99, returnFilter)
        if ground and position.Y - ground.Position.Y >= 1 and hasClearance(character, root, position) then
            return saved
        end

        local offsets = {Vector3.zero}
        for radius = 3, 12, 3 do
            for _, direction in {
                Vector3.xAxis,
                -Vector3.xAxis,
                Vector3.zAxis,
                -Vector3.zAxis,
                Vector3.new(1, 0, 1).Unit,
                Vector3.new(1, 0, -1).Unit,
                Vector3.new(-1, 0, 1).Unit,
                Vector3.new(-1, 0, -1).Unit
            } do
                table.insert(offsets, direction * radius)
            end
        end

        local best, bestDistance
        for _, offset in offsets do
            local origin = position + offset + Vector3.yAxis * 12
            local result = workspace:Raycast(origin, -Vector3.yAxis * 72, returnFilter)
            if result and result.Instance.CanCollide then
                local candidate = Vector3.new(origin.X, result.Position.Y + humanoid.HipHeight + root.Size.Y / 2, origin.Z)
                local distance = (candidate - position).Magnitude
                if candidate.Y > workspace.FallenPartsDestroyHeight + 12 and hasClearance(character, root, candidate)
                    and (not bestDistance or distance < bestDistance)
                then
                    best, bestDistance = candidate, distance
                end
            end
        end
        return best and CFrame.new(best) * saved.Rotation or nil
    end

    local function clearLasso(event)
        if activeLasso ~= event then return end
        activeLasso = nil
        if event.root.Parent then
            event.root.Anchored = false
        end
    end

    local function returnPlayer(event, visualReleased)
        if activeLasso ~= event or event.returned or not AntiLasso.Enabled then return false end
        if collectionService:HasTag(event.character, 'LassoHooked') then return false end
        if not visualReleased and getLassoObject(event.character) then return false end
        local root = event.root
        local returnCFrame = getSafeReturnCFrame(event)
        if not returnCFrame or lplr.Character ~= event.character or not entitylib.isAlive or entitylib.character.RootPart ~= root then
            clearLasso(event)
            return true
        end
        event.returned = true
        root.Anchored = false
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        root.CFrame = returnCFrame
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        if activeLasso == event then
            activeLasso = nil
        end
        return true
    end

    local function waitForRelease(event)
        task.spawn(function()
            local visualReleasedAt
            while activeLasso == event and AntiLasso.Enabled and lplr.Character == event.character and event.root.Parent do
                local tagged = collectionService:HasTag(event.character, 'LassoHooked')
                local visual = getLassoObject(event.character)
                if not tagged and not visual then
                    returnPlayer(event)
                    return
                end
                if not tagged then
                    visualReleasedAt = visualReleasedAt or tick()
                    if tick() - visualReleasedAt >= 1 then
                        returnPlayer(event, true)
                        return
                    end
                else
                    visualReleasedAt = nil
                end
                task.wait(0.05)
            end
        end)
    end

    local function startLasso(character, nativeEvent)
        if not AntiLasso.Enabled or character ~= lplr.Character or ignoredLasso == character then return end
        if activeLasso and activeLasso.character == character then
            if not nativeEvent or not activeLasso.releaseSeen then return end
            clearLasso(activeLasso)
        end
        if Random.new(os.clock()):NextNumber(1, 100) > Chance.Value or Check.Enabled and not entitylib.EntityPosition({
            Range = 50,
            Part = 'RootPart',
            Players = true
        }) then
            if nativeEvent then ignoredLasso = character end
            return
        end
        local root = character:FindFirstChild('HumanoidRootPart') or character.PrimaryPart
        local humanoid = character:FindFirstChildOfClass('Humanoid')
        if not root or not humanoid or humanoid.Health <= 0 or not isFiniteCFrame(root.CFrame) then return end
        if activeLasso then clearLasso(activeLasso) end
        lassoVersion += 1
        local event = {
            cframe = root.CFrame,
            character = character,
            root = root,
            token = lassoVersion
        }
        activeLasso = event
        root.Anchored = true
        waitForRelease(event)
    end

    local function releaseLasso(character)
        if ignoredLasso == character then
            ignoredLasso = nil
            return
        end
        local event = activeLasso
        if not event or event.character ~= character then return end
        event.releaseSeen = true
        task.defer(function()
            local deadline = tick() + 1
            repeat
                if activeLasso ~= event or returnPlayer(event) then return end
                task.wait()
            until tick() >= deadline
            returnPlayer(event, true)
        end)
    end

    local function Added(character)
        local previousCharacter = currentCharacter
        disconnectCharacter()
        if previousCharacter ~= character then ignoredLasso = nil end
        if not AntiLasso.Enabled or not character or not character.Parent then return end
        if activeLasso then clearLasso(activeLasso) end
        currentCharacter = character
        
        
        
        
        table.insert(currentConnections, character.DescendantAdded:Connect(function(descendant)
            if isLassoPart(descendant) then
                startLasso(character)
            end
        end))
        table.insert(currentConnections, character.Destroying:Connect(function()
            if currentCharacter == character then
                disconnectCharacter()
            end
            if activeLasso and activeLasso.character == character then
                clearLasso(activeLasso)
            end
        end))
        local humanoid = character:FindFirstChildOfClass('Humanoid')
        if humanoid then
            table.insert(currentConnections, humanoid.Died:Connect(function()
                if activeLasso and activeLasso.character == character then
                    clearLasso(activeLasso)
                end
            end))
        end
        if collectionService:HasTag(character, 'LassoHooked') or getLassoObject(character) then
            startLasso(character, collectionService:HasTag(character, 'LassoHooked'))
        end
    end

    AntiLasso = vape.Categories.Utility:CreateModule({
        Name = 'AntiLasso',
        Function = function(callback)
            if callback then
                AntiLasso:Clean(collectionService:GetInstanceAddedSignal('LassoHooked'):Connect(function(character)
                    if character == lplr.Character then
                        startLasso(character, true)
                    end
                end))
                AntiLasso:Clean(collectionService:GetInstanceRemovedSignal('LassoHooked'):Connect(function(character)
                    if character == lplr.Character then
                        releaseLasso(character)
                    end
                end))
                AntiLasso:Clean(entitylib.Events.LocalAdded:Connect(function(ent)
                    task.defer(function()
                        if AntiLasso.Enabled and ent and ent.Character then
                            Added(ent.Character)
                        end
                    end)
                end))
                AntiLasso:Clean(lplr.OnTeleport:Connect(function()
                    if activeLasso then clearLasso(activeLasso) end
                    ignoredLasso = nil
                    disconnectCharacter()
                end))
                if entitylib.isAlive then
                    Added(lplr.Character)
                end
            else
                lassoVersion += 1
                ignoredLasso = nil
                disconnectCharacter()
                if activeLasso then clearLasso(activeLasso) end
            end
        end,
        Tooltip = 'Stops lassos pulling you'
    })

    Chance = AntiLasso:CreateSlider({
        Name = 'Chance',
        Min = 0,
        Max = 100,
        Default = 100,
        Suffix = '%'
    })
    Check = AntiLasso:CreateToggle({Name = 'Only when targeting'})
end)

-- ===== Utility/AntiSuffocate.lua =====
run(function()

	local util = vape.Libraries.bedwarsutil
	local AntiSuffocate
	local Mode
	local Height

	local offsets = {
		Vector3.new(0, 3, 0),
		Vector3.new(3, 0, 0),
		Vector3.new(-3, 0, 0),
		Vector3.new(0, 0, 3),
		Vector3.new(0, 0, -3),
		Vector3.new(0, -3, 0)
	}

	local function getEscape(position)
		for _, v in offsets do
			local target = position + v
			if not getPlacedBlock(target) and not getPlacedBlock(target + Vector3.new(0, 3, 0)) then
				return target
			end
		end
		return nil
	end

	AntiSuffocate = vape.Categories.Utility:CreateModule({
		Name = 'AntiSuffocate',
		Function = function(callback)
			if callback then
				repeat
					if entitylib.isAlive and store.matchState == 1 then
						local root = entitylib.character.RootPart
						local head = root.Position + Vector3.new(0, Height.Value, 0)
						local block = getPlacedBlock(head)
						if block then
							if Mode.Value == 'Break' then
								bedwars.breakBlock(block, true, true)
							else
								local escape = getEscape(roundPos(head))
								if escape then
									root.CFrame = CFrame.new(escape - Vector3.new(0, Height.Value, 0)) * (root.CFrame - root.Position)
									root.AssemblyLinearVelocity = Vector3.zero
								end
							end
						end
					end
					task.wait(0.1)
				until not AntiSuffocate.Enabled
			end
		end,
		Tooltip = 'Gets you out when you are stuck inside blocks'
	})

	Mode = AntiSuffocate:CreateDropdown({
		Name = 'Mode',
		List = {'TP', 'Break'},
		Tooltip = 'TP - moves you to the nearest open cell\nBreak - breaks the block you are stuck in'
	})
	Height = AntiSuffocate:CreateSlider({
		Name = 'Check height',
		Min = 0,
		Max = 4,
		Default = 1.5,
		Decimal = 10,
		Suffix = util.Studs,
		Tooltip = 'How high above you the check looks'
	})
end)

-- ===== Utility/AutoCollect.lua =====
run(function()
	local CollectionService = collectionService
	local Entity = entitylib
	local LocalPlayer = lplr
	local AutoCollect
	local Collectables
	local Range
	local Delay
	local Animation

	local Request = bedwars.Handler:Get("CollectCollectableEntity")
	local Cooldowns: {[Instance]: number} = {}

	AutoCollect = vape.Categories.Utility:CreateModule({
		Name = "AutoCollect",
		Function = function(Callback: boolean)
			if Callback then
				repeat
					if Entity.isAlive then
						local LocalPosition: Vector3 = Entity.character.RootPart.Position
						for _, v: string in Collectables.ListEnabled do
							for _, Collectable: Instance in CollectionService:GetTagged(v) do
								local Part = Collectable:IsA("Model") and Collectable.PrimaryPart or Collectable
								local Id = Collectable:GetAttribute("Id")
								if Part and Id and tick() > (Cooldowns[Collectable] or 0) and (LocalPosition - Part.Position).Magnitude <= Range.Value then
									if Animation.Enabled then
										bedwars.GameAnimationUtil:playAnimation(LocalPlayer.Character, bedwars.AnimationType.PUNCH)
										bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.FP_USE_ITEM)
									end

									Request:Fire("SendToServer", {
										id = Id,
										collectableName = Collectable.Name
									})
									Cooldowns[Collectable] = tick() + 1
								end
							end
						end
					end
					task.wait(Delay.Value)
				until not AutoCollect.Enabled
			else
				table.clear(Cooldowns)
			end
		end,
		Tooltip = 'Picks up nearby kit collectables'
	})

	Range = AutoCollect:CreateSlider({
		Name = "Range",
		Min = 1,
		Max = 20,
		Default = 11,
		Suffix = function(Val: number)
			return Val <= 1 and "stud" or "studs"
		end,
		Tooltip = 'How close something must be to collect it'
	})
	Delay = AutoCollect:CreateSlider({
		Name = "Delay",
		Min = 0.05,
		Max = 1,
		Default = 0.1,
		Decimal = 100,
		Suffix = "seconds"
	})
	Animation = AutoCollect:CreateToggle({
		Name = "Animation",
		Default = true,
		Tooltip = "Plays the pickup animation"
	})
	Collectables = AutoCollect:CreateTextList({
		Name = "Collectables",
		Default = {
			"alchemist_ingedients",
			"alchemy_crystal",
			"crystalheart_seed",
			"forest_environment_plant",
			"jailor_soul",
			"murder_coin",
			"shadow_coin",
			"soulvine_seed",
			"spirit_gardener_energy",
			"spirit_gardener_seeds",
			"tearbloom_seed"
		},
		Darker = true,
		Tooltip = 'Collectables to pick up'
	})
end)

-- ===== Utility/AutoEnchant.lua =====
run(function()

	local util = vape.Libraries.bedwarsutil
	local AutoEnchant
	local Wanted
	local Repair
	local Legit
	local Range
	local Delay

	local Research = bedwars.Handler:Get('ResearchEnchant')
	local Fix = bedwars.Handler:Get('RepairEnchantTable')
	local learned

	local function findRepairPrompt(table)
		local part = table:IsA('Model') and (table.PrimaryPart or table:FindFirstChildWhichIsA('BasePart')) or table
		local prompt = part and part:FindFirstChildWhichIsA('ProximityPrompt')
		if not prompt and table:IsA('Model') then
			prompt = table:FindFirstChildWhichIsA('ProximityPrompt', true)
		end
		return prompt, part
	end

	local function legitRepair(table, localPosition)
		local prompt, part = findRepairPrompt(table)
		if not prompt or not prompt.Enabled then return false end
		if part and (localPosition - part.Position).Magnitude > (prompt.MaxActivationDistance or 10) then return false end
		local hold = tonumber(prompt.HoldDuration) or 0
		prompt:InputHoldBegin()
		task.wait(hold + 0.05)
		prompt:InputHoldEnd()
		task.wait(0.1)
		return true
	end

	AutoEnchant = vape.Categories.Utility:CreateModule({
		Name = 'AutoEnchant',
		Function = function(callback)
			if callback then
				learned = nil

				repeat
					if entitylib.isAlive and entitylib.character and entitylib.character.RootPart and not table.find(Wanted.ListEnabled, learned) then
						local localPosition = entitylib.character.RootPart.Position
						local emeralds = getItem('emerald')
						local diamonds = getItem('diamond')

						for _, v in store.enchant do
							local part = v:IsA('Model') and v.PrimaryPart or v
							if not part or not part.Position then continue end
							if (localPosition - part.Position).Magnitude > Range.Value then continue end

							if v:HasTag('broken-enchant-table') then
								if Repair.Enabled and diamonds and diamonds.amount >= 8 then
									if Legit.Enabled then
										if legitRepair(v, localPosition) then break end
									else
										Fix:Fire('CallServer', v)
										break
									end
								end
							elseif emeralds and emeralds.amount >= 2 then
								local enchant = Research:Fire('CallServer', {enchantTable = v})
								learned = typeof(enchant) == 'table' and enchant.enchantType or learned
								if learned then
									local meta = bedwars.EnchantMeta and bedwars.EnchantMeta[learned]
									notif('AutoEnchant', 'Researched '..tostring(meta and (meta.name or meta.displayName) or learned), 3)
								end
								break
							end
						end
					end
					task.wait(Delay.Value)
				until not AutoEnchant.Enabled
			end
		end,
		Tooltip = 'Rerolls the enchant table until you get a chosen enchant'
	})

	Range = AutoEnchant:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 30,
		Default = 12,
		Suffix = util.Studs
	})
	Delay = AutoEnchant:CreateSlider({
		Name = 'Delay',
		Min = 0.1,
		Max = 3,
		Default = 0.5,
		Decimal = 10,
		Suffix = 'seconds',
		Tooltip = 'Time between rerolls'
	})
	Repair = AutoEnchant:CreateGroup({
		Name = 'Repair tables',
		Default = true,
		Tooltip = 'Repairs a broken enchant table before rerolling'
	})
	Legit = Repair:CreateToggle({
		Name = 'Legit mode',
		Darker = true,
		Tooltip = 'Repairs by holding the prompt like a player would'
	})
	local enchantList = {}
	for id in bedwars.EnchantMeta or {} do
		if type(id) == 'string' then
			table.insert(enchantList, id)
		end
	end
	table.sort(enchantList)
	for _, id in {'critical_strike', 'execute', 'soul_reaver'} do
		if not table.find(enchantList, id) then
			table.insert(enchantList, id)
		end
	end
	Wanted = AutoEnchant:CreateMultiDropdown({
		Name = 'Enchants',
		List = enchantList,
		Default = {'critical_strike', 'execute', 'soul_reaver'},
		Darker = true,
		Tooltip = 'Stops rerolling once one of these is researched'
	})
end)

