    local function roleOf(record)
        local combat, sense = record.Combat, record.Sense
        local objectives, resources, team = record.Objectives, record.Resources, record.Teamwork
        local watched = math.max(record.Observed, 1)
        local minutes = math.max(watched / 60, 0.3)

        local scores = {
            Rusher = math.clamp(
                safeDiv(objectives.BedApproaches, minutes) * 0.5
                + objectives.Beds * 0.5
                + reward(objectives.DefenceBroken, 20) * 0.3
                + safeDiv(sense.ExposedTime, watched) * 0.6, 0, 2),
            Defender = math.clamp(
                safeDiv(sense.SafeTime, watched) * 1.1
                + reward(team.Defends, 10) * 0.6
                + safeDiv(sense.BedResponses, math.max(sense.BedAlerts, 1)) * 0.5, 0, 2),
            Fighter = math.clamp(
                safeDiv(combat.Kills + combat.FightsWon, minutes) * 0.35
                + reward(combat.DamageDealt, 400) * 0.4
                + reward(combat.MeleeHits, 40) * 0.3, 0, 2),
            Support = math.clamp(
                reward(team.Assists, 3) * 0.7
                + safeDiv(team.PushWindow, watched) * 0.9
                + reward(team.Shared, 4) * 0.25, 0, 2),
            Economy = math.clamp(
                safeDiv(resources.GenTime, watched) * 1.2
                + reward(resources.Purchases, 5) * 0.5
                + reward(resources.Iron, 60) * 0.4, 0, 2),
            ResourceControl = math.clamp(
                safeDiv(team.ControlTime, watched) * 1.6
                + reward(resources.Diamond + resources.Emerald * 2, 8) * 0.6, 0, 2)
        }

        local best, bestScore, second = 'Mixed', 0, 0
        for _, role in ROLES do
            local value = scores[role] or 0
            if value > bestScore then
                best, second, bestScore = role, bestScore, value
            elseif value > second then
                second = value
            end
        end

        if bestScore < 0.35 or bestScore < second * 1.35 then
            return 'Mixed', scores
        end
        return best, scores
    end

    
    
    
    
    
    local function bands()
        local sweat = SweatAt.Value
        local skilled = math.min(SkilledAt.Value, sweat - 1)
        local above = math.min(AboveAt.Value, skilled - 1)
        local beginner = math.min(BeginnerBelow.Value, above - 1)
        return sweat, skilled, above, beginner, math.min(NewBelow.Value, beginner - 1)
    end

    local function ratingOf(score, confidence)
        if confidence < (MinConfidence.Value / 100) then return 'Unknown' end
        local sweat, skilled, above, beginner, fresh = bands()
        if score >= sweat then return 'Sweat' end
        if score >= skilled then return 'Skilled' end
        if score >= above then return 'Above Average' end
        if score > beginner then return 'Average' end
        if score > fresh then return 'Beginner' end
        return 'New'
    end

    
    
    
    local function blankAnalysis()
        return {
            OverallSkill = 0,
            Confidence = 0,
            Rating = 'Unknown',
            Role = 'Mixed',
            Categories = {
                Combat = 0,
                Movement = 0,
                GameSense = 0,
                Objectives = 0,
                Resources = 0,
                Teamwork = 0
            },
            Strengths = {},
            Weaknesses = {},
            RecentEvents = {}
        }
    end

    
    
    local function highlights(blends)
        local pool = {}
        for _, entry in blends do
            for name, data in entry.named do
                if data.Confidence >= 0.35 and math.abs(data.Deviation) >= 0.3 then
                    table.insert(pool, {Name = name, Score = data.Deviation * data.Confidence * data.Weight})
                end
            end
        end
        table.sort(pool, function(a, b)
            return a.Score > b.Score
        end)

        local strengths, weaknesses = {}, {}
        for _, entry in pool do
            if entry.Score > 0.25 and #strengths < 4 then
                table.insert(strengths, entry.Name)
            end
        end
        for index = #pool, 1, -1 do
            if pool[index].Score < -0.25 and #weaknesses < 4 then
                table.insert(weaknesses, pool[index].Name)
            end
        end
        return strengths, weaknesses
    end

    local function round(value, places)
        local factor = 10 ^ (places or 1)
        return math.floor(value * factor + 0.5) / factor
    end

    local function rebuild(record)
        local now = tick()
        record.Dirty = false
        record.NextScore = now + RESCORE_INTERVAL

        local scores, confs, blends = {}, {}, {}
        scores.Combat, confs.Combat, blends[1] = scoreCombat(record)
        scores.Movement, confs.Movement, blends[2] = scoreMovement(record)
        scores.GameSense, confs.GameSense, blends[3] = scoreSense(record)
        scores.Objectives, confs.Objectives, blends[4] = scoreObjectives(record)
        scores.Resources, confs.Resources, blends[5] = scoreResources(record)
        scores.Teamwork, confs.Teamwork, blends[6] = scoreTeamwork(record)

        local role, roleScores = roleOf(record)
        local weights = ROLE_WEIGHTS[role] or ROLE_WEIGHTS.Mixed

        
        
        local sum, weight, confSum, confWeight = 0, 0, 0, 0
        for _, name in CATEGORIES do
            local categoryWeight = weights[name]
            local w = categoryWeight * confs[name]
            sum = sum + scores[name] * w
            weight = weight + w
            confSum = confSum + confs[name] * categoryWeight
            confWeight = confWeight + categoryWeight
        end

        local quality = dataQuality(record)
        local confidence = math.clamp(safeDiv(confSum, confWeight) * quality, 0, 1)
        if record.Context.AFK then
            confidence = confidence * 0.6
        end
        
        
        local overall = math.clamp(50 + ((weight > 0 and (sum / weight) or 50) - 50) * (0.35 + 0.65 * confidence), 0, 100)
        local rating = ratingOf(overall, confidence)
        local strengths, weaknesses = highlights(blends)

        local events = {}
        for index = #record.Events, 1, -1 do
            local entry = record.Events[index]
            table.insert(events, {
                Type = entry.Type,
                Time = entry.Time,
                Age = now - entry.Time,
                Confidence = entry.Confidence,
                Detail = entry.Detail
            })
        end

        local analysis = {
            OverallSkill = round(overall, 1),
            Confidence = round(confidence, 3),
            Rating = rating,
            Role = role,
            Categories = {
                Combat = round(scores.Combat, 1),
                Movement = round(scores.Movement, 1),
                GameSense = round(scores.GameSense, 1),
                Objectives = round(scores.Objectives, 1),
                Resources = round(scores.Resources, 1),
                Teamwork = round(scores.Teamwork, 1)
            },
            Strengths = strengths,
            Weaknesses = weaknesses,
            RecentEvents = events,
            
            Player = record.Player,
            CategoryConfidence = confs,
            RoleScores = roleScores,
            Observed = round(record.Observed, 1),
            AFK = record.Context.AFK,
            DataQuality = round(quality, 3)
        }

        local previous = record.Cache
        record.Cache = analysis
        if not previous or previous.Rating ~= analysis.Rating or previous.Role ~= analysis.Role then
            vapeEvents.EntityAnalysed:Fire(record.Player, analysis)
            local wasHigh = previous ~= nil and (previous.Rating == 'Skilled' or previous.Rating == 'Sweat')
            local isHigh = analysis.Rating == 'Skilled' or analysis.Rating == 'Sweat'
            if Notify.Enabled and isHigh and not wasHigh then
                notif('EntityAnalyser', record.Player.Name .. ' is ' .. analysis.Rating .. ' (' .. math.floor(analysis.OverallSkill) .. ', ' .. analysis.Role .. ')', 4)
            end
        end
        return analysis
    end

    local function analysisFor(plr)
        local record = peek(plr)
        if not record then return blankAnalysis() end
        if not record.Cache then return rebuild(record) end
        
        
        if record.Dirty and tick() >= record.NextScore then return rebuild(record) end
        return record.Cache
    end

    
    
    
    local function removeTag(plr)
        local tag = tags[plr]
        if tag then
            tag:Destroy()
        end
        tags[plr] = nil
    end

    local function ratingShown(rating)
        if table.find(Ratings.List, rating) then return Ratings:Has(rating) end
        return Ratings:Has('Unrated')
    end

    local function updateTag(plr, ent, analysis)
        local adornee = ent.Head or ent.RootPart
        if not folder or not adornee or not adornee.Parent or not ratingShown(analysis.Rating) then
            removeTag(plr)
            return
        end

        local tag = tags[plr]
        if not tag or tag.Adornee ~= adornee or not tag.Parent then
            removeTag(plr)
            tag = Instance.new('BillboardGui')
            tag.Name = 'EntityAnalyser'
            tag.AlwaysOnTop = true
            tag.ClipsDescendants = false
            tag.Size = UDim2.fromOffset(260, 18)
            
            
            tag.StudsOffsetWorldSpace = Vector3.new(0, 4.4, 0)
            tag.Adornee = adornee
            tag.Parent = folder

            local label = Instance.new('TextLabel')
            label.Name = 'Label'
            label.Size = UDim2.fromScale(1, 1)
            label.BackgroundTransparency = 1
            label.Font = Enum.Font.GothamBold
            label.TextSize = 13
            label.TextStrokeTransparency = 0.4
            label.Parent = tag
            tags[plr] = tag
        end

        local label = tag:FindFirstChild('Label')
        if label then
            local colour = ratingColor[analysis.Rating] or ratingColor.Unknown
            if label.TextColor3 ~= colour then label.TextColor3 = colour end
            local text = '\u{25CF} ' .. analysis.Rating
            if LabelInfo:Has('Score') and analysis.Rating ~= 'Unknown' then
                text = text .. ' ' .. math.floor(analysis.OverallSkill)
            end
            if LabelInfo:Has('Role') and analysis.Role ~= 'Mixed' then
                text = text .. ' \u{00B7} ' .. analysis.Role
            end
            if LabelInfo:Has('Confidence') then
                text = text .. ' \u{00B7} ' .. math.floor(analysis.Confidence * 100) .. '%'
            end
            if analysis.AFK then
                text = text .. ' \u{00B7} AFK'
            end
            if label.Text ~= text then label.Text = text end
        end
    end

    local function clearTags()
        for plr in tags do
            removeTag(plr)
        end
        table.clear(tags)
    end

    
    
    
    local function step()
        
        
        local now = tick()
        probeBudget = PROBE_BUDGET

        if store.matchState ~= lastMatchState then
            if store.matchState == 1 then
                matchStart = now
                bedsAtStart = #collectionService:GetTagged('bed')
            end
            lastMatchState = store.matchState
        end
        refreshWorld(now)

        for key, fight in engagements do
            if now - fight.Last > ENGAGE_MEMORY then
                engagements[key] = nil
            end
        end

        local origin = entitylib.isAlive and entitylib.character.RootPart and entitylib.character.RootPart.Position or nil
        local nearRange = SampleRange.Value
        local labelsOn = Labels.Enabled

        table.clear(seen)
        for _, ent in entitylib.List do
            local plr = ent.Player
            if plr and plr ~= lplr then
                seen[plr] = true
                local record = profileFor(plr)
                local root = ent.RootPart
                local distance = (origin and root and root.Parent) and (root.Position - origin).Magnitude or math.huge
                local fighting = now - record.Combat.LastHit <= FIGHT_MEMORY or now - record.Combat.LastHurt <= FIGHT_MEMORY
                local near = distance <= nearRange or fighting

                
                
                
                local interval = near and NEAR_INTERVAL or (record.Context.AFK and AFK_INTERVAL or FAR_INTERVAL)
                if now - record.LastSample >= interval then
                    local sampleDt = math.min(now - record.LastSample, 1)
                    record.LastSample = now
                    sampleEntity(ent, record, sampleDt, near)
                    updateContext(record, ent)
                    sampleInventory(record)
                    if near then
                        updateThreats(record, ent)
                        if now - record.LastProbe >= PROBE_INTERVAL then
                            record.LastProbe = now
                            probeEntity(ent, record)
                        end
                    end
                end

                
                
                
                local analysis = analysisFor(plr)
                if labelsOn and (Teammates.Enabled or not sameTeam(plr, lplr)) then
                    updateTag(plr, ent, analysis)
                else
                    removeTag(plr)
                end
            end
        end

        
        
        for plr in tags do
            if not seen[plr] then
                removeTag(plr)
            end
        end
    end

    
    
    
    local api
    api = {
        Enabled = false,
        
        
        
        Analyse = function(plr)
            if not running or typeof(plr) ~= 'Instance' or not plr:IsA('Player') then
                return blankAnalysis()
            end
            local ok, result = pcall(analysisFor, plr)
            return ok and result or blankAnalysis()
        end,
        GetAll = function()
            local all = {}
            if not running then return all end
            for plr in profiles do
                if plr.Parent then
                    all[plr] = api.Analyse(plr)
                end
            end
            return all
        end,
        Reset = function(plr)
            if plr then
                profiles[plr] = nil
                return
            end
            table.clear(profiles)
            table.clear(engagements)
            table.clear(pendingVoid)
        end,
        Ratings = {'New', 'Beginner', 'Average', 'Above Average', 'Skilled', 'Sweat'},
        Roles = ROLES
    }
    getgenv().EntityAnalyser = api

    EntityAnalyser = vape.Categories.Utility:CreateModule({
        Name = 'EntityAnalyser',
        Function = function(callback)
            running = callback
            api.Enabled = callback
            
            
            vapeEvents.EntityAnalyserState:Fire(callback)

            if callback then
                matchStart, lastMatchState = tick(), -1
                bedsAtStart = #collectionService:GetTagged('bed')
                folder = Instance.new('Folder')
                folder.Name = 'EntityAnalyser'
                folder.Parent = vape.gui
                EntityAnalyser:Clean(folder)

                EntityAnalyser:Clean(vapeEvents.EntityDamageEvent.Event:Connect(onDamage))
                EntityAnalyser:Clean(vapeEvents.EntityDeathEvent.Event:Connect(onDeath))
                EntityAnalyser:Clean(vapeEvents.BedwarsBedBreak.Event:Connect(onBedBreak))
                EntityAnalyser:Clean(vapeEvents.PlaceBlockEvent.Event:Connect(onPlaceBlock))
                EntityAnalyser:Clean(vapeEvents.BreakBlockEvent.Event:Connect(onBreakBlock))
                EntityAnalyser:Clean(vapeEvents.MatchEndEvent.Event:Connect(function()
                    table.clear(engagements)
                    table.clear(pendingVoid)
                end))
                EntityAnalyser:Clean(entitylib.Events.AnimationPlayed:Connect(function(plr, track)
                    if not running or not plr or plr == lplr then return end
                    local animation = track and track.Animation
                    if animation then
                        noteSwing(plr, animation.AnimationId)
                    end
                end))
                EntityAnalyser:Clean(workspace.ChildAdded:Connect(function(object)
                    
                    task.delay(0, function()
                        if object and object.Parent then
                            pcall(onProjectile, object)
                        end
                    end)
                end))
                
                
                EntityAnalyser:Clean(playersService.PlayerRemoving:Connect(function(plr)
                    profiles[plr] = nil
                    pendingVoid[plr] = nil
                    removeTag(plr)
                end))
                
                
                local nextStep = 0
                EntityAnalyser:Clean(runService.Heartbeat:Connect(function()
                    if not running then return end
                    local now = tick()
                    if now < nextStep then return end
                    nextStep = now + NEAR_INTERVAL
                    pcall(step)
                end))
            else
                clearTags()
                table.clear(profiles)
                table.clear(engagements)
                table.clear(pendingVoid)
                folder = nil
            end
        end,
        Tooltip = 'Rates how well each player is playing'
    })

    SweatAt = EntityAnalyser:CreateSlider({
        Name = 'Sweat at',
        Min = 60,
        Max = 99,
        Default = 84,
        Tooltip = 'Score needed for the top rating'
    })
    SkilledAt = EntityAnalyser:CreateSlider({
        Name = 'Skilled at',
        Min = 50,
        Max = 95,
        Default = 70,
        Tooltip = 'Score needed to count as skilled'
    })
    AboveAt = EntityAnalyser:CreateSlider({
        Name = 'Above average at',
        Min = 45,
        Max = 85,
        Default = 58,
        Tooltip = 'Score above which a player counts as above average'
    })
    BeginnerBelow = EntityAnalyser:CreateSlider({
        Name = 'Beginner below',
        Min = 15,
        Max = 50,
        Default = 38,
        Tooltip = 'Score under which a player counts as a beginner'
    })
    NewBelow = EntityAnalyser:CreateSlider({
        Name = 'New below',
        Min = 2,
        Max = 40,
        Default = 22,
        Tooltip = 'Score under which a player counts as new'
    })
    MinConfidence = EntityAnalyser:CreateSlider({
        Name = 'Minimum confidence',
        Min = 0,
        Max = 90,
        Default = 15,
        Suffix = '%',
        Tooltip = 'How sure it must be before rating a player'
    })
    SampleRange = EntityAnalyser:CreateSlider({
        Name = 'Sample range',
        Min = 40,
        Max = 250,
        Default = 90,
        Suffix = ' studs',
        Tooltip = 'Players in this range are checked more often'
    })
    Labels = EntityAnalyser:CreateToggle({
        Name = 'Labels',
        Default = true,
        Function = function(callback)
            if not callback then
                clearTags()
            end
        end,
        Tooltip = 'Shows the rating above each player'
    })
    LabelInfo = EntityAnalyser:CreateMultiDropdown({
        Name = 'Label shows',
        List = {'Score', 'Role', 'Confidence'},
        Default = {'Score', 'Role'},
        Darker = true,
        Visible = function() return Labels.Enabled end,
        Tooltip = 'What each label shows'
    })
    Ratings = EntityAnalyser:CreateMultiDropdown({
        Name = 'Ratings',
        List = {'Sweat', 'Skilled', 'Above Average', 'Average', 'Beginner', 'New', 'Unrated'},
        Default = {'Sweat', 'Skilled', 'Above Average', 'Average', 'Beginner', 'New'},
        Darker = true,
        Visible = function() return Labels.Enabled end,
        Tooltip = 'Which ratings get a label'
    })
    Teammates = EntityAnalyser:CreateToggle({
        Name = 'Label teammates',
        Tooltip = 'Also rate your own team'
    })
    Notify = EntityAnalyser:CreateToggle({
        Name = 'Notifications',
        Tooltip = 'Tells you when a player is rated skilled or above'
    })

    vape:Clean(function()
        running = false
        api.Enabled = false
        table.clear(profiles)
        table.clear(engagements)
        table.clear(pendingVoid)
    end)
end)

-- ===== Utility/InfoEditor.lua =====
run(function()
	local Main = vape.Libraries.mergedModule(vape.Categories.Utility, {
		Name = 'InfoEditor',
		Tooltip = 'Changes what your name, nametag and level look like on your screen'
	})

run(function()
	local CoreGui = coreGui
	local LocalPlayer = lplr
	local Players = playersService
	local NickHider
	local Replacement
	local ChatTags
	local Level
	local HideOthers
	local Kit
	local Hidden = setmetatable({}, {__mode = "k"})
	local Swapped = setmetatable({}, {__mode = "k"})
	local Watched = setmetatable({}, {__mode = "k"})
	local Patterns: {string} = {}
	local Plain: {string} = {}
	local Shortest: number = math.huge
	local TextClasses: {[string]: boolean} = {TextLabel = true, TextButton = true, TextBox = true}
	local Fake: string = "hidden"
	local Writing: Instance?
	local OldUsername, OldDisplayName, OldClanTag, OldLevel

	local Refreshing: boolean = false

	local function QueueRefresh()
		if Refreshing or not NickHider or not NickHider.Enabled then
			return
		end
		Refreshing = true

		task.delay(0.35, function()
			Refreshing = false
			if NickHider.Enabled then
				NickHider:Toggle()
				NickHider:Toggle()
			end
		end)
	end

	local function ShouldHidePlayer(Player: Player?)
		return Player and (Player.UserId == LocalPlayer.UserId or HideOthers.Enabled)
	end

	local function AddPlayerNames(Player: Player)
		for _, v: string in {Player.Name, Player.DisplayName} do
			if v ~= "" then
				local LowerName: string = v:lower()
				if not table.find(Plain, LowerName) then
					table.insert(Plain, LowerName)
					Shortest = math.min(Shortest, #LowerName)
				end
			end
			for _, Variant: string in {v, v:lower(), v:upper()} do
				local Pattern: string = (Variant:gsub("%W", "%%%0"))
				if Variant ~= "" and not table.find(Patterns, Pattern) then
					table.insert(Patterns, Pattern)
				end
			end
		end
	end

	local function ReplaceText(Object: Instance)
		if Writing == Object then
			return
		end

		local Text: string = Object.Text
		if type(Text) ~= "string" or #Text < Shortest then
			return
		end

		local Hit: boolean = false
		for _, v: string in Plain do
			if Text:find(v, 1, true) then
				Hit = true
				break
			end
		end
		if not Hit then
			local LowerText: string = Text:lower()
			for _, v: string in Plain do
				if LowerText:find(v, 1, true) then
					Hit = true
					break
				end
			end
		end
		if not Hit then
			return
		end

		local NewText: string = Text
		for _, v: string in Patterns do
			if NewText:find(v) then
				NewText = NewText:gsub(v, Fake)
			end
		end
		if NewText == Text then
			return
		end

		Swapped[Object] = Text
		Object:SetAttribute("NickHiderOriginalText", Text)
		Writing = Object
		Object.Text = NewText
		Writing = nil

		if not Watched[Object] then
			Watched[Object] = Object:GetPropertyChangedSignal("Text"):Connect(function()
				ReplaceText(Object)
			end)
		end
	end

	local function HideObject(Object: Instance)
		if TextClasses[Object.ClassName] then
			ReplaceText(Object)
		end
	end

	local function HideKit(Object: Instance)
		if not Kit.Enabled or Object.Name ~= "PlayerKitFrame" or Hidden[Object] ~= nil then
			return
		end

		task.defer(function()
			local Label = Object.Parent and Object.Parent:FindFirstChild("PlayerName", true)
			if not NickHider.Enabled or not Kit.Enabled or not Label or not Label.Text:find(Fake, 1, true) then
				return
			end

			Hidden[Object] = Object.Visible
			Object.Visible = false
		end)
	end

	local function Watch(Root: Instance?)
		if not Root then
			return
		end

		if vape.ThreadFix then
			setthreadidentity(8)
		end
		NickHider:Clean(Root.DescendantAdded:Connect(function(Object: Instance)
			if NickHider.Enabled then
				HideObject(Object)
				HideKit(Object)
			end
		end))

		local Clock: number = os.clock()
		for _, v: Instance in Root:GetDescendants() do
			HideObject(v)
			HideKit(v)

			if os.clock() - Clock > 0.002 then
				task.wait()
				if not NickHider.Enabled then
					return
				end
				Clock = os.clock()

				if vape.ThreadFix then
					setthreadidentity(8)
				end
			end
		end
	end

	NickHider = Main:Part({
		Label = 'Hide name',
		Name = "NickHider",
		ConfigName = "NameHider",
		Function = function(Callback: boolean)
			if Callback then
				table.clear(Patterns)
				table.clear(Plain)
				Shortest = math.huge
				for _, Player: Player in Players:GetPlayers() do
					if Player == LocalPlayer or HideOthers.Enabled then
						AddPlayerNames(Player)
					end
				end

				Fake = Replacement.Value ~= "" and Replacement.Value or "hidden"
				for _, v: string in Patterns do
					if Fake:find(v) then
						Fake = "hidden"
						break
					end
				end

				local GamePlayer = bedwars.GamePlayerUtil and bedwars.GamePlayerUtil.getGamePlayer(LocalPlayer)
				GamePlayer = GamePlayer and getmetatable(GamePlayer)
				GamePlayer = GamePlayer and GamePlayer.__index
				if GamePlayer and not OldUsername then
					OldUsername, OldDisplayName = GamePlayer.getUsername, GamePlayer.getDisplayName
					OldClanTag, OldLevel = GamePlayer.getClanTag, GamePlayer.getLevel
					GamePlayer.getUsername = function(self, ...)
						local Player: Player? = self:getPlayer()
						return ShouldHidePlayer(Player) and Fake or OldUsername(self, ...)
					end
					GamePlayer.getDisplayName = function(self, ...)
						local Player: Player? = self:getPlayer()
						return ShouldHidePlayer(Player) and Fake or OldDisplayName(self, ...)
					end
					GamePlayer.getClanTag = function(self, ...)
						local Player: Player? = self:getPlayer()
						return (Player and Player.UserId == LocalPlayer.UserId) and ChatTags.Enabled and "" or OldClanTag(self, ...)
					end
					GamePlayer.getLevel = function(self, ...)
						local Player: Player? = self:getPlayer()
						if Player and (HideOthers.Enabled or (Player.UserId == LocalPlayer.UserId and Level.Enabled)) then
							return -1
						end
						return OldLevel(self, ...)
					end
				end

				for _, v: Instance in {LocalPlayer:FindFirstChildOfClass("PlayerGui"), CoreGui, gethui and gethui() or nil, LocalPlayer.Character} do
					Watch(v)
				end

				NickHider:Clean(LocalPlayer.CharacterAdded:Connect(function(Character: Model)
					if NickHider.Enabled then
						Watch(Character)
					end
				end))
				NickHider:Clean(Players.PlayerAdded:Connect(function()
					if HideOthers.Enabled then
						QueueRefresh()
					end
				end))
				NickHider:Clean(Players.PlayerRemoving:Connect(function()
					if HideOthers.Enabled then
						QueueRefresh()
					end
				end))
			else
				local GamePlayer = bedwars.GamePlayerUtil and bedwars.GamePlayerUtil.getGamePlayer(LocalPlayer)
				GamePlayer = GamePlayer and getmetatable(GamePlayer)
				GamePlayer = GamePlayer and GamePlayer.__index
				if OldUsername and GamePlayer then
					GamePlayer.getUsername, GamePlayer.getDisplayName = OldUsername, OldDisplayName
					GamePlayer.getClanTag, GamePlayer.getLevel = OldClanTag, OldLevel
					OldUsername, OldDisplayName, OldClanTag, OldLevel = nil, nil, nil, nil
				end
				if vape.ThreadFix then
					setthreadidentity(8)
				end

				for _, v: RBXScriptConnection in Watched do
					v:Disconnect()
				end
				table.clear(Watched)

				for Object: GuiObject, Visible: boolean in Hidden do
					if Object.Parent then
						Object.Visible = Visible
					end
				end
				table.clear(Hidden)

				for Object: Instance, OriginalText: string in Swapped do
					if Object.Parent then
						Writing = Object
						Object.Text = OriginalText
						Object:SetAttribute("NickHiderOriginalText", nil)
					end
				end
				Writing = nil
				table.clear(Swapped)
			end
		end,
		Tooltip = 'Replaces your name everywhere on your screen',
		ExtraText = function()
			return Replacement.Value ~= "" and Replacement.Value or "hidden"
		end
	})

	Replacement = NickHider:CreateTextBox({
		Name = "Name",
		Function = QueueRefresh,
		Default = "hidden"
	})
	local Hide = NickHider:CreateMultiDropdown({
		Name = "Hide",
		List = {"Others", "Chat tags", "Level", "Kit"},
		Default = {},
		Function = QueueRefresh,
		Tooltip = 'What to hide on your screen'
	})
	local function flag(name)
		return setmetatable({}, {__index = function(_, key)
			if key == "Enabled" then
				return Hide:Has(name)
			end
		end})
	end
	HideOthers, ChatTags, Level, Kit = flag("Others"), flag("Chat tags"), flag("Level"), flag("Kit")
end)

run(function()
	local NameTagSpoofer
	local CustomNameBox
	local trackedElements = setmetatable({}, {__mode = 'k'})
	local trackedUsernames = setmetatable({}, {__mode = 'k'})
	local hiddenLabels = setmetatable({}, {__mode = 'k'})
	local watched = setmetatable({}, {__mode = 'k'})
	local applying = setmetatable({}, {__mode = 'k'})

	local function getCustomName()
		if CustomNameBox and type(CustomNameBox.Value) == "string" and CustomNameBox.Value ~= "" then
			return CustomNameBox.Value
		end
		return "Me"
	end

	local function containsLocalName(text)
		return type(text) == 'string' and (text:find(lplr.Name, 1, true) ~= nil
			or text:find(lplr.DisplayName, 1, true) ~= nil)
	end

	local function setText(element, value)
		if not element.Parent or element.Text == value then return end
		applying[element] = true
		element.Text = value
		applying[element] = nil
	end

	local applyObject
	local function watchText(element)
		if watched[element] then return end
		watched[element] = true
		NameTagSpoofer:Clean(element:GetPropertyChangedSignal('Text'):Connect(function()
			if NameTagSpoofer.Enabled and not applying[element] then applyObject(element) end
		end))
	end

	local CANDIDATE_NAMES = {PlayerName = true, EntityName = true, DisplayName = true, PlayerUsername = true, ['@'] = true}

	applyObject = function(element)
		if not element or not CANDIDATE_NAMES[element.Name] or not element.Parent then return end
		if element:IsA('TextLabel') and table.find({'PlayerName', 'EntityName', 'DisplayName'}, element.Name) then
			watchText(element)
			local original = trackedElements[element]
			if original then
				if containsLocalName(element.Text) then original.Text = element.Text end
				setText(element, getCustomName())
			elseif containsLocalName(element.Text) then
				trackedElements[element] = {Text = element.Text}
				setText(element, getCustomName())
			end
		elseif element:IsA('TextBox') and element.Name == 'PlayerUsername' then
			watchText(element)
			local original = trackedUsernames[element]
			if original then
				if containsLocalName(element.Text) then original.Text = element.Text end
				setText(element, '@'..getCustomName())
			elseif containsLocalName(element.Text) then
				trackedUsernames[element] = {Text = element.Text}
				setText(element, '@'..getCustomName())
			end
		elseif element:IsA('TextLabel') and element.Name == '@'
			and element.Parent and element.Parent.Name == 'PlayerUsername' then
			if hiddenLabels[element] == nil then hiddenLabels[element] = element.Visible end
			element.Visible = false
		end
	end

	local function processRoot(root)
		if not root then return end
		applyObject(root)
		for _, descendant in root:GetDescendants() do applyObject(descendant) end
	end

	local function attachCharacter(character)
		if not character then return end
		processRoot(character)
		NameTagSpoofer:Clean(character.DescendantAdded:Connect(applyObject))
	end

	local function restore()
		for element, original in trackedElements do
			if element.Parent then pcall(setText, element, original.Text) end
		end
		for element, original in trackedUsernames do
			if element.Parent then pcall(setText, element, original.Text) end
		end
		for element, visible in hiddenLabels do
			if element.Parent then pcall(function() element.Visible = visible end) end
		end
		table.clear(trackedElements)
		table.clear(trackedUsernames)
		table.clear(hiddenLabels)
		table.clear(watched)
		table.clear(applying)
	end

	NameTagSpoofer = Main:Part({
		Label = 'Custom nametag',
		Default = false,
		Name = 'NameTagSpoofer',
		Function = function(callback)
			if callback then
				processRoot(lplr.PlayerGui)
				attachCharacter(lplr.Character)
				NameTagSpoofer:Clean(lplr.PlayerGui.DescendantAdded:Connect(applyObject))
				NameTagSpoofer:Clean(lplr.CharacterAdded:Connect(attachCharacter))
				NameTagSpoofer:Clean(restore)
			else
				restore()
			end
		end,
		Tooltip = 'Changes your name in various places'
	})

	CustomNameBox = NameTagSpoofer:CreateTextBox({
		Name = 'Custom Name',
		Default = 'Me',
		Placeholder = 'Enter name...',
		Function = function()
			if not NameTagSpoofer.Enabled then return end
			for element in trackedElements do if element.Parent then setText(element, getCustomName()) end end
			for element in trackedUsernames do if element.Parent then setText(element, '@'..getCustomName()) end end
		end
	})
end)

run(function()
    local SetPlayerLevel
    local originalLevel = nil
    local customLevel = 1
    local applying = false

    local function apply()
        if not SetPlayerLevel.Enabled then return end
        applying = true
        lplr:SetAttribute('PlayerLevel', customLevel)
        applying = false
    end

    SetPlayerLevel = Main:Part({
		Label = 'Set level',
		Default = false,
        Name = 'SetPlayerLevel',
        Function = function(state)
            if state then
                originalLevel = lplr:GetAttribute('PlayerLevel')
                apply()
                SetPlayerLevel:Clean(lplr:GetAttributeChangedSignal('PlayerLevel'):Connect(function()
                    local current = lplr:GetAttribute('PlayerLevel')
                    if applying or current == customLevel then return end
                    originalLevel = current
                    apply()
                end))
            else
                if originalLevel ~= nil then
                    applying = true
                    lplr:SetAttribute('PlayerLevel', originalLevel)
                    applying = false
                end
                originalLevel = nil
            end
        end,
        Tooltip = 'Changes your player level, only on your screen'
    })

    SetPlayerLevel:CreateSlider({
        Name = 'Level',
        Min = 1,
        Max = 1000,
        Default = 1,
        Decimal = 1,
        Function = function(val)
            customLevel = math.floor(val)
            apply()
        end
    })
end)

run(function()
	local RemovePlayerLevel
	local hidden = setmetatable({}, {__mode = 'k'})
	local watched = setmetatable({}, {__mode = 'k'})

	local function hide(descendant)
		if descendant:IsA("TextLabel") and descendant.Name == "PlayerLevel" then
			if hidden[descendant] == nil then
				hidden[descendant] = descendant.Visible
			end
			descendant.Visible = false
		end
	end

	local function watch(gui)
		if watched[gui] then return end
		watched[gui] = true
		for _, descendant in gui:GetDescendants() do
			hide(descendant)
		end
		RemovePlayerLevel:Clean(gui.DescendantAdded:Connect(hide))
	end

	RemovePlayerLevel = Main:Part({
		Label = 'Hide tab list levels',
		Default = false,
		Name = 'RemovePlayerLevelUI',
		Function = function(callback)
			if callback then
				local existingTabList = lplr.PlayerGui:FindFirstChild("TabListScreenGui")
				if existingTabList then
					watch(existingTabList)
				end

				RemovePlayerLevel:Clean(lplr.PlayerGui.ChildAdded:Connect(function(gui)
					if gui.Name == "TabListScreenGui" then
						watch(gui)
					end
				end))
			else
				for label, visible in hidden do
					pcall(function()
						label.Visible = visible
					end)
				end
				table.clear(hidden)
				table.clear(watched)
			end
		end,
		Tooltip = 'Removes player levels from the player list'
	})
end)

end)

-- ===== Utility/KnockbackDelay.lua =====
run(function()
    local KnockbackDelay
    local Chance
    local AirDelay
    local GroundDelay
    local TargetCheck

    local old, hook
    local rand = Random.new()

    local function apply(without, ...)
	local root, mass, dir, knockback = ...
	if not old or typeof(root) ~= 'Instance' or not root.Parent then return end
	knockback = knockback and table.clone(knockback) or {}
	knockback[without] = 0
	return old(root, mass, dir, knockback, select(5, ...))
    end

    KnockbackDelay = vape.Categories.Utility:CreateModule({
	Name = 'KnockbackDelay',
	ExtraText = function() return Chance.Value..'%' end,
	Function = function(callback)
		if callback then
			if hook then return end
			old = bedwars.KnockbackUtil.applyKnockback
			hook = function(...)
				if not KnockbackDelay.Enabled or rand:NextNumber(0, 100) > Chance.Value then
					return old(...)
				end

				local root, mass, dir, knockback = ...
				if not TargetCheck.Enabled or entitylib.EntityPosition({
					Range = 50,
					Part = 'RootPart',
					Players = true,
				}) then
					task.delay(AirDelay:GetRandomValue() / 1000, apply, 'horizontal', root, mass, dir, knockback, select(5, ...))
					task.delay(GroundDelay:GetRandomValue() / 1000, apply, 'vertical', root, mass, dir, knockback, select(5, ...))
					return
				end
				return old(...)
			end
			bedwars.KnockbackUtil.applyKnockback = hook
		elseif hook and bedwars.KnockbackUtil.applyKnockback == hook then
			bedwars.KnockbackUtil.applyKnockback = old
			hook = nil
		end
	end,
	Tooltip = 'Delays the knockback you take'
    })

    Chance = KnockbackDelay:CreateSlider({
	Name = 'Chance',
	Min = 1,
	Max = 100,
	Default = 40,
	Suffix = '%',
    })
    AirDelay = KnockbackDelay:CreateTwoSlider({
	Name = 'Air delay',
	Min = 0,
	Max = 500,
	DefaultMin = 50,
	DefaultMax = 200,
	Tooltip = 'Delay before the upward part of knockback applies',
    })
    GroundDelay = KnockbackDelay:CreateTwoSlider({
	Name = 'Ground delay',
	Min = 0,
	Max = 500,
	DefaultMin = 50,
	DefaultMax = 200,
	Tooltip = 'Delay before the sideways part of knockback applies',
    })
    TargetCheck = KnockbackDelay:CreateToggle({
	Name = 'Target check',
	Tooltip = 'Only delays knockback with a player nearby',
    })
end)

-- ===== Utility/LagbackAura.lua =====
run(function()
	local LagbackAura
	local Targets
	local Sort
	local remoteCache = {}

	local function remote(name)
		local found = remoteCache[name]
		if found and found.Parent then return found end
		for _, v in replicatedStorage:GetDescendants() do
			if v.Name == name and (v:IsA('RemoteEvent') or v:IsA('RemoteFunction')) then
				remoteCache[name] = v
				return v
			end
		end
	end

	local function fire(name, ...)
		local r = remote(name)
		if not r then return end
		if r:IsA('RemoteEvent') then
			r:FireServer(...)
		else
			local args = table.pack(...)
			task.spawn(function()
				pcall(r.InvokeServer, r, table.unpack(args, 1, args.n))
			end)
		end
	end

	LagbackAura = vape.Categories.Utility:CreateModule({
		Name = 'LagbackAura',
		Tags = {'Experimental'},
		Function = function(callback)
			if callback then
				repeat
					task.wait(0.5)
					if not entitylib.isAlive then continue end

					local plrs = entitylib.AllPosition({
						Range = 30,
						Wallcheck = Targets.Walls.Enabled or nil,
						Part = 'RootPart',
						Players = Targets.Players.Enabled,
						NPCs = Targets.NPCs.Enabled,
						Limit = 1,
						Sort = sortmethods[Sort.Value]
					})

					if #plrs > 0 and plrs[1].Player then
						local actionBar = lplr.PlayerGui:FindFirstChild('ActionBarScreenGui')
						actionBar = actionBar and actionBar:FindFirstChild('ActionBar')
						local progBar = actionBar and actionBar:FindFirstChild('ProgressBarContainer')
						local bar = progBar and progBar:FindFirstChild('ProgressBar')
						if not bar or bar.Size.X.Scale < 0.33 then continue end

						fire('useAbility', 'elk_summon')
						task.wait(0.1)
						fire('SigridBeginChargeRequest', {player = plrs[1].Player})
						task.wait(1)
						fire('Dismount', {mountType = 'elk'})
						task.wait(7)
					end
				until not LagbackAura.Enabled
			end
		end,
		Tooltip = 'Charges the nearest player with the Sigrid elk to lag them back'
	})
	Targets = LagbackAura:CreateTargets({
		Players = true,
		NPCs = true
	})
	Sort = LagbackAura:CreateDropdown({
		Name = 'Target Mode',
		List = sortlist
	})
end)

-- ===== Utility/MP3Player.lua =====
run(function()
	local Main = vape.Libraries.mergedModule(vape.Categories.Utility, {
		Name = 'MP3Player',
		Tooltip = 'Plays your mp3 files from the ElevateV4/songs folder'
	})

run(function()
    local MP3Player
    local Volume
    local Shuffle
    local Loop
    local PlayField
    local Playlist
    local ShowHUD
    local PulseToBeat
    local PulseIntensity
    local PulseType
    local PulseColor
    local PulseRegions

    local SONGS = 'ElevateV4/songs'
    local SPOTIFY = 'ElevateV4/spotify'

    local soundService = game:GetService('SoundService')
    local sound
    local tracks, index = {}, 0
    local hudName, hudTime, hudBarFill, hudBackground
    local pulseWhole, pulseEdges = nil, {}
    local lastScan = 0
    local scanKey = ''
    local lastPlay = 0
    local loadDeadline = 0
    local loadFailures = 0
    local beatCooldown = 0
    local loudnessAverage, lastLoudness = 0, 0
    local FOV_STEP_NAME = 'AetherMP3BeatPulse'
    local fovOffset, fovBase = 0, nil
    local fovBound, fovPreRender = false, nil
    local beatTimes, tempo, nextBeat, offBeat = {}, nil, 0, 0
    local LOCK_TOLERANCE = 0.22
    local LOCK_SAMPLES = 3

    local function fsList(path)
        local ok, res = pcall(function()
            if isfolder and not isfolder(path) then
                if makefolder then makefolder(path) end
                return {}
            end
            return listfiles and listfiles(path) or {}
        end)
        return ok and res or {}
    end

    local function isAudio(path)
        path = tostring(path):lower()
        return path:sub(-4) == '.mp3' or path:sub(-4) == '.wav' or path:sub(-4) == '.ogg'
    end

    local function fileName(path)
        local normalised = tostring(path):gsub('\\', '/')
        local name = normalised:match('([^/]+)$') or normalised
        return (name:gsub('%.[^%.]+$', ''))
    end

    local function scan(announce)
        local found = {}
        for _, file in fsList(SONGS) do
            if isAudio(file) then
                table.insert(found, {Name = fileName(file), Path = tostring(file):gsub('\\', '/')})
            end
        end
        for _, file in fsList(SPOTIFY) do
            if isAudio(file) then
                table.insert(found, {Name = fileName(file), Path = tostring(file):gsub('\\', '/')})
            end
        end
        table.sort(found, function(a, b)
            return a.Name:lower() < b.Name:lower()
        end)

        local wanted = Playlist and Playlist.ListEnabled or {}
        if #wanted > 0 then
            local ordered = {}
            for _, entry in wanted do
                local needle = entry:lower()
                for _, track in found do
                    if track.Name:lower():find(needle, 1, true) then
                        table.insert(ordered, track)
                        break
                    end
                end
            end
            if #ordered > 0 then
                found = ordered
            end
        end

        local key = ''
        for _, track in found do
            key = key .. track.Path .. ';'
        end
        local changed = key ~= scanKey
        scanKey = key
        tracks = found
        if changed and announce and MP3Player.Enabled then
            notif('MP3Player', #tracks > 0 and (#tracks .. ' song' .. (#tracks == 1 and '' or 's') .. ' loaded') or 'No songs in the songs folder yet', 3)
        end
        return changed
    end

    local function assetFor(path)
        local ok, asset = pcall(function()
            return getcustomasset(path)
        end)
        return ok and asset or nil
    end

    local function refreshHUD()
        if not hudName then return end
        local track = tracks[index]
        hudName.Text = track and track.Name or 'No song loaded'

        local length = sound and sound.TimeLength or 0
        local at = sound and sound.TimePosition or 0
        if hudTime then
            local function clock(t)
                t = math.max(math.floor(t), 0)
                return string.format('%d:%02d', t // 60, t % 60)
            end
            hudTime.Text = track and (clock(at) .. ' / ' .. clock(length)) or ''
        end
        if hudBarFill then
            hudBarFill.Size = UDim2.fromScale(length > 0 and math.clamp(at / length, 0, 1) or 0, 1)
        end
    end

    local function setPulseTransparency(transparency)
        local value = math.clamp(transparency, 0, 1)
        if pulseWhole then
            pulseWhole.BackgroundTransparency = value
        end
        for _, edge in ipairs(pulseEdges) do
            edge.BackgroundTransparency = value
        end
    end

    local stopFovPulse

    local FOV_ATTACK = 30
    local FOV_DECAY = 8
    local FOV_BUMP_MIN = 2
    local FOV_BUMP_MAX = 20
    local fovBump, fovBumpAt = 0, 0

    local function applyFovPulse(delta)
        local camera = workspace.CurrentCamera
        if not camera then return end
        local now = os.clock()
        local step = math.clamp(delta or 0, 0, 0.1)
        local target = fovBump > 0 and fovBump * math.exp(-FOV_DECAY * (now - fovBumpAt)) or 0
        local speed = target > fovOffset and FOV_ATTACK or FOV_DECAY
        fovOffset += (target - fovOffset) * (1 - math.exp(-step * speed))
        local gameFov = camera.FieldOfView - fovOffset
        if target <= 0.01 and fovOffset <= 0.05 then
            fovOffset, fovBump = 0, 0
            camera.FieldOfView = gameFov
            stopFovPulse()
            return
        end
        camera.FieldOfView = gameFov + fovOffset
    end

    local function startFovPulse(amount)
        local current = fovBump > 0 and fovBump * math.exp(-FOV_DECAY * (os.clock() - fovBumpAt)) or 0
        fovBump, fovBumpAt = math.max(amount, current), os.clock()
        if fovBound then return end
        fovBound = true
        runService:BindToRenderStep(FOV_STEP_NAME, Enum.RenderPriority.Last.Value, applyFovPulse)
        fovPreRender = runService.PreRender:Connect(function()
            applyFovPulse(0)
        end)
    end

    stopFovPulse = function()
        local camera = workspace.CurrentCamera
        if camera and fovOffset ~= 0 then
            camera.FieldOfView = camera.FieldOfView - fovOffset
        end
        fovBump, fovBumpAt, fovOffset, fovBase = 0, 0, 0, nil
        if fovBound then
            fovBound = false
            runService:UnbindFromRenderStep(FOV_STEP_NAME)
        end
        if fovPreRender then
            fovPreRender:Disconnect()
            fovPreRender = nil
        end
    end

    local function resetBeatLock()
        table.clear(beatTimes)
        tempo, nextBeat, offBeat = nil, 0, 0
    end

    local function resetPulse()
        setPulseTransparency(1)
        stopFovPulse()
        beatCooldown = 0
        loudnessAverage, lastLoudness = 0, 0
        resetBeatLock()
    end

    local function beatInterval()
        local gaps = {}
        for index = 2, #beatTimes do
            local gap = beatTimes[index] - beatTimes[index - 1]
            if gap >= 0.24 and gap <= 1.6 then
                table.insert(gaps, gap)
            end
        end
        if #gaps < LOCK_SAMPLES then return nil end
        table.sort(gaps)
        local median = gaps[math.floor((#gaps + 1) / 2)]
        local agreeing = 0
        for _, gap in gaps do
            if math.abs(gap - median) <= median * 0.18 then agreeing += 1 end
        end
        return agreeing >= LOCK_SAMPLES and median or nil
    end

    local function onOnset(now)
        table.insert(beatTimes, now)
        while #beatTimes > 10 do
            table.remove(beatTimes, 1)
        end

        if tempo then
            if math.abs(now - nextBeat) <= tempo * LOCK_TOLERANCE then
                nextBeat = now + tempo
                offBeat = 0
            else
                offBeat += 1
                if offBeat >= 3 then
                    local interval = beatInterval()
                    tempo, nextBeat, offBeat = interval, interval and now + interval or 0, 0
                end
            end
            return false
        end

        local interval = beatInterval()
        if interval then
            tempo, nextBeat, offBeat = interval, now + interval, 0
        end
        return true
    end

    local function firePulse(peak)
        local intensity = math.clamp((PulseIntensity and PulseIntensity.Value or 55) / 100, 0, 1)
        local strength = math.clamp(intensity * (0.55 + peak * 0.45), 0, 1)
        if (PulseType and PulseType.Value or 'FOV') == 'FOV' then
            startFovPulse(FOV_BUMP_MIN + intensity * (FOV_BUMP_MAX - FOV_BUMP_MIN))
            return
        end
        local colour = PulseColor and Color3.fromHSV(PulseColor.Hue or 0, PulseColor.Sat or 0, PulseColor.Value == nil and 1 or PulseColor.Value) or Color3.new(1, 1, 1)
        if pulseWhole then
            pulseWhole.BackgroundColor3 = colour
        end
        for _, edge in ipairs(pulseEdges) do
            edge.BackgroundColor3 = colour
        end
        setPulseTransparency(1 - strength)
    end

    local function pulseFromBeat(loudness)
        if not PulseToBeat.Enabled or not sound or not sound.IsPlaying then return end
        local now = os.clock()
        local onset = false

        if loudness <= 0 then
            lastLoudness = 0
        else
            if loudnessAverage <= 0 then
                loudnessAverage = loudness
            else
                loudnessAverage = loudnessAverage * 0.9 + loudness * 0.1
            end

            local rising = loudness >= lastLoudness
            lastLoudness = loudness
            local threshold = math.max(loudnessAverage * 1.3, 15)
            if rising and loudness >= threshold and now >= beatCooldown then
                beatCooldown = now + 0.18
                onset = true
            end
        end

        local peak = math.clamp(loudness / math.max(loudnessAverage, 1) - 1, 0, 1)
        if onset and onOnset(now) then
            firePulse(peak)
        end

        if tempo and now >= nextBeat then
            firePulse(math.max(peak, 0.5))
            nextBeat += tempo
            if nextBeat < now then nextBeat = now + tempo end
        end
    end

    local function stop()
        if sound then
            pcall(function()
                sound:Stop()
            end)
        end
        resetPulse()
    end

    local function applyLoop()
        if not (sound and Loop and Shuffle) then return end
        sound.Looped = Loop.Enabled and not Shuffle.Enabled
    end

    local function play(newIndex, attempt)
        attempt = attempt or 0
        if #tracks <= 0 or attempt >= #tracks then
            if #tracks > 0 then
                notif('MP3Player', 'None of the songs in the folder could be played', 5, 'warning')
            end
            index = 0
            loadFailures = 0
            refreshHUD()
            resetPulse()
            return
        end
        index = ((newIndex - 1) % #tracks) + 1
        local track = tracks[index]
        local asset = track and assetFor(track.Path)
        if not asset then
            notif('MP3Player', 'Skipping ' .. (track and track.Name or 'a song') .. ' - it could not be loaded', 4, 'warning')
            play(index + 1, attempt + 1)
            return
        end
        if not sound then return end

        lastPlay = tick()
        loadDeadline = tick() + 5
        sound.SoundId = asset
        sound.Volume = Volume.Value / 100
        sound.TimePosition = 0
        applyLoop()
        resetPulse()
        pcall(function()
            sound:Play()
        end)
        refreshHUD()
    end

    local function advance(step)
        if #tracks <= 0 then return end
        if Shuffle.Enabled and #tracks > 1 then
            local pick = index
            for _ = 1, 8 do
                pick = math.random(1, #tracks)
                if pick ~= index then break end
            end
            play(pick)
            return
        end
        play(index + step)
    end

    MP3Player = Main:Part({
		Label = 'Player',
        Name = 'MP3Player',
        Function = function(callback)
            if callback then
                if not (listfiles and getcustomasset) then
                    notif('MP3Player', 'Your executor cannot read local files, so there is nothing to play', 6, 'warning')
                    return task.spawn(function()
                        if MP3Player.Enabled then MP3Player:Toggle() end
                    end)
                end
                if isfolder and makefolder then
                    if not isfolder(SONGS) then makefolder(SONGS) end
                end

                sound = Instance.new('Sound')
                sound.Name = 'AetherMP3'
                sound.Volume = Volume.Value / 100
                sound.Parent = soundService
                MP3Player:Clean(sound)
                MP3Player:Clean(sound.Ended:Connect(function()
                    if not MP3Player.Enabled then return end
                    advance(1)
                end))

                if MP3Player.Children then
                    MP3Player.Children.Visible = ShowHUD.Enabled
                end

                scan(true)
                if #tracks > 0 then
                    play(Shuffle.Enabled and math.random(1, #tracks) or 1)
                end

                MP3Player:Clean(runService.RenderStepped:Connect(function()
                    if PulseToBeat.Enabled and sound and sound.IsPlaying then
                        pulseFromBeat(sound.PlaybackLoudness)
                    else
                        resetPulse()
                    end

                    if pulseWhole and pulseWhole.BackgroundTransparency < 1 then
                        setPulseTransparency(math.min(1, pulseWhole.BackgroundTransparency + 0.08))
                    end
                end))

                MP3Player:Clean(task.spawn(function()
                    while MP3Player.Enabled do
                        if tick() - lastScan > 3 then
                            lastScan = tick()
                            local changed = scan(true)
                            if changed and sound and not sound.IsPlaying and #tracks > 0 then
                                play(index > 0 and index or 1)
                            end
                        end
                        local track = tracks[index]
                        if sound and track and sound.SoundId ~= '' then
                            if sound.IsPlaying or sound.IsPaused then
                                loadDeadline = 0
                                loadFailures = 0
                            elseif loadDeadline > 0 and tick() > loadDeadline then
                                loadDeadline = 0
                                loadFailures += 1
                                if loadFailures >= #tracks then
                                    notif('MP3Player', 'No song in the folder would play', 5, 'warning')
                                    index = 0
                                    sound.SoundId = ''
                                    refreshHUD()
                                    resetPulse()
                                else
                                    notif('MP3Player', 'Skipping ' .. track.Name .. ' - it would not play', 4, 'warning')
                                    advance(1)
                                end
                            elseif sound.IsLoaded and (tick() - lastPlay) > 1 then
                                advance(1)
                            end
                        end
                        refreshHUD()
                        task.wait(0.2)
                    end
                end))
            else
                stop()
                sound = nil
                index = 0
                scanKey = ''
                loadDeadline = 0
                loadFailures = 0
                refreshHUD()
            end
        end,
        Tooltip = 'Plays your mp3 files from the ElevateV4/songs folder',
        Size = UDim2.fromOffset(236, 66),
        ExtraText = function()
            local track = tracks[index]
            return track and track.Name or nil
        end
    })

    if MP3Player.Children then
        local hud = MP3Player.Children
        if hud.Position == UDim2.new() then
            hud.Position = UDim2.fromOffset(16, 340)
        end
        hudBackground = Instance.new('Frame')
        hudBackground.Size = UDim2.fromScale(1, 1)
        hudBackground.BackgroundColor3 = Color3.new()
        hudBackground.BackgroundTransparency = 0.35
        hudBackground.BorderSizePixel = 0
        hudBackground.Parent = hud
        local corner = Instance.new('UICorner')
        corner.CornerRadius = UDim.new(0, 5)
        corner.Parent = hudBackground

        local title = Instance.new('TextLabel')
        title.Size = UDim2.new(1, -14, 0, 16)
        title.Position = UDim2.fromOffset(9, 5)
        title.BackgroundTransparency = 1
        title.Font = Enum.Font.GothamBold
        title.TextSize = 12
        title.TextXAlignment = Enum.TextXAlignment.Left
        title.TextColor3 = Color3.fromRGB(170, 170, 170)
        title.Text = 'MP3Player'
        title.Parent = hudBackground

        hudName = Instance.new('TextLabel')
        hudName.Size = UDim2.new(1, -18, 0, 18)
        hudName.Position = UDim2.fromOffset(9, 21)
        hudName.BackgroundTransparency = 1
        hudName.Font = Enum.Font.GothamMedium
        hudName.TextSize = 13
        hudName.TextXAlignment = Enum.TextXAlignment.Left
        hudName.TextTruncate = Enum.TextTruncate.AtEnd
        hudName.TextColor3 = Color3.new(1, 1, 1)
        hudName.Text = 'No song loaded'
        hudName.Parent = hudBackground

        hudTime = Instance.new('TextLabel')
        hudTime.Size = UDim2.new(1, -18, 0, 14)
        hudTime.Position = UDim2.fromOffset(-9, 5)
        hudTime.BackgroundTransparency = 1
        hudTime.Font = Enum.Font.Gotham
        hudTime.TextSize = 11
        hudTime.TextXAlignment = Enum.TextXAlignment.Right
        hudTime.TextColor3 = Color3.new(1, 1, 1)
        hudTime.Text = ''
        hudTime.Parent = hudBackground

        local bar = Instance.new('Frame')
        bar.Size = UDim2.new(1, -18, 0, 4)
        bar.Position = UDim2.fromOffset(9, 46)
        bar.BackgroundColor3 = Color3.fromRGB(70, 70, 70)
        bar.BorderSizePixel = 0
        bar.Parent = hudBackground
        local barCorner = Instance.new('UICorner')
        barCorner.CornerRadius = UDim.new(1, 0)
        barCorner.Parent = bar

        hudBarFill = Instance.new('Frame')
        hudBarFill.Size = UDim2.fromScale(0, 1)
        hudBarFill.BackgroundColor3 = Color3.new(1, 1, 1)
        hudBarFill.BorderSizePixel = 0
        hudBarFill.Parent = bar
        local fillCorner = Instance.new('UICorner')
        fillCorner.CornerRadius = UDim.new(1, 0)
        fillCorner.Parent = hudBarFill
    end

    
    pulseWhole = Instance.new('Frame')
    pulseWhole.Name = 'AetherMP3BeatPulse'
    pulseWhole.Size = UDim2.fromScale(1, 1)
    pulseWhole.Position = UDim2.fromScale(0, 0)
    pulseWhole.BackgroundColor3 = Color3.new(1, 1, 1)
    pulseWhole.BackgroundTransparency = 1
    pulseWhole.BorderSizePixel = 0
    pulseWhole.ZIndex = 40
    pulseWhole.Visible = false
    pulseWhole.Parent = vape.gui

    for _, spec in ipairs({
        {Name = 'Top', Size = UDim2.new(1, 0, 0.18, 0), Position = UDim2.fromScale(0, 0), Rotation = 90},
        {Name = 'Bottom', Size = UDim2.new(1, 0, 0.18, 0), Position = UDim2.fromScale(0, 0.82), Rotation = 270},
        {Name = 'Left', Size = UDim2.new(0.14, 0, 0.64, 0), Position = UDim2.fromScale(0, 0.18), Rotation = 0},
        {Name = 'Right', Size = UDim2.new(0.14, 0, 0.64, 0), Position = UDim2.fromScale(0.86, 0.18), Rotation = 180}
    }) do
        local edge = Instance.new('Frame')
        edge.Name = spec.Name
        edge.Size = spec.Size
        edge.Position = spec.Position
        edge.BackgroundColor3 = Color3.new(1, 1, 1)
        edge.BackgroundTransparency = 1
        edge.BorderSizePixel = 0
        edge.ZIndex = 40
        edge.Visible = false
        edge.Parent = pulseWhole
        local gradient = Instance.new('UIGradient')
        gradient.Rotation = spec.Rotation
        gradient.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0),
            NumberSequenceKeypoint.new(1, 1)
        })
        gradient.Parent = edge
        table.insert(pulseEdges, edge)
    end

    MP3Player:CreateButton({
        Name = 'Play / Pause',
        Function = function()
            if not sound then return end
            if sound.IsPlaying then
                sound:Pause()
            elseif sound.SoundId ~= '' then
                sound:Resume()
            else
                play(index > 0 and index or 1)
            end
        end,
        Tooltip = 'Pause or resume the current song'
    })
    MP3Player:CreateButton({
        Name = 'Next song',
        Function = function()
            advance(1)
        end
    })
    MP3Player:CreateButton({
        Name = 'Previous song',
        Function = function()
            advance(-1)
        end
    })
    MP3Player:CreateButton({
        Name = 'Refresh songs',
        Function = function()
            lastScan = tick()
            scan(true)
            refreshHUD()
        end,
        Tooltip = 'Reloads the songs folder'
    })
    Volume = MP3Player:CreateSlider({
        Name = 'Volume',
        Min = 0,
        Max = 100,
        Default = 40,
        Suffix = '%',
        Function = function(val)
            if sound then
                sound.Volume = val / 100
            end
        end
    })
    Shuffle = MP3Player:CreateToggle({
        Name = 'Shuffle',
        Function = applyLoop,
        Tooltip = 'Pick the next song at random instead of in order'
    })
    Loop = MP3Player:CreateToggle({
        Name = 'Loop song',
        Function = applyLoop,
        Tooltip = 'Repeat the current song instead of moving on'
    })
    PlayField = MP3Player:CreateTextBox({
        Name = 'Play song',
        Placeholder = 'song name',
        Function = function(enter)
            if not enter then return end
            local val = PlayField and PlayField.Value or ''
            if val == '' then return end
            scan(false)
            local needle = val:lower()
            for i, track in tracks do
                if track.Name:lower():find(needle, 1, true) then
                    play(i)
                    return
                end
            end
            notif('MP3Player', 'No song matching "' .. val .. '"', 4, 'warning')
        end,
        Tooltip = 'Type part of a song name to jump straight to it'
    })
    Playlist = MP3Player:CreateTextList({
        Name = 'Playlist',
        Placeholder = 'song name',
        Function = function()
            scan(true)
        end,
        Tooltip = 'Songs to play in order, empty plays everything'
    })
    ShowHUD = MP3Player:CreateToggle({
        Name = 'Show HUD',
        Default = true,
        Tooltip = 'Shows the now-playing panel',
        Function = function(callback)
            if MP3Player.Children then
                MP3Player.Children.Visible = callback and MP3Player.Enabled
            end
        end
    })
    local function refreshPulseOptions()
        local on = PulseToBeat and PulseToBeat.Enabled
        local kind = PulseType and PulseType.Value or 'FOV'
        local regions = PulseRegions and PulseRegions.Value or 'Whole'
        if PulseType and PulseType.Object then PulseType.Object.Visible = on end
        if PulseIntensity and PulseIntensity.Object then PulseIntensity.Object.Visible = on end
        if PulseColor and PulseColor.Object then PulseColor.Object.Visible = on and kind == 'Colour' end
        if PulseRegions and PulseRegions.Object then PulseRegions.Object.Visible = on and kind == 'Colour' end
        if pulseWhole then
            pulseWhole.Visible = on and kind == 'Colour'
            pulseWhole.BackgroundTransparency = 1
        end
        for _, edge in ipairs(pulseEdges) do
            edge.Visible = on and kind == 'Colour' and regions == 'Border'
            edge.BackgroundTransparency = 1
        end
        if not on then resetPulse() end
    end

    PulseToBeat = MP3Player:CreateToggle({
        Name = 'Pulse to Beat',
        Function = function()
            refreshPulseOptions()
        end,
        Tooltip = 'Pulses the screen to the beat of the current song'
    })
    PulseType = MP3Player:CreateDropdown({
        Name = 'Type',
        List = { 'FOV', 'Colour' },
        Default = 'FOV',
        Darker = true,
        Function = refreshPulseOptions,
        Tooltip = 'FOV - bumps your field of view\nColour - pulses an overlay',
    })
    PulseIntensity = MP3Player:CreateSlider({
        Name = 'Intensity',
        Min = 1,
        Max = 100,
        Default = 55,
        Suffix = '%',
        Darker = true,
        Tooltip = 'How strong the pulse is',
    })
    PulseColor = MP3Player:CreateColorSlider({
        Name = 'Pulse Colour',
        Darker = true,
        DefaultSat = 0,
        DefaultValue = 1,
        Tooltip = 'Colour used by the Colour pulse type',
    })
    PulseRegions = MP3Player:CreateDropdown({
        Name = 'Regions',
        List = { 'Whole', 'Border' },
        Default = 'Whole',
        Darker = true,
        Function = refreshPulseOptions,
        Tooltip = 'Pulses the whole screen or only its edges',
    })
    refreshPulseOptions()
end)

run(function()
    local SongBeats
    local List
    local FOV
    local FOVValue = {}
    local Volume
    local alreadypicked = {}
    local beattick = tick()
    local oldfov, songobj, songbpm, songtween

    local function choosesong()
        local list = List.ListEnabled
        if #alreadypicked >= #list then
            table.clear(alreadypicked)
        end

        if #list <= 0 then
            notif('SongBeats', 'no songs', 10)
            SongBeats:Toggle()
            return
        end

        local chosensong = list[math.random(1, #list)]
        if #list > 1 and table.find(alreadypicked, chosensong) then
            repeat
                task.wait()
                chosensong = list[math.random(1, #list)]
            until not table.find(alreadypicked, chosensong) or not SongBeats.Enabled
        end
        if not SongBeats.Enabled then return end

        local split = chosensong:split('/')
        if not isfile(split[1]) then
            notif('SongBeats', 'Missing song ('..split[1]..')', 10)
            SongBeats:Toggle()
            return
        end

        songobj.SoundId = assetfunction(split[1])
        repeat task.wait() until songobj.IsLoaded or not SongBeats.Enabled
        if SongBeats.Enabled then
            beattick = tick() + (tonumber(split[3]) or 0)
            songbpm = 60 / (tonumber(split[2]) or 50)
            songobj:Play()
        end
    end

    SongBeats = Main:Part({
		Label = 'Song beats',
		Default = false,
        Name = 'SongBeats',
        Function = function(callback)
            if callback then
                songobj = Instance.new('Sound')
                songobj.Volume = Volume.Value / 100
                songobj.Parent = workspace
                repeat
                    if not songobj.Playing then choosesong() end
                    if beattick < tick() and SongBeats.Enabled and FOV.Enabled then
                        beattick = tick() + songbpm
                        oldfov = math.min(bedwars.FovController:getFOV() * (bedwars.SprintController.sprinting and 1.1 or 1), 120)
                        gameCamera.FieldOfView = oldfov - FOVValue.Value
                        songtween = tweenService:Create(gameCamera, TweenInfo.new(math.min(songbpm, 0.2), Enum.EasingStyle.Linear), {FieldOfView = oldfov})
                        songtween:Play()
                    end
                    task.wait()
                until not SongBeats.Enabled
            else
                if songobj then
                    songobj:Destroy()
                end
                if songtween then
                    songtween:Cancel()
                end
                if oldfov then
                    gameCamera.FieldOfView = oldfov
                end
                table.clear(alreadypicked)
            end
        end,
        Tooltip = 'Plays your mp3 files'
    })
    List = SongBeats:CreateTextList({
        Name = 'Songs',
        Placeholder = 'filepath/bpm/start'
    })
    FOV = SongBeats:CreateGroup({
        Name = 'Beat FOV',
        Function = function(callback)
            if FOVValue and FOVValue.Object then
            end
            if SongBeats.Enabled then
                SongBeats:Toggle()
                SongBeats:Toggle()
            end
        end,
        Default = true
    })
    FOVValue = FOV:CreateSlider({
        Name = 'Adjustment',
        Min = 1,
        Max = 30,
        Default = 5,
        Darker = true
    })
    Volume = SongBeats:CreateSlider({
        Name = 'Beat volume',
        Function = function(val)
            if songobj then
                songobj.Volume = val / 100
            end
        end,
        Min = 1,
        Max = 100,
        Default = 100,
        Suffix = '%'
    })
end)

end)

-- ===== Utility/MemoryFixer.lua =====
run(function()
	local MemoryFixer
	local Sync
	local Interval
	local Notify
	local signals = {'Heartbeat', 'PostSimulation', 'PreAnimation', 'PreRender', 'PreSimulation', 'RenderStepped', 'Stepped'}
	
	local hashes = setmetatable({}, {__mode = 'k'})
	local function hashOf(fn)
		local hash = hashes[fn]
		if not hash then
			hash = getfunctionhash(fn)
			hashes[fn] = hash
		end
		return hash
	end

	local function clean()
		if not getconnections or not getfunctionhash or not isexecutorclosure then
			return 0
		end
	
		local removed, seen = 0, {}
		local started = os.clock()
		for index, v in signals do
			if index > 1 then
				task.wait()
				started = os.clock()
			end
			local profiler = vape.Libraries.profiler
			local signal = profiler and profiler.RealSignal(v) or runService[v]
			for _, connection in getconnections(signal) do
				if os.clock() - started > 0.002 then
					task.wait()
					started = os.clock()
				end
				if connection.Function and not connection.ForeignState and isexecutorclosure(connection.Function) then
					local fn = profiler and profiler.Unwrap(connection.Function) or connection.Function
					local hash = v..hashOf(fn)
					if seen[hash] then
						connection:Disconnect()
						removed += 1
					else
						seen[hash] = true
					end
				end
			end
		end
	
		if Sync.Enabled then
			for _, event in bedwars.SyncEvents or {} do
				if typeof(event) == 'table' and typeof(event.entries) == 'table' then
					table.clear(seen)
					for i, entry in event.entries do
						local callback = entry.callbackInfo and entry.callbackInfo.callback
						if callback and isexecutorclosure(callback) then
							local profiler = vape.Libraries.profiler
							local hash = hashOf(profiler and profiler.Unwrap(callback) or callback)
							if seen[hash] then
								event.entries[i] = nil
								event.isSorted = false
								removed += 1
							else
								seen[hash] = true
							end
						end
					end
				end
			end
		end
	
		return removed
	end
	
	MemoryFixer = vape.Categories.Utility:CreateModule({
		Name = 'MemoryFixer',
		Function = function(callback)
			if callback then
				MemoryFixer:Clean(task.spawn(function()
					repeat
						local removed = clean()
						if Notify.Enabled and removed > 0 then
							notif('MemoryFixer', `Dropped {removed} leftover connection{removed == 1 and '' or 's'}`, 5)
						end
						task.wait(Interval.Value)
					until not MemoryFixer.Enabled
				end))
			end
		end,
		Tooltip = 'Clears leftovers from earlier injections'
	})
	Sync = MemoryFixer:CreateToggle({
		Name = 'Sync events',
		Default = true,
		Tooltip = 'Also clears duplicate game event listeners'
	})
	Interval = MemoryFixer:CreateSlider({
		Name = 'Interval',
		Min = 5,
		Max = 300,
		Default = 30,
		Suffix = 'seconds'
	})
	Notify = MemoryFixer:CreateToggle({
		Name = 'Notify',
		Default = true,
		Tooltip = 'Tells you how many it dropped'
	})
	MemoryFixer:CreateButton({
		Name = 'Clean now',
		Function = function()
			local removed = clean()
			notif('MemoryFixer', `Dropped {removed} leftover connection{removed == 1 and '' or 's'}`, 5)
		end
	})
end)

-- ===== Utility/PearlTP.lua =====
run(function()
	local PearlTP
	local Legit
	local Limit
	local SwitchBack

	local rayCheck = RaycastParams.new()
	rayCheck.FilterType = Enum.RaycastFilterType.Exclude
	rayCheck.RespectCanCollide = true

	local function getMouseTarget(mousePosition)
		if not entitylib.isAlive then return nil end
		rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera}
		local ray = gameCamera:ViewportPointToRay(mousePosition.X, mousePosition.Y)
		local result = workspace:Raycast(ray.Origin, ray.Direction * 2048, rayCheck)
		return result and result.Position
	end

	local function getPathObstacle(origin, velocity, speed, gravity, target)
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = {lplr.Character, gameCamera}
		params.RespectCanCollide = true

		local step, previous = 0.05, origin
		for i = 1, 40 do
			local flight = i * step
			local point = origin + velocity.Unit * (speed * flight) + Vector3.new(0, -0.5 * gravity * flight * flight, 0)
			if (point - target).Magnitude <= 1 then
				break
			end
			local segment = point - previous
			if segment.Magnitude > 0 then
				local hit = workspace:Raycast(previous, segment, params)
				if hit then
					return hit
				end
			end
			previous = point
		end
		return nil
	end

	local function throwPearl(target)
		if not entitylib.isAlive then notif('PearlTP', 'Character missing.', 3, 'warning'); return false end
		local pearl = getItem('telepearl')
		if not pearl or not pearl.tool then notif('PearlTP', 'No telepearl available.', 3, 'warning'); return false end

		local old = store.hand
		if Limit.Enabled and (not old or not old.tool or old.tool.Name:lower() ~= 'telepearl') then
			notif('PearlTP', 'Hold a telepearl first.', 3, 'warning')
			return false
		end

		local meta = bedwars.ProjectileMeta.telepearl
		if not meta or not meta.launchVelocity then
			notif('PearlTP', 'Telepearl projectile data unavailable.', 3, 'warning')
			return false
		end

		local origin = entitylib.character.RootPart.Position
		local speed, gravity = meta.launchVelocity, meta.gravitationalAcceleration or 196.2

		local calc = prediction.SolveTrajectory(origin, speed, gravity, target, Vector3.zero, 0, 0, 0, nil, false, target, nil, nil, true)
		if not calc then
			notif('PearlTP', 'Target is too far away for the telepearl.', 4, 'warning')
			return false
		end

		local constants = bedwars.BowConstantsTable or {}
		local shootPosition = (CFrame.new(origin, calc) * CFrame.new(Vector3.new(
			-(tonumber(constants.RelX) or 0),
			-(tonumber(constants.RelY) or 0),
			-(tonumber(constants.RelZ) or 0)
		))).Position
		local aim = prediction.SolveTrajectory(shootPosition, speed, gravity, target, Vector3.zero, 0, 0, 0, nil, false, target, nil, nil, true) or calc
		local direction = CFrame.lookAt(shootPosition, aim).LookVector * speed

		local obstacle = getPathObstacle(shootPosition, direction, speed, gravity, target)
		if obstacle and obstacle.Instance then
			notif('PearlTP', 'Obstacle in the way of the pearl (' .. obstacle.Instance.Name .. ')', 4, 'warning')
			return false
		end

		switchItem(pearl.tool)
		if Legit.Enabled then
			local hotbar = getHotbar(pearl.tool)
			if hotbar then hotbarSwitch(hotbar) end
		end

		local success = pcall(function()
			bedwars.Handler:Get('ProjectileFire'):Fire('CallServerAsync',
				pearl.tool,
				'telepearl',
				'telepearl',
				shootPosition,
				origin,
				direction,
				httpService:GenerateGUID(true),
				{
					drawDurationSeconds = 1,
					shotId = httpService:GenerateGUID(false)
				},
				workspace:GetServerTimeNow() - 0.045
			)
		end)

		if SwitchBack.Enabled and old and old.tool and old.tool ~= pearl.tool then
			switchItem(old.tool)
			if Legit.Enabled then
				local oldHotbar = getHotbar(old.tool)
				if oldHotbar then hotbarSwitch(oldHotbar) end
			end
		end
		return success
	end

	PearlTP = vape.Categories.Utility:CreateModule({
		Name = 'PearlTP',
		Function = function(callback)
			if not callback then return end
			local mousePosition = inputService:GetMouseLocation()
			local target = getMouseTarget(mousePosition)
			if not target then
				notif('PearlTP', 'No valid position under the mouse.', 3, 'warning')
				PearlTP:Toggle()
				return
			end
			throwPearl(target)
			PearlTP:Toggle()
		end,
		Tooltip = 'Throws a telepearl to the spot under your cursor'
	})

	Legit = PearlTP:CreateToggle({Name = 'Legit Switch', Default = true, Tooltip = 'Visibly switches items on your hotbar'})
	Limit = PearlTP:CreateToggle({Name = 'Limit to item', Tooltip = 'Only works while holding the item it uses'})
	SwitchBack = PearlTP:CreateToggle({Name = 'Switch back', Default = true, Tooltip = 'Switches back to your last item afterwards'})
end)

-- ===== Utility/PickupRange.lua =====
run(function()
    local PickupRange
    local Range
    local Network
    local Lower
    local Delay

    PickupRange = vape.Categories.Utility:CreateModule({
        Name = 'PickupRange',
        Function = function(callback)
            if callback then
                local items = collection('ItemDrop', PickupRange)
                local picked = setmetatable({}, {__mode = 'k'})
                repeat
                    if entitylib.isAlive then
                        local localPosition = entitylib.character.RootPart.Position
                        for _, v in items do
                            if tick() - (v:GetAttribute('ClientDropTime') or 0) < Delay.Value or (picked[v] or 0) > tick() then continue end
                            if isnetworkowner(v) and Network.Enabled and entitylib.character.Humanoid.Health > 0 then
                                v.CFrame = CFrame.new(localPosition - Vector3.new(0, 3, 0))
                            end

                            if (localPosition - v.Position).Magnitude <= Range.Value then
                                if Lower.Enabled and (localPosition.Y - v.Position.Y) < (entitylib.character.HipHeight - 1) then continue end
                                picked[v] = tick() + 1
                                task.spawn(function()
                                    bedwars.Client:Get(remotes.PickupItem):CallServerAsync({
                                        itemDrop = v
                                    }):andThen(function(suc)
                                        picked[v] = nil
                                        if suc and bedwars.SoundList then
                                            bedwars.SoundManager:playSound(bedwars.SoundList.PICKUP_ITEM_DROP)
                                            local sound = bedwars.ItemMeta[v.Name].pickUpOverlaySound
                                            if sound then
                                                bedwars.SoundManager:playSound(sound, {
                                                    position = v.Position,
                                                    volumeMultiplier = 0.9
                                                })
                                            end
                                        end
                                    end)
                                end)
                            end
                        end
                    end
                    task.wait(0.05)
                until not PickupRange.Enabled
            end
        end,
        Tooltip = 'Picks up items from further away'
    })
    Range = PickupRange:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 10,
        Default = 10,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
    Network = PickupRange:CreateToggle({
        Name = 'Network TP',
        Default = true
    })
    Lower = PickupRange:CreateToggle({Name = 'Feet Check'})
    Delay = PickupRange:CreateSlider({
        Name = 'Pickup delay',
        Min = 0,
        Max = 2,
        Default = 2,
        Decimal = 10,
        Suffix = 's',
        Tooltip = 'How long a drop must be on the ground before it is picked up'
    })
end)

-- ===== Utility/RegionLock.lua =====
run(function()
	local HttpService = httpService
	local LocalPlayer = lplr
	local SendNotification = notif
	local Store = store
	local TeleportService = cloneref(game:GetService('TeleportService'))
	local RegionLock
	local Regions
	local Timeout
	local Requeue

	local Status: string = "Next match"
	local ServerRegion: string?
	local Warned: boolean = false
	local Requeued: boolean = false
	local RequeueTries: number = 0
	local RequeueRetry: number = 0
	local Aliases: {[string]: string} = {
		AU = "SEA",
		AUS = "SEA",
		AUSTRALIA = "SEA",
		NZ = "SEA",
		OCE = "SEA",
		OCEANIA = "SEA",
		AS = "SEA",
		ASIA = "SEA",
		SG = "SEA",
		SGP = "SEA",
		US = "NA",
		USA = "NA",
		AMERICA = "NA",
		EUROPE = "EU",
		GB = "EU",
		UK = "EU"
	}

	local function Canonical(Value: string): string
		Value = tostring(Value):gsub("%s+", ""):upper()
		if Value:match("^SG%-%d+$") then
			return "SEA"
		end
		return Aliases[Value] or Value
	end

	local function GetRegion(): string?
		local Display: Instance? = LocalPlayer.PlayerGui:FindFirstChild("ServerRegionDisplay")
		local Label: TextLabel? = Display and Display:FindFirstChild("ServerRegionText")
		local Region: string? = Label and Label.Text:gsub("<[^>]+>", ""):match("REGION:%s*(%S+)") or nil
		if not Region then
			local State = bedwars.Store:getState().Game
			Region = type(State) == "table" and type(State.serverRegion) == "string" and State.serverRegion ~= "" and State.serverRegion or nil
		end
		if Region then
			ServerRegion = Region
		end
		return ServerRegion
	end

	local function IsRegionAllowed(): boolean
		if #Regions.ListEnabled == 0 then
			return true
		end

		local Region = GetRegion()
		if not Region then
			return false
		end

		Region = Canonical(Region)
		for _, v: string in Regions.ListEnabled do
			v = Canonical(v)
			if v ~= "" and Region:sub(1, #v) == v then
				return true
			end
		end
		return false
	end

	local function RequeueMatch(): string?
		local State = bedwars.Store:getState()
		if Requeued or State.Party.queueState ~= 0 then
			Requeued = true
			return "Requeued"
		end

		local Data = TeleportService:GetLocalPlayerTeleportData()
		if (type(Data) == "table" and Data.customMatch) or State.Game.customMatch or State.Party.leader.userId ~= LocalPlayer.UserId then
			return nil
		end

		local Match = type(Data) == "table" and Data.match
		local QueueType: string? = Match and Match.queueType or Store.queueType
		local Meta = QueueType and bedwars.QueueMeta[QueueType]
		if not Meta or Meta.disabled then
			return nil
		end

		if os.clock() >= RequeueRetry then
			if RequeueTries >= 3 then
				return "Requeue failed"
			end
			RequeueTries += 1
			RequeueRetry = os.clock() + 5
			pcall(bedwars.QueueController.joinQueue, bedwars.QueueController, QueueType)
		end
		return "Requeueing"
	end

	local function Release()
		if not getgenv().matchDodgeActive then
			if getgenv().dodged and not Store.readyHold.Remote then
				bedwars.Handler:Get("PlayerConnect"):Fire("SendToServer", TeleportService:GetLocalPlayerTeleportData())
			end
			Store.readyHold.Release()
			getgenv().dodged = false
		end
	end

	RegionLock = vape.Categories.Utility:CreateModule({
		Name = "RegionLock",
		Function = function(Callback: boolean)
			writefile(`ElevateV4/profiles/regionlock.txt`, tostring(Callback))
			getgenv().regionLockActive = Callback
			getgenv().regionLockAllowed = not Callback
			if Callback then
				Store.readyHold.Claimed = true
				RegionLock:Clean(coroutine.running())
				Warned = false
				repeat
					if not getgenv().dodged and not Store.readyHold.Held then
						Status = LocalPlayer:GetAttribute("PlayerConnected") and "Loaded" or "Next match"
					else
						local Started: number = Store.readyHold.Started or os.clock()
						getgenv().regionLockAllowed = IsRegionAllowed()
						if getgenv().regionLockAllowed then
							Status = ServerRegion or "Any region"
							Release()
						elseif ServerRegion then
							local RequeueStatus: string? = Requeue.Enabled and RequeueMatch() or nil
							Status = `{RequeueStatus or "Wrong region"} ({ServerRegion})`
						elseif Timeout.Value > 0 and (os.clock() - Started) >= Timeout.Value then
							if not Warned then
								Warned = true
								SendNotification("RegionLock", "Could not read this server region, loading anyway", 8, "warning")
							end
							getgenv().regionLockAllowed = true
							Status = "Unknown region"
							Release()
						else
							Status = "Finding region"
						end
					end
					task.wait(0.5)
				until not RegionLock.Enabled
			else
				Release()
				Status = "Loaded"
				Store.readyHold.Claimed = getgenv().matchDodgeActive
			end
		end,
		Tooltip = 'Skips matches hosted outside your chosen regions',
		ExtraText = function()
			return Status
		end
	})

	Regions = RegionLock:CreateTextList({
		Name = "Regions",
		Placeholder = "NA / EU / SEA",
		Default = {"NA", "EU", "SEA"},
		Function = function()
			if not Regions then
				return
			end
			for i: number, v: string in Regions.List do
				Regions.List[i] = v:gsub("%s+", ""):upper()
			end
			for i: number, v: string in Regions.ListEnabled do
				Regions.ListEnabled[i] = v:gsub("%s+", ""):upper()
			end
		end,
		Tooltip = 'Regions to accept'
	})
	Timeout = RegionLock:CreateSlider({
		Name = "Timeout",
		Min = 0,
		Max = 120,
		Default = 20,
		Suffix = function(Value: number)
			return Value == 1 and "second" or "seconds"
		end,
		Tooltip = 'Loads anyway after this long, 0 waits forever'
	})
	Requeue = RegionLock:CreateToggle({
		Name = "Requeue",
		Tooltip = 'Queues again when the region is wrong'
	})
end)

