-- ===== World/ACMODView.lua =====
run(function()
	
	
	local KnitInit, Knit
	local knitDeadline = tick() + 30
	repeat
		KnitInit, Knit = pcall(function()
			return debug.getupvalue(require(lplr.PlayerScripts.TS.knit).setup, 9)
		end)
		if KnitInit and Knit then break end
		task.wait()
	until tick() > knitDeadline
	if not (KnitInit and Knit) then
		error('Knit never became available for the anticheat view module')
	end

	if not debug.getupvalue(Knit.Start, 1) then
		local upvalueDeadline = tick() + 15
		repeat task.wait() until debug.getupvalue(Knit.Start, 1) or tick() > upvalueDeadline
		if not debug.getupvalue(Knit.Start, 1) then
			error('debug.getupvalue is unavailable, so the anticheat view module cannot start')
		end
	end

	local Players = game:GetService("Players")

	shared.PERMISSION_CONTROLLER_HASANYPERMISSIONS_REVERT = shared.PERMISSION_CONTROLLER_HASANYPERMISSIONS_REVERT or Knit.Controllers.PermissionController.hasAnyPermissions
	shared.MATCH_CONTROLLER_GETPLAYERPARTY_REVERT = shared.MATCH_CONTROLLER_GETPLAYERPARTY_REVERT or Knit.Controllers.MatchController.getPlayerParty

	local AC_MOD_View = {
		playerConnections = {},
		Enabled = false,
		Friends = {},
		parties = {},
		teamMap = {},
		display = {},
		isRefreshing = false,
		cacheDirty = true,
		disable_disguises = false,
		disguises = {},
		teamData = {}
	}

	AC_MOD_View.controller = Knit.Controllers.PermissionController
	AC_MOD_View.match_controller = Knit.Controllers.MatchController

	function AC_MOD_View:getPartyById(displayId)
		if not displayId then return end
		displayId = tostring(displayId)
		if self.display[displayId] then return self.display[displayId] end
		for _, party in pairs(self.parties) do
			if party.displayId == tostring(displayId) then
				self.display[displayId] = party
				return party
			end
		end
	end

	function AC_MOD_View:refreshDisplayCache()
		for _, plr in pairs(Players:GetPlayers()) do
			local playerId = tostring(plr.UserId)

			local playerPartyId = self.teamMap[playerId]
			if playerPartyId ~= nil then
				self:getPartyById(playerPartyId)
			end
			task.wait()
		end
	end

	function AC_MOD_View:refreshDisplayCacheAsync()
		task.spawn(self.refreshDisplayCache, self)
	end

	function AC_MOD_View:getPlayerTeamData(plr)
		if self.teamData[plr] then return self.teamData[plr] end

		self.teamData[plr] = {}

		local teamMembers = {}
		local playerTeam = plr.Team
		if not playerTeam then
			return teamMembers
		end

		local playerId = tostring(plr.UserId)
		self.Friends[playerId] = self.Friends[playerId] or {}

		for _, otherPlayer in pairs(Players:GetPlayers()) do
			if otherPlayer == plr then continue end

			local otherPlayerId = tostring(otherPlayer.UserId)
			local areFriends = self.Friends[playerId][otherPlayerId]

			if areFriends == nil then
				local suc, res = pcall(function()
					return plr:IsFriendsWith(otherPlayer.UserId)
				end)
				areFriends = suc and res or false

				if suc then
					self.Friends = self.Friends or {}
					self.Friends[playerId] = self.Friends[playerId] or {}
					self.Friends[playerId][otherPlayerId] = areFriends
					self.Friends[otherPlayerId] = self.Friends[otherPlayerId] or {}
					self.Friends[otherPlayerId][playerId] = areFriends
				end
			end

			if areFriends and otherPlayer.Team == playerTeam then
				table.insert(teamMembers, otherPlayerId)
			end
		end

		self.teamData[plr] = teamMembers

		return teamMembers
	end

	function AC_MOD_View:refreshPlayerTeamData()
		for i,v in pairs(Players:GetPlayers()) do
			self:getPlayerTeamData(v)
			task.wait()
		end
	end

	function AC_MOD_View:refreshPlayerTeamDataAsync()
		task.spawn(self.refreshPlayerTeamData, self)
	end

	function AC_MOD_View:refreshTeamMap()
		local allTeams = {}
		for _, p in pairs(Players:GetPlayers()) do
			local teamMembers = self:getPlayerTeamData(p)
			if teamMembers and #teamMembers > 0 then
				allTeams[p] = teamMembers
			end
		end

		local validTeams = {}
		for playerInTeams, members in pairs(allTeams) do
			local playerIdInTeams = tostring(playerInTeams.UserId)
			local cleanedMembers = {}

			for _, memberId in pairs(members) do
				local memberIdStr = tostring(memberId)
				if memberIdStr == playerIdInTeams then
					
				else
					table.insert(cleanedMembers, memberIdStr)
				end
			end

			if #cleanedMembers > 0 then
				validTeams[playerInTeams] = cleanedMembers
			end
		end

		self.parties = {}
		self.teamMap = {}
		local teamId = 0
		for playerInTeams, members in pairs(validTeams) do
			local playerIdInTeams = tostring(playerInTeams.UserId)
			if not self.teamMap[playerIdInTeams] then
				self.teamMap[playerIdInTeams] = teamId
				table.insert(self.parties, {
					displayId = tostring(teamId),
					members = members
				})
				teamId = teamId + 1

				for _, memberId in pairs(members) do
					self.teamMap[memberId] = teamId - 1
				end
			end
		end

		self.cacheDirty = false
		self.isRefreshing = false
	end

	function AC_MOD_View:refreshTeamMapAsync()
		if self.isRefreshing then return end
		self.isRefreshing = true
		task.spawn(function()
			self:refreshTeamMap()
		end)
	end

	function AC_MOD_View:getPlayerParty(plr)
		if not plr or not plr:IsA("Player") then
			return nil
		end

		local playerId = tostring(plr.UserId)

		if self.cacheDirty or not next(self.teamMap) then
			self:refreshTeamMapAsync()
		end

		local playerPartyId = self.teamMap[playerId]
		if playerPartyId ~= nil then
			return self:getPartyById(playerPartyId)
		end

		return nil
	end

	AC_MOD_View.mockGetPlayerParty = function(self, plr)
		local parties = self.parties
		if parties ~= nil and #parties > 0 then
			return shared.MATCH_CONTROLLER_GETPLAYERPARTY_REVERT(self, plr)
		end
		return AC_MOD_View:getPlayerParty(plr)
	end

	function AC_MOD_View:syncStreamRemover()
		local remover = vape.Legit and vape.Legit.Modules.StreamDisabler
		if not remover then return end
		local want = self.disable_disguises == true
		if remover.Enabled ~= want then
			if want then self.streamRemoverOwned = true end
			remover:Toggle()
		end
	end

	function AC_MOD_View:toggleDisableDisguises()
		if not self.Enabled then return end
		self:syncStreamRemover()
	end

	function AC_MOD_View:refreshCore()
		self:refreshTeamMapAsync()
		self:refreshDisplayCacheAsync()
		self:refreshPlayerTeamDataAsync()

		self:toggleDisableDisguises()
	end

	function AC_MOD_View:refreshCoreAsync()
		task.spawn(self.refreshCore, self)
	end

	function AC_MOD_View:init()
		self.Enabled = true
		if self.disableDisguisesToggle then
			self.disable_disguises = self.disableDisguisesToggle.Enabled == true
		end
		self.controller.hasAnyPermissions = function(self)
			return true
		end
		self.match_controller.getPlayerParty = self.mockGetPlayerParty

		self.playerConnections = {
			added = Players.PlayerAdded:Connect(function(player)
				self.cacheDirty = true
				self:refreshCoreAsync()
				player:GetPropertyChangedSignal("Team"):Connect(function()
					self.cacheDirty = true
					self:refreshCoreAsync()
				end)
			end),
			removed = Players.PlayerRemoving:Connect(function(player)
				local playerId = tostring(player.UserId)
				self.Friends[playerId] = nil
				for _, cache in pairs(self.Friends) do
					cache[playerId] = nil
				end
				self.cacheDirty = true
				self:refreshCoreAsync()
			end)
		}

		self:refreshCore()
	end

	function AC_MOD_View:disable()
		self.Enabled = false

		self.controller.hasAnyPermissions = shared.PERMISSION_CONTROLLER_HASANYPERMISSIONS_REVERT
		self.match_controller.getPlayerParty = shared.MATCH_CONTROLLER_GETPLAYERPARTY_REVERT

		if self.playerConnections then
			for _, v in pairs(self.playerConnections) do
				pcall(function() v:Disconnect() end)
			end
			table.clear(self.playerConnections)
		end

		self.parties = {}
		self.teamMap = {}
		self.Friends = {}
		self.display = {}
		self.teamData = {}
		self.cacheDirty = true

		if self.streamRemoverOwned then
			local remover = vape.Legit and vape.Legit.Modules.StreamDisabler
			if remover and remover.Enabled then remover:Toggle() end
			self.streamRemoverOwned = false
		end
	end

	shared.ACMODVIEWENABLED = false
	AC_MOD_View.moduleInstance = vape.Categories.World:CreateModule({
		Name = "ACMODView",
		Function = function(call)
			shared.ACMODVIEWENABLED = call
			if call then
				AC_MOD_View:init()
			else
				AC_MOD_View:disable()
			end
		end
	})

	AC_MOD_View.disableDisguisesToggle = AC_MOD_View.moduleInstance:CreateToggle({
		Name = "Remove Disguises",
		Function = function(call)
			AC_MOD_View.disable_disguises = call
			if AC_MOD_View.Enabled then
				AC_MOD_View:syncStreamRemover()
			end
		end,
		Default = true
	})
	AC_MOD_View.disable_disguises = true
end)

-- ===== World/AntiMagma.lua =====
run(function()
	local AntiMagma

	local function disableMagmaPart(v)
		local name = v.Name
		if not (name:find('agma', 1, true) or name:find('AGMA', 1, true)) then return end
		if not v:IsA('BasePart') then return end
		if not string.find(string.lower(name), 'magma', 1, true) then return end
		for _, stuff in v:GetDescendants() do
			if stuff:IsA('TouchTransmitter') then
				pcall(function() stuff:Destroy() end)
			end
		end
	end

	AntiMagma = vape.Categories.World:CreateModule({
		Name = 'AntiMagma',
		Tooltip = 'Stops magma killing you',
		Function = function(callback)
			if callback then
				scanDescendants(workspace, disableMagmaPart, AntiMagma)

				AntiMagma:Clean(workspace.DescendantAdded:Connect(function(v)
					disableMagmaPart(v)
				end))

				local worldFolder = getWorldFolder()
				if not worldFolder then return end
				local blocks = worldFolder:FindFirstChild('Blocks')
				if not blocks then return end
				AntiMagma:Clean(blocks.ChildAdded:Connect(function(v)
					disableMagmaPart(v)
				end))
			end
		end
	})
end)

-- ===== World/AutoCounter.lua =====
run(function()
    local AutoCounter
    local tntCount
    local LimitItem
    local AutoPlaceToggle
    local HighlightToggle

    local alltntBlocks = {}
    local counteredtnt = {}
    local tntHighlights = {}
    local autoCounterPlacing = false
	local function fixPosition(pos)
		return bedwars.BlockController:getBlockPosition(pos) * 3
	end

    local function addHighlight(tntBlock)
        if tntHighlights[tntBlock] or not tntBlock.Parent then return end
        local h = Instance.new('SelectionBox')
        h.Adornee = tntBlock
        h.Color3 = Color3.fromRGB(255, 50, 50)
        h.LineThickness = 0.05
        h.SurfaceTransparency = 0.6
        h.SurfaceColor3 = Color3.fromRGB(255, 50, 50)
        h.Parent = coreGui
        tntHighlights[tntBlock] = h
    end

    local function removeHighlight(tntBlock)
        if tntHighlights[tntBlock] then
            tntHighlights[tntBlock]:Destroy()
            tntHighlights[tntBlock] = nil
        end
    end

    local function clearAllHighlights()
        for _, h in pairs(tntHighlights) do
            h:Destroy()
        end
        table.clear(tntHighlights)
    end

    local function isEnemytnt(tntBlock)
        if not tntBlock or not tntBlock.Parent then return false end
        if tntBlock:GetAttribute("AutoCountertnt") then return false end

        local placerId = tntBlock:GetAttribute("PlacedByUserId")
        if not placerId then
            return true
        end

        if placerId == lplr.UserId then
            return false
        end
        local myTeam = lplr:GetAttribute('Team')
        if myTeam then
            for _, player in playersService:GetPlayers() do
                if player.UserId == placerId and player:GetAttribute('Team') == myTeam then
                    return false
                end
            end
        end

        return true
    end

    local function isHoldingtnt()
        return isHoldingItem({'tnt'})
    end

    AutoCounter = vape.Categories.World:CreateModule({
        Name = 'AutoCounter',
        Function = function(callback)
            if callback then
                table.clear(counteredtnt)

                local tntAddedConnection = workspace.DescendantAdded:Connect(function(obj)
                    if obj.Name == "tnt" and obj:IsA("Part") then
                        if autoCounterPlacing then
                            obj:SetAttribute("AutoCountertnt", true)
                        end
                        alltntBlocks[obj] = true

                        task.defer(function()
                            if HighlightToggle and HighlightToggle.Enabled and isEnemytnt(obj) then
                                addHighlight(obj)
                            end
                        end)

                        local ancestryConnection
                        ancestryConnection = obj.AncestryChanged:Connect(function()
                            if not obj.Parent then
                                alltntBlocks[obj] = nil
                                counteredtnt[obj] = nil
                                removeHighlight(obj)
                                if ancestryConnection then
                                    ancestryConnection:Disconnect()
                                end
                            end
                        end)
                    end
                end)
                AutoCounter:Clean(tntAddedConnection)

                for _, obj in workspace:GetDescendants() do
                    if obj.Name == "tnt" and obj:IsA("Part") and not alltntBlocks[obj] then
                        alltntBlocks[obj] = true
                    end
                end

                local horizontalSides = {}
                for _, side in ipairs(Enum.NormalId:GetEnumItems()) do
                    local sideVec = Vector3.fromNormalId(side)
                    if sideVec.Y == 0 then
                        table.insert(horizontalSides, sideVec)
                    end
                end

                repeat
                    if not entitylib.isAlive then
                        task.wait(0.1)
                        continue
                    end

                    if HighlightToggle and HighlightToggle.Enabled then
                        for tntBlock in pairs(alltntBlocks) do
                            if tntBlock.Parent and isEnemytnt(tntBlock) then
                                addHighlight(tntBlock)
                            end
                        end
                    else
                        clearAllHighlights()
                    end

                    if AutoPlaceToggle and AutoPlaceToggle.Enabled then
                        if LimitItem.Enabled and not isHoldingtnt() then
                            task.wait(0.1)
                            continue
                        end

                        if not getItem("tnt") then
                            task.wait(0.1)
                            continue
                        end

                        local myPosition = entitylib.character.RootPart.Position
                        local maxDistanceSq = 30 * 30

                        for tntBlock in pairs(alltntBlocks) do
                            if tntBlock.Parent and not counteredtnt[tntBlock] and isEnemytnt(tntBlock) then
                                local offset = tntBlock.Position - myPosition
                                local distanceSq = offset.X * offset.X + offset.Y * offset.Y + offset.Z * offset.Z

                                if distanceSq <= maxDistanceSq then
                                    local placedCount = 0
                                    local maxCount = tntCount.Value

                                    for _, sideVec in ipairs(horizontalSides) do
                                        if LimitItem.Enabled and not isHoldingtnt() then break end
                                        if placedCount >= maxCount then break end

                                        local placePos = fixPosition(tntBlock.Position + sideVec * 3.5)
                                        if not getPlacedBlock(placePos) and getItem("tnt") then
                                            if LimitItem.Enabled and not isHoldingtnt() then break end
                                            autoCounterPlacing = true
                                            bedwars.placeBlock(placePos, "tnt")
                                            autoCounterPlacing = false
                                            placedCount = placedCount + 1
                                            task.wait(0.05)
                                        end
                                    end

                                    counteredtnt[tntBlock] = true
                                    task.defer(function()
                                        if tntBlock.Parent then
                                            tntBlock.AncestryChanged:Wait()
                                        end
                                        counteredtnt[tntBlock] = nil
                                    end)
                                end
                            end
                        end
                    end

                    task.wait(0.1)
                until not AutoCounter.Enabled
            else
                table.clear(counteredtnt)
                clearAllHighlights()
            end
        end,
        Tooltip = 'Highlights and counters enemy TNT'
    })

    tntCount = AutoCounter:CreateSlider({
        Name = 'TNT Count',
        Min = 1,
        Max = 5,
        Default = 3
    })

    LimitItem = AutoCounter:CreateToggle({
        Name = 'Limit to TNT',
        Default = true,
    })

    AutoPlaceToggle = AutoCounter:CreateToggle({
        Name = 'Auto Place',
        Default = true,
    })

    HighlightToggle = AutoCounter:CreateToggle({
        Name = 'Highlight',
        Default = true,
    })
end)

-- ===== World/AutoSuffocate.lua =====
run(function()
    local AutoSuffocate
    local Range
    local LimitItem

    local function fixPosition(pos)
        return bedwars.BlockController:getBlockPosition(pos) * 3
    end

    AutoSuffocate = vape.Categories.World:CreateModule({
        Name = 'AutoSuffocate',
        Function = function(callback)
            if callback then
                local pending, nextSweep = {}, 0
                repeat
                    local item = store.hand.toolType == 'block' and store.hand.tool.Name or not LimitItem.Enabled and getWool()
                    if tick() >= nextSweep then
                        nextSweep = tick() + 5
                        for key, expires in pending do
                            if expires <= tick() then
                                pending[key] = nil
                            end
                        end
                    end

                    if item and entitylib.isAlive then
                        local plrs = entitylib.AllPosition({
                            Part = 'RootPart',
                            Range = Range.Value,
                            Players = true
                        })

                        for _, ent in plrs do
                            local needPlaced = {}

                            for _, side in Enum.NormalId:GetEnumItems() do
                                side = Vector3.fromNormalId(side)
                                if side.Y ~= 0 then continue end

                                side = fixPosition(ent.RootPart.Position + side * 2)
                                if not getPlacedBlock(side) then
                                    table.insert(needPlaced, side)
                                end
                            end

                            if #needPlaced < 3 then
                                table.insert(needPlaced, fixPosition(ent.Head.Position))
                                table.insert(needPlaced, fixPosition(ent.RootPart.Position - Vector3.new(0, 1, 0)))

                                for _, pos in needPlaced do
                                    if not getPlacedBlock(pos) then
                                        local key = tostring(pos)
                                        if (pending[key] or 0) <= tick() then
                                            pending[key] = tick() + 0.35
                                            task.spawn(bedwars.placeBlock, pos, item)
                                        end
                                        break
                                    end
                                end
                            end
                        end
                    end

                    task.wait(0.09)
                until not AutoSuffocate.Enabled
            end
        end,
        Tooltip = 'Places blocks on nearby confined entities'
    })
    Range = AutoSuffocate:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 20,
        Default = 20,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
    LimitItem = AutoSuffocate:CreateToggle({
        Name = 'Limit to Items',
        Default = true
    })
end)

-- ===== World/AutoTool.lua =====
run(function()
    local AutoTool
    local old, hook, event

    local function switchHotbarItem(block)
        if not block then return false end
        if block:GetAttribute('NoBreak') then return false end
        if block:GetAttribute('Team'..(lplr:GetAttribute('Team') or 0)..'NoBreak') then return false end

        local meta = bedwars.ItemMeta and bedwars.ItemMeta[block.Name]
        local blockMeta = meta and meta.block
        if not blockMeta or not blockMeta.breakType then return false end

        local tool, slot = getBreakTool(blockMeta.breakType), nil
        if tool then
            for i, v in store.inventory.hotbar do
                if v.item and v.item.itemType == tool.itemType then slot = i - 1 break end
            end

            if slot == nil or (store.inventory and store.inventory.hotbarSlot == slot) then return false end

            if hotbarSwitch(slot) then
                if inputService:IsMouseButtonPressed(0) and event then
                    event:Fire()
                end
                return true
            end
        end
        return false
    end

    local function hookBreak()
        if hook then return end
        if type(bedwars.BlockBreaker) ~= 'table' or type(bedwars.BlockBreaker.hitBlock) ~= 'function' then return end
        old = bedwars.BlockBreaker.hitBlock
        hook = function(self, maid, raycastparams, ...)
            if not AutoTool.Enabled then
                return old(self, maid, raycastparams, ...)
            end
            local ok, swapped = pcall(function()
                local selector = self.clientManager and self.clientManager:getBlockSelector()
                local block = selector and selector:getMouseInfo(1, {ray = raycastparams, range = self.range})
                return switchHotbarItem(block and block.target and block.target.blockInstance or nil)
            end)
            if ok and swapped then return end
            return old(self, maid, raycastparams, ...)
        end
        bedwars.BlockBreaker.hitBlock = hook
    end

    local function unhookBreak()
        if not hook then return end
        if bedwars.BlockBreaker.hitBlock == hook then
            bedwars.BlockBreaker.hitBlock = old
            hook, old = nil, nil
        end
    end

    AutoTool = vape.Categories.World:CreateModule({
        Name = 'AutoTool',
        Function = function(callback)
            if callback then
                event = Instance.new('BindableEvent')
                AutoTool:Clean(event)
                AutoTool:Clean(event.Event:Connect(function()
                    contextActionService:CallFunction('block-break', Enum.UserInputState.Begin, newproxy(true))
                end))
                hookBreak()
            else
                unhookBreak()
                event = nil
            end
        end,
        Tooltip = 'Selects the right tool for what you are mining'
    })
end)

-- ===== World/BedAssist.lua =====
run(function()

    local util = vape.Libraries.bedwarsutil
    local BedAssist
    local AimMode
    local Speed
    local Range
    local Shake
    local Angle
    local Sort
    local Mode
    local Limit

    local function ease(t)
        return t < 0.5 and 4 * t * t * t or 1 - math.pow(-2 * t + 2, 3) / 2
    end

    local started = 0
    local aimfuncs = {
        Simple = function(localcframe, pos, fps)
            local rng = Random.new()
            return localcframe:Lerp(
                CFrame.lookAt(
                    localcframe.p,
                    pos
                        + Vector3.new(
                            (rng:NextNumber() - 0.5) * Shake.Value * fps,
                            (rng:NextNumber() - 0.5) * Shake.Value * fps,
                            (rng:NextNumber() - 0.5) * Shake.Value * fps
                        )
                ),
                Speed.Value * fps
            ),
                Speed.Value
        end,
        Adaptive = function(localcframe, pos, fps)
            local prog, rng = ease(math.min((tick() - started) / (1 / (Speed.Value * 0.5)), 1)), Random.new()
            local speed = Speed.Value * prog
            return localcframe:Lerp(CFrame.lookAt(localcframe.p, pos + Vector3.new((rng:NextNumber() - 0.5) * Shake.Value * fps, (rng:NextNumber() - 0.5) * Shake.Value * fps, (rng:NextNumber() - 0.5) * Shake.Value * fps)), speed * fps), speed
        end
    }

    local function getMousePosition()
        local suc, mouseinfo = pcall(function()
            return bedwars.BlockBreaker.clientManager:getBlockSelector():getMouseInfo(0)
        end)

        if suc and mouseinfo then
            if mouseinfo.target and mouseinfo.target.blockRef then
                return mouseinfo.target.blockRef.blockPosition * 3
            end
            if mouseinfo.placementPosition then
                return mouseinfo.placementPosition * 3
            end
        end
        return nil
    end

    local function getBestPosition(block)
        local handler = bedwars.BlockController:getHandlerRegistry():getHandler(block.Name)
        local cost, pos = math.huge, nil
        local mag = 9e9

        local positions = (handler and handler:getContainedPositions(block) or { block.Position / 3 })

        for _, v in positions do
            local dpos, dcost = bedwars.calculateBreakPath(block, v * 3, breakmethods[Sort.Value], Angle.Value, getMousePosition())
            local dmag = dpos and (entitylib.character.RootPart.Position - dpos).Magnitude

            if dpos then
                if dcost < cost or (dcost == cost and dmag < mag) then
                    cost, pos, mag = dcost, dpos, dmag
                end
            end
        end

        if pos and (entitylib.character.RootPart.Position - pos).Magnitude <= Range.Value then
            return pos
        end
        return nil
    end

    BedAssist = vape.Categories.World:CreateModule({
        Name = 'BedAssist',
        Function = function(call)
            if call then
                repeat
                    task.wait()
                until store.matchState ~= 0 or not BedAssist.Enabled
                if not BedAssist.Enabled then
                    return
                end

                local beds = collection('bed', BedAssist, function(tab, obj)
                    task.delay(0, function()
                        if not obj:GetAttribute('Team' .. (lplr:GetAttribute('Team') or -1) .. 'NoBreak') then
                            table.insert(tab, obj)
                        end
                    end)
                end)
                local rng = Random.new()
                local lastbed = nil

                BedAssist:Clean(runService.PostSimulation:Connect(function(dt)
                    if entitylib.isAlive and (not Limit.Enabled or store.hand.tool and bedwars.ItemMeta[store.hand.tool.Name].breakBlock) then
                        local localPosition = entitylib.character.RootPart.Position
                        for _, v in beds do
                            if (localPosition - v.Position).Magnitude <= Range.Value then
                                if lastbed ~= v then
                                    started = tick()
                                end
                                lastbed = v

                                local pos = getBestPosition(v)
                                if pos then
                                    local pred, speed = aimfuncs[AimMode.Value](gameCamera.CFrame, pos, dt)

                                    if Mode.Value == 'Mouse' then
                                        pos += Vector3.new(
                                            (rng:NextNumber() - 0.5) * Shake.Value * 0.1,
                                            (rng:NextNumber() - 0.5) * Shake.Value * 0.1,
                                            (rng:NextNumber() - 0.5) * Shake.Value * 0.1
                                        )
                                        local campos, vis = gameCamera:WorldToViewportPoint(pos)

                                        if vis then
                                            local vec2 = (
                                                Vector2.new(campos.X, campos.Y) - inputService:GetMouseLocation()
                                            ) * (speed * dt)
                                            mousemoverel(vec2.X, vec2.Y)
                                        end
                                    else
                                        gameCamera.CFrame = pred
                                    end
                                end
                                break
                            end
                        end
                    end
                end))
            end
        end,
        Tooltip = 'Smoothly aims towards a bed close to your mouse'
    })

    local list = {'Camera'}
    if inputService.MouseEnabled and mousemoverel then
        table.insert(list, 'Mouse')
    end
    AimMode = BedAssist:CreateDropdown({
        Name = 'Mode',
        List = {'Simple', 'Adaptive'},
        Default = 'Simple',
    })
    Mode = BedAssist:CreateDropdown({
        Name = 'Aim Mode',
        List = list,
        Default = 'Camera',
    })
    Sort = BedAssist:CreateDropdown({
        Name = 'Target Mode',
        List = table.clone(sortlist),
        Default = 'Distance',
        Tooltip = TARGET_MODE_TOOLTIP
    })
    Speed = BedAssist:CreateSlider({
        Name = 'Aim Speed',
        Min = 1,
        Max = 20,
        Default = 7,
    })
    Range = BedAssist:CreateSlider({
        Name = 'Assist Range',
        Min = 1,
        Max = 30,
        Default = 20,
        Suffix = util.Studs,
    })
    Shake = BedAssist:CreateSlider({
        Name = 'Shake',
        Min = 1,
        Max = 100,
        Default = 3,
    })
    Angle = BedAssist:CreateSlider({
        Name = 'Max angle',
        Min = 1,
        Max = 360,
        Default = 200,
    })
    Limit = BedAssist:CreateToggle({Name = 'Limit to item', Default = true})
end)

-- ===== World/BedProtector.lua =====
run(function()
    local BedProtector
    local PlaceRange
    local Layers
    local Blacklist
    local Mode
    local Smart
    local Switch
    local WoolOnly
    local LimitItem
    local Template
    local EmergencyKey
    local Radius
    local NoAnimation
    local layout, adjacent = {}, {}
    local patchTarget
    local placing = false
    local placeAnimation
    pcall(function()
        placeAnimation = bedwars.BlockController:getAnimationController():getAssetId(0)
    end)
    for _, v in Enum.NormalId:GetEnumItems() do
        table.insert(adjacent, Vector3.FromNormalId(v) * 3)
    end
    local previewParts = {}
    local templateSpecs = {
        ['Quick Wool'] = {Layers = 1, Wool = true},
        Layered = {Layers = 2, Wool = false},
        Defensive = {Layers = 3, Wool = false},
        ['Anti-Explosive'] = {Layers = 2, Wool = false}
    }

    local function clearPreview()
        for _, part in previewParts do part:Destroy() end
        table.clear(previewParts)
    end

    local function getBedNear()
        local localPosition = entitylib.isAlive and entitylib.character.RootPart.Position or Vector3.zero
        for _, v in collectionService:GetTagged('bed') do
            if (localPosition - v.Position).Magnitude < 14
                and v:GetAttribute('Team' .. (lplr:GetAttribute('Team') or -1) .. 'NoBreak') then
                return v
            end
        end
        return nil
    end

    local function getBlocks()
        local blocks = {}
        for _, item in store.inventory.inventory.items do
            local block = bedwars.ItemMeta[item.itemType].block
            if block and (not Template or Template.Value ~= 'Quick Wool' or item.itemType:find('wool'))
                and not table.find(Blacklist.ListEnabled, item.itemType:find('wool') and 'wool' or item.itemType) then
                table.insert(blocks, { item.itemType, block.health, item.tool })
            end
        end
        table.sort(blocks, function(a, b)
            return a[2] > b[2]
        end)
        return blocks
    end

    
    
    
    
    
    local function bedCells(bed)
        local cf, size
        if bed:IsA('BasePart') then
            cf, size = bed.CFrame, bed.Size
        else
            cf = bed:GetPivot()
            local ok, ext = pcall(function() return bed:GetExtentsSize() end)
            size = ok and ext or Vector3.new(3, 3, 6)
        end
        local center = cf.Position
        
        
        local axis = (size.X >= size.Z) and cf.RightVector or cf.LookVector
        axis = Vector3.new(axis.X, 0, axis.Z)
        axis = axis.Magnitude > 0 and axis.Unit or Vector3.new(1, 0, 0)
        local a = roundPos(center + axis * 1.5)
        local b = roundPos(center - axis * 1.5)
        if a == b then b = roundPos(center - axis * 3) end
        return a, b
    end

    


    


    local function getPatchBlock(preferred)
        if LimitItem.Enabled then
            local hand = store.hand
            if not hand or hand.toolType ~= 'block' or not hand.tool then return nil end
            local itemType = hand.tool.Name
            if WoolOnly.Enabled and not itemType:find('wool') then return nil end
            if table.find(Blacklist.ListEnabled, itemType:find('wool') and 'wool' or itemType) then return nil end
            return {itemType, 0, hand.tool}
        end

        local best
        for _, item in store.inventory.inventory.items do
            local meta = bedwars.ItemMeta[item.itemType]
            local block = meta and meta.block
            if not block then continue end
            if WoolOnly.Enabled and not item.itemType:find('wool') then continue end
            if table.find(Blacklist.ListEnabled, item.itemType:find('wool') and 'wool' or item.itemType) then continue end
            if item.itemType == preferred then
                return {item.itemType, block.health or 0, item.tool}
            end
            if not best or (block.health or 0) > best[2] then
                best = {item.itemType, block.health or 0, item.tool}
            end
        end
        return best
    end

    local function patchBedNear()
        local localPosition = entitylib.isAlive and entitylib.character.RootPart.Position or Vector3.zero
        for _, v in collectionService:GetTagged('bed') do
            if (localPosition - v.Position).Magnitude < (PlaceRange.Value + Radius.Value)
                and v:GetAttribute('Team' .. (lplr:GetAttribute('Team') or -1) .. 'NoBreak') then
                return v
            end
        end
        return nil
    end

    local function scanBed(bed)
        table.clear(layout)
        for _, v in store.blocks do
            if not v:HasTag('bed') and (v.Position - bed.Position).Magnitude <= Radius.Value then
                layout[v.Position] = v.Name
            end
        end

        local holes = {}
        for position, name in layout do
            for _, offset in adjacent do
                local cell = position + offset
                if layout[cell] or holes[cell] or getPlacedBlock(cell) then continue end
                local walls = 0
                for _, side in adjacent do
                    if layout[cell + side] then walls += 1 end
                end
                if walls >= 4 then holes[cell] = name end
            end
        end
        for position, name in holes do
            layout[position] = name
        end
    end

    local function startPatching()
        local old = bedwars.AnimationUtil.playAnimation
        local hook = function(self, player, assetId, config)
            if placing and NoAnimation.Enabled and assetId == placeAnimation then
                return
            end
            return old(self, player, assetId, config)
        end
        bedwars.AnimationUtil.playAnimation = hook
        BedProtector:Clean(function()
            if bedwars.AnimationUtil.playAnimation == hook then
                bedwars.AnimationUtil.playAnimation = old
            end
            placing = false
            patchTarget = nil
            table.clear(layout)
        end)
        BedProtector:Clean(collectionService:GetInstanceAddedSignal('block'):Connect(function(block)
            if patchTarget and not block:HasTag('bed') and (block.Position - patchTarget.Position).Magnitude <= Radius.Value then
                layout[block.Position] = block.Name
            end
        end))
        BedProtector:Clean(vapeEvents.BreakBlockEvent.Event:Connect(function(blockTable)
            local player = blockTable.player
            if player and (player == lplr or player:GetAttribute('Team') == lplr:GetAttribute('Team')) then
                layout[blockTable.blockRef.blockPosition * 3] = nil
            end
        end))
    end

    local function patchBed()
        local found = patchBedNear()
        if found ~= patchTarget then
            patchTarget = found
            if found then scanBed(found) else table.clear(layout) end
        end
        local bed = patchTarget
        if not (bed and entitylib.isAlive) then return false end

        local localPosition = entitylib.character.RootPart.Position
        local holes = {}
        for position, name in layout do
            if (localPosition - position).Magnitude <= PlaceRange.Value and not getPlacedBlock(position) then
                table.insert(holes, {position, name})
            end
        end
        table.sort(holes, function(a, b)
            return (a[1] - bed.Position).Magnitude < (b[1] - bed.Position).Magnitude
        end)

        for _, hole in holes do
            if not BedProtector.Enabled then break end
            local position, name = hole[1], hole[2]
            if getPlacedBlock(position) then continue end
            local block = getPatchBlock(name)
            if not block then break end
            if Switch.Enabled then
                local slot = getHotbar(block[3])
                if slot and hotbarSwitch(slot) then task.wait() end
            end
            placing = true
            bedwars.placeBlock(position, block[1])
            placing = false
            task.wait(1 / bedwars.SharedConstants.BLOCK_PLACE_CPS)
        end
        return true
    end

    BedProtector = vape.Categories.World:CreateModule({
        Name = 'BedProtector',
        Function = function(callback)
            if callback then
                local spec = templateSpecs[Template.Value]
                local estimated = spec and ((spec.Layers * spec.Layers * 16) + 6) or 0
                notif('BedProtector', Template.Value..' needs about '..estimated..' blocks', 5, 'info')
                BedProtector:Clean(inputService.InputBegan:Connect(function(input, processed)
                    if not processed and input.KeyCode.Name == EmergencyKey.Value and BedProtector.Enabled then
                        clearPreview()
                        BedProtector:Toggle()
                        notif('BedProtector', 'Emergency stop', 3, 'warning')
                    end
                end))
                local patching = Mode.Value == 'Bed patcher'
                if patching then startPatching() end
                repeat
                    local bed = not patching and getBedNear()
                    if patching then
                        patchBed()
                    elseif bed then
                        
                        
                        local cellA, cellB = bedCells(bed)
                        local protected = { [cellA] = true, [cellB] = true }

                        for i, block in getBlocks() do
                            local switch, old = Switch.Enabled, store.hand and store.hand.tool and getHotbar(store.hand.tool) or nil
                            local hotbar = switch and getHotbar(block[3]) or nil

                            for layer = 1, Layers.Value do
                                local newPositions = {}

                                
                                for pos in pairs(protected) do
                                    
                                    for dx = -3, 3, 3 do
                                        for dz = -3, 3, 3 do
                                            if dx ~= 0 or dz ~= 0 then
                                                local newPos = pos + Vector3.new(dx, 0, dz)
                                                if not protected[newPos] then
                                                    newPositions[newPos] = true
                                                end
                                            end
                                        end
                                    end
                                    
                                    local upPos = pos + Vector3.new(0, 3, 0)
                                    if not protected[upPos] then
                                        newPositions[upPos] = true
                                    end
                                end

                                
                                
                                
                                
                                local ordered = {}
                                for newPos in pairs(newPositions) do
                                    table.insert(ordered, newPos)
                                end
                                local rootPos = entitylib.character.RootPart.Position
                                table.sort(ordered, function(a, b)
                                    return (rootPos - a).Magnitude < (rootPos - b).Magnitude
                                end)

                                
                                local placedAny = false
                                for _, newPos in ordered do
                                    if not BedProtector.Enabled then break end
                                    if getPlacedBlock(newPos) then
                                        protected[newPos] = true   
                                        continue
                                    end
                                    if (entitylib.character.RootPart.Position - newPos).Magnitude > PlaceRange.Value then
                                        continue
                                    end
                                    if hotbar and hotbarSwitch(hotbar) then task.wait() end
                                    task.spawn(bedwars.placeBlock, newPos, block[1], false)
                                    placedAny = true
                                    protected[newPos] = true
                                    task.wait(0.05)
                                end

                                
                                
                                if not placedAny then break end
                                if not BedProtector.Enabled then break end
                            end

                            if switch and old and hotbarSwitch(old) then task.wait() end
                        end
                    else
                        if Mode.Value == 'On Key' then
                            notif('BedProtector', 'Unable to locate bed', 5)
                            BedProtector:Toggle()
                        end
                    end
                    
                    task.wait(patching and 0.2 or 0.5)
                    if Mode.Value == 'On Key' then
                        BedProtector:Toggle()
                        break
                    end
                until not BedProtector.Enabled
            end
            if not callback then clearPreview() end
        end,
        Tooltip = 'Automatically places strong blocks around the bed'
    })

    
    
    local function syncModeOptions()
        
        
        if not Mode then return end
        if Smart and Smart.Object then Smart.Object.Visible = Mode.Value == 'Toggle' end
        local patching = Mode.Value == 'Bed patcher'
        if WoolOnly and WoolOnly.Object then WoolOnly.Object.Visible = patching end
        if LimitItem and LimitItem.Object then LimitItem.Object.Visible = patching end
        if Radius and Radius.Object then Radius.Object.Visible = patching end
        if NoAnimation and NoAnimation.Object then NoAnimation.Object.Visible = patching end
        if Template and Template.Object then Template.Object.Visible = not patching end
        if Layers and Layers.Object then Layers.Object.Visible = not patching end
    end
    local restarting = false

    Mode = BedProtector:CreateDropdown({
        Name = 'Mode',
        List = {'Toggle', 'On Key', 'Bed patcher'},
        Default = 'Toggle',
        Tooltip = 'Toggle - builds and keeps it up\nOn Key - builds once\nBed patcher - repairs what breaks',
        Function = function()
            syncModeOptions()
            if BedProtector.Enabled and not restarting then
                restarting = true
                task.defer(function()
                    restarting = false
                    if BedProtector.Enabled then
                        BedProtector:Toggle()
                        BedProtector:Toggle()
                    end
                end)
            end
        end,
    })
    Template = BedProtector:CreateDropdown({
        Name = 'Template',
        List = {'Quick Wool', 'Layered', 'Defensive', 'Anti-Explosive'},
        Function = function(value)
            local spec = templateSpecs[value]
            if not spec or not Layers then return end
            Layers:SetValue(spec.Layers)
            if WoolOnly then WoolOnly:SetValue(spec.Wool) end
            clearPreview()
            local bed = getBedNear()
            if bed then
                local a, b = bedCells(bed)
                for _, centre in {a, b} do
                    for x = -spec.Layers, spec.Layers do
                        for z = -spec.Layers, spec.Layers do
                            if math.max(math.abs(x), math.abs(z)) ~= spec.Layers then continue end
                            local pos = centre + Vector3.new(x * 3, 0, z * 3)
                            if getPlacedBlock(pos) then continue end
                            local ghost = Instance.new('Part')
                            ghost.Name, ghost.Size, ghost.Position = 'BedProtectorPreview', Vector3.new(3, 3, 3), pos
                            ghost.Anchored, ghost.CanCollide, ghost.CanQuery = true, false, false
                            ghost.Material, ghost.Color, ghost.Transparency = Enum.Material.ForceField, Color3.fromRGB(90, 210, 140), 0.65
                            ghost.Parent = workspace
                            table.insert(previewParts, ghost)
                        end
                    end
                end
                task.delay(5, clearPreview)
            end
        end
    })
    EmergencyKey = BedProtector:CreateDropdown({Name = 'Emergency Stop', List = {'X', 'V', 'B', 'N', 'Delete'}, Default = 'X'})
    Blacklist = BedProtector:CreateTextList({
        Name = 'Blacklist',
        Default = {'siege_tnt', 'tnt'},
    })
    PlaceRange = BedProtector:CreateSlider({
        Name = 'Place Range',
        Min = 1, Max = 30, Default = 15,
    })
    Layers = BedProtector:CreateSlider({
        Name = 'Layers',
        Min = 1, Max = 5, Default = 1,
        Suffix = function(val) return val <= 1 and 'layer' or 'layers' end,
    })
    Switch = BedProtector:CreateToggle({Name = 'Auto Switch'})
    Smart = BedProtector:CreateToggle({Name = 'Smart', Default = true})
    WoolOnly = BedProtector:CreateToggle({
        Name = 'Wool only',
        Tooltip = 'Repairs with wool instead of your toughest block'
    })
    LimitItem = BedProtector:CreateToggle({
        Name = 'Limit to item',
        Tooltip = 'Only works while holding the item it uses'
    })
    Radius = BedProtector:CreateSlider({
        Name = 'Defense Radius',
        Min = 3,
        Max = 30,
        Default = 15,
        Suffix = function(val) return val == 1 and 'stud' or 'studs' end,
        Tooltip = 'How far from the bed counts as your defense'
    })
    NoAnimation = BedProtector:CreateToggle({
        Name = 'No Animation',
        Tooltip = 'Hides the arm swing while repairing'
    })
    
    
    syncModeOptions()
end)

-- ===== World/BlockIn.lua =====
run(function()
    local BlockIn

    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    rayCheck.FilterType = Enum.RaycastFilterType.Exclude
    local PlaceMode
    local PlaceDelay
    local Bedfinder
    local LimitItem
    local UseBlacklist
    local Blacklist
    local Priority
    local ReturnSlot
    local WoolOnly
    local BedBreak
    local PocketBypass

    local function isBlacklisted(itemType)
	return UseBlacklist and UseBlacklist.Enabled and Blacklist and table.find(Blacklist.ListEnabled, itemType)
    end

	local function getHotbarItemTypes()
		local types = {}
		for _, slot in store.inventory.hotbar do
			local item = slot.item
			if item and item.itemType then
				types[item.itemType] = true
			end
		end
		if store.hand.tool and store.hand.toolType == 'block' then
			types[store.hand.tool.Name] = true
		end
		return types
	end

    local function getBlocks()
	local blocks = {}

	if LimitItem and LimitItem.Enabled then
		local itemType = store.hand.toolType == 'block' and store.hand.tool and store.hand.tool.Name
		local meta = itemType and bedwars.ItemMeta[itemType]
		local block = meta and meta.block
		if block and not isBlacklisted(itemType) and (store.hand.amount or 0) > 0
			and (not WoolOnly.Enabled or itemType:find('wool')) then
			table.insert(blocks, { itemType, block.health or 0, store.hand.tool, store.hand.amount })
		end
		return blocks
	end

	local reachable = getHotbarItemTypes()
	for _, item in store.inventory.inventory.items do
		local itemType = item.itemType
		local meta = itemType and bedwars.ItemMeta[itemType]
		local block = meta and meta.block
		if block and reachable[itemType] and not isBlacklisted(itemType) and (item.amount or 0) > 0
			and (not WoolOnly.Enabled or itemType:find('wool')) then
			table.insert(blocks, { itemType, block.health or 0, item.tool, item.amount })
		end
	end
	table.sort(blocks, function(a, b)
		return Priority.Value == 'Lowest cost' and a[2] < b[2] or Priority.Value ~= 'Lowest cost' and a[2] > b[2]
	end)
	return blocks
    end

    local function getBed()
	local localPosition = entitylib.isAlive and entitylib.character.RootPart.Position or Vector3.zero
	for _, v in collectionService:GetTagged('bed') do
		if
			not v:GetAttribute('Team' .. (lplr:GetAttribute('Team') or -1) .. 'NoBreak')
			and (localPosition - v.Position).Magnitude <= 30
		then
			return v
		end
	end
	return
    end

    local function getPyramid(protectedDirection)
	local pattern = {
		Vector3.new(3, 0, 0),
		Vector3.new(0, 0, 3),
		Vector3.new(-3, 0, 0),
		Vector3.new(0, 0, -3),
		Vector3.new(3, 3, 0),
		Vector3.new(0, 3, 3),
		Vector3.new(-3, 3, 0),
		Vector3.new(0, 3, -3),
	}

	local rng = Random.new()

	if rng:NextNumber() < 0.95 then
		local extraCount = rng:NextInteger(1, 3)
		for _ = 1, extraCount do
			local dirX = (rng:NextInteger(0, 1) == 1 and 1 or -1)
			local dirZ = (rng:NextInteger(0, 1) == 1 and 1 or -1)
			local y = ({ 0, 3 })[rng:NextInteger(1, 2)]

			local offset = Vector3.new(3 * dirX, y, 3 * dirZ)

			if table.find(pattern, offset) then
				continue
			end
			table.insert(pattern, offset)
		end
	end

	local axis = rng:NextInteger(0, 1) == 1 and 'X' or 'Z'
	local dir = rng:NextInteger(0, 1) == 1 and 1 or -1
	local extraPos = axis == 'X' and Vector3.new(3 * dir, 6, 0) or Vector3.new(0, 6, 3 * dir)
	table.insert(pattern, extraPos)
	table.insert(pattern, Vector3.new(0, 6, 0))

	if protectedDirection then
		for index = #pattern, 1, -1 do
			local flat = pattern[index] * Vector3.new(1, 0, 1)
			if flat.Magnitude > 0 and flat.Unit:Dot(protectedDirection) > 0.65 then table.remove(pattern, index) end
		end
	end
	return pattern
    end

    local POCKET_SIDES = {
	Vector3.new(3, 0, 0),
	Vector3.new(-3, 0, 0),
	Vector3.new(0, 0, 3),
	Vector3.new(0, 0, -3),
    }
    local POCKET_CEILING = Vector3.new(0, 3, 0)

    local function blockAnchor(pos)
	local _, anchor = getPlacedBlock(pos)
	return anchor and anchor * 3
    end

    local function isPocket(anchor)
	local walls = 0
	for _, side in POCKET_SIDES do
		if getPlacedBlock(anchor + side) then
			walls += 1
		end
	end
	return walls >= 3 and getPlacedBlock(anchor + POCKET_CEILING) ~= nil
    end

    local function startPocketBypass()
	if not PocketBypass.Enabled then return end
	local cleared = {}
	local connection

	local function releaseCollisions()
		for part, original in cleared do
			if part.Parent then
				pcall(function() part.CanCollide = original end)
			end
		end
		table.clear(cleared)
	end

	local function step()
		if not BlockIn.Enabled or not PocketBypass.Enabled or not entitylib.isAlive then return end
		local root = entitylib.character and entitylib.character.RootPart
		if not root then return end
		local anchor = blockAnchor(root.Position)
		if not anchor or not isPocket(anchor) then return end

		for _, side in POCKET_SIDES do
			local wall = getPlacedBlock(anchor + side)
			if wall and wall.CanCollide and not cleared[wall] then
				cleared[wall] = wall.CanCollide
				pcall(function() wall.CanCollide = false end)
			end
		end

		local offset = root.Position - anchor
		if Vector3.new(offset.X, 0, offset.Z).Magnitude > 0.05 then
			root.CFrame = CFrame.new(anchor) * (root.CFrame - root.Position)
			local velocity = root.AssemblyLinearVelocity
			root.AssemblyLinearVelocity = Vector3.new(0, velocity.Y, 0)
		end
	end

	connection = runService.Stepped:Connect(step)
	return function()
		if connection then
			connection:Disconnect()
			connection = nil
		end
		releaseCollisions()
	end
    end

    BlockIn = vape.Categories.World:CreateModule({
	Name = 'BlockIn',
	Function = function(callback)
		if callback then
			local stopPocketBypass = startPocketBypass()
			if stopPocketBypass then
				BlockIn:Clean(stopPocketBypass)
			end
			local selfpos = entitylib.isAlive and entitylib.character.RootPart.Position or nil
			local previousSlot = store.inventory.hotbarSlot

			if selfpos then
				rayCheck.FilterDescendantsInstances = { lplr.Character, gameCamera }

				if Bedfinder.Enabled and not getBed() then
					notif('BlockIn', 'No bed found', 2, 'warning')
				elseif LimitItem and LimitItem.Enabled and store.hand.toolType ~= 'block' then
					notif('BlockIn', 'Hold a block first', 2, 'warning')
				else
					local oldPlaceCPS = bedwars.SharedConstants.BLOCK_PLACE_CPS
                    local restored = false
                    local function restoreState()
                        if restored then return end
                        restored = true
                        bedwars.SharedConstants.BLOCK_PLACE_CPS = oldPlaceCPS or 12
                        if ReturnSlot.Enabled and previousSlot ~= nil then hotbarSwitch(previousSlot) end
                    end
                    BlockIn:Clean(restoreState)
					bedwars.SharedConstants.BLOCK_PLACE_CPS = math.clamp(20, 1, 20)
					if PlaceMode.Value == 'Smart' then
						local ray
						for _, offset in { Vector3.new(0, -2, 0), Vector3.new(0, 1, 0) } do
							local placement = workspace:Raycast(
								selfpos + offset,
								entitylib.character.RootPart.CFrame.LookVector * 4,
								rayCheck
							)

							if placement and placement.Instance and placement.Instance:IsA('BasePart') then
								local pos = placement.Instance.Position
								local rounded = roundPos(pos)
								local oldSlot = store.hand and store.hand.tool and getHotbar(store.hand.tool)
								ray = placement.Instance:GetPivot().Position

								if bedwars.BlockController:isBlockBreakable({ blockPosition = pos / 3 }, lplr) then
									repeat
										if not entitylib.isAlive then
											break
										end
										task.spawn(bedwars.breakBlock, placement.Instance, false, nil, true, true)
										task.wait(0.25)
									until not getPlacedBlock(rounded) or not BlockIn.Enabled or not entitylib.isAlive
								end

								if oldSlot then
									hotbarSwitch(oldSlot)
								end

								if BlockIn.Enabled and entitylib.isAlive then
									selfpos = entitylib.character.RootPart.Position
								end
							end
						end
						if ray then
							lplr.Character.Humanoid:MoveTo(Vector3.new(ray.X, selfpos.Y, ray.Z))
							lplr.Character.Humanoid.MoveToFinished:Wait()
							if entitylib.isAlive then
								selfpos = entitylib.character.RootPart.Position
							end
						end
					end

					local blocks = getBlocks()
					if #blocks <= 0 then
						notif('BlockIn', 'No blocks in your hotbar', 3, 'warning')
					end
                    local function currentBreakingDirection()
                        if not BedBreak.Enabled or not entitylib.isAlive or not inputService:IsMouseButtonPressed(0) then return nil end
                        local bed = getBed()
                        local selector = bedwars.BlockBreaker.clientManager:getBlockSelector()
                        local mouseinfo = selector and selector:getMouseInfo(0)
                        local target = mouseinfo and mouseinfo.target and mouseinfo.target.blockRef
                        if not bed or not target or (bed.Position - entitylib.character.RootPart.Position).Magnitude > 14 then return nil end
                        local delta = (target.blockPosition * 3 - entitylib.character.RootPart.Position) * Vector3.new(1, 0, 1)
                        return delta.Magnitude > 0.1 and delta.Unit or nil
                    end
					for i, block in blocks do
						if not BlockIn.Enabled or not entitylib.isAlive then
							break
						end
						if (block[4] or 0) <= 0 then
							continue
						end
						for index, v in store.inventory.hotbar do
							if v.item and v.item.tool == block[3] and index ~= (store.inventory.hotbarSlot + 1) then
								hotbarSwitch(index - 1)
								break
							end
						end
						local pattern = getPyramid(currentBreakingDirection())

						for i2, pos in pattern do
							if not BlockIn.Enabled or not entitylib.isAlive then
								break
							end
							if getPlacedBlock(selfpos + pos) and i2 ~= 10 then
								continue
							end
                            
                            
                            local direction = currentBreakingDirection()
                            local flat = pos * Vector3.new(1, 0, 1)
                            if direction and flat.Magnitude > 0 and flat.Unit:Dot(direction) > 0.65 then continue end
                            local worldPosition = selfpos + pos
                            local placed = getPlacedBlock(worldPosition)
                            for _ = 1, 3 do
                                if placed or not BlockIn.Enabled or not entitylib.isAlive then break end
                                bedwars.placeBlock(worldPosition, block[1], true)
                                local deadline = tick() + 0.35
                                repeat
                                    task.wait()
                                    placed = getPlacedBlock(worldPosition)
                                until placed or tick() >= deadline or not BlockIn.Enabled or not entitylib.isAlive
                            end
                            if not placed and BlockIn.Enabled then
                                notif('BlockIn', 'Placement was not confirmed; leaving the opening clear', 3, 'warning')
                            end
							local delay = PlaceDelay:GetRandomValue()
							if delay > 0 then
								task.wait(delay)
							end
						end
					end

					if #blocks < 1 then
						notif('BlockIn', 'Missing blocks', 4, 'warning')
					end
                    restoreState()
				end
			end
			if BlockIn.Enabled then
				BlockIn:Toggle()
			end
		end
	end,
	Tooltip = 'Automatically places strong blocks around yourself'
    })
    PlaceMode = BlockIn:CreateDropdown({
	Name = 'Placement Mode',
	List = { 'Normal', 'Smart' },
	Default = 'Normal',
    })
    PlaceDelay = BlockIn:CreateTwoSlider({
	Name = 'Place Delay',
	Min = 0,
	Max = 5,
	DefaultMin = 0.07,
	DefaultMax = 0.1,
	Decimal = 5,
    })
    Bedfinder = BlockIn:CreateToggle({ Name = 'Bed finder' })
    PocketBypass = BlockIn:CreateToggle({
	Name = '1x1 bypass',
	Tooltip = 'Holds you in a one-block pocket while breaking a bed'
    })
    BedBreak = BlockIn:CreateToggle({Name = 'Bed break', Tooltip = 'Keeps your breaking side open while patching other gaps'})
    Priority = BlockIn:CreateDropdown({Name = 'Block priority', List = {'Hardest', 'Lowest cost'}, Default = 'Hardest'})
    ReturnSlot = BlockIn:CreateToggle({Name = 'Return to last slot', Default = true})
    WoolOnly = BlockIn:CreateToggle({Name = 'Wool only'})
    LimitItem = BlockIn:CreateToggle({
	Name = 'Limit to items',
	Tooltip = 'Only works while holding the item it uses',
    })
    UseBlacklist = BlockIn:CreateGroup({
	Name = 'Use blacklist',
	Default = true,
    })
    Blacklist = UseBlacklist:CreateTextList({
	Name = 'Blacklists',
	Placeholder = 'block',
	Default = {
		'cannon',
		'tnt',
		'siege_tnt',
	},
    })
end)

-- ===== World/Breaker.lua =====
run(function()
    local Breaker
    local Range
    local Angle
    local AutoTool
    local UpdateRate
    local Custom
    local Targets
    local Effect
    local CustomHealth = {}
    local Animation
    local SelfBreak
    local LimitItem
    local BreakerType
    local BreakChance
    local CombatOnly
    local LEGIT_RANGE = 18
    local rng = Random.new()
    local losFilter
    local customlist, parts = {}, {}

    
    
    
    
    
    local function makeMaid()
        local tasks = {}
        return {
            GiveTask = function(_, item)
                table.insert(tasks, item)
                return item
            end,
            DoCleaning = function()
                for _, item in tasks do
                    if typeof(item) == 'function' then
                        pcall(item)
                    elseif typeof(item) == 'RBXScriptConnection' then
                        item:Disconnect()
                    elseif typeof(item) == 'Instance' then
                        item:Destroy()
                    elseif type(item) == 'table' and item.DoCleaning then
                        item:DoCleaning()
                    end
                end
                table.clear(tasks)
            end
        }
    end

    local function customHealthbar(self, blockRef, health, maxHealth, changeHealth, block)
        
        self.healthbarMaid = self.healthbarMaid or makeMaid()
        self.healthbarProgressRef = self.healthbarProgressRef or bedwars.Roact.createRef()
        if not self.healthbarPart or not self.healthbarBlockRef or self.healthbarBlockRef.blockPosition ~= blockRef.blockPosition then
            self.healthbarMaid:DoCleaning()
            self.healthbarBlockRef = blockRef
            local create = bedwars.Roact.createElement
            local percent = math.clamp(health / maxHealth, 0, 1)
            local cleanCheck = true
            local part = Instance.new('Part')
            part.Size = Vector3.one
            part.CFrame = CFrame.new(bedwars.BlockController:getWorldPosition(blockRef.blockPosition))
            part.Transparency = 1
            part.Anchored = true
            part.CanCollide = false
            part.Parent = workspace
            self.healthbarPart = part
            bedwars.QueryUtil:setQueryIgnored(self.healthbarPart, true)

            local mounted = bedwars.Roact.mount(create('BillboardGui', {
                Size = UDim2.fromOffset(249, 102),
                StudsOffset = Vector3.new(0, 2.5, 0),
                Adornee = part,
                MaxDistance = 40,
                AlwaysOnTop = true
            }, {
                create('Frame', {
                    Size = UDim2.fromOffset(160, 50),
                    Position = UDim2.fromOffset(44, 32),
                    BackgroundColor3 = Color3.new(),
                    BackgroundTransparency = 0.5
                }, {
                    create('UICorner', {CornerRadius = UDim.new(0, 5)}),
                    create('ImageLabel', {
                        Size = UDim2.new(1, 89, 1, 52),
                        Position = UDim2.fromOffset(-48, -31),
                        BackgroundTransparency = 1,
                        Image = getcustomasset('ElevateV4/assets/new/blur.png'),
                        ScaleType = Enum.ScaleType.Slice,
                        SliceCenter = Rect.new(52, 31, 261, 502)
                    }),
                    create('TextLabel', {
                        Size = UDim2.fromOffset(145, 14),
                        Position = UDim2.fromOffset(13, 12),
                        BackgroundTransparency = 1,
                        Text = bedwars.ItemMeta[block.Name].displayName or block.Name,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        TextYAlignment = Enum.TextYAlignment.Top,
                        TextColor3 = Color3.new(),
                        TextScaled = true,
                        Font = Enum.Font.Arial
                    }),
                    create('TextLabel', {
                        Size = UDim2.fromOffset(145, 14),
                        Position = UDim2.fromOffset(12, 11),
                        BackgroundTransparency = 1,
                        Text = bedwars.ItemMeta[block.Name].displayName or block.Name,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        TextYAlignment = Enum.TextYAlignment.Top,
                        TextColor3 = color.Dark(uipallet.Text, 0.16),
                        TextScaled = true,
                        Font = Enum.Font.Arial
                    }),
                    create('Frame', {
                        Size = UDim2.fromOffset(138, 4),
                        Position = UDim2.fromOffset(12, 32),
                        BackgroundColor3 = uipallet.Main
                    }, {
                        create('UICorner', {CornerRadius = UDim.new(1, 0)}),
                        create('Frame', {
                            [bedwars.Roact.Ref] = self.healthbarProgressRef,
                            Size = UDim2.fromScale(percent, 1),
                            BackgroundColor3 = Color3.fromHSV(math.clamp(percent / 2.5, 0, 1), 0.89, 0.75)
                        }, {create('UICorner', {CornerRadius = UDim.new(1, 0)})})
                    })
                })
            }), part)

            self.healthbarMaid:GiveTask(function()
                cleanCheck = false
                self.healthbarBlockRef = nil
                bedwars.Roact.unmount(mounted)
                if self.healthbarPart then
                    self.healthbarPart:Destroy()
                end
                self.healthbarPart = nil
            end)

            bedwars.RuntimeLib.Promise.delay(5):andThen(function()
                if cleanCheck then
                    self.healthbarMaid:DoCleaning()
                end
            end)
        end

        local newpercent = math.clamp((health - changeHealth) / maxHealth, 0, 1)
        tweenService:Create(self.healthbarProgressRef:getValue(), TweenInfo.new(0.3), {
            Size = UDim2.fromScale(newpercent, 1), BackgroundColor3 = Color3.fromHSV(math.clamp(newpercent / 2.5, 0, 1), 0.89, 0.75)
        }):Play()
    end

    
    
    losFilter = RaycastParams.new()
    losFilter.FilterType = Enum.RaycastFilterType.Exclude
    losFilter.RespectCanCollide = false
    losFilter.IgnoreWater = true

    local function refreshFilter()
        losFilter.FilterDescendantsInstances = {lplr.Character, gameCamera}
    end

    local VISIBILITY_PROBES = {
        Vector3.zero,
        Vector3.new(1.35, 0, 0), Vector3.new(-1.35, 0, 0),
        Vector3.new(0, 1.35, 0), Vector3.new(0, -1.35, 0),
        Vector3.new(0, 0, 1.35), Vector3.new(0, 0, -1.35)
    }

    local function isVisible(worldPos)
        local eye = gameCamera.CFrame.Position
        for _, offset in VISIBILITY_PROBES do
            local probe = worldPos + offset
            local ray = probe - eye
            local hit = workspace:Raycast(eye, ray, losFilter)
            if not hit or (hit.Position - eye).Magnitude >= ray.Magnitude - 1.5 then
                return true
            end
        end
        return false
    end

    local function isLegit()
        return BreakerType.Value == 'Legit'
    end

    local function breakRange()
        return isLegit() and math.min(Range.Value, LEGIT_RANGE) or Range.Value
    end

    local function heldTool()
        local tool = store.hand and store.hand.tool
        local meta = tool and bedwars.ItemMeta[tool.Name]
        return meta and meta.breakBlock and tool or nil
    end

    local function heldOnly()
        return not AutoTool.Enabled and (LimitItem.Enabled or isLegit())
    end

    local function heldHits(block, pos)
        return breakmethods.Health(block, pos, true)
    end

    local function inCombat()
        local combat = vape.Libraries.combat
        return combat ~= nil and combat:IsInCombat() == true
    end

    local function cellsOf(block)
        local handler = bedwars.BlockController:getHandlerRegistry():getHandler(block.Name)
        return handler and handler:getContainedPositions(block) or {block.Position / 3}
    end

    local function breakable(v, localPosition, reach)
        return v.Parent ~= nil
            and (v.Position - localPosition).Magnitude < reach
            and bedwars.BlockController:isBlockBreakable({blockPosition = v.Position / 3}, lplr)
            and (SelfBreak.Enabled or v:GetAttribute('PlacedByUserId') ~= lplr.UserId)
            and (v:GetAttribute('BedShieldEndTime') or 0) <= workspace:GetServerTimeNow()
    end

    local function nearest(tab, localPosition, reach, limit)
        local found = {}
        for _, v in tab do
            if breakable(v, localPosition, reach) then
                table.insert(found, v)
            end
        end
        table.sort(found, function(a, b)
            return (a.Position - localPosition).Magnitude < (b.Position - localPosition).Magnitude
        end)
        for index = #found, limit + 1, -1 do
            found[index] = nil
        end
        return found
    end

    local lockedTarget, lockedBlock, lockedPos, lostAt = nil, nil, nil, nil

    local function unlock()
        lockedTarget, lockedBlock, lockedPos, lostAt = nil, nil, nil, nil
    end

    local function drawPath(target, path, endpos)
        if not path then return end
        local currentnode = target
        for _, part in parts do
            part.Position = currentnode or Vector3.zero
            if currentnode then
                part.BoxHandleAdornment.Color3 = currentnode == endpos and Color3.new(1, 0.2, 0.2) or currentnode == target and Color3.new(0.2, 0.2, 1) or Color3.new(0.2, 1, 0.2)
            end
            currentnode = path[currentnode]
        end
    end

    local function strike(v, direct)
        local legit = isLegit()
        local only = heldOnly()
        return bedwars.breakBlock(
            v,
            Effect.Enabled,
            Animation.Enabled,
            CustomHealth.Enabled and customHealthbar or nil,
            AutoTool.Enabled,
            only and heldHits or breakmethods.Health,
            legit and (ViewAngle and ViewAngle.Value or Angle.Value) or 360,
            legit and isVisible or nil,
            {Legit = legit, HeldOnly = only, Direct = direct, Range = breakRange()}
        )
    end

    local function swing(v, direct)
        local delay = 0.25
        if isLegit() then
            delay = 0.3 + rng:NextNumber(0, 0.05)
            local roll = BreakChance.Value < 100 and (not CombatOnly.Enabled or inCombat())
            if roll and rng:NextNumber(0, 100) >= BreakChance.Value then
                task.wait(delay)
                return true
            end
        end
        local target, path, endpos = strike(v, direct)
        if not target then return false end
        drawPath(target, path, endpos)
        task.wait(delay)
        return true
    end

    local function legitEntry(v, localPosition, reach)
        local best, bestScore, bestCost = nil, math.huge, math.huge
        local only = heldOnly()
        for _, cell in cellsOf(v) do
            local pos, cost, _, depth = bedwars.calculateBreakPath(v, cell * 3, only and heldHits or breakmethods.Health, Angle.Value, isVisible, {Legit = true, HeldOnly = only, Range = reach})
            if pos then
                local score = (pos - localPosition).Magnitude + (depth or 0) * 3
                if score < bestScore or (score == bestScore and cost < bestCost) then
                    best, bestScore, bestCost = pos, score, cost
                end
            end
        end
        if best then
            return getPlacedBlock(best), best
        end
    end

    local function legitStep(lists, localPosition)
        local reach = breakRange()
        if (LimitItem.Enabled or not AutoTool.Enabled) and not heldTool() then return false end

        if lockedBlock then
            local held = lockedBlock.Parent ~= nil
                and getPlacedBlock(lockedPos) == lockedBlock
                and (lockedPos - localPosition).Magnitude <= reach
                and breakable(lockedTarget, localPosition, reach + 9)
            local listed = false
            for _, tab in lists do
                if tab and table.find(tab, lockedTarget) then
                    listed = true
                    break
                end
            end
            if held and listed then
                if isVisible(lockedPos) then
                    lostAt = nil
                    return swing(lockedBlock, lockedPos)
                end
                lostAt = lostAt or tick()
                if tick() - lostAt < 1 then return true end
            end
            unlock()
        end

        for _, tab in lists do
            if not tab then continue end
            for _, v in nearest(tab, localPosition, reach + 9, 4) do
                local block, pos = legitEntry(v, localPosition, reach)
                if block then
                    lockedTarget, lockedBlock, lockedPos = v, block, pos
                    return swing(block, pos)
                end
            end
        end
        return false
    end

    local function blatantStep(tab, localPosition)
        if not tab then return false end
        if LimitItem.Enabled and not heldTool() then return false end
        local reach = breakRange()
        local only = heldOnly()
        local method = only and heldHits or breakmethods.Health
        local best, bestCost = nil, math.huge
        for _, v in nearest(tab, localPosition, reach, 6) do
            for _, cell in cellsOf(v) do
                local pos, cost = bedwars.calculateBreakPath(v, cell * 3, method, 360, nil, {Legit = false, HeldOnly = only, Range = reach})
                if pos and cost < bestCost then
                    best, bestCost = v, cost
                end
            end
        end
        return best ~= nil and swing(best)
    end

    Breaker = vape.Categories.World:CreateModule({
        Name = 'Breaker',
        Function = function(callback)
            if callback then
                for _ = 1, 30 do
                    local part = Instance.new('Part')
                    part.Anchored = true
                    part.CanQuery = false
                    part.CanCollide = false
                    part.Transparency = 1
                    part.Parent = gameCamera
                    local highlight = Instance.new('BoxHandleAdornment')
                    highlight.Size = Vector3.one
                    highlight.AlwaysOnTop = true
                    highlight.ZIndex = 1
                    highlight.Transparency = 0.5
                    highlight.Adornee = part
                    highlight.Parent = part
                    table.insert(parts, part)
                end

                local beds = collection('bed', Breaker)
                local luckyblock = collection('LuckyBlock', Breaker)
                local ironores = collection('iron_ore_mesh_block', Breaker)
                local teslas = collection('tesla-trap', Breaker, function(tab, obj)
				task.delay(0.1, function()
					local player = playersService:GetPlayerByUserId(obj:GetAttribute('PlacedByUserId'))
					if player and player:GetAttribute('Team') ~= lplr:GetAttribute('Team') then
						table.insert(tab, obj)
					end
				end)
			end)
			local hives = collection('beehive', Breaker, function(tab, obj)
				task.delay(0.1, function()
					local player = playersService:GetPlayerByUserId(obj:GetAttribute('PlacedByUserId'))
					if player and player:GetAttribute('Team') ~= lplr:GetAttribute('Team') then
						table.insert(tab, obj)
					end
				end)
			end)

                customlist = collection('block', Breaker, function(tab, obj)
                    if table.find(Custom.ListEnabled, obj.Name) then
                        table.insert(tab, obj)
                    end
                end)

                repeat
                    task.wait(math.max(1 / UpdateRate.Value, (BreakSpeed and BreakSpeed.Value) or 0))
                    if not Breaker.Enabled then break end
                    if entitylib.isAlive then
                        local localPosition = entitylib.character.RootPart.Position

                        local lists = {Targets:Has('Bed') and beds, Targets:Has('Tesla') and teslas, Targets:Has('Hive') and hives, customlist, Targets:Has('Lucky Block') and luckyblock, Targets:Has('Iron Ore') and ironores}
                        local handled = false
                        if isLegit() then
                            refreshFilter()
                            handled = legitStep(lists, localPosition)
                        else
                            for index = 1, 6 do
                                if blatantStep(lists[index], localPosition) then
                                    handled = true
                                    break
                                end
                            end
                        end
                        if handled then continue end

                        for _, v in parts do
                            v.Position = Vector3.zero
                        end
                    end
                until not Breaker.Enabled
            else
                unlock()
                for _, v in parts do
                    v:ClearAllChildren()
                    v:Destroy()
                end
                table.clear(parts)
            end
        end,
        Tooltip = 'Breaks blocks around you',
        ExtraText = function()
            return BreakerType.Value
        end
    })
    BreakerType = Breaker:CreateDropdown({
        Name = 'Breaker Type',
        List = {'Blatant', 'Legit'},
        Default = 'Blatant',
        Tooltip = 'Blatant - the fastest way in, through walls\nLegit - only blocks you could reach yourself',
        Function = function(val)
            unlock()
            if val == 'Legit' and Range and Range.Value > LEGIT_RANGE then
                Range:SetValue(LEGIT_RANGE)
            end
        end
    })
    BreakChance = Breaker:CreateSlider({
        Name = 'Break Chance',
        Min = 1,
        Max = 100,
        Default = 100,
        Suffix = '%',
        Darker = true,
        Visible = function()
            return BreakerType.Value == 'Legit'
        end,
        Tooltip = 'Chance that each mining hit is sent'
    })
    CombatOnly = Breaker:CreateToggle({
        Name = 'Only while in combat',
        Darker = true,
        Visible = function()
            return BreakerType.Value == 'Legit'
        end,
        Tooltip = 'Only applies Break Chance during fights'
    })
    Angle = Breaker:CreateSlider({
        Name = 'Max angle',
        Min = 1,
        Max = 360,
        Default = 120,
        Darker = true,
        Visible = function()
            return BreakerType.Value == 'Legit'
        end,
        Tooltip = 'How far from your view a block can be'
    })
    Range = Breaker:CreateSlider({
        Name = 'Break range',
        Min = 1,
        Max = 30,
        Default = 30,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end,
        Function = function(val)
            if val > LEGIT_RANGE and BreakerType.Value == 'Legit' then
                Range:SetValue(LEGIT_RANGE)
            end
        end,
        Tooltip = 'How far away a block can be mined'
    })
    Breaker:CreateButton({
        Name = 'Reset to legit range',
        Tooltip = 'Sets the range back to the game\'s default',
        Function = function()
            Range:SetValue(LEGIT_RANGE)
        end
    })
    UpdateRate = Breaker:CreateSlider({
        Name = 'Update rate',
        Min = 1,
        Max = 120,
        Default = 60,
        Suffix = 'hz'
    })
    Custom = Breaker:CreateTextList({
        Name = 'Custom',
        Function = function()
            if not customlist then return end
            table.clear(customlist)
            for _, obj in store.blocks do
                if table.find(Custom.ListEnabled, obj.Name) then
                    table.insert(customlist, obj)
                end
            end
        end
    })
    Targets = Breaker:CreateMultiDropdown({
        Name = 'Break',
        List = {'Bed', 'Tesla', 'Hive', 'Lucky Block', 'Iron Ore'},
        Default = {'Bed', 'Tesla', 'Hive', 'Lucky Block', 'Iron Ore'},
        Tooltip = 'What it breaks'
    })
    Effect = Breaker:CreateGroup({
        Name = 'Show Healthbar & Effects',
        Function = function(callback)
            if CustomHealth and CustomHealth.Object then
            end
        end,
        Default = true
    })
    CustomHealth = Effect:CreateToggle({
        Name = 'Custom Healthbar',
        Default = true,
        Darker = true
    })
    Animation = Breaker:CreateToggle({Name = 'Animation'})
    SelfBreak = Breaker:CreateToggle({Name = 'Self Break'})
    AutoTool = Breaker:CreateToggle({
        Name = 'Auto Tool',
        Tooltip = 'Uses the best tool you own for each block'
    })

    ClosestBreak = Breaker:CreateToggle({
        Name = 'Closest break',
        Default = false,
        Tooltip = 'Always pick the block nearest your crosshair (through players)'
    })
    SmartBreak = Breaker:CreateToggle({
        Name = 'Smart Break',
        Default = true,
        Tooltip = 'Prioritize low health blocks and visible beds'
    })
    ViewAngle = Breaker:CreateSlider({
        Name = 'View angle',
        Min = 5,
        Max = 180,
        Default = 60,
        Suffix = 'degrees',
        Darker = true,
        Tooltip = 'How far off crosshair a block can sit in legit mode'
    })
    BreakSpeed = Breaker:CreateSlider({
        Name = 'Break speed',
        Min = 0,
        Max = 0.3,
        Default = 0.15,
        Decimal = 100,
        Tooltip = 'Wait between hits (lower = faster)'
    })
    PlayerCheck = Breaker:CreateToggle({
        Name = 'Player check',
        Default = false,
        Tooltip = 'Skip blocks when a player is near them'
    })
    -- extra block types Motion had
    if Targets and Targets.List then
        pcall(function()
            for _, extra in {'Snow', 'Pinata', 'Crops'} do
                if not table.find(Targets.List, extra) then
                    table.insert(Targets.List, extra)
                end
            end
        end)
    end

    LimitItem = Breaker:CreateToggle({
        Name = 'Limit to items',
        Tooltip = 'Only works while holding the item it uses'
    })

end)

-- ===== World/FastPlace.lua =====
run(function()
    local FastPlace
    local CPS
    local originalCPS

    local function restore()
        if originalCPS ~= nil then
            bedwars.SharedConstants.BLOCK_PLACE_CPS = originalCPS
            originalCPS = nil
        end
    end

    FastPlace = vape.Categories.World:CreateModule({
        Name = 'FastPlace',
        ExtraText = function() return tostring(CPS.Value) end,
        Function = function(enabled)
            if enabled then
                
                originalCPS = bedwars.SharedConstants.BLOCK_PLACE_CPS or 12
                bedwars.SharedConstants.BLOCK_PLACE_CPS = math.clamp(CPS.Value, 1, 20)
            else
                restore()
            end
        end,
        Tooltip = 'Lets you place blocks faster'
    })
    CPS = FastPlace:CreateSlider({
        Name = 'CPS', Min = 1, Max = 20, Default = 13,
        Function = function(value)
            if FastPlace.Enabled then bedwars.SharedConstants.BLOCK_PLACE_CPS = math.clamp(value, 1, 20) end
        end
    })
    FastPlace:CreateButton({Name = 'Use current BedWars CPS', Function = function()
        local current = originalCPS or bedwars.SharedConstants.BLOCK_PLACE_CPS or 12
        CPS:SetValue(math.clamp(current, 1, 20))
    end})
end)

-- ===== World/MineThrough.lua =====
run(function()
    local MineThrough
    local Place
    local Targets
    local Self

    local SCAN_DISTANCE = 64
    local SCAN_DISTANCE_SQ = SCAN_DISTANCE * SCAN_DISTANCE
    local QUERY_IGNORE = 'gamecore_GameQueryIgnore'

    local depth = 0
    local originalGetMouseInfo
    local selectorHook
    local originalHitBlock
    local breakHook

    local function invisible(entity)
        local root = entity.RootPart
        return root ~= nil and (root.Transparency >= 0.95 or root.LocalTransparencyModifier >= 0.95)
    end

    local function watched(entity)
        if Targets.Invisible.Enabled and invisible(entity) then return false end
        if entity.Player then
            return Targets.Players.Enabled
        end
        return Targets.NPCs.Enabled
    end

    local partCache = setmetatable({}, {__mode = 'k'})

    local function collectParts(character)
        local list = {}
        for _, part in character:GetDescendants() do
            if part:IsA('BasePart') then
                table.insert(list, part)
            end
        end
        return list
    end

    local function partsOf(character)
        local entry = partCache[character]
        if entry then
            if entry.Dirty then
                entry.Parts = collectParts(character)
                entry.Dirty = false
            end
            return entry.Parts
        end

        entry = {Parts = collectParts(character), Dirty = false}
        partCache[character] = entry
        character.DescendantAdded:Connect(function()
            entry.Dirty = true
        end)
        character.DescendantRemoved:Connect(function()
            entry.Dirty = true
        end)
        return entry.Parts
    end

    local hitboxes = {}
    local saved = {}
    local origin
    local total

    local function scan(character, root)
        if not character or not root then return end
        local offset = root.Position - origin
        if offset:Dot(offset) > SCAN_DISTANCE_SQ then return end
        for _, part in partsOf(character) do
            local ignored = part:GetAttribute(QUERY_IGNORE)
            if part.CanQuery and ignored ~= true then
                total += 1
                hitboxes[total] = part
                if ignored ~= nil then
                    saved[part] = ignored
                end
            end
        end
    end

    local function collect()
        origin = gameCamera.CFrame.Position
        total = 0

        for _, entity in entitylib.List do
            if watched(entity) then
                scan(entity.Character, entity.RootPart)
            end
        end
        if Self.Enabled and entitylib.isAlive then
            scan(entitylib.character.Character, entitylib.character.RootPart)
        end

        for index = total + 1, #hitboxes do
            hitboxes[index] = nil
        end

        return total
    end

    local charRay = RaycastParams.new()
    charRay.FilterType = Enum.RaycastFilterType.Include
    local charList, charListAt = {}, 0

    local function refreshCharacters()
        local now = os.clock()
        if now - charListAt < 0.25 then return end
        charListAt = now
        table.clear(charList)
        for _, entity in entitylib.List do
            if entity.Character and watched(entity) then
                table.insert(charList, entity.Character)
            end
        end
        if Self.Enabled and entitylib.isAlive and entitylib.character.Character then
            table.insert(charList, entitylib.character.Character)
        end
        charRay.FilterDescendantsInstances = charList
    end

    local function entityInTheWay()
        refreshCharacters()
        if #charList == 0 then return false end
        local camera = workspace.CurrentCamera
        if not camera then return true end
        local mouse = inputService:GetMouseLocation()
        local ray = camera:ViewportPointToRay(mouse.X, mouse.Y)
        return workspace:Raycast(ray.Origin, ray.Direction * SCAN_DISTANCE, charRay) ~= nil
    end

    local function ignoreHitboxes(callback, ...)
        if depth > 0 then return callback(...) end
        if not entityInTheWay() then return callback(...) end

        local count = collect()
        if count == 0 then
            return callback(...)
        end

        depth = 1

        for index = 1, count do
            local part = hitboxes[index]
            part.CanQuery = false
            part:SetAttribute(QUERY_IGNORE, true)
        end

        local args = table.pack(...)
        local results = table.pack(xpcall(function()
            return callback(table.unpack(args, 1, args.n))
        end, function(err) return err end))

        for index = 1, count do
            local part = hitboxes[index]
            if part.Parent then
                part.CanQuery = true
                part:SetAttribute(QUERY_IGNORE, saved[part])
            end
        end
        if next(saved) ~= nil then
            table.clear(saved)
        end
        depth = 0

        if not results[1] then error(results[2], 0) end
        return table.unpack(results, 2, results.n)
    end

    local function hookSelector()
        if selectorHook then return end
        local selector = bedwars.BlockSelector
        if type(selector) ~= 'table' or type(selector.getMouseInfo) ~= 'function' then return end

        originalGetMouseInfo = selector.getMouseInfo
        selectorHook = function(self, mode, ...)
            if depth > 0 or not MineThrough.Enabled or (mode == 0 and not Place.Enabled) then
                return originalGetMouseInfo(self, mode, ...)
            end
            return ignoreHitboxes(originalGetMouseInfo, self, mode, ...)
        end
        selector.getMouseInfo = selectorHook
    end

    local function unhookSelector()
        if not selectorHook then return end
        if bedwars.BlockSelector.getMouseInfo == selectorHook then
            bedwars.BlockSelector.getMouseInfo = originalGetMouseInfo
            selectorHook, originalGetMouseInfo = nil, nil
        end
    end

    local function hookBreak()
        if breakHook then return end
        local breaker = bedwars.BlockBreaker
        if type(breaker) ~= 'table' or type(breaker.hitBlock) ~= 'function' then return end

        originalHitBlock = breaker.hitBlock
        breakHook = function(self, ...)
            if depth > 0 or not MineThrough.Enabled then
                return originalHitBlock(self, ...)
            end
            return ignoreHitboxes(originalHitBlock, self, ...)
        end
        breaker.hitBlock = breakHook
    end

    local function unhookBreak()
        if not breakHook then return end
        if bedwars.BlockBreaker.hitBlock == breakHook then
            bedwars.BlockBreaker.hitBlock = originalHitBlock
            breakHook, originalHitBlock = nil, nil
        end
    end

    MineThrough = vape.Categories.World:CreateModule({
        Name = 'MineThrough',
        Tooltip = 'Mines the block behind an entity under your cursor',
        Function = function(enabled)
            if enabled then
                hookSelector()
                hookBreak()
                bedwars.MineThrough = Place.Enabled and ignoreHitboxes or nil
            else
                bedwars.MineThrough = nil
                unhookSelector()
                unhookBreak()
            end
        end,
        ExtraText = function()
            return Place.Enabled and 'Mine + place' or 'Mine'
        end
    })
    Targets = MineThrough:CreateTargets({
        Players = true,
        NPCs = true,
        Tooltip = 'Who it mines through',
    })
    Place = MineThrough:CreateToggle({
        Name = 'Place',
        Default = true,
        Tooltip = 'Lets you place blocks through entities',
        Function = function(value)
            if MineThrough.Enabled then
                bedwars.MineThrough = value and ignoreHitboxes or nil
            end
        end
    })
    Self = MineThrough:CreateToggle({
        Name = 'Self',
        Default = true,
        Tooltip = 'Also ignores your own hitbox'
    })
end)

-- ===== World/NightmareEmote.lua =====
run(function()
    local anim
    local asset
    local trackingConnection
    local lastPosition
    local NightmareEmote
    local cachedRootPart
    local cachedHumanoid
    local lastValidationCheck = 0

    NightmareEmote = vape.Categories.World:CreateModule({
        Name = "NightmareEmote",
        Function = function(call)
            if call then
                local l__GameQueryUtil__8
                if (not shared.CheatEngineMode) then
                    l__GameQueryUtil__8 = require(game:GetService("ReplicatedStorage")['rbxts_include']['node_modules']['@easy-games']['game-core'].out).GameQueryUtil
                else
                    local backup = {}; function backup:setQueryIgnored() end; l__GameQueryUtil__8 = backup;
                end
                local l__TweenService__9 = tweenService
                local player = playersService.LocalPlayer
                local character = player.Character

                if not character then
                    NightmareEmote:Toggle()
                    return
                end

                local humanoid = character:WaitForChild("Humanoid")
                local rootPart = character.PrimaryPart or character:FindFirstChild("HumanoidRootPart")

                if not rootPart then
                    NightmareEmote:Toggle()
                    return
                end

                cachedRootPart = rootPart
                cachedHumanoid = humanoid
                lastPosition = rootPart.Position
                lastValidationCheck = 0

                local v10 = game:GetService("ReplicatedStorage"):WaitForChild("Assets"):WaitForChild("Effects"):WaitForChild("NightmareEmote"):Clone()
                asset = v10
                v10.Parent = game.Workspace

                local descendants = v10:GetDescendants()
                for _, part in ipairs(descendants) do
                    if part:IsA("BasePart") then
                        l__GameQueryUtil__8:setQueryIgnored(part, true)
                        part.CanCollide = false
                        part.Anchored = true
                    end
                end

                local l__Outer__15 = v10:FindFirstChild("Outer")
                if l__Outer__15 then
                    l__TweenService__9:Create(l__Outer__15, TweenInfo.new(1.5, Enum.EasingStyle.Linear, Enum.EasingDirection.Out, -1), {
                        Orientation = l__Outer__15.Orientation + Vector3.new(0, 360, 0)
                    }):Play()
                end

                local l__Middle__16 = v10:FindFirstChild("Middle")
                if l__Middle__16 then
                    l__TweenService__9:Create(l__Middle__16, TweenInfo.new(12.5, Enum.EasingStyle.Linear, Enum.EasingDirection.Out, -1), {
                        Orientation = l__Middle__16.Orientation + Vector3.new(0, -360, 0)
                    }):Play()
                end

                anim = Instance.new("Animation")
                anim.AnimationId = "rbxassetid://9191822700"
                anim = humanoid:LoadAnimation(anim)
                anim:Play()

                local movementThresholdSq = 0.1 * 0.1

                trackingConnection = runService.RenderStepped:Connect(function()
                    if not asset or not asset.Parent then
                        if trackingConnection then
                            trackingConnection:Disconnect()
                        end
                        return
                    end

                    local currentTime = tick()

                    if (currentTime - lastValidationCheck) > 0.5 then
                        if not character or not character.Parent then
                            asset:Destroy()
                            asset = nil
                            if trackingConnection then
                                trackingConnection:Disconnect()
                            end
                            NightmareEmote:Toggle()
                            return
                        end

                        if not cachedRootPart or not cachedRootPart.Parent then
                            cachedRootPart = character.PrimaryPart or character:FindFirstChild("HumanoidRootPart")
                        end

                        if not cachedHumanoid or not cachedHumanoid.Parent then
                            cachedHumanoid = character:FindFirstChildOfClass("Humanoid")
                        end

                        if not cachedRootPart or not cachedHumanoid or cachedHumanoid.Health <= 0 then
                            asset:Destroy()
                            asset = nil
                            if trackingConnection then
                                trackingConnection:Disconnect()
                            end
                            NightmareEmote:Toggle()
                            return
                        end

                        lastValidationCheck = currentTime
                    end

                    if lastPosition and cachedRootPart then
                        local currentPosition = cachedRootPart.Position
                        local dx = currentPosition.X - lastPosition.X
                        local dy = currentPosition.Y - lastPosition.Y
                        local dz = currentPosition.Z - lastPosition.Z
                        local distanceMovedSq = dx * dx + dy * dy + dz * dz

                        if distanceMovedSq > movementThresholdSq then
                            asset:Destroy()
                            asset = nil
                            if trackingConnection then
                                trackingConnection:Disconnect()
                            end
                            NightmareEmote:Toggle()
                            return
                        end

                        lastPosition = currentPosition
                    end

                    if cachedRootPart then
                        v10:SetPrimaryPartCFrame(cachedRootPart.CFrame * CFrame.new(0, -3, 0))
                    end
                end)

                NightmareEmote:Clean(trackingConnection)

            else
                if trackingConnection then
                    trackingConnection:Disconnect()
                    trackingConnection = nil
                end

                if anim then
                    anim:Stop()
                    anim = nil
                end

                if asset then
                    asset:Destroy()
                    asset = nil
                end

                lastPosition = nil
                cachedRootPart = nil
                cachedHumanoid = nil
                lastValidationCheck = 0
            end
        end
    })
end)

-- ===== World/Schematica.lua =====
run(function()
    local Schematica
    local File
    local Mode
    local Transparency
    local Rotation
    local Mirror
    local VerticalOffset
    local Layer
    local parts, guidata, poschecklist = {}, {}, {}
    local point1, point2

    for x = -3, 3, 3 do
        for y = -3, 3, 3 do
            for z = -3, 3, 3 do
                if Vector3.new(x, y, z) ~= Vector3.zero then
                    table.insert(poschecklist, Vector3.new(x, y, z))
                end
            end
        end
    end

    local function checkAdjacent(pos)
        for _, v in poschecklist do
            if getPlacedBlock(pos + v) then return true end
        end
        return false
    end

    local function getPlacedBlocksInPoints(s, e)
        local list, blocks = {}, bedwars.BlockController:getStore()
        for x = (e.X > s.X and s.X or e.X), (e.X > s.X and e.X or s.X) do
            for y = (e.Y > s.Y and s.Y or e.Y), (e.Y > s.Y and e.Y or s.Y) do
                for z = (e.Z > s.Z and s.Z or e.Z), (e.Z > s.Z and e.Z or s.Z) do
                    local vec = Vector3.new(x, y, z)
                    local block = blocks:getBlockAt(vec)
                    if block and block:GetAttribute('PlacedByUserId') == lplr.UserId then
                        list[vec] = block
                    end
                end
            end
        end
        return list
    end

    local function loadMaterials()
        for _, v in guidata do
            v:Destroy()
        end
        local suc, read = pcall(function()
            return isfile(File.Value) and httpService:JSONDecode(readfile(File.Value))
        end)

        if suc and read then
            local items = {}
            for _, v in read do
                items[v[2]] = (items[v[2]] or 0) + 1
            end

            for i, v in items do
                local holder = Instance.new('Frame')
                holder.Size = UDim2.new(1, 0, 0, 32)
                holder.BackgroundTransparency = 1
                holder.Parent = Schematica.Children
                local icon = Instance.new('ImageLabel')
                icon.Size = UDim2.fromOffset(24, 24)
                icon.Position = UDim2.fromOffset(4, 4)
                icon.BackgroundTransparency = 1
                icon.Image = bedwars.getIcon({itemType = i}, true)
                icon.Parent = holder
                local text = Instance.new('TextLabel')
                text.Size = UDim2.fromOffset(100, 32)
                text.Position = UDim2.fromOffset(32, 0)
                text.BackgroundTransparency = 1
                local ownedItem = getItem(i)
                local owned = ownedItem and ownedItem.amount or 0
                text.Text = (bedwars.ItemMeta[i] and bedwars.ItemMeta[i].displayName or i)..': '..owned..' / '..v..(owned < v and '  missing '..(v - owned) or '')
                text.TextXAlignment = Enum.TextXAlignment.Left
                text.TextColor3 = uipallet.Text
                text.TextSize = 14
                text.FontFace = uipallet.Font
                text.Parent = holder
                table.insert(guidata, holder)
            end
            table.clear(read)
            table.clear(items)
        end
    end

    local function save()
        if point1 and point2 then
            local tab = getPlacedBlocksInPoints(point1, point2)
            local savetab = {}
            point1 = point1 * 3
            for i, v in tab do
                i = bedwars.BlockController:getBlockPosition(CFrame.lookAlong(point1, entitylib.character.RootPart.CFrame.LookVector):PointToObjectSpace(i * 3)) * 3
                table.insert(savetab, {
                    {
                        x = i.X,
                        y = i.Y,
                        z = i.Z
                    },
                    v.Name
                })
            end
            point1, point2 = nil, nil
            writefile(File.Value, httpService:JSONEncode(savetab))
            notif('Schematica', 'Saved '..getTableSize(tab)..' blocks', 5)
            loadMaterials()
            table.clear(tab)
            table.clear(savetab)
        else
            local mouseinfo = bedwars.BlockBreaker.clientManager:getBlockSelector():getMouseInfo(0)
            if mouseinfo and mouseinfo.target then
                if point1 then
                    point2 = mouseinfo.target.blockRef.blockPosition
                    notif('Schematica', 'Selected position 2, toggle again near position 1 to save it', 3)
                else
                    point1 = mouseinfo.target.blockRef.blockPosition
                    notif('Schematica', 'Selected position 1', 3)
                end
            end
        end
    end

    local function load(read)
        local mouseinfo = bedwars.BlockBreaker.clientManager:getBlockSelector():getMouseInfo(0)
        if mouseinfo and mouseinfo.target then
            local position = CFrame.new(mouseinfo.placementPosition * 3) * CFrame.Angles(0, math.rad(math.round(math.deg(math.atan2(-entitylib.character.RootPart.CFrame.LookVector.X, -entitylib.character.RootPart.CFrame.LookVector.Z)) / 45) * 45), 0)

            for _, v in read do
                local x, y, z = v[1].x, v[1].y, v[1].z
                if Mirror.Enabled then x = -x end
                local rotation = math.rad(tonumber(Rotation.Value) or 0)
                local transformed = CFrame.Angles(0, rotation, 0):VectorToWorldSpace(Vector3.new(x, y + VerticalOffset.Value * 3, z))
                if Layer.Value > 0 and math.floor(y / 3) + 1 ~= Layer.Value then continue end
                local blockpos = bedwars.BlockController:getBlockPosition((position * CFrame.new(transformed)).p) * 3
                if parts[blockpos] then continue end
                local handler = bedwars.BlockController:getHandlerRegistry():getHandler(v[2]:find('wool') and getWool() or v[2])
                if handler then
                    local part = handler:place(blockpos / 3, 0)
                    part.Transparency = Transparency.Value
                    part.CanCollide = false
                    part.Anchored = true
                    part.Parent = workspace
                    local existing = getPlacedBlock(blockpos)
                    part.Color = existing and (existing.Name == v[2] and Color3.fromRGB(75, 200, 105) or Color3.fromRGB(230, 150, 45)) or Color3.fromRGB(225, 75, 85)
                    parts[blockpos] = part
                end
            end
            table.clear(read)

            repeat
                if entitylib.isAlive then
                    local localPosition = entitylib.character.RootPart.Position
                    for i, v in parts do
                        local reachable = (i - localPosition).Magnitude < 60 and checkAdjacent(i)
                        v.Color = reachable and Color3.fromRGB(225, 75, 85) or Color3.fromRGB(110, 110, 120)
                        if reachable then
                            if not Schematica.Enabled then break end
                            if not getItem(v.Name) then continue end
                            bedwars.placeBlock(i, v.Name, false)
                            task.delay(0.1, function()
                                local block = getPlacedBlock(i)
                                if block then
                                    v:Destroy()
                                    parts[i] = nil
                                end
                            end)
                        end
                    end
                end
                task.wait()
            until getTableSize(parts) <= 0

            if getTableSize(parts) <= 0 and Schematica.Enabled then
                notif('Schematica', 'Finished building', 5)
                Schematica:Toggle()
            end
        end
    end
end)

-- ===== World/ShadowRemover.lua =====
run(function()
	local ShadowRemover
	local connections = {}
	local originalShadows = {}
	local processedShadows = {}
	
	local function removeShadow(obj)
		if obj:IsA("BasePart") and not processedShadows[obj] then
			if not originalShadows[obj] then
				originalShadows[obj] = obj.CastShadow
			end
			obj.CastShadow = false
			processedShadows[obj] = true
		end
	end
	
	ShadowRemover = vape.Categories.World:CreateModule({
		Name = 'ShadowRemover',
		Function = function(callback)
			if callback then
				scanDescendants(workspace, removeShadow, ShadowRemover)
				
				local conn = workspace.DescendantAdded:Connect(function(obj)
					if ShadowRemover.Enabled then
						removeShadow(obj)
					end
				end)
				table.insert(connections, conn)
			else
				for obj, shadow in pairs(originalShadows) do
					if obj and obj.Parent then
						pcall(function()
							obj.CastShadow = shadow
						end)
					end
				end
				
				for _, conn in connections do
					conn:Disconnect()
				end
				table.clear(connections)
				table.clear(originalShadows)
				table.clear(processedShadows)
			end
		end,
	})
end)

-- ===== Kits/AntiLasso.lua =====
run(function()
	local AntiLasso
	local Chance
	local watching = setmetatable({}, {__mode = 'k'})
	
	local function Added(ent)
		if watching[ent] then return end
	
		watching[ent] = ent.ChildAdded:Connect(function(v)
			if not AntiLasso.Enabled then return end
			if v:IsA('Accessory') and v:FindFirstChild('Rope') and Random.new(os.clock()):NextNumber(1, 100) < Chance.Value then
				ent.PrimaryPart.Anchored = true
				v.Destroying:Once(function()
					task.wait(0.5)
					ent.PrimaryPart.Anchored = false
				end)
			end
		end)
	end
	
	AntiLasso = vape.Categories.Kits:CreateModule({
		Name = 'AntiLasso',
		Function = function(callback)
			if callback then
				AntiLasso:Clean(entitylib.Events.LocalAdded:Connect(function(ent)
					task.delay(1, function()
						Added(ent.Character)
					end)
				end))
				if entitylib.isAlive then
					Added(lplr.Character)
				end
			else
				local char = lplr.Character
				local root = char and char.PrimaryPart
				if root then
					pcall(function() root.Anchored = false end)
				end
			end
		end,
		Tooltip = 'stops u gettin yanked by the lasso'
	})
	
	Chance = AntiLasso:CreateSlider({
		Name = 'Chance',
		Min = 0,
		Max = 100,
		Default = 100,
		Suffix = '%'
	})
end)

-- ===== Kits/AutoAbaddon.lua =====
run(function()

	local util = vape.Libraries.bedwarsutil
	local AutoAbaddon
	local Delay
	local Limit
	local Range
	local nextPlace = 0

	AutoAbaddon = kits:CreateModule({
		Name = 'AutoAbaddon',
		Function = function(callback)
			if callback then
				nextPlace = 0

				repeat
					if entitylib.isAlive and store.equippedKit == 'scarab' and tick() >= nextPlace and bedwars.AbilityController:canUseAbility('place_scarab_hive', {disableBlockedAbilityAlert = true}) then
						local origin = entitylib.character.RootPart.Position
						local hives = 0

						for _, v in collectionService:GetTagged('scarab_spawner') do
							local part = v:IsA('Model') and v.PrimaryPart or v
							if part and part:GetAttribute('PlacedByUserId') == lplr.UserId and (part.Position - origin).Magnitude <= Range.Value then
								hives += 1
							end
						end

						if hives < Limit.Value then
							nextPlace = tick() + Delay.Value
							bedwars.AbilityController:useAbility('place_scarab_hive')
						end
					end
					task.wait(0.1)
				until not AutoAbaddon.Enabled
			end
		end,
		Tooltip = 'Keeps scarab hives up around you'
	})

	Limit = AutoAbaddon:CreateSlider({
		Name = 'Hives',
		Min = 1,
		Max = 10,
		Default = 3,
		Tooltip = 'Stops at this many hives nearby'
	})
	Range = AutoAbaddon:CreateSlider({
		Name = 'Range',
		Min = 5,
		Max = 100,
		Default = 40,
		Suffix = util.Studs,
		Tooltip = 'How far out hives still count toward the limit'
	})
	Delay = AutoAbaddon:CreateSlider({
		Name = 'Delay',
		Min = 0.1,
		Max = 5,
		Default = 1.5,
		Decimal = 100,
		Suffix = util.Seconds
	})
end)

-- ===== Kits/AutoAdetunde.lua =====
run(function()
	local GetItem = getItem
	local LocalPlayer = lplr
	local AutoAdetunde
	local GUI
	local Last

	local Upgrades: {string} = {}
	for Upgrade: string in bedwars.AdetundeUpgradeMeta do
		table.insert(Upgrades, Upgrade)
	end
	table.sort(Upgrades)

	local function GetBuyOrder(Tiers: {[string]: number}): {string}
		local LastUpgrade: string? = Last.Value ~= "None" and Last.Value or nil
		local Order, Waiting = {}, false
		for _, v: string in Upgrades do
			if Tiers[v] == nil or v == LastUpgrade then
				continue
			end
			table.insert(Order, v)
			if AutoAdetunde.Options.Buy:Has(v) and bedwars.AdetundeUpgradeMeta[v].tiers[Tiers[v] + 1] then
				Waiting = true
			end
		end
		if LastUpgrade and Tiers[LastUpgrade] and not Waiting then
			table.insert(Order, LastUpgrade)
		end
		return Order
	end

	AutoAdetunde = kits:CreateModule({
		Name = "AutoAdetunde",
		Function = function(Callback: boolean)
			if Callback then
				repeat
					if not GUI.Enabled or bedwars.AppController:isAppOpen("FrostyHammerApp") then
						local Tiers: {[string]: number} = bedwars.AdetundeUtil.getUpgradesFromHammer(LocalPlayer) or {}
						for _, Upgrade: string in GetBuyOrder(Tiers) do
							local Crystal = GetItem("frost_crystal")
							if not Crystal then
								break
							end

							local NextUpgrade = AutoAdetunde.Options.Buy:Has(Upgrade) and bedwars.AdetundeUpgradeMeta[Upgrade].tiers[Tiers[Upgrade] + 1]
							if NextUpgrade and Crystal.amount >= NextUpgrade.price then
								bedwars.Handler:Get("UpgradeFrostyHammer"):Fire("CallServer", Upgrade)
								task.wait(0.1)
							end
						end
					end
					task.wait(0.5)
				until not AutoAdetunde.Enabled
			end
		end,
		Tooltip = "Upgrades your frosty hammer automatically"
	})

	AutoAdetunde:CreateMultiDropdown({
		Name = "Buy",
		List = table.clone(Upgrades),
		Default = table.clone(Upgrades),
		Tooltip = "Hammer upgrades it buys"
	})

	local LastList: {string} = {"None"}
	for _, v: string in Upgrades do
		table.insert(LastList, v)
	end
	Last = AutoAdetunde:CreateDropdown({
		Name = "Last upgrade",
		List = LastList,
		Default = "None",
		Tooltip = 'Buys this upgrade last'
	})

	GUI = AutoAdetunde:CreateToggle({
		Name = "GUI Check",
		Tooltip = "Only upgrades while the frosty hammer menu is open"
	})
end)

-- ===== Kits/AutoAgni.lua =====
run(function()
	local AutoAgni
	local Targets, Range, OnlySwinging, Clutch
	local swingMarker, swingSeenAt = nil, -math.huge
	local ray = RaycastParams.new()
	ray.FilterType = Enum.RaycastFilterType.Exclude
	ray.RespectCanCollide = true

	local function updateSwing()
		local value = bedwars.SwordController and bedwars.SwordController.lastSwing or 0
		if value ~= swingMarker then
			swingMarker, swingSeenAt = value, os.clock()
		end
	end

	local function voidFall(root)
		if not root or root.AssemblyLinearVelocity.Y >= -2 then return false end
		ray.FilterDescendantsInstances = lplr.Character and {lplr.Character} or {}
		return workspace:Raycast(root.Position, Vector3.new(0, -80, 0), ray) == nil
	end

	local function abilityController()
		return bedwars.AbilityController
			or (bedwars.Knit and bedwars.Knit.Controllers and bedwars.Knit.Controllers.AbilityController)
	end

	local function activate()
		local controller = abilityController()
		if not controller then return false end
		if type(controller.canUseAbility) == 'function' then
			local ok, ready = pcall(controller.canUseAbility, controller, 'rocket_detonate', {disableBlockedAbilityAlert = true})
			if not ok or ready == false or ready == nil then return false end
		end
		if type(controller.useAbility) ~= 'function' then return false end
		local used, result = pcall(controller.useAbility, controller, 'rocket_detonate')
		return used and result ~= false
	end

	AutoAgni = kits:CreateModule({
		Name = 'AutoAgni',
		Category = 'Auto',
		Function = function(callback)
			if not callback then return end
			swingMarker, swingSeenAt = bedwars.SwordController and bedwars.SwordController.lastSwing or 0, -math.huge
			local nextUse = 0
			repeat
				if entitylib.isAlive and store.equippedKit == 'agni' then
					local root = entitylib.character.RootPart
					updateSwing()
					if root and Clutch.Enabled and voidFall(root) then
						if os.clock() >= nextUse and activate() then nextUse = os.clock() + 0.5 end

						local land = getNearGround(30)
						local humanoid = entitylib.character.Humanoid
						if land and humanoid then
							local delta = Vector3.new(land.X - root.Position.X, 0, land.Z - root.Position.Z)
							if delta.Magnitude > 0.05 then humanoid:Move(delta.Unit, false) end
						end
					elseif not OnlySwinging.Enabled or os.clock() - swingSeenAt <= 0.3 then
						local target = entitylib.EntityPosition({
							Range = Range.Value,
							Part = 'RootPart',
							Players = Targets.Players.Enabled,
							Priority = Targets.Priority and Targets.Priority.Value,
							NPCs = Targets.NPCs.Enabled,
							Wallcheck = Targets.Walls.Enabled or nil,
							Sort = sortmethods.Distance
						})
						if target and os.clock() >= nextUse and activate() then nextUse = os.clock() + 0.5 end
					end
				end
				task.wait(0.03)
			until not AutoAgni.Enabled
		end,
		Tooltip = 'Uses Agni\'s rocket boost near targets and to save void falls'
	})
	Targets = AutoAgni:CreateTargets({Players = true, NPCs = true, Walls = true})
	Range = AutoAgni:CreateSlider({Name = 'Range', Min = 1, Max = 40, Default = 12, Suffix = ' studs'})
	OnlySwinging = AutoAgni:CreateToggle({Name = 'Only while swinging'})
	Clutch = AutoAgni:CreateToggle({Name = 'Clutch', Default = true, Tooltip = 'Uses Agni when falling into the void'})
end)

-- ===== Kits/AutoAlchemist.lua =====
run(function()
	local AutoAlchemist
	local PotionSelect
	local BrewDelay

	local RECIPES = {
		['Heal Potion']   = { ingredients = { wild_flower = 3 } },
		['Sleep Potion']  = { ingredients = { mushrooms = 3 } },
		['Poison Potion'] = { ingredients = { thorns = 1, mushrooms = 2 } },
		['Big Shield']    = { ingredients = { thorns = 2, wild_flower = 1 } },
	}

	local INGREDIENT_NAMES = {
		wild_flower = 'Wild Flower',
		mushrooms   = 'Mushrooms',
		thorns      = 'Thorns',
	}

	local ABILITY_MAP = {
		wild_flower = 'alchemist_add_flower',
		mushrooms   = 'alchemist_add_mushrooms',
		thorns      = 'alchemist_add_thorns',
	}

	-- Find the useAbility RemoteEvent from ReplicatedStorage
	local useAbilityRemote
	task.spawn(function()
		for _, desc in replicatedStorage:GetDescendants() do
			if desc.Name == 'useAbility' and desc:IsA('RemoteEvent') then
				useAbilityRemote = desc
				break
			end
		end
		if not useAbilityRemote then
			replicatedStorage.DescendantAdded:Connect(function(desc)
				if desc.Name == 'useAbility' and desc:IsA('RemoteEvent') then
					useAbilityRemote = desc
				end
			end)
		end
	end)

	local lplr = game:GetService('Players').LocalPlayer

	local function getItemCount(itemType)
		if not store or not store.inventory or not store.inventory.inventory then return 0 end
		local count = 0
		for _, item in store.inventory.inventory.items do
			if item.itemType == itemType then
				count += (item.quantity or 1)
			end
		end
		return count
	end

	local function isHoldingFlask()
		if not store or not store.inventory then return false end
		local inv = store.inventory.inventory or store.inventory.observedInventory and store.inventory.observedInventory.inventory
		if not inv then return false end
		local hand = inv.hand
		return hand and hand.itemType == 'alchemist_flask'
	end

	local function getStagedCount(ingredient)
		local attr = lplr:GetAttribute('AlchemistFlaskBrewStage')
		if type(attr) ~= 'string' or attr == '' then return 0 end
		local count = 0
		for t in attr:gmatch('[^,]+') do
			if t:lower() == ingredient then count += 1 end
		end
		return count
	end

	local function fireAbility(abilityId)
		local ok = pcall(function()
			bedwars.AbilityController:useAbility(abilityId)
		end)
		if not ok and useAbilityRemote then
			pcall(function()
				useAbilityRemote:FireServer(abilityId, {})
			end)
		end
	end

	AutoAlchemist = vape.Categories.Kits:CreateModule({
		Name = 'AutoAlchemist',
		Function = function(callback)
			if callback then
				repeat
					task.wait(BrewDelay and BrewDelay.Value or 0.5)
					if not entitylib.isAlive then continue end
					if not isHoldingFlask() then continue end

					local selectedPotion = PotionSelect and PotionSelect.Value or 'Heal Potion'
					local recipe = RECIPES[selectedPotion]
					if not recipe then continue end

					-- Check for missing ingredients
					local missing = {}
					for ingredient, needed in pairs(recipe.ingredients) do
						local staged = getStagedCount(ingredient)
						local have = getItemCount(ingredient)
						local stillNeeded = math.max(0, needed - staged)
						if have < stillNeeded then
							table.insert(missing, (stillNeeded - have) .. 'x ' .. INGREDIENT_NAMES[ingredient])
						end
					end

					if #missing > 0 then
						vape.Notify({
							Title = 'AutoAlchemist',
							Description = 'Missing: ' .. table.concat(missing, ', '),
							Duration = 3
						})
						continue
					end

					-- Stage each ingredient that still needs to be added
					for ingredient, needed in pairs(recipe.ingredients) do
						local toAdd = math.max(0, needed - getStagedCount(ingredient))
						for _ = 1, toAdd do
							fireAbility(ABILITY_MAP[ingredient])
							task.wait(0.2)
						end
					end

				until not AutoAlchemist.Enabled
			end
		end,
		Tooltip = 'Auto brews selected potions with the Alchemist flask. Notifies on missing ingredients.'
	})

	PotionSelect = AutoAlchemist:CreateDropdown({
		Name = 'Potion',
		List = {'Heal Potion', 'Sleep Potion', 'Poison Potion', 'Big Shield'},
		Default = 'Heal Potion',
		Tooltip = 'Potion to auto brew'
	})

	BrewDelay = AutoAlchemist:CreateSlider({
		Name = 'Brew Delay',
		Min = 0.1,
		Max = 2,
		Default = 0.5,
		Decimal = 10,
		Tooltip = 'Delay between brew cycles'
	})
end)

