-- ===== Kits/AutoCrypt.lua =====
run(function()
	local AutoCrypt
	local AutoCollect
	local CollectRange
	local CollectDelay
	local SoulESP
	local ESPBackground
	local ESPColor
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui
	local Reference = {}
	local collectionActive = false
	local soulIcon = "rbxassetid://6307844310"

	local function Added(obj)
		if Reference[obj] then return end
		local part = not obj:IsA('Model') and obj or obj.PrimaryPart
		if not part then return end
		local billboard = Instance.new('BillboardGui')
		billboard.Parent = Folder
		billboard.Name = 'Gravestone'
		billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
		billboard.Size = UDim2.fromOffset(36, 36)
		billboard.AlwaysOnTop = true
		billboard.ClipsDescendants = false
		billboard.Adornee = part
		local blur = addBlur(billboard)
		blur.Visible = ESPBackground.Enabled
		local image = Instance.new('ImageLabel')
		image.Size = UDim2.fromOffset(36, 36)
		image.Position = UDim2.fromScale(0.5, 0.5)
		image.AnchorPoint = Vector2.new(0.5, 0.5)
		image.BackgroundColor3 = Color3.fromHSV(ESPColor.Hue, ESPColor.Sat, ESPColor.Value)
		image.BackgroundTransparency = 1 - (ESPBackground.Enabled and ESPColor.Opacity or 0)
		image.BorderSizePixel = 0
		image.Image = soulIcon
		image.Parent = billboard
		local uicorner = Instance.new('UICorner')
		uicorner.CornerRadius = UDim.new(0, 4)
		uicorner.Parent = image
		Reference[obj] = billboard
	end

	local function Removed(obj)
		if Reference[obj] then
			Reference[obj]:Destroy()
			Reference[obj] = nil
		end
	end

	local function setupESP()
		for _, v in collectionService:GetTagged('Gravestone') do
			Added(v)
		end
		AutoCrypt:Clean(collectionService:GetInstanceAddedSignal('Gravestone'):Connect(function(v)
			if SoulESP.Enabled then Added(v) end
		end))
		AutoCrypt:Clean(collectionService:GetInstanceRemovedSignal('Gravestone'):Connect(function(v)
			Removed(v)
		end))
		local lastUpdate = 0
		AutoCrypt:Clean(runService.RenderStepped:Connect(function()
			if not SoulESP.Enabled then return end
			local now = tick()
			if now - lastUpdate < 0.2 then return end
			lastUpdate = now
			for obj in pairs(Reference) do
				if not obj or not obj.Parent then
					Removed(obj)
				end
			end
		end))
	end

	local function startAutoCollect()
		if collectionActive then return end
		collectionActive = true
		task.spawn(function()
			while AutoCrypt.Enabled and AutoCollect.Enabled and collectionActive do
				if not entitylib.isAlive then
					task.wait(0.5)
					continue
				end
				local localPosition = entitylib.character.RootPart.Position
				local range = CollectRange.Value
				for _, obj in collectionService:GetTagged('Gravestone') do
					if not AutoCrypt.Enabled or not AutoCollect.Enabled or not collectionActive then break end
					local part = not obj:IsA('Model') and obj or obj.PrimaryPart
					if part and (localPosition - part.Position).Magnitude <= range then
						local armorType = obj:GetAttribute('ArmorType')
						local weaponType = obj:GetAttribute('SwordType')
						local associatedPlayerUserId = obj:GetAttribute('GravestonePlayerUserId')
						local secret = obj:GetAttribute('GravestoneSecret')
						local position = obj:GetAttribute('GravestonePosition')
						if secret then
							local ok, result = pcall(function()
								return bedwars.Client:Get(remotes.ActivateGravestone).instance:InvokeServer({
									skeletonData = {
										armorType = armorType,
										weaponType = weaponType,
										associatedPlayerUserId = associatedPlayerUserId
									},
									secret = secret,
									position = position
								})
							end)
							if ok and result and result.success then
								local NecroController = bedwars.Knit.Controllers.NecromancerController
								if NecroController then
									pcall(function()
										NecroController:useGravestone(lplr, obj)
									end)
								end
							end
							if CollectDelay.Value > 0 then
								task.wait(CollectDelay.Value)
							end
						end
					end
				end
				task.wait(0.1)
			end
			collectionActive = false
		end)
	end

	local function stopAutoCollect()
		collectionActive = false
	end

	AutoCrypt = vape.Categories.Kits:CreateModule({
		Name = 'AutoCrypt',
		Function = function(callback)
			if callback then
				if SoulESP.Enabled then setupESP() end
				if AutoCollect.Enabled then startAutoCollect() end
			else
				stopAutoCollect()
				Folder:ClearAllChildren()
				table.clear(Reference)
			end
		end,
		Tooltip = 'grabs gravestones + esp for crypt'
	})

	AutoCollect = AutoCrypt:CreateToggle({
		Name = 'Auto Collect',
		Tooltip = 'auto uses the gravestones no cap',
		Function = function(callback)
			if CollectRange and CollectRange.Object then CollectRange.Object.Visible = callback end
			if CollectDelay and CollectDelay.Object then CollectDelay.Object.Visible = callback end
			if AutoCrypt.Enabled then
				if callback then startAutoCollect() else stopAutoCollect() end
			end
		end
	})
	CollectRange = AutoCrypt:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 40,
		Default = 12,
		Visible = false
	})
	CollectDelay = AutoCrypt:CreateSlider({
		Name = 'Delay',
		Min = 0,
		Max = 1,
		Default = 0.1,
		Decimal = 100,
		Suffix = 's',
		Visible = false
	})

	SoulESP = AutoCrypt:CreateToggle({
		Name = 'SoulESP',
		Tooltip = 'shows u where the gravestones at',
		Function = function(callback)
			if ESPBackground and ESPBackground.Object then ESPBackground.Object.Visible = callback end
			if ESPColor and ESPColor.Object then ESPColor.Object.Visible = (callback and ESPBackground and ESPBackground.Enabled) end
			if AutoCrypt.Enabled then
				if callback then
					setupESP()
				else
					Folder:ClearAllChildren()
					table.clear(Reference)
				end
			end
		end
	})
	ESPBackground = AutoCrypt:CreateToggle({
		Name = 'Background',
		Default = true,
		Function = function(callback)
			if ESPColor and ESPColor.Object then ESPColor.Object.Visible = (callback and SoulESP and SoulESP.Enabled) end
			for _, v in Reference do
				if v and v:FindFirstChild('ImageLabel') then
					local blur = v:FindFirstChild('Blur')
					if blur then blur.Visible = callback end
					v.ImageLabel.BackgroundTransparency = 1 - (callback and ESPColor.Opacity or 0)
				end
			end
		end
	})
	ESPColor = AutoCrypt:CreateColorSlider({
		Name = 'Background Color',
		DefaultValue = 0,
		DefaultOpacity = 0.5,
		Darker = true,
		Function = function(hue, sat, val, opacity)
			for _, v in Reference do
				if v and v:FindFirstChild('ImageLabel') then
					v.ImageLabel.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
					v.ImageLabel.BackgroundTransparency = 1 - opacity
				end
			end
		end
	})

	task.defer(function()
		local collectOn = AutoCollect and AutoCollect.Enabled
		if CollectRange and CollectRange.Object then CollectRange.Object.Visible = collectOn end
		if CollectDelay and CollectDelay.Object then CollectDelay.Object.Visible = collectOn end
		local espOn = SoulESP and SoulESP.Enabled
		if ESPBackground and ESPBackground.Object then ESPBackground.Object.Visible = espOn end
		if ESPColor and ESPColor.Object then ESPColor.Object.Visible = (espOn and ESPBackground.Enabled) end
	end)
end)

-- ===== Kits/AutoCyber.lua =====
run(function()
	local AutoCyber
	local Mode
	local Whitelist
	local Visual
	local Steal
	local Target
	local Limit

	local teamCache, cacheExpire = nil, 0
	local function getTeamGenerator()
		if cacheExpire > tick() and teamCache and teamCache.Parent then
			return teamCache
		end
		teamCache, cacheExpire = collectionService:GetTagged(lplr:GetAttribute('Team').. '_TeamOreGenerator')[1], tick() + 5
		return teamCache
	end
	local cache = nil
	local function getDrone()
		if Limit.Enabled and (not store.hand.tool or store.hand.tool.Name ~= 'drone') then
			return nil
		end
		if cache and cache.Parent then
			return cache
		end
		for _, v in collectionService:GetTagged('Drone') do
			if v:GetAttribute('PlayerUserId') == lplr.UserId then
				local Changed = function()
					if v:GetAttribute('HeldItem') then
						repeat
							bedwars.Handler:Get('DropDroneItem'):Fire('SendToServer', {
								direction = Vector3.new(1000, 10, 0),
								position = v.PrimaryPart.Position
							})
							task.wait(0.1)
						until not v:GetAttribute('HeldItem') or not AutoCyber.Enabled
					end
				end
				AutoCyber:Clean(v:GetAttributeChangedSignal('HeldItem'):Connect(Changed))
				AutoCyber:Clean(v:GetAttributeChangedSignal('HeldItemAmount'):Connect(Changed))
				cache = v
				return v
			end
		end
		if getItem('drone') and bedwars.Handler:Get('FireGuidedProjectile'):Fire('CallServer', 'drone') then
			task.wait(0.1)
			return getDrone()
		end
		return nil
	end
	local function getGenerator(drone, item)
		local children = collectionService:GetTagged(item.. '_OreGenerator')
		local pos = drone.PrimaryPart.Position
		table.sort(children, function(a, b)
			return (pos - a.PrimaryPart.Position).Magnitude < (pos - b.PrimaryPart.Position).Magnitude
		end)
		return children[1] and children[1].PrimaryPart or nil
	end
	local blacklist = {}
	local function getItemDrop(drone)
		local generator = getTeamGenerator()
		generator = generator and generator.PrimaryPart.Position or Vector3.zero
		local children = workspace.ItemDrops:GetChildren()
		local pos = drone.PrimaryPart.Position
		table.sort(children, function(a, b)
			return (pos - a.Position).Magnitude < (pos - b.Position).Magnitude
		end)
		for _, v in children do
			if tick() > (blacklist[v] or 0) and table.find(Whitelist.ListEnabled, v.Name) and v.Position.Y > 0 and math.abs(v.Velocity.Y) <= 0 and (not Steal.Enabled or (v.Position - generator).Magnitude > 20) and (not Target.Enabled or not entitylib.EntityPosition({
				Origin = pos,
				Range = 60,
				Part = 'RootPart',
				Players = true
			})) then
				return v
			end
		end
		return nil
	end
	AutoCyber = kits:CreateModule({
		Name = 'AutoCyber',
		Function = function(callback)
			if callback then
				AutoCyber:Clean(workspace.ItemDrops.ChildAdded:Connect(function(v)
					task.wait()
					if v.Velocity.X > 100 then
						blacklist[v] = tick() + 5
						local Amount = v:GetAttribute('Amount')
						local LastParent = v.Parent
						if Mode.Value == 'Player' then
							notif('AutoCyber', 'Collecting '.. tostring(Amount).. ' '.. v.Name, 4, 'info')
							repeat
								v.Velocity = Vector3.zero
								v.CFrame = entitylib.character.RootPart.CFrame - Vector3.new(0, 4, 0)
								task.spawn(function()
									bedwars.Handler:Get('PickupItemDrop'):Fire('CallServerAsync', {
										itemDrop = v
									}):andThen(function(suc)
										if suc and bedwars.SoundList then
											bedwars.AudioManager:playAudio(bedwars.SoundList.PICKUP_ITEM_DROP)
											local sound = bedwars.ItemMeta[v.Name].pickUpOverlaySound
											if sound then
												bedwars.AudioManager:playAudio(sound, {
													position = v.Position,
													volumeMultiplier = 0.9
												})
											end
										end
									end)
								end)
								task.wait(0.02)
							until not v or v.Parent ~= LastParent

							notif('AutoCyber', `Collected {Amount} {v.Name}{Amount > 1 and 's' or ''}`, 4, 'info')
						else
							local start = tick()
							local generator = getTeamGenerator()
							if generator then
								repeat
									v.Velocity = Vector3.zero
									v.CFrame = generator.PrimaryPart.CFrame
									task.wait()
								until (tick() - start) >= 1 or not v or v.Parent ~= LastParent
								notif('AutoCyber', 'Dropped '.. tostring(Amount).. ' '.. v.Name, 8, 'info')
							else
								notif('AutoCyber', 'Generator not found', 20, 'alert')
							end
						end
					end
				end))

				repeat
					local drone = getDrone()
					if drone then
						local v = getItemDrop(drone)
						if v then
							task.wait(0.3)
							local highlight
							if Visual.Enabled then
								highlight = Instance.new('Highlight')
								highlight.FillColor = Color3.new(1, 1, 1)
								highlight.FillTransparency = 0
								highlight.OutlineTransparency = 0.5
								highlight.OutlineColor = Color3.new()
							end
							drone.PrimaryPart.AssemblyLinearVelocity = Vector3.zero
							drone.PrimaryPart.CFrame = CFrame.new(drone.PrimaryPart.CFrame.X, 10000, drone.PrimaryPart.CFrame.Z)
							local magnitude, lastmag = 0, 9e9
							local pos = v.Position
							repeat
								if drone and drone.Parent then
									pos = v.Position
									local multi = drone:GetAttribute('SpeedBoost')
									multi = multi == 0 or multi == '' or not multi and true or false
									drone.PrimaryPart.CanCollide = false
									drone.PrimaryPart.AssemblyAngularVelocity = Vector3.zero
									drone.PrimaryPart.AssemblyLinearVelocity = CFrame.lookAt(drone.PrimaryPart.Position * Vector3.new(1, 0, 1), pos * Vector3.new(1, 0, 1)).LookVector * 30
									magnitude = ((drone.PrimaryPart.Position * Vector3.new(1, 0, 1)) - (pos * Vector3.new(1, 0, 1))).Magnitude
									if (lastmag - magnitude) >= 25 then
										lastmag = magnitude
										notif('AutoCyber', `Drone is {math.floor(magnitude)} studs away from {v.Name}.`, 1, 'info')
									end
								else
									break
								end
								task.wait()
							until not v or v.Parent ~= workspace.ItemDrops or not AutoCyber.Enabled or magnitude <= 2
							if not AutoCyber.Enabled then
								if highlight and highlight.Parent then
									highlight:Destroy()
								end
								break
							end

							if magnitude <= 5 then
								local start = tick()
								if Visual.Enabled then
									notif('AutoCyber', 'Attempting to collect '.. v.Name, 4, 'info')
								end
								repeat
									if drone and drone.Parent then
										drone.PrimaryPart.AssemblyLinearVelocity = Vector3.zero
										drone.PrimaryPart.AssemblyAngularVelocity = Vector3.new(0, -30, 0)
										drone.PrimaryPart.CFrame = CFrame.new(pos - Vector3.new(0, drone.Hitbox.Size.Y, 0))
									end
									task.wait(0.02)
								until (tick() - start) >= 1.25
							elseif Visual.Enabled then
								notif('AutoCyber', `Too far away to collect {v.Name} ({magnitude} studs).`, 8, 'info')
							end
							if highlight and highlight.Parent then
								highlight:Destroy()
							end
						else
							drone.PrimaryPart.CFrame = CFrame.new(drone.PrimaryPart.CFrame.X, 10000, drone.PrimaryPart.CFrame.Z)
							drone.PrimaryPart.Velocity = Vector3.zero
							for _, v2 in Whitelist.ListEnabled do
								local gen = getGenerator(drone, v2)
								if gen then
									local magnitude = 0
									repeat
										if drone and drone.Parent then
											if getItemDrop(drone) then break end
											drone.PrimaryPart.CanCollide = false
											drone.PrimaryPart.AssemblyAngularVelocity = Vector3.zero
											drone.PrimaryPart.AssemblyLinearVelocity = CFrame.lookAt(drone.PrimaryPart.Position * Vector3.new(1, 0, 1), gen.Position * Vector3.new(1, 0, 1)).LookVector * 30
											magnitude = ((drone.PrimaryPart.Position * Vector3.new(1, 0, 1)) - (gen.Position * Vector3.new(1, 0, 1))).Magnitude
										else
											break
										end
										task.wait()
									until not v or v.Parent ~= workspace.ItemDrops or not AutoCyber.Enabled or magnitude <= 5
								end
							end
						end
					end
					task.wait()
				until not AutoCyber.Enabled
			else
				local drone = getDrone()
				if drone then
					drone.PrimaryPart.CFrame = CFrame.new(drone.PrimaryPart.CFrame.X, 500, drone.PrimaryPart.CFrame.Z)
				end
			end
		end,
		Tooltip = 'Steals enemy resources with your drone'
	})
	Mode = AutoCyber:CreateDropdown({
		Name = 'Drop mode',
		List = {'Player', 'Generator'},
		Default = 'Player',
		Tooltip = 'Where cyber items are dropped'
	})
	Whitelist = AutoCyber:CreateMultiDropdown({
		Name = 'Whitelist',
		List = {'iron', 'diamond', 'emerald'},
		Default = {'emerald', 'diamond'}
	})
	Visual = AutoCyber:CreateToggle({
		Name = 'Visualize',
		Default = true,
		Tooltip = 'Shows what the drone is targeting and how far it is'
	})
	Steal = AutoCyber:CreateToggle({
		Name = 'Steal split',
		Default = true,
		Tooltip = 'Steals other teams\' generator split'
	})
	Target = AutoCyber:CreateToggle({Name = 'Target check'})
	Limit = AutoCyber:CreateToggle({Name = 'Limit to item'})
end)

-- ===== Kits/AutoDavey.lua =====
run(function()
	local CannonHandController = bedwars.CannonHandController
	local CannonController = bedwars.CannonController
	local oldLaunchSelf = CannonHandController.launchSelf
	local oldStopAiming = CannonController.stopAiming
	local oldStartAiming = CannonController.startAiming
	local AutoDavey
	local AutoDaveyAutojump
	local AutoDaveyAutoLaunch
	local AutoDaveyAutoBreak
	local AutoDaveyPickaxeCheck
	local AutoDaveyAutoSwitch
	local LaunchDelay
	local BreakDelay
	local isLaunching = false
	local didAutoLaunch = false

	local function getCannonSlot()
		for i, v in pairs(store.inventory.hotbar) do
			if v.item then
				local t = tostring(v.item.itemType):lower()
				if t:find("cannon") then
					return i - 1
				end
			end
		end
		return nil
	end

	local function hasWoodPickaxeOnly()
		local bestTier = 0
		for _, slot in pairs(store.inventory.hotbar) do
			if slot.item then
				local t = tostring(slot.item.itemType):lower()
				if t == "wood_pickaxe" and bestTier < 1 then
					bestTier = 1
				elseif (t:find("pickaxe") or t:find("drill")) and t ~= "wood_pickaxe" then
					bestTier = 2
				end
			end
		end
		return bestTier == 1
	end

	local function getNearestCannon()
		if not entitylib.isAlive then return nil end
		local nearest
		local nearestDist = math.huge
		local okCannons, cannons = pcall(CannonController.getCannons)
		if not okCannons or type(cannons) ~= 'table' then
			okCannons, cannons = pcall(CannonController.getCannons, CannonController)
		end
		if not okCannons or type(cannons) ~= 'table' then return nil end
		for i, v in pairs(cannons) do
			pcall(function()
				local dist = (v.Position - entitylib.character.RootPart.Position).Magnitude
				if dist < nearestDist and dist < 30 then
					nearestDist = dist
					nearest = v
				end
			end)
		end
		return nearest
	end

	local function findCannonModel(pos)
		local closest = nil
		local closestDist = 8
		for _, obj in store.blocks do
			if obj and obj:IsA("BasePart") and obj.Name == "cannon" then
				local dist = (obj.Position - pos).Magnitude
				if dist < closestDist then
					closestDist = dist
					closest = obj
				end
			end
		end
		return closest
	end

	local function doBreakCannon(cannon)
		if not entitylib.isAlive then return end
		if not cannon or not cannon.Parent then return end
		local block, blockpos = getPlacedBlock(cannon.Position)
		if block and block.Name == 'cannon' and
		   (entitylib.character.RootPart.Position - block.Position).Magnitude < 30 then
			pcall(bedwars.breakBlock, block, false, nil, true)
		else
			local directBlock = findCannonModel(cannon.Position)
			if directBlock and directBlock.Parent then
				pcall(bedwars.breakBlock, directBlock, false, nil, true)
			end
		end
	end

	local function firstHitCannon(cannon)
		if not entitylib.isAlive then return end
		if not cannon or not cannon.Parent then return end
		if hasWoodPickaxeOnly() then
			doBreakCannon(cannon)
		end
	end

	local function breakCannon(cannon, shootfunc)
		if not entitylib.isAlive then
			isLaunching = false
			return shootfunc()
		end

		local cannonSlot = nil

		if AutoDaveyAutoSwitch.Enabled and not isHoldingPickaxe() then
			local pickaxeSlot = getPickaxeSlot()
			if not pickaxeSlot then
				notif("AutoDavey", "No pickaxe found in hotbar!", 3)
				if AutoDaveyAutojump.Enabled and entitylib.isAlive and entitylib.character.Humanoid then
					entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
				end
				isLaunching = false
				return shootfunc()
			end
			cannonSlot = getCannonSlot()
			if hotbarSwitch(pickaxeSlot) then
				task.wait(0.05)
			end
		end

		if AutoDaveyPickaxeCheck.Enabled and not isHoldingPickaxe() then
			notif("AutoDavey", "You need to HOLD a pickaxe to break cannons!", 3)
			if AutoDaveyAutojump.Enabled and entitylib.isAlive and entitylib.character.Humanoid then
				entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
			end
			isLaunching = false
			return shootfunc()
		end

		if BreakDelay.Value > 0 then
			task.wait(BreakDelay.Value)
		end

		local cannonRef = cannon
		if AutoDaveyAutojump.Enabled and entitylib.isAlive and entitylib.character.Humanoid then
			entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
		end
		shootfunc()
		isLaunching = false

		task.spawn(function()
			task.wait(0.05)
			doBreakCannon(cannonRef)
			task.wait(0.35)
			if cannonRef and cannonRef.Parent then
				doBreakCannon(cannonRef)
			end
			if AutoDaveyAutoSwitch.Enabled and cannonSlot then
				task.wait(0.05)
				hotbarSwitch(cannonSlot)
			end
		end)
	end

	AutoDavey = vape.Categories.Kits:CreateModule({
		Name = 'AutoDavey',
		Function = function(callback)
			if callback then
				CannonHandController.launchSelf = function(...)
					if isLaunching then
						isLaunching = false
						return oldLaunchSelf(...)
					end
					isLaunching = true
					if LaunchDelay.Value > 0 then
						task.wait(LaunchDelay.Value)
					end
					if AutoDaveyAutoBreak.Enabled then
						local cannon = getNearestCannon()
						if cannon then
							local args = {...}
							breakCannon(cannon, function()
								oldLaunchSelf(unpack(args))
							end)
							return
						else
							if AutoDaveyAutojump.Enabled and entitylib.isAlive and entitylib.character.Humanoid then
								entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
							end
							local res = oldLaunchSelf(...)
							isLaunching = false
							return res
						end
					else
						if AutoDaveyAutojump.Enabled and entitylib.isAlive and entitylib.character.Humanoid then
							entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
						end
						local res = oldLaunchSelf(...)
						isLaunching = false
						return res
					end
				end

				local aimedCannon, aimStart = nil, 0
				local function safeNearestCannon()
					local ok, cannon = pcall(getNearestCannon)
					return ok and cannon or nil
				end

				-- original runs first and untouched so aiming keeps working
				CannonController.startAiming = function(self, block, ...)
					didAutoLaunch = false
					isLaunching = false
					local results = table.pack(oldStartAiming(self, block, ...))
					aimedCannon = block or safeNearestCannon()
					aimStart = tick()
					return table.unpack(results, 1, results.n)
				end

				CannonController.stopAiming = function(self, ...)
					local cannon = aimedCannon or safeNearestCannon()
					local aimedFor = tick() - aimStart
					local results = table.pack(oldStopAiming(self, ...))
					aimedCannon = nil
					isLaunching = false
					-- only auto launch after a real aim, not a quick tap/cancel
					if AutoDaveyAutoLaunch.Enabled and not didAutoLaunch and cannon and aimedFor > 0.25 then
						didAutoLaunch = true
						if AutoDaveyAutoBreak.Enabled and AutoDaveyPickaxeCheck.Enabled and not isHoldingPickaxe() and not AutoDaveyAutoSwitch.Enabled then
							notif("AutoDavey", "Hold a pickaxe to auto-break!", 3)
						else
							task.spawn(function()
								pcall(CannonHandController.launchSelf, CannonHandController, cannon)
							end)
						end
					end
					return table.unpack(results, 1, results.n)
				end

				local firstHitDebounce = {}
				AutoDavey:Clean(workspace.DescendantAdded:Connect(function(obj)
					if not (obj:IsA("BasePart") and obj.Name == "cannon") then return end
					if firstHitDebounce[obj] then return end
					firstHitDebounce[obj] = true
					task.spawn(function()
						task.wait(0.5)
						if AutoDaveyAutoBreak.Enabled and hasWoodPickaxeOnly() then
							local dist = entitylib.isAlive
								and (entitylib.character.RootPart.Position - obj.Position).Magnitude
								or math.huge
							if dist < 20 and obj.Parent then
								firstHitCannon(obj)
							end
						end
						firstHitDebounce[obj] = nil
					end)
				end))
			else
				CannonHandController.launchSelf = oldLaunchSelf
				CannonController.stopAiming = oldStopAiming
				CannonController.startAiming = oldStartAiming
				isLaunching = false
				didAutoLaunch = false
			end
		end,
	})

	LaunchDelay = AutoDavey:CreateSlider({
		Name = 'Launch Delay',
		Min = 0,
		Max = 2,
		Default = 0,
		Decimal = 10,
		Suffix = 's',
	})
	BreakDelay = AutoDavey:CreateSlider({
		Name = 'Break Delay',
		Min = 0,
		Max = 2,
		Default = 0,
		Decimal = 10,
		Suffix = 's',
	})

	AutoDaveyAutojump = AutoDavey:CreateToggle({
		Name = 'Auto Jump',
		Default = true,
	})
	AutoDaveyAutoLaunch = AutoDavey:CreateToggle({
		Name = 'Auto Launch',
		Default = true,
		Tooltip = 'automatically lauches u after your done aiming'
	})
	AutoDaveyAutoBreak = AutoDavey:CreateToggle({
		Name = 'Auto Break',
		Default = true,
		Tooltip = 'auto breaks cannon when you lauch'
	})
	AutoDaveyPickaxeCheck = AutoDavey:CreateToggle({
		Name = 'Pickaxe Check',
		Default = true,
	})
	AutoDaveyAutoSwitch = AutoDavey:CreateToggle({
		Name = 'AutoSwitch Pickaxe',
		Default = false,
		Tooltip = 'switches to pickaxe when breaking thens switches back to cannon'
	})
end)

-- ===== Kits/AutoDeathAdder.lua =====
run(function()
	local AutoDeathAdder
	local AutoCollect
	local CollectRange
	local CollectDelay
	local CrystalESP
	local ESPBackground
	local ESPColor
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui
	local Reference = {}
	local crystalIcon
	local collectionActive = false

	local function getCrystalIcon()
		if not crystalIcon then
			crystalIcon = bedwars.getIcon({itemType = 'wild_flower'}, true)
		end
		return crystalIcon
	end

	local function Added(obj)
		if Reference[obj] then return end
		local part = not obj:IsA('Model') and obj or obj.PrimaryPart
		if not part then return end
		local billboard = Instance.new('BillboardGui')
		billboard.Parent = Folder
		billboard.Name = 'alchemy_crystal'
		billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
		billboard.Size = UDim2.fromOffset(36, 36)
		billboard.AlwaysOnTop = true
		billboard.ClipsDescendants = false
		billboard.Adornee = part
		local blur = addBlur(billboard)
		blur.Visible = ESPBackground.Enabled
		local image = Instance.new('ImageLabel')
		image.Size = UDim2.fromOffset(36, 36)
		image.Position = UDim2.fromScale(0.5, 0.5)
		image.AnchorPoint = Vector2.new(0.5, 0.5)
		image.BackgroundColor3 = Color3.fromHSV(ESPColor.Hue, ESPColor.Sat, ESPColor.Value)
		image.BackgroundTransparency = 1 - (ESPBackground.Enabled and ESPColor.Opacity or 0)
		image.BorderSizePixel = 0
		image.Image = getCrystalIcon()
		image.Parent = billboard
		local uicorner = Instance.new('UICorner')
		uicorner.CornerRadius = UDim.new(0, 4)
		uicorner.Parent = image
		Reference[obj] = billboard
	end

	local function Removed(obj)
		if Reference[obj] then
			Reference[obj]:Destroy()
			Reference[obj] = nil
		end
	end

	local function setupESP()
		for _, v in collectionService:GetTagged('alchemy_crystal') do
			Added(v)
		end
		AutoDeathAdder:Clean(collectionService:GetInstanceAddedSignal('alchemy_crystal'):Connect(function(v)
			if CrystalESP.Enabled then Added(v) end
		end))
		AutoDeathAdder:Clean(collectionService:GetInstanceRemovedSignal('alchemy_crystal'):Connect(function(v)
			Removed(v)
		end))
		local lastUpdate = 0
		AutoDeathAdder:Clean(runService.RenderStepped:Connect(function()
			if not CrystalESP.Enabled then return end
			local now = tick()
			if now - lastUpdate < 0.2 then return end
			lastUpdate = now
			for obj in pairs(Reference) do
				if not obj or not obj.Parent then
					Removed(obj)
				end
			end
		end))
	end

	local function startAutoCollect()
		if collectionActive then return end
		collectionActive = true
		task.spawn(function()
			while AutoDeathAdder.Enabled and AutoCollect.Enabled and collectionActive do
				if not entitylib.isAlive then
					task.wait(0.5)
					continue
				end
				local localPosition = entitylib.character.RootPart.Position
				local range = CollectRange.Value
				for _, obj in collectionService:GetTagged('alchemy_crystal') do
					if not AutoDeathAdder.Enabled or not AutoCollect.Enabled or not collectionActive then break end
					local part = not obj:IsA('Model') and obj or obj.PrimaryPart
					if part and (localPosition - part.Position).Magnitude <= range then
						local id = obj:GetAttribute('Id') or obj:GetAttribute('id')
							or obj:GetAttribute('CollectableId') or tonumber(obj.Name:match('%d+'))
						if id then
							pcall(function()
								bedwars.GameAnimationUtil:playAnimation(lplr.Character, bedwars.AnimationType.PUNCH)
							end)
							pcall(function()
								bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.FP_USE_ITEM)
							end)
							pcall(function()
								collectRemote:FireServer({ id = id, collectableName = obj.Name })
							end)
							if CollectDelay.Value > 0 then
								task.wait(CollectDelay.Value)
							end
						end
					end
				end
				task.wait(0.1)
			end
			collectionActive = false
		end)
	end

	local function stopAutoCollect()
		collectionActive = false
	end

	AutoDeathAdder = vape.Categories.Kits:CreateModule({
		Name = 'AutoDeathAdder',
		Function = function(callback)
			if callback then
				if CrystalESP.Enabled then setupESP() end
				if AutoCollect.Enabled then startAutoCollect() end
			else
				stopAutoCollect()
				Folder:ClearAllChildren()
				table.clear(Reference)
			end
		end,
		Tooltip = 'grabs crystals + esp for deathadder'
	})

	AutoCollect = AutoDeathAdder:CreateToggle({
		Name = 'Auto Collect',
		Tooltip = 'auto grabs the crystals no cap',
		Function = function(callback)
			if CollectRange and CollectRange.Object then CollectRange.Object.Visible = callback end
			if CollectDelay and CollectDelay.Object then CollectDelay.Object.Visible = callback end
			if AutoDeathAdder.Enabled then
				if callback then startAutoCollect() else stopAutoCollect() end
			end
		end
	})
	CollectRange = AutoDeathAdder:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 40,
		Default = 15,
		Visible = false
	})
	CollectDelay = AutoDeathAdder:CreateSlider({
		Name = 'Delay',
		Min = 0,
		Max = 1,
		Default = 0.1,
		Decimal = 100,
		Suffix = 's',
		Visible = false
	})

	CrystalESP = AutoDeathAdder:CreateToggle({
		Name = 'Crystal ESP',
		Tooltip = 'shows u where the crystals at',
		Function = function(callback)
			if ESPBackground and ESPBackground.Object then ESPBackground.Object.Visible = callback end
			if ESPColor and ESPColor.Object then ESPColor.Object.Visible = (callback and ESPBackground and ESPBackground.Enabled) end
			if AutoDeathAdder.Enabled then
				if callback then
					setupESP()
				else
					Folder:ClearAllChildren()
					table.clear(Reference)
				end
			end
		end
	})
	ESPBackground = AutoDeathAdder:CreateToggle({
		Name = 'Background',
		Default = true,
		Function = function(callback)
			if ESPColor and ESPColor.Object then ESPColor.Object.Visible = (callback and CrystalESP and CrystalESP.Enabled) end
			for _, v in Reference do
				if v and v:FindFirstChild('ImageLabel') then
					local blur = v:FindFirstChild('Blur')
					if blur then blur.Visible = callback end
					v.ImageLabel.BackgroundTransparency = 1 - (callback and ESPColor.Opacity or 0)
				end
			end
		end
	})
	ESPColor = AutoDeathAdder:CreateColorSlider({
		Name = 'Background Color',
		DefaultValue = 0,
		DefaultOpacity = 0.5,
		Darker = true,
		Function = function(hue, sat, val, opacity)
			for _, v in Reference do
				if v and v:FindFirstChild('ImageLabel') then
					v.ImageLabel.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
					v.ImageLabel.BackgroundTransparency = 1 - opacity
				end
			end
		end
	})

	task.defer(function()
		local collectOn = AutoCollect and AutoCollect.Enabled
		if CollectRange and CollectRange.Object then CollectRange.Object.Visible = collectOn end
		if CollectDelay and CollectDelay.Object then CollectDelay.Object.Visible = collectOn end
		local espOn = CrystalESP and CrystalESP.Enabled
		if ESPBackground and ESPBackground.Object then ESPBackground.Object.Visible = espOn end
		if ESPColor and ESPColor.Object then ESPColor.Object.Visible = (espOn and ESPBackground.Enabled) end
	end)
end)

