-- ===== Kits/AutoGinger.lua =====
run(function()
    local AutoGinger
    local LimitToItem
    local BreakDelay
    local BreakDelaySlider
    local AutoSwitch
    local SwitchMode
    
    local Folder = Instance.new('Folder')
    Folder.Parent = vape.gui
    local lastBreakTime = 0
    local lastPlaceTime = 0
    local placeCheckConnection
    local justPlacedGumdrop = false
    local lastPlacedPosition = nil
    
    _G.gingerLock = _G.gingerLock or false
    
    local function getGumdropSlot()
        for i, v in store.inventory.hotbar do
            if v.item and v.item.itemType == "gumdrop_bounce_pad" then
                return i - 1
            end
        end
        return nil
    end
    
    local function getPredictedPosition()
        if not (lplr.Character and lplr.Character.PrimaryPart) then return nil end
        local root = lplr.Character.PrimaryPart
        local velocity = root.AssemblyLinearVelocity
        local horizontalVelocity = Vector3.new(velocity.X, 0, velocity.Z)
        local speed = horizontalVelocity.Magnitude
        if speed < 1 then return root.Position end
        local predictionTime = math.clamp(speed / 40, 0.15, 0.35)
        return root.Position + (horizontalVelocity * predictionTime)
    end
    
    local function forceBreak(block)
        if not block then return end
        lastBreakTime = tick()
        justPlacedGumdrop = false
        task.spawn(function()
            for i = 1, 6 do
                if not block or not block.Parent then return end
                pcall(bedwars.breakBlock, block, false, nil, true)
                task.wait(0.05)
            end
        end)
    end
    
    local function tryPlaceGumdrop()
        if not AutoSwitch.Enabled or _G.gingerLock then return end
        if not (lplr.Character and lplr.Character.PrimaryPart) then return end
        
        local inFirstPerson = isFirstPerson()
        if SwitchMode.Value == 'First Person' and not inFirstPerson then return end
        if SwitchMode.Value == 'Third Person' and inFirstPerson then return end
        
        local velocity = lplr.Character.PrimaryPart.AssemblyLinearVelocity.Y
        if velocity >= -5 then return end
        
        local gumdropSlot = getGumdropSlot()
        if not gumdropSlot then return end
        
        local root = lplr.Character.PrimaryPart
        local targetPos = getPredictedPosition() or root.Position
        local checkPos = targetPos - Vector3.new(0, 3, 0)
        local groundBlockPos = nil
        
        for i = 1, 16 do
            local testPos = checkPos - Vector3.new(0, 3 * (i - 1), 0)
            local block, blockpos = getPlacedBlock(roundPos(testPos))
            if block then
                groundBlockPos = blockpos * 3
                break
            end
        end
        
        if not groundBlockPos then return end
        
        local distanceToGround = root.Position.Y - groundBlockPos.Y
        if distanceToGround < 9 or distanceToGround > 18 then return end
        
        local placePos = groundBlockPos + Vector3.new(0, 3, 0)
        if lastPlacedPosition and (lastPlacedPosition - placePos).Magnitude < 1 then return end
        if getPlacedBlock(placePos) then return end
        
        _G.gingerLock = true
        
        if hotbarSwitch(gumdropSlot) then
            task.wait(0.03)
            local success = pcall(function()
                bedwars.placeBlock(placePos, "gumdrop_bounce_pad", false)
            end)
            
            if success then
                lastPlaceTime = tick()
                justPlacedGumdrop = true
                lastPlacedPosition = placePos
                
                task.wait(0.03)
                local pickaxeSlot = getPickaxeSlot()
                if pickaxeSlot then
                    hotbarSwitch(pickaxeSlot)
                    task.wait(0.08)
                    local placedBlock = getPlacedBlock(placePos)
                    if placedBlock and placedBlock.Name == "gumdrop_bounce_pad" then
                        forceBreak(placedBlock)
                    end
                end
            end
        end
        
        _G.gingerLock = false
    end
    
    AutoGinger = vape.Categories.Kits:CreateModule({
        Name = 'AutoGinger',
        Function = function(callback)
            if callback then
                local old = bedwars.LaunchPadController.attemptLaunch
                bedwars.LaunchPadController.attemptLaunch = function(...)
                    local res = {old(...)}
                    local self, block = ...
                    
                    if block:GetAttribute('PlacedByUserId') == lplr.UserId and
                       (block.Position - entitylib.character.RootPart.Position).Magnitude < 30 then

                        if LimitToItem.Enabled and not AutoSwitch.Enabled and not isHoldingPickaxe() then
                            return unpack(res)
                        end

                        local inFP = isFirstPerson()
                        local cameraAllowed = not AutoSwitch.Enabled or ((SwitchMode.Value ~= 'First Person' or inFP) and (SwitchMode.Value ~= 'Third Person' or not inFP))

                        if isHoldingPickaxe() then
                            local shouldBreak = true
                            if not AutoSwitch.Enabled and BreakDelay.Enabled and not justPlacedGumdrop then
                                if (tick() - lastBreakTime) < BreakDelaySlider.Value then
                                    shouldBreak = false
                                end
                            end
                            if shouldBreak then
                                forceBreak(block)
                            end
                        elseif AutoSwitch.Enabled and cameraAllowed and not _G.gingerLock then
                            local pickaxeSlot = getPickaxeSlot()
                            if pickaxeSlot then
                                _G.gingerLock = true
                                task.spawn(function()
                                    if hotbarSwitch(pickaxeSlot) then
                                        task.wait(0.03)
                                        forceBreak(block)
                                    end
                                    task.wait(0.2)
                                    _G.gingerLock = false
                                end)
                            end
                        elseif not LimitToItem.Enabled then
                            forceBreak(block)
                        end
                    end
                    
                    return unpack(res)
                end
                
				if AutoSwitch.Enabled then
                    if placeCheckConnection then
                        placeCheckConnection:Disconnect()
                        placeCheckConnection = nil
                    end
                    placeCheckConnection = runService.Heartbeat:Connect(function()
                        if not _G.gingerLock and entitylib.isAlive and tick() - lastPlaceTime > 0.15 then
                            tryPlaceGumdrop()
                        end
                    end)
                end
                
                AutoGinger:Clean(function()
                    bedwars.LaunchPadController.attemptLaunch = old
                    if placeCheckConnection then
                        placeCheckConnection:Disconnect()
                        placeCheckConnection = nil
                    end
                end)
            else
                lastBreakTime = 0
                lastPlaceTime = 0
                justPlacedGumdrop = false
                lastPlacedPosition = nil
                _G.gingerLock = false
                if placeCheckConnection then
                    placeCheckConnection:Disconnect()
                    placeCheckConnection = nil
                end
            end
        end,
        Tooltip = 'really just advanced autokit'
    })

    LimitToItem = AutoGinger:CreateToggle({
        Name = 'Limit to Pickaxe',
        Default = true,
    })
    
    BreakDelay = AutoGinger:CreateToggle({
        Name = 'Break Delay',
        Default = false,
        Function = function(callback)
            if BreakDelaySlider and BreakDelaySlider.Object then
                BreakDelaySlider.Object.Visible = callback and not AutoSwitch.Enabled
            end
        end,
    })
    
    BreakDelaySlider = AutoGinger:CreateSlider({
        Name = 'Delay',
        Min = 0,
        Max = 2,
        Default = 0.5,
        Decimal = 10,
        Suffix = 's',
        Visible = false,
    })
    
	AutoSwitch = AutoGinger:CreateToggle({
        Name = 'Auto-Switch',
        Default = false,
        Function = function(callback)
            if SwitchMode and SwitchMode.Object then SwitchMode.Object.Visible = callback end
            if BreakDelay and BreakDelay.Object then BreakDelay.Object.Visible = not callback end
            if BreakDelaySlider and BreakDelaySlider.Object then
                BreakDelaySlider.Object.Visible = (not callback) and BreakDelay.Enabled
            end
            if LimitToItem and LimitToItem.Object then LimitToItem.Object.Visible = not callback end

            if placeCheckConnection then
                placeCheckConnection:Disconnect()
                placeCheckConnection = nil
            end

            if callback and AutoGinger.Enabled then
                placeCheckConnection = runService.Heartbeat:Connect(function()
                    if not _G.gingerLock and entitylib.isAlive and tick() - lastPlaceTime > 0.15 then
                        tryPlaceGumdrop()
                    end
                end)
            end
        end,
    })
    
    SwitchMode = AutoGinger:CreateDropdown({
        Name = 'Camera Mode',
        List = {'Both', 'First Person', 'Third Person'},
        Default = 'Both',
        Visible = false,
    })
end)

-- ===== Kits/AutoGingerbreadMan.lua =====
run(function()
	local function CanPlace() return not bedwars.BlockPlacementController.disabled and not isCasting() end
	local Entity = entitylib
	local GetHotbar = getHotbar
	local GetItem = getItem
	local GetPlacedBlock = getPlacedBlock
	local HotbarSwitch = hotbarSwitch
	local LocalPlayer = lplr
	local RoundPosition = roundPos
	local RunService = runService
	local Store = store
	local SwitchItem = switchItem
	local AutoGingerbread
	local Range
	local Delay
	local Break
	local Place
	local PlaceDelay
	local Jump
	local Switch
	local OwnOnly
	local SuccessfulOnly

	local Old
	local NextPlace: number = 0

	AutoGingerbread = kits:CreateModule({
		Name = "AutoGingerbreadMan",
		Function = function(Callback: boolean)
			if Callback then
				NextPlace = 0
				AutoGingerbread:Clean(RunService.Heartbeat:Connect(function()
					if Place.Enabled and Entity.isAlive and Store.equippedKit == "gingerbread_man" and tick() >= NextPlace and CanPlace() and GetItem("gumdrop_bounce_pad") then
						local Position: Vector3 = RoundPosition(Entity.character.RootPart.Position - Vector3.new(0, Entity.character.HipHeight + 1.5, 0))
						if not GetPlacedBlock(Position) then
							NextPlace = tick() + math.max(PlaceDelay.Value, 1 / bedwars.SharedConstants.BLOCK_PLACE_CPS)
							bedwars.placeBlock(Position, "gumdrop_bounce_pad")
						end
					end
				end))

				Old = bedwars.LaunchPadController.attemptLaunch
				bedwars.LaunchPadController.attemptLaunch = function(self, Block, ...)
					local LastLaunch = self and self.lastLaunch or 0
					local Call = Old(self, Block, ...)

					if not SuccessfulOnly.Enabled or self and self.lastLaunch and self.lastLaunch ~= LastLaunch then
						if Break.Enabled and Entity.isAlive and Store.equippedKit == "gingerbread_man" and Block and Block:IsA("BasePart") and (not OwnOnly.Enabled or Block:GetAttribute("PlacedByUserId") == LocalPlayer.UserId) and (Block.Position - Entity.character.RootPart.Position).Magnitude <= Range.Value then
							task.delay(Delay.Value, function()
								if AutoGingerbread.Enabled and Block.Parent then
									if Switch.Enabled then
										local ItemMeta = bedwars.ItemMeta[Block.Name]
										local BreakType = ItemMeta and ItemMeta.block and ItemMeta.block.breakType
										local Tool = BreakType and Store.tools[BreakType] or Store.tools.sword
										local Slot = Tool and GetHotbar(Tool.tool)
										if Slot then
											HotbarSwitch(Slot)
										elseif Tool then
											SwitchItem(Tool.tool)
										end
									end
									bedwars.breakBlock(Block, false, nil, nil, Switch.Enabled)
								end
							end)
						end

						if Jump.Enabled and Entity.isAlive then
							Entity.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
						end
					end
					return Call
				end
			else
				bedwars.LaunchPadController.attemptLaunch = Old
			end
		end,
		Tooltip = 'Handles Gingerbread Man launch pads for you'
	})

	Place = AutoGingerbread:CreateGroup({
		Name = "Place pads",
		Tooltip = 'Keeps a bounce pad under you',
		Default = true
	})
	PlaceDelay = Place:CreateSlider({
		Name = "Place delay",
		Min = 0,
		Max = 1,
		Default = 0,
		Decimal = 100,
		Darker = true,
		Suffix = function(Val: number)
			return Val == 1 and "sec" or "secs"
		end
	})
	Break = AutoGingerbread:CreateGroup({
		Name = "Break launch pad",
		Function = function(Callback: boolean)
			if Range then
			end
		end,
		Default = true
	})
	Jump = AutoGingerbread:CreateToggle({Name = "Jump after launch"})

	Switch = Break:CreateToggle({
		Name = "Legit switch",
		Darker = true
	})
	OwnOnly = Break:CreateToggle({
		Name = "Own pads only",
		Default = true,
		Darker = true
	})
	SuccessfulOnly = AutoGingerbread:CreateToggle({
		Name = "Successful launch only",
		Default = true
	})
	Range = Break:CreateSlider({
		Name = "Range",
		Min = 1,
		Max = 30,
		Default = 30,
		Darker = true,
		Suffix = function(Val: number)
			return Val <= 1 and "stud" or "studs"
		end
	})
	Delay = Break:CreateSlider({
		Name = "Break delay",
		Min = 0,
		Max = 1,
		Default = 0.05,
		Decimal = 100,
		Darker = true,
		Suffix = function(Val: number)
			return Val == 1 and "sec" or "secs"
		end
	})
end)

-- ===== Kits/AutoGompy.lua =====
run(function()
	local AutoGompy
	local AutoCollect
	local Range
	local Delay
	local LimitToVacuum
	local Debug
	local collectRemote

	local function getRemote()
		if collectRemote then return collectRemote end

		local ok, remote = pcall(function() return bedwars.Handler:Get('CollectCollectableEntity') end)
		collectRemote = ok and remote or nil
		return collectRemote
	end

	local function collect(id)
		local remote = getRemote()
		if remote then
			return pcall(function() remote:Fire('SendToServer', {id = id}) end)
		end

		local ok, direct = pcall(function() return bedwars.Client:Get('CollectCollectableEntity') end)
		if ok and direct and type(direct.SendToServer) == 'function' then
			return (pcall(direct.SendToServer, direct, {id = id}))
		end
		return false
	end

	local function getGhostId(obj)
		return obj:GetAttribute('Id') or obj:GetAttribute('id') or obj:GetAttribute('CollectableId')
			or tonumber(obj.Name:match('%d+'))
	end

	local function holdingVacuum()
		local hand = store.hand
		return hand and hand.itemType ~= nil and hand.itemType:find('vacuum') ~= nil
	end

	local function collectPass()
		if not entitylib.isAlive then return end
		if LimitToVacuum.Enabled and not holdingVacuum() then return end

		local localPosition = entitylib.character.RootPart.Position
		for _, obj in collectionService:GetTagged('ghost') do
			if not AutoGompy.Enabled or not AutoCollect.Enabled then break end

			local part = not obj:IsA('Model') and obj or obj.PrimaryPart
			if part and (localPosition - part.Position).Magnitude <= Range.Value then
				local id = getGhostId(obj)
				if id then
					collect(id)
					if Delay.Value > 0 then
						task.wait(Delay.Value)
					end
				end
			end
		end
	end

	AutoGompy = kits:CreateModule({
		Name = 'AutoGompy',
		Function = function(callback)
			if not callback then return end

			AutoGompy:Clean(task.spawn(function()
				repeat
					local ok, err = pcall(collectPass)
					if not ok and Debug.Enabled then
						notif('AutoGompy', tostring(err), 6, 'warning')
					end
					task.wait(0.1)
				until not AutoGompy.Enabled or not AutoCollect.Enabled
			end))
		end,
		Tooltip = 'Vacuums up nearby ghosts'
	})

	AutoCollect = AutoGompy:CreateToggle({
		Name = 'Auto Collect',
		Default = true,
		Tooltip = 'Vacuums up nearby ghosts'
	})
	Range = AutoGompy:CreateSlider({
		Name = 'Range',
		Tooltip = 'How far it vacuums ghosts from',
		Min = 5,
		Max = 40,
		Default = 30
	})
	Delay = AutoGompy:CreateSlider({
		Name = 'Delay',
		Tooltip = 'Wait time between vacuums',
		Min = 0,
		Max = 1,
		Default = 0.1,
		Decimal = 100,
		Suffix = 's'
	})
	LimitToVacuum = AutoGompy:CreateToggle({
		Name = 'Limit to Vacuum',
		Tooltip = 'Only works while holding the item it uses'
	})
	Debug = AutoGompy:CreateToggle({
		Name = 'Debug',
		Tooltip = 'Logs what it does'
	})
end)

-- ===== Kits/AutoGrimReaper.lua =====
run(function()
	local AutoGrimReaper
	local Targets
	local Range
	local Delay
	local collectionActive = false

	local function startLoop()
		if collectionActive then return end
		collectionActive = true
		task.spawn(function()
			repeat task.wait() until Targets and Range and Delay
			while AutoGrimReaper.Enabled and collectionActive do
				if not entitylib.isAlive then
					task.wait(0.5)
					continue
				end
				local controller = bedwars.GrimReaperController
				if not controller or not controller.soulsByPosition then
					task.wait(0.2)
					continue
				end
				local localPosition = entitylib.character.RootPart.Position
				local range = Range.Value
				local char = lplr.Character
				local health = char and char:GetAttribute('Health')
				local maxHealth = char and char:GetAttribute('MaxHealth')
				local lowHealth = health and maxHealth and health <= (maxHealth / 4) and not char:GetAttribute('GrimReaperChannel')
				if lowHealth then
					for _, v in controller.soulsByPosition do
						if not AutoGrimReaper.Enabled or not collectionActive then break end
						if typeof(v) == 'Instance' then
							local part = not v:IsA('Model') and v or v.PrimaryPart
							if part and (localPosition - part.Position).Magnitude <= range then
								local secret = v:GetAttribute('GrimReaperSoulSecret')
								if secret then
									pcall(function()
										bedwars.Client:Get(remotes.ConsumeSoul):CallServer({ secret = secret })
									end)
									if Delay.Value > 0 then
										task.wait(Delay.Value)
									end
								end
							end
						end
					end
				end
				task.wait(0.1)
			end
			collectionActive = false
		end)
	end

	AutoGrimReaper = vape.Categories.Kits:CreateModule({
		Name = 'AutoGrimReaper',
		Function = function(callback)
			if callback then
				startLoop()
			else
				collectionActive = false
			end
		end,
		Tooltip = 'auto eats souls when ur hp is low'
	})

	Targets = AutoGrimReaper:CreateTargets({
		Players = true,
		NPCs = true,
		Walls = true
	})
	Range = AutoGrimReaper:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 150,
		Default = 120
	})
	Delay = AutoGrimReaper:CreateSlider({
		Name = 'Delay',
		Min = 0,
		Max = 1,
		Default = 0.1,
		Decimal = 100,
		Suffix = 's'
	})
end)

