	})
end)

-- ===== Kits/AutoKaida.lua =====
run(function()

	local util = vape.Libraries.bedwarsutil
	local AutoKaida
	local Targets
	local Sort
	local SwingRange
	local AttackRange
	local Spell
	local SpellMode
	local SpellCharge
	local SpellRange
	local Swing
	local Limit
	local Mouse
	local GUI

	local casting = 0

	local function getClaw()
		if Limit.Enabled then
			return store.hand.tool and bedwars.IsItemClaw(store.hand.tool.Name) and store.hand or nil
		end

		for _, item in store.inventory.inventory.items do
			if bedwars.IsItemClaw(item.itemType) then
				return item
			end
		end
		return nil
	end

	local function getSpellTarget()
		local localPosition = entitylib.character.RootPart.Position
		if SpellMode.Value == 'Camera' then
			local point = bedwars.AbilityIndicatorUtil:calculateBlockTargetPoint(gameCamera.CFrame.Position, gameCamera.CFrame.LookVector, 300, nil, {allowArenaBarrierTarget = false})
			return point and (point - localPosition).Magnitude <= SpellRange.Value and point or nil
		end

		local ent = entitylib.EntityPosition({
			Range = SpellRange.Value,
			Part = 'RootPart',
			Players = Targets.Players.Enabled,
			Priority = Targets.Priority and Targets.Priority.Value,
			NPCs = Targets.NPCs.Enabled,
			Sort = sortmethods[Sort.Value]
		})
		if not ent then return nil end

		local point = bedwars.AbilityIndicatorUtil:calculateBlockTargetPoint(ent.RootPart.Position + Vector3.new(0, 3, 0), Vector3.new(0, -1, 0), 30, nil, {allowArenaBarrierTarget = false})
		return point and (point - localPosition).Magnitude <= SpellRange.Value and point or ent.RootPart.Position
	end

	local function castSpell()
		local target = getSpellTarget()
		if not target or not bedwars.AbilityController:canUseAbility('summoner_start_charging', {disableBlockedAbilityAlert = true}) then return end

		casting = tick() + 6
		bedwars.AbilityController:useAbility('summoner_start_charging', nil, {targetPosition = target})

		local level = bedwars.SummonerUtil.summoner_getPlayerSpellLevel(lplr) or 1
		local charge = math.max(bedwars.SummonerUtil.summoner_getTotalCastTimeRequired(level) * (SpellCharge.Value / 100), bedwars.SummonerKitBalance.SPELL_MINIMUM_CAST_TIME)
		local deadline = tick() + charge

		repeat task.wait() until tick() >= deadline or not AutoKaida.Enabled or not entitylib.isAlive or not bedwars.SummonerKitController:isPlayerCastingSpell(lplr)

		if AutoKaida.Enabled and entitylib.isAlive and bedwars.SummonerKitController:isPlayerCastingSpell(lplr) then
			bedwars.AbilityController:useAbility('summoner_finish_charging')
		end
		casting = 0
	end

	AutoKaida = kits:CreateModule({
		Name = 'AutoKaida',
		Function = function(callback)
			if callback then
				repeat
					if entitylib.isAlive and store.equippedKit == 'summoner' then
						if Spell.Enabled and tick() > casting and not bedwars.SummonerKitController:isPlayerCastingSpell(lplr) then
							task.spawn(castSpell)
						end

						local claw = (not Mouse.Enabled or inputService:IsMouseButtonPressed(0)) and (not GUI.Enabled or not bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN)) and getClaw()
						local ent = claw and (workspace:GetServerTimeNow() - bedwars.SummonerClawHandController.lastAttackTime) > bedwars.SummonerKitBalance.CLAW_COOLDOWN and (Swing.Enabled or not bedwars.SummonerKitController:isPlayerCastingSpell(lplr)) and entitylib.EntityPosition({
							Range = SwingRange.Value,
							Wallcheck = Targets.Walls.Enabled or nil,
							Part = 'RootPart',
							Players = Targets.Players.Enabled,
							Priority = Targets.Priority and Targets.Priority.Value,
							NPCs = Targets.NPCs.Enabled,
							Sort = sortmethods[Sort.Value]
						})

						if ent then
							local selfpos = entitylib.character.RootPart.Position
							local delta = ent.RootPart.Position - selfpos
							local dir = CFrame.lookAt(selfpos, ent.RootPart.Position).LookVector
							targetinfo.Targets[ent] = tick() + 1
							switchItem(claw.tool, 0)
							if delta.Magnitude <= AttackRange.Value then
								bedwars.Handler:Get('SummonerClawAttackRequest'):Fire(nil, {
									position = selfpos + dir * math.max(delta.Magnitude - 16.399, 0),
									direction = dir,
									clientTime = workspace:GetServerTimeNow()
								})
							end
							bedwars.SummonerClawHandController.lastAttackTime = workspace:GetServerTimeNow()
							bedwars.SummonerClawController:clawAttack(lplr, selfpos, dir, claw.tool.Name)
						end
					end

					task.wait(0.1)
				until not AutoKaida.Enabled
			else
				casting = 0
			end
		end,
		Tooltip = 'Attacks with Kaida\'s claw and casts her summon circle'
	})
	Targets = AutoKaida:CreateTargets({Players = true})
	local methods = {'Distance', 'Damage'}
	for _, i in sortlist do
		if not table.find(methods, i) then
			table.insert(methods, i)
		end
	end
	Sort = AutoKaida:CreateDropdown({
		Name = 'Target mode',
		List = methods,
		Tooltip = TARGET_MODE_TOOLTIP
	})
	SwingRange = AutoKaida:CreateSlider({
		Name = 'Swing Range',
		Min = 1,
		Max = 32,
		Default = 32,
		Suffix = util.Studs
	})
	AttackRange = AutoKaida:CreateSlider({
		Name = 'Attack Range',
		Min = 1,
		Max = 32,
		Default = 32,
		Suffix = util.Studs
	})
	Spell = AutoKaida:CreateGroup({
		Name = 'Auto summon',
		Function = function(callback)
			if SpellMode then
			end
		end,
		Tooltip = 'Casts the summon circle automatically'
	})
	SpellMode = Spell:CreateDropdown({
		Name = 'Summon at',
		List = {'Target', 'Camera'},
		Darker = true,
		Tooltip = 'Target - on the closest enemy\nCamera - where you look'
	})
	SpellCharge = Spell:CreateSlider({
		Name = 'Charge',
		Min = 1,
		Max = 100,
		Default = 100,
		Darker = true,
		Suffix = '%',
		Tooltip = 'How far to charge before firing'
	})
	SpellRange = Spell:CreateSlider({
		Name = 'Summon Range',
		Min = 1,
		Max = 39,
		Default = 39,
		Darker = true,
		Suffix = util.Studs,
		Tooltip = 'How far away it can summon'
	})
	Swing = AutoKaida:CreateToggle({
		Name = 'Swing during ability',
		Default = true,
		Tooltip = 'Keeps attacking while the ability charges'
	})
	Limit = AutoKaida:CreateToggle({
		Name = 'Limit to items',
		Tooltip = 'Only works while holding the item it uses'
	})
	Mouse = AutoKaida:CreateToggle({Name = 'Require mouse down'})
	GUI = AutoKaida:CreateToggle({Name = 'GUI check'})
end)

-- ===== Kits/AutoKaliyah.lua =====
run(function()

	local util = vape.Libraries.bedwarsutil
	local AutoKaliyah
	local Range
	local Stacks
	local Delay
	local NoSlow

	local Legit = getFunctionRange(bedwars.DragonSlayerController.hasEligiblePunchTarget) or 14.4
	local modifier, old
	local noSlowUntil = 0

	local function punch()
		if NoSlow.Enabled then
			if not old then
				modifier = bedwars.SprintController:getMovementStatusModifier()
				old = modifier.addModifier
				modifier.addModifier = function(self, tab)
					if NoSlow.Enabled and tick() < noSlowUntil and tab and tab.moveSpeedMultiplier == 0 then
						tab.moveSpeedMultiplier = 1
					end
					return old(self, tab)
				end

				AutoKaliyah:Clean(function()
					modifier.addModifier = old
					modifier, old = nil, nil
					noSlowUntil = 0
				end)
			end
			noSlowUntil = math.max(noSlowUntil, tick() + Delay.Value + 0.1)
		end

		task.wait(Delay.Value)
		bedwars.AbilityController:useAbility('dragon_slayer_punch')
	end

	AutoKaliyah = kits:CreateModule({
		Name = 'AutoKaliyah',
		Function = function(call)
			if call then
				repeat
					if entitylib.isAlive and store.equippedKit == 'dragon_slayer' and bedwars.AbilityController:canUseAbility('dragon_slayer_punch', {disableBlockedAbilityAlert = true}) then
						local localPosition = entitylib.character.RootPart.Position
						for target, v in bedwars.DragonSlayerController.dragonEmblems do
							if v.stackCount >= Stacks.Value and target.PrimaryPart and (target.PrimaryPart.Position - localPosition).Magnitude <= Range.Value then
								punch()
								break
							end
						end
					end
					task.wait(0.1)
				until not AutoKaliyah.Enabled
			end
		end,
		Tooltip = 'Uses Kaliyah\'s punch ability'
	})
	NoSlow = AutoKaliyah:CreateToggle({
		Name = 'No Slow',
		Default = true,
		Tooltip = 'Stops the punch ability slowing you'
	})
	Range = AutoKaliyah:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 20,
		Default = 18,
		Suffix = util.Studs
	})
	AutoKaliyah:CreateButton({
		Name = 'Sync to legit range',
		Function = function()
			Range:SetValue(Legit)
		end
	})
	Stacks = AutoKaliyah:CreateSlider({
		Name = 'Stacks',
		Min = 1,
		Max = 3,
		Default = 1,
		Suffix = function(val)
			return val <= 1 and 'stack' or 'stacks'
		end,
		Tooltip = 'How many emblems a target needs before the punch'
	})
	Delay = AutoKaliyah:CreateSlider({
		Name = 'Delay',
		Min = 0,
		Max = 1,
		Default = 0.1,
		Decimal = 100
	})
end)

-- ===== Kits/AutoKit.lua =====
run(function()
	local Active
	local Legit = {Enabled = false}

	local function IsRunning()
		return Active ~= nil and Active.Enabled
	end

	local function kitCollection(id, func, range, specific)
		local objs = type(id) == 'table' and id or collection(id, Active)
		repeat
			if entitylib.isAlive then
				local localPosition = entitylib.character.RootPart.Position
				for _, v in objs do
					if not IsRunning() then break end
					local part = not v:IsA('Model') and v or (v.PrimaryPart or v:FindFirstChildWhichIsA('BasePart', true))
					if part and (part.Position - localPosition).Magnitude <= (not Legit.Enabled and specific and math.huge or range) then
						func(v)
					end
				end
			end
			task.wait(0.1)
		until not IsRunning()
	end

	local AutoKitFunctions = {
		battery = function()
			repeat
				if entitylib.isAlive then
					local localPosition = entitylib.character.RootPart.Position
					for i, v in bedwars.BatteryEffectsController.liveBatteries do
						if (v.position - localPosition).Magnitude <= 10 then
							local BatteryInfo = bedwars.BatteryEffectsController:getBatteryInfo(i)
							if not BatteryInfo or BatteryInfo.activateTime >= workspace:GetServerTimeNow() or BatteryInfo.consumeTime + 0.1 >= workspace:GetServerTimeNow() then continue end
							BatteryInfo.consumeTime = workspace:GetServerTimeNow()
							bedwars.Handler:Get('ConsumeBattery'):Fire('SendToServer', {batteryId = i})
						end
					end
				end
				task.wait(0.1)
			until not IsRunning()
		end,
		beekeeper = function()
			kitCollection('bee', function(v)
				bedwars.Handler:Get('PickUpBee'):Fire('SendToServer', {beeId = v:GetAttribute('BeeId')})
			end, 18, false)
		end,
		bigman = function()
			kitCollection('treeOrb', function(v)
				if bedwars.Handler:Get('ConsumeTreeOrb'):Fire('CallServer', {treeOrbSecret = v:GetAttribute('TreeOrbSecret')}) then
					v:Destroy()
				end
			end, 12, false)
		end,
		block_kicker = function()
			local old = bedwars.BlockKickerKitController.getKickBlockProjectileOriginPosition
			bedwars.BlockKickerKitController.getKickBlockProjectileOriginPosition = function(...)
				local origin, dir = select(2, ...)
				local plr = entitylib.EntityMouse({
					Part = 'RootPart',
					Range = 1000,
					Origin = origin,
					Players = true,
					Wallcheck = true
				})

				if plr then
					local calc = prediction.SolveTrajectory(origin, 100, 20, plr.RootPart.Position, plr.RootPart.Velocity, workspace.Gravity, plr.HipHeight, plr.Jumping and 42.6 or nil, nil, plr.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(plr.RootPart.AssemblyLinearVelocity.Y) > 0.01, plr.RootPart.Position, plr.RootPart, nil, true)

					if calc then
						for i, v in debug.getstack(2) do
							if v == dir then
								debug.setstack(2, i, CFrame.lookAt(origin, calc).LookVector)
							end
						end
					end
				end

				return old(...)
			end

			Active:Clean(function()
				bedwars.BlockKickerKitController.getKickBlockProjectileOriginPosition = old
			end)
		end,
		cat = function()
			local old = bedwars.CatController.leap
			bedwars.CatController.leap = function(...)
				vapeEvents.CatPounce:Fire()
				return old(...)
			end

			Active:Clean(function()
				bedwars.CatController.leap = old
			end)
		end,
		davey = function()
			local old = bedwars.CannonHandController.launchSelf
			bedwars.CannonHandController.launchSelf = function(...)
				local res = {old(...)}
				local self, block = ...

				if block:GetAttribute('PlacedByUserId') == lplr.UserId and (block.Position - entitylib.character.RootPart.Position).Magnitude < 30 then
					task.spawn(bedwars.breakBlock, block, false)
				end

				return unpack(res)
			end

			Active:Clean(function()
				bedwars.CannonHandController.launchSelf = old
			end)
		end,
		dragon_slayer = function()
			kitCollection('KaliyahPunchInteraction', function(v)
				bedwars.DragonSlayerController:deleteEmblem(v)
				bedwars.DragonSlayerController:playPunchAnimation(Vector3.zero)
				bedwars.Handler:Get('RequestDragonPunch'):Fire('SendToServer', {
					target = v
				})
			end, 18, true)
		end,
		farmer_cletus = function()
			kitCollection('HarvestableCrop', function(v)
				if bedwars.Handler:Get('HarvestCrop'):Fire('CallServer', {position = bedwars.BlockController:getBlockPosition(v.Position)}) then
					bedwars.GameAnimationUtil:playAnimation(lplr.Character, bedwars.AnimationType.PUNCH)
					bedwars.AudioManager:playAudio(bedwars.SoundList.CROP_HARVEST)
				end
			end, 10, false)
		end,
		fisherman = function()
			local old = bedwars.FishingMinigameController.startMinigame
			bedwars.FishingMinigameController.startMinigame = function(_, _, result)
				result({win = true})
			end

			Active:Clean(function()
				bedwars.FishingMinigameController.startMinigame = old
			end)
		end,
		gingerbread_man = function()
			local old = bedwars.LaunchPadController.attemptLaunch
			bedwars.LaunchPadController.attemptLaunch = function(...)
				local res = {old(...)}
				local self, block = ...

				if (workspace:GetServerTimeNow() - self.lastLaunch) < 0.4 then
					if block:GetAttribute('PlacedByUserId') == lplr.UserId and (block.Position - entitylib.character.RootPart.Position).Magnitude < 30 then
						task.spawn(bedwars.breakBlock, block, false)
					end
				end

				return unpack(res)
			end

			Active:Clean(function()
				bedwars.LaunchPadController.attemptLaunch = old
			end)
		end,
		hannah = function()
			kitCollection('HannahExecuteInteraction', function(v)
				local billboard = bedwars.Handler:Get('HannahPromptTrigger'):Fire('CallServer', {
					user = lplr,
					victimEntity = v
				}) and v:FindFirstChild('Hannah Execution Icon')

				if billboard then
					billboard:Destroy()
				end
			end, 30, true)
		end,
		jailor = function()
			kitCollection('jailor_soul', function(v)
				bedwars.JailorController:collectEntity(lplr, v, 'JailorSoul')
			end, 20, false)
		end,
		grim_reaper = function()
			kitCollection(bedwars.GrimReaperController.soulsByPosition, function(v)
				if entitylib.isAlive and lplr.Character:GetAttribute('Health') <= (lplr.Character:GetAttribute('MaxHealth') / 4) and (not lplr.Character:GetAttribute('GrimReaperChannel')) then
					bedwars.Handler:Get('ConsumeGrimReaperSoul'):Fire('CallServer', {
						secret = v:GetAttribute('GrimReaperSoulSecret')
					})
				end
			end, 120, false)
		end,
		melody = function()
			repeat
				local mag, hp, ent = 30, math.huge
				if entitylib.isAlive then
					local localPosition = entitylib.character.RootPart.Position
					for _, v in entitylib.List do
						if v.Player and v.Player:GetAttribute('Team') == lplr:GetAttribute('Team') then
							local newmag = (localPosition - v.RootPart.Position).Magnitude
							if newmag <= mag and v.Health < hp and v.Health < v.MaxHealth then
								mag, hp, ent = newmag, v.Health, v
							end
						end
					end
				end

				if ent and getItem('guitar') then
					bedwars.Handler:Get('GuitarHeal'):Fire('SendToServer', {
						healTarget = ent.Character
					})
				end

				task.wait(0.1)
			until not IsRunning()
		end,
		metal_detector = function()
			kitCollection('hidden-metal', function(v)
				bedwars.Handler:Get('CollectCollectableEntity'):Fire('SendToServer', {
					id = v:GetAttribute('Id')
				})
			end, 20, false)
		end,
		miner = function()
			kitCollection('petrified-player', function(v)
				bedwars.Handler:Get('DestroyPetrifiedPlayer'):Fire('SendToServer', {
					petrifyId = v:GetAttribute('PetrifyId')
				})
			end, 6, true)
		end,
		pinata = function()
			kitCollection(lplr.Name..':pinata', function(v)
				if getItem('candy') then
					bedwars.Handler:Get('DepositCoins'):Fire('CallServer', v)
				end
			end, 6, true)
		end,
		spirit_assassin = function()
			kitCollection('EvelynnSoul', function(v)
				bedwars.SpiritAssassinController:useSpirit(lplr, v)
			end, 120, true)
		end,
		star_collector = function()
			kitCollection('stars', function(v)
				bedwars.StarCollectorController:collectEntity(lplr, v, v.Name)
			end, 20, false)
		end,
		summoner = function()
			repeat
				local plr = entitylib.EntityPosition({
					Range = 31,
					Part = 'RootPart',
					Players = true,
					Sort = sortmethods.Health
				})

				if plr and (not Legit.Enabled or (lplr.Character:GetAttribute('Health') or 0) > 0) then
					local localPosition = entitylib.character.RootPart.Position
					local shootDir = CFrame.lookAt(localPosition, plr.RootPart.Position).LookVector
					localPosition += shootDir * math.max((localPosition - plr.RootPart.Position).Magnitude - 16, 0)

					bedwars.Handler:Get('SummonerClawAttackRequest'):Fire('SendToServer', {
						position = localPosition,
						direction = shootDir,
						clientTime = workspace:GetServerTimeNow()
					})
				end

				task.wait(0.1)
			until not IsRunning()
		end,
		void_dragon = function()
			local oldflap = bedwars.VoidDragonController.flapWings
			local flapped

			bedwars.VoidDragonController.flapWings = function(self)
				if not flapped and bedwars.Handler:Get('DragonFlap'):Fire('CallServer') then
					local modifier = bedwars.SprintController:getMovementStatusModifier():addModifier({
						blockSprint = true,
						constantSpeedMultiplier = 2
					})
					self.SpeedMaid:GiveTask(modifier)
					self.SpeedMaid:GiveTask(function()
						flapped = false
					end)
					flapped = true
				end
			end

			Active:Clean(function()
				bedwars.VoidDragonController.flapWings = oldflap
			end)

			repeat
				if bedwars.VoidDragonController.inDragonForm then
					local plr = entitylib.EntityPosition({
						Range = 30,
						Part = 'RootPart',
						Players = true
					})

					if plr then
						bedwars.Handler:Get('DragonBreath'):Fire('SendToServer', {
							player = lplr,
							targetPoint = plr.RootPart.Position
						})
					end
				end
				task.wait(0.1)
			until not IsRunning()
		end,
		warlock = function()
			local lastTarget
			repeat
				if store.hand.tool and store.hand.tool.Name == 'warlock_staff' then
					local plr = entitylib.EntityPosition({
						Range = 30,
						Part = 'RootPart',
						Players = true,
						NPCs = true
					})

					if plr and plr.Character ~= lastTarget then
						if not bedwars.Handler:Get('WarlockLinkTarget'):Fire('CallServer', {
							target = plr.Character
						}) then
							plr = nil
						end
					end

					lastTarget = plr and plr.Character
				else
					lastTarget = nil
				end

				task.wait(0.1)
			until not IsRunning()
		end,
		wizard = function()
			repeat
				local ability = lplr:GetAttribute('WizardAbility')
				if ability and bedwars.AbilityController:canUseAbility(ability, {disableBlockedAbilityAlert = true}) then
					local plr = entitylib.EntityPosition({
						Range = 50,
						Part = 'RootPart',
						Players = true,
						Sort = sortmethods.Health
					})

					if plr then
						bedwars.AbilityController:useAbility(ability, newproxy(true), {target = plr.RootPart.Position})
					end
				end

				task.wait(0.1)
			until not IsRunning()
		end
	}

	local function newBehaviour()
		local cleanups = {}
		local handle = {Enabled = false}

		function handle:Clean(obj)
			table.insert(cleanups, obj)
		end

		function handle:Clear()
			for _, v in cleanups do
				if typeof(v) == 'RBXScriptConnection' then
					pcall(function() v:Disconnect() end)
				elseif typeof(v) == 'Instance' then
					pcall(function() v:Destroy() end)
				elseif typeof(v) == 'function' then
					pcall(v)
				end
			end
			table.clear(cleanups)
		end

		return handle
	end

	local LEGIT_RANGE = {
		dragon_slayer = true, grim_reaper = true, hannah = true, miner = true,
		pinata = true, spirit_assassin = true, summoner = true
	}

	local kitIds = {}
	for kitId in AutoKitFunctions do
		table.insert(kitIds, kitId)
	end
	table.sort(kitIds, function(a, b)
		local metaA, metaB = bedwars.BedwarsKitMeta[a], bedwars.BedwarsKitMeta[b]
		return ((metaA and metaA.name) or a):lower() < ((metaB and metaB.name) or b):lower()
	end)

	task.defer(function()
		for _, kitId in kitIds do
			if kitHasBehaviour(kitId) then continue end
			local kit = getKitModule(kitId, true)
			local meta = bedwars.BedwarsKitMeta[kitId]
			local handle = newBehaviour()

			local legit = LEGIT_RANGE[kitId] and kit:CreateToggle({
				Name = 'Legit Range',
				Default = true,
				Tooltip = 'Keeps its reach close enough to look legit'
			}) or {Enabled = false}

			local function start()
				if handle.Running then return end
				handle.Running, handle.Enabled = true, true
				task.spawn(function()
					repeat
						if handle.Enabled and store.matchState ~= 0 and store.equippedKit == kitId and not kitHasBehaviour(kitId) then
							Active, Legit = handle, legit
							local ok, err = pcall(AutoKitFunctions[kitId])
							Active, Legit = nil, {Enabled = false}
							if not ok then
								notif('Kits', tostring(err), 6, 'warning')
								break
							end
						end
						task.wait(0.1)
					until not handle.Enabled
					handle.Running = false
					handle:Clear()
				end)
			end

			local function stop()
				handle.Enabled, handle.Running = false, false
				handle:Clear()
			end

			table.insert(kitHooksOf(kit), function(enabled)
				if enabled then start() else stop() end
			end)
			if kit.Enabled then start() end
			handle.Toggle = function()
				if kit.Enabled then stop() else start() end
			end
		end
	end)
end)

-- ===== Kits/AutoLani.lua =====
run(function()

	local util = vape.Libraries.bedwarsutil
	local AutoLani
	local Delay
	local UseEnemy
	local Enemy
	local Player

	local Request = bedwars.Handler:Get('PaladinAbilityRequest')

	AutoLani = kits:CreateModule({
		Name = 'AutoLani',
		Function = function(call)
			if call then
				local oldstart

				repeat
					local start = lplr:GetAttribute('PaladinStartTime')
					if oldstart and oldstart ~= start then
						local player = UseEnemy.Enabled and playersService:FindFirstChild(Enemy.Value) or not UseEnemy.Enabled and playersService:FindFirstChild(Player.Value) or nil

						if player then
							task.delay(Delay.Value, function()
								Request:Fire('SendToServer', {target = player})
							end)
						end
					end
					oldstart = start
					task.wait(0.1)
				until not AutoLani.Enabled
			end
		end,
		Tooltip = 'Uses the scepter of light ability'
	})
	local friends, enemies = {'None'}, {'None'}

	local function addConnection(plr, connected)
		local friendly = plr:GetAttribute('Team') == lplr:GetAttribute('Team')

		if not connected then
			vape:Clean(plr:GetAttributeChangedSignal('Team'):Connect(function()
				addConnection(plr, true)
			end))
		end

		if friendly and not table.find(friends, plr.Name) then
			table.insert(friends, plr.Name)
			Player:Change(friends)
		elseif not friendly and plr.Team and plr.Team.Name ~= 'Spectators' and not table.find(enemies, plr.Name) then
			table.insert(enemies, plr.Name)
			Enemy:Change(enemies)
		end
	end

	UseEnemy = AutoLani:CreateGroup({
		Name = 'Use enemy',
		Function = function(call)
			Player.Object.Visible = not call
		end,
		Tooltip = 'Uses the ability on enemies instead of teammates'
	})
	Player = AutoLani:CreateDropdown({
		Name = 'Selected Player',
		List = {},
		Tooltip = 'Player to use the ability on'
	})
	Enemy = UseEnemy:CreateDropdown({
		Name = 'Selected Enemy',
		List = {},
		Tooltip = 'Target to use the ability on'
	})
	Delay = AutoLani:CreateSlider({
		Name = 'Delay',
		Min = 1,
		Max = 20,
		Default = 5,
		Decimal = 10,
		Suffix = util.Seconds,
		Tooltip = 'Delay between triggers'
	})
	for _, v in playersService:GetPlayers() do
		addConnection(v)
	end
	vape:Clean(playersService.PlayerAdded:Connect(addConnection))
end)

-- ===== Kits/AutoLasso.lua =====
run(function()

	local util = vape.Libraries.bedwarsutil
	local AutoLasso
	local Targets
	local Range
	local FireRate
	local SwitchDelay
	local VoidClutch
	local ClutchFallSpeed
	local nextFire = 0
	local voidRay = RaycastParams.new()
	voidRay.RespectCanCollide = true
	voidRay.FilterType = Enum.RaycastFilterType.Exclude

	local function findClutchTarget()
		local root = entitylib.character.RootPart
		local velocity = root.AssemblyLinearVelocity
		if velocity.Y > -ClutchFallSpeed.Value then return end
		voidRay.FilterDescendantsInstances = {lplr.Character, gameCamera}
		local fallTime = math.clamp((-velocity.Y + math.sqrt(velocity.Y * velocity.Y + 2 * workspace.Gravity * 45)) / workspace.Gravity, 0.25, 1.35)
		local predicted = root.Position + velocity * fallTime + Vector3.new(0, -0.5 * workspace.Gravity * fallTime * fallTime, 0)
		if workspace:Raycast(root.Position, predicted - root.Position, voidRay) then return end

		return entitylib.EntityPosition({
			Origin = root.Position,
			Range = Range.Value,
			Part = 'RootPart',
			Players = Targets.Players.Enabled,
			Priority = Targets.Priority and Targets.Priority.Value,
			NPCs = Targets.NPCs.Enabled,
			Wallcheck = Targets.Walls.Enabled or nil,
			Sort = sortmethods.Distance
		})
	end

	local function throwLasso(target)
		local item = getItem('lasso')
		local source = item and bedwars.ItemMeta.lasso.projectileSource or nil
		target = target or (source and getFacingEntity({
			Part = 'RootPart',
			Range = Range.Value,
			Players = Targets.Players.Enabled,
			Priority = Targets.Priority and Targets.Priority.Value,
			NPCs = Targets.NPCs.Enabled,
			Wallcheck = Targets.Walls.Enabled,
			Limit = 10
		}) or nil)
		if not source or not target then return end

		local hotbar = store.hand.tool and getHotbar(store.hand.tool) or nil
		if hotbarSwitch(getHotbar(item.tool)) then
			task.wait(store.ping.total or 0)
			if fireProjectile(item, 'lasso', source.projectileType('lasso'), target) then
				nextFire = tick() + source.fireDelaySec + FireRate:GetRandomValue()
				task.wait(SwitchDelay.Value)
			end
			hotbarSwitch(hotbar)
		end
	end

	AutoLasso = kits:CreateModule({
		Name = 'AutoLasso',
		Function = function(callback)
			if callback then
				nextFire = 0

				repeat
					if entitylib.isAlive and tick() >= nextFire then
						if store.equippedKit == 'cowgirl' and store.hand.toolType == 'sword' and (tick() - bedwars.SwordController.lastSwing) < 0.2 then
							throwLasso()
						elseif VoidClutch.Enabled then
							local target = findClutchTarget()
							if target then throwLasso(target) end
						end
					end
					task.wait(0.1)
				until not AutoLasso.Enabled
			end
		end,
		Tooltip = 'Throws the lasso at your melee target, with an optional void clutch'
	})
	Targets = AutoLasso:CreateTargets({
		Players = true,
		NPCs = false
	})
	Range = AutoLasso:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 60,
		Default = 22,
		Suffix = util.Studs
	})
	FireRate = AutoLasso:CreateTwoSlider({
		Name = 'Fire Rate',
		Min = 0,
		Max = 1,
		DefaultMin = 0.05,
		DefaultMax = 0.12,
		Decimal = 100
	})
	SwitchDelay = AutoLasso:CreateSlider({
		Name = 'Switch Delay',
		Min = 0,
		Max = 1,
		Decimal = 100,
		Suffix = 'seconds',
		Default = 0.02
	})
	VoidClutch = AutoLasso:CreateToggle({
		
		
		Name = 'Void',
		Tooltip = 'Lassos a nearby target when falling into the void'
	})
	ClutchFallSpeed = AutoLasso:CreateSlider({
		Name = 'Clutch fall speed',
		Min = 1,
		Max = 100,
		Default = 18,
		Tooltip = 'How fast you must be falling before it acts'
	})
end)

-- ===== Kits/AutoLian.lua =====
run(function()
	local AutoLian
	local Targets
	local Range
	local Delay

	local dragonSwordFire = replicatedStorage:WaitForChild('rbxts_include'):WaitForChild('node_modules'):WaitForChild('@rbxts'):WaitForChild('net'):WaitForChild('out'):WaitForChild('_NetManaged'):WaitForChild('DragonSwordFire')

	local function startLoop()
		task.spawn(function()
			repeat task.wait() until Targets and Range and Delay
			repeat
				if not entitylib.isAlive then task.wait(0.1); continue end
				local plr = entitylib.EntityPosition({
					Range = Range.Value,
					Part = 'RootPart',
					Players = Targets.Players.Enabled,
					NPCs = Targets.NPCs.Enabled,
					Wallcheck = Targets.Walls.Enabled,
					Sort = sortmethods.Distance
				})
				if plr and plr.Character then
					pcall(function()
						dragonSwordFire:FireServer({ target = plr.Character })
					end)
					task.wait(Delay.Value)
				end
				task.wait(0.1)
			until not AutoLian.Enabled
		end)
	end

	AutoLian = vape.Categories.Kits:CreateModule({
		Name = 'AutoLian',
		Function = function(callback)
			if callback then startLoop() end
		end,
		Tooltip = 'auto swings lian dragon sword at enemies'
	})

	Targets = AutoLian:CreateTargets({
		Players = true,
		NPCs = true,
		Walls = true
	})
	Range = AutoLian:CreateSlider({
		Name = 'Range',
		Tooltip = 'how close a enemy gotta be',
		Min = 1,
		Max = 18,
		Default = 14
	})
	Delay = AutoLian:CreateSlider({
		Name = 'Delay',
		Tooltip = 'wait time between swings',
		Min = 0,
		Max = 2,
		Default = 0.5,
		Decimal = 10,
		Suffix = 's'
	})
end)

-- ===== Kits/AutoLucia.lua =====
run(function()
    local Lucia
    local AutoDepositToggle
    local RangeSlider
    local DelayToggle
    local DelaySlider
    local LuciaESPToggle
    local CandyESPToggle
    local IgnoreTeammatesESP
    local ESPBackground
    local ESPColor = {}
    local LuciaSpyToggle
    local IgnoreTeammatesSpy
    local DisplayNameToggle
    local Players = playersService
    local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui
	local Reference = {}
	local collectedPinatas = {}
	local trackedPinatas = {}

    local function kitCollection(id, func, range, specific)
        repeat
            if entitylib.isAlive then
                local objs = type(id) == 'table' and id or collection(id, Lucia)
                local localPosition = entitylib.character.RootPart.Position
                for _, v in objs do
                    if not Lucia.Enabled then break end
                    local part = not v:IsA('Model') and v or v.PrimaryPart
                    if part and (part.Position - localPosition).Magnitude <= range then
                        local success, err = pcall(func, v)
                        if not success then
                            warn("lucia deposit error:", err)
                        end
                        if DelayToggle.Enabled then
                            task.wait(DelaySlider.Value)
                        else
                            task.wait(0.05)
                        end
                    end
                end
            end
            task.wait(0.1)
        until not Lucia.Enabled
    end

    local function isTeammateESP(pinataPart)
        if not IgnoreTeammatesESP.Enabled then return false end

        local placerId = pinataPart:GetAttribute("PlacedByUserId") or pinataPart:GetAttribute("PlacerId")
        if not placerId then
            local parent = pinataPart.Parent
            if parent then
                placerId = parent:GetAttribute("PlacedByUserId") or parent:GetAttribute("PlacerId")
            end
        end

        if placerId then
            if placerId == lplr.UserId then
                return true
            end

            local placer = playersService:GetPlayerByUserId(placerId)
            if placer and placer.Team == lplr.Team then
                return true
            end
        end

        return false
    end

    local function isTeammateSpy(pinataPart)
        if not IgnoreTeammatesSpy.Enabled then return false end

        local placerId = pinataPart:GetAttribute("PlacedByUserId") or pinataPart:GetAttribute("PlacerId")
        if not placerId then
            local parent = pinataPart.Parent
            if parent then
                placerId = parent:GetAttribute("PlacedByUserId") or parent:GetAttribute("PlacerId")
            end
        end

        if placerId then
            if placerId == lplr.UserId then
                return true
            end

            local placer = playersService:GetPlayerByUserId(placerId)
            if placer and placer.Team == lplr.Team then
                return true
            end
        end

        return false
    end

    local function getCandyAmount(pinataPart)
        local coins = pinataPart:GetAttribute("Coin")
        return coins or 0
    end

    local function getProperIcon(iconType)
        local icon = bedwars.getIcon({itemType = iconType}, true)
        if not icon or icon == "" then
            return nil
        end
        return icon
    end

    local function Added(pinataPart)
        if isTeammateESP(pinataPart) then
            return
        end

        if Reference[pinataPart] then return end

        local billboard = Instance.new('BillboardGui')
        billboard.Parent = Folder
        billboard.Name = 'pinata'
        billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
        billboard.Size = UDim2.fromOffset(CandyESPToggle.Enabled and 80 or 36, 36)
        billboard.AlwaysOnTop = true
        billboard.ClipsDescendants = false
        billboard.Adornee = pinataPart

        local blur = addBlur(billboard)
        blur.Visible = ESPBackground.Enabled

        local frame = Instance.new('Frame')
        frame.Size = UDim2.fromScale(1, 1)
        frame.BackgroundColor3 = Color3.fromHSV(ESPColor.Hue, ESPColor.Sat, ESPColor.Value)
        frame.BackgroundTransparency = 1 - (ESPBackground.Enabled and ESPColor.Opacity or 0)
        frame.BorderSizePixel = 0
        frame.Parent = billboard

        local uicorner = Instance.new('UICorner')
        uicorner.CornerRadius = UDim.new(0, 4)
        uicorner.Parent = frame

        local pinataIcon = getProperIcon('pinata')
        if pinataIcon then
            local image = Instance.new('ImageLabel')
            image.Name = 'PinataIcon'
            image.Size = UDim2.fromOffset(36, 36)
            image.Position = UDim2.new(0, 0, 0.5, 0)
            image.AnchorPoint = Vector2.new(0, 0.5)
            image.BackgroundTransparency = 1
            image.Image = pinataIcon
            image.Parent = frame
        end

        local candyAmount = nil
        local candyIcon = nil

        if CandyESPToggle.Enabled then
            candyAmount = Instance.new('TextLabel')
            candyAmount.Name = 'CandyAmount'
            candyAmount.Size = UDim2.fromOffset(25, 20)
            candyAmount.Position = UDim2.new(0, 40, 0.5, 0)
            candyAmount.AnchorPoint = Vector2.new(0, 0.5)
            candyAmount.BackgroundTransparency = 1
            candyAmount.Text = tostring(getCandyAmount(pinataPart))
            candyAmount.TextColor3 = Color3.fromRGB(255, 255, 255)
            candyAmount.TextSize = 16
            candyAmount.Font = Enum.Font.GothamBold
            candyAmount.TextStrokeTransparency = 0.5
            candyAmount.TextStrokeColor3 = Color3.new(0, 0, 0)
            candyAmount.Parent = frame

            local candyIconImage = getProperIcon('candy')
            if candyIconImage then
                candyIcon = Instance.new('ImageLabel')
                candyIcon.Name = 'CandyIcon'
                candyIcon.Size = UDim2.fromOffset(18, 18)
                candyIcon.Position = UDim2.new(0, 65, 0.5, 0)
                candyIcon.AnchorPoint = Vector2.new(0, 0.5)
                candyIcon.BackgroundTransparency = 1
                candyIcon.Image = candyIconImage
                candyIcon.Parent = frame
            end
        end

        Reference[pinataPart] = {
            billboard = billboard,
            frame = frame,
            candyAmount = candyAmount,
            candyIcon = candyIcon
        }
    end

    local function Removed(pinataPart)
        if Reference[pinataPart] then
            Reference[pinataPart].billboard:Destroy()
            Reference[pinataPart] = nil
        end
    end

    local function updateCandyDisplay(pinataPart)
        local ref = Reference[pinataPart]
        if not ref then return end

        if CandyESPToggle.Enabled then
            if not ref.candyAmount then
                ref.candyAmount = Instance.new('TextLabel')
                ref.candyAmount.Name = 'CandyAmount'
                ref.candyAmount.Size = UDim2.fromOffset(25, 20)
                ref.candyAmount.Position = UDim2.new(0, 40, 0.5, 0)
                ref.candyAmount.AnchorPoint = Vector2.new(0, 0.5)
                ref.candyAmount.BackgroundTransparency = 1
                ref.candyAmount.TextColor3 = Color3.fromRGB(255, 255, 255)
                ref.candyAmount.TextSize = 16
                ref.candyAmount.Font = Enum.Font.GothamBold
                ref.candyAmount.TextStrokeTransparency = 0.5
                ref.candyAmount.TextStrokeColor3 = Color3.new(0, 0, 0)
                ref.candyAmount.Parent = ref.frame

                local candyIconImage = getProperIcon('candy')
                if candyIconImage and not ref.candyIcon then
                    ref.candyIcon = Instance.new('ImageLabel')
                    ref.candyIcon.Name = 'CandyIcon'
                    ref.candyIcon.Size = UDim2.fromOffset(18, 18)
                    ref.candyIcon.Position = UDim2.new(0, 65, 0.5, 0)
                    ref.candyIcon.AnchorPoint = Vector2.new(0, 0.5)
                    ref.candyIcon.BackgroundTransparency = 1
                    ref.candyIcon.Image = candyIconImage
                    ref.candyIcon.Parent = ref.frame
                end

                ref.billboard.Size = UDim2.fromOffset(80, 36)
            end

            if ref.candyAmount then
                ref.candyAmount.Text = tostring(getCandyAmount(pinataPart))
            end
        else
            if ref.candyAmount then
                ref.candyAmount:Destroy()
                ref.candyAmount = nil
            end
            if ref.candyIcon then
                ref.candyIcon:Destroy()
                ref.candyIcon = nil
            end
            ref.billboard.Size = UDim2.fromOffset(36, 36)
        end
    end

    local function findExistingPinatas()
        scanDescendants(workspace, function(obj)
            if obj:IsA("BasePart") and obj.Name == "pinata" then
                if not Reference[obj] and not isTeammateESP(obj) then
                    Added(obj)
                end
            end
        end)
    end

    local function refreshESP()
        Folder:ClearAllChildren()
        table.clear(Reference)
        findExistingPinatas()
    end

    local function getLuciaPlayerName(player)
		return getPlayerName(player, DisplayNameToggle and DisplayNameToggle.Enabled)
	end

    local function getTeamName(player)
		return player.Team and player.Team.Name or "Unknown"
	end

    local function setupLuciaSpy()
        local util = require(game:GetService("ReplicatedStorage").TS.games.bedwars.kit.kits['piggy-bank']['piggy-bank-util']).PiggyBankUtil

        scanDescendants(workspace, function(obj)
            if obj:IsA("BasePart") and obj.Name == "pinata" then
                if not isTeammateSpy(obj) then
                    local placerId = obj:GetAttribute("PlacedByUserId") or obj:GetAttribute("PlacerId")

                    if placerId then
                        local placer = playersService:GetPlayerByUserId(placerId)
                        local initialCandy = getCandyAmount(obj)

                        trackedPinatas[obj] = {
                            player = placer,
                            lastCandy = initialCandy,
                            exists = true,
                            placedTime = tick()
                        }
                    end
                end
            end
        end)

        Lucia:Clean(workspace.DescendantAdded:Connect(function(obj)
            if not LuciaSpyToggle.Enabled then return end

            if obj:IsA("BasePart") and obj.Name == "pinata" then
                task.wait(0.2)

                if not isTeammateSpy(obj) then
                    local placerId = obj:GetAttribute("PlacedByUserId") or obj:GetAttribute("PlacerId")

                    if placerId then
                        local placer = playersService:GetPlayerByUserId(placerId)
                        local initialCandy = getCandyAmount(obj)

                        trackedPinatas[obj] = {
                            player = placer,
                            lastCandy = initialCandy,
                            exists = true,
                            placedTime = tick()
                        }
                    end
                end
            end
        end))

        Lucia:Clean(bedwars.Client:Get("PiggyBankPop"):Connect(function(self)
            if not LuciaSpyToggle.Enabled then return end
            local plr = self.awardedPlayer
            if not plr then return end
            if IgnoreTeammatesSpy.Enabled then
                if plr == lplr or (plr.Team and plr.Team == lplr.Team) then
                    return
                end
            end

            local rewards = util:getRewardsFromCoins(self.coins)
            local I, D, E = 0, 0, 0
            for _, reward in ipairs(rewards) do
                if reward.itemType == "iron" then
                    I = I + (reward.amount or 0)
                elseif reward.itemType == "diamond" then
                    D = D + (reward.amount or 0)
                elseif reward.itemType == "emerald" then
                    E = E + (reward.amount or 0)
                end
            end

            local playerName = getPlayerName(plr)
            local teamName = getTeamName(plr)
            local loot = string.format("%d irons, %d diamonds, %d emeralds", I, D, E)

            vape:CreateNotification(
                "Lucia Spy",
                string.format("%s (%s) opened their pinata and got %s", playerName, teamName, loot),
                8
            )

            for pinataPart, data in pairs(trackedPinatas) do
                if data.player and data.player.UserId == plr.UserId then
                    trackedPinatas[pinataPart] = nil
                end
            end
        end))

        local luciaSpyCounter = 0
        Lucia:Clean(RunService.Heartbeat:Connect(function()
            if not LuciaSpyToggle.Enabled then return end
            luciaSpyCounter = luciaSpyCounter + 1
            if luciaSpyCounter % 6 ~= 0 then return end
            local toRemove = {}
            for pinataPart, data in pairs(trackedPinatas) do
                if pinataPart and pinataPart.Parent then
                    local currentCandy = getCandyAmount(pinataPart)

                    if currentCandy ~= data.lastCandy then
                        local difference = currentCandy - data.lastCandy

                        if difference > 0 and data.player then
                                local playerName = getPlayerName(data.player)
                                local teamName = getTeamName(data.player)

                                vape:CreateNotification(
                                    "Lucia Spy",
                                    string.format("%s (%s) has just deposited %d candy and now has %d candy",
                                        playerName, teamName, difference, currentCandy),
                                    5
                                )
                            end
                            data.lastCandy = currentCandy
                        end
                else
                    if data.exists and data.player then
                        local timeSincePlaced = tick() - (data.placedTime or tick())

                        if timeSincePlaced > 2 then
                                local playerName = getPlayerName(data.player)
                                local teamName = getTeamName(data.player)

                                vape:CreateNotification(
                                    "Lucia Spy",
                                    string.format("%s (%s) has just broken their pinata with %d candy",
                                        playerName, teamName, data.lastCandy),
                                    5
                                )
                            end
                        end

                    table.insert(toRemove, pinataPart)
                end
            end

            for _, pinataPart in ipairs(toRemove) do
                trackedPinatas[pinataPart] = nil
            end
        end))
    end

    Lucia = vape.Categories.Kits:CreateModule({
        Name = 'AutoLucia',
        Function = function(callback)
            if callback then
                if LuciaESPToggle.Enabled then
                    findExistingPinatas()

                    Lucia:Clean(workspace.DescendantAdded:Connect(function(obj)
                        if Lucia.Enabled and obj:IsA("BasePart") and obj.Name == "pinata" then
                            task.wait(0.1)
                            if not isTeammateESP(obj) then
                                Added(obj)
                            end
                        end
                    end))

                    Lucia:Clean(workspace.DescendantRemoving:Connect(function(obj)
                        if obj:IsA("BasePart") and obj.Name == "pinata" and Reference[obj] then
                            Removed(obj)
                        end
                    end))

                    local luciaESPCounter = 0
                    Lucia:Clean(RunService.Heartbeat:Connect(function()
                        if not Lucia.Enabled or not LuciaESPToggle.Enabled then return end
                        luciaESPCounter = luciaESPCounter + 1
                        if luciaESPCounter % 6 ~= 0 then return end
                        for pinataPart, ref in pairs(Reference) do
                            if pinataPart and pinataPart.Parent then
                                updateCandyDisplay(pinataPart)
                            else
                                if ref.billboard then
                                    ref.billboard:Destroy()
                                end
                                Reference[pinataPart] = nil
                            end
                        end
                    end))
                end

                if AutoDepositToggle.Enabled then
                    task.spawn(function()
                        local r = RangeSlider.Value
                        kitCollection(lplr.Name .. ':pinata', function(v)
                            if getItem('candy') then
                                bedwars.Client:Get(remotes.DepositCoins):CallServer(v)
                            end
                        end, r, true)
                    end)
                end

                if LuciaSpyToggle.Enabled then
                    setupLuciaSpy()
                end
            else
                Folder:ClearAllChildren()
                table.clear(Reference)
                table.clear(collectedPinatas)
                table.clear(trackedPinatas)
            end
        end,
    })

    AutoDepositToggle = Lucia:CreateToggle({
        Name = 'Auto Deposit',
        Default = false,
        Function = function(callback)
            if RangeSlider and RangeSlider.Object then RangeSlider.Object.Visible = callback end
            if DelayToggle and DelayToggle.Object then DelayToggle.Object.Visible = callback end
            if DelaySlider and DelaySlider.Object then DelaySlider.Object.Visible = (callback and DelayToggle.Enabled) end

            if not callback then
                if DelaySlider and DelaySlider.Object then
                    DelaySlider.Object.Visible = false
                end
            else
                if DelayToggle and DelayToggle.Enabled then
                    if DelaySlider and DelaySlider.Object then
                        DelaySlider.Object.Visible = true
                    end
                end
            end
        end
    })

    RangeSlider = Lucia:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 18,
        Default = 8,
        Suffix = ' studs',
        Visible = false
    })

    DelayToggle = Lucia:CreateToggle({
        Name = 'Delay',
        Default = false,
        Visible = false,
        Function = function(callback)
            if DelaySlider and DelaySlider.Object then
                DelaySlider.Object.Visible = callback
            end
        end
    })

    DelaySlider = Lucia:CreateSlider({
        Name = 'Delay Amount',
        Min = 0,
        Max = 2,
        Default = 0.5,
        Decimal = 10,
        Suffix = 's',
        Visible = false
    })

    LuciaESPToggle = Lucia:CreateToggle({
        Name = 'Pinata ESP',
        Function = function(callback)
            if CandyESPToggle and CandyESPToggle.Object then
                CandyESPToggle.Object.Visible = callback
            end
            if IgnoreTeammatesESP and IgnoreTeammatesESP.Object then
                IgnoreTeammatesESP.Object.Visible = callback
            end
            if ESPBackground and ESPBackground.Object then
                ESPBackground.Object.Visible = callback
            end
            if ESPColor and ESPColor.Object then
                ESPColor.Object.Visible = callback
            end

            if not callback then
                if ESPColor and ESPColor.Object then
                    ESPColor.Object.Visible = false
                end
            else
                if ESPBackground and ESPBackground.Enabled then
                    if ESPColor and ESPColor.Object then
                        ESPColor.Object.Visible = true
                    end
                end
            end

            if Lucia.Enabled then
                if callback then
                    findExistingPinatas()
                else
                    Folder:ClearAllChildren()
                    table.clear(Reference)
                end
            end
        end
    })

    CandyESPToggle = Lucia:CreateToggle({
        Name = 'Candy ESP',
        Visible = false,
        Tooltip = 'show amount of candy in pinatas',
        Function = function(callback)
            for pinataPart in pairs(Reference) do
                updateCandyDisplay(pinataPart)
            end
        end
    })

    IgnoreTeammatesESP = Lucia:CreateToggle({
        Name = 'Ignore Teammates',
        Visible = false,
        Function = function(callback)
            if Lucia.Enabled and LuciaESPToggle.Enabled then
                refreshESP()
            end
        end
    })

    ESPBackground = Lucia:CreateToggle({
        Name = 'Background',
        Visible = false,
        Function = function(callback)
            if ESPColor and ESPColor.Object then
                ESPColor.Object.Visible = callback
            end
            for _, ref in pairs(Reference) do
                if ref.frame then
                    ref.frame.BackgroundTransparency = 1 - (callback and ESPColor.Opacity or 0)
                    if ref.billboard.Blur then
                        ref.billboard.Blur.Visible = callback
                    end
                end
            end
        end
    })

    ESPColor = Lucia:CreateColorSlider({
        Name = 'Background Color',
        DefaultValue = 0,
        DefaultOpacity = 0.5,
        Visible = false,
        Function = function(hue, sat, val, opacity)
            ESPColor.Hue = hue
            ESPColor.Sat = sat
            ESPColor.Value = val
            ESPColor.Opacity = opacity

            for _, ref in pairs(Reference) do
                if ref.frame then
                    ref.frame.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
                    ref.frame.BackgroundTransparency = 1 - opacity
                end
            end
        end,
        Darker = true
    })

    LuciaSpyToggle = Lucia:CreateToggle({
        Name = 'Lucia Spy',
        Default = false,
        Tooltip = 'notifies you varius info for lucia kits for players (amount of loot and etc)',
        Function = function(callback)
            if IgnoreTeammatesSpy and IgnoreTeammatesSpy.Object then
                IgnoreTeammatesSpy.Object.Visible = callback
            end
            if DisplayNameToggle and DisplayNameToggle.Object then
                DisplayNameToggle.Object.Visible = callback
            end

            if Lucia.Enabled and callback then
                setupLuciaSpy()
            else
                table.clear(trackedPinatas)
            end
        end
    })

    IgnoreTeammatesSpy = Lucia:CreateToggle({
        Name = 'Ignore Teammates',
        Default = true,
        Visible = false
    })

    DisplayNameToggle = Lucia:CreateToggle({
        Name = 'Display Name',
        Default = false,
        Visible = false,
    })

    task.defer(function()
        if RangeSlider and RangeSlider.Object then RangeSlider.Object.Visible = false end
        if DelayToggle and DelayToggle.Object then DelayToggle.Object.Visible = false end
        if DelaySlider and DelaySlider.Object then DelaySlider.Object.Visible = false end
        if CandyESPToggle and CandyESPToggle.Object then CandyESPToggle.Object.Visible = false end
        if IgnoreTeammatesESP and IgnoreTeammatesESP.Object then IgnoreTeammatesESP.Object.Visible = false end
        if ESPBackground and ESPBackground.Object then ESPBackground.Object.Visible = false end
        if ESPColor and ESPColor.Object then ESPColor.Object.Visible = false end
        if IgnoreTeammatesSpy and IgnoreTeammatesSpy.Object then IgnoreTeammatesSpy.Object.Visible = false end
        if DisplayNameToggle and DisplayNameToggle.Object then DisplayNameToggle.Object.Visible = false end
    end)
end)

-- ===== Kits/AutoLumen.lua =====
run(function()

	local util = vape.Libraries.bedwarsutil
	local AutoLumen
	local Targets
	local Range
	local FullCharge
	local Delay

	local Balance = bedwars.LumenBalance or {MIN_CHARGE_TIME = 0.65, MAX_CHARGE_TIME = 1.25}
	local Sword = 'light_sword'
	local cooldown = 0

	local function getChargeTime()
		local itemmeta = bedwars.ItemMeta[Sword]
		local charged = itemmeta and itemmeta.sword and itemmeta.sword.chargedAttack
		local minimum = charged and charged.minChargeTimeSec or Balance.MIN_CHARGE_TIME
		local maximum = charged and charged.maxChargeTimeSec or Balance.MAX_CHARGE_TIME
		return FullCharge.Enabled and maximum or minimum
	end

	local function chargedSwing()
		local charge = bedwars.SwordChargeController
		if charge:getChargeState() ~= bedwars.ChargeState.Idle then return end

		charge:startCharging(Sword)
		local started = charge:getChargeStartTime()
		if started == 0 then return end

		local target = getChargeTime() + 0.05
		repeat task.wait() until not AutoLumen.Enabled or not entitylib.isAlive or (tick() - started) >= target

		local chargeTime = tick() - started
		charge:stopCharging(Sword)
		if not AutoLumen.Enabled or not entitylib.isAlive then return end

		local tool = store.hand.tool
		if not tool or tool.Name ~= Sword then return end

		local charged = bedwars.ItemMeta[Sword].sword.chargedAttack
		if not (charged.skipSwingDamage and chargeTime > (charged.minChargeTimeSec or Balance.MIN_CHARGE_TIME)) then
			bedwars.SwordController:swingSwordAtMouse(chargeTime)
		end

		bedwars.SyncEvents.SwordChargedSwing:fire(lplr, tool, {chargeTime = chargeTime})
		cooldown = tick() + Delay.Value
	end

	AutoLumen = kits:CreateModule({
		Name = 'AutoLumen',
		Function = function(callback)
			if callback then
				cooldown = 0

				repeat
					if entitylib.isAlive and store.equippedKit == 'lumen' and store.hand.tool and store.hand.tool.Name == Sword and tick() >= cooldown then
						local target = entitylib.EntityMouse({
							Origin = entitylib.character.RootPart.Position,
							Range = Range.Value,
							Part = 'RootPart',
							Players = Targets.Players.Enabled,
							Priority = Targets.Priority and Targets.Priority.Value,
							NPCs = Targets.NPCs.Enabled,
							Wallcheck = Targets.Walls.Enabled
						})

						if target then
							chargedSwing()
						end
					end
					task.wait(0.1)
				until not AutoLumen.Enabled
			end
		end,
		Tooltip = 'Charges and releases the sword of light when an enemy is in front of you'
	})
	Targets = AutoLumen:CreateTargets({
		Players = true,
		Walls = true
	})
	Range = AutoLumen:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 120,
		Default = 60,
		Suffix = util.Studs
	})
	FullCharge = AutoLumen:CreateToggle({
		Name = 'Full charge',
		Default = true,
		Tooltip = 'Holds the swing until fully charged'
	})
	Delay = AutoLumen:CreateSlider({
		Name = 'Delay',
		Min = 0,
		Max = 2,
		Default = 0.1,
		Decimal = 100,
		Suffix = 'seconds'
	})

end)

-- ===== Kits/AutoMarcel.lua =====
run(function()
	local AutoMarcel
	local Delay
	local Debug

	local function getController()
		local knit = bedwars.Knit
		local controllers = knit and knit.Controllers
		return controllers and controllers.DefenderKitController or nil
	end

	local function getScannerMode()
		local ok, state = pcall(bedwars.Store.getState, bedwars.Store)
		local kit = ok and type(state) == 'table' and state.Kit
		return kit and kit.defenderScannerMode or nil
	end

	local function request(controller, blockPos, blockType)
		local mode = getScannerMode()

		if mode == 'upgrade' and type(controller.requestScannerAction) == 'function' then
			return pcall(controller.requestScannerAction, controller, blockPos, 'upgrade', blockType)
		end
		if mode == 'refund' and type(controller.requestScannerAction) == 'function' then
			return pcall(controller.requestScannerAction, controller, blockPos, 'refund')
		end

		if type(controller.requestPlaceDefenderBlock) == 'function' then
			return pcall(controller.requestPlaceDefenderBlock, controller, blockPos)
		end

		local remote = controller.requestPlaceDefenderBlockRemote
		if remote then
			if type(remote.SendToServer) == 'function' then
				return pcall(function() remote:SendToServer(blockPos) end)
			end
			if type(remote.FireServer) == 'function' then
				return pcall(function() remote:FireServer(blockPos) end)
			end
		end

		return false, 'this BedWars build has no defender placement path'
	end

	local reportedFailure = false

	AutoMarcel = kits:CreateModule({
		Name = 'AutoMarcel',
		Function = function(callback)
			if not callback then return end
			reportedFailure = false

			AutoMarcel:Clean(task.spawn(function()
				repeat
					if entitylib.isAlive then
						local controller = getController()
						local schematic = controller and controller.currentSchematic
						if type(schematic) == 'table' then
							for blockPos, blockType in schematic do
								if not AutoMarcel.Enabled then break end
								if not entitylib.isAlive then break end

								local ok, err = request(controller, blockPos, blockType)
								if not ok and Debug.Enabled and not reportedFailure then
									reportedFailure = true
									notif('AutoMarcel', tostring(err), 8, 'warning')
								end
								task.wait(Delay.Value)
							end
						end
					end
					task.wait(0.1)
				until not AutoMarcel.Enabled
			end))
		end,
		Tooltip = 'Builds the whole Defender schematic for you'
	})

	Delay = AutoMarcel:CreateSlider({
		Name = 'Delay',
		Tooltip = 'Wait time between placements',
		Min = 0,
		Max = 1,
		Default = 0.05,
		Decimal = 100,
		Suffix = 's'
	})
	Debug = AutoMarcel:CreateToggle({
		Name = 'Debug',
		Tooltip = 'Logs what it does'
	})
end)

-- ===== Kits/AutoMarina.lua =====
run(function()

	local util = vape.Libraries.bedwarsutil
	local AutoMarina
	local Range

	AutoMarina = kits:CreateModule({
		Name = 'AutoMarina',
		Function = function(call)
			if call then
				local jellies = collection('jellyfish', AutoMarina, function(tab, obj)
					task.delay(0, function()
						if obj:GetAttribute('PlacedByUserId') == lplr.UserId then
							table.insert(tab, obj)
						end
					end)
				end)

				repeat
					if entitylib.isAlive and bedwars.AbilityController:canUseAbility('electrify_jellyfish', {disableBlockedAbilityAlert = true}) then
						for _, v in jellies do
							if v.PrimaryPart and entitylib.EntityPosition({
								Origin = v.PrimaryPart.Position,
								Range = Range.Value,
								Part = 'RootPart',
								Players = true
							}) then
								bedwars.AbilityController:useAbility('electrify_jellyfish')
								break
							end
						end
					end
					task.wait(0.1)
				until not AutoMarina.Enabled
			end
		end,
		Tooltip = 'Uses electrify when enemies are near your jellies'
	})
	Range = AutoMarina:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 65,
		Default = 50,
		Suffix = util.Studs
	})
end)

-- ===== Kits/AutoMarrow.lua =====
run(function()

	local util = vape.Libraries.bedwarsutil
	local AutoMarrow
	local Mode
	local Targets
	local Range
	local Health

	AutoMarrow = kits:CreateModule({
		Name = 'AutoMarrow',
		Function = function(callback)
			if callback then
				repeat
					if entitylib.isAlive and store.equippedKit == 'skeleton' and bedwars.AbilityController:canUseAbility('skeleton_ability', {disableBlockedAbilityAlert = true}) then
						local humanoid = entitylib.character.Humanoid
						local low = humanoid.Health <= (humanoid.MaxHealth * (Health.Value / 100))
						local near = #entitylib.AllPosition({
							Range = Range.Value,
							Part = 'RootPart',
							Players = Targets.Players.Enabled,
							NPCs = Targets.NPCs.Enabled,
							Wallcheck = Targets.Walls.Enabled
						}) > 0

						if (Mode.Value == 'Low Health' and low) or (Mode.Value == 'Enemy Near' and near) or (Mode.Value == 'Both' and (low or near)) then
							bedwars.AbilityController:useAbility('skeleton_ability')
						end
					end
					task.wait(0.1)
				until not AutoMarrow.Enabled
			end
		end,
		Tooltip = 'Drops Toxic Escape clouds when you are in trouble'
	})
	Targets = AutoMarrow:CreateTargets({
		Players = true,
		NPCs = true
	})

	Mode = AutoMarrow:CreateDropdown({
		Name = 'Mode',
