		Max = 1000,
		Default = 2,
		Tooltip = 'Only sells at the selected price'
	})
end)

-- ===== Kits/AutoTerra.lua =====
run(function()
	local AutoTerra
	local BlockCount

	local function startLoop()
		task.spawn(function()
			repeat task.wait() until BlockCount
			repeat
				if entitylib.isAlive and bedwars.AbilityController then
					local character = lplr.Character
					local blocks = 0
					if character then
						blocks = character:GetAttribute('BlockKickerKit_BlockCount') or lplr:GetAttribute('BlockKickerKit_BlockCount') or 0
					else
						blocks = lplr:GetAttribute('BlockKickerKit_BlockCount') or 0
					end
					if blocks <= BlockCount.Value and bedwars.AbilityController:canUseAbility('BLOCK_STOMP') then
						pcall(function() bedwars.AbilityController:useAbility('BLOCK_STOMP') end)
						task.wait(0.8)
					end
				end
				task.wait(0.1)
			until not AutoTerra.Enabled
		end)
	end

	AutoTerra = vape.Categories.Kits:CreateModule({
		Name = 'AutoTerra',
		Function = function(callback)
			if callback then startLoop() end
		end,
		Tooltip = 'auto stomps to refill ur blocks'
	})

	BlockCount = AutoTerra:CreateSlider({
		Name = 'Block Count',
		Tooltip = 'stomps when ur blocks drop to this',
		Min = 0,
		Max = 10,
		Default = 0
	})
end)

-- ===== Kits/AutoTrap.lua =====
run(function()
	local function CanPlace() return not bedwars.BlockPlacementController.disabled and not isCasting() end
	local Camera = gameCamera
	local Collection = collection
	local CollectionService = collectionService
	local Entity = entitylib
	local GetHotbar = getHotbar
	local GetItem = getItem
	local GetPlacedBlock = getPlacedBlock
	local HotbarSwitch = hotbarSwitch
	local LocalPlayer = lplr
	local ReplicatedStorage = replicatedStorage
	local RoundPosition = roundPos
	local SendNotification = notif
	local SortMethods = sortmethods
	local Store = store
	local AutoTrap
	local Mode
	local Targets
	local TrapType
	local Traps
	local Target
	local Radius
	local Range
	local Amount
	local PlaceRange
	local Delay
	local IgnoreWalls
	local Switch
	local Notify
	local Detonate

	local TrapperFolder: Folder = ReplicatedStorage.TS.games.bedwars.kit.kits.trapper
	local Constants = require(TrapperFolder["trapper-constants"])
	local TrapperUtil = require(TrapperFolder["trapper-util"])
	local TrapState = require(TrapperFolder["snap-trap-state"]).SnapTrapState
	local Balance = Constants.TrapperBalance
	local TrapNames: {[string]: string} = {Snap = "snap_trap", Venom = "venom_trap", Explosive = "explosive_trap"}
	local Placed: {[Vector3]: number} = {}
	local NextThrow: number = 0
	local NextSwitch: number = 0
	local NextDetonate: number = 0
	local BedCount: number = 0
	local Session: number = 0
	local RayFilter: {Instance} = {}
	local SightParams: RaycastParams = RaycastParams.new()
	SightParams.FilterType = Enum.RaycastFilterType.Exclude

	local function UpdateFilter()
		local Filter: {Instance} = {Camera, Entity.character.Character}
		for _, v: any in Entity.List do
			table.insert(Filter, v.Character)
		end
		for _, v: Instance in CollectionService:GetTagged("DontBlockAbilityRaycast") do
			table.insert(Filter, v)
		end
		RayFilter = Filter
	end

	local function Raycast(Origin: Vector3, Direction: Vector3): RaycastResult?
		SightParams.FilterDescendantsInstances = RayFilter
		return bedwars.QueryUtil:raycast(Origin, Direction, SightParams)
	end

	local function HasStock(Item: string): boolean
		local Meta = Constants.TrapperTrapMeta[Item]
		return Meta ~= nil and bedwars.TrapperController:canUseAbilities() and TrapperUtil.getTrapCount(LocalPlayer, Item) > 0 and TrapperUtil.getPlacedTrapCount(LocalPlayer, Item) < Meta.maxPlaced
	end

	local function GetTrap(EnemyMode: boolean): string?
		local Wanted: string? = TrapNames[TrapType.Value]
		if Wanted then
			return HasStock(Wanted) and Wanted or nil
		end

		if EnemyMode then
			local Selected: string = TrapperUtil.getSelectedTrap(LocalPlayer)
			if HasStock(Selected) then
				return Selected
			end
			for _, v: string in Constants.TrapperTraps do
				if HasStock(v) then
					return v
				end
			end
		else
			for _, v: string in Traps.ListEnabled do
				if TrapperUtil.isTrapperTrap(v) and HasStock(v) or not TrapperUtil.isTrapperTrap(v) and GetItem(v) then
					return v
				end
			end
		end
		return nil
	end

	local function GetGround(Position: Vector3): Vector3?
		local Hit: RaycastResult? = Raycast(Position + Vector3.new(0, 3, 0), Vector3.new(0, -24, 0))
		if Hit and Hit.Normal.Y > 0.99 then
			return RoundPosition(Hit.Position + Vector3.new(0, 0.15, 0))
		end
		return nil
	end

	local function IsValid(Position: Vector3, Item: string): boolean
		if tick() < (Placed[Position] or 0) or GetPlacedBlock(Position) then
			return false
		end

		local Origin: Vector3 = Entity.character.RootPart.Position + Vector3.new(0, 1, 0)
		if (Position - Origin).Magnitude > math.min(PlaceRange.Value, Balance.ThrowRange) then
			return false
		end

		if TrapperUtil.isTrapperTrap(Item) then
			return TrapperUtil.canThrowTrap(Origin, Position, Raycast, Vector3.yAxis)
		end
		return GetPlacedBlock(Position - Vector3.new(0, 3, 0)) ~= nil and CanPlace()
	end

	local function PlaceTrap(Position: Vector3, Item: string): boolean
		if not IsValid(Position, Item) then
			return false
		end

		if TrapperUtil.isTrapperTrap(Item) then
			if not HasStock(Item) or bedwars.TrapperController.currentAim then
				return false
			end

			if TrapperUtil.getSelectedTrap(LocalPlayer) ~= Item then
				if tick() >= NextSwitch and bedwars.AbilityController:canUseAbility("trapper_switch", {disableBlockedAbilityAlert = true}) then
					NextSwitch = tick() + math.max(Balance.SwitchCooldown, 0.25)
					bedwars.AbilityController:useAbility("trapper_switch", nil, {trapType = Item})
				end
				return false
			end

			local Controller = bedwars.TrapperController
			local Aim = {
				character = LocalPlayer.Character,
				trapType = Item,
				source = "binding",
				released = true,
				payload = {trapType = Item, target = Position, normal = Vector3.yAxis}
			}
			Controller.currentAim = Aim
			local Success, Fired = pcall(function(): boolean
				if not bedwars.AbilityController:canUseAbility("trapper_throw", {disableBlockedAbilityAlert = true}) then
					return false
				end
				bedwars.AbilityController:useAbility("trapper_throw", nil, Aim.payload)
				return true
			end)
			if Controller.currentAim == Aim then
				Controller:cancelAim()
			end
			if not Success then
				error(Fired)
			end
			if not Fired then
				return false
			end
		else
			local Previous: number? = Switch.Enabled and Store.hand.tool and GetHotbar(Store.hand.tool) or nil
			bedwars.placeBlock(Position, Item)
			if Previous then
				HotbarSwitch(Previous)
			end
		end

		Placed[Position] = tick() + 2
		if Notify.Enabled then
			SendNotification("AutoTrap", `Placed {Item}`, 3)
		end
		return true
	end

	local function GetBed(): BasePart?
		local Own: string = `Team{LocalPlayer:GetAttribute("Team") or -1}NoBreak`
		local Closest, ClosestDistance = nil, Range.Value
		for _, v: BasePart in CollectionService:GetTagged("bed") do
			local Mine: boolean = v:GetAttribute(Own) and true or false
			if Mine ~= (Target.Value == "Your bed") then
				continue
			end

			local Distance: number = (Entity.character.RootPart.Position - v.Position).Magnitude
			if Distance < ClosestDistance then
				Closest, ClosestDistance = v, Distance
			end
		end
		return Closest
	end

	local function TrapBed(Item: string): boolean
		local Bed: BasePart? = GetBed()
		if not Bed then
			return false
		end

		local Step: number = Radius.Value * 3
		for X: number = -Step, Step, 3 do
			for Z: number = -Step, Step, 3 do
				if math.abs(X) ~= Step and math.abs(Z) ~= Step then
					continue
				end

				local Position: Vector3? = GetGround(Bed.Position + Vector3.new(X, 0, Z))
				if Position and PlaceTrap(Position, Item) then
					return true
				end
			end
		end
		return false
	end

	local function GetEnemies(): {any}
		return Entity.AllPosition({
			Range = Detonate.Enabled and TrapperUtil.getArmedTrapCount(LocalPlayer, "explosive_trap") > 0 and math.huge or PlaceRange.Value + 15,
			Part = "RootPart",
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Wallcheck = (IgnoreWalls.Enabled or Targets.Walls.Enabled) and true or nil,
			Sort = SortMethods.Distance
		})
	end

	local function TrapEnemies(Item: string, Enemies: {any}): boolean
		local Origin: Vector3 = Entity.character.RootPart.Position + Vector3.new(0, 1, 0)
		for _, v: any in Enemies do
			local Position: Vector3 = v.RootPart.Position
			local Velocity: Vector3 = v.RootPart.AssemblyLinearVelocity * Vector3.new(1, 0, 1)
			local Duration: number = TrapperUtil.trapThrowDuration(Origin, Position) + Balance.SettleTime + Constants.TrapperTrapMeta[Item].setupTime + (Store.ping.total or 0)
			local Lead: Vector3 = Velocity * Duration
			if Lead.Magnitude > 18 then
				Lead = Lead.Unit * 18
			end

			for _, Factor: number in {1, 0.5, 0} do
				local Ground: Vector3? = GetGround(Position + Lead * Factor - Vector3.new(0, v.HipHeight - 1.5, 0))
				if Ground and PlaceTrap(Ground, Item) then
					return true
				end
			end
		end
		return false
	end

	local function DetonateTraps(PlacedTraps: {BasePart}, Enemies: {any})
		if not Detonate.Enabled or tick() < NextDetonate or TrapperUtil.getArmedTrapCount(LocalPlayer, "explosive_trap") == 0 or not bedwars.TrapperController:canUseAbilities() or not bedwars.AbilityController:canUseAbility("trapper_detonate", {disableBlockedAbilityAlert = true}) then
			return
		end

		for _, v: BasePart in PlacedTraps do
			if v.Name ~= "explosive_trap" or v:GetAttribute("PlacedByUserId") ~= LocalPlayer.UserId or v:GetAttribute("SnapTrapState") ~= TrapState.ACTIVE then
				continue
			end

			local Normal: Vector3 = v:GetAttribute("TrapperSurfaceNormal") or Vector3.yAxis
			local Center: Vector3 = TrapperUtil.trapSurfacePosition(v.Position, Normal)
			for _, Ent: any in Enemies do
				local Predicted: Vector3 = Ent.RootPart.Position + Ent.RootPart.AssemblyLinearVelocity * Balance.ExplosionDelay
				if (Ent.RootPart.Position - Center).Magnitude <= Balance.ExplosionRadius and (Predicted - Center).Magnitude <= Balance.ExplosionRadius then
					NextDetonate = tick() + math.max(Balance.DetonateCooldown, Balance.ExplosionDelay)
					bedwars.AbilityController:useAbility("trapper_detonate")
					return
				end
			end
		end
	end

	AutoTrap = kits:CreateModule({
		Name = "AutoTrap",
		Function = function(Callback: boolean)
			Session += 1
			if Callback then
				local CurrentSession: number = Session
				table.clear(Placed)
				NextThrow, NextSwitch, NextDetonate, BedCount = 0, 0, 0, 0
				local PlacedTraps: {BasePart} = Collection("trapper_trap", AutoTrap)

				repeat
					if Entity.isAlive then
						local Enemies: {any} = GetEnemies()
						DetonateTraps(PlacedTraps, Enemies)
						if tick() >= NextThrow then
							local EnemyMode: boolean = Mode.Value == "Enemies"
							local Item: string? = GetTrap(EnemyMode)
							if Item then
								UpdateFilter()
								local Success: boolean = EnemyMode and TrapEnemies(Item, Enemies) or not EnemyMode and TrapBed(Item)
								if Success then
									BedCount = EnemyMode and 0 or BedCount + 1
									local Pause: boolean = EnemyMode or BedCount >= Amount.Value
									NextThrow = tick() + math.max(Balance.ThrowCooldown, Pause and Delay.Value or 0)
									if Pause then
										BedCount = 0
									end
								end
							end
						end
					end

					for Position: Vector3, Expiry: number in Placed do
						if tick() >= Expiry then
							Placed[Position] = nil
						end
					end
					task.wait(0.1)
				until not AutoTrap.Enabled or CurrentSession ~= Session
			end
		end,
		Tooltip = 'Throws traps at enemies or around a bed and detonates explosives'
	})

	Mode = AutoTrap:CreateDropdown({
		Name = "Mode",
		List = {"Bed ring", "Enemies"},
		Function = function(Val: string)
			if Traps then
				local EnemyMode: boolean = Val == "Enemies"
				Target.Object.Visible = not EnemyMode
				Radius.Object.Visible = not EnemyMode
				Range.Object.Visible = not EnemyMode
				Amount.Object.Visible = not EnemyMode
				Traps.Object.Visible = not EnemyMode
				IgnoreWalls.Object.Visible = EnemyMode
			end
			BedCount = 0
		end,
		Tooltip = 'Bed ring - surrounds a bed\nEnemies - throws ahead of nearby targets'
	})
	Targets = AutoTrap:CreateTargets({Players = true})
	TrapType = AutoTrap:CreateDropdown({
		Name = "Trap type",
		List = {"Auto", "Snap", "Venom", "Explosive"},
		Tooltip = 'Which trap to use'
	})
	Target = AutoTrap:CreateDropdown({
		Name = "Target",
		List = {"Your bed", "Enemy bed"}
	})
	Radius = AutoTrap:CreateSlider({
		Name = "Radius",
		Min = 1,
		Max = 5,
		Default = 2,
		Suffix = "blocks"
	})
	Range = AutoTrap:CreateSlider({
		Name = "Range",
		Min = 4,
		Max = 60,
		Default = 20,
		Suffix = "studs",
		Tooltip = "How close the bed has to be before placing"
	})
	Amount = AutoTrap:CreateSlider({
		Name = "Amount",
		Min = 1,
		Max = 8,
		Default = 3,
		Suffix = "traps",
		Tooltip = 'Traps to throw at a time'
	})
	PlaceRange = AutoTrap:CreateSlider({
		Name = "Place Range",
		Min = 1,
		Max = 45,
		Default = 30,
		Suffix = "studs",
		Tooltip = 'How far it can throw'
	})
	Delay = AutoTrap:CreateSlider({
		Name = "Delay",
		Min = 0.35,
		Max = 10,
		Default = 0.5,
		Decimal = 100,
		Suffix = "seconds",
		Tooltip = 'Time between throws'
	})
	IgnoreWalls = AutoTrap:CreateToggle({
		Name = "Ignore behind walls",
		Visible = false,
		Tooltip = 'Skips enemies you cannot see'
	})
	Detonate = AutoTrap:CreateToggle({
		Name = "Auto detonate",
		Default = true,
		Tooltip = 'Detonates your explosives when an enemy is in the blast'
	})
	Switch = AutoTrap:CreateToggle({
		Name = "Switch back",
		Default = true,
		Tooltip = 'Switches back to your last item afterwards'
	})
	Notify = AutoTrap:CreateToggle({Name = "Notify"})
	Traps = AutoTrap:CreateTextList({
		Name = "Traps",
		Default = {"snap_trap", "venom_trap", "explosive_trap", "invisible_landmine", "spike_trap", "tesla_trap", "grave_trap", "lucky_block_trap"},
		Darker = true,
		Placeholder = "item",
		Tooltip = 'Traps to use, in order'
	})
end)

-- ===== Kits/AutoUma.lua =====
run(function()
	local AutoUma
	local Range
	local Limit
	local Animation
	local AutoSummon
	local HealSpirit
	local AttackSpirit
	local TargetItemDrops
	local Diamond
	local Emerald

	local function getAttackData()
		if Limit.Enabled then
			local tool = (store.hand.tool and store.hand.tool.Name == 'spirit_staff') and store.hand.tool or nil
			return tool, tool and getHotbar(tool) or nil
		end
		for i, v in store.inventory.inventory.items do
			if v.itemType == 'spirit_staff' and v.tool then
				switchItem(v.tool, 0)
				return v.tool, getHotbar(v.tool)
			end
		end
		return
	end

	local function getDrops(localPosition, ItemDrops)
		local drop, lastmag = nil, Range.Value + 1
		for i, v in ItemDrops do
			if v.Name == 'emerald' and Emerald.Enabled or v.Name == 'diamond' and Diamond.Enabled then
				local magnitude = (localPosition - v.Position).Magnitude
				if magnitude <= lastmag and not entitylib.Wallcheck(localPosition, v.Position, {gameCamera, lplr.Character, v}) then
					drop, lastmag = v, magnitude
				end
			end
		end
		return drop
	end

	AutoUma = kits:CreateModule({
		Name = 'AutoUma',
		Function = function(call)
			if call then
				local items = collection('ItemDrop', AutoUma)
				repeat
					local staff = getAttackData()
					if staff then
						if TargetItemDrops.Enabled then
							local attackSpirits = (lplr:GetAttribute('ReadySummonedAttackSpirits') or 0)
							local healSpirits = (lplr:GetAttribute('ReadySummonedHealSpirits') or 0)

							if AutoSummon.Enabled then
								if AttackSpirit.Enabled and attackSpirits < 1 and getItem('summon_stone') then
									bedwars.AbilityController:useAbility('summon_attack_spirit')
								end

								if HealSpirit.Enabled and healSpirits < 1 and getItem('summon_stone') then
									bedwars.AbilityController:useAbility('summon_heal_spirit')
								end
							end

							if (healSpirits + attackSpirits) > 0 then
								local localPosition = entitylib.character.RootPart.Position
								local drop = getDrops(localPosition, items)

								if drop then
									local shootpos = localPosition + Vector3.new(0, 2, 0)
									local dir = CFrame.lookAt(localPosition, drop.Position + Vector3.new(0, (localPosition - drop.Position).Magnitude / 5, 0)).LookVector * 100

									bedwars.Handler:Get('ProjectileFire').Remote.instance:InvokeServer(
										staff,
										nil,
										attackSpirits > 0 and 'attack_spirit' or 'heal_spirit',
										shootpos,
										localPosition,
										dir,
										httpService:GenerateGUID(),
										{
											drawDurationSeconds = 1,
											shotId = httpService:GenerateGUID(false),
										},
										workspace:GetServerTimeNow() - 0.045
									)

									if Animation.Enabled then
										bedwars.GameAnimationUtil:playAnimation(lplr.Character, bedwars.AnimationType.WIZARD_BALL_CAST)
										bedwars.AudioManager:playAudio(bedwars.SoundList.SPIRIT_SUMMONER_CHANGE_AFFINITY, {})
									end

									task.wait(1.5)
								end
							end
						end
					end
					task.wait(0.1)
				until not AutoUma.Enabled
			end
		end,
		Tooltip = 'Throws spirits at item drops and enemies'
	})
	Range = AutoUma:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 80,
		Default = 50,
		Decimal = 5,
		Suffix = function(val)
			return val >= 2 and 'studs' or 'stud'
		end
	})
	Animation = AutoUma:CreateToggle({
		Name = 'Animation',
		Default = true
	})
	Limit = AutoUma:CreateToggle({
		Name = 'Limit to item',
		Default = true
	})
	AutoSummon = AutoUma:CreateGroup({
		Name = 'Auto Summon',
		Function = function(call)
			if AttackSpirit then
			end
		end,
		Tooltip = 'Summons spirits for you'
	})
	local Spirits = AutoSummon:CreateMultiDropdown({
		Name = 'Spirits',
		List = {'Heal', 'Attack'},
		Default = {'Heal', 'Attack'},
		Tooltip = 'Which spirits it summons'
	})
	local function flag(option, name)
		return setmetatable({}, {__index = function(_, key)
			if key == 'Enabled' then
				return option:Has(name)
			end
		end})
	end
	HealSpirit, AttackSpirit = flag(Spirits, 'Heal'), flag(Spirits, 'Attack')
	TargetItemDrops = AutoUma:CreateGroup({
		Name = 'Target item drops',
		Default = true,
		Function = function(call)
			if Emerald then
			end
		end
	})
	local Drops = TargetItemDrops:CreateMultiDropdown({
		Name = 'Drops',
		List = {'Emerald', 'Diamond'},
		Default = {'Emerald', 'Diamond'},
		Tooltip = 'Which item drops the spirits go for'
	})
	Emerald, Diamond = flag(Drops, 'Emerald'), flag(Drops, 'Diamond')
end)

-- ===== Kits/AutoUmbra.lua =====
run(function()
	local AutoUmbra
	local Delay

	AutoUmbra = vape.Categories.Kits:CreateModule({
		Name = 'AutoUmbra',
		Function = function(callback)
			if callback then
				repeat task.wait() until Delay
				task.spawn(function()
					local notifApp = lplr.PlayerGui:WaitForChild('NotificationApp', 10)
					if not notifApp then return end
					AutoUmbra:Clean(notifApp.DescendantAdded:Connect(function(desc)
						if not AutoUmbra.Enabled then return end
						if desc:IsA("TextLabel") then
							local txt = string.lower(desc.Text)
							if string.find(txt, "teleport") then
								task.spawn(function()
									if Delay.Value > 0 then task.wait(Delay.Value) end
									for _ = 1, 10 do
										if not AutoUmbra.Enabled then break end
										if bedwars.AbilityController:canUseAbility('HATTER_TELEPORT') then
											bedwars.AbilityController:useAbility('HATTER_TELEPORT')
											break
										end
										task.wait(0.05)
									end
								end)
							end
						end
					end))
				end)
			end
		end,
		Tooltip = 'auto teleports for umbra when the game says so'
	})

	Delay = AutoUmbra:CreateSlider({
		Name = 'Delay',
		Min = 0,
		Max = 1,
		Default = 0.05,
		Decimal = 100,
		Suffix = 's'
	})
end)

-- ===== Kits/AutoVanessa.lua =====
run(function()
	local old, overcharge

	kits:CreateModule({
		Name = 'AutoVanessa',
		Function = function(callback)
			if callback then
				old = bedwars.TripleShotProjectileController.getChargeTime
				overcharge = bedwars.TripleShotProjectileController.overchargeStartTime
				bedwars.TripleShotProjectileController.getChargeTime = function()
					return 0
				end
				bedwars.TripleShotProjectileController.overchargeStartTime = tick()
			else
				bedwars.TripleShotProjectileController.getChargeTime = old
				bedwars.TripleShotProjectileController.overchargeStartTime = overcharge
			end
		end,
		Tooltip = 'Instantly charges your bow and enables triple shot'
	})
end)

-- ===== Kits/AutoVoidHunter.lua =====
run(function()

	local util = vape.Libraries.bedwarsutil
	local AutoVoidHunter
	local Range
	local Detonate

	AutoVoidHunter = kits:CreateModule({
		Name = 'AutoVoidHunter',
		Function = function(callback)
			if callback then
				repeat
					if entitylib.isAlive and store.equippedKit == 'void_hunter' then
						if Detonate.Enabled and bedwars.AbilityController:canUseAbility('void_hunter_detonate', {disableBlockedAbilityAlert = true}) then
							bedwars.AbilityController:useAbility('void_hunter_detonate')
						elseif bedwars.AbilityController:canUseAbility('void_hunter_mark', {disableBlockedAbilityAlert = true}) then
							local target = entitylib.EntityPosition({
								Origin = entitylib.character.RootPart.Position,
								Range = Range.Value,
								Part = 'RootPart',
								Players = true,
								Wallcheck = true
							})

							if target then
								bedwars.AbilityController:useAbility('void_hunter_mark')
							end
						end
					end
					task.wait(0.1)
				until not AutoVoidHunter.Enabled
			end
		end,
		Tooltip = 'Marks nearby enemies and sets the mark off'
	})
	Range = AutoVoidHunter:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 100,
		Default = 50,
		Suffix = util.Studs
	})
	Detonate = AutoVoidHunter:CreateToggle({
		Name = 'Auto detonate',
		Default = true,
		Tooltip = 'Sets the mark off'
	})
end)

-- ===== Kits/AutoVoidKnight.lua =====
run(function()

	local util = vape.Libraries.bedwarsutil
	local AutoVoidKnight
	local Iron
	local Emeralds
	local Keep
	local Ascend
	local Range

	local function feed(itemType, ability)
		local item = getItem(itemType)
		if item and item.amount > Keep.Value and bedwars.AbilityController:canUseAbility(ability, {disableBlockedAbilityAlert = true}) then
			bedwars.AbilityController:useAbility(ability)
		end
	end

	AutoVoidKnight = kits:CreateModule({
		Name = 'AutoVoidKnight',
		Function = function(callback)
			if callback then
				repeat
					if entitylib.isAlive and store.equippedKit == 'void_knight' then
						if Iron.Enabled then
							feed('iron', 'void_knight_consume_iron')
						end

						if Emeralds.Enabled then
							feed('emerald', 'void_knight_consume_emerald')
						end

						if Ascend.Enabled and bedwars.AbilityController:canUseAbility('void_knight_ascend', {disableBlockedAbilityAlert = true}) then
							local near = entitylib.EntityPosition({
								Origin = entitylib.character.RootPart.Position,
