	local InfiniteKrystal
	local Momentum
	local Mode
	local Freeze
	local Old
	local bound = false
	local driving = false

	local function release()
		if not driving then return end
		driving = false
		pcall(function()
			if store.equippedKit == 'glacial_skater' then
				bedwars.GlacialSkaterController:updateMomentum(0, 'newValue')
			else
				bedwars.SprintController:getMovementStatusModifier():updateModifiers()
			end
		end)
	end

	local function stop()
		if Old then
			bedwars.GlacialSkaterController.updateMomentum = Old
			Old = nil
		end
		if bound then
			bound = false
			runService:UnbindFromRenderStep('InfiniteKrystalMovement')
			release()
		end
	end

	local function start()
		if not Momentum.Enabled then return end
		if Mode.Value == 'Method 2' then
			local last = 0
			bound = true
			runService:BindToRenderStep('InfiniteKrystalMovement', Enum.RenderPriority.Character.Value + 2, function()
				if store.equippedKit ~= 'glacial_skater' then
					release()
					return
				end
				local now = tick()
				if now - last < 0.016 then return end
				last = now
				local controller = bedwars.GlacialSkaterController
				if controller then
					driving = true
					pcall(controller.updateMomentum, controller, 100, 'newValue')
				end
			end)
		else
			Old = bedwars.GlacialSkaterController.updateMomentum
			bedwars.GlacialSkaterController.updateMomentum = function(self, ...)
				self.momentum = 1000
				self.lastMomentumReport = workspace:GetServerTimeNow()
				return Old(self, ...)
			end
		end
	end

	local function getBed()
		local localPosition = entitylib.character.RootPart.Position
		for _, v in collectionService:GetTagged('bed') do
			if (localPosition - v.Position).Magnitude <= 22 and not v:GetAttribute(`Team{lplr:GetAttribute('Team') or -1}NoBreak`) then
				return v
			end
		end
	end

	local function defended(bed)
		for _, v in workspace:GetPartBoundsInRadius(bed.Position, 20) do
			if v ~= bed and v:GetAttribute('PlacedByUserId') then
				return true
			end
		end
		return false
	end

	InfiniteKrystal = vape.Categories.Kits:CreateModule({
		Name = 'InfiniteKrystal',
		Category = 'Ability',
		Function = function(callback)
			stop()
			if callback then
				start()
				repeat
					if Freeze.Enabled and entitylib.isAlive and store.equippedKit == 'glacial_skater' and bedwars.AbilityController:canUseAbility('skating_freeze', {disableBlockedAbilityAlert = true}) then
						local bed = getBed()
						if bed and defended(bed) then
							bedwars.AbilityController:useAbility('skating_freeze')
						end
					end
					task.wait(0.1)
				until not InfiniteKrystal.Enabled
			end
		end,
		Tooltip = 'Never run out of momentum'
	})
	Momentum = InfiniteKrystal:CreateGroup({
		Name = 'Infinite momentum',
		Default = true,
		Function = function(callback)
			if InfiniteKrystal.Enabled then
				stop()
				start()
			end
		end
	})
	Mode = Momentum:CreateDropdown({
		Name = 'Mode',
		List = {'Method 1', 'Method 2'},
		Darker = true,
		Function = function()
			if InfiniteKrystal.Enabled then
				stop()
				start()
			end
		end,
		Tooltip = 'Which way of keeping momentum full to use'
	})
	Freeze = InfiniteKrystal:CreateToggle({
		Name = 'Freeze bed defense',
		Default = false,
		Tooltip = 'Freezes enemy bed defenses when you are next to them'
	})
end)

-- ===== Kits/InfiniteSigrid.lua =====
run(function()
	local Entity = entitylib
	local LocalPlayer = lplr
	local Store = store
	local InfiniteSigrid
	local Mounted
	local Summon
	local Combat
	local Charge
	local Targets
	local Range
	local ChargeRange
	local NextSummon, NextCharge = 0, 0
	local mount

	local function UpdateVisibility()
		if ChargeRange then
			Combat.Object.Visible = Summon.Enabled
			Range.Object.Visible = Summon.Enabled and Combat.Enabled
			ChargeRange.Object.Visible = Charge.Enabled
			Targets.Object.Visible = (Summon.Enabled and Combat.Enabled) or Charge.Enabled
		end
	end

	local function matchRunning()
		return Store.matchState ~= 0
	end

	InfiniteSigrid = kits:CreateModule({
		Name = "InfiniteSigrid",
		Category = "Ability",
		Function = function(Callback: boolean)
			if Callback then
				NextSummon, NextCharge = 0, 0

				repeat
					if Entity.isAlive and Store.equippedKit == "elk_master" then
						if Mounted.Enabled and matchRunning() then
							if not mount then
								pcall(function() mount = bedwars.Client:Get("ElkKitMounted") end)
							end
							if mount then pcall(mount.SendToServer, mount) end
						end

						if Summon.Enabled and tick() >= NextSummon and bedwars.AbilityController:canUseAbility("elk_summon", {disableBlockedAbilityAlert = true}) then
							local Wanted: boolean = not Combat.Enabled

							if not Wanted then
								Wanted = #Entity.AllPosition({
									Range = Range.Value,
									Part = "RootPart",
									Players = Targets.Players.Enabled,
									NPCs = Targets.NPCs.Enabled
								}) > 0
							end

							if Wanted then
								NextSummon = tick() + 1
								bedwars.AbilityController:useAbility("elk_summon")
							end
						end

						if Charge.Enabled and LocalPlayer.Character:FindFirstChild("elk") and tick() >= NextCharge and bedwars.AbilityController:canUseAbility("elk_antler_uppercut", {disableBlockedAbilityAlert = true}) then
							local Ent = Entity.EntityPosition({
								Range = ChargeRange.Value,
								Wallcheck = Targets.Walls.Enabled or nil,
								Part = "RootPart",
								Players = Targets.Players.Enabled,
								NPCs = Targets.NPCs.Enabled
							})

							if Ent then
								local Root: BasePart = Entity.character.RootPart
								local Flat: Vector3 = (Ent.RootPart.Position - Root.Position) * Vector3.new(1, 0, 1)
								if Flat.Magnitude > 0.001 then
									Root.CFrame = CFrame.lookAlong(Root.Position, Flat)
								end
								NextCharge = tick() + 1
								bedwars.AbilityController:useAbility("elk_antler_uppercut")
							end
						end
					end
					task.wait(0.1)
				until not InfiniteSigrid.Enabled
			end
		end,
		Tooltip = 'Keeps the elk summoned and can charge nearby enemies'
	})

	Targets = InfiniteSigrid:CreateTargets({
		Players = true,
		NPCs = true,
		Visible = false
	})
	Mounted = InfiniteSigrid:CreateToggle({
		Name = "Keep mounted",
		Default = true,
		Tooltip = 'Keeps you mounted on the elk'
	})
	Summon = InfiniteSigrid:CreateToggle({
		Name = "Auto summon",
		Default = true,
		Function = UpdateVisibility,
		Tooltip = 'Summons the elk when the ability is ready'
	})
	Combat = InfiniteSigrid:CreateToggle({
		Name = "Only in combat",
		Darker = true,
		Function = UpdateVisibility,
		Tooltip = 'Only summons with someone nearby'
	})
	Range = InfiniteSigrid:CreateSlider({
		Name = "Range",
		Min = 1,
		Max = 80,
		Default = 40,
		Darker = true,
		Visible = false,
		Suffix = function(Val: number)
			return Val <= 1 and "stud" or "studs"
		end
	})
	Charge = InfiniteSigrid:CreateToggle({
		Name = "Charge attack",
		Function = UpdateVisibility,
		Tooltip = 'Charges at enemies in range while riding the elk'
	})
	ChargeRange = InfiniteSigrid:CreateSlider({
		Name = "Charge range",
		Min = 1,
		Max = 40,
		Default = 20,
		Darker = true,
		Visible = false,
		Suffix = function(Val: number)
			return Val <= 1 and "stud" or "studs"
		end
	})
end)

-- ===== Kits/JadeHammerExtender.lua =====
run(function()
    local JadeExtender
    local Multiplier
    
    local old
    
    JadeExtender = vape.Categories.Kits:CreateModule({
        Name = 'JadeHammerExtender',
        Function = function(callback)
            if callback then
                old = bedwars.JadeHammerController.useJadeHammer
                bedwars.JadeHammerController.useJadeHammer = function(self)
                    local jumped = bedwars.AbilityController:canUseAbility('jade_hammer_jump', {disableBlockedAbilityAlert = true})
                    local call = old(self)
    
                    if jumped and store.equippedKit == 'jade' and entitylib.isAlive then
                        local root = entitylib.character.RootPart
                        -- Applies horizontal momentum in the direction you are facing plus an upward boost scaled by Multiplier
                        local horizontalLook = root.CFrame.LookVector * Vector3.new(1, 0, 1)
                        local impulseVector = (horizontalLook * 70 + Vector3.new(0, 20.5, 0)) * root.AssemblyMass * (Multiplier.Value - 1)
                        
                        root:ApplyImpulse(impulseVector)
                    end
                    return call
                end
            else
                bedwars.JadeHammerController.useJadeHammer = old
            end
        end,
        Tooltip = 'Extends how far the Jade Hammer jump launches you horizontally and vertically'
    })
    Multiplier = JadeExtender:CreateSlider({
        Name = 'Multiplier',
        Min = 1,
        Max = 5,
        Default = 2,
        Decimal = 10,
        Suffix = 'x'
    })
end)

-- ===== Kits/JadeInstantKill.lua =====
run(function()
	local Main = vape.Libraries.mergedModule(kits, {
		Name = 'JadeInstantKill',
		Category = 'Ability',
		Tooltip = 'Launches you above a target and slams just before landing'
	})

run(function()
	local AutoJade
	local Targets
	local Range
	local Height
	local SlamMultiplier
	local Cooldown
	local Follow
	local lastUse = 0
	local MAX_SLAM_TIME = 4

	local function canUse()
		if not entitylib.isAlive then
			return false
		end
		if store.equippedKit ~= 'jade' then
			return false
		end
		if (store.matchState or 0) ~= 1 then
			return false
		end
		return bedwars.AbilityController:canUseAbility('jade_hammer_jump', {
			disableBlockedAbilityAlert = true,
		})
	end

	local function getTarget()
		if not entitylib.isAlive then
			return nil
		end
		return entitylib.EntityPosition({
			Origin = entitylib.character.RootPart.Position,
			Range = Range.Value,
			Part = 'RootPart',
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Wallcheck = Targets.Walls.Enabled or nil,
			Sort = sortmethods.Distance,
		})
	end

	local function followTarget(root, target)
		if not (Follow.Enabled and target and target.RootPart and target.RootPart.Parent) then return end
		local goal = target.RootPart.Position
		local position = root.Position
		root.CFrame = root.CFrame.Rotation + Vector3.new(goal.X, position.Y, goal.Z)
		local velocity = root.AssemblyLinearVelocity
		root.AssemblyLinearVelocity = Vector3.new(0, velocity.Y, 0)
	end

	local function grounded()
		local humanoid = entitylib.isAlive and entitylib.character.Humanoid
		return humanoid ~= nil and humanoid.FloorMaterial ~= Enum.Material.Air
	end

	local function execute(root, target)
		if tick() - lastUse < Cooldown.Value then
			return
		end
		if not canUse() then
			return
		end

		lastUse = tick()
		local start = root.CFrame

		root.CFrame = start + Vector3.new(0, Height.Value, 0)
		followTarget(root, target)
		local hold = tick() + 0.15
		repeat
			runService.Heartbeat:Wait()
			if not AutoJade.Enabled or not root.Parent then
				return
			end
			followTarget(root, target)
		until tick() >= hold

		bedwars.AbilityController:useAbility('jade_hammer_jump')

		local began = tick()
		local conn
		conn = runService.Heartbeat:Connect(function()
			local elapsed = tick() - began
			if not AutoJade.Enabled or not root.Parent or elapsed > MAX_SLAM_TIME or (elapsed > 0.2 and grounded()) then
				if conn then
					conn:Disconnect()
				end
				return
			end
			followTarget(root, target)
			if elapsed < 0.05 then return end
			local vel = root.AssemblyLinearVelocity
			if vel.Y < 0 then
				root.AssemblyLinearVelocity = Vector3.new(
					vel.X,
					vel.Y * SlamMultiplier.Value,
					vel.Z
				)
			end
		end)

		AutoJade:Clean(conn)
	end

	AutoJade = Main:Part({
		Label = 'Instant kill',
		Name = 'JadeInstantKill',
		Category = 'Ability',
		Function = function(callback)
			if not callback then
				return
			end

			AutoJade:Clean(runService.Heartbeat:Connect(function()
				if not AutoJade.Enabled then
					return
				end
				if not entitylib.isAlive then
					return
				end
				if not canUse() then
					return
				end

				local target = getTarget()
				if not target then
					return
				end

				local root = entitylib.character.RootPart
				if not root or not isnetworkowner(root) then
					return
				end

				execute(root, target)
			end))
		end,
		Tooltip = 'Launches you up for a big slam on landing',
	})

	Targets = AutoJade:CreateTargets({
		Players = true,
		NPCs = false,
	})
	Range = AutoJade:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 30,
		Default = 18,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end,
	})
	Height = AutoJade:CreateSlider({
		Name = 'Height',
		Min = 20,
		Max = 200,
		Default = 80,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end,
	})
	SlamMultiplier = AutoJade:CreateSlider({
		Name = 'Slam Multiplier',
		Min = 1,
		Max = 10,
		Default = 2.5,
		Decimal = 10,
		Suffix = 'x',
	})
	Follow = AutoJade:CreateToggle({
		Name = 'Follow target',
		Default = true,
		Tooltip = 'Keeps you above the target until you land',
	})
	Cooldown = AutoJade:CreateSlider({
		Name = 'Cooldown',
		Min = 0.5,
		Max = 5,
		Default = 1.5,
		Decimal = 10,
		Suffix = 's',
	})
end)

run(function()
	local v2 = httpService
	local v3 = playersService
	local v4 = replicatedStorage
	local v5 = runService
	local v6 = inputService
	local v7 = tweenService
	local v8 = collectionService
	local v9 = guiService
	local v10 = game:GetService('TeleportService')
	local obj = debug
	local currentCamera = gameCamera
	local localPlayer = lplr
	local entity = entitylib
	local getfontbounds = getfontsize
	local getvapeasset = getcustomasset

		local v12 = nil
		local v13 = nil
		local v14 = nil
		local v15 = nil
		local tbl3 = {}
		local v16 = nil
		local n = 0

		local function fn5(arg)
			if store.hand.tool ~= arg.tool then
				if v15.Enabled then
					hotbarSwitch(getHotbar(arg.tool))
				else
					switchItem(arg.tool, 0)
				end

				task.wait(tbl3.Value)
			end

			if v12.Enabled and entity.isAlive and bedwars.AbilityController:canUseAbility("jade_hammer_jump", { disableBlockedAbilityAlert = true }) then
				bedwars.JadeHammerController:useJadeHammer()
			end
		end

		v12 = Main:Part({
		Label = 'Auto slam',
			Name = "AutoJade",
			Function = function(arg)
				if arg then
					n = 0

					v12:Clean(v5.Heartbeat:Connect(function()
						if not entity.isAlive or store.equippedKit ~= "jade" or tick() < n or not bedwars.JadeHammerController then
							return
						end
						local rootPart = entity.character.RootPart
						if -v14.Value < rootPart.AssemblyLinearVelocity.Y then
							return
						end

						if not bedwars.AbilityController:canUseAbility("jade_hammer_jump", { disableBlockedAbilityAlert = true }) then
							return
						end
						local airRay = store.airRay
						if not workspace:Raycast(rootPart.Position, Vector3.new(0, -v13.Value, 0), airRay) then
							return
						end
						local hand

						if store.hand.tool and isJadeHammerName(store.hand.tool.Name) then
							hand = store.hand
						else
							hand = nil

							if not v16.Enabled then
								hand = nil

								for _, v17 in store.inventory.inventory.items, nil, nil do
									if isJadeHammerName(v17.itemType) then
										hand = v17
										break
									else
										hand = nil
									end
								end
							end
						end

						if not hand then
							return
						end
						local hammerCooldown = ((bedwars.JadeBalance and bedwars.JadeBalance.HAMMER_COOLDOWN) or 6)
						n = tick() + hammerCooldown
						task.spawn(fn5, hand)
					end))
				end
			end,
			Tooltip = "Slams the Jade hammer down right before you land",
		})

		v13 = v12:CreateSlider({
			Name = "Slam height",
			Min = 3,
			Max = 60,
			Default = 15,
			Suffix = function(arg)
				return arg <= 1 and "stud" or "studs"
			end,
			Tooltip = "Slams once the ground is this close beneath you",
		})

		v14 = v12:CreateSlider({
			Name = "Slam fall speed",
			Min = 0,
			Max = 100,
			Default = 10,
			Tooltip = "Only slams once you are dropping this fast",
		})

		v15 = v12:CreateGroup({
			Name = "Slam legit switch",
			Function = function(visible)
				if tbl3.Object then
				end
			end,
			Tooltip = 'Visibly switches items on your hotbar',
		})

		tbl3 = v15:CreateSlider({
			Name = "Slam switch delay",
			Min = 0,
			Max = 1,
			Decimal = 100,
			Default = 0.05,
			Darker = true,
			Suffix = "seconds",
		})

		v16 = v12:CreateToggle({ Name = "Slam limit to items", Tooltip = 'Only works while holding the item it uses' })
	end)

end)

-- ===== Kits/KitDisplay.lua =====
run(function()
	local v12 = nil
	local v13 = nil
	local RequestMatchHistory = bedwars.Handler:Get("RequestMatchHistory")
	local tbl3 = {}
	local tbl4 = {}

	local function fn6(arg)
		local userId = arg.UserId
		if tbl3[userId] then
			return tbl3[userId]
		end

		while tbl4[userId] do
			task.wait()
		end

		if tbl3[userId] then
			return tbl3[userId]
		end
		tbl4[userId] = true
		local CallServer = RequestMatchHistory:Fire("CallServer", tostring(arg.Name))
		local tbl5 = {}

		if type(CallServer) == "table" and type(CallServer.matchHistory) == "table" then
			table.sort(CallServer.matchHistory, function(arg2, arg3)
				return arg2.matchStartTime > arg3.matchStartTime
			end)

			for k, v14 in CallServer.matchHistory, nil, nil do
				if not (k > 8) then
					local players = v14.players or {}
					local str = "none"

					for _, v15 in players, nil, nil do
						if v15.playerInfo and v15.playerInfo.userId == userId then
							str = v15.bedwars and v15.bedwars.kit or "none"
							break
						end
					end

					table.insert(tbl5, str)
					continue
				end

				break
			end

			tbl3[userId] = tbl5
		end

		tbl4[userId] = nil
		return tbl5
	end

	local function fn7(parent, arg)
		local previousKits = parent:FindFirstChild("PreviousKits")

		if previousKits then
			previousKits:Destroy()
		end

		if not v13.Enabled then
			return
		end
		local frame = Instance.new("Frame")
		frame.Name = "PreviousKits"
		frame.AnchorPoint = Vector2.new(0.5, 0)
		frame.Position = UDim2.fromScale(0.5, 0.03)
		frame.Size = UDim2.fromScale(0.86, 0.24)
		frame.BackgroundColor3 = Color3.new()
		frame.BackgroundTransparency = 1
		frame.BorderSizePixel = 0
		frame.ClipsDescendants = true
		frame.ZIndex = 3
		frame.Parent = parent
		v12:Clean(frame)
		local uiCorner = Instance.new("UICorner")
		uiCorner.CornerRadius = UDim.new(0, 4)
		uiCorner.Parent = frame
		local uiPadding = Instance.new("UIPadding")
		uiPadding.PaddingLeft = UDim.new(0, 3)
		uiPadding.PaddingRight = UDim.new(0, 3)
		uiPadding.Parent = frame
		local uiListLayout = Instance.new("UIListLayout")
		uiListLayout.FillDirection = Enum.FillDirection.Horizontal
		uiListLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
		uiListLayout.VerticalAlignment = Enum.VerticalAlignment.Center
		uiListLayout.Padding = UDim.new(0, 2)
		uiListLayout.SortOrder = Enum.SortOrder.LayoutOrder
		uiListLayout.Parent = frame
		local v14 = fn6(arg)
		if not v12.Enabled or not v13.Enabled or not frame.Parent then
			return
		end

		if #v14 == 0 then
			frame:Destroy()
			return
		end
		frame.BackgroundTransparency = 1

		for k, v15 in v14, nil, nil do
			local none = bedwars.BedwarsKitMeta[v15] or bedwars.BedwarsKitMeta.none
			local imageLabel = Instance.new("ImageLabel")
			imageLabel.Name = ("Kit%*"):format(k)
			imageLabel.LayoutOrder = k
			imageLabel.Size = UDim2.fromScale(1, 1)
			imageLabel.SizeConstraint = Enum.SizeConstraint.RelativeYY
			imageLabel.BackgroundTransparency = 1
			imageLabel.Image = none.renderImage
			imageLabel.ScaleType = Enum.ScaleType.Fit
			imageLabel.ZIndex = 4
			imageLabel.Parent = frame
			local textLabel = Instance.new("TextLabel")
			textLabel.Name = "Order"
			textLabel.Position = UDim2.fromOffset(1, 1)
			textLabel.Size = UDim2.fromOffset(13, 13)
			textLabel.BackgroundColor3 = Color3.new()
			textLabel.BackgroundTransparency = 1
			textLabel.BorderSizePixel = 0
			textLabel.FontFace = uipallet.FontBold
			textLabel.Text = tostring(k)
			textLabel.TextColor3 = Color3.new(1, 1, 1)
			textLabel.TextSize = 9
			textLabel.ZIndex = 5
			textLabel.Parent = imageLabel
			local uiCorner2 = Instance.new("UICorner")
			uiCorner2.CornerRadius = UDim.new(0, 4)
			uiCorner2.Parent = textLabel
		end
	end

	local fn8 = nil

	fn8 = function(child)
		task.wait(0.3)
		if not v12.Enabled or not child.Parent then
			return
		end
		local playerName = child:FindFirstChild("PlayerName", true)
		if not playerName then
			return
		end
		local v14 = nil

		for _, v15 in playersService:GetPlayers() do
			local streamerModeController = bedwars.StreamerModeController and bedwars.StreamerModeController:getDisplayName(v15)
			local flag = v15.Name == playerName.Text or v15.DisplayName == playerName.Text
			local flag2

			if flag then
				flag2 = flag
			else
				local text = playerName.Text
				flag2 = v15:GetAttribute("DisguiseDisplayName") == text
			end

			flag2 = flag2 or streamerModeController == playerName.Text
			if flag2 then
				v14 = v15
				break
			end
		end

		if not v14 then
			return
		end
		local n1 = child:FindFirstChild("1")
		n1 = n1 and n1:FindFirstChild("MatchDraftPlayerCard")
		if not n1 then
			return
		end
		local kitImage = n1:FindFirstChild("KitImage")
		local none = bedwars.BedwarsKitMeta[v14:GetAttribute("PlayingAsKits")] or bedwars.BedwarsKitMeta.none

		if not kitImage then
			kitImage = Instance.new("ImageLabel")
			kitImage.BackgroundTransparency = 1
			kitImage.AnchorPoint = Vector2.new(1, 0.5)
			kitImage.Position = UDim2.fromScale(1.05, 0)
			kitImage.Name = "KitImage"
			kitImage.Size = UDim2.fromScale(1.5, 1.5)
			kitImage.ZIndex = 1
			kitImage.ImageTransparency = 0.4
			kitImage.SliceCenter = Rect.new(0, 0, 0, 0)
			kitImage.SliceScale = 1
			kitImage.ScaleType = Enum.ScaleType.Crop
			kitImage.Parent = n1
			v12:Clean(kitImage)
			local uiAspectRatioConstraint = Instance.new("UIAspectRatioConstraint")
			uiAspectRatioConstraint.Name = "1"
			uiAspectRatioConstraint.AspectRatio = 1
			uiAspectRatioConstraint.AspectType = Enum.AspectType.FitWithinMaxSize
			uiAspectRatioConstraint.DominantAxis = Enum.DominantAxis.Width
			uiAspectRatioConstraint.Parent = kitImage
		end

		kitImage.Image = none.renderImage
		kitImage.Position = UDim2.fromScale(1.05, 0)
		tweenService:Create(kitImage, TweenInfo.new(0.2, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out), { Position = UDim2.fromScale(1.05, 0.5) }):Play()
		task.spawn(fn7, n1, v14)

		local connection = v14:GetAttributeChangedSignal("PlayingAsKits"):Connect(function()
			if not v12.Enabled or not kitImage.Parent then
				return
			end
			none = bedwars.BedwarsKitMeta[v14:GetAttribute("PlayingAsKits")] or bedwars.BedwarsKitMeta.none
			kitImage.Image = none.renderImage
			kitImage.Position = UDim2.fromScale(1.05, 0)
			tweenService:Create(kitImage, TweenInfo.new(0.2, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out), { Position = UDim2.fromScale(1.05, 0.5) }):Play()
		end)

		v12:Clean(playerName:GetPropertyChangedSignal("Text"):Once(function()
			if connection then
				connection:Disconnect()
				connection = nil
			end

			fn8(child)
		end))

		v12:Clean(connection)
	end

	v12 = kits:CreateModule({
		Name = "KitDisplay",
		Category = "Visual",
		Function = function(arg)
			if arg then
				local matchDraftApp

				while true do
					matchDraftApp = lplr.PlayerGui:FindFirstChild("MatchDraftApp")
					matchDraftApp = matchDraftApp and matchDraftApp:FindFirstChild("DraftAppBackground")
					matchDraftApp = matchDraftApp and matchDraftApp:FindFirstChild("1")
					matchDraftApp = matchDraftApp and matchDraftApp:FindFirstChild("BodyContainer")

					if not matchDraftApp then
						task.wait(0.1)
					end

					if not (matchDraftApp or not v12.Enabled) then
						continue
					end
					break
				end

				local v14

				for i = 1, 2 do
					if v12.Enabled then
						local n = tick() + 10

						while true do
							local findFirstChild = matchDraftApp.FindFirstChild
							local str = ("Team%*Column"):format(i)
							v14 = findFirstChild(matchDraftApp, str)

							if not v14 then
								task.wait(0.1)
							end

							if not (v14 or not v12.Enabled or tick() >= n) then
								continue
							end
							break
						end

						if v14 then
							v12:Clean(v14.ChildAdded:Connect(fn8))

							for _, v15 in v14:GetChildren() do
								task.spawn(fn8, v15)
							end
						end

						continue
					end

					break
				end
			end
		end,
		Tooltip = 'Shows enemy kits in the match draft',
	})

	v13 = v12:CreateToggle({
		Name = "Show previous kits",
		Function = function()
			if v12.Enabled then
				v12:Toggle()
				v12:Toggle()
			end
		end,
		Default = true,
		Tooltip = 'Shows the kits each player recently used',
	})
end)

-- ===== Kits/KitESP.lua =====
run(function()
    local KitESP
    local Background
    local Color = {}
    local Reference = {}
    local kitGeneration = 0
    local Folder = Instance.new('Folder')
    Folder.Parent = vape.gui

    local ESPKits = {
	alchemist = {'alchemist_ingedients', 'wild_flower'},
	beekeeper = {'bee', 'bee'},
	bigman = {'treeOrb', 'natures_essence_1'},
	ghost_catcher = {'ghost', 'ghost_orb'},
	metal_detector = {'hidden-metal', 'iron'},
	sheep_herder = {'SheepModel', 'purple_hay_bale'},
	sorcerer = {'alchemy_crystal', 'wild_flower'},
	star_collector = {'stars', 'crit_star'},
    }

    local function Added(v, icon)
	local billboard = Instance.new('BillboardGui')
	billboard.Parent = Folder
	billboard.Name = icon
	billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
	billboard.Size = UDim2.fromOffset(36, 36)
	billboard.AlwaysOnTop = true
	billboard.ClipsDescendants = false
	billboard.Adornee = v
	local blur = addBlur(billboard)
	blur.Visible = Background.Enabled
	local image = Instance.new('ImageLabel')
	image.Size = UDim2.fromOffset(36, 36)
	image.Position = UDim2.fromScale(0.5, 0.5)
	image.AnchorPoint = Vector2.new(0.5, 0.5)
	image.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	image.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
	image.BorderSizePixel = 0
	image.Image = bedwars.getIcon({ itemType = icon }, true)
	image.Parent = billboard
	local uicorner = Instance.new('UICorner')
	uicorner.CornerRadius = UDim.new(0, 4)
	uicorner.Parent = image
	Reference[v] = billboard
    end

    local function addKit(kitName, tag, icon)
	KitESP:Clean(collectionService:GetInstanceAddedSignal(tag):Connect(function(v)
		if store.equippedKit == kitName and v.PrimaryPart then Added(v.PrimaryPart, icon) end
	end))
	KitESP:Clean(collectionService:GetInstanceRemovedSignal(tag):Connect(function(v)
		if v.PrimaryPart and Reference[v.PrimaryPart] then
			Reference[v.PrimaryPart]:Destroy()
			Reference[v.PrimaryPart] = nil
		end
	end))
    end
	local function refreshKit()
		Folder:ClearAllChildren()
		table.clear(Reference)
		local kit = ESPKits[store.equippedKit]
		if not kit then return end
		for _, object in collectionService:GetTagged(kit[1]) do if object.PrimaryPart then Added(object.PrimaryPart, kit[2]) end end
	end

    KitESP = kits:CreateModule({
	Name = 'KitESP',
	Category = 'Visual',
	Function = function(callback)
		kitGeneration += 1
		if callback then
			local generation = kitGeneration
			for kitName, kit in ESPKits do addKit(kitName, kit[1], kit[2]) end
			local activeKit = store.equippedKit
			refreshKit()
			
			
			task.spawn(function()
				while KitESP.Enabled and kitGeneration == generation do
					task.wait(0.25)
					if kitGeneration ~= generation then break end
					if store.equippedKit ~= activeKit then activeKit = store.equippedKit; refreshKit() end
				end
			end)
		else
			Folder:ClearAllChildren()
			table.clear(Reference)
		end
	end,
	Tooltip = 'Shows kit objects through walls'
    })
    Background = KitESP:CreateGroup({
	Name = 'Background',
	Function = function(callback)
		if Color and Color.Object then
		end
		for _, v in Reference do
			v.ImageLabel.BackgroundTransparency = 1 - (callback and Color.Opacity or 0)
			v.Blur.Visible = callback
		end
	end,
	Default = true,
    })
    Color = Background:CreateColorSlider({
	Name = 'Background Colour',
	DefaultValue = 0,
	DefaultOpacity = 0.5,
	Function = function(hue, sat, val, opacity)
		for _, v in Reference do
			v.ImageLabel.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
			v.ImageLabel.BackgroundTransparency = 1 - opacity
		end
	end,
	Darker = true,
    })
end)

-- ===== Kits/KitExtender.lua =====
run(function()
	local KitExtender
	local Kaida
	local KaidaRange
	local OldMethods = {}
	local SummonRange: number?
	
	local BOOST_WINDOW = 0.6
	local HORIZONTAL = Vector3.new(1, 0, 1)
	local VERTICAL = Vector3.yAxis

	local function amplify(multiplier, mask)
		if multiplier <= 1 or not entitylib.isAlive then return end
		local character = entitylib.character.Character
		local root = entitylib.character.RootPart
		if not character or not root then return end

		local function scale(vector)
			local along = vector * mask
			return vector - along + along * multiplier
		end

		local baseline = (root.AssemblyLinearVelocity * mask).Magnitude
		local handledConstraint, handledVelocity = false, false
		local connections = {}
		local finish = tick() + BOOST_WINDOW

		local function scaleConstraint(obj)
			task.defer(function()
				if not obj.Parent then return end
				if obj:IsA('BodyVelocity') then
					obj.Velocity = scale(obj.Velocity)
					handledConstraint = true
				elseif obj:IsA('LinearVelocity') then
					if obj.VelocityConstraintMode == Enum.VelocityConstraintMode.Vector then
						obj.VectorVelocity = scale(obj.VectorVelocity)
					elseif obj.VelocityConstraintMode == Enum.VelocityConstraintMode.Line then
						obj.LineVelocity *= multiplier
					else
						obj.PlaneVelocity *= multiplier
					end
					handledConstraint = true
				end
			end)
		end

		table.insert(connections, character.DescendantAdded:Connect(scaleConstraint))
		table.insert(connections, runService.Heartbeat:Connect(function()
			if tick() > finish or not root.Parent then
				for _, connection in connections do connection:Disconnect() end
				table.clear(connections)
				return
			end
			if handledConstraint or handledVelocity then return end
			local velocity = root.AssemblyLinearVelocity
			local speed = (velocity * mask).Magnitude
			if speed > baseline + 8 and (mask ~= VERTICAL or velocity.Y > 0) then
				handledVelocity = true
				root.AssemblyLinearVelocity = scale(velocity)
			end
		end))
	end

	local Boosts = {
	    {
	        Name = "Jade Hammer",
	        Kit = "jade",
	        Controller = "JadeHammerController",
	        Method = "useJadeHammer",
	        Tooltip = 'Extends how far the Jade Hammer launches you',
	        Hook = function(Entry, Old)
	            return function(self, ...)
	                local Jumped: boolean = bedwars.AbilityController:canUseAbility("jade_hammer_jump", {disableBlockedAbilityAlert = true})
	                if Entry.Toggle.Enabled and Jumped and store.equippedKit == "jade" then
	                    amplify(Entry.Multiplier.Value, VERTICAL)
	                end
	                return Old(self, ...)
	            end
	        end
	    },
	    {
	        Name = "Void Regent Dash",
	        Kit = "regent",
	        Controller = "VoidAxeController",
	        Method = "useVoidAxe",
	        Tooltip = "Extends how far the Void Regent axe dash launches you",
	        Hook = function(Entry, Old)
	            return function(self, ...)
	                local Dashed: boolean = bedwars.AbilityController:canUseAbility("void_axe_jump", {disableBlockedAbilityAlert = true})
	                if Entry.Toggle.Enabled and Dashed and store.equippedKit == "regent" then
	                    amplify(Entry.Multiplier.Value, HORIZONTAL)
	                end
	                return Old(self, ...)
	            end
	        end
	    },
	    {
	        Name = "Yamini Pounce",
	        Kit = "cat",
	        Controller = "CatController",
	        Method = "leap",
	        Tooltip = "Extends how far the Yamini pounce launches you",
	        Hook = function(Entry, Old)
	            return function(self, Character: Model?, ...)
	                if Entry.Toggle.Enabled and store.equippedKit == "cat" and (Character == nil or Character == lplr.Character) then
	                    amplify(Entry.Multiplier.Value, HORIZONTAL)
	                end
	                return Old(self, Character, ...)
	            end
	        end
	    },
	    {
	        Name = "Yamini Wall Kick",
	        Kit = "cat",
	        Controller = "CatController",
	        Method = "dismountWall",
	        Tooltip = "Extends how high dropping off a climbed wall throws you",
	        Hook = function(Entry, Old)
	            return function(self, ...)
	                if Entry.Toggle.Enabled and store.equippedKit == "cat" then
	                    amplify(Entry.Multiplier.Value, VERTICAL)
	                end
	                return Old(self, ...)
	            end
	        end
	    },
	    {
	        Name = "Yuzi Dash",
	        Kit = "dasher",
	        Controller = "DaoController",
	        Method = "dashForward",
	        Tooltip = "Extends how far the yuzi dash launches you",
	        Hook = function(Entry, Old)
	            return function(self, ...)
	                if Entry.Toggle.Enabled and store.equippedKit == "dasher" then
	                    amplify(Entry.Multiplier.Value, HORIZONTAL)
	                end
	                return Old(self, ...)
	            end
	        end
	    },
	    {
	        Name = "Xurot Wing Flap",
	        Kit = "void_dragon",
	        Controller = "VoidDragonController",
	        Method = "flapWings",
	        Tooltip = "Extends how high each wing flap throws you",
	        Hook = function(Entry, Old)
	            return function(self, ...)
	                if Entry.Toggle.Enabled and store.equippedKit == "void_dragon" then
	                    amplify(Entry.Multiplier.Value, VERTICAL)
	                end
	                return Old(self, ...)
	            end
	        end
	    }
	}
	
	KitExtender = vape.Categories.Kits:CreateModule({
	    Name = "KitExtender",
	    Category = "Ability",
	    Function = function(Callback: boolean)
	        if Callback then
	            for i: number, v: any in Boosts do
	                local Controller = bedwars[v.Controller]
	                if Controller and Controller[v.Method] then
	                    OldMethods[i] = Controller[v.Method]
	                    Controller[v.Method] = v.Hook(v, OldMethods[i])
	                end
	            end
	
	            if Kaida.Enabled then
	                local Success, Balance = pcall(function()
	                    return require(replicatedStorage.TS.games.bedwars.kit.kits.summoner["summoner-kit-balance"]).SummonerKitBalance
	                end)
	                if Success and Balance then
	                    SummonRange = SummonRange or Balance.SPELL_CAST_RANGE
	                    Balance.SPELL_CAST_RANGE = math.max(KaidaRange.Value, SummonRange)
	                end
	            end
	        else
	            for i: number, v: any in Boosts do
	                local Controller = bedwars[v.Controller]
	                if Controller and OldMethods[i] then
	                    Controller[v.Method] = OldMethods[i]
	                end
	            end
	            table.clear(OldMethods)
	
	            if SummonRange then
	                local Success, Balance = pcall(function()
	                    return require(replicatedStorage.TS.games.bedwars.kit.kits.summoner["summoner-kit-balance"]).SummonerKitBalance
	                end)
	                if Success and Balance then
	                    Balance.SPELL_CAST_RANGE = SummonRange
	                end
	                SummonRange = nil
	            end
	        end
	    end,
	    Tooltip = "Extends multiple kit abilities"
	})
	
	for _, v: any in Boosts do
	    v.Toggle = KitExtender:CreateToggle({
	        Name = v.Name,
	        Function = function(Callback: boolean)
	            if v.Multiplier and v.Multiplier.Object then
	                v.Multiplier.Object.Visible = Callback
	            end
	        end,
	        Tooltip = v.Tooltip
	    })
	    v.Multiplier = KitExtender:CreateSlider({
	        Name = `{v.Name} multiplier`,
	        Min = 1,
	        Max = 5,
	        Decimal = 10,
	        Default = 2,
	        Darker = true,
	        Visible = false,
	        Suffix = "x"
	    })
	end
	Kaida = KitExtender:CreateGroup({
	    Name = "Kaida Summon Range",
	    Function = function(Callback: boolean)
	        if KitExtender.Enabled then
	            KitExtender:Toggle()
	            KitExtender:Toggle()
	        end
	    end,
	    Tooltip = 'Lets the summon circle land further away'
	})
	KaidaRange = Kaida:CreateSlider({
	    Name = "Kaida summon range",
	    Min = 45,
	    Max = 120,
	    Function = function(Val: number)
	        if not KitExtender.Enabled or not SummonRange then
	            return
	        end
	        local Success, Balance = pcall(function()
	            return require(replicatedStorage.TS.games.bedwars.kit.kits.summoner["summoner-kit-balance"]).SummonerKitBalance
	        end)
	        if Success and Balance then
	            Balance.SPELL_CAST_RANGE = math.max(Val, SummonRange)
	        end
	    end,
	    Default = 75,
	    Darker = true,
	    Suffix = function(Val: number)
	        return Val == 1 and "stud" or "studs"
	    end
	})
end)

-- ===== Kits/KitSpy.lua =====
run(function()
	local httpService   = httpService
	local playersService = playersService
	local replicatedStorage = replicatedStorage
	local runService    = runService
	local inputService  = inputService
	local tweenService  = tweenService
	local collectionService = collectionService
	local guiService    = guiService
	local teleportService = game:GetService('TeleportService')
	local obj           = debug
	local currentCamera = gameCamera
	local localPlayer   = lplr
	local entity        = entitylib
	local getfontbounds = getfontsize
	local getvapeasset  = getcustomasset

	local function connectRemote(name, callback)
		local remote = bedwars.Handler:Get(name).Remote
		if remote then
			return remote:Connect(callback)
		end
		return { Disconnect = function() end }
	end

	local kitSpyModule        = nil
	local expandedBeeToggle, expandedMetalToggle
	local viewerToggle        = nil
	local notificationsToggle = nil
	local ignoreTeammatesToggle = nil
	local ignoreYourselfToggle  = nil
	local rangeSlider         = nil
	local windowSlider        = nil
	local delaySlider         = nil
	local itemsList           = nil
	local collectablesList    = nil
	local kitToggles          = {}

	local collectableLabels = {
		alchemist_ingedients = "ingredient",
		alchemy_crystal = "crystal",
		crystalheart_seed = "crystalheart seed",
		forest_environment_plant = "plant",
		ghost = "ghost",
		murder_coin = "coin",
		shadow_coin = "shadow coin",
		soulvine_seed = "soulvine seed",
		spirit_gardener_energy = "energy",
		spirit_gardener_seeds = "seed",
		tearbloom_seed = "tearbloom seed",
	}

	local totals        = {}
	local viewerButton  = nil
	local viewerLabel   = nil
	local viewerExpanded = false
	local shovelDigAnimationId
	pcall(function()
		shovelDigAnimationId = bedwars.GameAnimationUtil:getAssetId(bedwars.AnimationType.SHOVEL_DIG)
	end)

	local digWatches = setmetatable({}, { __mode = "k" })

	local beeTotals   = {}
	local beeSeen     = setmetatable({}, { __mode = "k" })
	local beeGone     = {}
	local beePanel    = nil
	local beeLabel    = nil
	local beeExpanded = false

	local metalWatches = setmetatable({}, { __mode = "k" })

	local function getDisplayName(plr)
		if plr then
			plr = plr.DisplayName or plr.Name
		end
		return plr or "someone"
	end

	local function isIgnored(plr)
		if plr == localPlayer then
			return ignoreYourselfToggle.Enabled
		end
		return ignoreTeammatesToggle.Enabled and plr.Team == localPlayer.Team
	end

	local function pluralize(count, noun)
		return ("%* %*%*"):format(count, noun, count == 1 and "" or "s")
	end

	local function refreshViewer()
		if not viewerButton then
			return
		end
		local entries = {}

		for plr, categories in totals do
			local parts = {}
			local total = 0

			for category, count in categories do
				total += count
				table.insert(parts, pluralize(count, category))
			end

			table.sort(parts)
			table.insert(entries, { Name = getDisplayName(plr), Total = total, Text = table.concat(parts, ", ") })
		end

		table.sort(entries, function(a, b)
			return a.Total > b.Total
		end)

		local lines = { "KitSpy" }

		if #entries == 0 then
			table.insert(lines, "Nothing spotted yet")
		else
			for i, entry in entries do
				if not viewerExpanded and i > 5 then
					table.insert(lines, ("+%* more"):format(#entries - 5))
					break
				else
					table.insert(lines, ("%*: %*"):format(entry.Name, entry.Text))
				end
			end
		end

		viewerLabel.Text = table.concat(lines, "\n")
		local textSize = viewerLabel.TextSize
		local fontFace = viewerLabel.FontFace
		local bounds   = getfontbounds(removeTags(viewerLabel.Text), textSize, fontFace)
		local height   = bounds.Y + 16
		viewerButton.Size = UDim2.fromOffset(
			math.max(
				bounds.X,
				getfontbounds(
					"KitSpy",
					viewerLabel.TextSize,
					Font.new(viewerLabel.FontFace.Family, Enum.FontWeight.Bold)
				).X
			) + 16,
			height
		)
		viewerButton.Visible = viewerToggle.Enabled
	end

	local function addTotal(plr, category, amount)
		local categories = totals[plr] or {}
		categories[category] = (categories[category] or 0) + amount
		totals[plr] = categories
		refreshViewer()
		return categories[category]
	end

	local function ensureViewer()
		if viewerButton then
			return
		end
		viewerButton = Instance.new("TextButton")
		viewerButton.Name = "KitSpyViewer"
		viewerButton.Position = UDim2.fromOffset(12, 260)
		viewerButton.BackgroundColor3 = Color3.new()
		viewerButton.BackgroundTransparency = 0.5
		viewerButton.Text = ""
		viewerButton.AutoButtonColor = false
		viewerButton.Visible = false
		viewerButton.Parent = vape.gui.ScaledGui
		addBlur(viewerButton)
		local uiCorner = Instance.new("UICorner")
		uiCorner.CornerRadius = UDim.new(0, 5)
		uiCorner.Parent = viewerButton
		viewerLabel = Instance.new("TextLabel")
		viewerLabel.Size = UDim.new(1, -16, 1, -16)
		viewerLabel.Position = UDim2.fromOffset(8, 8)
		viewerLabel.BackgroundTransparency = 1
		viewerLabel.TextXAlignment = Enum.TextXAlignment.Left
		viewerLabel.TextYAlignment = Enum.TextYAlignment.Top
		viewerLabel.TextSize = 16
		viewerLabel.TextColor3 = Color3.new(1, 1, 1)
		viewerLabel.TextStrokeColor3 = Color3.new()
		viewerLabel.TextStrokeTransparency = 0.8
		viewerLabel.Font = Enum.Font.Arial
		viewerLabel.RichText = true
		viewerLabel.Parent = viewerButton

		viewerButton.MouseButton1Click:Connect(function()
			viewerExpanded = not viewerExpanded
			refreshViewer()
		end)
	end

	local function countItem(plr, itemType)
		local items = (store.inventories[plr] or { items = {} }).items
		local total = 0

		for _, item in items do
			if item.itemType == itemType then
				total += item.amount or 1
			end
		end

		return total
	end

	local function recentItems(plr, filterList)
		local serverTimeNow = workspace:GetServerTimeNow()
		local lines         = {}
		local inventory     = store.inventories[plr] or { items = {} }

		for _, item in inventory.items do
			if not (windowSlider.Value < serverTimeNow - (item.addedToBackpackTime or 0)) then
				if not (filterList and #itemsList.ListEnabled > 0 and not table.find(itemsList.ListEnabled, item.itemType)) then
					local meta = bedwars.ItemMeta[item.itemType]
					table.insert(lines, ("%*%*"):format(
						(item.amount or 1) > 1 and ("%*x "):format(item.amount) or "",
						meta and meta.displayName or item.itemType
					))
				end
			end
		end

		return lines
	end

	local function reportDig(plr, prefix, filterList)
		local items = recentItems(plr, filterList)
		if #items == 0 then
			return
		end
		notif("KitSpy", ("%* %* %*"):format(getDisplayName(plr), prefix, table.concat(items, ", ")), 8, "info")
	end

	local function findNearbyPlayer(position)
		local bestDistance = rangeSlider.Value
		local bestPlayer   = nil

		for _, ent in entity.List do
			if not (not ent.Player or isIgnored(ent.Player)) then
				local distance = (ent.RootPart.Position - position).Magnitude
				if distance <= bestDistance then
					bestPlayer   = ent.Player
					bestDistance = distance
				end
			end
		end

		return bestPlayer
	end

	local function reportPickup(plr, category, amount)
		local newTotal = addTotal(plr, category, amount)

		if notificationsToggle.Enabled then
			notif("KitSpy", ("%* picked up %* (%* total)"):format(
				getDisplayName(plr), pluralize(amount, category), newTotal
			), 5, "info")
		end
	end

	local function trackKitPickups(tag, category, itemType, labelMap)
		local positions   = {}
		local disappeared = {}
		local seenCounts  = {}

		local tracked = collection(tag, kitSpyModule, function(list, obj)
			table.insert(list, obj)
			local part = obj:IsA("Model")
					and (obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart", true))
				or obj
			if part then
				positions[obj] = part.Position
			end
		end, function(list, obj, name)
			local idx = table.find(list, obj)
			if idx then
				table.remove(list, idx)
			end

			local lastPos = positions[obj]
			positions[obj] = nil
			if not lastPos then
				return
			end

			if not itemType then
				local blamed = findNearbyPlayer(lastPos)
				if blamed then
					reportPickup(blamed, labelMap and labelMap[name] or category, 1)
				end
				return
			end

			table.insert(disappeared, { Position = lastPos, Time = tick() })
		end)

		if itemType then
			for _, ent in entity.List do
				if ent.Player then
					seenCounts[ent.Player] = countItem(ent.Player, itemType)
				end
			end
		end

		while true do
			local now = tick()

			for _, obj in tracked do
				local part = obj:IsA("Model")
						and (obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart", true))
					or obj
				if part then
					positions[obj] = part.Position
				end
			end

			for i = #disappeared, 1, -1 do
				if now - disappeared[i].Time > windowSlider.Value then
					table.remove(disappeared, i)
				end
			end

			if itemType then
				for _, ent in entity.List do
					local plr = ent.Player
					if not (not plr or isIgnored(plr)) then
						local newCount = countItem(plr, itemType)
						local oldCount = seenCounts[plr]
						seenCounts[plr] = newCount

						if not (not oldCount or newCount <= oldCount or not ent.RootPart) then
							for i = #disappeared, 1, -1 do
								if not (rangeSlider.Value < (ent.RootPart.Position - disappeared[i].Position).Magnitude) then
									table.remove(disappeared, i)
									reportPickup(plr, category, newCount - oldCount)
									break
								end
							end
						end
					end
				end
			end

			task.wait(0.2)
			if kitSpyModule.Enabled then
				continue
			end
			break
		end
	end

	local function watchMetalDetectorDigs()
		local function onEntity(ent)
			if not ent.Player or isIgnored(ent.Player) then
				return
			end
			local animator = ent.Humanoid:FindFirstChildOfClass("Animator")
			if not animator or digWatches[animator] then
				return
			end

			digWatches[animator] = animator.AnimationPlayed:Connect(function(anim)
				if anim.Animation.AnimationId ~= shovelDigAnimationId then
					return
				end
				task.delay(delaySlider.Value, reportDig, ent.Player, "dug up", true)
			end)
		end

		kitSpyModule:Clean(entity.Events.EntityAdded:Connect(onEntity))

		kitSpyModule:Clean(function()
			for _, conn in digWatches do
				conn:Disconnect()
			end
			table.clear(digWatches)
		end)

		for _, ent in entity.List do
			onEntity(ent)
		end
	end

	local function beeCount(plr)
		local items = (store.inventories[plr] or { items = {} }).items
		local total = 0

		for _, item in items do
			if item.itemType == "bee" then
				total += item.amount or 1
			end
		end

		return total
	end

	local function refreshBeePanel()
		if not beePanel then
			return
		end
		local entries = {}

		for plr, total in beeTotals do
			table.insert(entries, { Name = plr.Name, Total = total })
		end

		table.sort(entries, function(a, b)
			return a.Total > b.Total
		end)

		local lines = { "BeekeeperSpy" }

		if #entries == 0 then
			table.insert(lines, "No bees collected yet")
		else
			for i, entry in entries do
				if not beeExpanded and i > 5 then
					table.insert(lines, ("+%* more"):format(#entries - 5))
					break
				else
					table.insert(lines, ("%*: %* bee%*"):format(
						entry.Name, entry.Total, entry.Total == 1 and "" or "s"
					))
				end
			end
		end

		beeLabel.Text = table.concat(lines, "\n")
		local bounds = getfontbounds(removeTags(beeLabel.Text), beeLabel.TextSize, beeLabel.FontFace)
		beePanel.Size = UDim2.fromOffset(
			math.max(
				bounds.X,
				getfontbounds(
					"BeekeeperSpy",
					beeLabel.TextSize,
					Font.new(beeLabel.FontFace.Family, Enum.FontWeight.Bold)
				).X
			) + 16,
			bounds.Y + 16
		)
	end

	local function ensureBeePanel()
		if beePanel then
			return
		end

		beePanel = Instance.new("TextButton")
		beePanel.Name = "BeekeeperSpyViewer"
		beePanel.Position = UDim2.fromOffset(12, 260)
		beePanel.BackgroundColor3 = Color3.new()
		beePanel.BackgroundTransparency = 0.5
		beePanel.Text = ""
		beePanel.AutoButtonColor = false
		beePanel.Visible = false
		beePanel.Parent = vape.gui.ScaledGui
		addBlur(beePanel)

		local uiCorner = Instance.new("UICorner")
		uiCorner.CornerRadius = UDim.new(0, 5)
		uiCorner.Parent = beePanel

		beeLabel = Instance.new("TextLabel")
		beeLabel.Size = UDim.new(1, -16, 1, -16)
		beeLabel.Position = UDim2.fromOffset(8, 8)
		beeLabel.BackgroundTransparency = 1
		beeLabel.TextXAlignment = Enum.TextXAlignment.Left
		beeLabel.TextYAlignment = Enum.TextYAlignment.Top
		beeLabel.TextSize = 16
		beeLabel.TextColor3 = Color3.new(1, 1, 1)
		beeLabel.TextStrokeColor3 = Color3.new()
		beeLabel.TextStrokeTransparency = 0.8
		beeLabel.Font = Enum.Font.Arial
		beeLabel.RichText = true
		beeLabel.Parent = beePanel

		beePanel.MouseButton1Click:Connect(function()
			beeExpanded = not beeExpanded
			refreshBeePanel()
		end)
	end

	local function runBeekeeperSpy()
		ensureBeePanel()
		table.clear(beeGone)

		for _, ent in entity.List do
			if ent.Player then
				beeTotals[ent.Player] = beeCount(ent.Player)
			end
		end

		refreshBeePanel()

		local bees = collection("bee", kitSpyModule, function(list, obj)
			table.insert(list, obj)
			local part = obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart")
			if part then
				beeSeen[obj] = part.Position
			end
		end, function(list, obj)
			local idx = table.find(list, obj)
			if idx then
				table.remove(list, idx)
			end

			local lastPos = beeSeen[obj]
			beeSeen[obj] = nil
			if not lastPos then
				return
			end
			table.insert(beeGone, { Position = lastPos, Time = tick() })
		end)

		while true do
			local now = tick()

			for _, obj in bees do
				local part = obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart")
				if part then
					beeSeen[obj] = part.Position
				end
			end

			for i = #beeGone, 1, -1 do
				if now - beeGone[i].Time > ignoreTeammatesToggle.Value then
					table.remove(beeGone, i)
				end
			end

			for _, ent in entity.List do
				local plr = ent.Player
				if not (not plr or plr == localPlayer or isIgnored(plr)) then
					local current = beeCount(plr)
					local previous = beeTotals[plr]
					beeTotals[plr] = current

					if not (not previous or current <= previous or not ent.RootPart) then
						local gained = current - previous

						for i = #beeGone, 1, -1 do
							if not (rangeSlider.Value < (ent.RootPart.Position - beeGone[i].Position).Magnitude) then
								table.remove(beeGone, i)
								beeTotals[plr] = current

								if notificationsToggle.Enabled then
									notif(
										"BeekeeperSpy",
										("%* picked up %* bee%* (%* total)"):format(
											plr.Name,
											gained,
											gained == 1 and "" or "s",
											current
										),
										5,
										"info"
									)
								end

								refreshBeePanel()
							break
							end
						end
					end
				end
		end

			task.wait(0.2)
			if kitSpyModule.Enabled then
				continue
			end

			break
		end
	end		

	local function watchDigs()
		local function onEntity(ent)
			if not ent.Player or ent.Player == localPlayer or isIgnored(ent.Player) then
				return
			end

			local animator = ent.Humanoid:FindFirstChildOfClass("Animator")
			if not animator or metalWatches[animator] then
				return
			end

			metalWatches[animator] = animator.AnimationPlayed:Connect(function(anim)
				if anim.Animation.AnimationId ~= shovelDigAnimationId then
					return
				end
				task.delay(delaySlider.Value, reportDig, ent.Player, "dug up", true)
			end)
		end

		kitSpyModule:Clean(entity.Events.EntityAdded:Connect(onEntity))

		kitSpyModule:Clean(function()
			for _, conn in metalWatches do
				conn:Disconnect()
			end
			table.clear(metalWatches)
		end)

		for _, ent in entity.List do
			onEntity(ent)
		end
	end

	local kitHandlers = {
		beekeeper = function()
			trackKitPickups("bee", "bee", "bee")
		end,
		bigman = function()
			trackKitPickups("treeOrb", "tree orb")
		end,
		bounty_hunter = function()
			local bounties = {}

			kitSpyModule:Clean(function()
				table.clear(bounties)
			end)

			kitSpyModule:Clean(connectRemote("BountyHunterTargetChanged", function(payload)
				local hunter = typeof(payload) == "table" and payload.hunter
				if typeof(hunter) ~= "Instance" or not hunter:IsA("Player") then
					return
				end
				local target = payload.newTargetUserId ~= 0
						and playersService:GetPlayerByUserId(payload.newTargetUserId)
					or nil
				bounties[hunter] = target

				if target and notificationsToggle.Enabled and not isIgnored(hunter) then
					notif("KitSpy", ("%* is now hunting %*"):format(
						getDisplayName(hunter), getDisplayName(target)
					), 12, "info")
				end
			end))

			kitSpyModule:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(payload)
				local victim = playersService:GetPlayerFromCharacter(payload.entityInstance)
				local killer = playersService:GetPlayerFromCharacter(payload.fromEntity)
				if not victim or not killer or bounties[killer] ~= victim then
					return
				end
				bounties[killer] = nil
				if isIgnored(killer) then
					return
				end
				addTotal(killer, "bounty", 1)
				notif(
					"KitSpy",
					("%* claimed their bounty on %*"):format(
						getDisplayName(killer), getDisplayName(victim)
					),
					20,
					"alert"
				)
				task.delay(delaySlider.Value, reportDig, killer, "looted", false)
			end))

			kitSpyModule:Clean(playersService.PlayerRemoving:Connect(function(plr)
				bounties[plr] = nil
				for hunter, target in bounties do
					if target == plr then
						bounties[hunter] = nil
					end
				end
			end))
		end,
		farmer_cletus = function()
			trackKitPickups("HarvestableCrop", "crop")
		end,
		fisherman = function()
			kitSpyModule:Clean(connectRemote("FishCaught", function(payload)
				local catcher = typeof(payload) == "table" and payload.catchingPlayer
				if not catcher or not payload.dropData or not payload.dropData.drops or isIgnored(catcher) then
					return
				end
				local lines = {}

				for _, drop in payload.dropData.drops do
					local meta = bedwars.ItemMeta[drop.itemType]
					table.insert(lines, pluralize(
						drop.amount,
						(meta and meta.displayName or drop.itemType):lower()
					))
				end

				if #lines == 0 then
					return
				end
				addTotal(catcher, "catch", 1)

				if notificationsToggle.Enabled then
					notif(
						"KitSpy",
						("%* caught %*"):format(getDisplayName(catcher), table.concat(lines, ", ")),
						20,
						"info"
					)
				end
			end))
		end,
		jailor = function()
			trackKitPickups("jailor_soul", "soul")
		end,
		metal_detector = function()
			trackKitPickups("hidden-metal", "metal")
			watchMetalDetectorDigs()
		end,
		spirit_assassin = function()
			trackKitPickups("EvelynnSoul", "spirit")
		end,
		star_collector = function()
			trackKitPickups("stars", "star")
		end,
	}

	kitSpyModule = vape.Categories.Kits:CreateModule({
		Name = "KitSpy",
		Category = "Visual",
		Function = function(enabled)
			if enabled then
				ensureViewer()
				refreshViewer()

				for kitName, handler in kitHandlers do
					if kitToggles[kitName].Enabled then
						task.spawn(handler)
					end
				end

				if #collectablesList.ListEnabled > 0 then
					task.spawn(trackKitPickups, collectablesList.ListEnabled, "collectable", nil, collectableLabels)
				end

				if expandedBeeToggle.Enabled then
					task.spawn(runBeekeeperSpy)
				end

				if expandedMetalToggle.Enabled then
					watchDigs()
				end
			elseif viewerButton then
				viewerButton.Visible = false

				if beePanel then
					beePanel.Visible = false
				end
			end
		end,
		Tooltip = 'Reports what other players are doing with their kits',
	})

	viewerToggle = kitSpyModule:CreateToggle({
		Name = "Viewer",
		Function = function()
			refreshViewer()
		end,
		Tooltip = 'Shows a panel of what each player has picked up',
		Default = true,
	})

	notificationsToggle = kitSpyModule:CreateToggle({
		Name = "Notifications",
		Default = true,
		Tooltip = 'Tells you when someone uses their kit',
	})

	ignoreTeammatesToggle = kitSpyModule:CreateToggle({ Name = "Ignore teammates", Default = true })
	ignoreYourselfToggle  = kitSpyModule:CreateToggle({ Name = "Ignore yourself", Default = true })

	rangeSlider = kitSpyModule:CreateSlider({
		Name = "Range",
		Min = 1,
		Max = 40,
		Default = 25,
		Suffix = function(value)
			return value <= 1 and "stud" or "studs"
		end,
		Tooltip = 'How close a player must be to count as taking it',
	})

	windowSlider = kitSpyModule:CreateSlider({
		Name = "Window",
		Min = 1,
		Max = 10,
		Default = 3,
		Suffix = function(value)
			return value > 1 and "secs" or "sec"
		end,
		Tooltip = 'How recently it must have happened to count',
	})

	delaySlider = kitSpyModule:CreateSlider({
		Name = "Delay",
		Min = 0,
		Max = 2,
		Default = 0.5,
		Decimal = 100,
		Suffix = function(value)
			return value == 1 and "sec" or "secs"
		end,
		Tooltip = 'Delay before reading their inventory',
	})

	itemsList = kitSpyModule:CreateTextList({
		Name = "Items",
		Placeholder = "item type (iron_ingot)",
		Darker = true,
		Tooltip = 'Items to report, empty reports everything',
	})

	collectablesList = kitSpyModule:CreateTextList({
		Name = "Collectables",
		Default = {
			"alchemist_ingedients",
			"alchemy_crystal",
			"crystalheart_seed",
			"ghost",
			"murder_coin",
			"shadow_coin",
			"soulvine_seed",
			"spirit_gardener_energy",
			"spirit_gardener_seeds",
			"tearbloom_seed",
		},
		Darker = true,
		Tooltip = 'Extra collectables to watch',
	})

	kitSpyModule:CreateButton({
		Name = "Reset totals",
		Function = function()
			table.clear(totals)
			refreshViewer()

			table.clear(beeTotals)
			refreshBeePanel()
		end,
	})

	local function kitDisplayName(kitName)
		local meta = bedwars.BedwarsKitMeta[kitName]
		return meta and meta.name or kitName
	end

	local sortedKits = {}

	for kitName in kitHandlers do
		table.insert(sortedKits, kitName)
	end

	table.sort(sortedKits, function(a, b)
		return kitDisplayName(a) < kitDisplayName(b)
	end)

	for _, kitName in sortedKits do
		kitToggles[kitName] = kitSpyModule:CreateToggle({ Name = kitDisplayName(kitName), Default = true })
	end

	expandedBeeToggle = kitSpyModule:CreateToggle({
		Name = "BeekeeperSpy",
		Default = false,
		Tooltip = 'Tracks which players collect bees and how many',
	})

	local expandedBeeViewer = kitSpyModule:CreateToggle({
		Name = "BeekeeperSpy viewer",
		Default = true,
		Darker = true,
		Function = function(visible)
			if beePanel then
				beePanel.Visible = visible and expandedBeeToggle.Enabled
			end
		end,
		Tooltip = 'Shows everyone\'s total bees in a panel',
	})

	expandedBeeToggle.Function = function(enabled)
		if beePanel then
			beePanel.Visible = enabled and expandedBeeViewer.Enabled
		end

		if enabled and kitSpyModule.Enabled then
			task.spawn(runBeekeeperSpy)
		end
	end

	expandedMetalToggle = kitSpyModule:CreateToggle({
		Name = "MetalDetectorSpy",
		Default = false,
		Tooltip = 'Reports what other players dig up',
	})

	expandedMetalToggle.Function = function(enabled)
		if enabled and kitSpyModule.Enabled then
			watchDigs()
		end
	end
end)

-- ===== Kits/KrystalDisabler.lua =====
run(function()
	local KrystalDisabler
	local UPDATE_INTERVAL = 0.016
	local lastUpdateTime = 0
	local renderStepName = 'KrystalDisablerMovement'
	local driving = false

	local function release()
		if not driving then return end
		driving = false
		pcall(function()
			if store.equippedKit == 'glacial_skater' then
				bedwars.GlacialSkaterController:updateMomentum(0, 'newValue')
			else
				bedwars.SprintController:getMovementStatusModifier():updateModifiers()
			end
		end)
	end

	KrystalDisabler = kits:CreateModule({
		Name = 'KrystalDisabler',
		Category = 'Ability',
		Tooltip = 'Keeps Krystal\'s momentum full and stops its speed checks',
		Function = function(callback)
			if callback then
				lastUpdateTime = 0
				runService:BindToRenderStep(renderStepName, Enum.RenderPriority.Character.Value + 2, function()
					if store.equippedKit ~= 'glacial_skater' then
						release()
						return
					end
					local currentTime = tick()
					if currentTime - lastUpdateTime < UPDATE_INTERVAL then return end
					lastUpdateTime = currentTime
					local controller = bedwars.GlacialSkaterController
					if controller then
						driving = true
						pcall(controller.updateMomentum, controller, 100, 'newValue')
					end
				end)
			else
				runService:UnbindFromRenderStep(renderStepName)
				release()
			end
		end
	})
end)

-- ===== Kits/MelodyExploit.lua =====
run(function()
	local MelodyExploit
	local Switch
	local Cooldown
	local Retry
	local OnlyHurt
	local AutoBuy

	local SWORDS = {'emerald_sword', 'diamond_sword', 'iron_sword', 'stone_sword', 'wood_sword', 'wooden_sword'}
	local net

	local function remote(name)
		if not net or not net.Parent then
			local ok, found = pcall(function()
				return replicatedStorage.rbxts_include.node_modules['@rbxts'].net.out._NetManaged
			end)
			net = ok and found or nil
		end
		return net and net:FindFirstChild(name)
	end

	local function folder()
		local inventories = replicatedStorage:FindFirstChild('Inventories')
		return inventories and inventories:FindFirstChild(lplr.Name)
	end

	local function guitar()
		local inv = folder()
		return inv and inv:FindFirstChild('guitar')
	end

	local function sword()
		local inv = folder()
		if not inv then return end
		for _, name in SWORDS do
			local item = inv:FindFirstChild(name)
			if item then return item end
		end
	end

	local function hand(item)
		local equip = item and remote('SetInvItem')
		if equip then
			task.spawn(pcall, equip.InvokeServer, equip, {hand = item})
		end
	end

	local function heal(item)
		local play = remote('PlayGuitar')
		if play and lplr.Character then
			pcall(play.FireServer, play, {healTarget = lplr.Character, tool = item})
		end
	end

	local function strum(item)
		hand(item)
		heal(item)
		task.wait(0.03)
		hand(sword())
	end

	local function owned()
		for _, container in {lplr.Character, lplr:FindFirstChild('Backpack')} do
			for _, child in container:GetChildren() do
				if child.Name:lower() == 'guitar' then return true end
			end
		end
		return false
	end

	local function buy()
		local purchase = remote('BedwarsPurchaseItem')
		if not purchase then return end
		pcall(purchase.InvokeServer, purchase, {
			shopItem = {
				amount = 1,
				lockAfterPurchase = true,
				itemType = 'guitar',
				category = 'Combat',
				price = 16,
				requiresKit = {'melody'},
				spawnWithItems = {'guitar'},
				currency = 'iron'
			},
			shopId = '1_item_shop'
		})
	end

	MelodyExploit = kits:CreateModule({
		Name = 'MelodyExploit',
		Category = 'Auto',
		Function = function(callback)
			if not callback then return end
			MelodyExploit:Clean(task.spawn(function()
				repeat
					if AutoBuy.Enabled and lplr.Character and not owned() then
						buy()
						task.wait(0.5)
					end
					task.wait(0.5)
				until not MelodyExploit.Enabled
			end))
			local last = 0
			repeat
				local humanoid = entitylib.isAlive and entitylib.character.Humanoid
				local item = humanoid and guitar()
				if item and humanoid.Health > 0 and (not OnlyHurt.Enabled or humanoid.Health < humanoid.MaxHealth) then
					if not Switch.Enabled then
						heal(item)
						task.wait(0.25)
					elseif os.clock() - last >= Cooldown.Value then
						last = os.clock()
						local before = humanoid.Health
						strum(item)
						task.wait(0.2)
						if Retry.Enabled and MelodyExploit.Enabled and humanoid.Parent and humanoid.Health < humanoid.MaxHealth * 0.97 and humanoid.Health <= before + 0.1 then
							hand(item)
							task.wait(lplr:GetNetworkPing() / 2)
							heal(item)
							task.wait(0.03)
							hand(sword())
						end
						task.wait(math.max(Cooldown.Value - 0.03, 0))
					end
				end
				task.wait(0.05)
			until not MelodyExploit.Enabled
		end,
		Tooltip = 'Heals you with the guitar while keeping your sword in hand'
	})
	Switch = MelodyExploit:CreateGroup({
		Name = 'Sword switch',
		Default = true,
		Tooltip = 'Switches back to your best sword after each heal'
	})
	Cooldown = Switch:CreateSlider({
		Name = 'Heal delay',
		Min = 0.5,
		Max = 3,
		Default = 1,
		Decimal = 100,
		Darker = true,
		Suffix = 's'
	})
	Retry = Switch:CreateToggle({
		Name = 'Retry missed heals',
		Default = true,
		Darker = true,
		Tooltip = 'Heals again when your health did not go up after a heal'
	})
	OnlyHurt = MelodyExploit:CreateToggle({
		Name = 'Only when hurt',
		Tooltip = 'Skips healing while your health is full'
	})
	AutoBuy = MelodyExploit:CreateToggle({
		Name = 'Auto buy guitar',
		Default = true,
		Tooltip = 'Buys a guitar from the item shop whenever you do not have one'
	})
end)

-- ===== Kits/MissileTP.lua =====
run(function()
    local MissileTP

    MissileTP = kits:CreateModule({
        Name = 'MissileTP',
        Category = 'Ability',
        Function = function(callback)
            if callback then
                MissileTP:Toggle()
                local plr = entitylib.EntityMouse({
                    Range = 1000,
                    Players = true,
                    Part = 'RootPart'
                })

                if getItem('guided_missile') and plr then
                    local projectile = bedwars.RuntimeLib.await(bedwars.GuidedProjectileController.fireGuidedProjectile:CallServerAsync('guided_missile'))
                    if projectile then
                        local projectilemodel = projectile.model
                        if not projectilemodel.PrimaryPart then
                            projectilemodel:GetPropertyChangedSignal('PrimaryPart'):Wait()
                        end

                        local bodyforce = Instance.new('BodyForce')
                        bodyforce.Force = Vector3.new(0, projectilemodel.PrimaryPart.AssemblyMass * workspace.Gravity, 0)
                        bodyforce.Name = 'AntiGravity'
                        bodyforce.Parent = projectilemodel.PrimaryPart

                        repeat
                            projectile.model:SetPrimaryPartCFrame(CFrame.lookAlong(plr.RootPart.CFrame.p, gameCamera.CFrame.LookVector))
                            task.wait(0.1)
                        until not projectile.model or not projectile.model.Parent
                    else
                        notif('MissileTP', 'Missile on cooldown.', 3)
                    end
                end
            end
        end,
        Tooltip = 'Sends a missile at the player nearest your mouse'
    })
end)

-- ===== Kits/OwlAura.lua =====
run(function()
	local Main = vape.Libraries.mergedModule(kits, {
		Name = 'OwlAura',
		Category = 'Aim',
		Tooltip = 'Shoots at nearby enemies and helps a teammate with your owl'
	})

run(function()
    local OwlAura
    local Targets
    local Mode
    local Range
    local ShowFOV
    local FOV
    local fovColour
    local fovThickness
    local fovCircle
    local circleLibrary = vape.Libraries and vape.Libraries.fovcircle

    local function insideFOV(ent)
        return circleLibrary ~= nil and circleLibrary.ContainsEntity ~= nil and circleLibrary.ContainsEntity(ent, FOV.Value)
    end

    local function findTarget(origin)
        local settings = {
            Origin = origin,
            Range = Range.Value,
            Part = 'RootPart',
            Players = Targets.Players.Enabled,
            Priority = Targets.Priority and Targets.Priority.Value,
            NPCs = Targets.NPCs.Enabled,
            Wallcheck = Targets.Walls.Enabled,
            Sort = sortmethods[Mode.Value],
        }
        if not ShowFOV.Enabled then
            return entitylib.EntityPosition(settings)
        end
        for _, ent in entitylib.AllPosition(settings) do
            if ent.RootPart and insideFOV(ent) then return ent end
        end
    end

    local function runFOVCircle(state)
        if fovCircle then fovCircle:Destroy(); fovCircle = nil end
        if not state or not (circleLibrary and circleLibrary.New) then return end
        fovCircle = circleLibrary.New({
            Name = 'OwlAuraFOVCircle',
            Parent = vape.gui,
            Visible = function()
                return OwlAura and OwlAura.Enabled and ShowFOV.Enabled
            end,
            Radius = function()
                return FOV.Value
            end,
            Colour = function()
                return Color3.fromHSV(fovColour.Hue, fovColour.Sat, fovColour.Value)
            end,
            Thickness = function()
                return fovThickness.Value
            end
        })
    end

    local function getProjectileMeta()
        local meta = table.clone(bedwars.ProjectileMeta.owl_projectile)
        return meta
    end

    OwlAura = Main:Part({
		Label = 'Owl aura',
        Name = 'OwlAura',
        Category = 'Aim',
        Function = function(callback)
            runFOVCircle(callback and ShowFOV.Enabled)
            if callback then
                local owls = collection('Owl', OwlAura, function(self, obj)
                    task.delay(1, function()
                        if obj and obj.Parent and obj:GetAttribute('Owner') == lplr.UserId then
                            table.insert(self, obj)
                        end
                    end)
                end)
                repeat
                    if store.equippedKit ~= 'owl' then
                        task.wait(3)
                        continue
                    end

                    if entitylib.isAlive then
                        local owl = owls[1]
                        if owl then
                            local origin = owl.Part.Position
                            local plr = findTarget(origin)

                            if plr then
                                local meta = getProjectileMeta()
                                local calc = prediction.SolveTrajectory(origin, meta.launchVelocity, meta.gravitationalAcceleration, plr.RootPart.Position, plr.RootPart.Velocity, workspace.Gravity, plr.HipHeight, plr.Jumping and 42.6 or nil, nil, plr.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(plr.RootPart.AssemblyLinearVelocity.Y) > 0.01, plr.RootPart.Position, plr.RootPart, nil, true)
                                if calc then
                                    local dir = CFrame.lookAt(origin, calc).LookVector * meta.launchVelocity
                                    bedwars.Client:Get('OwlAiming'):SendToServer({
                                        owl = owl.Part,
                                        starting = true,
                                    })
                                    bedwars.Client:Get('OwlFireProjectile'):SendToServer({
                                        ProjectileRefId = vape.Libraries.string:GenerateString(8),
                                        direction = dir,
                                        fromPosition = origin,
                                        initialVelocity = dir,
                                    })
                                    task.wait(lplr:GetNetworkPing())
                                end
                            end
                        end
                    end
                    task.wait(0.1)
                until not OwlAura.Enabled
            else
                bedwars.Client:Get('OwlAiming'):SendToServer({
                    starting = false,
                })
            end
        end,
        Tooltip = 'Shoots owl projectiles at nearby enemies'
    })

    Targets = OwlAura:CreateTargets({
        Players = true,
        Wallcheck = true,
    })
    local methods = {'Distance', 'Damage'}
    for _, v in sortlist do
        if not table.find(methods, v) then
            table.insert(methods, v)
        end
    end
    Mode = OwlAura:CreateDropdown({
        Name = 'Target mode',
        List = methods,
        Default = 'Distance',
        Tooltip = TARGET_MODE_TOOLTIP
    })
    Range = OwlAura:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 50,
        Suffix = function(val)
            return val <= 0 and 'stud' or 'studs'
        end,
        Default = 50,
    })
    ShowFOV = OwlAura:CreateGroup({
        Name = 'FOV Circle',
        Tooltip = 'Shows the range around your cursor',
        Function = function(callback)
            if FOV and FOV.Object then FOV.Object.Visible = callback end
            if OwlAura.Enabled then runFOVCircle(callback) end
        end
    })
    FOV = OwlAura:CreateSlider({
        Name = 'FOV',
        Min = 1,
        Max = 1000,
        Default = 300,
        Darker = true,
        Visible = false
    })
    fovColour = ShowFOV:CreateColorSlider({
        Name = 'Circle colour',
        Darker = true
    })
    fovThickness = ShowFOV:CreateSlider({
        Name = 'Circle thickness',
        Min = 1,
        Max = 8,
        Default = 1,
        Darker = true
    })
end)

run(function()
	local Camera = gameCamera
	local Entity = entitylib
	local LocalPlayer = lplr
	local Players = playersService
	local ReplicatedStorage = replicatedStorage
	local RunService = runService
	local Store = store
	local UserInputService = inputService
	local AutoWhisper
	local Heal
	local Threshold
	local Fly
	local Owl
	local Target
	local FOVCheck
	local FOV
	local RangeCircle
	local CircleColor
	local CircleTransparency
	local CircleThickness
	local CircleFilled
	local CircleObject

	local Teammates: {string} = {"None"}
	local Old
	local MapBottom: number = math.huge
	local FallDepth: number = 12
	local FootingCharacter, FootingY = nil, -math.huge

	local Success, OwlBalance = pcall(function()
		return require(ReplicatedStorage.TS.balance["owl-balance-file"]).OwlBalance
	end)
	local AttachRange: number = Success and OwlBalance.OWL_ATTACH_MAX_RANGE or 60

	local function GetMouseOrigin()
		return UserInputService.TouchEnabled and Camera.ViewportSize / 2 or UserInputService:GetMouseLocation()
	end

	local function GetOwlTarget(): Player?
		local Picked: Player? = Players:FindFirstChild(Target.Value)
		if not FOVCheck.Enabled then
			return Picked
		end

		if not Entity.isAlive then
			return nil
		end

		local Origin: Vector2 = GetMouseOrigin()
		local Best, BestDistance = nil, FOV.Value
		for _, v: Player in (Picked and {Picked} or Players:GetPlayers()) do
			local Character: Model? = v.Character
			local Root: BasePart? = Character and Character:FindFirstChild("HumanoidRootPart")
			if v == LocalPlayer or not Root or v:GetAttribute("Team") ~= LocalPlayer:GetAttribute("Team") or v:GetAttribute("IsOwlTarget") then
				continue
			end

			if (Root.Position - Entity.character.RootPart.Position).Magnitude > AttachRange then
				continue
			end

			local Position, Visible = Camera:WorldToViewportPoint(Root.Position)
			local Distance: number = (Vector2.new(Position.X, Position.Y) - Origin).Magnitude
			if Visible and Distance <= BestDistance then
				Best, BestDistance = v, Distance
			end
		end

		return Best
	end

	local function RefreshOptions()
		local ShowFOV: boolean = Owl.Enabled and FOVCheck.Enabled
		local ShowCircle: boolean = ShowFOV and RangeCircle.Enabled

		Target.Object.Visible = Owl.Enabled
		FOVCheck.Object.Visible = Owl.Enabled
		FOV.Object.Visible = ShowFOV
		RangeCircle.Object.Visible = ShowFOV
		CircleColor.Object.Visible = ShowCircle
		CircleTransparency.Object.Visible = ShowCircle
		CircleThickness.Object.Visible = ShowCircle
		CircleFilled.Object.Visible = ShowCircle

		if CircleObject then
			CircleObject.Visible = AutoWhisper.Enabled and ShowFOV
		end
	end

	local function GetAttachedCharacter(): Model?
		local Attached: Instance? = bedwars.OwlAbilityController.target
		if Attached and Attached:IsA("Player") then
			return Attached.Character
		end
		return Attached :: Model?
	end

	local function GetMapBottom(): number
		if MapBottom == math.huge then
			for _, v: BasePart in Store.blocks do
				MapBottom = math.min(MapBottom, v.Position.Y - (v.Size.Y / 2))
			end
		end
		return MapBottom == math.huge and -math.huge or MapBottom
	end

	local function CanUse(Ability: string): boolean
		return bedwars.AbilityController:getEnabledAbility(Ability) ~= nil and bedwars.AbilityController:canUseAbility(Ability, {disableBlockedAbilityAlert = true})
	end

	local function AddConnection(TargetPlayer: Player, Connected: boolean?)
		if not Connected then
			vape:Clean(TargetPlayer:GetAttributeChangedSignal("Team"):Connect(function()
				AddConnection(TargetPlayer, true)
			end))
		end

		if TargetPlayer ~= LocalPlayer and TargetPlayer:GetAttribute("Team") == LocalPlayer:GetAttribute("Team") and not table.find(Teammates, TargetPlayer.Name) then
			table.insert(Teammates, TargetPlayer.Name)
			Target:Change(Teammates)
		end
	end

	AutoWhisper = Main:Part({
		Label = 'Teammate owl',
		Name = "AutoWhisper",
		Function = function(Callback: boolean)
			if CircleObject then
				CircleObject.Visible = Callback and Owl.Enabled and FOVCheck.Enabled
			end

			if Callback then
				AutoWhisper:Clean(RunService.RenderStepped:Connect(function()
					if CircleObject then
						CircleObject.Position = GetMouseOrigin()
					end
				end))

				Old = bedwars.OwlKitController.onAbilityUsed
				bedwars.OwlKitController.onAbilityUsed = function(self, Character, Data, ...)
					if Owl.Enabled and Data and Data.ability == "SUMMON_OWL" and Character == LocalPlayer.Character then
						local TargetPlayer: Player? = GetOwlTarget()
						if TargetPlayer and TargetPlayer ~= LocalPlayer then
							bedwars.Handler:Get("SummonOwl"):Fire("CallServer", TargetPlayer)
							return
						end
					end
					return Old(self, Character, Data, ...)
				end

				repeat
					task.wait()
				until Store.matchState ~= 0 or not AutoWhisper.Enabled
				if not AutoWhisper.Enabled then
					return
				end

				repeat
					if Owl.Enabled and not bedwars.OwlAbilityController.target and GetOwlTarget() and bedwars.AbilityController:canUseAbility("SUMMON_OWL", {disableBlockedAbilityAlert = true}) then
						bedwars.AbilityController:useAbility("SUMMON_OWL")
					end

					local Character: Model? = GetAttachedCharacter()
					if Character then
						local Root: BasePart? = Character.PrimaryPart
						if Root then
							if FootingCharacter ~= Character then
								FootingCharacter, FootingY = Character, GetMapBottom() + FallDepth
							end
							if math.abs(Root.AssemblyLinearVelocity.Y) < 2 then
								FootingY = Root.Position.Y
							end

							if Fly.Enabled and Root.Position.Y < FootingY - FallDepth and CanUse("OWL_LIFT") then
								bedwars.AbilityController:useAbility("OWL_LIFT")
							end
						end

						local Health: number? = Character:GetAttribute("Health")
						local MaxHealth: number? = Character:GetAttribute("MaxHealth")
						if Heal.Enabled and (Threshold.Value >= 100 or Health and MaxHealth and MaxHealth > 0 and Health / MaxHealth <= Threshold.Value / 100) and CanUse("OWL_HEAL") then
							bedwars.AbilityController:useAbility("OWL_HEAL")
						end
					end
					task.wait(0.1)
				until not AutoWhisper.Enabled
			elseif Old then
				bedwars.OwlKitController.onAbilityUsed = Old
				Old = nil
			end
		end,
		Tooltip = 'Uses Whisper\'s abilities for you'
	})

	Heal = AutoWhisper:CreateGroup({
		Name = "Heal",
		Default = true
	})
	Threshold = Heal:CreateSlider({
		Name = "Heal health",
		Min = 1,
		Max = 100,
		Default = 99,
		Darker = true,
		Suffix = "%"
	})
	Fly = AutoWhisper:CreateToggle({
		Name = "Fly",
		Default = true,
		Tooltip = 'Lifts your owl\'s player when they fall over the void'
	})
	Owl = AutoWhisper:CreateToggle({
		Name = "Auto owl",
		Function = RefreshOptions,
		Tooltip = 'Sends the owl to the chosen teammate when ready'
	})
	Target = AutoWhisper:CreateDropdown({
		Name = "Teammate",
		List = Teammates,
		Darker = true,
		Visible = false,
		Tooltip = 'Who the owl is summoned onto'
	})
	FOVCheck = AutoWhisper:CreateToggle({
		Name = "FOV check",
		Function = RefreshOptions,
		Darker = true,
		Visible = false,
		Tooltip = 'Only sends the owl to a teammate near your cursor'
	})
	FOV = AutoWhisper:CreateSlider({
		Name = "Teammate FOV",
		Min = 1,
		Max = 1000,
		Function = function(Val: number)
			if CircleObject then
				CircleObject.Radius = Val
			end
		end,
		Darker = true,
		Default = 150,
		Visible = false
	})
	RangeCircle = AutoWhisper:CreateToggle({
		Name = "Range Circle",
		Function = function(Callback: boolean)
			if Callback then
				CircleObject = Drawing.new("Circle")
				CircleObject.Filled = CircleFilled.Enabled
				CircleObject.Color = Color3.fromHSV(CircleColor.Hue, CircleColor.Sat, CircleColor.Value)
				CircleObject.Position = GetMouseOrigin()
				CircleObject.Radius = FOV.Value
				CircleObject.NumSides = 100
				CircleObject.Thickness = CircleThickness.Value
				CircleObject.Transparency = 1 - CircleTransparency.Value
			else
				pcall(function()
					CircleObject.Visible = false
					CircleObject:Remove()
				end)
				CircleObject = nil
			end
			RefreshOptions()
		end,
		Darker = true,
		Visible = false
	})
	CircleColor = AutoWhisper:CreateColorSlider({
		Name = "Circle Color",
		Function = function(Hue: number, Sat: number, Val: number)
			if CircleObject then
				CircleObject.Color = Color3.fromHSV(Hue, Sat, Val)
			end
		end,
		Darker = true,
		Visible = false
	})
	CircleTransparency = AutoWhisper:CreateSlider({
		Name = "Transparency",
		Min = 0,
		Max = 1,
		Decimal = 10,
		Function = function(Val: number)
			if CircleObject then
				CircleObject.Transparency = 1 - Val
			end
		end,
		Darker = true,
		Default = 0.5,
		Visible = false
	})
	CircleThickness = AutoWhisper:CreateSlider({
		Name = "Thickness",
		Min = 1,
		Max = 10,
		Decimal = 10,
		Function = function(Val: number)
			if CircleObject then
				CircleObject.Thickness = Val
			end
		end,
		Darker = true,
		Default = 1,
		Visible = false,
		Tooltip = 'How wide the circle\'s outline is'
	})
	CircleFilled = AutoWhisper:CreateToggle({
		Name = "Circle Filled",
		Function = function(Callback: boolean)
			if CircleObject then
				CircleObject.Filled = Callback
			end
		end,
		Darker = true,
		Visible = false
	})

	for _, v: Player in Players:GetPlayers() do
		AddConnection(v)
	end
	vape:Clean(Players.PlayerAdded:Connect(AddConnection))
end)

end)

-- ===== Kits/RavenAura.lua =====
run(function()
	local util = vape.Libraries.bedwarsutil
	local RavenAura
	local Transform
	local TransformRange
	local Send
	local SendRange
	local Delay
	local nextAction = 0

	local function show(option, visible)
		if option and option.Object then option.Object.Visible = visible end
	end

	local function teleportRaven()
		local plr = entitylib.EntityMouse({
			Range = 1000,
			Players = true,
			Part = 'RootPart'
		})
		if not (getItem('raven') and plr) then return end
		bedwars.Handler:Get('SpawnRaven'):Fire('CallServerAsync'):andThen(function(projectile)
			if not (projectile and projectile.PrimaryPart) then return end
			local bodyforce = Instance.new('BodyForce')
			bodyforce.Force = Vector3.new(0, projectile.PrimaryPart.AssemblyMass * workspace.Gravity, 0)
			bodyforce.Parent = projectile.PrimaryPart
			task.spawn(function()
				for _ = 1, 20 do
					if plr.RootPart and projectile.Parent then
						projectile:SetPrimaryPartCFrame(CFrame.lookAlong(plr.RootPart.Position, gameCamera.CFrame.LookVector))
					end
					task.wait(0.05)
				end
			end)
			task.wait(0.3)
			bedwars.RavenController:detonateRaven()
		end)
	end

	RavenAura = kits:CreateModule({
		Name = 'RavenAura',
		Category = 'Ability',
		Function = function(callback)
			if callback then
				nextAction = 0
				repeat
					if entitylib.isAlive and util.IsKit('raven') and tick() >= nextAction then
						local range = math.max(Transform.Enabled and TransformRange.Value or 0, Send.Enabled and SendRange.Value or 0)
						local target = range > 0 and entitylib.EntityPosition({
							Origin = entitylib.character.RootPart.Position,
							Range = range,
							Part = 'RootPart',
							Players = true,
							Wallcheck = true
						}) or nil

						if target and Transform.Enabled and util.Ability.Ready('raven_transform') then
							nextAction = tick() + Delay.Value
							util.Ability.Use('raven_transform')
						elseif target and Send.Enabled and util.Ability.Ready('raven_send_request') then
							nextAction = tick() + Delay.Value
							util.Ability.Use('raven_send_request')
						end
					end
					task.wait(0.1)
				until not RavenAura.Enabled
			end
		end,
		Tooltip = 'Transforms into the raven or sends it at nearby enemies'
	})
	Transform = RavenAura:CreateToggle({
		Name = 'Auto transform',
		Default = false,
		Function = function(callback)
			show(TransformRange, callback)
		end
	})
	TransformRange = RavenAura:CreateSlider({
		Name = 'Transform range',
		Visible = false,
		Min = 1,
		Max = 80,
		Default = 30,
		Darker = true,
		Suffix = util.Studs
	})
	Send = RavenAura:CreateToggle({
		Name = 'Auto send',
		Default = true,
		Function = function(callback)
			show(SendRange, callback)
		end
	})
	SendRange = RavenAura:CreateSlider({
		Name = 'Send range',
		Min = 1,
		Max = 100,
		Default = 50,
		Darker = true,
		Suffix = util.Studs
	})
	Delay = RavenAura:CreateSlider({
		Name = 'Delay',
		Min = 0.1,
		Max = 5,
		Default = 0.5,
		Decimal = 10,
		Suffix = util.Seconds
	})
	RavenAura:CreateButton({
		Name = 'Teleport raven',
		Function = teleportRaven,
		Tooltip = 'Flies a raven onto the player nearest your cursor'
	})
end)

-- ===== Kits/RegentAxeExtender.lua =====
run(function()
	local VoidRegentExtender
	local Multiplier
	
	local old
	
	VoidRegentExtender = vape.Categories.Kits:CreateModule({
		Name = 'RegentAxeExtender',
		Function = function(callback)
			if callback then
				old = bedwars.VoidAxeController.useVoidAxe
				bedwars.VoidAxeController.useVoidAxe = function(self)
					local dashed = bedwars.AbilityController:canUseAbility('void_axe_jump', {disableBlockedAbilityAlert = true})
					local call = old(self)
	
					if dashed and store.equippedKit == 'regent' and entitylib.isAlive then
						local root = entitylib.character.RootPart
						root:ApplyImpulse(root.CFrame.LookVector * Vector3.new(1, 0, 1) * root.AssemblyMass * (Multiplier.Value - 1) * 70)
					end
					return call
				end
			else
				bedwars.VoidAxeController.useVoidAxe = old
			end
		end,
		Tooltip = 'Extends how far the Void Regent axe dash launches you'
	})
	Multiplier = VoidRegentExtender:CreateSlider({
		Name = 'Multiplier',
		Min = 1,
		Max = 5,
		Default = 2,
		Decimal = 10,
		Suffix = 'x'
	})
end)

-- ===== Kits/SigridDisabler.lua =====
run(function()
	local SigridDisabler
	local elkCtrl = nil
	local modMaid = nil
	local sentMount = false

	local function getElk()
		local ok, Knit = pcall(function()
			return require(game.ReplicatedStorage.rbxts_include.node_modules['@easy-games'].knit.src).KnitClient
		end)
		if not ok or not Knit then return nil end
		return Knit.Controllers.ElkMasterController
	end

	SigridDisabler = vape.Categories.Kits:CreateModule({
		Name = 'Sigrid Disabler',
		Function = function(callback)
			if callback then
				elkCtrl = getElk()
				if not elkCtrl then
					notif('Sigrid Disabler', 'u aint on sigrid gng', 5, 'alert')
					task.defer(function()
						if SigridDisabler.Enabled then
							SigridDisabler:Toggle()
						end
					end)
					return
				end

				sentMount = false
				pcall(function()
					local Knit = require(game.ReplicatedStorage.rbxts_include.node_modules['@easy-games'].knit.src).KnitClient
					local Maid = require(game.ReplicatedStorage.rbxts_include.node_modules['@rbxts'].maid.Maid)
					modMaid = Maid.new()
					modMaid:GiveTask(Knit.Controllers.SprintController:getMovementStatusModifier():addModifier({
						blockSprint = false,
						moveSpeedMultiplier = 1.5
					}))
					modMaid:GiveTask(Knit.Controllers.JumpHeightController:getJumpModifier():addModifier({
						jumpHeightMultiplier = 1.6
					}))
				end)

				local lastForce = 0
				SigridDisabler:Clean(runService.Heartbeat:Connect(function()
					if not elkCtrl or not SigridDisabler.Enabled then return end
					if (tick() - lastForce) < 0.25 then return end
					lastForce = tick()
					pcall(function()
						elkCtrl.isMounted = true
						if elkCtrl.summonAbilityMaid then
							elkCtrl.summonAbilityMaid:DoCleaning()
							elkCtrl.summonAbilityMaid = nil
						end
						local Knit = require(game.ReplicatedStorage.rbxts_include.node_modules['@easy-games'].knit.src).KnitClient
						Knit.Controllers.BlockPlacementController:enableBlockPlacer()
					end)
				end))

				task.spawn(function()
					repeat
						if entitylib.isAlive and store.equippedKit == 'elk_master' then
							if not sentMount then
								sentMount = true
								pcall(function()
									bedwars.Client:Get('ElkKitMounted'):SendToServer()
								end)
							end
						else
							sentMount = false
						end
						task.wait(0.5)
					until not SigridDisabler.Enabled
				end)
			else
				sentMount = false
				if modMaid then
					pcall(function() modMaid:DoCleaning() end)
					modMaid = nil
				end
				if elkCtrl then
					pcall(function() elkCtrl.isMounted = false end)
					pcall(function()
						if elkCtrl.summonAbilityMaid then
							elkCtrl.summonAbilityMaid:DoCleaning()
							elkCtrl.summonAbilityMaid = nil
						end
						if elkCtrl.playerModifierMaid then
							elkCtrl.playerModifierMaid:DoCleaning()
							elkCtrl.playerModifierMaid = nil
						end
					end)
					pcall(function()
						local Knit = require(game.ReplicatedStorage.rbxts_include.node_modules['@easy-games'].knit.src).KnitClient
						Knit.Controllers.SwordController:toggleSwordSwing(false)
						Knit.Controllers.BlockPlacementController:enableBlockPlacer()
					end)
					pcall(function()
						local MountType = require(game.ReplicatedStorage.TS.mount['mount-type']).MountType
						bedwars.Client:Get('Dismount'):SendToServer({mountType = MountType.ELK})
					end)
					pcall(function()
						bedwars.Client:Get('Dismount'):SendToServer({mountType = 'elk'})
					end)
				end
				elkCtrl = nil
			end
		end
	})
end)

-- ===== Kits/TerraAimbot.lua =====
run(function()
	local Main = vape.Libraries.mergedModule(kits, {
		Name = 'TerraAimbot',
		Category = 'Aim',
		Tooltip = 'Steers terra blocks at targets, kicks blocks and stomps'
	})

run(function()
    local TerraAimbot
    local Range
    local Mode
    local Sort

    local old

    TerraAimbot = Main:Part({
		Label = 'Aimbot',
        Name = 'TerraAimbot',
        Category = 'Aim',
        Function = function(callback)
            if callback then
                old = bedwars.BlockKickerKitController.getKickBlockProjectileOriginPosition
                local hook
                hook = function(...)
                    if not TerraAimbot.Enabled then return old(...) end
                    local origin, dir = select(2, ...)
                    local plr = entitylib['Entity'.. Mode.Value]({
                        Part = 'RootPart',
                        Range = Range.Value,
                        Origin = origin,
                        Players = true,
                        Wallcheck = true,
                        Sort = sortmethods[Sort.Value]
                    })

                    if plr then
                        local calc = prediction.SolveTrajectory(origin, 100, 20, plr.RootPart.Position, plr.RootPart.Velocity, workspace.Gravity, plr.HipHeight, plr.Jumping and 42.6 or nil, nil, plr.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(plr.RootPart.AssemblyLinearVelocity.Y) > 0.01, plr.RootPart.Position, plr.RootPart, nil, true)

                        if calc then
                            for i, v in debug.getstack(2) do
                                if v == dir then
                                    debug.setstack(2, i, CFrame.lookAt(origin, calc).LookVector)
                                end
                            end
                        end
                    end

                    return old(...)
                end
                bedwars.BlockKickerKitController.getKickBlockProjectileOriginPosition = hook
                TerraAimbot:Clean(function()
                    if bedwars.BlockKickerKitController.getKickBlockProjectileOriginPosition == hook then
                        bedwars.BlockKickerKitController.getKickBlockProjectileOriginPosition = old
                    end
                end)
            end
        end,
        Tooltip = 'Silently steers terra blocks at targets'
    })

    Mode = TerraAimbot:CreateDropdown({
        Name = 'Mode',
        List = {'Position', 'Mouse'},
        Default = 'Mouse'
    })
    local methods = {'Distance', 'Damage'}
    for _, v in sortlist do
        if not table.find(methods, v) then
            table.insert(methods, v)
        end
    end
    Sort = TerraAimbot:CreateDropdown({
        Name = 'Target mode',
        List = methods,
        Tooltip = TARGET_MODE_TOOLTIP
    })
    Range = TerraAimbot:CreateSlider({
        Name = 'Range',
        Min = 1,
        Max = 1000,
        Default = 1000,
        Suffix = function(val)
            return val <= 1 and 'studs' or 'stud'
        end
    })
end)

run(function()
	local util = vape.Libraries.bedwarsutil
	local AutoBlockKicker
	local Kick
	local KickRange
	local KickDelay
	local Stomp
	local StompTargets
	local StompRange
	local StompDelay
	local nextKick, nextStomp = 0, 0

	local function show(option, visible)
		if option and option.Object then option.Object.Visible = visible end
	end

	AutoBlockKicker = Main:Part({
		Label = 'Auto kick and stomp',
		Name = 'AutoBlockKicker',
		Function = function(callback)
			if callback then
				nextKick, nextStomp = 0, 0
				repeat
					if entitylib.isAlive and util.IsKit('block_kicker') then
						if Kick.Enabled and tick() >= nextKick and util.Ability.Ready('BLOCK_KICK') then
							local target = entitylib.EntityPosition({
								Origin = entitylib.character.RootPart.Position,
								Range = KickRange.Value,
								Part = 'RootPart',
								Players = true,
								Wallcheck = true
							})
							if target then
								nextKick = tick() + KickDelay.Value
								util.Ability.Use('BLOCK_KICK')
							end
						end
						if Stomp.Enabled and tick() >= nextStomp and util.Ability.Ready('BLOCK_STOMP') then
							local found = #entitylib.AllPosition({
								Origin = entitylib.character.RootPart.Position,
								Range = StompRange.Value,
								Part = 'RootPart',
								Players = true
							})
							if found >= StompTargets.Value then
								nextStomp = tick() + StompDelay.Value
								util.Ability.Use('BLOCK_STOMP')
							end
						end
					end
					task.wait(0.1)
				until not AutoBlockKicker.Enabled
			end
		end,
		Tooltip = 'Kicks blocks at enemies and stomps when surrounded'
	})
	Kick = AutoBlockKicker:CreateToggle({
		Name = 'Auto kick',
		Default = true,
		Function = function(callback)
			show(KickRange, callback)
			show(KickDelay, callback)
		end
	})
	KickRange = AutoBlockKicker:CreateSlider({
		Name = 'Kick range',
		Min = 1,
		Max = 60,
		Default = 25,
		Darker = true,
		Suffix = util.Studs
	})
	KickDelay = AutoBlockKicker:CreateSlider({
		Name = 'Kick delay',
		Min = 0.1,
		Max = 5,
		Default = 0.5,
		Decimal = 10,
		Darker = true,
		Suffix = util.Seconds
	})
	Stomp = AutoBlockKicker:CreateToggle({
		Name = 'Auto stomp',
		Default = true,
		Function = function(callback)
			show(StompTargets, callback)
			show(StompRange, callback)
			show(StompDelay, callback)
		end
	})
	StompTargets = AutoBlockKicker:CreateSlider({
		Name = 'Stomp targets',
		Min = 1,
		Max = 8,
		Default = 2,
		Darker = true
	})
	StompRange = AutoBlockKicker:CreateSlider({
		Name = 'Stomp range',
		Min = 1,
		Max = 60,
		Default = 20,
		Darker = true,
		Suffix = util.Studs
	})
	StompDelay = AutoBlockKicker:CreateSlider({
		Name = 'Stomp delay',
		Min = 0.1,
		Max = 5,
		Default = 0.5,
		Decimal = 10,
		Darker = true,
		Suffix = util.Seconds
	})
end)

end)

-- ===== Kits/TritonClutch.lua =====
run(function()
	local Entity = entitylib
	local GetHotbar = getHotbar
	local GetItem = getItem
	local HotbarSwitch = hotbarSwitch
	local PredictionLib = prediction
	local ReplicatedStorage = replicatedStorage
	local Store = store
	local SwitchItem = switchItem
	local TritonClutch
	local Legit
	local Back
	local LandCheck
	local BackDelay
	local Limit
	local FallSpeed
	local Search
	local Recall
	local NextFire: number = 0
	local virtualInputManager = cloneref(game:GetService('VirtualInputManager'))

	local RayCheck: RaycastParams = RaycastParams.new()
	RayCheck.RespectCanCollide = true
	RayCheck.FilterType = Enum.RaycastFilterType.Include

	local function GetHarpoon()
		return GetItem("harpoon") or GetItem("triton_harpoon") or GetItem("trident")
	end

	local function IsHarpoon(tool)
		local name = tool and tool.Name and tool.Name:lower()
		return name == "harpoon" or name == "trident" or name == "triton_harpoon"
	end

	local function GetNearGround(Origin: Vector3)
		for Step: number = 1, Search.Value do
			for _, v: Vector3 in {Vector3.xAxis, Vector3.zAxis, -Vector3.xAxis, -Vector3.zAxis} do
				local RayResult: RaycastResult? = workspace:Raycast((Origin + Vector3.new(0, 3, 0)) + (v * Step), Vector3.new(0, -80, 0), RayCheck)
				if RayResult then
					return RayResult.Position
				end
			end
		end
		return nil
	end

	local function WaitForClutch()
		local started = tick()
		repeat
			task.wait()
			local root = Entity.isAlive and Entity.character.RootPart
			if root and root.AssemblyLinearVelocity.Y > -10 then
				return true
			end
		until not TritonClutch.Enabled or tick() - started > 3
		return false
	end

	local function RecallHome()
		task.wait(1.25)
		virtualInputManager:SendKeyEvent(true, Enum.KeyCode.C, false, game)
		task.wait()
		virtualInputManager:SendKeyEvent(false, Enum.KeyCode.C, false, game)
		local started, lastPosition, stable = tick(), nil, 0
		repeat
			task.wait(0.1)
			local root = Entity.isAlive and Entity.character.RootPart
			if root then
				local moved = lastPosition and (root.Position - lastPosition).Magnitude or math.huge
				if tick() - started > 0.75 and moved < 1 and root.AssemblyLinearVelocity.Magnitude < 8 then
					stable += 0.1
					if stable >= 0.3 then return true end
				else
					stable = 0
				end
				lastPosition = root.Position
			end
		until not TritonClutch.Enabled or tick() - started > 7
		return false
	end

	local function FireHarpoon(Item, Spot: Vector3)
		local Meta = bedwars.ProjectileMeta.harpoon_projectile
		local Source = bedwars.ItemMeta[Item.itemType].projectileSource
		local Origin: Vector3 = Entity.character.RootPart.Position
		local Speed, Gravity = Meta.launchVelocity, Meta.gravitationalAcceleration or 196.2
		local ShootPosition: Vector3 = (CFrame.new(Origin, Spot) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ))).Position
		local AimPoint: Vector3? = PredictionLib.SolveTrajectory(ShootPosition, Speed, Gravity, Spot, Vector3.zero, workspace.Gravity, 0, nil, nil, false, Spot)
		if not AimPoint then
			return false
		end

		local Hotbar, Previous = GetHotbar(Item.tool), Store.hand.tool
		SwitchItem(Item.tool)
		if Legit.Enabled and Hotbar then
			HotbarSwitch(Hotbar)
		end

		NextFire = tick() + (Source and Source.fireDelaySec or 8)
		bedwars.Handler:Get("ProjectileFire"):Fire("CallServerAsync",
			Item.tool,
			nil,
			Source and Source.projectileType(Item.itemType) or "harpoon_projectile",
			ShootPosition,
			Origin,
			CFrame.lookAt(ShootPosition, AimPoint).LookVector * Speed,
			bedwars.IdUtil.generateId(8),
			bedwars.getShotData(Item.itemType),
			workspace:GetServerTimeNow() - 0.045
		):andThen(function(Result)
			if type(Result) == "table" and Result.accepted and Result.model then
				Result.model.Parent = ReplicatedStorage
			end
		end)

		if Back.Enabled and Previous then
			if LandCheck.Enabled then WaitForClutch() end
			if Recall.Enabled then
				RecallHome()
			else
				task.wait(BackDelay:GetRandomValue())
			end
			SwitchItem(Previous)
			if Legit.Enabled and GetHotbar(Previous) then
				HotbarSwitch(GetHotbar(Previous))
			end
		elseif Recall.Enabled then
			task.spawn(RecallHome)
		end
		return true
	end

	TritonClutch = kits:CreateModule({
		Name = "TritonClutch",
		Category = "Ability",
		Function = function(Callback: boolean)
			if Callback then
				NextFire = 0
				local LastGround: Vector3?

				repeat
					if Entity.isAlive and tick() >= NextFire and (not Limit.Enabled or IsHarpoon(Store.hand.tool)) then
						local Root: BasePart = Entity.character.RootPart
						local Harpoon = GetHarpoon()
						RayCheck.FilterDescendantsInstances = {Store.map}
						RayCheck.CollisionGroup = Root.CollisionGroup

						if Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air then
							LastGround = Root.Position
						end

						if Harpoon and Root.AssemblyLinearVelocity.Y < -FallSpeed.Value and not workspace:Raycast(Root.Position, Vector3.new(0, -200, 0), RayCheck) then
							local Spot: Vector3? = GetNearGround(Root.Position + Vector3.new(0, 40, 0)) or LastGround and GetNearGround(LastGround + Vector3.new(0, 5, 0))
							if Spot then
								FireHarpoon(Harpoon, Spot)
							end
						end
					end
					task.wait(0.1)
				until not TritonClutch.Enabled
			end
		end,
		Tooltip = 'Throws the harpoon onto nearby ground when falling into the void'
	})

	FallSpeed = TritonClutch:CreateSlider({
		Name = "Fall speed",
		Min = 10,
		Max = 200,
		Default = 60,
		Suffix = "studs a second",
		Tooltip = 'How fast you must be falling before it acts'
	})
	Search = TritonClutch:CreateSlider({
		Name = "Search range",
		Min = 4,
		Max = 60,
		Default = 40,
		Suffix = function(Val: number)
			return Val <= 1 and "stud" or "studs"
		end,
		Tooltip = 'How far it looks for ground to land on'
	})
	Legit = TritonClutch:CreateToggle({
		Name = "Legit Switch",
		Default = true,
		Tooltip = 'Visibly switches items on your hotbar'
	})
	Back = TritonClutch:CreateGroup({
		Name = "Switch back",
		Default = true,
		Tooltip = 'Switches back to your last item afterwards'
	})
	LandCheck = Back:CreateToggle({
		Name = "Only after clutch",
		Darker = true,
		Tooltip = 'Only switches back after a clutch'
	})
	BackDelay = Back:CreateTwoSlider({
		Name = "Switch Back Delay",
		Min = 0,
		Max = 2,
		DefaultMin = 0.1,
		DefaultMax = 0.2,
		Darker = true
	})
	Limit = TritonClutch:CreateToggle({
		Name = "Limit to items",
		Tooltip = 'Only works while holding the item it uses'
	})
	Recall = TritonClutch:CreateToggle({
		Name = "Recall",
		Tooltip = 'Recalls to base after a clutch'
	})
end)

-- ===== Kits/TrixieDisabler.lua =====
run(function()
	local Main = vape.Libraries.mergedModule(kits, {
		Name = 'TrixieDisabler',
		Category = 'Ability',
		Tooltip = 'Controls your clone while warping, warps onto targets and removes the cooldown'
	})

run(function()
	local TrixieDisabler
	local KeepClose, CloseDistance
	local STALL_TIMEOUT = 3
	local previousClonePosition
	local realRoot, character, humanoid, clone
	local diedConnection
	local savedHipHeight, savedTransparency, savedCanCollide, savedCanQuery, savedQueryIgnored
	local warping, awaitingRewind, rewindRequested, rewinding = false, false, false, false
	local warpTimeout, phaseEnd, nextAction, rewindReadyAt = 0, 0, 0, 0

	local function snapToClone()
		local target = clone.CFrame
		local offset = target.Position - realRoot.Position
		if offset.Magnitude > 100 then
			target = CFrame.new(realRoot.Position + offset.Unit * 100) * target.Rotation
		end
		realRoot.CFrame = target
	end

	local function release(moveToClone)
		if not realRoot then return end
		if diedConnection then
			diedConnection:Disconnect()
			diedConnection = nil
		end

		if realRoot.Parent and character.Parent then
			local velocity = realRoot.AssemblyLinearVelocity
			character.Parent = replicatedStorage
			realRoot.Parent = character
			if clone then
				if moveToClone then
					snapToClone()
					velocity = clone.AssemblyLinearVelocity
				end
				clone:Destroy()
			end
			character.PrimaryPart = realRoot
			character.Parent = workspace
			realRoot.Transparency = savedTransparency
			realRoot.CanCollide = savedCanCollide
			bedwars.QueryUtil:setQueryIgnored(realRoot, savedQueryIgnored)
			realRoot.CanQuery = savedCanQuery
			if humanoid.Parent then
				humanoid.HipHeight = savedHipHeight
			end
			realRoot.AssemblyLinearVelocity = velocity
			local entity = entitylib.character
			if entity and entity.Character == character then
				entity.HumanoidRootPart = realRoot
				entity.RootPart = realRoot
			end
		else
			if clone then clone:Destroy() end
			if realRoot.Parent then realRoot:Destroy() end
		end

		if store.rootpart == realRoot then
			store.rootpart = nil
		end
		realRoot, character, clone, humanoid = nil, nil, nil, nil
		previousClonePosition = nil
		warping, awaitingRewind, rewindRequested, rewinding = false, false, false, false
		warpTimeout, phaseEnd, nextAction, rewindReadyAt = 0, 0, 0, 0
	end

	local function capture()
		if realRoot or store.rootpart or vape.MovementOwner or not entitylib.isAlive or store.equippedKit ~= 'void_walker' then
			return false
		end
		local char = lplr.Character
		if not char or not char.Parent or entitylib.character.Character ~= char or entitylib.character.Humanoid.Health <= 0 then
			return false
		end
		local controller = bedwars.VoidWalkerKitController
		if controller.playerWarpDataMap[lplr] or controller.playerBeamOriginOverrideMap[lplr]
			or not bedwars.AbilityController:canUseAbility('void_walker_warp', {disableBlockedAbilityAlert = true}) then
			return false
		end
		local root = entitylib.character.Humanoid.RootPart
		if not root or root.Parent ~= char then
			return false
		end

		character, realRoot, humanoid = char, root, entitylib.character.Humanoid
		savedTransparency = realRoot.Transparency
		savedHipHeight = humanoid.HipHeight
		savedCanQuery = realRoot.CanQuery
		savedCanCollide = realRoot.CanCollide
		savedQueryIgnored = bedwars.QueryUtil:isQueryIgnored(realRoot)

		character.Parent = replicatedStorage
		clone = realRoot:Clone()
		clone.Parent = character
		realRoot.Transparency = 1
		realRoot.Parent = workspace
		clone.AssemblyLinearVelocity = realRoot.AssemblyLinearVelocity
		realRoot.AssemblyLinearVelocity = Vector3.zero
		realRoot.AssemblyAngularVelocity = Vector3.zero
		store.rootpart = realRoot
		character.PrimaryPart = clone
		character.Parent = workspace
		bedwars.QueryUtil:setQueryIgnored(clone, true)
		bedwars.QueryUtil:setQueryIgnored(realRoot, true)

		diedConnection = humanoid.Died:Connect(function()
			if character == char then
				release()
			end
		end)
		return true
	end

	TrixieDisabler = Main:Part({
		Label = 'Disabler',
		Name = 'TrixieDisabler',
		Category = 'Ability',
		Function = function(callback)
			if not callback then return end

			local controller = bedwars.VoidWalkerKitController
			local balance = require(replicatedStorage.TS.games.bedwars.kit.kits['void-walker']['void-walker-kit-balance']).VoidWalkerKitBalance
			local gameWorldUtil = require(replicatedStorage.TS.util['game-world-util']).GameWorldUtil
			local warpRemote = bedwars.Client:Get('VoidWalker_ClientUsedWarpAbility')
			local old = {
				teleportPlayer = controller.teleportPlayer,
				useWarpAbility = controller.useWarpAbility,
				createPortal = controller.createPortal,
				playPortalOpenSound = controller.playPortalOpenSound,
				playPortalCloseSound = controller.playPortalCloseSound,
				enableBeam = controller.enableBeam,
				onAbilityUsed = controller.onAbilityUsed
			}
			local oldAddAbilityButton = bedwars.AbilityController.addAbilityButton
			local damageBuff = require(replicatedStorage.TS['status-effect']['status-effect-meta']).StatusEffectMeta.void_walker_damage_buff
			local oldNoDisplay = damageBuff and damageBuff.noDisplay
			local active = true
			local hiddenPortals, hiddenCount = {}, 0

			local function ownPortal(position)
				if not realRoot or typeof(position) ~= 'Vector3' then return false end
				if realRoot.Parent and (position - realRoot.Position).Magnitude <= balance.WARP_DISTANCE + 5 then
					return true
				end
				return clone ~= nil and clone.Parent ~= nil and (position - clone.Position).Magnitude <= 15
			end

			TrixieDisabler:Clean(function()
				active = false
				for name, fn in old do controller[name] = fn end
				table.clear(hiddenPortals)
				if damageBuff then damageBuff.noDisplay = oldNoDisplay end
				bedwars.AbilityController.addAbilityButton = oldAddAbilityButton
				local rewind = bedwars.AbilityController:getEnabledAbility('void_walker_rewind')
				if rewind then
					oldAddAbilityButton(bedwars.AbilityController, rewind)
				end
				release(humanoid and humanoid.Health > 0 and lplr.Character == character)
			end)

			if damageBuff then damageBuff.noDisplay = true end

			bedwars.AbilityController.addAbilityButton = function(self, ability, ...)
				if ability.abilityId == 'void_walker_rewind' then return end
				return oldAddAbilityButton(self, ability, ...)
			end
			if controller.rewindUIMaid then
				controller.rewindUIMaid:DoCleaning()
			end
			for _, object in lplr.PlayerGui:GetDescendants() do
				if object.Name == 'void_walker_rewind' and object:IsA('GuiObject') then
					local visible = object.Visible
					object.Visible = false
					TrixieDisabler:Clean(function()
						if object.Parent then object.Visible = visible end
					end)
				end
			end

			controller.onAbilityUsed = function(self, player, data, ...)
				if active and realRoot and type(data) == 'table' and data.ability == 'void_walker_warp' then return end
				return old.onAbilityUsed(self, player, data, ...)
			end
			controller.createPortal = function(self, position, ...)
				if active and ownPortal(position) then
					if hiddenCount >= 32 then
						table.clear(hiddenPortals)
						hiddenCount = 0
					end
					hiddenPortals[position] = true
					hiddenCount += 1
					return Instance.new('Model')
				end
				return old.createPortal(self, position, ...)
			end
			controller.playPortalOpenSound = function(self, position, ...)
				if active and (hiddenPortals[position] or ownPortal(position)) then return end
				return old.playPortalOpenSound(self, position, ...)
			end
			controller.playPortalCloseSound = function(self, position, ...)
				if active and (hiddenPortals[position] or ownPortal(position)) then return end
				return old.playPortalCloseSound(self, position, ...)
			end
			controller.enableBeam = function(self, beam, ...)
				if active and realRoot and beam == self.playerBeamMap[lplr] then return end
				return old.enableBeam(self, beam, ...)
			end
			for _, portal in controller.portals do
				if portal.Parent then portal.Parent = replicatedStorage end
			end
			controller.teleportPlayer = function(self, player, a, b, delay, skip, ...)
				if active and realRoot and lplr.Character == character and player == lplr then
					if not skip then
						warping, awaitingRewind = true, true
						phaseEnd = os.clock() + math.max(delay, 0) + 0.2
						warpTimeout = phaseEnd + STALL_TIMEOUT
					end
					return
				end
				return old.teleportPlayer(self, player, a, b, delay, skip, ...)
			end
			controller.useWarpAbility = function(self, player, ...)
				local ownClone = active and player == lplr and lplr.Character == character and clone
				local velocity = ownClone and ownClone.AssemblyLinearVelocity
				local result = old.useWarpAbility(self, player, ...)
				if active and player == lplr and self.rewindUIMaid then
					self.rewindUIMaid:DoCleaning()
				end
				if ownClone and ownClone == clone and ownClone.Parent then
					ownClone.AssemblyLinearVelocity = velocity
				end
				return result
			end

			TrixieDisabler:Clean(bedwars.Client:Get('VoidWalker_Rewind'):Connect(function(data)
				if active and warping and rewindRequested and realRoot and lplr.Character == character and data.player == lplr then
					rewinding = true
					phaseEnd = os.clock() + math.max(data.endTime - workspace:GetServerTimeNow(), 0)
					rewindReadyAt = data.endTime + balance.REWIND_COOLDOWN
					warpTimeout = phaseEnd + STALL_TIMEOUT
				end
			end))
			TrixieDisabler:Clean(lplr.CharacterRemoving:Connect(function(char)
				if active and character == char then release() end
			end))

			TrixieDisabler:Clean(runService.Heartbeat:Connect(function()
				if not active then return end
				if not realRoot then
					capture()
					return
				end
				if lplr.Character ~= character or not character.Parent or not realRoot.Parent or not clone.Parent
					or humanoid.Health <= 0 or store.equippedKit ~= 'void_walker' or vape.MovementOwner then
					release()
					return
				end
				realRoot.AssemblyLinearVelocity = Vector3.zero
				realRoot.AssemblyAngularVelocity = Vector3.zero
				local now = os.clock()

				local clonePosition = clone.Position
				if KeepClose.Enabled and previousClonePosition then
					local offset = clonePosition - realRoot.Position
					local flat = Vector3.new(offset.X, 0, offset.Z)
					local excess = flat.Magnitude - CloseDistance.Value
					if excess > 0 then
						local away = flat.Unit
						local moved = clonePosition - previousClonePosition
						local outward = moved:Dot(away)
						if outward > 0 and outward < 50 then
							local keep = math.clamp(1 - excess / CloseDistance.Value, 0.35, 1)
							clone.CFrame -= away * outward * (1 - keep)
							clonePosition = clone.Position
						end
					end
				end
				previousClonePosition = clonePosition

				if rewinding and now >= phaseEnd then
					controller:disablePlayerBeam(lplr)
					warping, awaitingRewind, rewindRequested, rewinding = false, false, false, false
					nextAction = now
				end
				if warping and now >= warpTimeout then
					warping, awaitingRewind, rewindRequested, rewinding = false, false, false, false
					nextAction = now + 0.1
					return
				end

				if not awaitingRewind and not rewinding then
					if not warping and controller.playerWarpDataMap[lplr] then
						warping, awaitingRewind = true, true
						phaseEnd, warpTimeout = now, now + STALL_TIMEOUT
					elseif now >= nextAction and not controller.playerWarpDataMap[lplr] and not controller.playerBeamOriginOverrideMap[lplr]
						and bedwars.AbilityController:canUseAbility('void_walker_warp', {disableBlockedAbilityAlert = true}) then
						local camera = workspace.CurrentCamera
						if not camera then return end
						local origin = realRoot.Position
						local offset = clone.Position - origin
						local direction = offset.Magnitude > 0.1 and offset.Unit or camera.CFrame.LookVector
						local distance = math.clamp(offset.Magnitude, 1, balance.WARP_DISTANCE)
						local hit = gameWorldUtil.raycastWithOnlyWorldCollision(origin, direction, distance)
						if not warping then warpTimeout = now + STALL_TIMEOUT end
						warping = true
						nextAction = now + 0.1
						warpRemote:SendToServer({
							clientStartPosition = origin,
							direction = direction,
							clientDestinationPosition = hit and hit.Position or origin + direction * distance
						})
					end
				elseif awaitingRewind and not rewinding and now >= phaseEnd and workspace:GetServerTimeNow() >= rewindReadyAt
					and (not rewindRequested or now >= nextAction)
					and bedwars.AbilityController:getEnabledAbility('void_walker_rewind')
					and bedwars.AbilityController:canUseAbility('void_walker_rewind', {disableBlockedAbilityAlert = true}) then
					if not rewindRequested then warpTimeout = now + STALL_TIMEOUT end
					rewindRequested = true
					nextAction = now + 0.1
					bedwars.AbilityController:useAbility('void_walker_rewind')
				end
			end))

			capture()
		end,
		Tooltip = 'Repeats Warp and Rewind so you can move freely as your clone'
	})
	KeepClose = TrixieDisabler:CreateGroup({
		Name = 'Keep close',
		Default = true,
		Tooltip = 'Slows your clone so your camera stays close'
	})
	CloseDistance = KeepClose:CreateSlider({
		Name = 'Close distance',
		Min = 10,
		Max = 100,
		Default = 30,
		Suffix = 'studs',
		Tooltip = 'How far your clone can get ahead before slowing down'
	})
end)

run(function()

	local util = vape.Libraries.bedwarsutil
	local AutoTrixie
	local Targets
	local Warp
	local WarpRange
	local Rewind
	local Health
	local nextAbility = 0

	AutoTrixie = Main:Part({
		Label = 'Auto warp',
		Name = 'AutoTrixie',
		Function = function(callback)
			if callback then
				nextAbility = 0

				repeat
					if entitylib.isAlive and store.equippedKit == 'void_walker' and tick() >= nextAbility then
						local humanoid = entitylib.character.Humanoid

						if Rewind.Enabled and humanoid.Health <= (humanoid.MaxHealth * (Health.Value / 100)) and bedwars.AbilityController:canUseAbility('void_walker_rewind', {disableBlockedAbilityAlert = true}) then
							nextAbility = tick() + 1
							bedwars.AbilityController:useAbility('void_walker_rewind')
						elseif Warp.Enabled and bedwars.AbilityController:canUseAbility('void_walker_warp', {disableBlockedAbilityAlert = true}) then
							local target = entitylib.EntityPosition({
								Range = WarpRange.Value,
								Part = 'RootPart',
								Players = Targets.Players.Enabled,
								NPCs = Targets.NPCs.Enabled,
								Wallcheck = Targets.Walls.Enabled,
								Sort = sortmethods.Distance
							})

							if target then
								local root = entitylib.character.RootPart
								root.CFrame = CFrame.lookAlong(root.Position, (target.RootPart.Position - root.Position) * Vector3.new(1, 0, 1))
								nextAbility = tick() + 1
								bedwars.AbilityController:useAbility('void_walker_warp')
							end
						end
					end
					task.wait(0.1)
				until not AutoTrixie.Enabled
			end
		end,
		Tooltip = 'Warps you onto your target and back out when in danger'
	})

	Targets = AutoTrixie:CreateTargets({
		Players = true,
		NPCs = true,
		Walls = true
	})
	Warp = AutoTrixie:CreateGroup({
		Name = 'Warp to target',
		Default = true,
		Tooltip = 'Faces the closest enemy before warping'
	})
	WarpRange = Warp:CreateSlider({
		Name = 'Warp range',
		Min = 5,
		Max = 80,
		Default = 40,
		Suffix = util.Studs
	})
	Rewind = AutoTrixie:CreateGroup({
		Name = 'Rewind on low health',
		Default = true,
	})
	Health = Rewind:CreateSlider({
		Name = 'Health',
		Min = 1,
		Max = 100,
		Default = 40,
		Suffix = '%'
	})
end)

run(function()
	local InfiniteTrixie
	local oldSetOnCooldown
	local oldUseAbility

	InfiniteTrixie = Main:Part({
		Label = 'No warp cooldown',
		Name = 'InfiniteTrixie',
		Category = 'Ability',
		Function = function(callback)
			local abilities = bedwars.AbilityController
			if callback then
				local cooldowns = abilities.cooldownController
				oldSetOnCooldown = cooldowns.setOnCooldown
				cooldowns.setOnCooldown = function(self, ability, ...)
					if ability == 'void_walker_warp' then return end
					return oldSetOnCooldown(self, ability, ...)
				end

				oldUseAbility = abilities.useAbility
				abilities.useAbility = function(self, ability, ...)
					if ability == 'void_walker_warp' then
						if lplr.Character and self:canUseAbility(ability) then
							bedwars.SyncEvents.AbilityUsed:fire(lplr.Character, ability, ...)
						end
						return
					end
					return oldUseAbility(self, ability, ...)
				end

				cooldowns:removeCooldown('void_walker_warp')
			else
				if oldSetOnCooldown then abilities.cooldownController.setOnCooldown = oldSetOnCooldown end
				if oldUseAbility then abilities.useAbility = oldUseAbility end
				oldSetOnCooldown, oldUseAbility = nil, nil
			end
		end,
		Tooltip = 'Removes Rift Warp\'s cooldown'
	})
end)

end)

-- ===== Kits/TurretRecall.lua =====
run(function()
	local TurretRecall
	local HPThreshold
	local recalled = {}
	local takeBackRemote = game:GetService('ReplicatedStorage'):WaitForChild('rbxts_include'):WaitForChild('node_modules'):WaitForChild('@rbxts'):WaitForChild('net'):WaitForChild('out'):WaitForChild('_NetManaged'):WaitForChild('TakeBackCameraTurret')

	local function getMaxHealth(turret)
		local ok, result = pcall(function()
			return bedwars.ItemMeta[turret.Name].block.health
		end)
		return (ok and result) or turret:GetAttribute('MaxHealth') or 50
	end

	local function getCurrentHealth(turret)
		local blockpos = bedwars.BlockController:getBlockPosition(turret.Position)
		local blockdata = bedwars.BlockController:getStore():getBlockData(blockpos)
		return (blockdata and (blockdata:GetAttribute('1') or blockdata:GetAttribute('Health'))) or turret:GetAttribute('Health') or 0
	end

	local function recallTurret(turret)
		if recalled[turret] then return end
		recalled[turret] = true
		local blockPos = bedwars.BlockController:getBlockPosition(turret.Position)
		pcall(function()
			takeBackRemote:FireServer({turretBlockPos = blockPos})
		end)
	end

	local function watchTurret(turret)
		if not (TurretRecall and TurretRecall.Enabled) then return end
		if turret:GetAttribute('PlacedByUserId') ~= lplr.UserId then return end
		local maxHp = getMaxHealth(turret)
		task.spawn(function()
			while turret and turret.Parent do
				task.wait(0.1)
				if not TurretRecall.Enabled then continue end
				local hp = getCurrentHealth(turret)
				local threshold = (HPThreshold.Value / 100) * maxHp
				if hp <= threshold then
					recallTurret(turret)
					break
				end
			end
		end)
		turret.AncestryChanged:Connect(function()
			if not turret.Parent then
				recalled[turret] = nil
			end
		end)
	end

	collectionService:GetInstanceAddedSignal('Turret'):Connect(watchTurret)
	for _, v in collectionService:GetTagged('Turret') do
		watchTurret(v)
	end

	TurretRecall = vape.Categories.Kits:CreateModule({
		Name = 'TurretRecall',
		Tooltip = 'picks up your turrent based off hp threshold'
	})
	HPThreshold = TurretRecall:CreateSlider({
		Name = 'HP Threshold',
		Min = 1,
		Max = 50,
		Default = 20,
		Suffix = function(v) return '%' end
	})
end)

