-- ===== Kits/VulcanAssist.lua =====
run(function()
	local util = vape.Libraries.bedwarsutil
	local VulcanAssist
	local Targets
	local Aim
	local Range
	local Sort
	local Mark
	local MarkRange
	local MarkDelay
	local nextMark = 0

	local function show(option, visible)
		if option and option.Object then option.Object.Visible = visible end
	end

	local function aimTurret()
		local turret = entitylib.isAlive and bedwars.Store:getState().Game.selectedTurret
		if not turret then return end
		local origin = turret.Rotate.Position
		local ent = entitylib.EntityMouse({
			Range = Range.Value,
			Origin = origin,
			Wallcheck = Targets.Walls.Enabled or nil,
			Part = 'RootPart',
			Players = Targets.Players.Enabled,
			Priority = Targets.Priority and Targets.Priority.Value,
			NPCs = Targets.NPCs.Enabled,
			Sort = sortmethods[Sort.Value]
		})
		local pos = ent and prediction.SolveTrajectory(origin, 320, 10, ent.RootPart.Position, ent.RootPart.AssemblyLinearVelocity, workspace.Gravity, ent.HipHeight, nil, store.airRay, ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(ent.RootPart.AssemblyLinearVelocity.Y) > 0.01, ent.RootPart.Position, ent.RootPart)
		if pos then
			local delta = pos - origin
			bedwars.TurretCameraController.angleX = math.atan2(-delta.X, -delta.Z)
			bedwars.TurretCameraController.angleY = math.clamp(math.atan2(delta.Y, math.sqrt(delta.X ^ 2 + delta.Z ^ 2)), -0.8, 0.8)
		end
	end

	local function markTarget()
		if not (entitylib.isAlive and util.IsKit('vulcan') and tick() >= nextMark and util.Ability.Ready('vulcan_artillery_mark')) then return end
		local target = entitylib.EntityPosition({
			Origin = entitylib.character.RootPart.Position,
			Range = MarkRange.Value,
			Part = 'RootPart',
			Players = true,
			Wallcheck = true
		})
		if target then
			nextMark = tick() + MarkDelay.Value
			util.Ability.Use('vulcan_artillery_mark', {target = target.RootPart.Position})
		end
	end

	VulcanAssist = kits:CreateModule({
		Name = 'VulcanAssist',
		Category = 'Aim',
		Function = function(callback)
			if callback then
				nextMark = 0
				repeat
					if Aim.Enabled then aimTurret() end
					if Mark.Enabled then markTarget() end
					task.wait(0.1)
				until not VulcanAssist.Enabled
			end
		end,
		Tooltip = 'Aims the turret and marks the closest enemy'
	})
	Targets = VulcanAssist:CreateTargets({Walls = true, Players = true})
	Aim = VulcanAssist:CreateToggle({
		Name = 'Aim turret',
		Default = true,
		Function = function(callback)
			show(Sort, callback)
			show(Range, callback)
		end
	})

	local methods = {'Distance', 'Damage'}
	for _, i in sortlist do
		if not table.find(methods, i) then
			table.insert(methods, i)
		end
	end

	Sort = VulcanAssist:CreateDropdown({
		Name = 'Target mode',
		List = methods,
		Default = methods[1],
		Darker = true,
		Tooltip = TARGET_MODE_TOOLTIP
	})
	Range = VulcanAssist:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 1000,
		Default = 500,
		Darker = true
	})
	Mark = VulcanAssist:CreateToggle({
		Name = 'Auto mark',
		Default = false,
		Tooltip = 'Marks the closest enemy when the ability is ready',
		Function = function(callback)
			show(MarkRange, callback)
			show(MarkDelay, callback)
		end
	})
	MarkRange = VulcanAssist:CreateSlider({
		Name = 'Mark range',
		Visible = false,
		Min = 1,
		Max = 150,
		Default = 60,
		Darker = true,
		Suffix = util.Studs
	})
	MarkDelay = VulcanAssist:CreateSlider({
		Name = 'Mark delay',
		Visible = false,
		Min = 0.1,
		Max = 10,
		Default = 2,
		Decimal = 10,
		Darker = true,
		Suffix = util.Seconds
	})
end)

-- ===== Kits/WhimAura.lua =====
run(function()
	local Main = vape.Libraries.mergedModule(kits, {
		Name = 'WhimAura',
		Category = 'Aim',
		Tooltip = 'Casts spells at nearby enemies and reads nearby tomes'
	})

run(function()
	local AutoWhim
	local Targets
	local Range
	local FireRate
	local SwitchDelay
	local nextFire = 0

	local function getSpellSource()
		local util = bedwars.MageKitUtil
		local element = bedwars.BalanceFile.MAGE_ELEMENT_CYCLE[(lplr:GetAttribute('MageElementIndex') or 0) + 1]
		if not element or table.find(util.getUnlockedMageElements(lplr), element) == nil then
			element = 'BASE'
		end

		local meta = util.MageElementMeta[element]
		return meta and meta.projectileSource or nil
	end

	local function castSpell()
		local item = getItem('mage_spellbook')
		local source = item and getSpellSource() or nil
		local target = source and getFacingEntity({
			Part = 'RootPart',
			Range = Range.Value,
			Players = Targets.Players.Enabled,
			Priority = Targets.Priority and Targets.Priority.Value,
			NPCs = Targets.NPCs.Enabled,
			Wallcheck = Targets.Walls.Enabled,
			Limit = 10
		}) or nil
		if not target then return end

		local hotbar = store.hand.tool and getHotbar(store.hand.tool) or nil
		if hotbarSwitch(getHotbar(item.tool)) then
			task.wait(store.ping.total or 0)
			if fireProjectile(item, 'mage_spellbook', source.projectileType('mage_spellbook'), target) then
				nextFire = tick() + source.fireDelaySec + FireRate:GetRandomValue()
				task.wait(SwitchDelay.Value)
			end
			hotbarSwitch(hotbar)
		end
	end

	AutoWhim = Main:Part({
		Label = 'Auto cast',
		Name = 'AutoWhim',
		Function = function(callback)
			if callback then
				nextFire = 0

				repeat
					if entitylib.isAlive and store.equippedKit == 'mage' and store.hand.toolType == 'sword' and (tick() - bedwars.SwordController.lastSwing) < 0.2 and tick() >= nextFire then
						castSpell()
					end
					task.wait(0.1)
				until not AutoWhim.Enabled
			end
		end,
		Tooltip = 'Casts the magic book at your melee target'
	})
	Targets = AutoWhim:CreateTargets({
		Players = true,
		NPCs = false
	})
	Range = AutoWhim:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 60,
		Default = 22,
		Suffix = function(val)
			return val <= 1 and 'stud' or 'studs'
		end
	})
	FireRate = AutoWhim:CreateTwoSlider({
		Name = 'Fire Rate',
		Min = 0,
		Max = 1,
		DefaultMin = 0.05,
		DefaultMax = 0.12,
		Decimal = 100
	})
	SwitchDelay = AutoWhim:CreateSlider({
		Name = 'Switch Delay',
		Min = 0,
		Max = 1,
		Decimal = 100,
		Suffix = 'seconds',
		Default = 0.02
	})
end)

run(function()
	local v2 = httpService
	local v3 = playersService
	local v4 = replicatedStorage
	local v5 = runService
	local v6 = inputService
	local v7 = tweenService
	local v8 = collectionService
	local v9 = guiService
	local v10 = game:GetService('TeleportService')
	local obj = debug
	local currentCamera = gameCamera
	local localPlayer = lplr
	local entity = entitylib
	local getfontbounds = getfontsize
	local getvapeasset = getcustomasset
	local LEARN_TOME_DURATION = (bedwars.BalanceFile and bedwars.BalanceFile.LEARN_TOME_DURATION) or 2

		local v12 = nil
		local v13 = nil
		local v14 = nil
		local v15 = nil
		local tbl3 = {}

		local function fn5(arg)
			local attribute = arg:GetAttribute("TomeSecret")
			local flag = not attribute

			if not flag then
				flag = (tbl3[attribute] or 0) > tick()
			end

			if flag then
				return
			end
			tbl3[attribute] = tick() + 3
			local CallServer
			local ok = pcall(function()
				CallServer = bedwars.Handler:Get("LearnElementTome"):Fire("CallServer", { secret = attribute })
			end)
			if not ok or typeof(CallServer) ~= "table" or not CallServer.element then
				return
			end
			local element = CallServer.element

			pcall(function()
				bedwars.MageController:destroyTomeGuidingBeam()
				bedwars.MageController:playLearnTomeEffect(localPlayer, arg, element)
			end)

			task.delay(LEARN_TOME_DURATION or 2, function()
				pcall(function()
					bedwars.MageController:fadeOutTome(arg)

					if localPlayer.Character then
						bedwars.MageKitUtil.changeMageKitAppearance(localPlayer, localPlayer.Character, element)
					end
				end)
			end)

			if v15.Enabled then
				notif("AutoWhimElement", ("Learned the %* element"):format(CallServer.element), 5, "info")
			end
		end

		v12 = Main:Part({
		Label = 'Read tomes',
			Name = "AutoWhimElement",
			Function = function(arg)
				if arg then
					table.clear(tbl3)

					while true do
						if entity.isAlive and store.equippedKit == "mage" then
							local position = entity.character.RootPart.Position

							for _, v16 in v8:GetTagged("ElementTome") do
								local primaryPart = v16.Parent and (not v16:IsA("Model") and v16 or v16.PrimaryPart or v16:FindFirstChildWhichIsA("BasePart", true))

								if primaryPart and (primaryPart.Position - position).Magnitude <= v13.Value then
									fn5(v16)
								end
							end
						end

						task.wait(v14.Value)
						if v12.Enabled then
							continue
						end
						break
					end
				else
					table.clear(tbl3)
				end
			end,
			Tooltip = 'Reads nearby Tomes of the Elements to unlock spells',
		})

		v13 = v12:CreateSlider({
			Name = "Tome range",
			Min = 1,
			Max = 500,
			Default = 10,
			Suffix = function(arg)
				return arg <= 1 and "stud" or "studs"
			end,
			Tooltip = 'How close a tome must be to read it',
		})

		v14 = v12:CreateSlider({
			Name = "Tome delay",
			Min = 0.1,
			Max = 5,
			Decimal = 10,
			Default = 0.5,
			Suffix = "seconds",
			Tooltip = "How often it looks for a tome",
		})

		v15 = v12:CreateToggle({ Name = "Notify", Default = true, Tooltip = "Tells you which element you picked up" })
	end)

end)

-- ===== Kits/YaminiExtender.lua =====
run(function()
	local YaminiExtender
	local Multiplier
	
	local old
	
	YaminiExtender = vape.Categories.Kits:CreateModule({
		Name = 'YaminiExtender',
		Function = function(callback)
			if callback then
				old = bedwars.CatController.leap
				bedwars.CatController.leap = function(self, character, direction)
					local call = old(self, character, direction)
					local horizontal = direction and direction * Vector3.new(1, 0, 1) or Vector3.zero
					local root = character and character:FindFirstChild('HumanoidRootPart')
	
					if store.equippedKit == 'cat' and root and horizontal.Magnitude > 0 then
						root:ApplyImpulse(horizontal.Unit * root.AssemblyMass * (Multiplier.Value - 1) * 70)
					end
					return call
				end
			else
				bedwars.CatController.leap = old
			end
		end,
		Tooltip = 'Extends how far the ability launches you'
	})
	Multiplier = YaminiExtender:CreateSlider({
		Name = 'Multiplier',
		Min = 1,
		Max = 5,
		Default = 2,
		Decimal = 10,
		Suffix = 'x'
	})
end)

-- ===== Kits/YuziDasher.lua =====
run(function()
	local YuziDasher
	local ImpulseSlider
	local JumpHeightSlider
	local CurrentKeybind = Enum.KeyCode.Q

	local canDash = true

	local function PerformDash()
		if not canDash then return end
		if not entitylib.isAlive then return end

		local heldItem = store.hand.tool
		if not heldItem or not (heldItem.Name:find("dao") or heldItem.Name:find("yuzi") or heldItem.Name == "jade_hammer" or heldItem.Name == "void_axe") then return end

		local abilityId = (heldItem.Name == "jade_hammer" and "JADE_HAMMER_JUMP") or (heldItem.Name == "void_axe" and "VOID_AXE_JUMP") or nil

		local character = lplr.Character
		if not (character and character.PrimaryPart) then return end

		canDash = false

		task.spawn(function()
			local originalJumpHeight = character.Humanoid.JumpHeight

			pcall(function() character:SetAttribute('CanDash', 0) end)

			local lookVector = gameCamera.CFrame.LookVector
			local origin = character.PrimaryPart.Position

			pcall(function()
				local n = game:GetService("ReplicatedStorage"):FindFirstChild("rbxts_include")
				if n then n = n:FindFirstChild("node_modules") end
				if n then n = n:FindFirstChild("@rbxts") end
				if n then n = n:FindFirstChild("net") end
				if n then n = n:FindFirstChild("out") end
				if n then n = n:FindFirstChild("_NetManaged") end
				if n then n = n:FindFirstChild("SwordSwingMiss") end
				if n then n:FireServer({ weapon = heldItem, chargeRatio = 0 }) end
			end)

			task.wait(0.05)

			local useDash = abilityId == nil
			local canUse = useDash and bedwars.AbilityController:canUseAbility('dash') or (abilityId and bedwars.AbilityController:canUseAbility(abilityId))

			if canUse then
				if useDash then
					bedwars.AbilityController:useAbility('dash', nil, {
						direction = lookVector,
						origin = origin,
						weapon = heldItem.Name
					})
				else
					bedwars.AbilityController:useAbility(abilityId)
				end

				pcall(function()
					bedwars.GameAnimationUtil:playAnimation(lplr, bedwars.AnimationType.DAO_DASH)
				end)

				pcall(function()
					local hrp = character.HumanoidRootPart
					local mass = hrp.AssemblyMass or 5
					hrp:ApplyImpulse(lookVector.Unit * Vector3.new(1, 0, 1) * mass * ImpulseSlider.Value)
					character.Humanoid.JumpHeight = JumpHeightSlider.Value
					character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
				end)

				task.delay(0.5, function()
					if character and character.Humanoid then
						pcall(function()
							character.Humanoid.JumpHeight = originalJumpHeight
							if bedwars.JumpHeightController then
								bedwars.JumpHeightController:setJumpHeight(game:GetService("StarterPlayer").CharacterJumpHeight)
							end
						end)
					end
				end)
			end

			task.wait(0.3)
			canDash = true
		end)
	end

	YuziDasher = vape.Categories.Kits:CreateModule({
		Name = 'YuziDasher',
		Function = function(callback)
			if callback then
				YuziDasher:Clean(inputService.InputBegan:Connect(function(input, gameProcessed)
					if gameProcessed then return end
					if input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode == CurrentKeybind then
						PerformDash()
					end
				end))
			else
				canDash = true
			end
		end,
	})

	local keybindOptions = {
		"Q", "E", "R", "F", "G", "X", "Z", "V", "B",
		"LeftAlt", "LeftControl", "LeftShift", "RightAlt", "RightControl", "RightShift",
		"Space", "CapsLock", "Tab"
	}

	YuziDasher:CreateDropdown({
		Name = 'Keybind',
		List = keybindOptions,
		Default = "Q",
		Function = function(value)
			CurrentKeybind = Enum.KeyCode[value]
		end
	})

	ImpulseSlider = YuziDasher:CreateSlider({
		Name = 'Impulse Multiplier',
		Min = 10,
		Max = 500,
		Default = 100,
		Tooltip = 'Controls dash speed'
	})

	JumpHeightSlider = YuziDasher:CreateSlider({
		Name = 'Jump Height',
		Min = 0,
		Max = 50,
		Default = 10,
	})
end)

-- ===== Kits/ZephyrDisabler.lua =====
run(function()
	local Main = vape.Libraries.mergedModule(kits, {
		Name = 'ZephyrDisabler',
		Category = 'Ability',
		Tooltip = 'Raises your speed with the Zephyr kit and air jumps before TP Down'
	})

run(function()
	local Speed
	local Value
	local WallCheck
	local AlwaysJump
	local measuredSpeed = 0
	local lastPosition, engineSpeed, lastPush = nil, 0, 0
	local ZephyrSpeeds = {}

	local function zephyrSpeed(stacks)
		stacks = math.floor(tonumber(stacks) or 0)
		if stacks < 1 then return nil end
		local option = ZephyrSpeeds[math.min(stacks, 5)]
		return option and option.Value or nil
	end

	local function movementSpeed()
		if not entitylib.isAlive then return Value.Value end
		local equipped = store.equippedKit
		if equipped == nil or equipped == '' then
			equipped = lplr:GetAttribute('PlayingAsKit') or lplr:GetAttribute('PlayingAsKits')
		end
		local kit = string.lower(tostring(equipped or ''))
		if kit:find('wind_walker', 1, true) or kit:find('zephyr', 1, true) then
			local speed = zephyrSpeed(type(getWindStacks) == 'function' and getWindStacks() or 0)
			if speed then return speed end
		end
		return Value.Value
	end

	local rayCheck = RaycastParams.new()
	rayCheck.RespectCanCollide = true

	Speed = Main:Part({
		Label = 'Speed',
		Name = 'ZephyrDisabler',
		Category = 'Ability',
		Function = function(callback)
			frictionTable.ZephyrDisabler = callback or nil
			updateVelocity()
			local speedModule = vape.Modules.Speed
			local speedBlatant = speedModule and speedModule.Enabled and speedModule.Options.Mode and speedModule.Options.Mode.Value == 'Blatant'
			pcall(function()
				debug.setconstant(bedwars.WindWalkerController.updateSpeed, 7, (callback or speedBlatant) and 'constantSpeedMultiplier' or 'moveSpeedMultiplier')
			end)
			if not callback and not speedBlatant then
				pcall(function()
					bedwars.StatefulEntityKnockbackController.lastImpulseTime = time()
				end)
			end

			if callback then
				lastPosition, engineSpeed, lastPush, measuredSpeed = nil, 0, 0, 0
				Speed:Clean(runService.PreSimulation:Connect(function(dt)
					bedwars.StatefulEntityKnockbackController.lastImpulseTime = math.huge
					if not entitylib.isAlive then return end
					if (Fly and Fly.Enabled) or (LongJump and LongJump.Enabled) then return end

					local root = entitylib.character.RootPart
					local position = root.Position
					local travelled = lastPosition and (position - lastPosition) or Vector3.zero
					lastPosition = position
					local achieved = math.min(Vector3.new(travelled.X, 0, travelled.Z).Magnitude / math.max(dt, 1e-4), 500)
					engineSpeed = engineSpeed + (math.max(achieved - lastPush, 0) - engineSpeed) * 0.5
					lastPush = 0
					measuredSpeed = engineSpeed

					local target = movementSpeed()
					bedwars.SprintController:setSpeed(math.min(target, 20))

					local state = entitylib.character.Humanoid:GetState()
					if state == Enum.HumanoidStateType.Climbing then return end

					local moveDirection = AntiFallDirection or entitylib.character.Humanoid.MoveDirection
					local destination = moveDirection * math.max(target - engineSpeed, 0) * dt

					if WallCheck.Enabled and destination.Magnitude > 1e-4 then
						rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera}
						rayCheck.CollisionGroup = root.CollisionGroup
						local skin = (math.max(root.Size.X, root.Size.Z) / 2) + 0.4
						local half = root.Size.Y / 2

						for _ = 1, 3 do
							local step = destination.Magnitude
							if step <= 1e-4 then break end
							local direction = destination.Unit
							local back = root.Position - direction * skin
							local distance, normal
							for _, height in {0, half * 0.8, -half * 0.8} do
								local origin = back + Vector3.new(0, height, 0)
								local hit = workspace:Raycast(origin, direction * (step + skin * 6), rayCheck)
								if hit and (not distance or hit.Distance < distance) then
									distance, normal = hit.Distance, hit.Normal
								end
							end
							if not distance then break end
							local approach = -direction:Dot(normal)
							if approach <= 1e-4 then break end
							local into = -destination:Dot(normal)
							local allowed = (distance - skin) * approach - skin
							if into <= allowed then break end
							destination += normal * (into - allowed)
						end
					end

					root.CFrame += destination
					lastPush = destination.Magnitude / math.max(dt, 1e-4)
					measuredSpeed = engineSpeed + lastPush

					if AlwaysJump.Enabled and (state == Enum.HumanoidStateType.Running or state == Enum.HumanoidStateType.Landed) and moveDirection ~= Vector3.zero then
						entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
					end
				end))
			else
				bedwars.SprintController:setSpeed(bedwars.SprintController:isSprinting() and 20 or 14)
			end
		end,
		ExtraText = function()
			return math.floor(measuredSpeed) .. ' studs/s'
		end,
		Tooltip = 'Raises your speed with the Zephyr kit'
	})

	Value = Speed:CreateSlider({
		Name = 'Base Speed',
		Min = 1,
		Max = 80,
		Default = 23,
		Suffix = ' studs/s',
		Tooltip = 'Speed with zero wind stacks'
	})

	for index = 1, 5 do
		ZephyrSpeeds[index] = Speed:CreateSlider({
			Name = 'Zephyr ' .. index .. ' stack',
			Min = 1,
			Max = 80,
			Default = 21 + index,
			Suffix = ' studs/s'
		})
	end

	WallCheck = Speed:CreateToggle({
		Name = 'Wall Check',
		Default = true
	})
	AlwaysJump = Speed:CreateToggle({
		Name = 'Always Jump'
	})
	Speed:CreateButton({
		Name = 'Reset to Legit Speeds',
		Function = function()
			Value:SetValue(20)
			for index = 1, 5 do
				ZephyrSpeeds[index]:SetValue(21 + index)
			end
		end,
	})
end)

run(function()
	local AutoZephyr
	local Lead
	
	local TeleportLimits: {[string]: number} = {
	    Fly = 2,
	    InfiniteJump = 2
	}
	
	local function GetPullIn(): number?
	    if vape.FloatExempt then
	        return nil
	    end
	    local TPDown = vape.Modules.TPDown
	    if TPDown and TPDown.Enabled then
	        return TPDown.PullIn
	    end
	
	    local AirTime: number = tick() - (entitylib.character.AirTime or tick())
	    for Name: string, Limit: number in TeleportLimits do
	        local Module = vape.Modules[Name]
	        local Option = Module and Module.Options["TP Down"]
	        if Module and Module.Enabled and Option and Option.Enabled then
	            return Limit - AirTime
	        end
	    end
	    return nil
	end
	
	AutoZephyr = Main:Part({
		Label = 'Auto air jump',
	    Name = "AutoZephyr",
	    Category = "Ability",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Humanoid: Humanoid? = nil
	            local StateConnection: RBXScriptConnection? = nil
	            local Used: number = 0
	            local NextJump: number = 0
	
	            AutoZephyr:Clean(function()
	                if StateConnection then
	                    StateConnection:Disconnect()
	                    StateConnection = nil
	                end
	            end)
	
	            AutoZephyr:Clean(runService.PreSimulation:Connect(function()
	                if not entitylib.isAlive or vape.MovementOwner then
	                    return
	                end
	
	                if entitylib.character.Humanoid ~= Humanoid then
	                    if StateConnection then
	                        StateConnection:Disconnect()
	                    end
	                    Humanoid = entitylib.character.Humanoid
	                    Used = 0
	                    StateConnection = entitylib.character.Humanoid.StateChanged:Connect(function(Old: Enum.HumanoidStateType, New: Enum.HumanoidStateType)
	                        if New == Enum.HumanoidStateType.Landed then
	                            Used = 0
	                        elseif Old == Enum.HumanoidStateType.Freefall and New == Enum.HumanoidStateType.Jumping then
	                            Used += 1
	                        end
	                    end)
	                end
	
	                if entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air or NextJump > tick() then
	                    return
	                end
	
	                local Controller = bedwars.JumpHeightController
	                local Allowed: number = Controller and Controller.allowedAirJumps or 0
	                local PullIn: number? = GetPullIn()
	                if Used < Allowed and PullIn and PullIn <= Lead.Value then
	                    NextJump = tick() + 0.25
	                    pcall(function() bedwars.Client:Get("NotifyAirJump"):SendToServer() end)
	                    entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
	                    entitylib.character.AirTime = tick()
	                end
	            end))
	        end
	    end,
	    Tooltip = 'Uses an air jump before a TP Down pulls you down'
	})
	
	Lead = AutoZephyr:CreateSlider({
	    Name = "Lead",
	    Min = 0.05,
	    Max = 0.5,
	    Default = 0.15,
	    Decimal = 100,
	    Suffix = function(Val: number)
	        return Val == 1 and "second" or "seconds"
	    end,
	    Tooltip = 'How long before the pull down to jump'
	})
end)

run(function()
    local old, hook

    local function setEffect(visible)
        local zephyreffect = lplr.PlayerGui:FindFirstChild('WindWalkerEffect', true)
        if zephyreffect then
            zephyreffect.Visible = visible
        end
    end

    Main:Part({
		Label = 'Hide status indicator',
        Name = 'CleanKit',
        Function = function(callback)
            local controller = bedwars.WindWalkerController
            if callback then
                if not hook then
                    old = controller.spawnOrb
                    hook = function() end
                    controller.spawnOrb = hook
                end
                setEffect(false)
            else
                if hook and controller.spawnOrb == hook then
                    controller.spawnOrb = old
                end
                hook, old = nil, nil
                setEffect(true)
            end
        end,
        Tooltip = 'Removes the Zephyr status display',
        Category = 'Hud'
    })
end)

end)

-- ===== Minigames/BedPlates.lua =====
run(function()
    local BedPlates
    local Background
    local Color
    local LayerCounter
    local LayerColor
    local Reference = {}
    local Folder = Instance.new('Folder')
    Folder.Parent = vape.gui

    local function getBlockLayerHealth(block)
	local meta = bedwars.ItemMeta[block]
	return meta and meta.block and meta.block.health or 0
    end

    local function getLayerColor()
	return LayerColor and Color3.fromHSV(LayerColor.Hue, LayerColor.Sat, LayerColor.Value) or Color3.new(1, 1, 1)
    end

    local function scanSide(self, start, tab)
	for _, side in sides do
		local layers = {}
		for i = 1, 15 do
			local block = getPlacedBlock(start + (side * i))
			if not block or block == self or block.Name == 'bed' then
				break
			end
			if not block:GetAttribute('NoBreak') then
				layers[block.Name] = (layers[block.Name] or 0) + 1
			end
		end

		for block, amount in layers do
			tab[block] = math.max(tab[block] or 0, amount)
		end
	end
    end

    local function refreshAdornee(v)
	for _, obj in v.Frame:GetChildren() do
		if obj:IsA('ImageLabel') and obj.Name ~= 'Blur' then
			obj:Destroy()
		end
	end

	local start = v.Adornee.Position
	local layers = {}
	local alreadygot = {}
	scanSide(v.Adornee, start, layers)
	scanSide(v.Adornee, start + Vector3.new(0, 0, 3), layers)
	for block, amount in layers do
		table.insert(alreadygot, {block, amount})
	end
	table.sort(alreadygot, function(a, b)
		local healthA, healthB = getBlockLayerHealth(a[1]), getBlockLayerHealth(b[1])
		return healthA == healthB and a[1] < b[1] or healthA > healthB
	end)
	v.Enabled = #alreadygot > 0

	for _, blockData in alreadygot do
		local block, amount = blockData[1], blockData[2]
		local blockimage = Instance.new('ImageLabel')
		blockimage.Size = UDim2.fromOffset(32, 32)
		blockimage.BackgroundTransparency = 1
		blockimage.Image = bedwars.getIcon({ itemType = block }, true)
		blockimage.Parent = v.Frame
		if amount > 1 and (not LayerCounter or LayerCounter.Enabled) then
			local amounttext = Instance.new('TextLabel')
			amounttext.Name = 'Amount'
			amounttext.Size = UDim2.fromScale(1, 1)
			amounttext.BackgroundTransparency = 1
			amounttext.Text = tostring(amount)
			amounttext.TextColor3 = getLayerColor()
			amounttext.TextSize = 16
			amounttext.TextStrokeTransparency = 0.3
			amounttext.Font = Enum.Font.Arial
			amounttext.Parent = blockimage
		end
	end
    end

    local function refreshAll()
	for _, v in Reference do
		refreshAdornee(v)
	end
    end

    local function updateLayerTextColor()
	local textColor = getLayerColor()
	for _, v in Reference do
		for _, obj in v.Frame:GetDescendants() do
			if obj:IsA('TextLabel') and obj.Name == 'Amount' then
				obj.TextColor3 = textColor
			end
		end
	end
    end

    local function Added(v)
	local billboard = Instance.new('BillboardGui')
	billboard.Parent = Folder
	billboard.Name = 'bed'
	billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
	billboard.Size = UDim2.fromOffset(36, 36)
	billboard.AlwaysOnTop = true
	billboard.ClipsDescendants = false
	billboard.Adornee = v
	local blur = addBlur(billboard)
	blur.Visible = Background.Enabled
	local frame = Instance.new('Frame')
	frame.Size = UDim2.fromScale(1, 1)
	frame.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	frame.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
	frame.Parent = billboard
	local layout = Instance.new('UIListLayout')
	layout.FillDirection = Enum.FillDirection.Horizontal
	layout.Padding = UDim.new(0, 4)
	layout.VerticalAlignment = Enum.VerticalAlignment.Center
	layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
	layout:GetPropertyChangedSignal('AbsoluteContentSize'):Connect(function()
		billboard.Size = UDim2.fromOffset(math.max(layout.AbsoluteContentSize.X + 4, 36), 36)
	end)
	layout.Parent = frame
	local corner = Instance.new('UICorner')
	corner.CornerRadius = UDim.new(0, 4)
	corner.Parent = frame
	Reference[v] = billboard
	refreshAdornee(billboard)
    end

    local function refreshNear(data)
	data = data.blockRef.blockPosition * 3
	for i, v in Reference do
		if (data - i.Position).Magnitude <= 30 then
			refreshAdornee(v)
		end
	end
    end

    BedPlates = vape.Categories.Minigames:CreateModule({
	Name = 'BedPlates',
	Function = function(callback)
		if callback then
			for _, v in collectionService:GetTagged('bed') do
				task.spawn(Added, v)
			end
			BedPlates:Clean(vapeEvents.PlaceBlockEvent.Event:Connect(refreshNear))
			BedPlates:Clean(vapeEvents.BreakBlockEvent.Event:Connect(refreshNear))
			BedPlates:Clean(collectionService:GetInstanceAddedSignal('bed'):Connect(Added))
			BedPlates:Clean(collectionService:GetInstanceRemovedSignal('bed'):Connect(function(v)
				if Reference[v] then
					Reference[v]:Destroy()
					Reference[v]:ClearAllChildren()
					Reference[v] = nil
				end
			end))
		else
			table.clear(Reference)
			Folder:ClearAllChildren()
		end
	end,
	Tooltip = 'Shows which blocks surround each bed',
    })
    Background = BedPlates:CreateGroup({
	Name = 'Background',
	Function = function(callback)
		for _, v in Reference do
			v.Frame.BackgroundTransparency = 1 - (callback and Color.Opacity or 0)
			v.Blur.Visible = callback
		end
	end,
	Default = true,
    })
    Color = Background:CreateColorSlider({
	Name = 'Background Colour',
	DefaultValue = 0,
	DefaultOpacity = 0.5,
	Function = function(hue, sat, val, opacity)
		for _, v in Reference do
			v.Frame.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
			v.Frame.BackgroundTransparency = 1 - opacity
		end
	end,
	Darker = true,
    })
    LayerCounter = BedPlates:CreateGroup({
	Name = 'Layer Counter',
	Function = function(callback)
		refreshAll()
	end,
	Default = true,
    })
    LayerColor = LayerCounter:CreateColorSlider({
	Name = 'Counter Text Colour',
	DefaultSat = 0,
	DefaultValue = 1,
	Function = function()
		updateLayerTextColor()
	end,
	Visible = LayerCounter.Enabled,
    })
end)

-- ===== Minigames/Breaker.lua =====
run(function()
    local Breaker
    local Range
    local Angle
    local AutoTool
    local UpdateRate
    local Custom
    local Targets
    local Effect
    local CustomHealth = {}
    local Animation
    local SelfBreak
    local LimitItem
    local BreakerType
    local BreakChance
    local CombatOnly
    local LEGIT_RANGE = 18
    local rng = Random.new()
    local losFilter
    local customlist, parts = {}, {}

    
    
    
    
    
    local function makeMaid()
        local tasks = {}
        return {
            GiveTask = function(_, item)
                table.insert(tasks, item)
                return item
            end,
            DoCleaning = function()
                for _, item in tasks do
                    if typeof(item) == 'function' then
                        pcall(item)
                    elseif typeof(item) == 'RBXScriptConnection' then
                        item:Disconnect()
                    elseif typeof(item) == 'Instance' then
                        item:Destroy()
                    elseif type(item) == 'table' and item.DoCleaning then
                        item:DoCleaning()
                    end
                end
                table.clear(tasks)
            end
        }
    end

    local function customHealthbar(self, blockRef, health, maxHealth, changeHealth, block)
        
        self.healthbarMaid = self.healthbarMaid or makeMaid()
        self.healthbarProgressRef = self.healthbarProgressRef or bedwars.Roact.createRef()
        if not self.healthbarPart or not self.healthbarBlockRef or self.healthbarBlockRef.blockPosition ~= blockRef.blockPosition then
            self.healthbarMaid:DoCleaning()
            self.healthbarBlockRef = blockRef
            local create = bedwars.Roact.createElement
            local percent = math.clamp(health / maxHealth, 0, 1)
            local cleanCheck = true
            local part = Instance.new('Part')
            part.Size = Vector3.one
            part.CFrame = CFrame.new(bedwars.BlockController:getWorldPosition(blockRef.blockPosition))
            part.Transparency = 1
            part.Anchored = true
            part.CanCollide = false
            part.Parent = workspace
            self.healthbarPart = part
            bedwars.QueryUtil:setQueryIgnored(self.healthbarPart, true)

            local mounted = bedwars.Roact.mount(create('BillboardGui', {
                Size = UDim2.fromOffset(249, 102),
                StudsOffset = Vector3.new(0, 2.5, 0),
                Adornee = part,
                MaxDistance = 40,
                AlwaysOnTop = true
            }, {
                create('Frame', {
                    Size = UDim2.fromOffset(160, 50),
                    Position = UDim2.fromOffset(44, 32),
                    BackgroundColor3 = Color3.new(),
                    BackgroundTransparency = 0.5
                }, {
                    create('UICorner', {CornerRadius = UDim.new(0, 5)}),
                    create('ImageLabel', {
                        Size = UDim2.new(1, 89, 1, 52),
                        Position = UDim2.fromOffset(-48, -31),
                        BackgroundTransparency = 1,
                        Image = getcustomasset('ElevateV4/assets/new/blur.png'),
                        ScaleType = Enum.ScaleType.Slice,
                        SliceCenter = Rect.new(52, 31, 261, 502)
                    }),
                    create('TextLabel', {
                        Size = UDim2.fromOffset(145, 14),
                        Position = UDim2.fromOffset(13, 12),
                        BackgroundTransparency = 1,
                        Text = bedwars.ItemMeta[block.Name].displayName or block.Name,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        TextYAlignment = Enum.TextYAlignment.Top,
                        TextColor3 = Color3.new(),
                        TextScaled = true,
                        Font = Enum.Font.Arial
                    }),
                    create('TextLabel', {
                        Size = UDim2.fromOffset(145, 14),
                        Position = UDim2.fromOffset(12, 11),
                        BackgroundTransparency = 1,
                        Text = bedwars.ItemMeta[block.Name].displayName or block.Name,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        TextYAlignment = Enum.TextYAlignment.Top,
                        TextColor3 = color.Dark(uipallet.Text, 0.16),
                        TextScaled = true,
                        Font = Enum.Font.Arial
                    }),
                    create('Frame', {
                        Size = UDim2.fromOffset(138, 4),
                        Position = UDim2.fromOffset(12, 32),
                        BackgroundColor3 = uipallet.Main
                    }, {
                        create('UICorner', {CornerRadius = UDim.new(1, 0)}),
                        create('Frame', {
                            [bedwars.Roact.Ref] = self.healthbarProgressRef,
                            Size = UDim2.fromScale(percent, 1),
                            BackgroundColor3 = Color3.fromHSV(math.clamp(percent / 2.5, 0, 1), 0.89, 0.75)
                        }, {create('UICorner', {CornerRadius = UDim.new(1, 0)})})
                    })
                })
            }), part)

            self.healthbarMaid:GiveTask(function()
                cleanCheck = false
                self.healthbarBlockRef = nil
                bedwars.Roact.unmount(mounted)
                if self.healthbarPart then
                    self.healthbarPart:Destroy()
                end
                self.healthbarPart = nil
            end)

            bedwars.RuntimeLib.Promise.delay(5):andThen(function()
                if cleanCheck then
                    self.healthbarMaid:DoCleaning()
                end
            end)
        end

        local newpercent = math.clamp((health - changeHealth) / maxHealth, 0, 1)
        tweenService:Create(self.healthbarProgressRef:getValue(), TweenInfo.new(0.3), {
            Size = UDim2.fromScale(newpercent, 1), BackgroundColor3 = Color3.fromHSV(math.clamp(newpercent / 2.5, 0, 1), 0.89, 0.75)
        }):Play()
    end

    
    
    losFilter = RaycastParams.new()
    losFilter.FilterType = Enum.RaycastFilterType.Exclude
    losFilter.RespectCanCollide = false
    losFilter.IgnoreWater = true

    local function refreshFilter()
        losFilter.FilterDescendantsInstances = {lplr.Character, gameCamera}
    end

    local VISIBILITY_PROBES = {
        Vector3.zero,
        Vector3.new(1.35, 0, 0), Vector3.new(-1.35, 0, 0),
        Vector3.new(0, 1.35, 0), Vector3.new(0, -1.35, 0),
        Vector3.new(0, 0, 1.35), Vector3.new(0, 0, -1.35)
    }

    local function isVisible(worldPos)
        local eye = gameCamera.CFrame.Position
        for _, offset in VISIBILITY_PROBES do
            local probe = worldPos + offset
            local ray = probe - eye
            local hit = workspace:Raycast(eye, ray, losFilter)
            if not hit or (hit.Position - eye).Magnitude >= ray.Magnitude - 1.5 then
                return true
            end
        end
        return false
    end

    local function isLegit()
        return BreakerType.Value == 'Legit'
    end

    local function breakRange()
        return isLegit() and math.min(Range.Value, LEGIT_RANGE) or Range.Value
    end

    local function heldTool()
        local tool = store.hand and store.hand.tool
        local meta = tool and bedwars.ItemMeta[tool.Name]
        return meta and meta.breakBlock and tool or nil
    end

    local function heldOnly()
        return not AutoTool.Enabled and (LimitItem.Enabled or isLegit())
    end

    local function heldHits(block, pos)
        return breakmethods.Health(block, pos, true)
    end

    local function inCombat()
        local combat = vape.Libraries.combat
        return combat ~= nil and combat:IsInCombat() == true
    end

    local function cellsOf(block)
        local handler = bedwars.BlockController:getHandlerRegistry():getHandler(block.Name)
        return handler and handler:getContainedPositions(block) or {block.Position / 3}
    end

    local function breakable(v, localPosition, reach)
        return v.Parent ~= nil
            and (v.Position - localPosition).Magnitude < reach
            and bedwars.BlockController:isBlockBreakable({blockPosition = v.Position / 3}, lplr)
            and (SelfBreak.Enabled or v:GetAttribute('PlacedByUserId') ~= lplr.UserId)
            and (v:GetAttribute('BedShieldEndTime') or 0) <= workspace:GetServerTimeNow()
    end

    local function nearest(tab, localPosition, reach, limit)
        local found = {}
        for _, v in tab do
            if breakable(v, localPosition, reach) then
                table.insert(found, v)
            end
        end
        table.sort(found, function(a, b)
            return (a.Position - localPosition).Magnitude < (b.Position - localPosition).Magnitude
        end)
        for index = #found, limit + 1, -1 do
            found[index] = nil
        end
        return found
    end

    local lockedTarget, lockedBlock, lockedPos, lostAt = nil, nil, nil, nil

    local function unlock()
        lockedTarget, lockedBlock, lockedPos, lostAt = nil, nil, nil, nil
    end

    local function drawPath(target, path, endpos)
        if not path then return end
        local currentnode = target
        for _, part in parts do
            part.Position = currentnode or Vector3.zero
            if currentnode then
                part.BoxHandleAdornment.Color3 = currentnode == endpos and Color3.new(1, 0.2, 0.2) or currentnode == target and Color3.new(0.2, 0.2, 1) or Color3.new(0.2, 1, 0.2)
            end
            currentnode = path[currentnode]
        end
    end

    local function strike(v, direct)
        local legit = isLegit()
        local only = heldOnly()
        return bedwars.breakBlock(
            v,
            Effect.Enabled,
            Animation.Enabled,
            CustomHealth.Enabled and customHealthbar or nil,
            AutoTool.Enabled,
            only and heldHits or breakmethods.Health,
            legit and (ViewAngle and ViewAngle.Value or Angle.Value) or 360,
            legit and isVisible or nil,
            {Legit = legit, HeldOnly = only, Direct = direct, Range = breakRange()}
        )
    end

    local function swing(v, direct)
        local delay = 0.25
        if isLegit() then
            delay = 0.3 + rng:NextNumber(0, 0.05)
            local roll = BreakChance.Value < 100 and (not CombatOnly.Enabled or inCombat())
            if roll and rng:NextNumber(0, 100) >= BreakChance.Value then
                task.wait(delay)
                return true
            end
        end
        local target, path, endpos = strike(v, direct)
        if not target then return false end
        drawPath(target, path, endpos)
        task.wait(delay)
        return true
    end

    local function legitEntry(v, localPosition, reach)
        local best, bestScore, bestCost = nil, math.huge, math.huge
        local only = heldOnly()
        for _, cell in cellsOf(v) do
            local pos, cost, _, depth = bedwars.calculateBreakPath(v, cell * 3, only and heldHits or breakmethods.Health, Angle.Value, isVisible, {Legit = true, HeldOnly = only, Range = reach})
            if pos then
                local score = (pos - localPosition).Magnitude + (depth or 0) * 3
                if score < bestScore or (score == bestScore and cost < bestCost) then
                    best, bestScore, bestCost = pos, score, cost
                end
            end
        end
        if best then
            return getPlacedBlock(best), best
        end
    end

    local function legitStep(lists, localPosition)
        local reach = breakRange()
        if (LimitItem.Enabled or not AutoTool.Enabled) and not heldTool() then return false end

        if lockedBlock then
            local held = lockedBlock.Parent ~= nil
                and getPlacedBlock(lockedPos) == lockedBlock
                and (lockedPos - localPosition).Magnitude <= reach
                and breakable(lockedTarget, localPosition, reach + 9)
            local listed = false
            for _, tab in lists do
                if tab and table.find(tab, lockedTarget) then
                    listed = true
                    break
                end
            end
            if held and listed then
                if isVisible(lockedPos) then
                    lostAt = nil
                    return swing(lockedBlock, lockedPos)
                end
                lostAt = lostAt or tick()
                if tick() - lostAt < 1 then return true end
            end
            unlock()
        end

        for _, tab in lists do
            if not tab then continue end
            for _, v in nearest(tab, localPosition, reach + 9, 4) do
                local block, pos = legitEntry(v, localPosition, reach)
                if block then
                    lockedTarget, lockedBlock, lockedPos = v, block, pos
                    return swing(block, pos)
                end
            end
        end
        return false
    end

    local function blatantStep(tab, localPosition)
        if not tab then return false end
        if LimitItem.Enabled and not heldTool() then return false end
        local reach = breakRange()
        local only = heldOnly()
        local method = only and heldHits or breakmethods.Health
        local best, bestCost = nil, math.huge
        for _, v in nearest(tab, localPosition, reach, 6) do
            for _, cell in cellsOf(v) do
                local pos, cost = bedwars.calculateBreakPath(v, cell * 3, method, 360, nil, {Legit = false, HeldOnly = only, Range = reach})
                if pos and cost < bestCost then
                    best, bestCost = v, cost
                end
            end
        end
        return best ~= nil and swing(best)
    end

    Breaker = vape.Categories.Minigames:CreateModule({
        Name = 'Breaker',
        Function = function(callback)
            if callback then
                for _ = 1, 30 do
                    local part = Instance.new('Part')
                    part.Anchored = true
                    part.CanQuery = false
                    part.CanCollide = false
                    part.Transparency = 1
                    part.Parent = gameCamera
                    local highlight = Instance.new('BoxHandleAdornment')
                    highlight.Size = Vector3.one
                    highlight.AlwaysOnTop = true
                    highlight.ZIndex = 1
                    highlight.Transparency = 0.5
                    highlight.Adornee = part
                    highlight.Parent = part
                    table.insert(parts, part)
                end

                local beds = collection('bed', Breaker)
                local luckyblock = collection('LuckyBlock', Breaker)
                local ironores = collection('iron_ore_mesh_block', Breaker)
                local teslas = collection('tesla-trap', Breaker, function(tab, obj)
				task.delay(0.1, function()
					local player = playersService:GetPlayerByUserId(obj:GetAttribute('PlacedByUserId'))
					if player and player:GetAttribute('Team') ~= lplr:GetAttribute('Team') then
						table.insert(tab, obj)
					end
				end)
			end)
			local hives = collection('beehive', Breaker, function(tab, obj)
				task.delay(0.1, function()
					local player = playersService:GetPlayerByUserId(obj:GetAttribute('PlacedByUserId'))
					if player and player:GetAttribute('Team') ~= lplr:GetAttribute('Team') then
						table.insert(tab, obj)
					end
				end)
			end)

                customlist = collection('block', Breaker, function(tab, obj)
                    if table.find(Custom.ListEnabled, obj.Name) then
                        table.insert(tab, obj)
                    end
                end)

                repeat
                    task.wait(math.max(1 / UpdateRate.Value, (BreakSpeed and BreakSpeed.Value) or 0))
                    if not Breaker.Enabled then break end
                    if entitylib.isAlive then
                        local localPosition = entitylib.character.RootPart.Position

                        local lists = {Targets:Has('Bed') and beds, Targets:Has('Tesla') and teslas, Targets:Has('Hive') and hives, customlist, Targets:Has('Lucky Block') and luckyblock, Targets:Has('Iron Ore') and ironores}
                        local handled = false
                        if isLegit() then
                            refreshFilter()
                            handled = legitStep(lists, localPosition)
                        else
                            for index = 1, 6 do
                                if blatantStep(lists[index], localPosition) then
                                    handled = true
                                    break
                                end
                            end
                        end
                        if handled then continue end

                        for _, v in parts do
                            v.Position = Vector3.zero
                        end
                    end
                until not Breaker.Enabled
            else
                unlock()
                for _, v in parts do
                    v:ClearAllChildren()
                    v:Destroy()
                end
                table.clear(parts)
            end
        end,
        Tooltip = 'Breaks blocks around you',
        ExtraText = function()
            return BreakerType.Value
        end
    })
    BreakerType = Breaker:CreateDropdown({
        Name = 'Breaker Type',
        List = {'Blatant', 'Legit'},
        Default = 'Blatant',
        Tooltip = 'Blatant - the fastest way in, through walls\nLegit - only blocks you could reach yourself',
        Function = function(val)
            unlock()
            if val == 'Legit' and Range and Range.Value > LEGIT_RANGE then
                Range:SetValue(LEGIT_RANGE)
            end
        end
    })
    BreakChance = Breaker:CreateSlider({
        Name = 'Break Chance',
        Min = 1,
        Max = 100,
        Default = 100,
        Suffix = '%',
        Darker = true,
        Visible = function()
            return BreakerType.Value == 'Legit'
        end,
        Tooltip = 'Chance that each mining hit is sent'
    })
    CombatOnly = Breaker:CreateToggle({
        Name = 'Only while in combat',
        Darker = true,
        Visible = function()
            return BreakerType.Value == 'Legit'
        end,
        Tooltip = 'Only applies Break Chance during fights'
    })
    Angle = Breaker:CreateSlider({
        Name = 'Max angle',
        Min = 1,
        Max = 360,
        Default = 120,
        Darker = true,
        Visible = function()
            return BreakerType.Value == 'Legit'
        end,
        Tooltip = 'How far from your view a block can be'
    })
    Range = Breaker:CreateSlider({
        Name = 'Break range',
        Min = 1,
        Max = 30,
        Default = 30,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end,
        Function = function(val)
            if val > LEGIT_RANGE and BreakerType.Value == 'Legit' then
                Range:SetValue(LEGIT_RANGE)
            end
        end,
        Tooltip = 'How far away a block can be mined'
    })
    Breaker:CreateButton({
        Name = 'Reset to legit range',
        Tooltip = 'Sets the range back to the game\'s default',
        Function = function()
            Range:SetValue(LEGIT_RANGE)
        end
    })
    UpdateRate = Breaker:CreateSlider({
        Name = 'Update rate',
        Min = 1,
        Max = 120,
        Default = 60,
        Suffix = 'hz'
    })
    Custom = Breaker:CreateTextList({
        Name = 'Custom',
        Function = function()
            if not customlist then return end
            table.clear(customlist)
            for _, obj in store.blocks do
                if table.find(Custom.ListEnabled, obj.Name) then
                    table.insert(customlist, obj)
                end
            end
        end
    })
    Targets = Breaker:CreateMultiDropdown({
        Name = 'Break',
        List = {'Bed', 'Tesla', 'Hive', 'Lucky Block', 'Iron Ore'},
        Default = {'Bed', 'Tesla', 'Hive', 'Lucky Block', 'Iron Ore'},
        Tooltip = 'What it breaks'
    })
    Effect = Breaker:CreateGroup({
        Name = 'Show Healthbar & Effects',
        Function = function(callback)
            if CustomHealth and CustomHealth.Object then
            end
        end,
        Default = true
    })
    CustomHealth = Effect:CreateToggle({
        Name = 'Custom Healthbar',
        Default = true,
        Darker = true
    })
    Animation = Breaker:CreateToggle({Name = 'Animation'})
    SelfBreak = Breaker:CreateToggle({Name = 'Self Break'})
    AutoTool = Breaker:CreateToggle({
        Name = 'Auto Tool',
        Tooltip = 'Uses the best tool you own for each block'
    })

    ClosestBreak = Breaker:CreateToggle({
        Name = 'Closest break',
        Default = false,
        Tooltip = 'Always pick the block nearest your crosshair (through players)'
    })
    SmartBreak = Breaker:CreateToggle({
        Name = 'Smart Break',
        Default = true,
        Tooltip = 'Prioritize low health blocks and visible beds'
    })
    ViewAngle = Breaker:CreateSlider({
        Name = 'View angle',
        Min = 5,
        Max = 180,
        Default = 60,
        Suffix = 'degrees',
        Darker = true,
        Tooltip = 'How far off crosshair a block can sit in legit mode'
    })
    BreakSpeed = Breaker:CreateSlider({
        Name = 'Break speed',
        Min = 0,
        Max = 0.3,
        Default = 0.15,
        Decimal = 100,
        Tooltip = 'Wait between hits (lower = faster)'
    })
    PlayerCheck = Breaker:CreateToggle({
        Name = 'Player check',
        Default = false,
        Tooltip = 'Skip blocks when a player is near them'
    })
    -- extra block types Motion had
    if Targets and Targets.List then
        pcall(function()
            for _, extra in {'Snow', 'Pinata', 'Crops'} do
                if not table.find(Targets.List, extra) then
                    table.insert(Targets.List, extra)
                end
            end
        end)
    end

    LimitItem = Breaker:CreateToggle({
        Name = 'Limit to items',
        Tooltip = 'Only works while holding the item it uses'
    })

end)


-- ===== AERO SKID PACK (working) =====

-- aero WhiteHits (fixed: scans existing highlights and watches respawns)
run(function()
	local WhiteHits
	WhiteHits = vape.Categories.Legit:CreateModule({
		Name = 'WhiteHits',
		Function = function(callback)
			if callback then
				local function killHighlight(obj)
					if obj and obj.Name == '_DamageHighlight_' then
						pcall(function()
							if obj:IsA('Highlight') then obj.Enabled = false end
							obj:Destroy()
						end)
					end
				end
				local function sweep(root)
					if not root then return end
					killHighlight(root)
					for _, obj in root:GetDescendants() do
						killHighlight(obj)
					end
				end
				local function watchPlayer(plr)
					if not plr then return end
					WhiteHits:Clean(plr.CharacterAdded:Connect(function(character)
						task.defer(sweep, character)
					end))
					sweep(plr.Character)
				end
				WhiteHits:Clean(workspace.DescendantAdded:Connect(killHighlight))
				WhiteHits:Clean(playersService.PlayerAdded:Connect(watchPlayer))
				for _, plr in playersService:GetPlayers() do watchPlayer(plr) end
				-- Catch any already-existing highlight, including ones nested in folders.
				sweep(workspace)
			end
		end,
		Tooltip = 'Removes the red damage highlight from players'
	})
end)

--[[
	Kits Modules
]]


-- aero ShadowRemover
run(function()
	local ShadowRemover
	local connections = {}
	local originalShadows = setmetatable({}, {__mode = 'k'})
	local processedShadows = setmetatable({}, {__mode = 'k'})
	
	local function removeShadow(obj)
		if obj:IsA("BasePart") and not processedShadows[obj] then
			if not originalShadows[obj] then
				originalShadows[obj] = obj.CastShadow
			end
			obj.CastShadow = false
			processedShadows[obj] = true
		end
	end
	
	ShadowRemover = vape.Categories.World:CreateModule({
		Name = 'ShadowRemover',
		Function = function(callback)
			if callback then
				scanDescendants(workspace, removeShadow, ShadowRemover)
				
				local conn = workspace.DescendantAdded:Connect(function(obj)
					if ShadowRemover.Enabled then
						removeShadow(obj)
					end
				end)
				table.insert(connections, conn)
			else
				for obj, shadow in pairs(originalShadows) do
					if obj and obj.Parent then
						pcall(function()
							obj.CastShadow = shadow
						end)
					end
				end
				
				for _, conn in connections do
					conn:Disconnect()
				end
				table.clear(connections)
				table.clear(originalShadows)
				table.clear(processedShadows)
			end
		end,
	})
end)


-- aero FPSBoost
run(function()
	local FPSBoost
	local Kill
	local Visualizer
	local effects, util = {}, {}
	local originalAddGameNametag
	local nametagHooked = false
	
	FPSBoost = vape.Categories.World:CreateModule({
		Name = 'FPSBoost',
		Function = function(callback)
			if callback then
				if Kill.Enabled then
					for i, v in bedwars.KillEffectController.killEffects do
						if not i:find('Custom') then
							effects[i] = v
							bedwars.KillEffectController.killEffects[i] = {
								new = function() 
									return {
										onKill = function() end, 
										isPlayDefaultKillEffect = function() 
											return true 
										end
									} 
								end
							}
						end
					end
				end

			if Visualizer.Enabled then
				local keepKeys = {'beam', 'Beam', 'projectile', 'Projectile', 'draw', 'Draw', 'line', 'Line', 'ray', 'Ray', 'arc', 'Arc'}
				for i, v in bedwars.VisualizerUtils do
					local keep = false
					for _, k in keepKeys do
						if tostring(i):lower():find(k:lower()) then
							keep = true
							break
						end
					end
					if not keep then
						util[i] = v
						bedwars.VisualizerUtils[i] = function() end
					end
				end
			end

			else
				for i, v in effects do 
					bedwars.KillEffectController.killEffects[i] = v 
				end
				
				for i, v in util do 
					bedwars.VisualizerUtils[i] = v 
				end
				
				if nametagHooked and originalAddGameNametag then
					bedwars.NametagController.addGameNametag = originalAddGameNametag
					nametagHooked = false
				end
				
				table.clear(effects)
				table.clear(util)
			end
		end,
		Tooltip = 'improves fps - well tries'
	})
	
	Kill = FPSBoost:CreateToggle({
		Name = 'Kill Effects',
		Function = function()
			if FPSBoost.Enabled then
				FPSBoost:Toggle()
				FPSBoost:Toggle()
			end
		end,
		Default = true
	})
	
	Visualizer = FPSBoost:CreateToggle({
		Name = 'Visualizer',
		Function = function()
			if FPSBoost.Enabled then
				FPSBoost:Toggle()
				FPSBoost:Toggle()
			end
		end,
		Default = true
	})
end)


