			for _, obj in workspace:GetDescendants() do
				if obj:IsA('Model') and obj.Name == 'Drill' then drills[obj] = true end
			end
			Session:Clean(workspace.DescendantAdded:Connect(function(obj)
				if obj:IsA('Model') and obj.Name == 'Drill' then drills[obj] = true end
			end))
